local P = LoreForeverPacks.Begin("LoreForever_Lang_ukUA")
P.entries["quest:58"] = {n="Нічна Варта",s="Це останнє доручення Командира Алтеї Ебонлок посилає шукачів пригод з Альянсу до склепів у східній частині Цвинтаря Воронячого Пагорба. Нічна Варта ледве встигає захищати Даркшир, тож чужинці мусять увійти до гробниць і винищити розносників чуми, що там кишать. Це вершина прямої військової кампанії міської варти, спрямованої на те, щоб стримати навалу нежиті.",h="Це останнє доручення Командира Алтеї Ебонлок посилає шукачів пригод з Альянсу до склепів у східній частині...",kw={"нічна варта","алтея ебонлок","мавзолей","розносники чуми","цвинтар воронячого пагорба","гулі"},ang={["class:Paladin"]="Заражені чумою склепи Воронячого Пагорба — нечестиве глузування зі священних похоронних обрядів, тож очищення його гробниць — важливий обов'язок слуг Святого Світла.",["class:Priest"]="Мерзенна зараза, яку розносять гулі зі східного мавзолею, кидає виклик святості Світла й вимагає очищення і духовного, і тілесного.",["faction:Alliance"]="Королівська Корона в Стормвінді не чує благань Сутінколісся, тож захисники Альянсу мусять самі стати до бою, щоб уберегти вірних підданих від навали нежиті."},sec={{t="Відчайдушне прикордоння",b="Даркшир стоїть майже цілком самотою: армія Стормвінда його покинула, і він покладається лише на власне ополчення — Нічну Варту. Командир Алтея Ебонлок вичерпала свої мізерні сили, охороняючи перехрестя, міський периметр і шляхи постачання. Неспокійні мерці множаться по всьому Сутінколіссю, тож командирці не лишається нічого іншого, як наймати мандрівних звитяжців і нести бій просто в темні закутки Воронячого Пагорба."},{t="Очищення мавзолею",b="Східний мавзолей Цвинтаря Воронячого Пагорба — одне з найнебезпечніших скупчень нежиті в краї. На відміну від відкритих курганів, цей кам'яний склеп кишить розносниками чуми — гулями, що несуть скверну, здатну вразити живих. Двадцять знищених потвор дарують утомленій Нічній Варті дорогоцінний перепочинок і не дозволяють нежиті вдарити по Даркширу злагодженим наступом із заходу."}},faq={{q="Чому Нічна Варта посилає шукачів пригод, а не своїх людей?",a="Сили Нічної Варти розпорошені по всьому Сутінколіссю. Стормвінд не дає жодних офіційних військ, тож Командирові Алтеї Ебонлок ледве вистачає вартових, щоб тримати околиці Даркширу й стежити за дорогами, — для зачистки глибоких укріплених склепів на кшталт Воронячого Пагорба вільних ополченців немає.",al={"чому допомагати даркширу","чому нічній варті потрібна допомога","нічної варти мало"}},{q="Де розташований східний мавзолей?",a="Він у східній частині Цвинтаря Воронячого Пагорба на північному заході Сутінколісся. Вхід веде під землю, до кам'яних склепів, де збираються розносники чуми.",al={"де розносники чуми","де східний мавзолей","де мавзолей"}},{q="Чим небезпечні розносники чуми?",a="Розносники чуми — ненажерливі гулі, що несуть заразний тлін. Якщо їх не стримувати, їхня мерзенна скверна може вийти за межі цвинтаря й заразити вцілілих мешканців Даркширу.",al={"чому вбивати розносників чуми","хто такі розносники чуми"}},{q="Хто така Командир Алтея Ебонлок?",a="Алтея Ебонлок — командирка й провідниця Нічної Варти, а також родичка мера Даркширу, Лорда Елло Ебонлока. Вона організовує оборону Сутінколісся з Даркширу.",al={"хто така алтея","командир ебонлок","хто очолює нічну варту"}},{q="Чи кладе цей ланцюжок край загрозі нежиті в Сутінколіссі?",a="Ні. Проріджування мавзолею послаблює безпосередній тиск на Даркшир, але Воронячий Пагорб і далі кишить нежиттю, а темніші сили по всьому Сутінколіссю й далі збурюють мертвих.",al={"чи врятовано воронячий пагорб","чи даркшир тепер безпечний"}},{q="Яке місце це посідає в ланцюжку «Нічна Варта»?",a="Це третій і останній розділ бойової серії «Нічна Варта» від Командира Ебонлок: від відкритих доріг до околиць цвинтаря, а зрештою — глибоко в мавзолей.",al={"який це ланцюжок","чи це останнє завдання нічної варти"}}},fp="15,358,20.458.0,21.438.0,68.281.0,39.175.0,42.187.0,34.190.0,61.180.0,49.193.0"}
P.entries["quest:5881"] = {n="Виклик резервів",s="«Виклик резервів» — завдання гінця Орди, яке доручають шукачам пригод, що відпочивають у Притулку Сонячної Скелі. Маґґран Ертбайндер посилає вас на південь, на край Пусток, із наказом змінити виснаженого вартового, що стереже Великий Підйомник.",h="«Виклик резервів» — завдання гінця Орди, яке доручають шукачам пригод, що відпочивають у Притулку Сонячної...",kw={"виклик резервів","великий підйомник","ґріш лонґраннер","маґґран ертбайндер","притулок сонячної скелі","вартовий"},ang={["faction:Horde"]="Це доручення показує, як командири Орди розпоряджаються силами на кордонах Калімдору: вони міняють вартових, щоб підтримувати бойовий дух і надійність застав.",["race:Tauren"]="Допомагаючи міняти вартових біля Великого Підйомника, ви підтримуєте життєво важливий прохід, що з'єднує південь Калімдору з широкими землями Тандер Блафа."},sec={{t="Довгоочікувана зміна",b="Навіть у часи відносного добробуту після Третьої війни утримувати гарнізони по всьому центральному Калімдору — важке випробування для сил Орди. У Притулку Сонячної Скелі в Горах Кам'яного Кігтя за постачанням і добробутом вояків наглядає Маґґран Ертбайндер. Розуміючи, що навіть загартовані бійці виснажуються від нескінченної варти, Маґґран відсилає на південь, до Великого Підйомника, наказ про переведення: там далеко від дому стоїть на посту молодий вартовий Ґріш Лонґраннер."},{t="Варта біля Підйомника",b="Великий Підйомник — єдина інженерна артерія, що з'єднує високі плато південних Пусток із вивітреними каньйонами Тисячі Голок унизу. Лист, переданий Ґрішеві, звільняє його від самотньої й одноманітної варти біля механізмів підйомника: нарешті він зможе повернутися до родини, а на зміну стануть свіжі резерви."}},faq={{q="Хто дає це завдання?",a="Завдання дає Маґґран Ертбайндер у Притулку Сонячної Скелі, високо в Горах Кам'яного Кігтя.",al={"хто дає завдання","де взяти виклик резервів","де маґґран"}},{q="Куди доставити лист Маґґрана?",a="Треба віднести Резервний Лист Маґрана на південь через Пустки аж до Великого Підйомника — величезної дерев'яної споруди-підйомника на кордоні, звідки видно Тисячу Голок.",al={"де ґріш лонґраннер","де ґріш","де великий підйомник"}},{q="Чому Ґрішеві Лонґраннеру потрібна заміна?",a="Ґріш довго ніс службу сам, стережучи механізми підйомника. Він давно подав офіційне прохання, щоб його змінили й він міг поїхати додому провідати родину.",al={"історія ґріша","чому ґріш іде","варта на великому підйомнику"}},{q="Чи треба в цьому завданні битися?",a="Битися не треба. Це суто доручення гінця, що має скерувати мандрівників на південь, до Тисячі Голок.",al={"чи треба битися","мирне завдання","завдання гінця"}},{q="Яка фракція дає репутацію за це завдання?",a="Доставка листа Ґрішеві дає репутацію з Тандер Блафом — адже на цьому шляху присутні й порядкують таурени.",al={"репутація за нагороду","яку репутацію дає","репутація тандер блафа"}},{q="Куди веде це завдання далі?",a="Доставка приводить вас просто на вершину Великого Підйомника, звідки можна спуститися підйомниками в каньйони Тисячі Голок і досліджувати нові застави Орди.",al={"наступне завдання","куди йти далі","завдання тисячі голок"}}},fp="23,234,21.467.0,17.366.0,22.102.0,36.185.0,38.180.0,44.111.0,52.134.0,32.174.0"}
P.entries["quest:59"] = {n="Полотняна і шкіряна броня",s="«Полотняна і шкіряна броня» — доручення Вартового Томаса біля східного мосту в Лісі Елвінн. Вражений службою шукача пригод, Томас видає офіційний військовий талон на обладунок, який можна обміняти в місцевої майстрині Сари Тімберлейн. Завдання веде новобранців далі на схід, до Лісозаготівельного Табору Східної Долини, по належне спорядження для захисту королівства.",h="«Полотняна і шкіряна броня» — доручення Вартового Томаса біля східного мосту в Лісі Елвінн.",kw={"броня","талон на обладунок","вартовий томас","сара тімберлейн","східна долина","кравецтво"},ang={["faction:Alliance"]="Спорядження захисників через місцеві замовлення показує, як сільські громади Елвінну тримають Альянс на ходу, попри політичний параліч у столиці.",["profession:Tailoring"]="Армійське замовлення Сари Тімберлейн доводить, що кравецтво — важливе й офіційно підтримуване військове ремесло в королівстві.",["race:Human"]="Служба Вартовому Томасу й торгівля з Сарою Тімберлейн відображають спільні громадські зв'язки, що тримають укупі невеликі садиби Лісу Елвінн."},sec={{t="Знак від вартового",b="Вартовий Томас несе варту на східній переправі через річку в Елвінні, тримаючи кордон проти ворожих мурлоків і мандрівних гнолів. Цінуючи зусилля здібних мандрівників, що допомагають його самотньому посту, він дає їм офіційний Талон на Обладунок Стормвінда замість віддавати спорядження зі своїх убогих польових запасів. Цей талон — військовий реквізиційний документ, який офіційно визнає службу власника короні."},{t="Ткаля Східної Долини",b="За мостом на схід лежить Лісозаготівельний Табір Східної Долини — головна лісозаготівля Елвінну. Саме звідти працює Сара Тімберлейн, яка має офіційне замовлення від армії Стормвінда на виготовлення спорядження з тканини та шкіри. Централізовані арсенали королівства виснажені й розтягнуті до краю, тож такі місцеві майстри, як Сара, незамінні, коли треба спорядити війська й допоміжних розвідників на прикордонні."}},faq={{q="Що таке Талон на Обладунок Стормвінда?",a="Це офіційна військова розписка, яку видають офіцери на кшталт Вартового Томаса. Замість тримати громіздкі комплекти обладунків на віддалених сторожових постах, вартові мають талони, за якими надійні новобранці можуть отримати обладунки, припасовані цивільними майстрами на замовлення війська.",al={"талон на обладунок","стормвіндський талон","що таке талон"}},{q="Хто така Сара Тімберлейн?",a="Сара Тімберлейн — кравчиня й майстриня з Лісозаготівельного Табору Східної Долини. Вона має угоду з військом Стормвінда на виготовлення тканинного й шкіряного спорядження для людей королівства й дозволених допоміжних бійців.",al={"сара тімберлейн","кравчиня східної долини","хто робить обладунок"}},{q="Де розташований Лісозаготівельний Табір Східної Долини?",a="Лісозаготівельний Табір Східної Долини — на крайньому сході Лісу Елвінн. Від посту Вартового Томаса біля мосту через річку йдіть дорогою на схід у лісисту долину, де лісоруби заготовляють деревину для королівства.",al={"де східна долина","як дістатися тімберлейн","де лісозаготівельний табір"}},{q="Чому Вартовий Томас посилає шукачів пригод до Східної Долини?",a="Томас не тримає на своєму пості біля річки запасу готового спорядження. Натомість він винагороджує сміливі вчинки, посилаючи новобранців до Сари Тімберлейн, — так мандрівники потрапляють до Східної Долини й водночас отримують належний захист, щоб боронити Елвінн.",al={"чому вартовий томас посилає","навіщо томас","чому східна долина"}},{q="Чому військо покладається на місцевих кравців?",a="Король Варіан Рінн зник, а військо Стормвінда розпорошене через Дефіас і диких звірів, тож місцеві оборонні пости значною мірою залежать від найнятих у краї робітників, що підтримують постачання.",al={"проблеми постачання стормвінда","чому місцеві ремісники","логістика війська"}},{q="Від кого захищає край Вартовий Томас?",a="Вартовий Томас наглядає за східним кордоном Лісу Елвінн, стережучи міст від набігів річкових мурлоків, хижих звірів і небезпек дикої глушини на межі з Горами Редріджу.",al={"вороги вартового томаса","загрози біля мосту","загрози східного елвінна"}}},fp="23,360,15.429.0,22.402.0,33.259.0,23.223.0,35.202.0,51.242.0,54.211.0,38.202.0"}
P.entries["quest:590"] = {n="Угода з пройдисвітом",s="Угода з пройдисвітом — сутичка з Келвіном Монтеґ'ю в Похоронному Подзвоні. Запропонувавши щойно пробудженим Відступникам роботу з обіцянкою багатства, хитрий розбійник виказує справжні наміри, коли від нього вимагають платню.",h="Угода з пройдисвітом — сутичка з Келвіном Монтеґ'ю в Похоронному Подзвоні.",kw={"угода з пройдисвітом","келвін монтеґ'ю","розбійник","платня","дуель","похоронний подзвін"},ang={["class:Rogue"]="Зустріч із Келвіном Монтеґ'ю дає молодим розбійникам миттєвий урок професійного ризику: нікому не вірте, пильнуйте гаманець і ніколи не дозволяйте іншому пройдисвіту піти з вашою часткою.",["race:Undead"]="Пробудження в Похоронному Подзвоні швидко доводить: смерть не позбавляє людство найдрібніших вад; шахраї з Відступників так само охоче дурять своїх, як і живі розбійники."},sec={{t="Безчесна обіцянка",b="Келвін Монтеґ'ю тиняється біля склепів Похоронного Подзвону, пропонуючи новопіднятим Відступникам на позір легку роботу. Запевняючи, що за доставку листа можна заробити добру монету, Монтеґ'ю посилає зелених шукачів пригод у небезпеку. Та щойно доручення виконано, Монтеґ'ю зручно забуває про обіцяну платню, вдаючи цілковите невідання щодо будь-якої домовленості чи боргу."},{t="Розплата",b="Коли від нього вимагають дотримати слова, Монтеґ'ю показує своє справжнє обличчя. Замість розлучатися зі своїм сріблом він береться за зброю, розраховуючи легко зарубати недосвідченого новачка. Лише добряче відлупцювавши розбійника, його можна змусити поступитися. Ґрунтовно побитий, він викашлює частку монет і відверто визнає, що збрехав про винагороду просто тому, що думав: йому це зійде з рук."}},faq={{q="Чому Келвін Монтеґ'ю нападає, коли в нього просять платню?",a="Келвін Монтеґ'ю — безсовісний розбійник, що й не думав ділитися грошима. Коли йому нагадують про порушену обіцянку, він намагається назавжди змусити помічника замовкнути, аби не платити, гадаючи, що щойно піднятий Відступник буде легкою здобиччю.",al={"чому келвін б'ється","келвін монтеґ'ю ворожий","чому пройдисвіт нападає"}},{q="Де відбувається ця сутичка?",a="Сутичка відбувається просто в Похоронному Подзвоні — зруйнованому селищі на південному заході Галявин Тірісфалю, де вперше прокидаються щойно підняті Відступники.",al={"де келвін монтеґ'ю","місце келвіна монтеґ'ю","де угода з пройдисвітом"}},{q="Чи справді Келвін Монтеґ'ю платить обіцяне?",a="Ні. Переможений у бою, Келвін здається й віддає трохи грошей, але визнає, що це набагато менше, ніж він обіцяв, бо брехав про всю суму від самого початку.",al={"нагорода келвіна","чи келвін платить","чи він збрехав про гроші"}},{q="Як відкривається це друге доручення?",a="Виконавши перше доручення Келвіна Монтеґ'ю з доставкою, поверніться й поговоріть із ним знову, щоб вимагати обіцяних грошей. Щойно ви викриєте його брехню, починається бій.",al={"як отримати частину 2","відкрити бій угоди з пройдисвітом","таємне завдання пройдисвіта"}},{q="Чи гине Келвін Монтеґ'ю, коли його переможено?",a="Ні. Монтеґ'ю здається, перш ніж отримає смертельний удар, рясно хвалить вашу бойову вправність і неохоче розв'язує гаманець, щоб урятувати власну шкуру.",al={"чи я вбив келвіна","чи келвін мертвий","келвін здається"}},{q="Якого уроку ця сутичка навчає нових Відступників?",a="Це ранній практичний урок суворої дійсності Відступників: честі серед нежиті обмаль, слова дешеві, а повагу здобувають лише бойовою силою.",al={"сенс угоди з пройдисвітом","переказ про угоду з пройдисвітом"}}},fp="14,216,22.368.0,16.390.1,55.244.1,41.145.0,51.177.1,33.183.1,39.153.1,54.183.0"}
P.entries["quest:5921"] = {n="Місячний Гай",s="«Місячний Гай» — вступний обряд посвяти для молодих друїдів нічних ельфів, що вчаться єднатися зі священними землями Калімдору. Під проводом Матренґіла Берволкера в Дарнасусі новачки вивчають закляття, яке магічно переносить їх через увесь світ до Місячного Гаю, де в Нічному Притулку на них чекає Дендрит Старблейз. Так починається їхня духовна подорож до опанування сили ведмежої форми.",h="«Місячний Гай» — вступний обряд посвяти для молодих друїдів нічних ельфів, що вчаться єднатися зі священними...",kw={"місячний гай","нічний притулок","хранитель ремулос","дендрит старблейз","телепортація","форма ведмедя","друїд"},ang={["class:Druid"]="Ця подорож — ваше пробудження до друїдської спадщини всього світу: відтепер у вас є вічна ниточка до спокійного серця Кола Кенарія.",["faction:Alliance"]="Дарнасус стоїть за Альянс, але Місячний Гай нагадує друїдам нічних ельфів про давніше, вище покликання, що стоїть понад земними фракціями.",["race:NightElf"]="Покинувши гілля Тельдрассилу заради прадавнього Місячного Гаю, молоді калдореї торкаються батьківщини предків, що вціліла ще з часів до Великого Розколу."},sec={{t="Священний прихисток",b="Місячний Гай стоїть осібно від решти Азероту — це прадавнє святилище, присвячене вченню Кенарія. Під пильною опікою Хранителя Ремулоса його спокійні гаї дарують мир і глибоке єднання з природою. Для молодого друїда навчитися переносити себе через землі до Місячного Гаю закляттям телепортації — важливий крок: відтепер серце друїдської мудрості завжди поруч, хоч би якими далекими були смертні відстані."},{t="Політика Кола",b="Місячний Гай відкритий для всіх, хто йде шляхом дикої природи, але й тут не без напруги. Між Архідруїдом Фандралом Стаґгелмом у Дарнасусі й Хранителем Ремулосом у Місячному Гаю росте розлам щодо опіки над природою та створення Тельдрассилу. Та попри ці філософські тріщини в Колі Кенарія, молодих послушників і далі беззастережно приймають у прихистку Нічного Притулку, щоб вони могли продовжувати священну науку."},{t="Шлях Ведмедя",b="У Нічному Притулку новачок постає перед Дендритом Старблейзом — старійшиною, що веде початківців шляхами Пазура. Перш ніж посвячуваний зможе прийняти мантію ведмедя, він має пройнятися його баченням: витривалістю, люттю й незламним захистом дикої природи. Старблейз приймає кожного нового учня з благоговійною шаною до Батька Кенарія й розпочинає випробування Великого Духа Ведмедя."}},faq={{q="Навіщо друїди вчаться телепортуватися до Місячного Гаю?",a="Телепорт до Місячного Гаю з'єднує друїда безпосередньо із серцем його ордену. Оскільки навчання, спілкування з духами й засідання вищої ради відбуваються в Нічному Притулку, миттєвий духовний провідник дає кожному змогу повернутися, щоб учитися й відновлювати духовні сили.",al={"навіщо телепорт у місячний гай","мета телепорту в місячний гай","чому йти до місячного гаю"}},{q="Хто такий Дендрит Старблейз?",a="Дендрит Старблейз — друїд-старійшина на горішньому поверсі великої оселі в Нічному Притулку. Він опікується новачками, що прибувають до Місячного Гаю, і починає їхні випробування з опанування звіриного світогляду — першим іде первісний дух ведмедя.",al={"роль дендрита старблейза","хто такий дендрит","дендрит старблейз"}},{q="Яка напруга існує між Фандралом Стаґгелмом і Хранителем Ремулосом?",a="Архідруїд Фандрал Стаґгелм очолив вирощування Тельдрассилу без благословення Драконячих Аспектів, обстоюючи для нічних ельфів агресивнішу, націоналістичну позицію. Хранитель Ремулос і прихильники традицій у Місячному Гаю лишаються вірними давнім нейтральним шляхам Кенарія, і це породжує ідейне тертя в Колі Кенарія.",al={"напруга стаґгелма і ремулоса","фандрал проти ремулоса","розкол кола"}},{q="Чи можуть друїди Орди теж навідуватися до Місячного Гаю?",a="Так. Місячний Гай — нейтральний притулок під захистом Хранителя Ремулоса й Кола Кенарія. І нічні ельфи, і таурени-друїди бажані в Нічному Притулку, щоб разом пізнавати дикі шляхи, відклавши фракційну ворожнечу під миром Кенарія.",al={"місячний гай орда","чи таурени можуть бути в місячному гаю","чи місячний гай нейтральний"}},{q="Що буде, коли дістатися Дендрита Старблейза?",a="Коли ви доповідаєте Дендритові Старблейзу, він веде вас до обрядового випробування Великого Духа Ведмедя. Ця духовна зустріч перевіряє вашу рішучість і розуміння, перш ніж вам дозволять опанувати первісну силу ведмедя.",al={"після завдання місячного гаю","наступний крок ведмежа подоба","наступне ведмеже завдання"}},{q="Де в Нічному Притулку знайти Дендрита?",a="Дендрит Старблейз — у головній оселі нічних ельфів біля центру Нічного Притулку; він стоїть на балконі другого поверху, звідки видно все селище.",al={"знайти дендрита старблейза","де дендрит старблейз","де дендрит"}}},fp="9,404,15.446.0,22.424.0,20.412.0,45.299.0,26.243.0,64.338.0,41.247.0,47.229.0,40.160.0"}
P.entries["quest:5922"] = {n="Місячний Гай",s="Це завдання знайомить юного друїда-таурена з Місячним Гаєм — священним прихистком друїдів Кенарія. Під проводом Турака Рунтотема з Тандер Блафа учень учиться долати простори світу наяву, щоб єднатися безпосередньо з прадавніми охоронцями природи.",h="Це завдання знайомить юного друїда-таурена з Місячним Гаєм — священним прихистком друїдів Кенарія.",kw={"місячний гай","друїд","турак рунтотем","нічний притулок","хранитель ремулос","дендрит старблейз","великий дух ведмедя"},ang={["class:Druid"]="Цей обряд посвяти долає відстань між традиційними племінними віруваннями й ширшим ученням Кола Кенарія, відчиняючи двері до прадавніх форм перевтілення.",["faction:Horde"]="Хоч у Калімдорі тліє напруга, друїди Орди знаходять у Місячному Гаю одне з небагатьох місць у світі, де можна мирно зустрітися зі своїми побратимами — нічними ельфами.",["race:Tauren"]="Для учнів-тауренів прибуття до Місячного Гаю — глибоке пробудження: доказ того, що їхні прадавні узи із Земною Матір'ю глибоко співзвучні з ученням Кенарія."},sec={{t="Священний прихисток понад фракціями",b="Місячний Гай стоїть осторонь бурхливої політики Калімдору. Ця прадавня долина під первісним гіллям, яку оберігає Хранитель Ремулос, син Кенарія, — нейтральний прихисток для всіх, хто йде шляхом природи. Нічний ельф чи таурен — кожен друїд, що входить до Нічного Притулку, стає там рівним серед рівних під вічним покровом Кола Кенарія."},{t="Стрибок через Калімдор",b="Щоб сприяти вашому духовному й бойовому зростанню, Турак Рунтотем навчає вас особливого заклинання переміщення, пов'язаного із самою долиною. Прикликаючи містичний зв'язок між друїдами й світом природи, ви долаєте сотні ліг за один удар серця. Цей прихисток стане для вас і залою науки, і незмінним притулком упродовж усієї подорожі."},{t="Пробудження ведмедя",b="Прибувши до Нічного Притулку, ви зустрічаєте Дендрита Старблейза — старшого друїда з нічних ельфів, що чекає на нових учнів. Під його проводом починається перше справжнє випробування вашого покликання: побачити світ очима ведмедя. Щоб прийняти шлях Пазура, треба довести свою силу, відвагу й рівновагу перед Великим Духом Ведмедя."}},faq={{q="Чому таурени можуть навідуватися до притулку нічних ельфів, як-от Місячного Гаю?",a="Місячний Гай — суверенна священна земля під опікою Кола Кенарія на чолі з Хранителем Ремулосом. У її межах відданість природі й Кенарію цілком переважує протистояння Орди й Альянсу, тож таурени й нічні ельфи-друїди мирно навчаються й живуть пліч-о-пліч.",al={"чому таурени в місячному гаю","чи орді можна в місячний гай","чи місячний гай нейтральний"}},{q="Хто такий Дендрит Старблейз?",a="Дендрит Старблейз — друїд-старійшина нічних ельфів у поселенні Нічний Притулок. Він наставляє новачків обох рас, що щойно прибули, і проводить їхні перші випробування, коли вони налаштовуються на давні звірині аспекти.",al={"дендрит старблейз","хто такий дендрит","видавець завдання нічний ельф"}},{q="Хто такий Хранитель Ремулос?",a="Хранитель Ремулос — могутній Хранитель Гаю й син напівбога Кенарія. Він — верховний охоронець Місячного Гаю: пильнує священні кургани, де сплять друїди, і стежить, щоб святість долини лишалася непорушною.",al={"хранитель ремулос","ремулос місячний гай","хто охороняє місячний гай"}},{q="Що буде, коли дістатися Місячного Гаю?",a="Розмова з Дендритом Старблейзом починає ваше випробування Великим Духом Ведмедя. Він посилає вас до оселі духа на північному заході Місячного Гаю, щоб пізнати силу тіла й силу серця — перший крок до таємниць ведмежої подоби.",al={"що робити далі","ведмежий ланцюжок завдань","після завдання місячного гаю"}},{q="Як «Телепорт: Місячний Гай» діє з погляду переказів?",a="Друїди сплітають природну лей-енергію й свій духовний зв'язок із Колом Кенарія, щоб миттєво подолати відстань між тим місцем, де стоять, і серцем Місячного Гаю. Це духовний якір, що дає змогу повертатися по науку й розраду, щойно їх покличуть.",al={"переказ про телепорт у місячний гай","закляття телепорту друїда"}},{q="Де знайти Турака Рунтотема?",a="Турак Рунтотем мешкає на Узвишші Старійшин у Тандер Блафі; він наставляє молодих тауренів, що почули поклик дикої природи, а тоді посилає їх до Місячного Гаю.",al={"де турак рунтотем","де турак"}}},fp="9,253,29.367.0,24.339.0,18.320.1,54.310.0,26.218.0,22.251.0,38.257.0,44.275.0,33.155.0"}
P.entries["quest:5923"] = {n="Почути поклик",s="«Почути поклик» — мить, коли учень-друїд нічних ельфів привертає увагу старшого проводу Кола Кенарія. Покликаний до Дарнасуса на зустріч із Матренґілом Берволкером, молодий посвячуваний ступає на священний шлях до опанування першого звіриного образу — ведмедя.",h="«Почути поклик» — мить, коли учень-друїд нічних ельфів привертає увагу старшого проводу Кола Кенарія.",kw={"почути поклик","матренґіл берволкер","ценаріонський анклав","фандрал стаґгелм","форма ведмедя","друїд","терідран"},ang={["class:Druid"]="Це завдання знаменує ваш офіційний перехід від новачка, що плете закляття коріння й гніву, до справжнього друїда, який змінює подобу й пізнає духів Калімдору.",["faction:Alliance"]="Те, що це завдання можна отримати в Терідрана в Стормвінді, показує, як міцнішає співпраця калдореїв Тельдрассилу з їхніми союзниками-людьми на сході.",["race:NightElf"]="Відгукнувшись на виклик, ви потрапляєте в серце Ценаріонського Анклаву Дарнасуса й ушановуєте тисячолітню традицію калдореїв під пильним оком кола Фандрала Стаґгелма."},sec={{t="Виклик з Анклаву",b="Друїди-новачки, що вдосконалюють своє ремесло на Тельдрассилі чи навчаються в далеких краях на кшталт Стормвінда, рано чи пізно отримують особистий виклик. Наставники — Кал у Доланаарі, Денатаріон у Дарнасусі чи Терідран за Великим Морем — передають, що Матренґіл Берволкер бажає сам наглядати за їхнім навчанням. Як безпосередній помічник Архідруїда Фандрала Стаґгелма, Матренґіл — один із найшанованіших і найобізнаніших наставників серед нічних ельфів, і його увага — певний знак, що учень готовий до справжніх випробувань."},{t="Шлях Ведмедя",b="Зустріч із Матренґілом на верхньому ярусі високої оселі Фандрала Стаґгелма в Ценаріонському Анклаві відчиняє двері до глибших таїнств. Щоб належно служити природі, друїд має навчитися втілювати її живих створінь, а не лише спостерігати за ними. Матренґіл вітає кандидатів звісткою, що їхньою першою великою справою буде прийняти силу, витривалість і дух ведмедя, — і ця подорож поведе їх далеко за межі Тельдрассилу, до священних земель предків."}},faq={{q="Хто посилає мене на це завдання?",a="Цей заклик ви можете отримати від кількох наставників друїдів, щойно наберетеся досить досвіду: від Кала в Доланаарі, Денатаріона в Дарнасусі чи Терідрана в кварталі Парк у Стормвінді.",al={"хто дає завдання","хто починає це","де взяти це завдання"}},{q="Хто такий Матренґіл Берволкер?",a="Матренґіл Берволкер — старший друїд нічних ельфів і безпосередній помічник Архідруїда Фандрала Стаґгелма. Він мешкає в Ценаріонському Анклаві в Дарнасусі й є провідним наставником новачків, що прагнуть опанувати звірині подоби.",al={"матренґіл","хто такий матренґіл","берволкер"}},{q="Де в Дарнасусі знайти Матренґіла Берволкера?",a="Він у Ценаріонському Анклаві в північно-західному кварталі Дарнасуса — чекає на другому поверсі великого живого дерева, що слугує святилищем Архідруїда Фандрала Стаґгелма.",al={"де матренґіл","де знайти матренґіла","де кенарійський анклав"}},{q="До якого навчання веде це завдання?",a="Доповідь Матренґілу починає священне випробування Ведмежої подоби. Він пошле вас через Калімдор до священного притулку Місячний Гай, щоб пізнати силу тіла й серця, потрібну для спілкування з Великим Духом Ведмедя.",al={"що далі","що я отримаю","наступне завдання"}},{q="Чому це завдання можна отримати в Стормвінді?",a="Посланці й друїди нічних ельфів, як-от Терідран, тримають святилище в Парку Стормвінда, щоб допомагати союзникам з Альянсу. Якщо молодий друїд мандрує за морем у Лісі Елвінн, Терідран може передати йому заклик повернутися додому, на Тельдрассил.",al={"завдання стормвінд","терідран","чи можна взяти в стормвінді"}},{q="Чому ведмежу подобу навчають першою?",a="Друїди вважають, що природі потрібні і захисники, і доглядачі. Ведмідь утілює первісну стійкість, фізичну силу й мужність заступати рівновагу від лиха — тож це основна подоба, щоб вижити у випробуваннях небезпечної глушини.",al={"чому ведмежа подоба","переказ про ведмежу подобу друїдів"}}},fp="16,278,26.560.0,20.479.0,27.197.0,29.235.0,52.204.0,38.222.0,38.246.0,52.241.0"}
P.entries["quest:5926"] = {n="Почути поклик",s="«Почути поклик» — завдання, що кличе друїда-новачка на Узвишшя Старійшин у Тандер Блафі для поглибленого особистого навчання. Звістку передають корчмарі й родичі в поселеннях Орди, і вона скеровує охочих до перевтілення до Турака Рунтотема. Ця зустріч відкриває священні випробування, потрібні, щоб опанувати форму й дух ведмедя.",h="«Почути поклик» — завдання, що кличе друїда-новачка на Узвишшя Старійшин у Тандер Блафі для поглибленого...",kw={"почути поклик","друїд","турак рунтотем","узвишшя старійшин","форма ведмедя","коло кенарія","великий дух ведмедя"},ang={["class:Druid"]="Це завдання — перший важливий крок на шляху до опанування звіриних форм, початок священної подорожі до духу й стійкості ведмедя.",["faction:Horde"]="Корчмарі на землях і орків, і тауренів дбають, щоб молоді друїди почули свій поклик, — так Орда зберігає життєво важливий зв'язок із дикою землею.",["race:Tauren"]="Для тауренів навчання в Турака на Узвишші Старійшин підтверджує їхнє глибоке, прадавнє возз'єднання з Колом Кенарія та дикими духами Калімдору."},sec={{t="Слово в корчмі",b="Звістки швидко розлітаються рівнинами Малгору й запиленими вулицями Оргріммара. Почуєте ви її від Корчмарки Гришки серед орків, від Корчмарки Пали в Тандер Блафі чи від Ґеннії Рунтотем у Селі Бладгуф — послання одне: Турак Рунтотем помітив ваші перші успіхи. Коло Кенарія не кличе послідовників легковажно, і це запрошення означає, що дні простого збирання трав і найпростіших чарів принесли вам право на глибше єднання з дикими духами природи."},{t="Коло на Узвишші Старійшин",b="Турак Рунтотем — помічник Верховного Друїда Гамуула Рунтотема: у великому наметі Кола Кенарія на Узвишші Старійшин він веде юних тауренів до обов'язку їхніх предків. Відкриваючи учням ширше розуміння спадщини Кенарія, Турак навчає, що звірі й рослини — і союзники, і доручені під їхню опіку створіння. Зустріч із ним — перший поріг обряду: крок за межі звичайного наставництва назустріч випробуванням тіла й серця, без яких не поєднатися безпосередньо з Великим Духом Ведмедя."}},faq={{q="Хто посилає мене до Турака Рунтотема?",a="Заклик можуть передати кілька різних зв'язкових: Ґеннія Рунтотем у Селі Бладгуф, Корчмарка Пала в Тандер Блафі чи Корчмарка Гришка в Оргріммарі. Кожна з них отримала звістку, що Турак хоче особисто вести ваше навчання.",al={"хто дає почути поклик","хто видає почути поклик","де почати почути поклик"}},{q="Де знайти Турака Рунтотема?",a="Турак мешкає на Узвишші Старійшин у Тандер Блафі. Він живе в помітному наметі Кола Кенарія, поруч з іншими наставниками-друїдами міста.",al={"де турак рунтотем","де турак","як знайти турака"}},{q="Чому цей заклик такий важливий для молодих друїдів?",a="Цей заклик починає ваші офіційні випробування з перевтілення. Турак Рунтотем скеровує вас на священну землю Місячного Гаю, щоб ви пізнали шлях ведмедя й здобули свою першу звірину подобу.",al={"навіщо мені турак","для чого це завдання","завдання друїда 10 рівня орда"}},{q="Хто такий Турак Рунтотем в ієрархії Кола Кенарія?",a="Турак — шанований друїд-таурен і довірений помічник Архідруїда Хамуула Рунтотема. Він славиться терпінням і мудрістю, коли навчає молодих новачків рівноваги природи.",al={"хто такий турак рунтотем","переказ про турака"}},{q="Чи можуть інші класи взяти це завдання?",a="Ні. Це завдання пропонують виключно друїдам, що досягли десятого сезону досвіду, — як обряд посвяти в перевтілення.",al={"чи почути поклик лише для друїдів","чи шаман може взяти це завдання"}},{q="Що буде після розмови з Тураком?",a="Турак вітає вас на службі Кенарію й посилає до священного друїдського притулку Місячний Гай — знайти Дендрита Старблейза й розпочати спілкування з Великим Духом Ведмедя.",al={"що після почути поклик","наступне завдання після турака"}}},fp="16,326,17.516.0,24.497.0,43.242.0,33.149.0,50.184.0,49.181.0,36.151.0,36.176.1"}
P.entries["quest:5931"] = {n="Назад до Дарнасуса",s="Це завдання знаменує повернення друїда-новачка з нічних ельфів зі священних галявин Місячного Гаю до Дарнасуса. Поєднавшись із Великим Духом Ведмедя, посвячуваний повертається до Матренґіла Берволкера в Ценаріонському Анклаві, щоб розпочати практичні випробування зміни подоби.",h="Це завдання знаменує повернення друїда-новачка з нічних ельфів зі священних галявин Місячного Гаю до...",kw={"назад до дарнасуса","великий дух ведмедя","матренґіл берволкер","дендрит старблейз","місячний гай","друїд","форма ведмедя"},ang={["class:Druid"]="Ця подорож — важливий обряд посвяти для молодих друїдів: перехід від теоретичного духовного єднання до справжньої зміни подоби.",["race:NightElf"]="Мандрівка між прадавнім святилищем Місячного Гаю й нещодавно посадженим Світовим Древом Тельдрассилом віддзеркалює рівновагу між тисячолітньою спадщиною калдореїв і їхніми нинішніми обов'язками."},sec={{t="Подорож між святилищами",b="Поєднавшись із Великим Духом Ведмедя в Місячному Гаю, молодий друїд має перекинути місток між позачасовими святилищами природи й неспокійним світом. Дендрит Старблейз відсилає посвячуваного з Нічного Притулку назад до Дарнасуса й довіряє наступний етап навчання місцевим наставникам, що бережуть Тельдрассил."},{t="Шлях Пазура",b="Матренґіл Берволкер чекає в Ценаріонському Анклаві — він береже природу навіть там, де хитається рівновага. Благословення Великого Духа Ведмедя — лише перший крок: Матренґіл готує посвячуваного закріпити цю люту прадавню мудрість у фізичній подобі, пройшовши суворі випробування тіла й серця."}},faq={{q="Навіщо мені повертатися до Дарнасуса?",a="Місячний Гай дарує спілкування з Великим Духом Ведмедя, але ваш безпосередній наставник, Матренґіл Берволкер, мешкає в Ценаріонському Анклаві в Дарнасусі. Він проводить практичні випробування, потрібні, щоб опанувати щойно здобуту силу.",al={"чому повертатися до дарнасуса","чому залишити місячний гай","куди дендрит мене посилає"}},{q="Хто такий Матренґіл Берволкер?",a="Матренґіл Берволкер — досвідчений наставник друїдів нічних ельфів у Ценаріонському Анклаві Дарнасуса. Він спеціалізується на тому, щоб вести молодих новачків Шляхом Пазура й навчати ведмежої подоби.",al={"хто такий матренґіл","переказ про матренґіла","берволкер"}},{q="Як повернутися з Місячного Гаю до Дарнасуса?",a="Майстриня гіпогрифів Сільва Філ'навет на південному заході Нічного Притулку переносить новачків прямим перельотом через море до Дарнасуса.",al={"як залишити нічний притулок","політ назад з місячного гаю","сільва філ'навет"}},{q="Що буде після розмови з Матренґілом?",a="Матренґіл дасть вам перше справжнє випробування мети: зійтися з Лунакло біля Каменя Місячника на схід від Обердайна на Темному Узбережжі, щоб довести, що ваші тіло й серце готові до ведмежої подоби.",al={"наступне завдання після назад до дарнасуса","що далі"}},{q="Що таке Шлях Пазура?",a="Шлях Пазура — друїдська традиція, зосереджена на тому, щоб спрямовувати лють, стійкість і силу ведмедя, втілені через спілкування з давніми первісними духами.",al={"шлях пазура","переказ про пазур друїда"}},{q="Чому Дендрит згадує, що рівновага біля Дарнасуса хитається?",a="Тельдрассил молодий і не має благословення Драконячих Аспектів, тож його гілля вразливе до дивної скверни, шаленства фурболгів і темряви, що насувається, — з усім цим активно борються друїди Ценаріонського Анклаву.",al={"рівновага дарнасуса хитається","тельдрассил осквернений"}}},fp="17,265,29.312.0,20.320.0,37.238.0,29.197.0,46.148.0,41.199.0,29.175.0,59.205.0"}
P.entries["quest:5932"] = {n="Назад до Тандер Блафа",s="«Назад до Тандер Блафа» — важливий обряд посвяти для юних друїдів-тауренів, що повертаються зі священних галявин Місячного Гаю. Поєднавшись із Великим Духом Ведмедя, учень за настановою Дендрита Старблейза вирушає назад на Узвишшя Старійшин, щоб продовжити навчання в Турака Рунтотема.",h="«Назад до Тандер Блафа» — важливий обряд посвяти для юних друїдів-тауренів, що повертаються зі священних...",kw={"назад до тандер блафа","друїд","великий дух ведмедя","дендрит старблейз","турак рунтотем","місячний гай","шлях пазура"},ang={["class:Druid"]="Цей відрізок вашої подорожі пов'язує прадавній відлюдний прихисток Місячного Гаю з продуваними вітрами висотами Тандер Блафа й позначає ваше зростання на Шляху Пазура.",["faction:Horde"]="Знання, принесені з Місячного Гаю, дають Орді могутніх захисників-перевертнів у її лавах на рівнинах Калімдору.",["race:Tauren"]="Повернувшись на Узвишшя Старійшин, ви приносите мудрість прадавніх духів додому, на користь і захист своїх племен у Малгорі."},sec={{t="Братство через кордони",b="Місячний Гай стоїть осторонь фракційних розколів смертного світу: це прихисток, де нічні ельфи й таурени, що практикують магію природи, збираються як Коло Кенарія. Після єднання з Великим Духом Ведмедя наставник із нічних ельфів Дендрит Старблейз відсилає юного таурена назад до свого народу. Хоч нічні ельфи часто вважають тауренів новачками в упорядкованому вченні Кенарія, Старблейз охоче визнає глибоку мудрість і рівновагу, які зберігає Турак Рунтотем."},{t="Повернення на кручі",b="Знову піднявшись на широкі висоти Узвишшя Старійшин у Тандер Блафі, новачок постає перед Тураком Рунтотемом зміненим. Єднання з прадавніми тотемними духами, як-от Великий Дух Ведмедя, глибоко вкорінене в культурі тауренів, проте ступити на Шлях Пазура — серйозне зобов'язання. Коли духовний зв'язок уже викувано, Турак готує друїда втілити здобуту силу й витривалість у дію."}},faq={{q="Чому нічний ельф навчав таурена в Місячному Гаю?",a="Коло Кенарія нейтральне й цілком віддане збереженню природи. У Місячному Гаю політичну ворожнечу між Ордою й Альянсом суворо відкладено, тож старійшини нічних ельфів на кшталт Дендрита Старблейза можуть наставляти молодих друїдів-тауренів.",al={"дендрит старблейз орда","чому нічний ельф-наставник","коло кенарія таурен"}},{q="Хто такий Турак Рунтотем?",a="Турак Рунтотем — шанований друїд-таурен, один із помічників Архідруїда, що служить на Узвишші Старійшин у Тандер Блафі. Він опікується навчанням молодих тауренів, які прагнуть іти шляхом природи й пазура, і є важливим зв'язковим із Колом Кенарія.",al={"роль турака рунтотема","друїдський ватажок на піднесенні старійшин"}},{q="Що молодий друїд зробив перед цим завданням?",a="Перш ніж повернутися до Малгору, новачок вирушив до Місячного Гаю, щоб знайти давній Великий Дух Ведмедя й поспілкуватися з ним, здобувши його благословення й пізнавши духовну суть ведмежої подоби.",al={"що було перед назад до тандер блафа","завдання духу великого ведмедя"}},{q="Як молоді друїди повертаються з Місячного Гаю до Тандер Блафу?",a="Бунтен Плейнсвінд на південному заході Нічного Притулку — майстер польотів, що безпечно переносить друїдів-тауренів назад до Тандер Блафу після їхніх обрядів.",al={"як повернутися з місячного гаю","політ назад з місячного гаю"}},{q="Що далі в навчанні друїда?",a="Після повернення Турак Рунтотем дає новачкові завдання «Тіло й серце» й посилає його на фізичне випробування до Каменя Місячника, там, де Пустки сходяться з Малгором, щоб довести, що він здатен утілити силу духа в справжню звірину подобу.",al={"наступне завдання друїда","після назад до тандер блафа"}},{q="Чому Дендрит Старблейз називає тауренів «молодими на шляхах Кенарія»?",a="Хоча тауренські перекази сягають давнього спілкування з Кенарієм на світанку світу, офіційне друїдство Кола Кенарія розвивали й зберігали нічні ельфи впродовж десяти тисяч років. Таурени лише нещодавно відновили впорядковане навчання під проводом Кола Кенарія.",al={"чи таурени нові друїди","історія тауренів-друїдів кенарій"}}},fp="21,276,20.491.0,20.427.0,51.262.0,23.261.0,52.198.0,64.183.0,40.244.0,72.261.0"}
P.entries["quest:6"] = {n="Винагорода за Ґарріка Педфута",s="«Винагорода за Ґарріка Педфута» — контракт Альянсу на винагороду, виданий Помічником Віллемом біля Абатства Нортшира. Він посилає молодих новобранців вистежити сумнозвісного місцевого злодія, який із відлюдної халупи біля виноградників тероризує фермерів і купців Елвінну.",h="«Винагорода за Ґарріка Педфута» — контракт Альянсу на винагороду, виданий Помічником Віллемом біля Абатства...",kw={"ґаррік педфут","винагорода","злодій","помічник віллем","нортшир","халупа"},ang={["class:Rogue"]="Ґаррік Педфут дає розбійникам перше уявлення про те, як злочинці діють у тіні Елвінну, і показує, що погано прихована схованка притягує швидкі клинки.",["faction:Alliance"]="Розправа з Ґарріком Педфутом — одна з перших прямих послуг, які майбутній шукач пригод Альянсу робить, щоб повернути стабільність Королівству Стормвінд.",["race:Human"]="Для людей, що виросли в королівстві, очистити Нортшир від головорізів на кшталт Педфута — особиста справа захисту священної землі батьківщини та її фермерів."},sec={{t="Пошесть у долині",b="Долину Нортширу колись вважали безпечним прихистком для вишколу новобранців і догляду за священними виноградниками, та нещодавній занепад закону й порядку по всьому Елвінну лишив її беззахисною. У долину прокралися зграї злодіїв, і головоріз на ім'я Ґаррік Педфут швидко став їхнім ватажком. Уже кілька тижнів Ґаррік зі своєю бандою грабує обози, обирає купців на дорогах і залякує місцевих фермерів."},{t="Правосуддя Помічника Віллема",b="Варта Стормвінда розтягнута між захистом столиці й зовнішніх кордонів, тож місцевим маршалам і помічникам лишається покладатися на завзятих добровольців, щоб тримати мир у Нортширі. Помічник Віллем призначає публічну винагороду за голову Ґарріка, аби раз і назавжди позбавити долину його банди. Розправа з Педфутом у його занедбаній халупі на схід від річки — перший удар по ширшому беззаконню, що просочується в серце людських земель."}},faq={{q="Хто такий Ґаррик Педфут?",a="Ґаррик Педфут — бандит і головоріз, що діє в Долині Нортширу. Тижнями він непокоїть місцевих фермерів і влаштовує засідки на купців, зібравши довкола себе невелику ватагу головорізів, щоб застовпити територію біля виноградників.",al={"ґаррик педфут","хто такий ґаррик","педфут"}},{q="Де знайти Ґаррика Педфута?",a="Він засів у невеликій дерев'яній хижці на схід від Абатства Нортшира, за мостом через річку, біля виноградників. Його стережуть спільники-головорізи.",al={"де ґаррик педфут","місце ґаррика","халупа ґаррика"}},{q="Хто оголосив винагороду за Ґаррика?",a="Винагороду оголошує Помічник Віллем, що стоїть біля Абатства Нортшира. Через брак міської варти, щоб пильнувати долину, Віллем наймає мандрівних новобранців, щоб ті віддали розбійника в руки правосуддя.",al={"хто оголосив винагороду за ґаррика педфута","винагорода віллема"}},{q="Чому Стормвінд не посилає регулярних вояків розібратися з ним?",a="Військо Стормвінда перевантажене. Король Варіан Рінн зник, напруга росте по всьому Лісу Елвінн і далі, тож столиця не може виділяти досвідчені гарнізони на кожного дрібного головоріза, і місцевим помічникам доводиться наймати новобранців.",al={"чому вартові не вб'ють ґаррика","де вартові стормвінда"}},{q="Чи діє Ґаррик Педфут сам?",a="Ні. Ґаррик оточив себе невеликою бандою розбійників і грабіжників, що отаборилися довкола його хижки біля виноградників Нортшира, щоб його захищати.",al={"чи ґаррик сам","банда педфута"}},{q="Який доказ вимагає Помічник Віллем?",a="Помічник Віллем вимагає речового доказу, перш ніж виплатити гроші, — а саме принести до Абатства Нортшира відрубану голову Ґаррика Педфута.",al={"доказ смерті ґаррика","голова ґаррика"}}},fp="25,260,22.420.0,23.419.0,23.227.0,35.152.0,33.181.0,63.236.0,33.147.0,38.157.0"}
P.entries["quest:60"] = {n="Кобольдські свічки",s="«Кобольдські свічки» — одне з перших доручень Вільяма Пестла з Корчми «Лев'яча Гордість» у Ґолдширі. Алхімік, що навідався сюди зі своєї крамниці в Стормвінді, шукає густий віск великих свічок, які носять кобольди, що заполонили місцеві копальні Лісу Елвінн. Для шукачів пригод це раннє знайомство з підземними шкідниками, які зазіхають на цінні золоті жили королівства.",h="«Кобольдські свічки» — одне з перших доручень Вільяма Пестла з Корчми «Лев'яча Гордість» у Ґолдширі.",kw={"кобольдські свічки","кобольди","вільям пестл","віск","фарґодіп","яшмова копальня","ґолдшир"},ang={["faction:Alliance"]="Поки королівська армія виснажена внутрішніми політичними чварами, а сили корони відсутні, захист місцевого господарства лягає на добровольців і мандрівних шукачів пригод.",["profession:Mining"]="Зачищаючи кобольдів заради свічок, рудокопи-початківці потрапляють просто на найбагатші мідні й золоті жили Елвінну, покинуті людьми-рудокопами.",["race:Human"]="Повернути захоплені копальні Елвінну й постачати товар стормвіндським ремісникам — ранні обов'язки молодих підданих королівства."},sec={{t="Доручення аптекаря",b="Вільям Пестл разом із братом тримає «Аптеку Пестла» в Торговому Кварталі Стормвінда. Коли вариш ліки, мазі й настої, такої сировини, як віск, завжди бракує. Замість купувати гарні свічки в міських торговців, Пестл помітив, що шкідники, які плюндрують Елвінн, носять на лобі напрочуд важкі грудки лою й воску — бери задарма, якщо знайдеться шукач пригод, готовий їх віддерти."},{t="Копальні Елвінну",b="Кобольди цілком заполонили і Копальню Фарґодіп на південь від Ґолдшира, і Яшмову копальню на північному сході. Ці сопучі підземні створіння цінують свої свічки понад усе: мерехтливе світло веде їх темними штольнями, поки вони риють у пошуках золота й блискучих дрібничок. Відбирати ці свічки означає не лише поповнити алхімічні запаси Пестла, а й потроху вибивати шкідників, що душать дорогоцінні рудні ділянки королівства."}},faq={{q="Навіщо Вільямові Пестлу кобольдські свічки?",a="Вільям Пестл і його брат тримають аптекарську крамницю в Торговому Кварталі Стормвінда. Перетоплений лій і віск із великих свічок вони використовують для запечатування, мазей і різних алхімічних препаратів.",al={"навіщо пестлу свічки","для чого свічки","для чого воскові свічки"}},{q="Де шукати великі свічки?",a="Свічки носять кобольди-робітники, гризуни й копачі, що живуть у копальнях Лісу Елвінн — передусім у тунелях Копальні Фарґодіп на південь від Ґолдширу та Яшмової копальні на сході.",al={"де кобольдські свічки","місця свічок","як отримати великі свічки"}},{q="Чому кобольди такі одержимі свічками?",a="Кобольди живуть у непроглядно темних підземних тунелях і бачать, копаючи, лише завдяки вогникам, прив'язаним до голів. Вони мають забобонний, майже шалений страх перед темрявою й люто захищають свої свічки від кожного, хто намагається їх відібрати.",al={"чому кобольди мають свічки","що означає не бери свічку","переказ про кобольдські свічки"}},{q="Хто такий Вільям Пестл?",a="Вільям Пестл — купець і алхімік-людина зі Стормвінда. Коли він не працює у своїй крамниці в Торговому Кварталі міста, то їздить до Ґолдширу, щоб дешево купувати матеріали в мандрівних шукачів пригод.",al={"хто такий вільям пестл","переказ про вільяма пестла","пестл ґолдшир"}},{q="Чи пов'язане це завдання з іншими негараздами в Елвінні?",a="Так. Навала кобольдів на Копальню Фарґодіп і Яшмову копальню — серйозна економічна загроза для Ґолдширу й Стормвінда. Гірників-людей вигнано, і звільнення тунелів — одне з головних завдань Маршала Дуґана.",al={"проблеми копалень елвінна","чому кобольди в копальнях","загроза кобольдів ґолдшира"}},{q="Чи є в Елвінні інші копальні, захоплені кобольдами?",a="Копальня Фарґодіп і Яшмова копальня — дві головні біля Ґолдширу, але кобольди трапляються й на берегах річок у лісі та далі на схід, до меж Редріджу.",al={"інші копальні кобольдів","список копалень елвінна"}}},fp="14,393,20.450.0,19.454.0,44.223.0,36.205.0,41.253.0,22.204.0,52.216.0,56.187.0"}
P.entries["quest:6001"] = {n="Тіло й серце",s="«Тіло й серце» — завершальне випробування в посвяті молодого друїда нічних ельфів на шлях пазура. За настановою Матренґіла Берволкера в Дарнасусі посвячуваний має вирушити в дикі хащі Темного Узбережжя, викликати охоронця місячників Лунакло й довести, що має і внутрішню стійкість, і бойову силу, — лише тоді він зможе прийняти форму ведмедя.",h="«Тіло й серце» — завершальне випробування в посвяті молодого друїда нічних ельфів на шлях пазура.",kw={"тіло й серце","лунакло","камінь місячника","кенарійський місячний пил","форма ведмедя","обердайн","друїд"},ang={["class:Druid"]="Цей обряд — визначальний поріг раннього друїдського навчання: він перетворює новачка-чарівника на захисника, що змінює подобу й може прийняти могутню форму ведмедя.",["race:NightElf"]="Для нічних ельфів єднання з прадавніми духами звірів і шанування священних каменів на Темному Узбережжі відновлює зв'язок із кенарійськими звичаями, що склалися тисячоліття тому."},sec={{t="Випробування Лунакло",b="Матренґіл Берволкер у Дарнасусі скеровує посвячуваних друїдів нічних ельфів на схід від прибережного поселення Обердайн. Там, у природній печері, де живуть дикі місячники, стоїть прадавній Камінь Місячника. Помазавши цей священний моноліт Кенарійським Місячним Пилом, посвячуваний будить Лунакло — давнього захисника каменя, що кидає виклик кожному, хто прагне успадкувати священну силу пазура."},{t="Сила тіла й серця",b="Прийняти мантію ведмедя — це куди більше, ніж груба сила. Великий Дух Ведмедя дає основи вчення про лютість природи, а випробування з Лунакло перевіряє, чи вистачить посвячуваному стійкості серця, щоб приборкати цю первісну силу й скерувати її. Здолавши охоронця в бою й дослухавшись до мудрості духу, що лишається по ньому, друїд доводить, що готовий приймати форму ведмедя, не втрачаючи себе у звіриних інстинктах."}},faq={{q="Хто такий Лунакло?",a="Лунакло — лютий дух-охоронець із місячників, що живе в печері просто на схід від Обердайна на Темному Узбережжі. Він захищає священний Камінь Місячника й відгукується на заклик новачків, які посипають реліквію Кенарійським Місячним Пилом.",al={"що таке лунакло","переказ про лунакло","бос місячників оберіжина"}},{q="Яка мета цього випробування?",a="Цей обряд посвяти — останнє випробування для новачка з нічних ельфів, що прагне вступити до лав Друїдів Пазура. Здолавши Лунакло, новачок доводить, що має і фізичну стійкість, і душевну врівноваженість, потрібні, щоб перейняти дух і подобу ведмедя.",al={"чому тіло й серце","що робить це завдання","переказ про ведмежу подобу"}},{q="Хто дає це завдання?",a="Матренґіл Берволкер, старійшина-наставник друїдів у Ценаріонському Анклаві в Дарнасусі, дає новачкам це випробування, коли вони поспілкуються з Великим Духом Ведмедя.",al={"хто дає тіло й серце","хто дає завдання ведмежої подоби"}},{q="Що таке Кенарійський Місячний Пил?",a="Кенарійський Місячний Пил — освячений обрядовий порошок, який старійшини дають новачкам. Коли його сиплють на Камінь Місячника, його магічні властивості пробуджують Лунакло й починають обрядовий бій.",al={"що таке місячний пил","переказ про кенарійський місячний пил"}},{q="Де відбувається це випробування?",a="Випробування відбувається в печері на схід від Обердайна на Темному Узбережжі, де довкола давнього різьбленого Каменя Місячника гніздяться дикі місячники.",al={"де камінь місячника","печера місячників оберіжина"}},{q="Що буде, коли Лунакло переможено?",a="Коли істоту здолано, над її тілом з'являється Дух Лунакло, щоб дарувати своє благословення й визнати подвійну силу серця й тіла друїда, перш ніж той повернеться до Дарнасуса.",al={"що буде після вбивства лунакло","дух лунакло"}}},fp="14,353,21.435.0,26.461.1,16.223.0,34.287.0,21.178.0,26.189.0,33.129.0,40.202.1"}
P.entries["quest:6002"] = {n="Тіло й серце",s="«Тіло й серце» — завершальне випробування для юних друїдів-тауренів, які прагнуть опанувати форму ведмедя. За дорученням Турака Рунтотема з Тандер Блафа учень вирушає на межу Малгору й Пусток, щоб прикликати й здолати Лунакло біля Каменя Місячника.",h="«Тіло й серце» — завершальне випробування для юних друїдів-тауренів, які прагнуть опанувати форму ведмедя.",kw={"тіло й серце","форма ведмедя","лунакло","камінь місячника","кенарійський місячний пил","турак рунтотем","друїд пазура"},ang={["class:Druid"]="Цей обряд посвяти долає прірву між ученням Кенарія від нічних ельфів і спадщиною тауренів, дозволяючи вам нарешті проявити люту стійкість форми ведмедя.",["faction:Horde"]="Друїди-таурени приносять на передову Орди життєво важливу стійкість, укорінюючи магічну силу фракції в глибокій опіці над дикою природою.",["race:Tauren"]="Для шу'гало пробудити в собі ведмедя — це і святе єднання з духами природи, і практичний спосіб захистити рівнини Малгору від загроз, що наступають."},sec={{t="Шлях Пазура",b="Щоб справді піти шляхом Друїда Пазура, учні-таурени мусять поєднати духовну переконаність із фізичною стійкістю. Після єднання з Великим Духом Ведмедя в Місячному Гаю навчання друїда перевіряють ділом. Турак Рунтотем, старший наставник друїдів на Узвишші Старійшин у Тандер Блафі, вручає гідним учням Кенарійський Місячний Пил і доручає розшукати священний камінь неподалік посушливого рубежу, де Малгор сходиться з Пустками."},{t="Випробування Лунакло",b="Камінь Місячника, що стоїть на захід від Табору Тауражо, — рідкісне святилище Кенарія на півдні Калімдору. Місячники не водяться на випалених сонцем рівнинах центрального Калімдору, тож присутність звіра-охоронця Лунакло має глибоке значення. Розсипавши місячний пил на прадавньому пам'ятнику, друїд викликає Лунакло на бій. Перемога над звіром доводить, що учень володіє і силою тіла, і ясністю серця, — так він здобуває благословення звіра й відкриває в собі внутрішню сутність ведмедя."}},faq={{q="Яка мета цього випробування?",a="Це завдання — останній крок до Ведмежої подоби для друїдів Орди. Виконавши випробування, ви доводите, що готові стати Друїдом Пазура під проводом Турака Рунтотема.",al={"чому тіло й серце","що робить тіло й серце","що я отримаю від тіла й серця"}},{q="Де розташований Камінь Місячника?",a="Камінь Місячника — у Пустках, на захід від Табору Тауражо, при дорозі, що веде до брами Малгору. Трохи на південь від дороги, за деревом біля самотнього намету, лежить священний камінь.",al={"де камінь місячника","де знайти камінь місячника","місце каменю місячника"}},{q="Хто такий Лунакло?",a="Лунакло — лютий охоронець-місячник, прив'язаний до Каменя Місячника. Прикликаний Кенарійським Місячним Пилом, він перевіряє, чи має друїд первісну завзятість і душевну стриманість, потрібні, щоб орудувати силою ведмедя.",al={"хто такий лунакло","що таке лунакло"}},{q="Що буде, якщо я програю бій із Лунакло?",a="Якщо вас переможуть, Кенарійський Місячний Пил буде витрачено. Треба повернутися до Турака Рунтотема на Узвишші Старійшин у Тандер Блафі по новий мішечок пилу, перш ніж знову пробувати прикликання.",al={"програв лунакло","втратив місячний пил","помер від лунакло"}},{q="Чи місячники — корінні мешканці Пусток?",a="Ні. Як зауважує Турак Рунтотем, місячники не водяться ні в Пустках, ні в Малгорі. Ця істота — неприродне видовище на савані, пов'язане саме з обрядами Кола Кенарія й давніми місцями небесної сили.",al={"місячники в пустках","чому тут місячники","місячники пусток"}},{q="Хто дає завдання «Тіло й серце»?",a="Завдання дає Турак Рунтотем, старший наставник друїдів на Узвишші Старійшин у Тандер Блафі, коли новачок повертається з Місячного Гаю.",al={"хто починає тіло й серце","хто дає тіло й серце"}}},fp="14,256,19.461.0,21.507.0,34.205.0,35.199.0,16.218.0,51.201.0,34.205.0,35.155.0"}
P.entries["quest:6061"] = {n="Приборкання звіра",s="«Приборкання звіра» — основоположний обряд посвяти для молодих мисливців-тауренів у Селі Бладгуф. Під проводом наставника Ява Шарпмейна мисливець вирушає в Малгор, щоб приборкати дорослого довгоступа, і робить перший крок до духовного зв'язку зі створіннями Земної Матері.",h="«Приборкання звіра» — основоположний обряд посвяти для молодих мисливців-тауренів у Селі Бладгуф.",kw={"приборкання","довгоступ","мисливець","яв шарпмейн","село бладгуф","малгор","звір-супутник"},ang={["class:Hunter"]="Цей обряд знаменує перехід від недосвідченого слідопита до справжнього повелителя звірів і вчить вас спілкуватися з тваринами під проводом Земної Матері.",["race:Tauren"]="Приборкання звіра — прадавній звичай, осердя кочового мисливського спадку Малгору, що зміцнює зв'язок між мисливцем і природою."},sec={{t="Священний зв'язок із дикою природою",b="Для тауренів полювання ніколи не зводилося до вбивства звірів заради м'яса й шкур. Прадавні перекази кажуть: здолавши дику звірину Малгору й поєднавшись із нею, мисливець вбирає її дух і наближається до Земної Матері. Приборкання звіра-супутника підносить цей зв'язок ще вище: той, хто міг стати супротивником, обертається на довічного партнера, суголосного з природною рівновагою рівнин."},{t="Перше випробування",b="Яв Шарпмейн починає навчання посвяченого не з лютих верховних хижаків, а зі швидких і сторожких довгоступів, що блукають травами Малгору. Озброєний зачарованим жезлом приборкання, мисливець має стати віч-на-віч із дорослим довгоступом, угамувати його дикі інстинкти й заслужити довіру. Це перше випробування доводить рішучість мисливця й готує його до вибагливіших звірів, які чекають попереду."}},faq={{q="Яка мета цього випробування?",a="Це завдання — перше практичне випробування для мисливців-тауренів, що вчаться мистецтва дружби зі звірами. Приборкавши за допомогою жезла приборкання дорослого рівнинного довгоступа, мисливець пізнає основи духовного й робочого зв'язку зі звірами.",al={"чому приборкувати довгоступа","мета завдання","завдання вихованця таурена"}},{q="Хто дає це завдання і де його знайти?",a="Завдання дає Яв Шарпмейн — наставник мисливців у Селі Бладгуф серед центральних рівнин Малгору.",al={"хто дає завдання","де видавець завдання","де яв шарпмейн"}},{q="Чи лишається дорослий рівнинний довгоступ у мене назавжди?",a="Ні. Звірі, приборкані під час трьох перших випробувань Ява Шарпмейна, — тимчасові напарники для вправ. Коли ви пройдете весь ланцюжок навчання й опануєте приборкання, то зможете вирушити в світ і назавжди приборкати будь-якого придатного супутника.",al={"чи вихованець постійний","чи я лишу довгоступа","лишити звіра після завдання"}},{q="Чому таурени вважають приборкання звірів духовним дійством?",a="Тауренська традиція навчає, що, спілкуючись із дикими істотами й перемагаючи їх, мисливці переймають їхній дух і зливаються з природним світом. Приборкання звіра — це взаємна пошана й єдність із творіннями Земної Матері.",al={"переказ про вихованців таурена","приборкання за землею-матір'ю","чому таурени приборкують звірів"}},{q="Де водяться дорослі рівнинні довгоступи?",a="Дорослі рівнинні довгоступи блукають по всіх хвилястих саванах і долинах довкола Села Бладгуф у Малгорі.",al={"де довгоступи","де рівнинний довгоступ","знайти дорослого довгоступа"}},{q="Що далі після цього завдання?",a="Повернення жезла приборкання Явові Шарпмейну веде до наступного випробування: треба приборкати степового нишпорку, а тоді — агресивного пікірника, і лише потім навчитися постійного приборкання звірів.",al={"що далі","ланцюжок після цього","наступний крок приборкання"}}},fp="16,289,27.405.0,14.390.0,34.268.0,48.125.0,45.233.0,52.239.0,39.118.0,28.198.0"}
P.entries["quest:6062"] = {n="Приборкання звіра",s="Це випробування — перший крок молодого мисливця Орди в мистецтві приборкання звірів. Під проводом ветерана Тотара в Гострому Пагорбі майбутні мисливці за допомогою зачарованого жезла приборкання впокорюють лютого плямистого вепра й пов'язують його з собою.",h="Це випробування — перший крок молодого мисливця Орди в мистецтві приборкання звірів.",kw={"мисливець","тотар","приборкання","вепр","гострий пагорб","улюбленець"},ang={["class:Hunter"]="Цей обряд посвяти — міст між простим стрільцем і справжнім володарем звірів: він відкриває визначальний для мисливця зв'язок зі звіриними супутниками.",["race:Orc"]="Для орків влада над звіром — відображення сили волі й панування над суворою дикою землею їхнього нового дому в Дуротарі.",["race:Troll"]="Мисливці Темного Списа через це навчання налаштовують свій дух на сувору дику природу Калімдору, продовжуючи свої давні традиції вистежування."},sec={{t="Обряд посвяти мисливця",b="Для мисливців-орків і тролів Темного Списа, що зростають у Дуротарі, вижити самотою в дикій природі — лише половина справи. Справжній мисливець, володар дикої землі, має навчитися підкоряти своїй волі саму природу, перетворюючи ворожих звірів на вірних союзників. Наставник мисливців Тотар довіряє новачкам зачарований жезл приборкання й кидає їм виклик: стати віч-на-віч із лютим диким вепром, не вдаючись до смертоносної стріли."},{t="Вепри Дуротару",b="Люті плямисті вепри блукають посушливими чагарями довкола Гострого Пагорба. Хоч вони грубі й злі, їхня витривалість і лють роблять їх ідеальними для першого приборкання. Витримати їхні наскоки й стерпіти їхню агресію, водночас спрямовуючи силу жезла, — для цього потрібні терпіння й залізна рішучість, чесноти, без яких не обійтися жодному слідопитові Орди."}},faq={{q="Яка мета цього випробування?",a="Це перше практичне випробування для молодих мисливців у Дуротарі: воно вчить спрямовувати волю крізь жезл приборкання, щоб скорити дику істоту, а не просто вбити її.",al={"навіщо це завдання","причина приборкання кабана","сенс приборкання звіра"}},{q="Хто дає це завдання?",a="Тотар, наставник мисливців на Гострому Пагорбі, дає це доручення, коли ви доведете свої основні навички виживання в Дуротарі.",al={"хто дає завдання","хто дає приборкання звіра","де взяти завдання кабана"}},{q="Де водяться люті плямисті кабани?",a="Люті плямисті кабани блукають сухими чагарниками одразу за частоколом Гострого Пагорба в центрі Дуротару.",al={"де люті плямисті кабани","місце кабанів","де знайти кабана"}},{q="Чи лишається кабан у мене назавжди після цього завдання?",a="Ні. Кабан, приборканий у цій першій вправі, — лише для тренування. Він іде геть, коли ви повертаєтеся до Тотара, адже, перш ніж утворити тривалий зв'язок, треба продовжити навчання з іншими істотами.",al={"чи лишу кабана","чи кабан постійний вихованець","лишити лютого кабана"}},{q="Що далі після цього доручення?",a="Коли ви повернетеся до Тотара, він перевірить, як ви даєте раду іншим небезпечним хижакам Дуротару — зокрема прибійним повзунам і броньованим скорпідам.",al={"наступне завдання","що після приборкання кабана","наступний крок ланцюжка приборкання"}},{q="Навіщо жезл приборкання, а не чистий інстинкт?",a="Мисливцям-новачкам бракує витонченої духовної й фізичної дисципліни, щоб безпосередньо порозумітися зі звірами. Зачарований жезл приборкання слугує осередком, що допомагає новачкам утверджувати владу над духом дикого звіра, доки вони назавжди не опанують це мистецтво.",al={"навіщо жезл приборкання","що робить жезл","переказ про жезл приборкання"}}},fp="16,222,26.396.0,20.350.0,34.185.0,21.138.0,39.121.0,50.195.0,27.150.0,46.246.0"}
P.entries["quest:6063"] = {n="Приборкання звіра",s="Це завдання — перше випробування на шляху мисливця нічних ельфів до мистецтва звіриного товариства. За настановою Дазалара з Доланаара мисливець-початківець має зачарованим жезлом приборкання встановити зв'язок із диким павуком, що зветься Причаєнець Плетива Лісу. Воно перевіряє, чи здатен мисливець поважати природу й єднатися з нею, а не підкоряти її силою.",h="Це завдання — перше випробування на шляху мисливця нічних ельфів до мистецтва звіриного товариства.",kw={"приборкання звіра","мисливець","дазалар","причаєнець плетива лісу","жезл приборкання","доланаар"},ang={["class:Hunter"]="Цей обряд переходу знаменує перетворення мисливця з самотнього лучника на справжнього партнера дикої природи, пов'язаного з лісовими звірами.",["race:NightElf"]="Відображаючи філософію калдорей, приборкання звірів робить наголос на єднанні й шанобі до природи, а не на підкоренні й пануванні."},sec={{t="Священний зв'язок",b="Для калдорей полювання — не просто вистежування здобичі чи виживання в хащах; це священні стосунки з природою. Наставники мисливців, такі як Дазалар, навчають, що природа незмірно більша за будь-кого зі смертних. Тварини — не в'ючна худоба й не знаряддя, які можна силоміць зігнути під свою волю, а самостійні створіння, що потребують взаємної поваги. Щоб довести готовність до звіра-супутника на все життя, мисливці-новачки мають приборкати первісні інстинкти місцевої живності давніми прийомами, а не грубою силою."},{t="Перше випробування",b="Випробування починаються з велетенських павуків, що заполонили гілля Тельдрассила. Дазалар довіряє мисливцеві особливий жезл приборкання й велить розшукати Причаєнця Плетива Лісу. Заглибившись у тінисті хащі, мисливець має зустрітися з отруйним павуком і встановити з ним чуттєвий зв'язок, витримуючи його напади. Успішно наведений тимчасовий міст між розумами доводить, що мисливець здатен єднатися навіть із моторошними хижаками Світового Дерева, які шурхотять у темряві."}},faq={{q="Навіщо це завдання?",a="Це завдання відкриває низку випробувань, які мають пройти мисливці нічних ельфів, щоб навчитися назавжди приборкувати звірів-супутників. Застосовуючи жезл приборкання до визначених місцевих звірів, мисливці доводять, що мають досить витримки й уміння, аби єднатися з дикими хижаками.",al={"навіщо це завдання","вихованець завдання","що дає приборкання звіра"}},{q="Хто дає це завдання?",a="Дазалар, наставник мисливців, що живе в поселенні Доланаар на Тельдрассилі, пропонує це завдання молодим мисливцям нічних ельфів, які набули достатньо досвіду у своїй справі.",al={"хто дає завдання","де взяти завдання приборкання","хто починає приборкання звіра"}},{q="Яку істоту треба приборкати в цьому випробуванні?",a="Вам належить приборкати Причаєнця Плетива Лісу — одного з отруйних велетенських павуків, що водяться в диких хащах і лісах довкола Доланаару.",al={"якого вихованця приборкати","ціль причаєнець плетива лісу","якого звіра приборкати"}},{q="Чи лишиться Причаєнець Плетива Лісу зі мною назавжди?",a="Ні. Причаєнець Плетива Лісу, якого ви приборкаєте під час цього завдання, — тимчасовий супутник, лише для того, щоб опанувати основи поводження з вихованцем. Щойно ви повернетеся до Дазалара, зв'язок розривається, і ви готуєтеся до наступного випробування.",al={"чи лишу павука","чи причаєнець постійний","лишити вихованця"}},{q="Чому нічні ельфи спершу випробовують мисливців павуками?",a="Причаєнці Плетива Лісу хижі й агресивні, тож суворо перевіряють витримку новачка. Підкоривши павука, що здається чимось неприродним, мисливець доводить, що здатен поєднати свою свідомість із найрізноманітнішими й найворожішими проявами природи.",al={"чому причаєнець плетива лісу","навіщо приборкувати павука","переказ про приборкання павуків"}},{q="Що буде після повернення до Дазалара?",a="Дазалар посилає мисливця перевірити свій зв'язок з іншими тваринами Тельдрассилу — а саме зі Скрадливим Нічним Шаблезубом і Верескуном-стригідом, — і лише тоді дарує вміння приборкувати звірів назавжди.",al={"що далі","після приборкання звіра","наступне випробування"}}},fp="16,332,13.537.0,15.474.0,34.242.0,21.181.0,42.138.0,41.209.0,51.235.0,38.190.1"}
P.entries["quest:6064"] = {n="Приборкання звіра",s="«Приборкання звіра» — перше випробування на шляху дворфійського мисливця до володіння звірами-супутниками в Дун Мороґу. Під проводом Ґріфа Вайлдгарта з Хараноса юні слідопити вчаться втихомирити лютого Великого Скелястого Вепра й зріднитися з ним за допомогою зачарованого жезла приборкання.",h="«Приборкання звіра» — перше випробування на шляху дворфійського мисливця до володіння звірами-супутниками в...",kw={"приборкання","мисливець","вепр","вайлдгарт","жезл","харанос","звір"},ang={["class:Hunter"]="Це завдання — вирішальний поріг, за яким новачок-стрілець стає справжнім володарем звірів, і початок низки випробувань, що відкривають постійних тваринних супутників.",["race:Dwarf"]="Горяни Айронфорджа шанують звірів, здатних витримати пронизливий холод Дун Мороґу; починати з витривалого скелястого вепра — у дусі дворфійської поваги до впертості й стійкості."},sec={{t="Супутник мисливця",b="Доти дворфійські горяни й слідопити покладалися лише на стрілецьку майстерність, пастки та чуття дикої природи. Та справжня душа мисливця — у довічному партнерстві з диким звіром. Ґріф Вайлдгарт, що стоїть біля Ґуральні Тандербрю в Хараносі, наглядає за цим обрядом переходу. Замість вимагати, щоб новачок назавжди прив'язав до себе першого-ліпшого звіра, Ґріф велить йому випробувати терпіння й рішучість на кількох тутешніх видах Дун Мороґу."},{t="Скелястий Вепр",b="Перше випробування зводить слідопита з Великим Скелястим Вепром — одним із витривалих товстошкурих кабанів, що блукають засніженими передгір'ями Дун Мороґу. Укриті щетинистим хутром і жорсткою плоттю, ці звірі вперті й агресивні, тож ідеально підходять для першого випробування волі. Жезлом Приборкання, який дає Ґріф, мисливець має витримати натиск вепра і вгамувати його лють, доки той не скориться."}},faq={{q="Хто проводить це випробування?",a="Випробування дає Ґріф Вайлдгарт, досвідчений наставник мисливців-дворфів, що стоїть біля Ґуральні Тандербрю в Хараносі.",al={"хто дає завдання","хто починає приборкання звіра","де ґріф вайлдгарт"}},{q="Чому спершу треба приборкати Великого Скелястого Вепра?",a="Великі Скелясті Вепри міцні й уперті, але їх повно на засніжених хребтах Дун Мороґа. Підкорити таку витривалу товстошкіру істоту — базова вправа, яка вчить спокійно, але владно поводитися з агресивним звіром.",al={"чому скелястий вепр","якого звіра приборкати","приборкання вепра"}},{q="Чи залишиться цей вепр зі мною назавжди?",a="Ні. Це випробування — лише практика. Зв'язок, викуваний Жезлом Приборкання, тимчасовий: він дає змогу відчути, як це — керувати звіром, перш ніж ви повернете жезл і спробуєте інші види.",al={"чи вепр постійний","лишити скелястого вепра","чи можна лишити вихованця"}},{q="Де знайти Великих Скелястих Вепрів?",a="Великі Скелясті Вепри блукають відкритими сніговими полями й сосновими гаями довкола Хараноса та замерзлими схилами Дун Мороґа.",al={"місця вепрів","де великі скелясті вепри","поява великого скелястого вепра"}},{q="Що далі, після приборкання скелястого вепра?",a="Повернувшись до Ґріфа Вайлдгарта, ви завершуєте цей перший урок і одразу переходите до другого випробування — приборкати Снігового Леопарда.",al={"наступне випробування","що після цього завдання","наступний крок ланцюжка мисливця"}},{q="Як діє Жезл Приборкання?",a="Жезл Приборкання — зачарований інструмент, який наставники мисливців дають новачкам, щоб ті могли спрямувати свою волю й угамувати дикі інстинкти звіра без особливої магічної підготовки чи багаторічного досвіду заклинання звірів.",al={"переказ про жезл приборкання","що таке жезл","як приборкувати"}}},fp="16,251,20.493.0,13.427.0,22.127.0,38.231.0,35.190.0,34.124.0,38.144.0,29.209.0"}
P.entries["quest:6065"] = {n="Шлях мисливця",s="«Шлях мисливця» — важлива віха для молодих мисливців-тауренів у Малгорі, що спрямовує їх до поглибленого навчання дружби зі звірами. Щойно новачки доведуть основи влучності й вистежування, місцеві наставники відсилають їх до Села Бладгуф по пораду до наставника мисливців Ява Шарпмейна. Ця подорож відкриває духовні та практичні випробування, потрібні, щоб приборкати дикого звіра й зріднитися з ним.",h="«Шлях мисливця» — важлива віха для молодих мисливців-тауренів у Малгорі, що спрямовує їх до поглибленого...",kw={"шлях мисливця","яв шарпмейн","село бладгуф","малгор","таурени","приборкання звірів","озеро кам'яного бика"},ang={["class:Hunter"]="Це завдання позначає мить, коли лучник чи стрілець стає справжнім повелителем звірів і робить перший крок до вірного бойового супутника.",["faction:Horde"]="Мисливці Орди значною мірою покладаються на лютих звірів прикордоння як на передових захисників і слідопитів у суворих нетрях Калімдору.",["race:Tauren"]="Для шу'хало вміння приборкувати диких звірів — духовне продовження їхньої шани до природи й творіння Земної Матері."},sec={{t="Обряд посвяти",b="Для кочових шу'хало полювання — священнодійство, а не розвага. Мисливець має розуміти рівновагу природи, шанувати духів рівнин і виявляти повагу до тварин, які годують племена. Коли молодий мисливець доводить, що вміє вижити в дикому краю й володіє луком чи рушницею, старійшини визнають: він готовий піти далі самотнього вистежування. Наказ розшукати досвідчених наставників позначає поріг справжньої зрілості в культурі тауренів."},{t="Дорога до Села Бладгуф",b="Шлях веде новачків через розлогі трави Малгору до Села Бладгуф — осередку громади, що притулився біля Озера Кам'яного Бика. Там чекає Яв Шарпмейн, бувалий ловець, який добре знає норов тутешньої звірини. Розмова з Шарпмейном — не проста формальність: вона засвідчує, що мисливець готовий до непростих випробувань приборкання звірів і до того, щоб учитися єднатися з хижаками, а не лише полювати на них."}},faq={{q="Навіщо завдання «Шлях мисливця»?",a="Це завдання — офіційне запрошення для молодих мисливців-тауренів розпочати випробування з приборкання звірів. Воно скеровує мисливця до Села Бладгуф, до Ява Шарпмейна, який проводить обряди, потрібні, щоб поєднатися зі звіром-супутником.",al={"навіщо це завдання","мета шляху мисливця","початок завдання вихованця мисливця"}},{q="Хто посилає на це завдання?",a="Завдання дають наставники мисливців-тауренів — наприклад, ті, що стоять у Таборі Нарачі, — щойно молодий мисливець набуде достатньо досвіду й опанує основи виживання та стрільби.",al={"хто дає шлях мисливця","завдання наставника мисливців"}},{q="Хто такий Яв Шарпмейн?",a="Яв Шарпмейн — шанований наставник мисливців-тауренів, що живе в Селі Бладгуф. Йому доручено вчити молодих мисливців небезпечного мистецтва: як підійти до диких звірів Малгора, заспокоїти їх і приборкати.",al={"хто такий шарпмейн","роль яв шарпмейна"}},{q="Що буде після виконання цього завдання?",a="Коли ви доповісте Явові Шарпмейну, він розпочне низку випробувань «Приборкання звіра». Мисливцеві доведеться вирушити в дикі краї з жезлом приборкання й угамувати кількох місцевих тварин, перш ніж здобути право навчати постійного супутника.",al={"що далі","наступне завдання після шляху мисливця"}},{q="Чому мисливці-таурени єднаються зі звірами, а не просто полюють на них?",a="За традицією тауренів, звірі — споріднені душі, діти Земної Матері. Звір, із яким поєднався мисливець, — не слуга, а супутник і напарник на полюванні; у цьому втілено взаємну повагу й спільне виживання на рівнинах.",al={"переказ про вихованців таурена","чому таурени приборкують вихованців"}},{q="Чи можуть мисливці інших рас узяти саме це завдання?",a="Ця версія завдання призначена саме для мисливців-тауренів, які навчаються в Малгорі. Інші раси Орди, як-от орки й тролі, отримують відповідні настанови, пристосовані до їхніх рідних земель у Дуротарі.",al={"чи це лише для таурена","чи орки можуть взяти шлях мисливця таурена"}}},fp="17,421,17.483.0,29.455.0,41.243.0,28.201.0,21.207.0,41.250.0,68.203.0,52.228.0"}
P.entries["quest:6068"] = {n="Шлях мисливця",s="Шлях мисливця — обряд посвяти, що скеровує молодих мисливців-орків і тролів до Гострого Пагорба. Під проводом майстра-мисливця Тотара слідопити-початківці опановують життєво важливу науку — підкоряти диких хижаків своїй волі.",h="Шлях мисливця — обряд посвяти, що скеровує молодих мисливців-орків і тролів до Гострого Пагорба.",kw={"мисливець","тотар","шлях мисливця","гострий пагорб","приборкання","дуротар"},ang={["class:Hunter"]="Цей виклик — найважливіший поріг у вашій подорожі: від самотнього стрільця до справжнього володаря звірів.",["faction:Horde"]="Орда покладається на своїх розвідників і слідопитів, які приборкують тутешніх хижаків і перетворюють безжальну природу Дуротару на свою перевагу.",["race:Orc"]="Для орків союз із лютим супутником відлунює давніми традиціями, що сягають вовчих вершників Дренору.",["race:Troll"]="Мисливці Темного Списа вважають уміння приборкувати місцевих рапторів і вепрів необхідним, щоб закріпитися в підступних нетрях Дуротару."},sec={{t="Пробудження мисливця",b="Досі учень-мисливець у Дуротарі покладався лише на власний лук і кмітливість. Вистежування здобичі серед каньйонів червоної глини й суворих чагарів навчає терпіння, та справжня майстерність в Орді вимагає зв'язку з неприборканою звіриною цього краю. Класові наставники бачать, коли учень досить виріс, щоб ступити на цю дорогу, і посилають його просто до Гострого Пагорба."},{t="Майстер у Гострому Пагорбі",b="У Гострому Пагорбі чекає Тотар — мисливець-ветеран, що глибоко знає дику мудрість Дуротару. Тотар — той наставник, який навчає новачків небезпечного ритуалу: впокорити лютих звірів, не зламавши їхнього духу. Зустріч із ним — перший крок до того, щоб ходити дикими землями з вірним супутником поруч."}},faq={{q="Навіщо завдання «Шлях мисливця»?",a="Це вступний виклик, що відправляє мисливців-орків і тролів до Гострого Пагорба, де вони розпочинають навчання з приборкання звірів.",al={"чому шлях мисливця","мета шляху мисливця","що робить це завдання"}},{q="Хто такий Тотар?",a="Тотар — досвідчений мисливець із Гострого Пагорба, який проводить випробування для молодих слідопитів Орди: вони мають навчитися єднатися з дикими звірами й керувати ними.",al={"хто такий тотар","тотар хто він","тотар разор гілл"}},{q="Чому молоді мисливці не можуть приборкувати вихованців одразу?",a="Щоб упоратися з небезпечним хижаком, потрібні глибока дисципліна, терпіння й особливі прийоми приборкання. Поки мисливець не доведе, що має базові навички виживання, спроба підкорити дикого звіра закінчилася б каліцтвом або смертю.",al={"чому немає вихованця на першому рівні","чому мисливці чекають вихованців","коли мисливці отримують вихованців"}},{q="Які раси проходять саме це випробування?",a="Ця версія шляху призначена для орків і тролів Темного Спису, що дорослішають у Дуротарі; мисливці-таурени проходять подібне випробування в Малгорі.",al={"хто отримує це завдання","чи це лише для орків і тролів","які раси це роблять"}},{q="Що буде, коли я доповім Тотарові?",a="Тотар одразу доручає мисливцеві вистежити й підкорити різних місцевих хижаків Дуротару, щоб довести свою вправність у приборканні.",al={"що далі","після шляху мисливця","наступне завдання після тотара"}},{q="Де відбувається це навчання?",a="Випробування зосереджене довкола Гострого Пагорба — головного поселення в центрі Дуротару, між Долиною Випробувань та Оргріммаром.",al={"де разор гілл","де тотар","куди йти"}}},fp="17,222,20.376.0,24.320.0,41.131.0,14.145.0,46.220.0,42.159.0,39.141.0,36.131.0"}
P.entries["quest:6074"] = {n="Шлях мисливця",s="«Шлях мисливця» — обряд переходу для дворфійських мисливців-новачків по всьому Дун Мороґу, щойно вони опанують основи вистежування та стрільби. Місцеві наставники посилають учнів до Ґріфа Вайлдгарта в Харанос, щоб ті почали вчитися мистецтва приборкання диких звірів як постійних супутників.",h="«Шлях мисливця» — обряд переходу для дворфійських мисливців-новачків по всьому Дун Мороґу, щойно вони...",kw={"мисливець","шлях","вайлдгарт","харанос","приборкання","звір","наставник"},ang={["class:Hunter"]="Це завдання знаменує вирішальний перехід від самотнього слідопита до справжнього володаря звірів, здатного керувати дикими хижаками.",["race:Dwarf"]="Дворфійські горяни здавна тримають ведмедів і вепрів як надійних розвідницьких супутників на засніжених вершинах Дун Мороґу."},sec={{t="Справжнє покликання мисливця",b="Доки мисливець не опанує мистецтво єднання зі звіром, він ходить засніженими скелями Дун Мороґу сам, покладаючись лише на сокиру, рушницю чи лук. Наставники, як-от Олмін Бернінґбірд і Трістан Шедоустоун, пильно стежать за учнями, доки ті не виявлять витримки, потрібної, щоб зустріти дикого звіра й не вбити його. Щойно новачок доводить достатню дисципліну, його посилають гірськими дорогами до Хараноса."},{t="Прибути до Ґріфа Вайлдгарта",b="У Хараносі Ґріф Вайлдгарт наглядає за останніми випробуваннями дворфійського мисливства. Приборкати звіра вважають значно складнішим, ніж убити його заради м'яса чи шкури: це потребує терпіння, фізичної витривалості й чуттєвого зв'язку з дикими хижаками гір. Вайлдгарт — брама до цих випробувань, що готує мисливця до виснажливої перевірки сили волі проти найлютішої звірини Дун Мороґу."}},faq={{q="Навіщо це завдання?",a="Це офіційний виклик, що відправляє подорослішого мисливця до Хараноса, де під наглядом Ґріфа Вайлдгарта починаються випробування з приборкання вихованця.",al={"навіщо це завдання","що таке шлях мисливця","початок завдання вихованця мисливця"}},{q="Хто відправляє мене в цю путь?",a="Своїх учнів на це завдання скеровують наставники мисливців — зокрема Олмін Бернінґбірд у Залі Зброї Айронфорджа, Трістан Шедоустоун та Ейнріс Брайтспір.",al={"хто дає завдання","хто дає шлях мисливця","де його взяти"}},{q="Де знайти Ґріфа Вайлдгарта?",a="Ґріф Вайлдгарт стоїть біля Ґуральні Тандербрю в Хараносі, у засніженій долині Дун Мороґа.",al={"де ґріф вайлдгарт","де ґріф","наставник мисливців харанос"}},{q="Навіщо мисливцям наставник, щоб приборкувати звірів?",a="Приборкання диких звірів вимагає особливих прийомів і жезла приборкання, щоб порозумітися з хижаком, не спровокувавши бою на смерть. Ґріф Вайлдгарт навчає цих традицій.",al={"навіщо потрібне навчання приборкання","переказ про приборкання вихованців","чому ще не можу приборкувати"}},{q="Що буде, коли я доповім Ґріфові Вайлдгарту?",a="Ґріф Вайлдгарт одразу перевіряє, з якого ви тіста, і відправляє вас у дикі краї з жезлом приборкання, щоб підкорити кількох різних звірів, які водяться в Дун Мороґу.",al={"наступне завдання","що після шляху мисливця","ланцюжок після цього"}},{q="Чи може будь-який мисливець узяти саме це завдання?",a="Цей виклик призначений для мисливців-дворфів, які діють у Дун Мороґу: він скеровує їх до місцевого наставника в Хараносі.",al={"чи це лише для дворфів","чи нічні ельфи можуть це взяти","обмеження за расою"}}},fp="17,296,23.404.0,27.430.0,34.124.0,26.164.0,32.114.0,45.184.0,47.153.0,40.129.0"}
P.entries["quest:6081"] = {n="Навчання звіра",s="Навчання звіра — завершальний обряд посвяти для молодих мисливців-орків і тролів у Дуротарі. Довівши владу над дикими звірами рівнин, мисливці вирушають із Гострого Пагорба до Оргріммару вчитися в майстра-мисливця Ормака Ґрімшота. Ця подорож навчає новачка доглядати, годувати й відточувати вміння звіриного супутника на все життя.",h="Навчання звіра — завершальний обряд посвяти для молодих мисливців-орків і тролів у Дуротарі.",kw={"мисливець","ормак ґрімшот","оргріммар","долина честі","улюбленець","навчання звіра"},ang={["class:Hunter"]="Це завдання — мить, коли ваш улюбленець стає постійним, надійним союзником, а не скороминущим прикликанням: воно відкриває необхідні вміння «Годування улюбленця» й «Оживлення улюбленця».",["faction:Horde"]="Орда покладається на своїх розвідників і звірів, щоб берегти крихкі кордони Дуротару й Пусток від набігів кентаврів, шипогривів та Альянсу.",["race:Orc"]="Орки вважають зв'язок із мисливським супутником справою воїнської честі й обов'язку — союзом, що гартується в боях на суворих рубежах Дуротару.",["race:Troll"]="Для тролів Темного Списа, що облаштовують новий дім у Калімдорі, уміння порозумітися з дикими створіннями Дуротару життєво важливе для розвідки й виживання на незнайомій землі."},sec={{t="Подорож за межі дикої землі",b="У посушливих каньйонах Дуротару опанувати лук і вистояти проти суворої природи — лише половина обов'язку мисливця. Довівши свою стійкість приборканням лютих вепрів Дуротару, прибійних крабів і броньованих скорпідів, молоді мисливці готові до справжньої відповідальності — опіки над звіром. Тотар, що стоїть у Гострому Пагорбі, посилає їх на північ через яри червоної глини просто до укріплених воріт Оргріммару."},{t="Долина Честі",b="У велелюдній столиці майбутні майстри-слідопити мають розшукати Долину Честі — осередок, де войовничі душі й досвідчені слідопити відточують своє ремесло. Там живе Ормак Ґрімшот, один із найшанованіших майстрів-мисливців Орди. Ормак дивиться крізь зелену юність, щоб побачити, чи має мисливець терпіння не лише командувати звіром, а й підтримувати та плекати його крізь голод, битви та втрати."},{t="Зв'язок із дикою природою",b="Звір, здобутий силою волі, лишається диким, доки між мисливцем і супутником не постане порозуміння. Ормак передає священні традиції, потрібні, щоб берегти цей зв'язок: знання про те, яка їжа живить дух кожної істоти, дисципліну, щоб навчити їх смертоносних прийомів, і духовну зосередженість, щоб оживити полеглого звіра, якщо він впаде, виконуючи обов'язок."}},faq={{q="Хто дає завдання «Навчання звіра»?",a="Тотар, наставник мисливців, що стоїть біля казарм на Гострому Пагорбі, пропонує це завдання, коли ви успішно підкорите всіх трьох звірів-випробувачів у Дуротарі.",al={"хто дає навчання звіра","хто починає навчання звіра","де почати навчання звіра"}},{q="Де знайти Ормака Ґрімшота?",a="Ормак Ґрімшот живе в Долині Честі — східному кварталі столиці Оргріммар, поряд з іншими досвідченими наставниками мисливців і воїнів.",al={"де ормак ґрімшот","знайти ормака ґрімшота","де ормак"}},{q="Чого навчає Ормак Ґрімшот?",a="Ормак навчає, як прищеплювати супутникові активні й пасивні вміння, як годувати вихованця, щоб він лишався відданим і задоволеним, і як оживити його, якщо він загине в бою.",al={"чого я навчуся","навички з нагороди","здібності вихованця мисливця"}},{q="Чому мисливцям-оркам і тролям для цього треба йти до Оргріммара?",a="Місцеві наставники на кшталт Тотара можуть навчити основ виживання в дикій природі, але вищу майстерність володіння звірами бережуть старші розвідники Орди й шановані слідопити на зразок Ормака Ґрімшота в столиці.",al={"чому йти до оргріммара","чому оргріммар","відвідини долини честі"}},{q="Чи виконують саме це завдання інші раси Орди?",a="Ні. Цей обряд призначений для мисливців-орків і тролів, що починають у Дуротарі. Мисливці-таурени проходять схожий ритуал у Малгорі під проводом власних племінних майстрів.",al={"чи таурени можуть це зробити","чи це лише для орків","мисливець нежить"}},{q="Що буде, якщо мисливець не завершить це навчання?",a="Не пройшовши цього навчання, мисливець не зможе годувати свого супутника, як слід його тренувати чи воскрешати, тож будь-який упійманий звір буде нещасним, слабким і зрештою схильним його покинути.",al={"чи потрібно це робити","чи можна пропустити навчання звіра"}}},fp="18,382,31.428.0,19.411.0,21.391.0,40.164.0,32.156.0,42.174.0,62.190.0,48.167.0,60.188.0"}
P.entries["quest:6082"] = {n="Приборкання звіра",s="Це завдання — останнє випробування в основних обрядах посвяти молодого мисливця Орди в Дуротарі. Під проводом мисливця-ветерана Тотара в Гострому Пагорбі майбутній слідопит має зустрітися з небезпечним броньованим скорпідом і приборкати його. Перемога над цим панцирним хижаком доводить владу над дикими звірами й відкриває довічну здатність приборкувати, кликати й відпускати справжнього супутника.",h="Це завдання — останнє випробування в основних обрядах посвяти молодого мисливця Орди в Дуротарі.",kw={"мисливець","тотар","скорпід","приборкання","гострий пагорб","улюбленець"},ang={["class:Hunter"]="Цей обряд посвяти — визначальна віха раннього шляху мисливця: він назавжди відкриває основні вміння приборкувати, кликати й вести звіриних супутників.",["faction:Horde"]="Молоді орки й тролі в Дуротарі мають вистояти проти найлютіших хижаків пустельної землі, щоб заслужити місце справжніх розвідників і годувальників Орди.",["race:Orc"]="Упокорення скорпідів Дуротару вшановує орківську філософію: долати сувору землю незламною волею й воїнською дисципліною.",["race:Troll"]="Мисливці Темного Списа покладаються на гостре чуття й глибокий зв'язок із духами дикої природи, щоб угамувати отруйних хижаків, які вразили б інших."},sec={{t="Останнє випробування",b="Перш ніж мисливцеві дозволять блукати Калімдором із вірним звіриним супутником, він має довести, що здатен приборкати найсуворішу звірину Дуротару. Наставник мисливців Гострого Пагорба Тотар посилає учнів впокорити трьох різних створінь зачарованим жезлом приборкання. Уже випробувавши свою стійкість проти лютих вепрів і прудких прибійних крабів, мисливці мають стати проти броньованого скорпіда — отруйного хижака в товстому панцирі, що втілює витривалість і смертоносну швидкість."},{t="Зв'язок із дикою природою",b="Упокорити броньованого скорпіда — це не просто вбивство, а доказ зосередженості й панування під невпинним натиском. Тотар закликає мисливців наслідувати швидкі, впевнені удари звіра. Повернення до Гострого Пагорба після успішного приборкання отруйного членистоногого доводить, що мисливець має спокійну волю, потрібну, щоб утримувати владу. Коли жезл приборкання повернуто, Тотар передає вроджені прийоми дикої природи, і мисливець може сам шукати й прив'язувати постійного супутника на власний вибір."}},faq={{q="Якого звіра треба приборкати в цьому випробуванні?",a="Вам треба знайти броньованого скорпіда, що блукає посушливими червоними скелями Дуротару, і жезлом приборкання Тотара угамувати його та підкорити.",al={"якого звіра приборкати","цільовий звір","завдання скорпіда"}},{q="Чи залишиться броньований скорпід зі мною після завдання?",a="Ні. Броньований скорпід, приборканий під час випробування, — тимчасовий і зникає, щойно ви повернете навчальний жезл. Зате, виконавши завдання, ви назавжди здобудете вміння приборкувати будь-якого дикого звіра, якого забажаєте.",al={"чи скорпід лишиться","чи я лишу вихованця","скорпід постійний"}},{q="Хто проводить цей обряд посвяти?",a="Тотар, наставник мисливців із Гострого Пагорба в центрі Дуротару, проводить цей обряд посвяти для молодих мисливців-орків і тролів.",al={"хто дає завдання","хто дає приборкання звіра","де тотар"}},{q="Чому Тотар хоче, щоб мисливці приборкали саме броньованого скорпіда?",a="Тотар вважає броньованого скорпіда взірцем для наслідування через його впевнені, стрімкі удари й природну витривалість. Підкоривши такого небезпечного хижака, мисливець доводить, що готовий керувати будь-яким диким звіром.",al={"чому скорпід","навіщо скорпід"}},{q="Яких умінь я навчуся, виконавши це завдання?",a="Це випробування дає основні вміння досвідченого володаря звірів: «Приборкати звіра», «Покликати вихованця» й «Відпустити вихованця».",al={"нагороди","які закляття я отримаю","відкриті навички приборкання"}},{q="Що буде після цього випробування?",a="Коли ви навчитеся приборкувати й кликати власного супутника, Тотар скерує вас тренувати вихованця й дасть наступне завдання — «Навчання звіра», щоб ви опанували, як годувати свого союзника й командувати ним.",al={"наступне завдання","що далі","після приборкання 3"}}},fp="16,359,15.484.0,21.523.0,47.128.0,63.215.0,35.136.0,69.220.0,52.122.0,28.207.0"}
P.entries["quest:6083"] = {n="Приборкання звіра",s="Друге випробування в обряді майстерності молодого мисливця в Дуротарі, яке доручає наставник Тотар у Гострому Пагорбі. Майбутніх мисливців-орків і тролів посилають на узбережжя біля Островів Відлуння приборкати прибійного краба — так їхній зв'язок виходить за межі суходільних звірів до прибережної живності.",h="Друге випробування в обряді майстерності молодого мисливця в Дуротарі, яке доручає наставник Тотар у Гострому...",kw={"мисливець","тотар","прибійний краб","приборкання","острови відлуння","узбережжя"},ang={["class:Hunter"]="Це випробування закладає основну дисципліну, потрібну, щоб керувати захисними звірами, і показує, як природний панцир і впертість створіння доповнюють стрільця.",["race:Orc"]="Для орків, що облаштовують постійний дім у Дуротарі, впокорення витривалої живності узбережжя підкріплює їхню владу над суворим краєм.",["race:Troll"]="Тролі Темного Списа добре знають води біля Островів Відлуння й Села Сен'джин, тож це випробування — зустріч зі знайомою живністю їхнього прибережного притулку."},sec={{t="Зв'язок із узбережжям",b="Упокоривши лютого плямистого вепра, мисливець-початківець дістає від Тотара нове завдання — звернути погляд до моря. Сувора природа Дуротару — це й зубчасті береги, і мілкі рифи, де кишать панцирні ракоподібні. Зустріч із прибійним крабом вимагає терпіння й стійкості, адже ці броньовані краби опираються кожному вторгненню в їхні прибережні володіння."},{t="Продовження волі",b="Тотар навчає, що кожен звір, якого прив'язує мисливець, має стати продовженням його власної сили. Упокорюючи жезлом приборкання водяне створіння, як-от прибійного краба, мисливець учиться поширювати свою владну присутність на різні вдачі й середовища, доводячи готовність до постійних супутників."}},faq={{q="Де водяться прибійні повзуни?",a="Прибійні повзуни снують уздовж східного узбережжя Дуротару, зокрема на мілинах навпроти Села Сен'джин, біля вод, що ведуть до Островів Відлуння.",al={"де прибійний повзун","місця прибійних повзунів","де краби"}},{q="Навіщо приборкувати прибійного повзуна?",a="Тотар доручає приборкати прибійного повзуна, щоб навчити мисливців керувати різними звірами. Опанувавши приборкання панцирної водяної істоти, мисливець розширює свою владу й доводить, що впорається з тваринами з води так само легко, як і з суходолу.",al={"навіщо приборкувати краба","мета завдання прибійного повзуна"}},{q="Чи залишиться прибійний повзун зі мною назавжди?",a="Ні. Звірі, приборкані під час цих перших випробувань, — лише тимчасові навчальні піддослідні, підкорені магією жезла приборкання Тотара. Тільки пройшовши всю низку випробувань, ви назавжди опануєте вміння приборкувати звірів.",al={"чи лишу краба","чи прибійний повзун постійний"}},{q="Хто дає це завдання?",a="Тотар, наставник мисливців із Гострого Пагорба, пропонує це випробування, після того як ви доведете, що здатні приборкати лютого плямистого вепра.",al={"хто дає завдання","хто починає приборкання звіра 2"}},{q="Що буде після приборкання прибійного повзуна?",a="Коли ви повернете жезл Тотарові, він дасть вам третє, останнє випробування — вистежити й приборкати Броньованого Скорпіда, — а тоді навчить вас володіти звірами назавжди.",al={"наступне завдання","що далі в ланцюжку"}},{q="Навіщо жезл приборкання, а не власні навички?",a="Мисливці-новачки ще не виплекали вродженої духовної влади, потрібної, щоб поєднатися з дикими звірами назавжди. Жезл приборкання слугує провідником, що дає змогу початківцям безпечно вчитися спрямовувати свою волю, перш ніж опанувати справжню техніку.",al={"навіщо жезл приборкання","що таке жезл приборкання"}}},fp="16,281,22.353.0,21.318.0,30.166.0,45.230.0,39.219.0,21.126.0,41.179.0,47.241.0"}
P.entries["quest:6084"] = {n="Приборкання звіра",s="Це завдання — друге випробування в посвяті дворфійського мисливця, яке дає Ґріф Вайлдгарт у Хараносі. Навчившись давати раду грубій витривалості скелястого вепра, юний мисливець має опанувати прудкість і смертоносну грацію тутешнього снігового леопарда.",h="Це завдання — друге випробування в посвяті дворфійського мисливця, яке дає Ґріф Вайлдгарт у Хараносі.",kw={"приборкання","леопард","мисливець","вайлдгарт","жезл","харанос"},ang={["class:Hunter"]="Цей обряд переходу вчить дворфійських мисливців-новачків різниці між витривалими улюбленцями на кшталт вепрів і прудкими, агресивними бійцями на кшталт котів.",["race:Dwarf"]="Горяни Каз Модану здавна ділять замерзлі вершини Дун Мороґу зі сніговими леопардами, поважаючи і їхню скрадливість, і смертоносну мисливську вправність."},sec={{t="Урок витонченості",b="Якщо скелясті вепри вчать горянина витримувати неприкриту лють і тримати удар, то Ґріф Вайлдгарт наголошує: справжній мисливець має розуміти різні стилі бою. Він показує учням на південний схід, де нишпорять снігові леопарди Дун Мороґу. Ґріф порівнює цих граційних хижаків із вишукано зробленою рушницею: зовні вражають, та під білосніжними шубами ховають нищівну силу."},{t="Опанування Жезла Приборкання",b="Зачарованим жезлом приборкання мисливець має зустріти дикого леопарда і повернути його мисливські інстинкти на партнерство. Снігові леопарди випробовують спритність, швидкість і гострі рефлекси, а не чисту витривалість. Опанувати такого звіра означає довести, що новачок здатен порозумітися з хижаками, які блискавично б'ють із засніжених скель, — і зробити ще один крок до справжньої влади над дикими звірами."}},faq={{q="Навіщо це завдання?",a="Це другий етап обряду посвяти мисливців-дворфів. Наставник мисливців Ґріф Вайлдгарт вимагає від учнів перевірити свої вміння на різних диких звірах, перш ніж дати їм знання, як назавжди поєднатися зі звірами-супутниками.",al={"навіщо це завдання","завдання снігового леопарда дворф","приборкання звіра 2"}},{q="Де знайти снігових леопардів?",a="Снігові леопарди скрадаються кам'янистими скелями й засніженими схилами на південь і схід від Хараноса в Дун Мороґу.",al={"де сніговий леопард","де сніжні леопарди дун мороґ","місця леопардів"}},{q="Навіщо Ґріф Вайлдгарт посилає приборкувати леопарда?",a="Ґріф вважає, що мисливець має відчути і грубу силу, і витончену спритність. Скелястий вепр покладається на кремезну витривалість, а сніговий леопард навчить мисливця битися пліч-о-пліч зі швидким, моторним і смертоносним бійцем.",al={"чому сніговий леопард","чому ґріф вайлдгарт посилає по леопарда"}},{q="Чи залишиться цей сніговий леопард зі мною назавжди?",a="Ні. Звірі, приборкані під час цих перших випробувань, — тимчасові навчальні напарники, прив'язані магією жезла приборкання. Коли наприкінці ланцюжка завдань Ґріф визнає ваше навчання завершеним, ви назавжди здобудете вміння приборкати будь-якого дикого звіра на свій вибір.",al={"чи лишу снігового леопарда","чи леопард постійний"}},{q="Хто призначає це випробування?",a="Ґріф Вайлдгарт, наставник мисливців-дворфів, що стоїть біля таверни в Хараносі, у Дун Мороґу.",al={"хто дає завдання","видавець завдання","роль ґріфа вайлдгарта"}},{q="Що далі в ланцюжку?",a="Коли ви доведете, що впоралися зі сніговим леопардом, Ґріф відправить вас на третє, останнє випробування — приборкати Ведмедя Крижаний Кіготь, — а тоді офіційно навчить приборкувати й тренувати диких звірів самостійно.",al={"наступне завдання","що після снігового леопарда"}}},fp="16,259,19.416.0,24.396.0,34.251.0,34.110.0,50.228.0,47.254.0,23.91.0,29.204.1"}
P.entries["quest:6085"] = {n="Приборкання звіра",s="Це завдання — останнє випробування в базовому вишколі дворфійського мисливця під проводом Ґріфа Вайлдгарта з Хараноса. Приборкавши зачарованим жезлом агресивного Ведмедя Крижаного Кігтя і зрозумівши його, мисливець доводить владу над чистою грубою силою. Виконання цієї вправи відкриває основні вміння, потрібні, щоб приборкати, покликати й відпустити постійного дикого супутника.",h="Це завдання — останнє випробування в базовому вишколі дворфійського мисливця під проводом Ґріфа Вайлдгарта з...",kw={"приборкання","ведмідь","крижаний кіготь","мисливець","вайлдгарт","жезл","харанос"},ang={["class:Hunter"]="Це завдання — обряд переходу, що перетворює самотнього лучника на справжнього мисливця-приборкувача й відкриває головні вміння приборкувати та прикликати звірів.",["race:Dwarf"]="Ведмеді здавна були знаковими супутниками дворфійських горян, що патрулюють Дун Мороґ, і славляться тим, що не поступаються господарям упертою стійкістю."},sec={{t="Сила дикої природи",b="По всьому Дун Мороґу горяни й розвідники здавна покладаються на витривалих звірів, щоб пережити крижані скелі. Після вправ на прудких і хитрих хижаках майстер-мисливець Ґріф Вайлдгарт ставить перед новачками останню ціль — Ведмідь Крижаний Кіготь. Ці величезні звірі, що нишпорять у снігових заметах на схід від Хараноса, втілюють грубу фізичну міць і невтомну витривалість — якості, які кожен дворфійський мисливець має навчитися підкоряти."},{t="Заслужити супутника",b="Випробування з Жезлом Приборкання — суто навчальні вправи, що показують мисливцям, як дикі інстинкти відгукуються на волю і спокійний намір. Щойно жезл утихомирює ведмедя, тимчасовий зв'язок виконує своє призначення. Повернення знаряддя Ґріфу завершує офіційні випробування, і майстер розкриває довічні таємниці володіння звірами: як умиротворити будь-яке придатне дике створіння і кликати його впродовж цілого життя пригод."}},faq={{q="Якого звіра треба приборкати в цьому завданні?",a="Вам треба розшукати Ведмедя Крижаний Кіготь, що никає замерзлими пагорбами на схід від Хараноса в Дун Мороґу. Жезл Приборкання, який вам дадуть, підкорить звіра, і ви відчуєте, як це — керувати неприборканою грубою силою.",al={"який ведмідь","цільова тварина","ціль приборкання"}},{q="Чи залишиться Ведмідь Крижаний Кіготь зі мною, коли я здам завдання?",a="Ні. Ведмідь, підкорений Жезлом Приборкання, — лише тимчасова перевірка дисципліни й уміння. Щойно ви повернете жезл Ґріфові Вайлдгарту, звір піде, а ви здобудете справжнє вміння приборкувати будь-якого дикого звіра на свій вибір.",al={"чи лишу ведмедя","лишити вихованця","чи ведмідь постійний"}},{q="Де знайти Ґріфа Вайлдгарта?",a="Ґріф Вайлдгарт стоїть біля Ґуральні Тандербрю в Хараносі, у Дун Мороґу, де навчає молодих мисливців стрільби й володіння звірами.",al={"де ґріф","де знайти ґріфа","наставник мисливців харанос"}},{q="Яких умінь я навчуся, пройшовши це випробування?",a="Це останнє випробування навчить вас основних заклинань мисливця: «Приборкати звіра», «Покликати вихованця» й «Відпустити вихованця». Тепер ви можете вирушити у світ і поєднатися з постійним супутником.",al={"нагороди завдання","навички мисливця","нагорода приборкання звіра"}},{q="Що робити після виконання цього завдання?",a="Ґріф відправить вас далі із завданням «Навчання звіра»: ви маєте навчитися як слід годувати, доглядати й навчати нового супутника, щоб він лишався відданим у бою.",al={"наступне завдання","що далі","навчання звіра"}},{q="Чому Ґріф змушує мисливців випробовувати кілька видів звірів?",a="Три випробування знайомлять мисливця-новачка з різними стилями бою — спритністю, хитрістю й грубою силою. Пізнавши ці різні вдачі, горянин зможе обрати найкращого супутника для свого способу полювання.",al={"чому три звіри","мета випробувань","три тварини"}}},fp="16,364,24.446.0,19.439.0,45.200.0,55.227.0,32.168.0,52.198.0,50.177.0,57.223.0"}
P.entries["quest:6086"] = {n="Навчання звіра",s="«Навчання звіра» — завершальний обряд переходу для молодих дворфійських мисливців у Дун Мороґу. Опанувавши мистецтво втихомирення й приборкання диких хижаків серед засніжених скель, слідопити-новачки вирушають у серце Айронфорджа, щоб навчитися годувати, вишколювати й доглядати довічного тваринного супутника.",h="«Навчання звіра» — завершальний обряд переходу для молодих дворфійських мисливців у Дун Мороґу.",kw={"навчання звіра","мисливець","тандерґраніт","зала зброї","айронфордж","супутник","улюбленець"},ang={["class:Hunter"]="Ця віха відкриває саму серцевину мисливського ремесла: уміння належно годувати постійного тваринного супутника, керувати ним і воскрешати його.",["faction:Alliance"]="Володарі звірів Айронфорджа — вагома частина розвідувальних сил Альянсу, що покладаються на вірних супутників із дикої природи, патрулюючи крижані гірські перевали.",["race:Dwarf"]="Дворфи бачать у полюванні давню традицію гірських нетрів Каз Модану й мають ведмедів, вепрів і гірських котів за шанованих партнерів у розвідці та обороні."},sec={{t="З дикої природи до Кузні",b="Довівши свою вправність на диких звірах Дун Мороґу — втихомиривши жезлом приборкання великих скелястих вепрів, снігових леопардів і міцних ведмедів Крижаних Кігтів, — учні-мисливці завершують випробування під пильним оком Ґріфа Вайлдгарта біля Хараноса. Та впіймати дике серце тварини — лише половина зв'язку. Ґріф посилає своїх загартованих вихованців гірським перевалом до Айронфорджа — знайти військовий квартал, відомий як Зала Зброї."},{t="Наука Белії Тандерґраніт",b="У кам'яних склепіннях Зали Зброї Айронфорджа стоїть Белія Тандерґраніт — одна з найшанованіших майстринь дресирування тварин у дворфійському королівстві. Белія передає найважливіше знання, яке перетворює дикого переляканого звіра на запекло відданого партнера. Її наука сягає далеко за прості команди: вона показує молодим мисливцям, як годувати улюбленців, навчати їх нових бойових умінь і навіть повертати їхні душі зі смерті, якщо ті поляжуть, боронячи господаря."},{t="Зв'язок дворфійського мисливця",b="Дворфійська традиція наголошує, що володіння звірами будується на повазі, а не на підкоренні. Белія нагадує кожному молодому мисливцю: тваринний супутник відображає турботу, яку отримує. Якщо звіра добре годувати, поважати й належно вишколювати, він відплатить непохитною відданістю проти трогів, морозних тролів і будь-якої загрози, що зазіхне на Каз Модан."}},faq={{q="Навіщо це завдання?",a="Це завдання — останній крок базового навчання мисливця-дворфа. Воно дає основні знання, потрібні, щоб утримувати постійного бойового вихованця: годувати його, розвивати його вміння, кликати до себе й воскрешати, якщо він загине.",al={"навіщо це завдання","мета навчання звіра","нагорода вихованця мисливця"}},{q="Хто така Белія Тандерґраніт?",a="Белія Тандерґраніт — шанована майстриня-дресирувальниця звірів у Залі Зброї Айронфорджа. Вона старша наставниця дворфійських слідопитів: учить їх дисципліни, харчування звірів і команд, потрібних, щоб приборкані дикі тварини стали союзниками на все життя.",al={"хто така белія","переказ про белію тандерґраніт","наставниця мисливців айронфорд"}},{q="Де знайти Белію Тандерґраніт?",a="Белія Тандерґраніт перебуває в Айронфорджі, у Залі Зброї — військовому крилі міста, де збираються й тренуються воїни, мисливці й паладини з дворфів і гномів.",al={"де белія","де белія тандерґраніт","де зала зброї айронфорд"}},{q="Яких звірів приборкують мисливці-дворфи перед цим навчанням?",a="Під час попередніх випробувань Ґріф Вайлдгарт перевіряє молодих мисливців: вони мають зачарованим жезлом тимчасово угамувати великого скелястого вепра, снігового леопарда й ведмедя Крижаний Кіготь у Дун Мороґу.",al={"яких звірів приборкують","випробування вихованців дворфа","звірі з попередніх завдань"}},{q="Чому мисливці-дворфи мусять годувати своїх вихованців?",a="За звіриною наукою дворфів, тварини-супутники — напарники, а не знаряддя. Якщо не дбати про голод звіра, його настрій псується, а охота битися згасає; ситий же звір запекло відданий і в бою якнайдієвіший.",al={"навіщо годувати вихованця","переказ про задоволеність вихованця","вірність звіра дворфа"}},{q="Хто дає це завдання?",a="Ґріф Вайлдгарт, досвідчений наставник мисливців, що стоїть край дороги на схід від Хараноса в Дун Мороґу, дає це завдання, коли ви успішно пройдете третє випробування з приборкання.",al={"хто починає навчання звіра","роль ґріфа вайлдгарта","хто дає завдання"}}},fp="18,311,26.447.0,32.466.0,25.360.0,34.249.0,28.258.0,37.166.0,67.211.0,41.254.0,21.184.0"}
P.entries["quest:6087"] = {n="Приборкання звіра",s="Це випробування — другий ступінь посвяти мисливця-таурена в мистецтво приборкання звірів. Під проводом наставника мисливців Ява Шарпмейна в Селі Бладгуф новачок має підкорити швидкого й безстрашного степового переслідувача.",h="Це випробування — другий ступінь посвяти мисливця-таурена в мистецтво приборкання звірів.",kw={"приборкання","степовий переслідувач","вовк","яв шарпмейн","село бладгуф","малгор","мисливець"},ang={["class:Hunter"]="Цей обряд посвяти поєднує основи виживання з наступальною злагодженістю і вчить вас битися пліч-о-пліч зі стрімким супутником.",["race:Tauren"]="На відміну від культур, де улюбленців мають лише за робочу худобу, шу'хало бачать у приборканні звіра кування священної спорідненості під пильною ласкою Земної Матері."},sec={{t="Уроки переслідувача",b="Коли молодий мисливець опанував оборонну витривалість дорослого довгоступа, Яв Шарпмейн кидає йому виклик: дивитися далі простого виживання. Степовий переслідувач утілює зовсім іншу філософію полювання — невпинну швидкість, злагодженість зграї та безстрашний натиск. Щоб приборкати такого, треба підійти до хитрого хижака, не збившись із кроку, віддзеркаливши рішучу вдачу самого вовка."},{t="Пліч-о-пліч",b="Для тауренів полювання разом зі звіром ніколи не було ні рабством, ні грубим підкоренням. Яв Шарпмейн наголошує: мисливець і хижак мають битися як одне ціле, пов'язані взаємною повагою та спільним ритмом. Зріднившись зі степовим переслідувачем під відкритим небом Малгору, мисливець учиться доповнювати натиск партнера й рухатися з ним у лад у розпал бою."}},faq={{q="Якого звіра Яв Шарпмейн просить приборкати в цьому випробуванні?",a="Цей другий урок вимагає приборкати степового скрадача — одного з прудких вовків, що никають хвилястими рівнинами Малгора.",al={"якого звіра приборкати","який вихованець наступний","приборкати степового скрадача"}},{q="Чому мисливець-таурен учиться приборкувати вовків?",a="Яв Шарпмейн навчає, що степовий скрадач уособлює швидкість і безстрашність. Поєднавшись із таким хижаком, мисливець переймає саме ці риси й учиться злагоджено атакувати разом зі спритним напарником на полюванні.",al={"чому вовки","переказ про степового скрадача","навіщо приборкувати вовка"}},{q="Де зазвичай водяться степові скрадачі?",a="Степові скрадачі блукають трав'янистими рівнинами центрального й північного Малгора й часто полюють у преріях довкола Села Бладгуф.",al={"де степовий скрадач","де степові скрадачі","знайти степового скрадача"}},{q="Чи залишиться степовий скрадач зі мною після завдання?",a="Ні. Жезл приборкання створює лише тимчасовий зв'язок для навчання. Коли ви пройдете всю низку випробувань, то назавжди здобудете вміння приборкувати будь-якого дикого супутника на свій вибір.",al={"чи лишу вовка","лишити степового скрадача","чи це мій постійний вихованець"}},{q="Хто такий Яв Шарпмейн?",a="Яв Шарпмейн — місцевий наставник мисливців у Селі Бладгуф. Він веде молодих тауренів через духовні й практичні рубежі, які треба подолати, щоб опанувати дику природу Малгора.",al={"хто такий яв","переказ про шарпмейна","яв кривавий копит"}},{q="Що буде після приборкання степового скрадача?",a="Коли Яв Шарпмейн переконається, що ви впоралися з вовком, він відправить вас на третє, останнє випробування ланцюжка — перевірити свою рішучість на потайливому стрімкокрилі.",al={"наступне завдання","що після степового скрадача","третє завдання приборкання"}}},fp="16,233,21.405.0,16.376.0,60.124.0,46.237.0,44.136.0,53.198.0,21.187.0,44.173.0"}
P.entries["quest:6088"] = {n="Приборкання звіра",s="Це випробування — останній урок молодого мисливця-таурена в навчанні у Ява Шарпмейна в Селі Бладгуф. Зріднившись за допомогою жезла приборкання з диким стрімкокрилом, мисливець доводить владу над створіннями повітря й здобуває священну довіру Земної Матері. Виконання цього завдання дарує тривке знання, потрібне, щоб приборкати довічного супутника й керувати ним.",h="Це випробування — останній урок молодого мисливця-таурена в навчанні у Ява Шарпмейна в Селі Бладгуф.",kw={"приборкання","стрімкокрил","яв шарпмейн","село бладгуф","малгор","мисливець","жезл приборкання"},ang={["class:Hunter"]="Це завдання завершує ланцюжок основного навчання, що відкриває постійне приборкання звірів, і позначає перехід від учня до цілком самостійного розвідника дикого краю.",["race:Tauren"]="Для шу'хало зріднення з диким звіром — акт духовного єднання, благословенний Земною Матір'ю, і воно має глибоке культурне значення на всіх рівнинах Малгору."},sec={{t="Влада над небом",b="Коли наземних хижаків пагорбистих рівнин Малгору вже підкорено, Яв Шарпмейн звертає вашу увагу до відкритого неба. Стрімкокрил — лютий гостродзьобий хижий птах, відомий розмашистими піке й грізною поставою. Узяти під владу такого дикого крилатого мисливця — випробування для ваших рефлексів і спокою: доведеться витерпіти його кігті, зачарованим жезлом настроюючи свій дух на його інстинкти."},{t="Дар Земної Матері",b="Для тауренів полювання й дружба з тваринами — передусім духовний шлях, а не просте підкорення. Опанувавши створіння і землі, і неба, ви засвідчуєте рівновагу й повагу, потрібні, щоб ходити рівнинами, не порушуючи природи. Яв Шарпмейн визнає цю зрілість: забирає свій тимчасовий жезл приборкання й передає вам тривкі вміння — кликати, відпускати й назавжди приборкувати супутника на власний вибір."}},faq={{q="Чому для останнього випробування треба приборкати стрімкокрила?",a="Яв Шарпмейн хоче перевірити, як ви впораєтеся з істотами, що живуть у небі. Стрімкокрили атакують гостро й стрімко та мають грізний вигляд; приборкавши такого птаха, мисливець доводить, що дасть раду і з повітряними хижаками, і з наземними звірами, а отже, заслуговує на справжню самостійність.",al={"чому приборкати стрімкокрила","мета приборкання стрімкокрила","чому стрімкокрил"}},{q="Чи залишиться стрімкокрил, якого я приборкаю, зі мною?",a="Ні. Стрімкокрила приборкують тимчасово, жезлом приборкання Ява Шарпмейна, у межах обрядового навчання. Виконавши завдання, ви здобудете справжнє вміння приборкувати будь-якого дикого звіра, якого захочете залишити назавжди.",al={"чи лишу стрімкокрила","чи стрімкокрил мій вихованець","чи можна лишити птаха"}},{q="Хто дає це завдання і де його знайти?",a="Яв Шарпмейн, наставник мисливців у Селі Бладгуф у центрі Малгора, пропонує це завдання як третій і останній крок перших випробувань із приборкання звірів.",al={"хто дає завдання","хто починає це","де яв шарпмейн"}},{q="Що буде, коли я поверну жезл приборкання?",a="Яв Шарпмейн навчить вас власних умінь приборкувати, кликати й відпускати звірів. А ще він скерує вас до Тандер Блафа, щоб ви навчилися як слід тренувати обраного супутника й дбати про нього.",al={"чого я навчуся далі","нагороди за завершення","що після цього завдання"}},{q="Де в Малгорі знайти диких стрімкокрилів?",a="Стрімкокрили кружляють над відкритими луками й краями столових гір по всьому центральному Малгору, часто просто над рівнинами за Селом Бладгуф.",al={"місця стрімкокрилів","де стрімкокрили","знайти стрімкокрила"}},{q="Чому приборкання вихованця вважається в тауренів обрядом посвяти?",a="Таурени бачать у звірах не знаряддя, а таких самих дітей Земної Матері. Щоб поєднатися із супутником, потрібні терпіння, взаємна повага й духовна рівновага, а не сама лише сила.",al={"переказ про мисливців-тауренів","духовний шлях мисливця","зв'язок із землею-матір'ю"}}},fp="16,362,18.438.0,22.453.0,50.249.0,45.209.0,48.161.0,43.207.0,40.132.0,58.199.0"}
P.entries["quest:6089"] = {n="Навчання звіра",s="«Навчання звіра» — завершальний обряд посвяти для молодих мисливців-тауренів у Малгорі. Довівши духовне терпіння й рішучість, потрібні, щоб угамувати диких звірів рівнин, мисливці вирушають до Тандер Блафа опановувати довічну науку: ріднитися з постійним тваринним супутником, годувати його й керувати ним.",h="«Навчання звіра» — завершальний обряд посвяти для молодих мисливців-тауренів у Малгорі.",kw={"навчання звіра","голт тандергорн","узвишшя мисливців","тандер блаф","яв шарпмейн","мисливець","супутник"},ang={["class:Hunter"]="Цей обряд позначає перехід від самотньої боротьби до бою поруч із вірним супутником і завершує ваше основне навчання як охоронця дикого краю.",["race:Tauren"]="Для шу'хало взяти тваринного супутника в бій — священний обов'язок опіки та поваги до творінь Земної Матері."},sec={{t="Шлях до Великого Бескиду",b="Випробувавши свій дух проти небезпечних хижаків Малгору — довгоступів, степових переслідувачів і стрімкокрилів, — мисливці-таурени визнаються гідними справжнього мисливського звання. Яв Шарпмейн, наставник із Села Бладгуф, доручає новачкові подорож на Узвишшя Мисливців у Тандер Блафі. Там стоїть Голт Тандергорн — легендарна постать серед шу'хало, чия слава в єднанні з дикою природою поступається лише його шані до Земної Матері."},{t="Священний зв'язок",b="Для тауренів звір — не проста зброя і не невільник, а партнер, дарований через гармонію з природним світом. Голт Тандергорн передає знання, конче потрібні, щоб підтримувати це партнерство. Мисливець має навчитися не лише спрямовувати бойові інстинкти створіння, а й живити його тіло регулярним годуванням, гоїти його рани й кликати його дух назад, якщо воно впаде, захищаючи свого товариша на рівнинах."}},faq={{q="З ким говорити для цього завдання?",a="Вам треба поговорити з Голтом Тандергорном, майстром-мисливцем на Узвишші Мисливців у Тандер Блафі. Яв Шарпмейн скеровує вас до нього, щойно ви завершите перші випробування з приборкання диких звірів у Малгорі.",al={"здати завдання","хто такий голт тандергорн","де голт"}},{q="Чого вчаться мисливці-таурени, виконавши це завдання?",a="Голт Тандергорн навчає, як тренувати вихованця новим умінням, як годувати супутника, щоб він лишався відданим і задоволеним, і як оживити вихованця, якщо той загине в бою.",al={"які здібності я отримаю","навички з нагороди","чого навчає голт"}},{q="Яке місце це завдання посідає в ланцюжку мисливців-тауренів?",a="Це останнє завдання низки. Воно йде після «Шляху мисливця» і трьох випробувань «Приборкання звіра», під час яких мисливець тимчасово угамовує дорослого рівнинного довгоступа, степового скрадача й стрімкокрила на рівнинах.",al={"ланцюжок мисливців","завдання вихованця мулґор","ланцюжок навчання звіра"}},{q="Чому Голт Тандергорн такий шанований серед мисливців-тауренів?",a="Голт усе життя випробовував себе в сутичках із найлютішими звірами Азероту, керуючи кількома могутніми супутниками й зберігаючи глибокий духовний зв'язок із Земною Матір'ю. Завдяки своїй мудрості він головний наставник молодих мисливців-шу'гало в Тандер Блафі.",al={"переказ про голта тандергорна","хто такий голт"}},{q="Чи можна приборкати постійного вихованця, ще не здавши це завдання?",a="Уміння приборкувати диких звірів ви вже маєте після попереднього випробування, але поки не поговорите з Голтом Тандергорном, не знатимете, як годувати, оживляти чи навчати вмінь обраного супутника.",al={"чи можна приборкати вихованця зараз","коли я отримаю вихованця","чи потрібне навчання звіра"}},{q="Чому в культурі тауренів догляд за вихованцем пов'язаний із Земною Матір'ю?",a="Таурени вважають усіх живих істот дітьми Земної Матері. Мисливець не підкоряє звіра самою силою волі, а укладає з ним духовний союз: мисливець дає їжу й турботу, а тварина натомість — відданість і захист.",al={"переказ про вихованців таурена","земна матір і звірі"}}},fp="18,336,27.484.0,13.429.0,33.201.0,63.180.0,53.226.0,71.272.0,66.194.0,58.257.0"}
P.entries["quest:61"] = {n="Посилка до Стормвінда",s="«Посилка до Стормвінда» — кур'єрське завдання Альянсу, що завершує свічкову справу Вільяма Пестла в Лісі Елвінн. Зібравши великі воскові свічки в місцевих кобольдів, шукачі пригод несуть запаковану посилку дорогою до Торгового Кварталу Стормвінда — братові Вільяма, Морґану Пестлу.",h="«Посилка до Стормвінда» — кур'єрське завдання Альянсу, що завершує свічкову справу Вільяма Пестла в Лісі...",kw={"посилка до стормвінда","вільям пестл","морґан пестл","свічки","ґолдшир","торговий квартал"},ang={["faction:Alliance"]="Нести припаси королівським трактом до Стормвінда — класичний обряд посвяти для молодих героїв Альянсу, що переходять від сільських сутичок до гамірної столиці.",["profession:Herbalism"]="Родинна справа Пестлів тісно пов'язана з місцевими реагентами Елвінну, тож зазирнути до їхньої стормвіндської крамниці — звична річ і для збирачів трав, і для зіллєварів."},sec={{t="Родинна справа",b="Брати Пестли ведуть алхімічну торгівлю між сільськими селищами Лісу Елвінн і гамірними вулицями Стормвінда. Вільям збирає трави, реагенти й сировину в Ґолдширі, а його брат Морґан тримає «Аптеку Пестла» в Торговому Кварталі столиці. Вільяму нелегко покинути свій пост у Корчмі «Лев'яча Гордість», тож він покладається на мандрівників, що прямують до міської брами, аби ті побули кур'єрами."},{t="Від кобольдського воску до столичних зіль",b="У пакунку Вільяма — великі свічки, зібрані в кобольдів із копалень Елвінну. Він і Морґан тримають аптеку в Стормвінді, і Вільям каже, що збирає свічки заради воску. З доставленою посилкою ці припаси потрапляють до Морґана в Торговий Квартал."}},faq={{q="Що в посилці Вільяма?",a="У посилці — свічки, зібрані в кобольдів у Лісі Елвінн. Вільям збирав їх заради воску й запакував для Морґана в «Аптеку Пестла».",al={"вміст посилки","що в посилці","що надіслав вільям"}},{q="Де знайти Морґана Пестла?",a="Морґан Пестл працює в Аптекарні Пестла, що в Торговому Кварталі Стормвінда, за кілька кроків від головної брами.",al={"де морґан пестл","де морґан","знайти морґана пестла"}},{q="Ким доводяться одне одному Вільям і Морґан Пестл?",a="Вільям і Морґан Пестл — брати, які разом ведуть алхімічну справу. Вільям добуває матеріали в Лісі Елвінн, а Морґан порядкує в їхній крамниці в Стормвінді.",al={"брати пестли","хто брат вільяма пестла"}},{q="Чому Вільям не доставить посилку сам?",a="Вільям по вуха в торгівлі й зборі алхімічних інгредієнтів у Ґолдширі. Він воліє наймати мандрівних шукачів пригод, які й так прямують на північ, до брами столиці.",al={"чому вільям не йде до стормвінда","чому найняти гінця"}},{q="Чи справді кобольдячі свічки придатні для алхімії?",a="Вільям каже, що їм із братом свічки потрібні заради воску. Як саме віск використовують в аптеці, завдання не описує.",al={"навіщо кобольдські свічки","кобольдський віск алхімія"}},{q="Що буде після доставки посилки?",a="Ця доставка завершує короткий ланцюжок, що почався зі збору кобольдячих свічок у Лісі Елвінн. Морґан просто платить вам за кур'єрську роботу й запрошує заходити до його крамниці.",al={"що далі після посилки до стормвінда","продовження посилки до стормвінда"}}},fp="21,306,14.433.0,34.261.0,34.157.0,30.135.0,42.172.0,48.189.0,48.143.0,41.182.0"}
P.entries["quest:6101"] = {n="Приборкання звіра",s="Це випробування — другий етап навчання мисливця нічних ельфів приборкувати звірів під проводом Дазалара в Доланаарі. Мисливцям доручають упокорити зачарованим жезлом приборкання нічного шаблезуба-переслідувача, щоб краще відчути мінливе розмаїття диких звірів. Так міцніє порозуміння між дикою природою Тельдрассила й слідопитами-вартовими, що ходять під її гіллям.",h="Це випробування — другий етап навчання мисливця нічних ельфів приборкувати звірів під проводом Дазалара в...",kw={"приборкання звіра","мисливець","дазалар","нічний шаблезуб","переслідувач","доланаар"},ang={["class:Hunter"]="Цей обряд — серцевина науки мисливця: ви вчитеся поважати різні звірині вдачі, перш ніж вам довірять супутника на все життя.",["race:NightElf"]="Нічні шаблезуби глибоко вплетені в історію й культуру калдорей, тож приборкання переслідувача — традиційна віха для місцевих лісових розвідників."},sec={{t="Мінлива природа звірів",b="Перші уроки зосереджені на розумінні основних інстинктів, та Дазалар наголошує: єдина сталість природи — її безнастанна мінливість. Кожен лісовий вид має власну вдачу, і мисливець мусить навчитися відповідно підлаштовувати свою волю. У тіні крони Тельдрассила це означає мати справу зі створіннями хитрими, потайними й куди більш хижими, ніж прості павуки-прядильники."},{t="Упокорення нічного шаблезуба",b="Нічні шаблезуби шановані калдореями як священні хижаки, люті охоронці й потайні супутники Вартових. Для мисливця-новачка спрямувати силу жезла приборкання на нічного шаблезуба-переслідувача означає мати міцні нерви й спокійну владність. Обернувши хижу агресію переслідувача на прихильний зв'язок, мисливець доводить, що здатен владарювати не лише над сумирними чи меншими створіннями лісу."}},faq={{q="Навіщо це завдання?",a="Це проміжне випробування в ланцюжку мисливців нічних ельфів, що відкриває постійне приборкання звірів. Дазалар посилає вас приборкати Скрадливого Нічного Шаблезуба, щоб ви побачили, як відрізняється вдача різних хижаків.",al={"навіщо це завдання","приборкання вихованця 2","мета приборкання нічного шаблезуба"}},{q="Де водяться скрадливі нічні шаблезуби?",a="Скрадливі нічні шаблезуби никають лісовими стежками й підліском на південь від Доланаару, у центрі Тельдрассилу.",al={"де скрадливі шаблезуби","місця скрадачів","де знайти кота"}},{q="Чи залишиться скрадливий нічний шаблезуб моїм постійним вихованцем?",a="Ні. Звір, приборканий жезлом, тимчасовий і слугує лише для практики. Коли ви пройдете всі три випробування й повернете жезл, то навчитеся справжнього приборкання й зможете обрати постійного супутника.",al={"чи лишу нічного шаблезуба","чи можна лишити нічного шаблезуба","чи це мій вихованець назавжди"}},{q="Хто дає це завдання?",a="Дазалар, наставник мисливців у Доланаарі на Тельдрассилі, дає це доручення після того, як ви пройдете перше випробування з приборкання.",al={"хто дає завдання","хто починає це","де дазалар"}},{q="Чому нічні ельфи так глибоко шанують нічних шаблезубів?",a="Нічні шаблезуби тисячоліттями живуть поруч із калдореями як супутники, розвідники й бойові скакуни Вартових і жриць Елуни. Приборкати такого звіра — гордий знак калдорейської майстерності в лісовій справі.",al={"переказ про котів нічних ельфів","чому нічні шаблезуби важливі","лор про нічних шаблезубів"}},{q="Що буде після виконання цього доручення?",a="Дазалар дасть останнє завдання — приборкати ще одну істоту Тельдрассилу, — а тоді навчить природного вміння приборкувати, годувати й доглядати постійних звірів-супутників по всьому Азероту.",al={"наступне завдання","що після скрадливого шаблезуба","наступне випробування мисливця"}}},fp="16,377,29.399.0,23.418.0,34.227.0,39.105.0,60.230.0,21.140.0,48.213.0,38.180.0"}
P.entries["quest:6102"] = {n="Приборкання звіра",s="Це завдання — останнє випробування базового вишколу юного мисливця нічних ельфів. Під проводом Дазалара з Доланаара мисливці мають приборкати хижу сову небес, перш ніж здобути право обрати собі справжнього супутника на все життя.",h="Це завдання — останнє випробування базового вишколу юного мисливця нічних ельфів.",kw={"приборкання звіра","мисливець","дазалар","верескун-стригід","сова","жезл приборкання","доланаар"},ang={["class:Hunter"]="Цей обряд переходу — поріг, за яким мисливець перестає битися сам і укладає довічне партнерство з диким супутником.",["race:NightElf"]="Приборкання корінної живності Тельдрассила відображає шлях калдорей — іти в злагоді з природою, а не гнути її силою."},sec={{t="Влада над кронами",b="Перш ніж завершити початкову науку звірознавства, мисливці нічних ельфів мають досягти злагоди зі створіннями з кожного куточка екосистеми Тельдрассила. Мисливець уже довів свою волю проти звірів підліска, тож тепер Дазалар доручає йому впокорити дух небес; його ціль — Верескун-стригід. Ці пильні хижі птахи гніздяться високо в гіллі на захід від Доланаара, і щоб утихомирити їх зачарованим Жезлом Приборкання, потрібні терпіння й міцні нерви."},{t="Зв'язок мисливця",b="Успіх із Верескуном-стригідом завершує давні уроки єднання мисливців калдорей із природою. Повернувши Дазаларові спорожнілий жезл, учень лишає позаду тренувальні вправи й здобуває повне мистецтво кликати, відпускати й назавжди приборкувати обраних звірів по всьому Азероту."}},faq={{q="Де водяться Верескуни-стригіди?",a="Верескуни-стригіди гніздяться в лісах на захід від Доланаару. Мисливці мають розшукати цих хижих птахів серед крон і коріння довкола поселення, щоб випробувати свій жезл.",al={"де верескуни","де стригід верескун","де сови"}},{q="Хто такий Дазалар?",a="Дазалар — наставник мисливців нічних ельфів у Доланаарі. Він опікується молодими калдореями, які вже опанували основи стрільби з лука й вистежування, і випробовує їх на наземних і небесних звірах, перш ніж дарувати вміння поєднатися зі справжнім звіром-супутником.",al={"роль дазалара","хто навчає приборкання в доланаарі","наставник мисливців доланаар"}},{q="Чи залишиться Верескун-стригід моїм вихованцем?",a="Ні. Верескуни, приборкані під час цього випробування, — тимчасові піддослідні, яких тримає лише магія Жезла Приборкання. Коли випробування здано, жезл повертають, а мисливця вчать приборкувати в дикій природі постійного супутника на власний вибір.",al={"лишити сову","чи верескун постійний","чи лишу цього вихованця"}},{q="Що буде після цього випробування?",a="Дазалар назавжди відкриває вам уміння приборкувати, кликати й відпускати звірів. А ще він скеровує вас на подальше навчання до Дарнасуса — опанувати важливе мистецтво годувати супутника й навчати його в бою.",al={"що далі","після приборкання звіра","кінець завдання вихованця мисливця"}},{q="Чому нічні ельфи приборкують саме сов?",a="Хижі птахи, як-от сови, мають для калдореїв глибоке культурне значення: це пильні нічні мисливці й надійні розвідники. Підкоривши небесну істоту, мисливець доводить, що розуміється на повітряних хижаках так само, як і на наземних звірах.",al={"переказ про сов нічних ельфів","чому сови","чим важливий стригід верескун"}},{q="Чи можуть мисливці після цього завдання обрати будь-якого звіра?",a="Так. Щойно Дазалар навчить постійного приборкання, мисливець вільний шукати будь-якого звіра, якого можна приборкати, — на суші, у воді чи в небі, на Тельдрассилі й далеко за ним.",al={"яких вихованців я можу отримати","вибір першого вихованця","чи можна приборкати будь-якого звіра"}}},fp="16,234,21.463.0,15.320.0,35.165.0,15.244.0,49.250.0,41.205.0,42.245.0,47.160.0"}
P.entries["quest:6103"] = {n="Навчання звіра",s="«Навчання звіра» — завершальний обряд переходу для мисливців-початківців нічних ельфів у Тельдрассилі. Довівши свою майстерність приборканням диких звірів на гіллі, мисливці вирушають до Дарнасуса — вчитися глибших мистецтв догляду й дисципліни улюбленця в Джокасте.",h="«Навчання звіра» — завершальний обряд переходу для мисливців-початківців нічних ельфів у Тельдрассилі.",kw={"навчання звіра","мисливець","джокасте","дазалар","ценаріонський анклав","дарнасус"},ang={["class:Hunter"]="Цей обряд знаменує ваш випуск із новачків-слідопитів у справжні володарі звірів: ви здобуваєте змогу навчати, годувати й оживляти свого супутника.",["race:NightElf"]="Традиція калдорей товаришувати зі звірами будується на повазі й співіснуванні, відображаючи вчення, передані через Дарнасус і Ценаріонський Анклав."},sec={{t="Обряд переходу мисливця",b="Перш ніж мисливець нічних ельфів зможе блукати Калімдором із вірним супутником поруч, йому треба опанувати більше, ніж жезл приборкання. Упокорення дикого створіння доводить базову силу й волю, та ненавчений звір лишається непередбачуваним тягарем. Щойно посвячений показує свої здібності в хащах довкола Доланаара, Дазалар скеровує його вглиб, до Дарнасуса, щоб завершити навчання."},{t="Настанови в Ценаріонському Анклаві",b="У тихих гаях Ценаріонського Анклаву шанована мисливиця Джокасте передає основні мистецтва товариства зі звіром. Вона вчить молодого мисливця, як належно годувати улюбленця, воскрешати його, коли станеться лихо, і плекати його бойові інстинкти тренуванням. Для нічних ельфів ці стосунки вкорінені в глибокій шанобі до природи, а не в простому пануванні."}},faq={{q="Навіщо це завдання?",a="Це завдання завершує перший ланцюжок про вихованців для мисливців нічних ельфів. Воно скеровує вас до Дарнасуса, де ви опануєте основні вміння, потрібні, щоб доглядати й тренувати постійного звіра-супутника.",al={"навіщо це завдання","завдання навчання вихованця нічного ельфа","що дає навчання звіра"}},{q="Де знайти Джокасте?",a="Джокасте мешкає в Дарнасусі, у Ценаріонському Анклаві, що ховається серед велетенських дерев і мисливських осель у північно-західній частині столиці.",al={"де джокасте","місце джокасте","знайти джокасте"}},{q="Хто дає це завдання?",a="Дазалар, наставник мисливців у Доланаарі, пропонує це завдання, коли ви пройдете всі три етапи випробувань із приборкання на Тельдрассилі.",al={"хто дає завдання","хто дає навчання звіра","де дазалар"}},{q="Чого навчає Джокасте?",a="Розмова з Джокасте відкриває основи володіння звірами: як годувати супутника, оживляти його, якщо він полягне в бою, і навчати нових умінь.",al={"які здібності я отримаю","нагороди джокасте","закляття вихованця мисливця"}},{q="Чому нічні ельфи приділяють стільки уваги навчанню вихованців?",a="Мисливці-калдореї вважають своїх вихованців напарниками, а не слухняними знаряддями. Належне навчання й турбота віддзеркалюють головну філософію раси — жити в рівновазі з природою й у благоговінні перед нею.",al={"переказ про мисливців нічних ельфів","чому нічні ельфи навчають звірів"}},{q="Чи доступне це завдання іншим расам?",a="Саме ця подорож до Дарнасуса — лише для мисливців нічних ельфів. Мисливці інших рас проходять рівноцінні обряди навчання у власних расових наставників.",al={"чи дворфи можуть це зробити","чи орда може навчання звіра"}}},fp="18,265,26.403.0,32.383.0,34.188.0,24.149.0,21.135.0,38.161.0,50.175.0,39.151.0"}
P.entries["quest:6121"] = {n="Нові уроки",s="«Нові уроки» — завдання посвяти, яке Матренґіл Берволкер у Дарнасусі дає друїдам Альянсу, що набираються досвіду. Воно скеровує посвячуваних до священного прихистку Місячного Гаю, щоб зустрітися з Дендритом Старблейзом і почати вчитися мистецтва очищення від отрут.",h="«Нові уроки» — завдання посвяти, яке Матренґіл Берволкер у Дарнасусі дає друїдам Альянсу, що набираються...",kw={"нові уроки","матренґіл берволкер","дендрит старблейз","нічний притулок","обердайн","отрута","друїд"},ang={["class:Druid"]="Цей обряд посвяти знаменує ваш перехід від простої зміни подоби й виживання до справжньої опіки над дикою природою: ви вчитеся знімати з неї смертельні пошесті й отрути.",["faction:Alliance"]="Криза, що загрожує Обердайну, показує, наскільки важлива допомога друїдів для захисту хитких північних поселень Альянсу на Темному Узбережжі.",["race:NightElf"]="Це завдання від Ценаріонського Анклаву Дарнасуса безпосередньо пов'язує молодих калдореїв із глибшими обов'язками предків у Місячному Гаю й на Темному Узбережжі."},sec={{t="Дар Кенарія",b="Друїди мають священний зв'язок із живим світом, успадкований через учення й благословення напівбога Кенарія. Серед цих дарів — сила одним простим закляттям очищати від мерзенних отрут. Та такі могутні дари ніколи не дають посвячуваним легковажно. Щоб по-справжньому шанувати дивовижну легкість свого чародійства, молоді друїди мусять спершу зрозуміти, якої виснажливої буденної праці вимагає боротьба з отрутами без прямого втручання природи."},{t="Виклик до Нічного Притулку",b="Матренґіл Берволкер, наставник друїдів у Ценаріонському Анклаві Дарнасуса, велить учневі не вправлятися на місці, а вирушити просто до Місячного Гаю. Там, у тихому селищі Нічний Притулок, Дендрит Старблейз керує ширшими справами Кола Кенарія й готовий доручити новачкові нагальне практичне завдання."},{t="Справжня криза",b="Прибувши до Нічного Притулку, посвячувані дізнаються, що їхнє випробування — не влаштований іспит і не розписаний обряд. Поселення Обердайн на Темному Узбережжі потерпає від хвилі отруєнь тварин, яку місцеві не в змозі зупинити. Дендрит Старблейз доручає новачкові розібратися й допомогти Темному Узбережжю — і кидає його просто в справжню кризу, де на кону життя."}},faq={{q="Хто дає завдання «Нові уроки»?",a="Завдання дає Матренґіл Берволкер, наставник друїдів нічних ельфів у Ценаріонському Анклаві в Дарнасусі.",al={"хто дає нові уроки","хто видає нові уроки","завдання матренґіла берволкера"}},{q="Куди треба вирушити, щоб виконати це завдання?",a="Вам треба дістатися священного друїдського краю — Місячного Гаю — і доповісти Дендритові Старблейзу, який перебуває в мирному поселенні Нічний Притулок.",al={"куди йти","де дендрит старблейз","здати нові уроки"}},{q="Чому друїди спершу мусять навчитися лікувати отруєння, як звичайні люди?",a="Наставники-друїди вважають, що дивовижний дар Кенарія — зцілювати від отрути простим заклинанням — може породити самовдоволення. Змушуючи учнів спершу долати отруєння травами й буденними засобами, вони дбають, щоб друїд по-справжньому шанував тягар і страждання, яких завдає отрута.",al={"чому друїди як звичайні люди","чому лікувати отруєння без магії","урок кенарія про отруту"}},{q="Що за біда в Обердайні?",a="Обердайн потерпає від спалаху тяжких отруєнь тварин на всьому узбережжі Темного Узбережжя. Місцеві нічні ельфи не змогли зцілити цю недугу, тож надіслали прохання про допомогу до Кола Кенарія в Місячному Гаю.",al={"отруєння в оберіжині","що відбувається в оберіжині","отруєння тварин темного узбережжя"}},{q="Якого вміння зрештою навчає цей ланцюжок завдань?",a="Це завдання відкриває ланцюжок «Влада над отрутою», що навчає друїдів важливого заклинання «Зцілення від отрути», яке дає змогу магією очищати союзників від токсинів.",al={"яку нагороду я отримаю","завдання зцілення від отрути","ланцюжок влади над отрутою"}},{q="Чи доступне це завдання друїдам Орди?",a="Ні. «Нові уроки» — це саме альянсівська версія завдання, що починається в Дарнасусі. Друїди-таурени отримують схоже завдання в Тандер Блафі, яке так само скеровує їх до Місячного Гаю вчитися зцілювати від отрути.",al={"нові уроки орда","чи таурени можуть це взяти","нові уроки таурен"}}},fp="12,273,20.462.0,21.348.0,19.409.1,34.120.0,45.147.0,58.296.0,42.236.0,52.157.0,40.227.0"}
P.entries["quest:6122"] = {n="Головне джерело",s="«Головне джерело» — важливий обряд посвяти для молодих друїдів із нічних ельфів, що вчаться розуміти й зцілювати природу. Новачки, яких Дендрит Старблейз посилає з Місячного Гаю, мусять набрати отруєної води біля Водоспаду Скельного Джерела на Темному Узбережжі, щоб допомогти Аланндаріан Найтсонг, натуралістці з Обердайна, зупинити хворобу, що шириться серед лісових оленів.",h="«Головне джерело» — важливий обряд посвяти для молодих друїдів із нічних ельфів, що вчаться розуміти й...",kw={"головне джерело","водоспад скельного джерела","дендрит старблейз","аланндаріан найтсонг","коло кенарія","наги"},ang={["class:Druid"]="Це завдання — частина основоположного друїдського випробування. Зіткнувшись із занепадом природи біля Водоспаду Скельного Джерела й готуючи ліки, ви пробуджуєте духовні й рослинні знання, потрібні, щоб зцілювати отруєння в дикій природі.",["race:NightElf"]="Для калдореїв Обердайна отруєння Водоспаду Скельного Джерела — пряма наруга над лісами предків, що вимагає негайного втручання, аби вберегти невинних створінь краю."},sec={{t="Отруєна життєва артерія",b="Водоспад Скельного Джерела — головне джерело прісної води на півночі Темного Узбережжя. Коли звірі — передусім місцеві олені — почали піддаватися протиприродній, затяжній недузі, Коло Кенарія звернуло увагу на річку. Підозрюючи, що отруєно самі підземні води, Дендрит Старблейз у Місячному Гаю доручає молодим друїдам важливе завдання: дістатися входу до печери під водоспадом і набрати непошкоджену пробу отруєної води."},{t="Тіні біля водоспаду",b="Набрати воду — справа небезпечна. Люті наги облаштувалися в Печері Річки Скельного Джерела й гніздяться біля самих верхів'їв водоспаду. Їхня присутність довкола підземного джерела — пряма загроза кожному, хто розслідує пошесть. Попри небезпеку, лише здобувши незабруднену пробу біля входу до печери, Коло Кенарія зможе дослідити те, що нівечить дику природу."},{t="Глибша недуга",b="Коли пробу приносять Аланндаріан Найтсонг в Обердайн, смердюча вода підтверджує найгірші побоювання Кола. Та дослідження мерзенної рідини відкриває тривожну правду: хоча отруєний водоспад справді головний провідник, що отруює береги річки, уражених оленів бачили далеко за його прямою течією. Вода стає важливим реагентом, щоб почати готувати протиотруту, але Аланндаріан підозрює, що глибша, ширша порча шириться всіма підземними водами Темного Узбережжя."}},faq={{q="Чому Водоспад Скельного Джерела такий важливий для Темного Узбережжя?",a="Водоспад Скельного Джерела — головне природне джерело питної води для півночі Темного Узбережжя. Він живить місцеві струмки, річки, рослини й тварин довкола, тож будь-яка отрута, що потрапить у його витоки, швидко розходиться по всій місцевій природі.",al={"чому важливий водоспад скельного джерела","значення річки скельного джерела","водне джерело темного узбережжя"}},{q="Чому хворіють олені на Темному Узбережжі?",a="Місцеві олені п'ють просто з Водоспаду Скельного Джерела й струмків, які він живить. Якась згубна отрута забруднила воду біля самого джерела, і лісові звірі потерпають від тяжкої виснажливої хвороби.",al={"чому олені хворі","хворі олені темного узбережжя","що отруїло оленів"}},{q="Хто такий Дендрит Старблейз?",a="Дендрит Старблейз — старший наставник друїдів, що живе у священному притулку Місячного Гаю. Він веде друїдів, які здобувають нові щаблі майстерності, стежить за негараздами по всьому Калімдору й спрямовує дії Кола Кенарія, коли природу спіткає лихо.",al={"переказ про дендрита старблейза","хто дав завдання","старблейз місячний гай"}},{q="Хто така Аланндаріан Найтсонг?",a="Аланндаріан Найтсонг — дослідниця природи з нічних ельфів, що перебуває в Обердайні. Стривожена поширенням скверни й стражданнями тварин на Темному Узбережжі, вона звернулася до Кола Кенарія в Місячному Гаю по досвідчену допомогу, щоб дослідити недугу й знайти ліки.",al={"хто така аланндаріан","аланндаріан найтсонг оберіжин"}},{q="Що наги роблять біля Водоспаду Скельного Джерела?",a="Наги з прибережних вод Темного Узбережжя просунулися вглиб суходолу й захопили печери за Водоспадом Скельного Джерела. Через них дістатися до витоків і дослідити воду вкрай небезпечно.",al={"наги біля скельного джерела","чому тут наги","наги водоспаду скельного джерела"}},{q="Якого вміння допомагає навчитися це завдання?",a="Це розслідування — частина випробування «Влада над отрутою». Розпізнавши цю пошесть серед тварин і разом з Аланндаріан Найтсонг виготовивши протиотруту, учні-друїди опановують важливе магічне мистецтво зцілення від отрути.",al={"яке закляття дає це завдання","завдання друїда про отруту","ланцюжок зцілення від отрути"}}},fp="20,354,26.501.0,20.422.0,15.507.1,51.280.0,42.223.0,26.234.0,29.262.0,34.233.0,47.220.0"}
P.entries["quest:6123"] = {n="Збір ліків",s="«Збір ліків» — важливе випробування для молодих друїдів із нічних ельфів, що вчаться опановувати цілющі сили природи на Темному Узбережжі. Під проводом Аланндаріан Найтсонг з Обердайна друїд збирає важливі природні реагенти, щоб зварити відновлювальну мазь для хворих звірів краю. Це завдання закладає практичну основу розуміння того, як трав'яні засоби борються з отрутою та хворобами.",h="«Збір ліків» — важливе випробування для молодих друїдів із нічних ельфів, що вчаться опановувати цілющі сили...",kw={"збір ліків","аланндаріан найтсонг","земнокорінь","місячний гриб","коло кенарія","друїди"},ang={["class:Druid"]="Цей обряд посвяти вчить молодих друїдів, як ліки смертних взаємодіють із природними отрутами, і закладає основу, щоб спрямовувати чисту цілющу енергію без звичайних знарядь.",["profession:Herbalism"]="Аланндаріан окремо наголошує на цінності травників: лише їхнє натреноване око вміє викопати земнокорінь просто з землі.",["race:NightElf"]="Берегти священні гаї та звірів Темного Узбережжя — священний обов'язок калдореїв, які шанують Елуну й духів дикої природи."},sec={{t="Ліки для звірів Темного Узбережжя",b="Після того як з'ясувалося, що місцевих звірів нівечить отруєне джерело води, Аланндаріан Найтсонг в Обердайні береться приготувати дієву цілющу мазь. Чиста вода — основа суміші, але для справжнього зцілення потрібні сильні природні каталізатори. Хворі лісові олені не одужають самі, тож для Кола Кенарія зібрати цілющі засоби — нагальна справа."},{t="Коріння й місячне цвітіння",b="Для відновлювальної мазі потрібні дві важливі рослини: земнокорінь і Місячний Гриб. Земнокорінь має чисті цілющі властивості, і, щоб викопати його з кам'янистого ґрунту, потрібне натреноване око травника. А щоб надати суміші сили, Аланндаріан посилає друїда в сусідні східні печери збирати грибне цвітіння, що буяє в темряві серед дедалі войовничіших і збуджених місячників."},{t="Шлях до очищення від отрут",b="Створити окрему протиотруту для кожної отрути — копітка й виснажлива справа. Проводячи новачка крізь делікатне збирання й варіння матеріальних інгредієнтів, Аланндаріан показує, скільки зусиль вимагає звичайне лікування. Це практичне варіння стає сходинкою до опанування вродженого друїдського мистецтва виганяти отрути чистою магією природи."}},faq={{q="Навіщо завдання «Збір ліків»?",a="Завдання доручає учневі-друїду зібрати земнокорінь і Місячний Гриб для Аланндаріан Найтсонг в Обердайні. З цих реагентів готують цілющу мазь для хворих оленів Темного Узбережжя, і це навчальний крок на шляху до вміння знешкоджувати отрути.",al={"навіщо збір ліків","мета збору ліків","для чого збір ліків"}},{q="Де росте Місячний Гриб?",a="Місячний Гриб росте в печерах у пагорбах просто на схід від Обердайна. Друїдам слід обережно пробиратися цими лігвами, бо дикі місячники, що там живуть, стали агресивними й ревно боронять свою територію.",al={"де місячний гриб","місця місячного гриба","як знайти місячний гриб"}},{q="Чи треба бути травником, щоб добути земнокорінь?",a="Самому опановувати Травництво не обов'язково, хоча земнокорінь збирають із диких рослин. Якщо ви не займаєтеся цим ремеслом, доведеться виміняти його в травника чи роздобути в інших, щоб завершити рецепт Аланндаріан.",al={"чи потрібне травництво для земнокореня","чи можна без травництва земнокорінь","земнокорінь без професії"}},{q="Хто така Аланндаріан Найтсонг?",a="Аланндаріан Найтсонг — друїдка Кола Кенарія, що перебуває в Обердайні. Вона стежить за здоров'ям рослин і тварин Темного Узбережжя й веде молодих друїдів через перші випробування, навчаючи їх очищати й берегти дику природу.",al={"хто така аланндаріан","переказ про аланндаріан найтсонг"}},{q="Чому хворіють олені на Темному Узбережжі?",a="Олені напилися води, отруєної забрудненим джерелом у дикій місцевості. Отрута виснажує їх і завдає мук, і щоб полегшити їхні страждання, потрібна дієва цілюща мазь.",al={"чому олені отруєні","хворі олені темне узбережжя","що отруїло оленів"}},{q="Як це завдання допомагає мені опанувати «Зцілення від отрути»?",a="Це завдання — частина ширшого навчання «Влада над отрутою». Показуючи учням, як клопітно готувати трав'яні протиотрути до кожної окремої отрути, Коло Кенарія готує їх спрямовувати чисту магію природи, що знешкоджує отрути без жодних зусиль.",al={"завдання зцілення від отрути друїд","вивчити зцілення від отрути","ланцюжок влади над отрутою"}}},fp="18,378,33.409.0,22.396.0,28.386.1,42.269.0,33.196.0,46.214.0,29.218.0,35.204.0,46.260.0"}
P.entries["quest:6124"] = {n="Зцілення хворих",s="«Зцілення хворих» — важливе випробування для молодих друїдів Альянсу: їм доручають приготованою маззю лікувати отруєних звірів, що блукають Темним Узбережжям. Безпосередньо допомагаючи враженим оленям, новачки протистоять недузі, яка насувається на північ Калімдору, а тоді доповідають Колу Кенарія в Місячному Гаю.",h="«Зцілення хворих» — важливе випробування для молодих друїдів Альянсу: їм доручають приготованою маззю...",kw={"зцілення хворих","цілюща мазь для тварин","аланндаріан найтсонг","дендрит старблейз","місячний гай","олені"},ang={["class:Druid"]="Цей обряд посвяти перевіряє відданість новачка збереженню рівноваги й веде до вродженого вміння виганяти отрути друїдською магією.",["race:NightElf"]="Темне Узбережжя — давній рубіж сучасних поселень нічних ельфів, тож раптова пошесть серед оленів — лиховісне знамення для калдореїв."},sec={{t="Моровиця в лісах",b="По всіх затінених лісах Темного Узбережжя, від вод Річки Скельного Джерела на південь до меж Ашенвалю, місцеві звірі потерпають від затяжної хвороби. Хворі олені безцільно блукають у тумані, ослаблені протиприродними отрутами, що просочилися в ґрунт і струмки. Зібравши потрібні реагенти, травниця Аланндаріан Найтсонг довіряє молодому друїдові щойно зварену Цілющу Мазь для Тварин, щоб лікувати уражених створінь на місці."},{t="Розплющені очі в Місячному Гаю",b="Коли вилікувано десять оленів, новачка посилають доповісти Дендритові Старблейзу у священному прихистку — Місячному Гаю. Поки Обердайн трохи полегшено зітхає, Дендрит бачить у хворих стадах провісника значно зловіснішої порчі, що охоплює північ Калімдору. Він застерігає: поки провідники в Дарнасусі сперечаються й не помічають повзучої гнилі, Коло Кенарія мусить пильно стежити за справжніми масштабами порчі, що вкорінюється на континенті."}},faq={{q="Чому хворіють олені на Темному Узбережжі?",a="Олені потерпають від скверни, що розповзається природою: вона вже просочується у води й ґрунт Темного Узбережжя від Річки Скельного Джерела аж на південь до Ашенвалю. Пасучись, олені мимоволі їдять отруєні рослини й п'ють річкову воду, тож слабнуть і хворіють.",al={"чому олені хворі","хворі олені темного узбережжя","що отруїло оленів"}},{q="Хто готує цілющу мазь для оленів?",a="Аланндаріан Найтсонг, травниця з міста нічних ельфів Обердайн, готує Цілющу Мазь для Тварин із рідкісних реагентів, які зібрав учень-друїд. Цієї партії вистачає на десять доз, щоб негайно допомогти тваринам, поки вона з місцевими жителями намагається приготувати ще.",al={"хто робить ліки","мазь аланндаріан","хто готує мазь для звірів"}},{q="Чому Дендритові Старблейзу не байдужі олені?",a="Дендрит Старблейз наглядає за навчанням друїдів від імені Кола Кенарія в Місячному Гаю. Для нього турбота про диких тварин — і практична перевірка друїдського обов'язку, і суворе підтвердження того, що дику природу Калімдору охоплює ширша й небезпечна скверна.",al={"чому дендрит у місячному гаю","інтерес кола кенарія до оленів","роль дендрита старблейза"}},{q="На яку політичну напругу натякає Дендрит Старблейз?",a="Коли завдання виконано, Дендрит зауважує, що одні можновладці нічних ельфів у Дарнасусі визнають, що природа дедалі більше гниє, а інші вперто не помічають тривожних знаків. Він закликає учня ніколи не заплющувати очі на незручну правду, з якою стикається світ природи.",al={"напруга дарнасуса","хто ігнорує осквернення","шори дарнасуса"}},{q="Де знайти хворих оленів?",a="Хворі олені блукають майже по всьому Темному Узбережжю. Вони трапляються одразу на південь від Річки Скельного Джерела, що тече трохи північніше від Обердайна, і далі прибережними лісами аж до кордону з Ашенвалем.",al={"місця хворих оленів","де олені","олені темного узбережжя"}},{q="Чого вчиться друїд, виконавши це завдання?",a="Це завдання — практичний підсумок друїдського навчання з очищення від отрут. Побачивши страждання лісових тварин і застосувавши звичайні ліки, друїд долає прірву між трав'яними засобами й духовною владою над отрутою.",al={"чого вчить це друїдів","навчання друїда зціленню від отрути","урок зцілення хворих"}}},fp="15,327,25.476.0,26.476.1,35.304.0,49.288.0,48.264.0,55.280.0,35.235.0,50.242.0"}
P.entries["quest:6125"] = {n="Влада над отрутою",s="«Влада над отрутою» — завершення випробування, у якому молодий друїд опановує боротьбу з отруєннями. Навчившись власноруч варити трав'яні ліки на Темному Узбережжі, посвячуваний повертається до Дарнасуса, щоб отримати магічне благословення Кола Кенарія й очищати від отрут за власним бажанням.",h="«Влада над отрутою» — завершення випробування, у якому молодий друїд опановує боротьбу з отруєннями.",kw={"влада над отрутою","аланндаріан найтсонг","місячний гриб","земнокорінь","обердайн","очищення","друїд"},ang={["class:Druid"]="Цей обряд посвяти поєднує скромне травництво зі священною цілющою магією й позначає мить, коли друїд отримує силу благодаттю природи знешкоджувати отруту.",["race:NightElf"]="Це випробування в Ценаріонському Анклаві Дарнасуса віддзеркалює шанування рівноваги в калдореїв і їхню урочисту опіку над прадавніми лісами."},sec={{t="Покора учня",b="Перш ніж дати друїдові вроджену магічну здатність очищати від отрут, Коло Кенарія вимагає, щоб посвячувані зрозуміли страждання простого люду. На Темному Узбережжі Аланндаріан Найтсонг доручає молодим друїдам власноруч зібрати Земнокорінь і Місячний Гриб і зварити мазь, щоб зцілити уражених звірів. Цей урок гарантує, що, коли друїд спрямовує силу природи на лікування отруєння, він робить це з глибоким співчуттям до тих, хто мусить боротися з отрутою без допомоги духів."},{t="Повернення до Анклаву",b="Щойно ліки довели свою дієвість в Обердайні, Старблейз відсилає друїда назад через море до Дарнасуса. У гіллі Ценаріонського Анклаву на нього чекає Матренґіл Берволкер. Задоволений тим, як гідно посвячуваний тримався під тиском, Матренґіл урочисто передає йому мистецтво природного очищення й назавжди дарує владу над отрутами. Та випробування приносить і тривожні вісті: сильні отрути в диких землях довкола Обердайна вказують на неприродну пошесть, що порушує тонку рівновагу краю."}},faq={{q="Навіщо це завдання?",a="Це завдання завершує друїдське випробування зі зцілення від отрут. Успішно приготувавши для Дендрита Старблейза в Місячному Гаю й на Темному Узбережжі цілющу суміш, учень повертається до Матренґіла Берволкера в Дарнасусі, щоб навчитися магічного заклинання «Зцілення від отрути».",al={"навіщо влада над отрутою","мета влади над отрутою","завдання зцілення від отрути"}},{q="Хто такий Дендрит Старблейз?",a="Дендрит Старблейз — старший друїд, що перебуває у священному Нічному Притулку в Місячному Гаю. Він веде учнів через духовні випробування, перевіряючи їхнє терпіння й відданість природі, перш ніж відправити назад до власних наставників.",al={"роль дендрита старблейза","хто дає владу над отрутою"}},{q="Хто такий Матренґіл Берволкер?",a="Матренґіл Берволкер — майстер-наставник друїдів у Ценаріонському Анклаві в Дарнасусі. Він опікується зростанням друїдів нічних ельфів серед гілля Тельдрассилу, навчаючи їх подоб, цілющих мистецтв та урочистих обов'язків Кола Кенарія.",al={"переказ про матренґіла берволкера","берволкер дарнасус"}},{q="Чому друїд мусив спершу приготувати ліки власноруч?",a="Дендрит Старблейз навчає, що друїд має розуміти, як отрута виснажує тіло і скільки праці потрібно, щоб вилікувати її без магії. Збираючи звичайні інгредієнти й власноруч допомагаючи хворим, учень вчиться смирення й уміння цінувати дари природи, які ось-ось отримає.",al={"чому готувати трав'яні ліки","урок влади над отрутою"}},{q="Що непокоїть Матренґіла в подіях довкола Обердайна?",a="Матренґіл зауважує, що раптова поява смертельних отрут у дикій природі Темного Узбережжя довкола Обердайна — річ неприродна. Негаразди з місцевими тваринами й рослинами загрожують рівновазі природи й наводять на думку, що на туманному узбережжі діє якась згубна сила.",al={"переказ про отруєння оберіжина","що непокоїть матренґіла"}}},fp="17,269,22.487.0,21.526.0,34.268.0,26.243.0,29.255.0,56.291.0,58.255.0"}
P.entries["quest:6126"] = {n="Нові уроки",s="«Нові уроки» — обряд посвяти для юних друїдів-тауренів, який розпочинає Турак Рунтотем на Узвишші Старійшин у Тандер Блафі. Він скеровує учнів до священного прихистку Місячного Гаю, щоб почати опановувати мистецтво очищення від природних і неприродних отрут. Під проводом нічного ельфа Дендрита Старблейза цей урок замість умовних випробувань ставить учня перед справжньою нагальною бідою — отруєнням.",h="«Нові уроки» — обряд посвяти для юних друїдів-тауренів, який розпочинає Турак Рунтотем на Узвишші Старійшин у...",kw={"нові уроки","друїд","отрута","турак рунтотем","дендрит старблейз","нічний притулок","місячний гай","перехрестя"},ang={["class:Druid"]="Це завдання знаменує ваш перехід від простого перевтілення й сутичок до справжньої опіки над дикою природою й відкриває шлях до опанування заклинання «Зцілення від отрути».",["faction:Horde"]="Поки воїни Орди б'ються з нічними ельфами в Ашенвалі, друїди Орди знаходять безпечний прихисток у Місячному Гаю під священною опікою Кола Кенарія.",["race:Tauren"]="Для тауренів ця мандрівка показує, наскільки глибоко діти Земної Матері відновили зв'язок із ученням Кенарія пліч-о-пліч зі своїми побратимами — нічними ельфами."},sec={{t="Дар Кенарія",b="Друїди мають священний обов'язок оберігати дику природу, і серед іншого Кенарій дарував їм дивовижну здатність одним заклинанням очищати від лютих отрут. Проте таку могутню магію не вручають без належного підґрунтя. Турак Рунтотем наполягає: перш ніж спрямовувати божественну енергію, щоб без зусиль розвіювати пошесті, друїд має зрозуміти, як отрута вражає тіло, і навчитися лікувати її звичайними, земними засобами."},{t="Поклик до Нічного Притулку",b="Здібних послушників не навчають лише на кручах Малгору — їх відсилають на північ священними стежками до Місячного Гаю. Там, у мирному селищі Нічний Притулок, прадавні наставники з нічних ельфів, як-от Дендрит Старблейз, опікуються навчанням і ельфів, і тауренів. Це спільне навчання підкреслює тонке перемир'я, що панує в Колі Кенарія, піднімаючись над політичними чварами, які розділяють Орду й Альянс."},{t="Справжня біда в Пустках",b="Колишні учні відпрацьовували обряди очищення в умовах, що їх контролювали наставники, але Старблейз не має часу на вигадані вправи. Біля Перехрестя в посушливих Пустках спалахнула нестримна хвиля отруєнь звірів. Розпачливе прохання про допомогу з Перехрестя перетворює навчальний обряд посвяти на нагальне польове доручення, і юні друїди мають безпосередньо зіткнутися зі стражданнями диких звірів."}},faq={{q="Хто дає це завдання і де його знайти?",a="Завдання дає Турак Рунтотем, наставник друїдів-тауренів на Узвишші Старійшин у Тандер Блафі. Він кличе учнів, які вже довели свою відданість ученню Кенарія.",al={"хто дає нові уроки","де взяти нові уроки","видавець нових уроків"}},{q="Хто такий Дендрит Старблейз?",a="Дендрит Старблейз — старший друїд нічних ельфів, що живе в Нічному Притулку в Місячному Гаю. Попри ширшу ворожнечу між нічними ельфами й тауренами, він наставляє молодих друїдів обох рас у традиціях Кола Кенарія.",al={"хто такий дендрит","роль дендрита старблейза","хто нічний ельф у місячному гаю"}},{q="Якої сили навчає мене це завдання?",a="Цей ланцюжок завдань розпочинає ваше навчання «Зцілення від отрути». Він учить друїдів розуміти фізичну й магічну природу отрути, щоб очищати від шкідливих недуг союзників і диких істот, про яких вони дбають.",al={"якої здібності я навчуся","яке закляття для цього","завдання лікування отрути"}},{q="Чому таурен має вчитися в нічного ельфа?",a="Коло Кенарія — нейтральне братство, віддане рівновазі природи. Хоча саме нічні ельфи першими впорядкували сучасне друїдство під проводом Кенарія, вони знову прийняли тауренів до ордену й ділять із ними священні місця на кшталт Місячного Гаю, попри війну фракцій.",al={"чому таурен вчиться в нічного ельфа","нічні ельфи таурени друїди","фракція кола кенарія"}},{q="Що діється на Перехресті?",a="Тварин довкола Перехрестя в Пустках косить хвиля тяжких отруєнь, яку місцеві доглядачі не можуть зупинити. Дендрит Старблейз переносить ваше навчання просто в поле: треба знайти джерело біди й виготовити ліки.",al={"проблема перехрестя","що отруює тварин","хвороба перехрестя"}},{q="Як найшвидше дістатися до Місячного Гаю для цього завдання?",a="Як друїд, ви маєте власне заклинання «Телепортація: Місячний Гай», що переносить вас просто до святилища Нічного Притулку, — не треба йти пішки через небезпечні спірні землі.",al={"як дістатися місячного гаю","дорога до нічного притулку","телепорт у місячний гай"}}},fp="12,403,20.427.0,21.458.0,28.418.1,47.199.0,26.236.0,37.234.0,50.276.0,36.257.0,59.191.0"}
P.entries["quest:6127"] = {n="Головне джерело",s="«Головне джерело» — завдання для друїдів Орди, яке дає Дендрит Старблейз у Місячному Гаю. Воно посилає друїдів-новачків на Пік Жахливої Імли на півночі Пусток, щоб набрати зразок отруєної води зі ставка й принести його на Перехрестя, де чекає Тонга Рунтотем. Зразок дає основу, щоб зрозуміти отруту, яка шириться серед місцевої звірини.",h="«Головне джерело» — завдання для друїдів Орди, яке дає Дендрит Старблейз у Місячному Гаю.",kw={"головне джерело","дендрит старблейз","пік жахливої імли","тонга рунтотем","палаючий клинок","друїд"},ang={["class:Druid"]="Цей обряд посвяти — важливий крок на вашому шляху захисника дикої природи: він доводить, що ви вмієте простежити скверну до її джерела й відокремити магічні отрути, перш ніж вони знищать цілий край.",["faction:Horde"]="Перехрестя — серце постачання Орди в Калімдорі, тож неприборкане поширення демонічної пошесті просто в нього під боком — пряма загроза торгівлі й виживанню.",["race:Tauren"]="Пустки — родові землі племен Калімдору; очищення води захищає від демонічної скверни стада газелей, що поколіннями годували ваш народ."},sec={{t="Отруєна гора",b="Пік Жахливої Імли височіє на північний захід від Перехрестя — так високо, що його гірські джерела й ставки впливають на погоду й природну вологу посушливих північних Пусток. На жаль, на його скелях отаборилися демонопоклонники з Палаючого Клинка. Дендрит Старблейз розуміє: мерзенне чаклунство на такій важливій природній висоті може отруїти всю довколишню улоговину."},{t="Пошесть на рівнинах",b="На північній савані бачили хворих газелей, що, спотикаючись, бредуть на північ від головного шляху зі сходу на захід через Перехрестя. Тонга Рунтотем, шукаючи допомоги для місцевих тауренів, звернувся до Кола Кенарія, щоб з'ясувати, що отруює стадо. Вирушивши на пік і здобувши чистий зразок отруєної води, друїди передають у руки Тонги важливий каталізатор, потрібний, щоб дослідити недугу й зварити протиотруту."}},faq={{q="Де взяти пробу води для цього завдання?",a="Воду треба набрати з водойми на самій вершині Піку Жахливої Імли, на північний захід від Перехрестя в Пустках. Дістаньтеся до озерця на вершині, де збираються сектанти Палаючого Клинка, і наберіть води в посудину для проб, яку дав Дендрит Старблейз.",al={"де пробу води","де озерце піку жахливої імли","головне джерело зразок води"}},{q="Чому вода на Піку Жахливої Імли така важлива для Пусток?",a="На висоті Піку Жахливої Імли лежать водойми, що безпосередньо впливають на місцеву погоду й тумани. Коли демонічні сектанти оскверняють ці води, отруйні випари й стоки спливають униз і псують рівнини, а звірі по всій півночі Пусток хворіють.",al={"чому важливий пік жахливої імли","погодне озерце пусток","озерця піку жахливої імли"}},{q="Хто такий Тонга Рунтотем?",a="Тонга Рунтотем — друїд-таурен на Перехресті в Пустках. Глибоко стривожений неприродними недугами, що ширяться серед місцевих газелей, він звернувся до Кола Кенарія в Місячному Гаю по допомогу, щоб розпізнати хворобу й очистити землю.",al={"хто такий тонга","роль тонги рунтотема","друїд перехрестя"}},{q="Хто отруює воду на вершині?",a="Води осквернив Палаючий Клинок — темний культ чорнокнижників-демонопоклонників і прислужників скверни, що захопили звивисті стежки й вершину Піку Жахливої Імли.",al={"хто отруїв воду","сектанти жахливої імли","палаючий клинок жахлива імла"}},{q="Якого вміння навчає цей ланцюжок?",a="Це доручення — частина ширшого обряду «Влада над отрутою» для молодих друїдів Орди, що завершується опануванням духовних і трав'яних знань, потрібних, щоб зцілювати від отрут у польових умовах.",al={"нагорода влади над отрутою","закляття друїда проти отрути","завдання зцілення від отрути пустки"}},{q="Чи можуть друїди Альянсу виконати це завдання?",a="Ні. «Головне джерело» — це саме ординська версія випробування, яка відправляє гравців у Пустки до Тонги Рунтотема. Друїди Альянсу проходять рівноцінний шлях на Темному Узбережжі, щоб здобути вміння очищати від отрут.",al={"аналог для альянсу","чи нічні ельфи можуть головне джерело","завдання альянсу про отруту"}}},fp="20,346,18.429.0,22.428.0,47.253.0,63.265.0,23.253.0,40.184.0,46.185.0,34.232.0"}
P.entries["quest:6128"] = {n="Збір ліків",s="«Збір ліків» — священний обряд посвяти для молодих тауренських друїдів на Перехресті. За дорученням Тонги Рунтотема друїд збирає земнокорінь і міцні роги кодо, щоб приготувати цілющу мазь для отруєних газелей Пусток.",h="«Збір ліків» — священний обряд посвяти для молодих тауренських друїдів на Перехресті.",kw={"збір ліків","тонга рунтотем","земнокорінь","роги кодо","газелі","друїд"},ang={["class:Druid"]="Це доручення — частина важливих випробувань, у яких друїди вчаться виходити за межі смертного травництва й спрямовувати магію природи, щоб напряму очищати від отрут.",["faction:Horde"]="Виконуючи доручення Тонги, ви захищаєте звірину довкола Перехрестя й бережете рівновагу природи навколо цієї серцевинної застави Орди.",["profession:Herbalism"]="Завдання тримається на земляному корені й підкреслює незмінну цінність диких лікувальних коренів, які збирають на кам'янистих схилах савани."},sec={{t="Рецепт полегшення",b="Здобувши зразок води з Піка Жахливої Імли, Тонга Рунтотем потребує сирих реагентів, щоб зварити дієву протиотруту. Природна вода — основа мазі, звичайний земнокорінь дає їй головні цілющі властивості, а мелений ріг кодо — відновну силу, потрібну, щоб вибити отруту з тіла істоти. Для молодого друїда здобути ці складники означає покластися на дари землі й проредити місцевих звірів."},{t="Уроки очищення",b="Алхімія й знання трав — традиційні способи протидіяти окремим отрутам, але кожна отрута зазвичай вимагає точних, особливих ліків. Тонга використовує це клопітке приготування, щоб показати новачкам межі тілесних ліків. Справжня влада над природними отрутами приходить не від нескінченних запасів сушених трав і рогів у торбі, а від прямого налаштування на цілющі енергії природи — глибокий урок, що веде прямо до друїдського мистецтва Зцілення від отрути."}},faq={{q="Які інгредієнти просить Тонга Рунтотем?",a="Тонга просить п'ять пучків земнокореня й п'ять цілих рогів кодо. Земнокорінь дає цілющі властивості трав, а роги — ту життєву силу, що потрібна, аби перебороти отруту, яка вразила місцевих газелей.",al={"предмети збору ліків","які інгредієнти потрібні","матеріали ліків"}},{q="Де знайти роги кодо?",a="Кодо блукають посушливими рівнинами північних і центральних Пусток і часто пасуться біля доріг довкола Перехрестя. Тонга наголошує, що для мазі згодяться лише цілі, міцні роги цих звірів, а не крихкі уламки.",al={"де кодо","де роги кодо","знайти кодо в пустках"}},{q="Чи треба бути травником, щоб добути земнокорінь?",a="Ні, самому володіти травництвом не обов'язково. Травники збирають земнокорінь на кручах і скелястих виступах по всіх Пустках, а друїди, які не вміють його збирати, можуть роздобути його в інших мандрівників або на торгових пунктах.",al={"чи потрібне травництво","земнокорінь без травництва","вимога професії для земнокореня"}},{q="Навіщо Тонга готує звичайну мазь?",a="Тонга готує звичайну протиотруту, щоб лікувати отруєних газелей, які страждають по всій півночі Пусток. А ще цей клопітний процес виготовлення ліків на кожен окремий випадок показує, наскільки вигідніше опанувати природні магічні заклинання очищення.",al={"навіщо протиотрута","мета мазі","чому не магія"}},{q="Хто такий Тонга Рунтотем?",a="Тонга Рунтотем — старший друїд-таурен на Перехресті в Пустках. Він досліджує скверну, що розходиться водами краю, і вчить молодих друїдів берегти рівновагу природи.",al={"хто дає збір ліків","роль тонги рунтотема","хто такий тонга"}},{q="Що буде після збору інгредієнтів?",a="Коли Тонга зварить із реагентів цілющу мазь, він відправить друїда в савану, щоб той намастив нею хворих газелей і випробував ліки, а тоді навчить глибшого мистецтва магічного очищення.",al={"що після збору ліків","наступне завдання після збору ліків","після збору ліків"}}},fp="18,244,19.464.0,20.467.0,46.224.0,34.236.0,49.256.0,40.267.0,23.217.0,45.223.1"}
P.entries["quest:6129"] = {n="Зцілення хворих",s="«Зцілення хворих» — важливе випробування для молодих друїдів Орди: їм доручено лікувати уражену звірину на півночі Пусток. Накладаючи свіжоприготовану трав'яну мазь хворим газелям, новачки показують і практичне польове цілительство, і відданість збереженню природної рівноваги. Виконавши цей обов'язок, вони доводять свою відданість просто Колу Кенарія в Місячному Гаю.",h="«Зцілення хворих» — важливе випробування для молодих друїдів Орди: їм доручено лікувати уражену звірину на...",kw={"зцілення хворих","газелі","тонга рунтотем","дендрит старблейз","коло кенарія","друїд"},ang={["class:Druid"]="Цей обряд зцілення знаменує ваш перехід від учня травництва до діяльного охоронця природи й доводить, що ви готові спрямовувати магію життя проти смертельних отрут.",["faction:Horde"]="Лікуючи уражену звірину біля Перехрестя, тауренські друїди допомагають уберегти важливі мисливські угіддя й шляхи, на яких тримаються позиції Орди в центральному Калімдорі.",["race:Tauren"]="Коли ваш народ відновлює давні зв'язки з Колом Кенарія, зцілення Пусток доводить, що діти Земної Матері — гідні охоронці рівноваги."},sec={{t="Мор на стада",b="На північній савані Пусток газелі на пасовищах почали падати від неприродної недуги. Зібравши земнокорінь і роги кодо для цілющих ліків, Тонга Рунтотем на Перехресті доручає молодому друїдові провести лікування просто в полі. Новачок мусить вирушити на північ від головного перехрестя, знайти десять хворих тварин і допомогти їм, перш ніж гниль глибше пустить коріння в довкіллі."},{t="Благословення Кола",b="Коли мазь розділено, шлях друїда веде назад під тихе гілля Місячного Гаю. Там Дендрит Старблейз визнає співчуття й пильність новачка. Він зауважує, що страждання газелей — лише ознака глибшої, підступної скверни, що підкрадається до дикої природи Калімдору. Доглядаючи найменших звірів, тауренські друїди показують, що шана до Кенарія стоїть понад племінними межами, і здобувають глибші таємниці очищення від отрут і магії природи."}},faq={{q="Де знайти хворих газелей?",a="Хворі газелі блукають посушливими рівнинами північних Пусток, здебільшого на північ від головного торгового шляху зі сходу на захід, що перетинає Перехрестя.",al={"де хворі газелі","місця газелей","газелі пусток"}},{q="Хто дає це завдання?",a="Тонга Рунтотем, друїд-таурен на Перехресті в Пустках, дає це завдання й видає Цілющу Мазь для Тварин, коли ви виконаєте його доручення зі збору реагентів.",al={"хто дає зцілення хворих","хто дає завдання","де тонга рунтотем"}},{q="Кому доповісти, вилікувавши тварин?",a="Завдання здають Дендритові Старблейзу в друїдському святилищі Місячного Гаю — до священного гаю ви дістанетеся телепортацією.",al={"де здати","здати завдання","де дендрит старблейз"}},{q="Чому Колу Кенарія не байдужі Пустки?",a="Коло Кенарія стежить за гармонією землі. Хвороба, що шириться серед диких газелей, — відгомін усеосяжної скверни, яка повзе Калімдором і, якщо її не зупинити, може розхитати природний лад.",al={"чому друїди піклуються про пустки","коло кенарія пустки"}},{q="Яке вміння відкриває цей ланцюжок завдань?",a="Це випробування — друга половина друїдського обряду посвяти, що зрештою дає учневі вміння очищати від отрут і токсинів себе й союзників.",al={"нагорода зцілення від отрути","навіщо це завдання друїду"}},{q="Чи можуть вилікувати газелей не друїди?",a="Ні. Цей ланцюжок завдань — лише для друїдів: це окреме класове випробування під наглядом самого Кола Кенарія.",al={"чи це лише для друїдів","хто може зцілення хворих"}}},fp="15,397,23.459.0,21.483.0,36.158.0,22.180.0,44.140.0,53.218.0,42.180.0,35.122.0"}
P.entries["quest:6130"] = {n="Влада над отрутою",s="«Влада над отрутою» — завершальний обряд у випробуванні юного друїда Орди, що опановує цілющу магію природи. Вилікувавши уражених газелей довкола Перехрестя самими лише трав'яними сумішами, учень повертається до Турака Рунтотема на Узвишшя Старійшин у Тандер Блафі, щоб отримати справжній дар — «Зцілення від отрути».",h="«Влада над отрутою» — завершальний обряд у випробуванні юного друїда Орди, що опановує цілющу магію природи.",kw={"влада над отрутою","друїд","Зцілення від отрути","турак рунтотем","тонга рунтотем","перехрестя","газелі"},ang={["class:Druid"]="Цей обряд посвяти поєднує звичайне травництво Калімдору з вродженою магією природи й назавжди дарує друїдам змогу очищати союзників від отрут.",["faction:Horde"]="Випробування довкола Перехрестя показують, що Орда відіграє дедалі більшу роль в охороні диких просторів центрального Калімдору від неприродної скверни.",["race:Tauren"]="Для учнів-тауренів виконання цього завдання доводить їхню відданість Колу Кенарія й підтримує живою мудрість Земної Матері на Узвишші Старійшин."},sec={{t="Урок страждання",b="Перш ніж дати молодому друїдові вроджену магічну силу очищати від отрут, Коло Кенарія вимагає, щоб він зрозумів, що таке недуга насправді. Дендрит Старблейз відіслав новачка на Перехрестя, де Тонга Рунтотем доручив йому зібрати земні складники для цілющої мазі, приготованої власноруч. Лише лікуючи отруєних газелей Пусток без допомоги духів, учень бачить, як мучаться звичайні створіння в боротьбі з природними й неприродними отрутами."},{t="Повернення на Узвишшя Старійшин",b="Коли випробування завершено, Дендрит відсилає учня назад до Турака Рунтотема — великого наставника друїдів, що живе на Узвишші Старійшин у Тандер Блафі. Турак зауважує, що дивні люті отрути, які з'являються біля Перехрестя, загрожують природній рівновазі рівнин і викликають серйозне занепокоєння. Похваливши учня за витримку під тиском, Турак назавжди передає йому духовне мистецтво зцілення від отрут і доручає берегти живих істот Калімдору."}},faq={{q="Навіщо це завдання?",a="Це завдання завершує випробування друїдів Орди зі зцілення від отрут. Показавши дисципліну й урятувавши страждальних газелей звичайними ліками, учень повертається до Турака Рунтотема, щоб опанувати заклинання «Зцілення від отрути» через друїдське єднання з природою.",al={"навіщо влада над отрутою","що робить це завдання","мета завдання друїда про отруту"}},{q="Де знайти Турака Рунтотема?",a="Турак Рунтотем живе на Узвишші Старійшин у Тандер Блафі — серед наметів і видовбаних гнізд, де друїди-таурени єднаються з природою й навчаються.",al={"де турак рунтотем","де турак","знайти турака рунтотема"}},{q="Хто відправляє друїда назад до Тандер Блафа?",a="Дендрит Старблейз, друїд нічних ельфів із Кола Кенарія, що перебуває у священному притулку Місячного Гаю, відправляє учня назад до наставника, коли той успішно вилікує тварин біля Перехрестя.",al={"хто дає владу над отрутою","видавець завдання","дендрит старблейз"}},{q="Чому Коло Кенарія змусило друїда спершу лікувати звірів власноруч?",a="Дендрит Старблейз наголошує: перш ніж володіти легкою духовною магією, друїд має зрозуміти, що означає лікувати отруту самою працею, у межах смертних можливостей. Відчувши біду вражених істот, учень навчається співчуття й поваги до рівноваги природи.",al={"чому лікувати вручну","чому спершу мазі","урок друїда про отруту"}},{q="Що непокоїть Турака Рунтотема в подіях на Перехресті?",a="Турак глибоко стривожений тим, що тварин Пусток довкола Перехрестя отруюють неприродні, агресивні отрути. Він вважає таке забруднення тяжким порушенням рівноваги землі, яке вимагає пильності й надалі.",al={"турак і перехрестя","перехрестя отрута рівновага"}},{q="Чи доступне це завдання друїдам Альянсу?",a="Друїди Альянсу проходять схоже випробування з тією самою назвою. Тільки замість Турака Рунтотема на Узвишші Старійшин учні з нічних ельфів завершують урок у Матренґіла Берволкера в Дарнасусі.",al={"чи нічні ельфи можуть це взяти","влада над отрутою альянс"}}},fp="17,300,21.494.0,24.465.0,34.271.0,33.158.0,42.206.0,70.273.0,51.234.0,43.215.0"}
P.entries["quest:6181"] = {n="Спішне послання",s="Інтендантові Льюїсу в Сентінел Гіллі терміново потрібні обладунки зі Стормвінда, щоб спорядити Народне ополчення. Вестфол майже не отримує офіційної військової допомоги, тож він відправляє вас до майстра грифонів Тора — доставити термінову заявку до столиці повітрям.",h="Інтендантові Льюїсу в Сентінел Гіллі терміново потрібні обладунки зі Стормвінда, щоб спорядити Народне...",kw={"спішне послання","інтендант льюїс","тор","осрік стренг","грифон","сентінел гілл"},ang={["faction:Alliance"]="Доручення оголює глибокий розрив у постачанні між величною столицею Стормвінда та її знесиленими прикордонними заставами у Вестфолі.",["race:Human"]="Для людей королівства записка Льюїса показує, в якому тяжкому стані провінції Стормвінда, і знайомить із важливими грифоновими шляхами, що пов'язують рідні землі."},sec={{t="Благання через небеса",b="Сентінел Гілл стоїть самотою проти дедалі більшої хвилі розбійників Дефіасу й гнолів, позбавлений прямої військової допомоги від Стормвінда. Інтендант Льюїс покладається на приватні зв'язки в столиці, щоб Народне ополчення мало зброю й обладунки. Спорядження дедалі менше, і його єдина рятівна ниточка — Осрік Стренг, бронник зі Старого Міста. Щоб термінова заявка швидко дійшла до нього, Льюїс просить мандрівників звернутися до майстра грифонів Вестфолу — Тора."},{t="Мережа польотів",b="Грифони дають Королівству Стормвінд неоціненну мережу швидкого сполучення й кур'єрського зв'язку. Тор, що облаштувався в Сентінел Гіллі, опікується повітряним сполученням застави зі столицею. Записка Льюїса, передана Торові, відкриває небесний шлях між Вестфолом і королівським містом і показує, наскільки важливі вершники грифонів для прикордонних гарнізонів, відрізаних від офіційної допомоги."}},faq={{q="Навіщо Інтендантові Льюїсу надсилати записку до Стормвінда?",a="Вестфол майже не отримує військової допомоги від уряду Стормвінда, і Народному ополченню катастрофічно бракує обладунків. Льюїс мусить звернутися до надійного купця в місті, Осріка Стренга, щоб роздобути нове спорядження.",al={"навіщо надсилати записку","навіщо записка льюїса","чому писати до стормвінда"}},{q="Хто такий Осрік Стренг?",a="Осрік Стренг — майстер обладунків, чия крамниця «Обмежений імунітет» розташована в Старому Місті Стормвінда. Коли офіційні канали підводять, він — надійний приватний постачальник Льюїса.",al={"осрік стренг","хто такий осрік","власник обмеженої недоторканності"}},{q="Хто такий Тор?",a="Тор — розпорядник грифонів на Сентінел Гіллі. Він доглядає летючих скакунів, що з'єднують Вестфол зі Стормвіндом, і завдяки ним кур'єри й мандрівники швидко долають шлях.",al={"хто такий тор","політний майстер вестфолу","майстер грифонів тор"}},{q="Чому Стормвінд не надсилає до Вестфолу солдатів і спорядження напряму?",a="Король Варіан Рінн зник, ресурсів бракує, тож керівництво Стормвінда здебільшого занедбало віддалені фермерські землі. Прикордонним заставам на кшталт Сентінел Гілла доводиться виживати завдяки добровольчим ополченням і приватним домовленостям.",al={"чому стормвінд не допомагає","чому стормвінд ігнорує вестфол","де армія"}},{q="Чи може будь-який шукач пригод узятися за це доручення?",a="Це доручення дають саме шукачам пригод-людям, які вже проявили себе у Вестфолі; воно знайомить їх із мережею перельотів королівства на грифонах.",al={"хто може взяти це завдання","завдання лише для людей","чи дворфи можуть це завдання"}},{q="Куди веде це кур'єрське доручення далі?",a="Коли ви віддасте записку Торові, він приготує грифона до перельоту просто в Стормвінд; там ви підете до Дунґара Лонґдрінка, розпорядника грифонів столиці, а тоді розшукаєте Осріка Стренга в Старому Місті.",al={"наступний крок","що після тора","куди йти далі"}}},fp="15,269,23.481.0,18.370.0,62.223.0,20.175.0,12.161.0,67.235.0,39.172.0,42.197.0"}
P.entries["quest:62"] = {n="Копальня Фарґодіп",s="Маршал Дуґан із Ґолдшира доручає розвідникам перевірити повідомлення, що Копальню Фарґодіп захопили кобольди. Копальня лежить на південь від містечка, між фермами Стоунфілдів і Маклурів, і її падіння свідчить про дедалі більшу навалу шкідників по всьому Лісі Елвінн.",h="Маршал Дуґан із Ґолдшира доручає розвідникам перевірити повідомлення, що Копальню Фарґодіп захопили кобольди.",kw={"копальня фарґодіп","кобольди","маршал дуґан","ґолдшир","розвідка","стоунфілди","маклури"},ang={["faction:Alliance"]="Захоплена копальня — ще один виразний знак того, що влада Стормвінда в Елвінні слабне, а місцева варта ледве захищає найнеобхідніше господарство.",["profession:Mining"]="Багаті мідні жили Копальні Фарґодіп життєво важливі для ковалів-початківців, та щоб їх розробляти, доведеться прорубуватися крізь кобольдів, які бережуть свою територію."},sec={{t="Клопіт на південь від Ґолдшира",b="Поки Долина Нортширу давала раду власним шкідникам, до Ґолдшира дійшли тривожні вісті: кобольди захопили ще одне важливе місце. Копальня Фарґодіп, що притулилася між ворогуючими садибами Стоунфілдів і Маклурів на південь від містечка, колись давала королівству камінь і руду. Тепер вогкі тунелі сповнені пронизливого цвірінькання й мерехтіння лойових свічок, і Маршал Дуґан посилає шукачів пригод розвідати глибини й підтвердити найгірше."},{t="Виснажена варта",b="Підтверджена навала лише додає головного болю вартовим Стормвінда. Регулярні війська розтягнуті між обороною від бандитів Дефіас і нападами гнолів, тож варті бракує людей, щоб одразу зачистити копальню. Похмура реакція Дуґана на підтвердження показує, як поступово вислизає з рук контроль над серцем королівства, і він одразу починає тривожитися за інші рудні місця — зокрема за Яшмову копальню на північному сході."}},faq={{q="Де розташована Копальня Фарґодіп?",a="Копальня Фарґодіп лежить майже точно на південь від Ґолдшира в Лісі Елвінн, якраз між садибами Стоунфілдів і Маклюрів.",al={"де фарґодіп","де копальня фарґодіп","карта копальні фарґодіп"}},{q="Хто посилає розвідати Копальню Фарґодіп?",a="Маршал Дуґан, командир Варти Стормвінда в Ґолдширі, доручає розвідати тунелі.",al={"хто дає завдання фарґодіп","завдання маршала дуґана"}},{q="Які істоти захопили копальню?",a="Копальню цілком заполонили кобольди: вони там окопалися, запалили свої свічки й витіснили робітників-людей.",al={"хто у фарґодіпі","які чудовиська у фарґодіпі"}},{q="Чому Маршалові Дуґану потрібні шукачі пригод, щоб перевірити копальню?",a="Варта Стормвінда й так ледве дає раду з місцевими розбійниками, рештками орків і набігами гнолів, тож у Дуґана немає вільних солдатів навіть для того, щоб перевірити звичайні донесення розвідників.",al={"чому розвідувати","чому вартові не йдуть"}},{q="Що буде після розвідки Копальні Фарґодіп?",a="Коли ви доповісте Маршалові Дуґану погані новини, він злякається, що біда поширилася, і відправить вас на північний схід — перевірити ще й Яшмову копальню.",al={"наступне завдання після фарґодіпа","що далі"}},{q="Чому захоплення Копальні Фарґодіп таке важливе?",a="Падіння Фарґодіпу доводить, що навала кобольдів у Нортширі не була поодиноким випадком. Воно показує, як швидко дикі загрози підступають до обжитих фермерських земель просто під брамою Стормвінда.",al={"чому фарґодіп важливий","переказ про копальню фарґодіп"}}},fp="18,257,26.450.0,16.435.0,36.127.0,42.132.0,40.117.0,59.193.0,47.150.1,53.200.0"}
P.entries["quest:6261"] = {n="Дунґар Лонґдрінк",s="Це доручення знайомить шукачів пригод із Дунґаром Лонґдрінком, головним майстром грифонів Стормвінда. Забравши в Осріка Стренга термінові припаси, гінці мають домовитися про швидкий переліт, щоб доставити спорядження захисникам Вестфолу, які ледве тримають оборону.",h="Це доручення знайомить шукачів пригод із Дунґаром Лонґдрінком, головним майстром грифонів Стормвінда.",kw={"дунґар лонґдрінк","грифон","осрік стренг","вестфол","інтендант льюїс","стормвінд"},ang={["faction:Alliance"]="Грифонові шляхи між Стормвіндом і місцевими поселеннями життєво важливі для підтримання ладу, поки головне військо королівства перебуває далеко.",["race:Dwarf"]="Дворфійські приборкувачі, як-от Дунґар Лонґдрінк і Тор, несуть давній зв'язок свого народу з грифонами в саме серце людського королівства.",["race:Human"]="Відколи Дім Вельмож забув про Вестфол, окремі торговці й місцеві приборкувачі мусять співпрацювати напряму, щоб прикордонні застави мали зброю."},sec={{t="Життєво важливе постачання",b="Вестфол на межі: його виснажують розбійники Дефіас і здичавілі жнивні големи, тож Інтендант Льюїс і Народне ополчення відчайдушно потребують припасів. Коли Льюїс надіслав до столиці прохання про нове спорядження, бронник Осрік Стренг спакував усе, що просили. Везти військовий вантаж пішки розбійницькими шляхами Елвінну й Вестфолу — це втрата дорогоцінного часу, тож нові повітряні маршрути королівства стають рятівною артерією."},{t="Господар гнізда",b="Дунґар Лонґдрінк, що облаштувався в Торговому Кварталі, керує кур'єрськими й пасажирськими грифонами Стормвінда. Цих величних звірів здавна вирощують і приборкують дворфи Вайлдгаммер, і вони надійно переносять вантажі й людей над людськими землями — аби лише гнізда на обох кінцях шляху знали одне одного. Принісши важку скриню Осріка просто до Дунґара, гінці дізнаються, як працює повітряне сполучення, і прокладають прямий зв'язок між складами столиці та прикордонними заставами на кшталт Сентінел Гілла."}},faq={{q="Хто такий Дунґар Лонґдрінк?",a="Дунґар Лонґдрінк — розпорядник грифонів Стормвінда, що стоїть біля Торгового Кварталу, поруч із грифонячим сідалом. Він опікується кур'єрськими звірами столиці й наглядає за перевезенням пасажирів по всіх землях Альянсу в південному Лордероні й Азероті.",al={"дунґар","хто такий дунґар","майстер грифонів стормвінда"}},{q="Чому Осрік відправляє цей ящик грифоном?",a="Інтендантові Льюїсу й Народному ополченню у Вестфолі вкрай бракує спорядження, щоб відбиватися від бандитів. Пішки чи возом важкий вантаж ішов би кілька днів і ризикував потрапити в засідку, а навчений грифон перенесе припаси Осріка через кордони за лічені хвилини.",al={"чому грифон","чому не пішки","осрік доставка ящика"}},{q="Хто такий Тор і чому спершу треба поговорити з ним?",a="Тор — розпорядник грифонів на Сентінел Гіллі у Вестфолі. Грифонів навчають літати певними маршрутами від точки до точки, тож скакуни Дунґара можуть віднести вас назад до Вестфолу лише тоді, коли ви вже проклали шлях, відмітившись у Тора на іншому кінці.",al={"хто такий тор","чому йти до тора","грифон тора"}},{q="Що буде, коли Дунґар прийме ящик?",a="Оглянувши вантаж, Дунґар готує грифона до польоту й доручає вам доставити ящик просто Інтендантові Льюїсу на Сентінел Гілл.",al={"що далі","повернутися до льюїса","наступне завдання"}},{q="Яке місце це завдання посідає в ланцюжку перельотів?",a="Це третій крок вступного навчання користуватися мережею перельотів: воно починається у Вестфолі зі «Спішного послання», веде до Стормвінда через «Далі до Стормвінда», знайомить із Дунґаром і завершується «Поверненням до Льюїса».",al={"ланцюжок завдань","ланцюжок перельотів","скільки завдань"}},{q="Чому Стормвінд покладається на дворфійських грифонів?",a="Відтоді як Друга війна об'єднала Альянс Лордерону з кланом Вайлдгаммерів із Пригір'я, грифони стали найкращими розвідниками й перевізниками королівств Альянсу: вони швидко долають шлях, оминаючи зруйновані дороги й ворожі заслони.",al={"чому грифони в стормвінді","переказ про грифонів альянсу"}}},fp="16,263,20.452.0,23.476.0,24.255.0,44.265.0,47.262.0,44.149.0,48.215.0,44.265.0"}
P.entries["quest:6281"] = {n="Далі до Стормвінда",s="Це доручення знайомить шукачів пригод у Вестфолі зі швидкістю й зручністю грифонової мережі Королівства Стормвінд. З терміновою заявкою із Сентінел Гілла мандрівники летять просто до Старого Міста, щоб передати звістку торговцеві Осрікові Стренгу.",h="Це доручення знайомить шукачів пригод у Вестфолі зі швидкістю й зручністю грифонової мережі Королівства...",kw={"далі до стормвінда","тор","осрік стренг","старе місто","грифон","інтендант льюїс"},ang={["faction:Alliance"]="Мережа польотів, яку підтримують майстри грифонів, з'єднує розкидані застави Альянсу й тримає віддалені гарнізони на зв'язку зі столицею.",["race:Human"]="Повернення до Старого Міста показує, наскільки відірваними від політики величного Дому Вельмож почуваються прості городяни й самотні мешканці прикордоння."},sec={{t="На крилах",b="Коли Інтендант Льюїс у Сентінел Гіллі складає заявку, місцевий майстер грифонів Тор пропонує найшвидший шлях геть зі спірних рівнин. За скромну плату мандрівники сідають на одного з навчених грифонів королівства й злітають над курними нивами, над річковим кордоном Лісу Елвінн і над високими білими мурами самого Стормвінда."},{t="Постачання зі Старого Міста",b="Приземлившись у торговому гнізді столиці, гонець вирушає до Старого Міста, щоб знайти Осріка Стренга в його крамниці «Обмежений імунітет». Осрік постачає прикордонню спорядження й припаси, хоча його похмура зустріч показує, як поглиблюється розрив між знесиленим Народним ополченням у Вестфолі й неуважними правителями у Фортеці Стормвінда."}},faq={{q="Навіщо це завдання?",a="Завдання — практичне знайомство з грифонячими маршрутами Альянсу: воно вчить шукачів пригод швидко подорожувати між віддаленими заставами й столицею.",al={"навіщо це завдання","мета завдання","ціль далі до стормвінда"}},{q="Де знайти Осріка Стренга?",a="Осрік Стренг тримає крамницю «Обмежений імунітет» на звивистих вулицях Старого Міста в Стормвінді.",al={"де осрік стренг","знайти осріка стренга","де обмежена недоторканність"}},{q="Навіщо Сентінел Гіллу припаси зі Стормвінда?",a="Народне ополчення на Сентінел Гіллі ледве тримається проти Братства Дефіас і майже не отримує офіційної військової допомоги зі столиці, тож Інтендант Льюїс змушений купувати спорядження просто в цивільних купців.",al={"чому потрібні припаси","проблема постачання вестфолу","спорядження сентінел гілл"}},{q="Хто такий Тор?",a="Тор — розпорядник грифонів Альянсу на Сентінел Гіллі; він відає маршрутами, що з'єднують Вестфол зі Стормвіндом та іншими дружніми осередками.",al={"хто такий тор","майстер грифонів вестфолу","тор вестфол"}},{q="Що в Записці Льюїса?",a="Це термінова заявка Інтенданта Льюїса з переліком спорядження й провіанту, яких конче потребує гарнізон Сентінел Гілла.",al={"записка льюїса","що в записці","вміст записки"}},{q="Що буде після доставки записки?",a="Отримавши заявку, Осрік скеровує вас до стормвіндського розпорядника грифонів Дунґара Лонґдрінка, щоб домовитися про доставку замовлених припасів назад до Вестфолу.",al={"що далі","наступне завдання","після осріка стренга"}}},fp="21,268,11.357.0,21.336.0,34.174.0,30.113.0,52.218.0,12.153.0,27.148.0,39.179.0"}
P.entries["quest:6282"] = {n="Загроза гарпій",s="«Загроза гарпій» — завдання Орди, яке дає Маґґран Ертбайндер у Притулку Сонячної Скелі в Горах Кам'яного Кігтя. Виконуючи покликання тауренів як охоронців землі, шукачі пригод вирушають на південь, у спустошену Обвуглену Долину, щоб прорідити дедалі численніші лави гарпій із ковену Бладф'юрі.",h="«Загроза гарпій» — завдання Орди, яке дає Маґґран Ертбайндер у Притулку Сонячної Скелі в Горах Кам'яного...",kw={"загроза гарпій","гарпії","бладф'юрі","обвуглена долина","маґґран ертбайндер","притулок сонячної скелі"},ang={["class:Druid"]="Викривлена присутність ковену Бладф'юрі оскверняє й без того крихку, сплюндровану вогнем природу Обвугленої Долини.",["class:Shaman"]="На прохання Маґґрана Ертбайндера шамани відгукуються на поклик очистити край від агресивних осквернителів, що порушують природну рівновагу стихій.",["faction:Horde"]="Очищене небо над Обвугленою Долиною зміцнює опору Орди в Притулку Сонячної Скелі проти небезпечних диких сил, що населяють Гори Кам'яного Кігтя.",["race:Tauren"]="Для тауренів знищення Бладф'юрі, що насуваються на їхні землі, — почесний обов'язок, виконання давньої обіцянки предків бути захисниками дикої природи Калімдору."},sec={{t="Захисники землі",b="Таурени з Притулку Сонячної Скелі мають глибокий обов'язок оберігати Гори Кам'яного Кігтя: підтримувати природну рівновагу й захищати мирних мандрівників від небезпек краю. Маґґран Ертбайндер, старійшина й провідник притулку, з дедалі більшою тривогою спостерігає, як невпинно множаться місцеві гарпії. Ковен Бладф'юрі розповзся випаленими пустирями Обвугленої Долини, нападає на звірів, що проходять повз, і перекриває шляхи. Якщо його не спинити, хижі зграї загрожують повністю відрізати Притулок Сонячної Скелі від світу."},{t="Зачистка Обвугленої Долини",b="На південь від Притулку Сонячної Скелі лежить Обвуглена Долина — безлюдна пустка з попелу, випаленої землі й тліючих дерев, що лишилися після нищівних пожеж. Тут, гніздячись високо в обгорілих рештках прадавніх лісів, Бладф'юрі звели собі твердиню. Маґґран доручає воякам Орди вирушити в цю ворожу улоговину й знищити десятки гарпій — засідниць, убивць і крадійок-пернатих. Прорідивши зграю, вони зламають хватку ковену на долині й розчистять шлях до прямого двобою з родом його матріархів."}},faq={{q="Хто дає завдання «Загроза гарпій»?",a="Завдання дає Маґґран Ертбайндер, таурен, що стоїть біля водойми посеред Притулку Сонячної Скелі в Горах Кам'яного Кігтя.",al={"хто дає загрозу гарпій","де взяти загрозу гарпій","завдання маґґрана ертбайндера"}},{q="Де живуть гарпії Бладф'юрі?",a="Гарпії Бладф'юрі населяють Обвуглену Долину — випалений простір просто на південь від Притулку Сонячної Скелі. Гірська стежка позаду Сонячної Скелі веде прямо вниз, у долину.",al={"де гарпії бладф'юрі","місця гарпій бладф'юрі","гарпії обвугленої долини"}},{q="Чому таурени хочуть проріджувати гарпій?",a="Таурени вважають себе охоронцями природної рівноваги Гір Кам'яного Кігтя. Маґґран Ертбайндер боїться, що Бладф'юрі агресивно розселяються Калімдором, нападають на невинних і не дають живим істотам вільно мандрувати цим краєм.",al={"чому вбивати гарпій","конфлікт тауренів і гарпій","чому маґґран ненавидить гарпій"}},{q="Що буде після завдання «Загроза гарпій»?",a="Виконавши «Загрозу гарпій», ви відкриєте наступне завдання — «Родовід Бладф'юрі», у якому Маґґран Ертбайндер посилає вас знищити ватажків ковену Бладф'юрі.",al={"наступне завдання загроза гарпій","продовження загрози гарпій","що після загрози гарпій"}},{q="Це завдання лише для Орди?",a="Так. Завдання пропонують тільки Орді, у поселенні Притулок Сонячної Скелі.",al={"чи альянс може загрозу гарпій","загроза гарпій лише для орди","альянс загроза гарпій"}},{q="Яких гарпій треба вбити?",a="Треба вбити по сім гарпій Бладф'юрі, засадниць Бладф'юрі, убивць Бладф'юрі й розбійниць Бладф'юрі в Обвугленій Долині.",al={"яких гарпій вбивати","типи гарпій обвугленої долини","цілі загрози гарпій"}}},fp="16,288,22.518.0,25.538.0,37.139.0,40.183.0,42.251.0,45.175.0,25.91.0,36.149.0"}
P.entries["quest:6283"] = {n="Родовід Бладф'юрі",s="«Родовід Бладф'юрі» — завдання Орди від Маґґрана Ертбайндера в Притулку Сонячної Скелі: убити ватажку гарпій Бладф'юрі. Це полювання — вінець зусиль Маґґрана очистити Обвуглену Долину, і воно має зламати люту хватку зграї над пораненою дикою землею.",h="«Родовід Бладф'юрі» — завдання Орди від Маґґрана Ертбайндера в Притулку Сонячної Скелі: убити ватажку гарпій...",kw={"родовід бладф'юрі","потрошителька бладф'юрі","гарпії","обвуглена долина","маґґран ертбайндер","притулок сонячної скелі"},ang={["faction:Horde"]="Захищені підступи до Притулку Сонячної Скелі вберігають єдину оселю Орди, що сховалася глибоко в спірних Горах Кам'яного Кігтя.",["race:Tauren"]="Понівечений край Гір Кам'яного Кігтя завдає тауренам болю, і усунення лютої королеви гарпій дає місцевим шаманам, як-от Маґґранові, змогу знову звернути думки до гармонії та зцілення."},sec={{t="Удар по матроні",b="Винищення дрібніших гарпій на краю Обвугленої Долини приносить Притулку Сонячної Скелі лише тимчасове полегшення. Маґґран Ертбайндер переконаний: єдиний надійний спосіб приборкати їхню агресію — знищити їхню матріарху, Потрошительку Бладф'юрі. Зграя шанує її майже як королеву й черпає безжальну злагодженість і зухвальство просто з її проводу на скелястому західному гребені."},{t="Мир у землі",b="Щойно Потрошителька Бладф'юрі падає, а її рештки приносять як доказ, безпосередня загроза притулкові вщухає. Без своєї королеви-праматері розладнані гарпії вже не такі страшні, і стримувати їх стає набагато легше. Перемога знімає духовний тягар і з самого Маґґрана: звільнившись від гіркої пильності, він може повернутися до звичного для тауренів пошуку гармонії й рівноваги."}},faq={{q="Хто дає завдання «Родовід Бладф'юрі»?",a="Завдання дає Маґґран Ертбайндер, шаман-таурен, що стоїть біля водойми в Притулку Сонячної Скелі.",al={"хто дає родовід бладф'юрі","хто починає родовід бладф'юрі","завдання маґґрана ертбайндера"}},{q="Що треба виконати, перш ніж відкриється це полювання?",a="Спершу треба виконати «Загрозу гарпій»: у цьому завданні Маґґран посилає вас до Обвугленої Долини, щоб проріджувати лави гарпій Бладф'юрі.",al={"що потрібно перед родоводом бладф'юрі","попереднє завдання родоводу бладф'юрі","продовження загрози гарпій"}},{q="Де знайти Потрошительку Бладф'юрі?",a="Вона нишпорить кам'янистими пагорбами вздовж північно-західного краю Обвугленої Долини. Від решти зграї її легко відрізнити за синім забарвленням.",al={"де потрошителька бладф'юрі","знайти потрошительку бладф'юрі","поява потрошительки бладф'юрі"}},{q="Чому Маґґран хоче смерті Потрошительки Бладф'юрі?",a="Маґґран бачить у Потрошительці Бладф'юрі королеву, що веде зграю в її лютому захопленні нових земель. Убивши її, ви розколете їхнє проводирство й назавжди послабите їхню хватку на долині.",al={"чому вбити потрошительку бладф'юрі","переказ про ватажка гарпій","мотив маґґрана ертбайндера"}},{q="Як смерть Потрошительки Бладф'юрі впливає на тауренів Притулку Сонячної Скелі?",a="Її смерть дарує Маґґранові душевний спокій: він звільняється від затятого гніву й постійного страху перед нападом і може знову зосередитися на зціленні землі.",al={"переказ про гарпій кам'яного кігтя","що буде після смерті потрошительки","реакція маґґрана"}},{q="Як найшвидше дістатися з Притулку Сонячної Скелі до Обвугленої Долини?",a="Гірська стежка веде просто з тилу Притулку Сонячної Скелі: вона оминає звивисті головні дороги Кам'яного Кігтя й спускається прямо в Обвуглену Долину.",al={"як дістатися обвугленої долини з сонячної скелі","зворотний шлях притулку сонячної скелі","скорочення до обвугленої долини"}}},fp="19,275,19.400.0,18.386.0,40.117.0,60.141.0,34.148.0,44.195.0,72.172.1,74.159.0"}
P.entries["quest:6284"] = {n="Арахнофобія",s="«Арахнофобія» — завдання Орди за винагороду: ціль — Бесселет, прадавня велетенська хижачка, що тероризує південь Гір Кам'яного Кігтя. Оголошення біля дороги поблизу Кручі Вітрорізу кличе шукачів пригод у Каньйон Сішир, щоб здобути ікло павучої матріархи для Маґґрана Ертбайндера в Притулку Сонячної Скелі. Поклавши край її владі, ви зробите гірські дороги безпечнішими для нічних мандрівників.",h="«Арахнофобія» — завдання Орди за винагороду: ціль — Бесселет, прадавня велетенська хижачка, що тероризує...",kw={"арахнофобія","бесселет","павучиха","каньйон сішир","маґґран ертбайндер","ікло бесселет"},ang={["class:Hunter"]="Вистежити невловиму велетенську павучиху серед затінених круч Каньйону Сішир — справжнє випробування для гірського мисливця.",["faction:Horde"]="Знищення Бесселет робить безпечнішим шлях до Притулку Сонячної Скелі й захищає життєво важливу опору Орди серед центральних круч Гір Кам'яного Кігтя.",["race:Tauren"]="Маґґран Ертбайндер носить болючий шрам від отрути Бесселет, тож це полювання — справа честі й допомога побратимові, синові землі."},sec={{t="Попередження біля дороги",b="Мандрівники на головному шляху на південь від Кручі Вітрорізу помітять вицвіле оголошення про розшук, що попереджає про небезпеку на заході. Каньйон Сішир і Стежка Павутинника геть кишать восьминогими хижаками. У самому серці цього павутинного лиха сидить Бесселет — незвично велика павучиха помаранчевого кольору, що керує своїм виводком і нападає з засідки на кожного, хто наважиться зійти зі стежки після заходу сонця."},{t="Кривда Ертбайндера",b="Нагороду за Бесселет призначив Маґґран Ертбайндер, таурен із Притулку Сонячної Скелі. У Маґґрана з матріархою особисті рахунки: під час минулої зустрічі він ледь не загинув, коли Бесселет уразила його своїм величезним іклом завдовжки у два фути. Хоч йому й вдалося відбитися й, накульгуючи, дістатися безпечного місця, рана, що досі не загоїлася, постійно нагадує про небезпеку, яка чатує в тінях каньйону. Доручивши шукачеві пригод здобути Ікло Бесселет, Маґґран сподівається убезпечити перевали, щоб торгівля й подорожі до Притулку Сонячної Скелі процвітали без страху."}},faq={{q="Де починається завдання «Арахнофобія»?",a="Завдання починається з оголошення про розшук, вивішеного на західному узбіччі головної дороги в Горах Кам'яного Кігтя, трохи на південь від входу до Кручі Вітрорізу.",al={"де взяти арахнофобію","де оголошення бесселет","як почати арахнофобію"}},{q="Де знайти Бесселет?",a="Бесселет має лігво в Каньйоні Сішир, що трохи на захід від оголошення при дорозі. Вона никає серед свого павучого виводку по обплутаному павутинням дну каньйону.",al={"де бесселет","де знайти бесселет","знайти павучиху бесселет"}},{q="Хто такий Маґґран Ертбайндер?",a="Маґґран Ертбайндер — таурен із Притулку Сонячної Скелі в Горах Кам'яного Кігтя. Він сам пережив отруйний укус Бесселет і призначив нагороду, щоб позбавити каньйон цієї загрози.",al={"хто такий маґґран","роль маґґрана ертбайндера","кому здати арахнофобію"}},{q="Чому Бесселет така небезпечна для краю?",a="Бесселет — надзвичайно велика й безжальна павучиха, що полює в Каньйоні Сішир і на сусідній Стежці Павутинника. Вона та її виводок під покровом ночі нападають на мандрівників, загрожуючи кожному, хто намагається дістатися Притулку Сонячної Скелі.",al={"чому бесселет небезпечна","що зробила бесселет"}},{q="Який доказ потрібен, щоб отримати нагороду?",a="Треба вбити Бесселет і відтяти одне з її величезних іклів, завдовжки зо два фути. Віддавши Ікло Бесселет Маґґранові Ертбайндеру в Притулку Сонячної Скелі, ви отримаєте нагороду.",al={"доказ бесселет","предмет завдання бесселет","що випадає з бесселет"}},{q="Чи доступне це завдання Альянсу?",a="Ні. Нагороду за оголошенням видає Маґґран Ертбайндер у Притулку Сонячної Скелі — таборі Орди, тож «Арахнофобія» доступна лише Орді.",al={"чи альянс може арахнофобію","завдання арахнофобія для альянсу"}}},fp="13,392,20.398.0,27.556.0,41.169.0,29.162.0,27.200.0,45.237.0,43.162.0,40.153.0"}
P.entries["quest:6285"] = {n="Повернення до Льюїса",s="«Повернення до Льюїса» — останній відтинок вступного кур'єрського перельоту, яким украй потрібний обладунок зі Стормвінда доставляють просто на Сентінел Гілл. Дунґар Лонґдрінк довіряє кур'єрам Ящик Осріка, і ті летять на грифонах небом Елвінну й Вестфолу, щоб поповнити запаси обложеного Народного ополчення.",h="«Повернення до Льюїса» — останній відтинок вступного кур'єрського перельоту, яким украй потрібний обладунок...",kw={"повернення до льюїса","інтендант льюїс","сентінел гілл","грифон","ящик осріка","дунґар лонґдрінк","народне ополчення"},ang={["class:Warrior"]="Кожен ящик нагрудників і поножів, доставлений на Сентінел Гілл, означає ще одного бійця ополчення, здатного витримати удари розбійників Дефіас.",["faction:Alliance"]="Налагоджені маршрути грифонів між Стормвіндом і віддаленими поселеннями на кшталт Сентінел Гілла конче потрібні, щоб скріпити дедалі розколотіше королівство.",["race:Dwarf"]="Уся система повітряних перевезень королівства тримається на дворфійській майстерності — від Дунґара Лонґдрінка на столичному сідалі до Тора у Вестфолі."},sec={{t="Рятівна нитка в небі",b="Вестфол вислизає з рук королівства: його облягають бандити Дефіас, ненажерливі гноли й механічні жниварки. Сухопутні шляхи постачання під ударами, дороги небезпечні для самотніх возів, тож мережа розпорядників польотів стає життєво важливою ниткою. Осрік, зброяр зі Старого Міста Стормвінда, підготував важкий ящик з обладунком, щоб підкріпити побитих добровольців Народного ополчення на Сентінел Гіллі."},{t="Звичаї грифонів",b="Грифони — надзвичайно вірні й добре вишколені звірі, та щоб вести їх над землями, потрібне знайомство з маршрутом. Як пояснює Дунґар Лонґдрінк кур'єрам-новачкам, грифони інстинктивно знають дорогу додому, до столичного сідала в Стормвінді, але понесуть вершника до віддаленої застави лише тоді, коли мандрівник особисто зустрівся з тамтешнім розпорядником польотів. Якщо ви вже відмітилися в Тора на Сентінел Гіллі, небо над прикордонням відкрите для швидких перельотів."},{t="Припаси для ополчення",b="Після приземлення на Сентінел Гіллі доставлений ящик приймає Інтендант Льюїс — офіцер, що споряджає добровольче військо Ґраяна Стаутмантла. Льюїс одразу береться роздавати обладунок захисникам прикордоння. Для Сентінел Гілла надійний повітряний зв'язок зі столицею — це різниця між утриманням лінії оборони й цілковитим розгромом від рук Братства Дефіас."}},faq={{q="Що в Ящику Осріка?",a="У ящику — щойно виготовлені обладунки, які підготував стормвіндський майстер Осрік. Їх конче чекає Народне ополчення на Сентінел Гіллі: королівського постачання воно не має й спорядження для своїх бійців-добровольців отримує лише з пожертв і приватних поставок.",al={"вміст ящика осріка","що в скрині","що я доставляю"}},{q="Хто такий Інтендант Льюїс?",a="Інтендант Льюїс відповідає за постачання Народного ополчення й стоїть біля вежі на Сентінел Гіллі. Він відає пайками, спорядженням і зброєю для добровольців, які боронять Вестфол від Братства Дефіас.",al={"льюїс вестфол","роль інтенданта льюїса","хто такий льюїс"}},{q="Хто такий Дунґар Лонґдрінк?",a="Дунґар Лонґдрінк — досвідчений розпорядник грифонів Стормвінда, дворф; його сідало — одразу за величною брамою столиці. Він відає повітряними маршрутами королівства для кур'єрів і пасажирів.",al={"дунґар стормвінд","майстер грифонів стормвінда","політний майстер стормвінда"}},{q="Чому грифони літають лише туди, де ви вже бували?",a="За словами Дунґара, грифонів привчено самостійно знаходити дорогу назад до столиці, але щоб доправити вершника на віддалене прикордонне сідало, як-от до Тора на Сентінел Гіллі, їм потрібні відомі орієнтири й знайомство з маршрутом.",al={"правило польоту грифонів","як працюють маршрути","чому спершу тор"}},{q="Хто такий Тор?",a="Тор — розпорядник польотів на Сентінел Гіллі у Вестфолі. Він доглядає грифонів застави й приймає повітряних кур'єрів зі Стормвінда.",al={"тор вестфол","майстер грифонів сентінел гілл","політний майстер тор"}},{q="Чому Стормвінд не може просто відправити припаси королівськими возами?",a="На дорогах між Лісом Елвінн і Вестфолом безчинствують бандити Дефіас, гноли Річколапів і злодії. Наземні обози ризикують потрапити в засідку й утратити вантаж, тож повітряний шлях грифоном набагато швидший і безпечніший.",al={"чому грифони","чому не по землі","дороги вестфолу"}}},fp="15,310,17.432.0,20.495.0,24.404.0,29.275.0,27.232.0,24.194.0,58.253.0,12.151.0,57.224.0"}
P.entries["quest:63"] = {n="Поклик води",s="Цей важливий обряд посвяти веде шаманів із Пусток за Велике море, до сплюндрованих берегів Срібнолісся. Щоб здобути право на єднання з духами води, новачок мусить зустрітися з оскверненим елементалем і очистити прадавнє прибережне святилище, сплюндроване чумою Погибелі.",h="Цей важливий обряд посвяти веде шаманів із Пусток за Велике море, до сплюндрованих берегів Срібнолісся.",kw={"поклик води","жаровня вічноджерела","срібнолісся","іслен вотерсір","брайн","шаман"},ang={["class:Shaman"]="Цей обряд доводить, що шаман — не лише той, хто кличе бурі, а й цілитель зламаних земель, покликаний очищати їх від духовної скверни.",["faction:Horde"]="Подорож у Срібнолісся змушує народжених у Калімдорі орків і тауренів на власні очі побачити похмурі, зачумлені злигодні їхніх союзників-Відступників."},sec={{t="Паломництво за море",b="Здобувши під наглядом самітниці Брайн краплі чистої води, шаман повертається на узбережжя Пусток, де чекає Іслен Вотерсір. Тоді Іслен доручає новачкові куди небезпечнішу справу: перенести цю очищену суть за море, на примарне узбережжя Срібнолісся, трохи на захід від притулку Відступників — Гробниці."},{t="Очищення Вічноджерела",b="Обране святилище — Жаровня Вічноджерела, прадавній стихійний фокус, чиї води спотворилися й стали ворожими під впливом чумної скверни Лордерону. Духи води, що жили тут, онімілі й здичавіли. Здолавши осквернену сутність, прив'язану до цього місця, і віддавши полум'ю жаровні і її наручі, і найчистішу воду, шаман розриває лещата помори й викликає неоскверненого духа припливів."}},faq={{q="Чому шаманові доводиться мандрувати аж до Срібнолісся?",a="Іслен Вотерсір вимагає, щоб шамани довели свою владу над скверною, а не лише вивчали спокій. Прибережне святилище на захід від Гробниці стало жертвою чуми Лордерону, тож учень має нагоду зцілити святилище стихій і знову пробудити духів води, які ні з ким іншим говорити не хочуть.",al={"чому йти до срібнолісся","чому подорож через море","чому водне завдання в срібноліссі"}},{q="Що станеться, коли скористатися Жаровнею Вічного Джерела?",a="Коли покласти у вогонь наручі переможеного елементаля разом з останніми краплями найчистішої води, почнеться обряд очищення, якого навчила Іслен. Ця потріскувальна пожертва очищає місцеву водойму й викликає чисте втілення води, готове дати своє благословення.",al={"подія жаровні вічного джерела","що робить жаровня","як очистити озеро"}},{q="Хто оскверняє святилище води в Срібноліссі?",a="Воду спотворила чума, що досі висить над занепалим королівством Лордерон. Скверна, що стікає з пагорбів, отруїла місцеве джерело й перетворила його духів води на здичавілих, ворожих потвор.",al={"хто осквернив святилище","чому прояв осквернений","осквернення води в срібноліссі"}},{q="Що я отримаю, пройшовши це випробування?",a="Очистивши Жаровню Вічного Джерела, ви зможете поспілкуватися з чистим духом води. Віднісши доказ очищення Іслен Вотерсір у Пустки, ви нарешті здобудете Тотем Води й завершите довге випробування «Поклик води».",al={"нагорода поклику води","відкрити тотем води","що я отримаю"}},{q="Де саме розташоване святилище?",a="Святилище стоїть просто на західному узбережжі Срібнолісся, за спустошеним хребтом трохи на захід від Гробниці.",al={"де жаровня вічного джерела","де святилище","координати святилища срібнолісся"}},{q="Хто така Іслен Вотерсір?",a="Іслен Вотерсір — відлюдниця, що єднається зі стихіями й живе на Узбережжі Крамарів Пусток, на південь від Раджета. Вона — шанована духовна провідниця, яка веде молодих шаманів Орди через важкі обряди, потрібні, щоб злагодитися зі стихією води.",al={"хто така іслен","історія іслен вотерсір","наставниця води в пустках"}}},fp="13,295,27.345.0,23.441.1,66.303.0,51.264.0,49.240.0,48.237.0,36.123.0,23.246.0"}
P.entries["quest:6301"] = {n="Цикл переродження",s="«Цикл переродження» — завдання Орди, яке дає Таммра Віндфілд у Притулку Сонячної Скелі: зібрати рідкісне насіння Геї на берегах Озера Міркфаллон. Засмучена тим, яку ціну платять Гори Кам'яного Кігтя за промислову жадобу й нескінченні війни, Таммра хоче благословити ці витривалі зернята шаманською силою, щоб оживити сплюндровану землю гір. Це перший і найважливіший крок у зціленні пораненої дикої природи.",h="«Цикл переродження» — завдання Орди, яке дає Таммра Віндфілд у Притулку Сонячної Скелі: зібрати рідкісне...",kw={"цикл переродження","таммра віндфілд","насіння геї","озеро міркфаллон","земна мати","шаман"},ang={["class:Druid"]="Друїди оцінять, що й тут ідеться про природні цикли та вирощування насіння: відродження мертвої землі прямо перегукується з кенарійським опікуванням природою.",["class:Shaman"]="Зусилля Таммри відбивають шаманське покликання — виправляти порушену рівновагу природи: духи й Земна Мати здатні відновити те, що руйнує промисловий визиск.",["race:Tauren"]="Для шу'гало зцілення пораненої землі Гір Кам'яного Кігтя — духовний обов'язок перед Земною Матір'ю, відповідь на спустошення, яке принесли безрозсудні вирубки й війни між фракціями."},sec={{t="Поранена глушина",b="Вершини Гір Кам'яного Кігтя несуть глибокі рани і від торговельного визиску, і від нескінченних місцевих чвар. Через загарбницькі вирубки й сутички ворожих сил цілі смуги лісу випалено, вирубано дочиста чи обернено на попіл. Для тауренів із Притулку Сонячної Скелі бачити, як стрімко нищиться природа, — тяжка рана. Шамани на кшталт Таммри Віндфілд не лише борються за кожну п'ядь землі, а й звертаються до давнього природного ладу, прагнучи запустити цілющий цикл Земної Матері."},{t="Насіння з Міркфаллону",b="Щоб повернути життя мертвій землі, потрібна надзвичайна життєва сила, і Таммра знаходить її в рідкісному насінні Геї, що росте довкола Озера Міркфаллон. На березі цього озера, на північ від Притулку Сонячної Скелі, біля самої води визрівають міцні насінні коробочки. Хоч довкола чигає чимало небезпек, це насіння має природну витривалість, властиву лише Горам Кам'яного Кігтя. Коли його принесуть, Таммра вливає в кожне зернятко благословення предків, пробуджуючи приховану силу, щоб прискорити ріст для майбутньої праці."}},faq={{q="Навіщо збирати насіння Ґеї?",a="Насіння Ґеї має виняткову природну життєву силу, тож чудово надається для відродження спустошених земель. Таммра Віндфілд збирає його, щоб наповнити благословеннями Земної Матері й шаманською силою — тоді воно швидко проросте й відновить ті частини Кам'яного Кігтя, які зруйнували промисловці й війна.",al={"навіщо насіння ґеї","для чого насіння ґеї","мета циклу переродження"}},{q="Де знайти насіння Ґеї?",a="Насіння Ґеї лежить на березі Озера Міркфаллон, просто на північ від Притулку Сонячної Скелі в Горах Кам'яного Кігтя. Його можна знайти в землі біля самої води по всьому периметру озера.",al={"де насіння ґеї","де знайти насіння ґеї","насіння озера мірквалон"}},{q="Хто така Таммра Віндфілд?",a="Таммра Віндфілд — шаманка-тауренка, що живе в Притулку Сонячної Скелі. Глибоко засмучена тим, як війни й лісозаготівельні синдикати винищили й спустошили Кам'яний Кіготь, вона присвячує себе зціленню землі благословеннями Земної Матері.",al={"хто така таммра","переказ про таммру віндфілд"}},{q="Що робить Таммра, коли отримує насіння?",a="Отримавши десять насінин Ґеї, Таммра заводить священний спів, щоб наповнити зерна шаманською енергією й пришвидшити їхній природний ріст, — тоді їх можна буде посадити в спустошених місцях.",al={"що з насінням","здати цикл переродження"}},{q="Яке завдання йде після «Циклу переродження»?",a="«Цикл переродження» веде просто до завдання «Нове життя», у якому насіння, сповнене сили, несуть у спустошену Обвуглену Долину, щоб знову дати там життя рослинам.",al={"продовження циклу переродження","наступне завдання після циклу переродження","що після циклу переродження"}},{q="Чому землі Кам'яного Кігтя потребують зцілення?",a="Гори Кам'яного Кігтя тяжко постраждали від безперервних війн і суцільних вирубок промислових лісозаготівельників: лишилися випалена земля й понівечені долини, які насилу заростають самі.",al={"чому кам'яний кіготь руйнується","що сталося з кам'яним кігтем"}}},fp="16,429,20.546.0,23.520.0,45.309.0,33.224.0,24.255.0,48.196.0,36.166.0,49.232.0"}
P.entries["quest:631"] = {n="Міст Тандол",s="Після нищівного вибуху, що струсонув північ Багнокраю, Раґ Ґармасон просить мандрівників обшукати зруйновані прольоти Мосту Тандол у пошуках зниклого дворфа-розвідника. Клан Темного Заліза жорстоко напав на Дун Модр, обірвавши зв'язок і лишивши місцевих захисників без підкріплень. Знайти Старого Растлока — перший крок до того, щоб збагнути повний розмах диверсії.",h="Після нищівного вибуху, що струсонув північ Багнокраю, Раґ Ґармасон просить мандрівників обшукати зруйновані...",kw={"міст тандол","раґ ґармасон","старий растлок","дун модр","темне залізо","багнокрай"},ang={["faction:Alliance"]="Міст Тандол — єдиний суходільний шлях постачання, що пов'язує Стормвінд і Айронфордж із силами Альянсу, які тримаються в Араті й Гілсбреді.",["race:Dwarf"]="Руйнування Мосту Тандол — образа дворфійському кам'яному ремеслу й прямий удар по Каз Модану від ненависних родичів із Темного Заліза."},sec={{t="Грім над мостом",b="Нещодавно нищівний вибух розірвав Міст Тандол, розтрощивши величезну кам'яну переправу між Багнокраєм і Аратійським нагір'ям. Вояки-Бронзбірди, що стояли на кордоні, потрапили під удар, коли дворфи Темного Заліза влаштували засідку на Дун Модр. Із порідшалими лавами й обложеними твердинями вцілілі під проводом Лонґбрейда Похмурого змушені вперто й відчайдушно оборонятися від нападників."},{t="Розвідник, посланий на схід",b="Сподіваючись урятувати переправу й з'ясувати, чи лишився придатний шлях на північ, Лонґбрейд відрядив досвідченого розвідника Ебенізера Растлока оглянути східний проліт. Минали дні без жодного донесення, але з Дун Модром в облозі Раґ Ґармасон і гарнізон не мають вояків, щоб послати рятувальний загін у руїни, захоплені ворогом."},{t="Похмура знахідка",b="Вийшовши на розтрощений міст, бачиш, якою ціною обернувся напад Темного Заліза. Старий Растлок не повернувся з розвідки — він загинув серед уламків східного прольоту. Його тіло й пергамент, затиснутий у кулаці, підтверджують найгірше: він натрапив на засідку Темного Заліза, а дворфи Темного Заліза ще не покінчили з цією життєво важливою артерією між Каз Моданом і Лордероном."}},faq={{q="Що таке Міст Тандол?",a="Міст Тандол — колосальна дворфійська споруда, перекинута через прірву між північчю Багнокраю й Аратійським нагір'ям. Це головний суходільний шлях, що з'єднує Каз Модан із північними землями Лордерону.",al={"міст тандол","що таке міст тандол","міст у мокрих землях"}},{q="Хто напав на Міст Тандол?",a="На міст і сусідню заставу Дун Модр напав клан дворфів Темного Заліза. Вони підірвали вибухівку, щоб перервати міст, паралізували переміщення Альянсу й заскочили зненацька оборонців із клану Бронзбірдів.",al={"хто підірвав міст","вибух мосту тандол","хто напав на дун модр"}},{q="Хто такий Старий Растлок?",a="Ебенезер Растлок був надійним дворфійським розвідником на службі в Лонґбрейди Похмурого. Його послали оцінити стан східної частини мосту після вибуху, але під час завдання сили Темного Заліза здолали його й убили.",al={"ебенезер растлок","хто такий растлок","зниклий розвідник"}},{q="Де знайти Раґа Ґармасона?",a="Раґ Ґармасон стоїть біля обложеного поселення Дун Модр, трохи на південь від Мосту Тандол на півночі Багнокраю. Він допомагає керувати обороною, поки гарнізон відрізаний від Айронфорджа.",al={"де раґ ґармасон","місце раґа","видавець у дун модрі"}},{q="Чому Айронфордж не надіслав допомогу до Дун Модра?",a="Раптовий напад, зруйнований міст і облога Дун Модра лишили гарнізон в ізоляції. Оборонців надто мало, щоб відправити гінців чи відрядити загони, тож вони залежать від мандрівних шукачів пригод, які можуть передати звістку.",al={"чому немає підкріплення","допомога айронфорджа мокрим землям","підкріплення дун модра"}},{q="Що буде, коли знайти тіло Растлока?",a="При останках Растлока лежить пергамент, з якого видно, що Кам Діпф'юрі, натхненник нападу, сховав запас вибухівки по той бік мосту. Так починаються спроби знищити схованку, перш ніж вибухівка дістанеться вцілілої частини мосту, а згодом — і пошуки ширшої допомоги через звернення до проводу Альянсу.",al={"наступне завдання після растлока","продовження мосту тандол","після мосту тандол"}}},fp="16,413,21.432.0,17.358.0,14.380.1,25.226.0,30.202.0,21.231.1,31.206.0,43.267.0,46.302.1"}
P.entries["quest:632"] = {n="Міст Тандол",s="Раґ Ґармасон доручає шукачам пригод провідати Старого Ебенізера Растлока — розвідника, якого послали оглянути величезну кам'яну переправу Мосту Тандол і з яким зник зв'язок. Пошуки під арками переправи розкривають обставини його зникнення й загрози північним шляхам постачання.",h="Раґ Ґармасон доручає шукачам пригод провідати Старого Ебенізера Растлока — розвідника, якого послали оглянути...",kw={"міст тандол","накази діпф'юрі","ебенізер растлок","раґ ґармасон","темне залізо","засідка"},ang={["faction:Alliance"]="Міст Тандол — артерія, що прив'язує Айронфордж і Стормвінд до північних твердинь Альянсу, тож знахідка біля тіла Растлока критично важлива для безпеки всього континенту.",["race:Dwarf"]="Те, що сили Темного Заліза діють так далеко на північ від Палючої Ущелини, показує, як глибоко сягає їхнє підступне проникнення, що загрожує побратимам з Айронфорджа."},sec={{t="Останній бій розвідника",b="Командир Лонґбрейд послав Ебенізера Растлока наглядати за цілістю й безпекою Мосту Тандол. Коли зв'язок із розвідником обірвався, одразу запідозрили лихе. Обшукавши закутки під арками, ви знаходите Растлока мертвим: він загинув у лютій засідці, яку з тіні влаштували загарбники з Темного Заліза."},{t="Накази Діпф'юрі",b="Біля стиснутих пальців Растлока знаходять письмові накази з ім'ям Діпф'юрі. Це не випадковий грабіж і не поодинока прикордонна сутичка: пергамент розкриває навмисні операції Темного Заліза, спрямовані на те, щоб розхитати переправу. Доставлений Ґармасонові доказ змінює настрій гарнізону — зі звичайного пошуку на нагальну воєнну оборону."}},faq={{q="Хто такий Ебенезер Растлок?",a="Ебенезер «Старий» Растлок — дворф Альянсу, якого відрядили розвідати Міст Тандол і пильнувати його. Його заскочили зненацька й убили дворфи Темного Заліза, що нишпорили під мостом.",al={"хто такий растлок","старий растлок","ебенезер растлок"}},{q="Хто вбив Растлока?",a="Він потрапив у засідку агентів Темного Заліза, які діяли під Мостом Тандол, виконуючи накази Кама Діпф'юрі.",al={"хто вбив растлока","хто влаштував засідку","тіло растлока"}},{q="Що знаходять при тілі Растлока?",a="Біля його стиснутого кулака лежить пергамент — Накази Діпф'юрі, у яких описано таємні змови Темного Заліза проти життєво важливого північного мосту.",al={"що було в руці","накази діпф'юрі","пергамент на растлоку"}},{q="Хто такий Раґ Ґармасон?",a="Раґ Ґармасон — офіцер Альянсу на південному боці Мосту Тандол у Багнокраї; він відповідає за безпечний рух між дворфійськими землями й північчю.",al={"раґ ґармасон","хто такий ґармасон"}},{q="Чому за Міст Тандол точиться така запекла боротьба?",a="Міст Тандол — єдиний суходільний міст, що з'єднує дворфійські землі Каз Модану й Багнокрай з Аратійським нагір'ям і Лордероном. Утримати його життєво важливо для постачання Альянсу.",al={"чому міст тандол важливий","значення мосту тандол"}},{q="Що буде, коли віддати накази Раґові Ґармасону?",a="Усвідомивши всю серйозність загрози, Раґ Ґармасон посилає вас знищити запас вибухівки Темного Заліза, схований по той бік мосту, в Аратійському нагір'ї, щоб зірвати їхню диверсію.",al={"що буде далі","продовження мосту тандол"}}},fp="16,322,21.358.0,17.380.1,27.191.1,21.123.1,34.141.1,21.184.0,45.196.0,54.184.1"}
P.entries["quest:6321"] = {n="Постачання для Гробниці",s="«Постачання для Гробниці» — доручення з постачання від Вартового Смерті Подріґа в Гробниці в Срібноліссі. Щоб місцевий загін вартових смерті мав чим битися з дикими жахіттями й Погибеллю, що нишпорять лісами, нагальну заявку на зброю треба передати через доглядача кажанів Кароса Разока постачальникам зброї в Андерсіті.",h="«Постачання для Гробниці» — доручення з постачання від Вартового Смерті Подріґа в Гробниці в Срібноліссі.",kw={"постачання для гробниці","вартовий смерті подріґ","карос разок","ґордон вендгем","гробниця","кажани","зброя"},ang={["faction:Horde"]="Налагодити й підтримувати надійні летючі шляхи між залогами й столицями — основа злагодженої військової оборони в спірних краях.",["race:Undead"]="Утримання застав на кшталт Гробниці дає Відступникам змогу поширювати свою силу за межі Галявин Тірісфалю й убезпечувати навколишню дику місцину для Темної Леді."},sec={{t="Озброїти передову",b="Вартовий Смерті Подріґ доповідає, що Гробниця відносно добре забезпечена, але безперервні втрати в Срібноліссі пожирають спорядження з тривожною швидкістю. Між дикими звірами, рештками Погибелі й агресивними місцевими загрозами фронтове спорядження зношується чи лишається на полі після сутичок. За наказом Екзекутора Гадрека Подріґ складає пряму заявку Ґордонові Вендгему — торговцеві зброєю зі столиці. Постійний приплив нових клинків і обладунків вкрай потрібен, якщо Відступники хочуть утримати свої хиткі позиції за межами Галявин Тірісфалю."},{t="Летюча мережа",b="Пересилати важливе листування й військові припаси затуманеними дорогами Срібнолісся пішки — повільно й небезпечно через засідки. Щоб обійти ці небезпеки, Відступники покладаються на приручених, навчених кажанів-кровопивців. Передавши заявку Подріґа доглядачеві кажанів Каросові Разоку, ви долучаєте піхоту до ширшої повітряної мережі постачання Андерсіті — тих летючих шляхів, що прив'язують віддалені залоги просто до столиці Сильвани."}},faq={{q="Навіщо замовлення Подріґа?",a="Вартовий Смерті Подріґ перевірив зброярню Гробниці на доручення Виконавця Гадрека. Провіанту й загального спорядження вистачало, але треба було замінити зброю, зламану чи втрачену в сутичках із Погибеллю та іншими загрозами лісу.",al={"навіщо замовлення подріґа","що таке вимога подріґа","мета постачання гробниці"}},{q="Хто такий Ґордон Вендгем?",a="Ґордон Вендгем — торговець зброєю в Андерсіті. Подріґ адресує заявку саме йому, щоб забезпечити гарнізон новою зброєю.",al={"хто такий ґордон вендгем","ґордон вендгем андерсіті"}},{q="Хто такий Карос Разок?",a="Карос Разок — доглядач кажанів у Гробниці. Він відає сідалом жахливих кажанів, на яких по всьому Лордерону перевозять гінців, розвідників і припаси.",al={"роль кароса разока","хто той кажановодець"}},{q="Чому кажани, а не кур'єри по дорогах?",a="Срібнолісся кишить ворожими звірами, мандрівними загонами Погибелі та іншими небезпечними силами. Кур'єри на дорогах постійно ризикують потрапити в засідку, тож повітряні маршрути на кажанах — найшвидший і найбезпечніший зв'язок з Андерсіті.",al={"чому летіти до андерсіті","чому кажани"}},{q="Які загрози нависли над Гробницею?",a="Гробницю оточують ворожі сили: недобитки нежиті Погибелі, воргени, дикі звірі й місцеві угруповання людей, — тож гарнізон мусить завжди бути напоготові й постійно поновлювати спорядження.",al={"загрози гробниці","чому вартовим смерті потрібна зброя"}},{q="Куди веде це доручення далі?",a="Коли ви доставите замовлення Каросові Разоку, він влаштує вам переліт просто до Андерсіті, де заявку можна передати безпосередньо Ґордонові Вендгему.",al={"яке завдання далі","що після постачання для гробниці"}}},fp="23,328,21.597.0,18.443.0,38.243.0,22.159.0,19.163.0,38.216.0,37.207.0,31.167.0"}
P.entries["quest:6322"] = {n="Майкл Гарретт",s="«Майкл Гарретт» — просте доручення гінця, що поєднує торгівлю в Андерсіті з повітряною мережею Відступників. Забравши припаси, спаковані Ґордоном Вендгемом у Торговому Кварталі, ви маєте віднести ящик доглядачеві кажанів Майклові Гарретту, щоб той відправив вантаж до Склепу. Це завдання показує, як Відступники навченими кажанами-вампірами поєднують столицю із заставами по всьому Лордерону.",h="«Майкл Гарретт» — просте доручення гінця, що поєднує торгівлю в Андерсіті з повітряною мережею Відступників.",kw={"майкл гарретт","ґордон вендгем","ящик гордона","кажани","торговий квартал","склеп","андерсіті"},ang={["faction:Horde"]="Для мандрівників, що прибувають із Калімдору, мережа кажанів Відступників — основний спосіб швидко переміщатися північчю Східних Королівств.",["race:Undead"]="Щоб утримувати присутність Сильвани за межами Галявин Тірісфалю, конче треба розуміти, як працює повітряне постачання, яким опікуються наглядачі на кшталт Майкла Гарретта."},sec={{t="Постачання застав",b="Молоде королівство, вирубане з руїн Лордерона, потребує невпинного постачання. Застави на кшталт Склепу в Срібноліссі дуже залежать від товарів, боєприпасів і харчів, що йдуть з Андерсіті. Ґордон Вендгем пакує потрібні припаси в один ящик у Торговому Кварталі міста, та возити вантажі суходолом крізь отруєні ліси і повільно, і небезпечно: у засідці можуть чекати рештки Погибелі чи дикі звірі."},{t="Крила Відступників",b="Щоб обійти небезпеки на дорогах, Відступники тримають кажанів-вампірів, яких вирощують і доглядають умілі наглядачі. Майкл Гарретт опікується цими крилатими створіннями зі свого сідала в Торговому Кварталі Андерсіті. Передавши йому вантаж, ви забезпечите, що припаси приторочать до кажана й перенесуть просто через пагорби до Срібнолісся, — а нові гінці заразом дізнаються, як столиця тримає зв'язок із віддаленими поселеннями."}},faq={{q="Хто такий Майкл Гарретт?",a="Майкл Гарретт — доглядач кажанів Андерсіті в Торговому Кварталі. Він відає кажанами-вампірами мережі перельотів і влаштовує подорожі та повітряні доставки між столицею Відступників і союзними розпорядниками польотів по всьому Лордерону.",al={"майкл гарретт","майстер кажанів андерсіті","хто такий гарретт"}},{q="Що в Ящику Гордона?",a="У ящику — важливий провіант і польові припаси, які Ґордон Вендгем зібрав у Торговому Кварталі, призначені саме для загонів Відступників у Гробниці в Срібноліссі.",al={"ящик ґордона","які припаси","ящик гробниці"}},{q="Чому кажани, а не вози чи коні?",a="Наземні дороги, що в'ються з Галявин Тірісфалю до Срібнолісся, повні небезпек: там і мандрівні звірі Погибелі, і ворожі люди, і підступна місцевість. Повітряні маршрути на навчених велетенських кажанах набагато швидші й цілком оминають засідки на землі.",al={"чому політ кажанів","чому кажани","літаючі припаси"}},{q="Куди йде вантаж після Майкла Гарретта?",a="Коли Майкл Гарретт отримає Ящик Гордона, вантаж готують до перельоту кажаном просто до розпорядника кажанів у Гробниці в Срібноліссі — так ланцюжок постачання замикається.",al={"наступний крок","після майкла гарретта","куди летять кажани"}},{q="Де в Андерсіті знайти Майкла Гарретта?",a="Він у південно-західній частині Торгового Кварталу — того самого кварталу, де сідають кажани, що прилітають із Гробниці.",al={"де гарретт","знайти кажановодця","де політний майстер андерсіті"}},{q="Чи треба побувати в Гробниці перед цим завданням?",a="Щоб самому полетіти кажаном разом із вантажем, ви маєте заздалегідь поговорити з доглядачем кажанів у Гробниці й відкрити повітряний маршрут; інакше доведеться йти туди пішки.",al={"потрібен маршрут гробниці","чи можна одразу летіти"}}},fp="15,424,22.451.0,21.410.0,23.236.0,26.199.0,40.281.0,49.188.0,48.122.0,60.197.0"}
P.entries["quest:6323"] = {n="Переліт до Андерсіті",s="«Переліт до Андерсіті» знайомить молодих Відступників із повітряною мережею Орди в Лордероні. Везучи запит на зброю з обложеної застави Склеп, гінці летять на жахокажані просто до Торгового Кварталу Андерсіті, щоб поповнити запаси захисників краю.",h="«Переліт до Андерсіті» знайомить молодих Відступників із повітряною мережею Орди в Лордероні.",kw={"переліт до андерсіті","карос разок","ґордон вендгем","жахокажан","склеп","торговий квартал","срібнолісся"},ang={["faction:Horde"]="Розпорядники польотів — сполучна тканина територіального поступу Орди: вони обертають виснажливі переходи глушиною на швидкі тактичні перекидання.",["profession:Blacksmithing"]="Доставивши замовлення Ґордонові Вендгему, коваль бачить сам хребет постачання Лордерона, де кожен шмат заліза тримають гострим і готовим до війни.",["race:Undead"]="Переліт зі Срібнолісся до столиці показує, як далеко простягається й як злагоджено працює мережа Темної Леді: жоден відрізаний гарнізон не лишиться без промислу Андерсіті."},sec={{t="Крила над Срібноліссям",b="Щоб зберігати зв'язок між столицею Відступників і її передовими заставами, потрібен швидкий і надійний транспорт. Карос Разок, доглядач кажанів у Склепі в Срібноліссі, опікується навченими жахокажанами, що переносять гінців і припаси над зараженим краєм. Дорогами никають вороже налаштовані звірі, воргени Місячної Люті й рештки Погибелі, тож піднятися в небо — найбезпечніший і найшвидший спосіб доставити нагальні військові запити до столиці."},{t="Озброїти передову",b="Приземлившись у гамірному Торговому Кварталі Андерсіті, гінець передає запит Подріґа на спорядження просто Ґордонові Вендгему. Цей зброяр Андерсіті, відданий справі Темної Леді, дбає, щоб застави на кшталт Склепу мали справну, готову до бою зброю. Підтримувати ці оборонні осередки конче важливо для молодої держави Відступників, яка закріплює свої кордони проти ворогів довкола."}},faq={{q="Навіщо цей переліт до Андерсіті?",a="Мета — доставити офіційну заявку на зброю від Вартового Смерті Подріґа з Гробниці просто Ґордонові Вендгему, торговцю зброєю з Торгового Кварталу Андерсіті, а заразом навчити нових поборників користуватися мережею перельотів Відступників.",al={"навіщо переліт до андерсіті","мета переліту до андерсіті","призначення наказу подріґа"}},{q="Хто такий Карос Разок?",a="Карос Разок — розпорядник кажанів у Гробниці в Срібноліссі. Він відає сідалом жахливих кажанів, завдяки яким Відступники швидко подорожують і підтримують зв'язок з Андерсіті.",al={"роль кароса разока","хто майстер кажанів гробниці"}},{q="Хто такий Ґордон Вендгем?",a="Ґордон Вендгем — зброяр із Відступників у Торговому Кварталі Андерсіті, поруч із майданчиком, де сідають кажани. Він пишається тим, що зброя в нього завжди чиста, нагострена й готова для передових загонів Леді Сильвани.",al={"ґордон вендгем","де ґордон вендгем"}},{q="Чому Відступники подорожують на кажанах?",a="Жахливі кажани — місцеві нічні хижаки, що добре пасують до осквернених небес Лордерону. Вони стрімко переносять мандрівників над підступними небезпеками внизу — здичавілими воргенами, ворожими гнилошкірими гнолами й Погибеллю.",al={"чому кажани","летючі скакуни відступників"}},{q="Що буде після доставки?",a="Отримавши замовлення, Ґордон Вендгем скеровує кур'єрів до Майкла Гарретта, доглядача кажанів Андерсіті, і так відкривається зворотний маршрут до Гробниці.",al={"що далі","продовження переліту до андерсіті"}},{q="Де в Андерсіті сідає жахливий кажан?",a="Жахливий кажан сідає на піднесене сідало просто посеред Торгового Кварталу Андерсіті, звідки рукою подати до міських ремісників і купців-постачальників.",al={"де сідає кажан андерсіті","де приземляється кажан"}}},fp="21,294,21.489.0,16.446.0,52.261.0,19.198.0,22.239.0,41.202.0,43.166.0,47.181.0"}
P.entries["quest:6324"] = {n="Повернення до Подріґа",s="«Повернення до Подріґа» — завдання з постачання, що завершує мандрівку гінця між Срібноліссям і Андерсіті. Доставивши донесення до столиці, гінець отримує ящик зброї, який має перенести назад до Вартового Смерті Подріґа в Склепі через мережу доглядачів кажанів Відступників.",h="«Повернення до Подріґа» — завдання з постачання, що завершує мандрівку гінця між Срібноліссям і Андерсіті.",kw={"повернення до подріґа","вартовий смерті подріґ","майкл гарретт","карос разок","ящик гордона","склеп","кажани"},ang={["faction:Horde"]="Це завдання показує, як влаштоване постачання, що поєднує Андерсіті з віддаленими заставами на півночі континенту.",["race:Undead"]="Щоб боронити Лордерон і закріпити молоде королівство королеви Сильвани, передові гарнізони конче мають бути озброєні."},sec={{t="Шлях постачання з Андерсіті",b="Застави по всьому Лордерону, щоб діяти, сильно залежать від регулярних поставок з Андерсіті. У Склепі в Срібноліссі вартові смерті відбиваються і від місцевих воргенів, і від решток Даларана, і від уцілілих Погибелі. Забезпечувати віддалені гарнізони свіжою зброєю конче потрібно, щоб край лишався під владою Відступників."},{t="Крила Відступників",b="Майстер кажанів Майкл Гарретт тримає головне сідало в Торговому Кварталі Андерсіті — осередок повітряних подорожей Відступників. Кажани й самі вертаються до столиці, та перш ніж прокласти переліт до далекої застави, вершникам треба домовитися з місцевими доглядачами, як-от Каросом Разоком. Перевезення Ящика Гордона небом Лордерона вчить гінців, як Відступники зв'язують докупи свої розпорошені твердині."}},faq={{q="Що в Ящику Гордона?",a="У ящику — нова зброя, виготовлена в Андерсіті, щоб вартові смерті в Гробниці були як слід озброєні проти навколишніх загроз.",al={"вміст ящика ґордона","що я віддаю подріґу"}},{q="Хто такий Вартовий Смерті Подріґ?",a="Вартовий Смерті Подріґ — воїн Відступників у Гробниці в Срібноліссі, який відає постачанням і обороною місцевого гарнізону.",al={"подріґ","хто такий подріґ"}},{q="Хто такий Майкл Гарретт?",a="Майкл Гарретт — розпорядник кажанів Відступників у Торговому Кварталі Андерсіті, що координує маршрути польотів по всьому Лордерону.",al={"майкл гарретт","майстер кажанів андерсіті"}},{q="Чому перед польотом кудись треба поговорити з розпорядником кажанів?",a="Кажани Відступників самі знають дорогу назад до головного сідала в Андерсіті, але для польотів звідти спершу треба прокласти маршрут із місцевим доглядачем, щоб безпечно дістатися мети.",al={"правила польоту","як працюють кажановоди"}},{q="Чому так важливо постачати Гробницю?",a="Гробниця — головна передова база Відступників у Срібноліссі. Вона тримає їхню військову присутність проти зграй воргенів, загрози з боку Мунрейджів і сил Даларану в цьому краї.",al={"чому гробниця важлива","значення гробниці"}},{q="Хто такий Карос Разок?",a="Карос Разок — розпорядник кажанів у Гробниці в Срібноліссі; він доглядає кажанів, що з'єднують заставу з Андерсіті.",al={"карос разок","майстер кажанів гробниці"}}},fp="16,292,25.353.0,21.419.0,26.156.0,25.154.0,23.151.0,65.183.0,44.178.0,19.143.0"}
P.entries["quest:633"] = {n="Міст Тандол",s="Ця важлива місія Альянсу доручає героям захистити єдиний уцілілий прогін Мосту Тандол. Після підлого вбивства Ебенізера Растлока Раґ Ґармасон розкриває змову зрадника Кама Діпф'юрі: підірвати сховану вибухівку й перерізати життєво важливий зв'язок Айронфорджа з північчю.",h="Ця важлива місія Альянсу доручає героям захистити єдиний уцілілий прогін Мосту Тандол.",kw={"міст тандол","кам діпф'юрі","раґ ґармасон","вибухівка","аратійське нагір'я","темне залізо"},ang={["faction:Alliance"]="Утримати міст конче важливо для безпеки континенту: якщо ця переправа впаде, перекидати війська й ресурси Альянсу в Араті й Лордерон стане незрівнянно небезпечніше.",["profession:Engineering"]="Інженери оцінять нищівну силу схованки Діпф'юрі, приготованої, щоб знести величну дворфійську кладку, гідну титанів.",["race:Dwarf"]="Для синів Айронфорджа оборона Мосту Тандол — захист життєвої артерії Короля Маґні до північних союзників і удар по зрадливих лазутчиках Темного Заліза."},sec={{t="Розкрита змова",b="Після того як у підмурках Мосту Тандол знайдено тіло Ебенізера Растлока, віднайдений документ проливає світло на ще темніші наміри. Підбурювач із Темного Заліза Кам Діпф'юрі, що спланував перше руйнування мосту, ще не закінчив. Обваливши одну з величних кам'яних переправ, його мережа диверсантів заклала другу схованку важкої вибухівки просто за північним кордоном, в Аратійському нагір'ї, щоб довершити справу."},{t="Порятунок життєвої артерії",b="Міст Тандол — головний суходільний коридор, що пов'язує південні королівства Каз Модану й Стормвінда з розтерзаними війною землями півночі. Щоб уберегти цей шлях, Раґ Ґармасон наказує негайно завдати випереджального удару по схованці вибухівки в Араті, перш ніж змовники Діпф'юрі встигнуть пустити її в хід. Підрив вибухівки усуває безпосередню небезпеку й зберігає Айронфорджу доступ на північ, хоча Ґармасонові й досі відчайдушно бракує вояків, щоб боронити пролом."}},faq={{q="Хто такий Кам Діпф'юрі?",a="Кам Діпф'юрі — дворф Темного Заліза, натхненник диверсії на Мосту Тандол. Не вдовольнившись обвалом першої арки, він сховав додаткову вибухівку по той бік прірви, в Аратійському нагір'ї, щоб знищити й решту мосту.",al={"кам діпф'юрі","хто підірвав міст тандол","натхненник мосту тандол"}},{q="Чому Міст Тандол має таке стратегічне значення?",a="Міст — єдина суходільна переправа через величезну прірву між Багнокраєм і Аратійським нагір'ям. Якщо його зруйнують, Альянс утратить головний наземний шлях постачання між Айронфорджем, Стормвіндом і союзниками, що тримаються на півночі Лордерону.",al={"чому міст тандол важливий","переказ про міст тандол"}},{q="Що сталося з Ебенезером Растлоком?",a="Ебенезер Растлок — оборонець Айронфорджа, якого вбили в глибинах під мостом. Саме з його розвідки й паперів, знайдених при тілі, Раґ Ґармасон дізнався про таємну схованку вибухівки Діпф'юрі.",al={"смерть растлока","хто був растлок"}},{q="Де схована вибухівка?",a="Вибухівку сховали по той бік мосту, з боку Аратійського нагір'я, — досить близько, щоб спільники Діпф'юрі могли швидко перенести її до вцілілої частини мосту.",al={"де вибухівка","де сховок вибухівки","місце схованки"}},{q="Хто наказує знищити вибухівку?",a="Раґ Ґармасон, офіцер-дворф, що стоїть біля Мосту Тандол з боку Багнокраю, наказує знайти й знищити схованку, щоб пошанувати жертву Растлока й уберегти решту мосту.",al={"хто починає це завдання","раґ ґармасон"}},{q="Що буде після знищення вибухівки?",a="Безпосередню диверсію зірвано, але Раґ Ґармасон розуміє, що без допомоги його гарнізон не втримає пошкоджений міст довіку. Чекаючи на резерви з Айронфорджа, він надсилає прохання про підкріплення Капітанові Найлсу в табір Альянсу в Притулку на Аратійському нагір'ї.",al={"що далі після мосту тандол","завдання заклик до альянсу"}}},fp="16,308,15.456.0,19.482.1,20.252.0,47.268.0,36.222.1,40.195.0,46.196.0,47.287.1"}
P.entries["quest:634"] = {n="Заклик до Альянсу",s="«Заклик до Альянсу» несе через Міст Тандол до Араті відчайдушне прохання про підкріплення від уцілілих дворфійських захисників Дун Модра. Після різанини гарнізону, яку влаштували лазутчики Темного Заліза, дворфи шукають допомоги в людських сил у Притулку — і з'ясовують, що Альянс розтягнуто понад межі можливого.",h="«Заклик до Альянсу» несе через Міст Тандол до Араті відчайдушне прохання про підкріплення від уцілілих...",kw={"заклик до альянсу","капітан найлс","раґ ґармасон","притулок","стромґард","міст тандол"},ang={["faction:Alliance"]="Ця розмова підкреслює, наскільки розколотим лишається Альянс на півночі Східних Королівств, де місцеві гарнізони ведуть окремі відчайдушні битви без спільних резервів.",["race:Dwarf"]="Для дворфів ця місія показує болючу відрізаність північних гарнізонів на кшталт Дун Модра: навіть давні союзники-люди надто обложені, щоб подати руку допомоги.",["race:Human"]="Мандрівники-люди бачать гірку скорботу Капітана Найлс, яка розривається між вірністю братерству Альянсу й боротьбою за виживання загиблого Стромґарда."},sec={{t="Крик через прірву",b="Після спустошення Дун Модра й диверсії на Мосту Тандол, які вчинили дворфи Темного Заліза, уцілілі дворфи ледве тримаються на північному краю Багнокраю. Поки головні резерви Айронфорджа ще не прибули, Раґ Ґармасон і командир Лонґбрейд звертають погляди на північ, до Аратійського нагір'я. Дізнавшись про табір Альянсу в Притулку, Ґармасон посилає вісника через зруйнований міст — благати Капітана Найлс про негайну військову допомогу."},{t="Біда Стромґарда",b="Діставшись Притулку, посланець бачить сувору дійсність північного Альянсу. Капітан Найлс щиро співчуває воякам Лонґбрейда, але не може виділити жодного бійця. Сам Стромґард лежить у руїнах, заполонений розбійниками Синдикату, огрями-Каменекулаками й тролями-Сухокорими. Уцілілі захисники Стромґарда цілком віддані боротьбі за свою прадідівську столицю. Скута честю й власним відчайдушним становищем, Найлс мусить передати у відповідь, що дворфи біля мосту мають вистояти самі."}},faq={{q="Хто надсилає прохання до Притулку?",a="Раґ Ґармасон, що стоїть біля зруйнованого предмостя Мосту Тандол на межі Багнокраю, надсилає прохання від імені командувача Лонґбрейди та решти оборонців Дун Модра.",al={"хто дає заклик до альянсу","завдання раґа ґармасона","хто просить допомоги"}},{q="Навіщо дворфам допомога з Притулку?",a="Дун Модр упав під раптовим і жорстоким натиском лазутчиків клану Темного Заліза, які також підірвали Міст Тандол. Поки вцілілі чекають на важкі резерви з Айронфорджа, їх надто мало, щоб самотужки відбити поселення й убезпечити переправу.",al={"навіщо дворфам допомога","чому просити притулок","підкріплення дун модра"}},{q="Чому Капітан Найлс відмовляється надіслати солдатів?",a="Капітан Найлс не може виділити жодного вояка, бо королівство Стромґард і саме лежить у руїнах. Людські сили в Притулку цілком зайняті відчайдушною кампанією, щоб відвоювати Стромґард у Синдикату, огрів і лісових тролів.",al={"чому немає допомоги від найлса","чому притулок відмовляє","відповідь капітана найлса"}},{q="Де розташований Притулок?",a="Притулок лежить неподалік головної дороги в центрі Аратійського нагір'я, на північ від переправи через Міст Тандол між Багнокраєм і Араті.",al={"де притулок","де капітан найлс","як знайти притулок"}},{q="Що сталося з Дун Модром?",a="Дун Модр захопив і пограбував клан Темного Заліза, що пробрався горами, аби перерізати суходільний шлях між південними дворфійськими землями й північними володіннями Альянсу.",al={"переказ про дун модр","що сталося з дун модром","хто напав на дун модр"}},{q="Що буде після того, як Капітан Найлс відмовить?",a="Капітан Найлс передає свої жалі командувачеві Лонґбрейді, підтверджуючи, що підкріплення від людей не буде. Вцілілим дворфам біля мосту доведеться покладатися на власну кмітливість, мандрівних шукачів пригод і далекі резерви з Айронфорджа.",al={"що далі після заклику до альянсу","наступне завдання після заклику","продовження ланцюжка"}}},fp="20,349,22.483.0,24.543.0,36.183.0,48.264.0,47.248.0,31.142.0,26.194.0,56.233.0"}
P.entries["quest:6341"] = {n="Дари Тельдрассила",s="«Дари Тельдрассила» — вступне доручення від Несси Шедовсонг у Селищі Рут'теран. Прагнучи порівняти незвичайний розмір і чисельність острівної риби з тією, що ловиться біля материка, вона готує збірку кісток і луски, щоб переслати через протоку на Темне Узбережжя. Передати цей пакунок місцевому доглядачеві гіпогрифів — перший крок до переправи через море в Обердайн.",h="«Дари Тельдрассила» — вступне доручення від Несси Шедовсонг у Селищі Рут'теран.",kw={"дари тельдрассила","несса шедовсонг","селище рут'теран","веспристус","лейрд","гіпогрифи"},ang={["faction:Alliance"]="Шлях між Рут'тераном і Обердайном — важлива транспортна артерія, що з'єднує столицю нічних ельфів з рештою північного Калімдору.",["race:NightElf"]="Для мандрівників із нічних ельфів ця подорож — традиційний перехід із безпечних висот Тельдрассилу на затінені материкові береги Темного Узбережжя."},sec={{t="Дослідження рибалки",b="Під велетенським гіллям Світового Дерева захищені води довкола Селища Рут'теран кишать напрочуд великою й численною морською живністю. Несса Шедовсонг, спостерігаючи за дивовижними уловами місцевих рибалок, хоче з'ясувати, чи ця життєва сила сягає давніх материкових берегів, чи властива лише водам, які живить Тельдрассил. Щоб перевірити свою гіпотезу, вона готує збірку луски й кісток для Лейрда — колеги-торговця рибою з Обердайна по той бік води."},{t="Як переправитися",b="Щоб переправляти вантажі й мандрівників через відкриту протоку між острівним гіллям і материком Калімдору, потрібні надійні крила. Замість відсилати пакунок невеликим човном Несса скеровує мандрівників просто до Веспристуса — селищного майстра гіпогрифів. Передавши йому збірку, мандрівники домовляються про все потрібне, щоб осідлати навченого звіра й доставити зразки просто до пристаней Темного Узбережжя."}},faq={{q="Що намагається з'ясувати Несса?",a="Несса Шедовсонг помітила, що риба з вод довкола Селища Рут'теран надзвичайно велика й рясна. Вона хоче відправити через море зразки кісток і луски, щоб порівняти улов Тельдрассилу з рибою з материкових берегів Темного Узбережжя.",al={"мета несси","навіщо порівнювати рибу","мета дарів тельдрассила"}},{q="Хто в Обердайні отримує зразки риби?",a="Збірка адресована Лейрдові, торговцеві рибою в прибережному селищі Обердайн на материковому березі Темного Узбережжя.",al={"хто отримає збірку несси","лейрд темне узбережжя","торговець рибою оберіжин"}},{q="Чому треба віднести посилку Веспристусові, а не йти просто до Обердайна?",a="Веспристус — розпорядник гіпогрифів у Селищі Рут'теран. Віддавши збірку йому, ви влаштуєте повітряне перевезення й зможете перелетіти на гіпогрифі через море до Темного Узбережжя.",al={"чому веспристус","хто такий веспристус","майстер гіпогрифів рут'теран"}},{q="Де розташоване Селище Рут'теран щодо Тельдрассилу?",a="Селище Рут'теран лежить біля південного підніжжя Тельдрассилу, на рівні моря, і з'єднане з Дарнасусом смарагдовим порталом. Це головна прибережна гавань для кораблів і гіпогрифів, що прибувають до великого дерева й вирушають від нього.",al={"де рут'теран","де несса","як дістатися рут'терана"}},{q="Що буде, коли віддати збірку Веспристусові?",a="Веспристус приймає збірку й пропонує наступне завдання — «Політ до Обердайна»: на спині гіпогрифа ви злетите над протокою просто до Темного Узбережжя.",al={"політ до оберіжина далі","після дарів тельдрассила","що робить веспристус"}},{q="Чи це частина виходу нічних ельфів зі стартової зони?",a="Так. Цей ланцюжок знайомить молодих шукачів пригод із нічних ельфів із маршрутами польотів і веде їх з острівних крон униз, на материковий Калімдор, щоб вони продовжили мандри на Темному Узбережжі.",al={"вихід із тельдрассила","завдання нічного ельфа 10 рівня","переїзд на темне узбережжя"}}},fp="24,405,19.514.0,17.410.0,36.280.0,47.133.0,77.202.0,62.236.0,55.178.0,58.182.0"}
P.entries["quest:6342"] = {n="Політ до Обердайна",s="Це доручення знайомить шукачів пригод, що вирушають із Тельдрассилу, з повітряною мережею сполучення нічних ельфів. На прохання майстра гіпогрифів Веспристуса в Селищі Рут'теран мандрівники летять через море, щоб доставити пакунок із надзвичайно великими морськими зразками Лейрдові в Обердайн.",h="Це доручення знайомить шукачів пригод, що вирушають із Тельдрассилу, з повітряною мережею сполучення нічних...",kw={"політ до обердайна","веспристус","гіпогрифи","селище рут'теран","лейрд","тельдрассил"},ang={["faction:Alliance"]="Гіпогрифи — головна повітряна мережа Альянсу на півночі Калімдору, що з'єднує прибережні застави безпосередньо зі столицею.",["race:NightElf"]="Політ на гіпогрифі до Обердайна — знаковий обряд переходу для молодих калдореїв, що ступають із Тельдрассилу на материк своїх предків."},sec={{t="На крилах до Темного Узбережжя",b="Для багатьох молодих шукачів пригод, що покидають гілля Тельдрассилу, Селище Рут'теран — поріг між прихистком і широким світом. Протокою між острівною гаванню й материком Калімдору курсує звичайний пором, але нічні ельфи так само покладаються на своїх вірних гіпогрифів. Отримавши від Несси Шедовсонг пакунок із рідкісними частинами риби, мандрівники сідають на одного з цих крилатих звірів і відкривають свій найперший шлях польоту — на береги Темного Узбережжя."},{t="Дивний улов",b="Сама доставка дуже цікавить рибалок Темного Узбережжя. Лейрд, що чекає на знахідки Несси на пристанях Обердайна, оглядає улов і знаходить величезні лусочки завбільшки з кулак і щелепу майже вдвічі більшу, ніж у материкових зразків. Острівні води біля підніжжя Світового Дерева, схоже, породжують змінене чи ненормально велике життя — дивина, що натякає на могутню, неспокійну природу самого Тельдрассилу."}},faq={{q="Навіщо цей політ?",a="Подорож — практичний урок, як з'єднувати маршрути польотів між поселеннями, а заразом спосіб доставити Лейрдові в Обердайн зразки незвичайної риби, виловленої біля Селища Рут'теран.",al={"навіщо летіти до оберіжина","мета польоту до оберіжина","навіщо політ"}},{q="Хто надсилає посилку і що в ній?",a="Посилку надсилає рибалка Несса Шедовсонг. У ній — зразки риби з вод довкола Селища Рут'теран, зокрема величезна луска й завелика щелепна кістка.",al={"збірка несси","що в посилці","хто надіслав посилку"}},{q="Чому риба з Тельдрассилу така велика?",a="Лейрд зауважує, що щелепа майже вдвічі більша за звичайну, а луска — завбільшки з кулак. Води довкола Світового Дерева Тельдрассил чомусь роблять живих істот більшими, ніж на материкових берегах Темного Узбережжя.",al={"чому риба велика","розмір риби рут'терана","величезна луска"}},{q="Хто такий Веспристус?",a="Веспристус — розпорядник гіпогрифів у Селищі Рут'теран. Він доглядає скакунів нічних ельфів і влаштовує перельоти через море до материкового Калімдору.",al={"переказ про веспристуса","хто майстер гіпогрифів"}},{q="Хто такий Лейрд?",a="Лейрд — рибалка з нічних ельфів, що живе в Обердайні на Темному Узбережжі. Він вивчає місцеве водяне життя й порівнює материкові улови з тими, що виловлені біля Тельдрассилу.",al={"переказ про лейрда","хто такий лейрд","лейрд темне узбережжя"}},{q="Чи можна дістатися з Рут'терана до Обердайна без польоту?",a="Так. Між причалами Селища Рут'теран і пристанню Обердайна регулярно ходить пором — це альтернатива перельоту на гіпогрифі.",al={"корабель до оберіжина","пором на темне узбережжя","інший шлях до оберіжина"}}},fp="19,272,24.467.0,15.428.0,35.198.0,44.182.0,42.226.0,18.169.0,13.174.0,63.147.0"}
P.entries["quest:6343"] = {n="Повернення до Несси",s="Це завдання посилає молодих мандрівників з Обердайна назад до Селища Рут'теран, щоб передати Нессі Шедовсонг висновки Лейрда. Воно завершує вступне доручення, що вчить шукачів пригод переправлятися між материком Калімдору й Тельдрассилом.",h="Це завдання посилає молодих мандрівників з Обердайна назад до Селища Рут'теран, щоб передати Нессі Шедовсонг...",kw={"повернення до несси","несса шедовсонг","лейрд","кейлайс мунфезер","селище рут'теран","пором"},ang={["faction:Alliance"]="Обердайн і Селище Рут'теран — важливі морські ворота, що пов'язують поселення нічних ельфів на півночі Калімдору з ширшими інтересами Альянсу по всьому Азероту.",["race:NightElf"]="Для нічних ельфів, що вперше вирушають із гілля Тельдрассилу, цей обмін — перше офіційне доручення, яке пов'язує новий острівний прихисток із давнім материком Темного Узбережжя."},sec={{t="Посланець через море",b="Доставивши перші запитання Несси Шедовсонг Лейрдові в Обердайн, мандрівники мають віднести його письмові спостереження назад через воду. Лейрд зауважує разючі відмінності між уловом біля Темного Узбережжя й біля берегів Тельдрассилу й підозрює, що саме велике Світове Дерево змінює місцеве морське життя. Щоб повернутися до Селища Рут'теран, шукачі пригод можуть або найняти політ у майстрині гіпогрифів Кейлайс Мунфезер, або сісти на пором, що регулярно ходить від пристані Обердайна."},{t="Дивні щедроти",b="Отримавши відповідь Лейрда в Селищі Рут'теран, Несса захоплюється помітною різницею в морському житті. Величезна риба біля Світового Дерева — неабияке благо для місцевих рибалок, але її справжня причина лишається для калдореїв відкритим питанням. Несса вирішує поділитися знахідками з односельцями: поки що вона задоволена щедрим уловом, але пильно стежить, які сили насправді за цим стоять."}},faq={{q="Хто дає і хто приймає це завдання?",a="Завдання дає рибалка Лейрд в Обердайні на Темному Узбережжі. Здати його треба Нессі Шедовсонг у Селищі Рут'теран, біля підніжжя Тельдрассилу.",al={"хто дає завдання","де здати","хто видає завдання"}},{q="Як найшвидше повернутися до Селища Рут'теран?",a="Можна або швидко перелетіти гіпогрифом, поговоривши з Кейлайс Мунфезер в Обердайні, або вийти на довгу пристань і сісти на звичайний пасажирський пором до причалів Селища Рут'теран.",al={"як повернутися","дорога до рут'терана","пором чи гіпогриф"}},{q="Навіщо Лейрд вивчає рибу?",a="Лейрд помічає, що морські улови біля Темного Узбережжя разюче відрізняються від тих, що добувають довкола Тельдрассилу. Він підозрює, що бурхливе зростання й особлива енергія Світового Дерева безпосередньо змінюють навколишню живність.",al={"навіщо вивчати рибу","чим відрізняється риба","відповідь лейрда"}},{q="Чи дізнається Несса, чому риба така дивна?",a="Не одразу. Несса відзначає разючу різницю й погоджується, що це варто дослідити, але поки що задовольняється тим, що ділиться звісткою з місцевими й тішиться щедрими уловами.",al={"чому риба велика","таємниця риби тельдрассила"}},{q="Що передує цьому завданню?",a="Це завдання йде одразу після «Польоту до Обердайна», у якому мандрівники вирушають із Селища Рут'теран на Темне Узбережжя з первісним листом Несси до Лейрда.",al={"попереднє завдання","завдання перед цим","політ до оберіжина"}},{q="Навіщо цей ланцюжок завдань?",a="Окрім того, що він розповідає про загадковий вплив Тельдрассилу на місцеву природу, цей ланцюжок доставок — обряд посвяти, що вчить молодих шукачів пригод із нічних ельфів подорожувати між рідним островом і материковим Калімдором кораблем і з розпорядником польотів.",al={"навіщо це завдання","завдання з подорожжю"}}},fp="15,253,26.515.0,16.478.0,36.166.0,51.205.0,31.234.0,48.213.0,29.153.0,40.267.0"}
P.entries["quest:6344"] = {n="Несса Шедовсонг",s="«Несса Шедовсонг» — вступне завдання-доручення від Мідраннула в Дарнасусі. Воно веде молодих шукачів пригод зі Світового Древа вниз, до Селища Рут'теран, на зустріч із торговкою рибальським приладдям Нессою Шедовсонг. Це перший крок, що пов'язує столицю в кронах із берегами й гаванями внизу.",h="«Несса Шедовсонг» — вступне завдання-доручення від Мідраннула в Дарнасусі.",kw={"несса шедовсонг","мідраннул","селище рут'теран","тельдрассил","обердайн","портал","гіпогрифи"},ang={["faction:Alliance"]="Це доручення знайомить із важливою мережею постачання, що пов'язує відрізаний острів Тельдрассил з рештою земель Альянсу в Калімдорі.",["race:NightElf"]="Для шукачів пригод із нічних ельфів ця подорож — традиційний вихід зі спокійних висот Дарнасуса на жваві прибережні шляхи, що поєднують їхній новий дім із давніми берегами Темного Узбережжя."},sec={{t="Доручення за межами крон",b="У Дарнасусі Мідраннул придивляється до мандрівників, що шукають роботи й мети. Коли торговці рибальським приладдям Нессі Шедовсонг треба переправити пакунок через море на Темне Узбережжя, Мідраннул скеровує здібних гінців до узбережжя. Чимало молодих нічних ельфів проводять перші мандри цілком у гіллі Тельдрассилу, а це просте прохання спонукає їх поглянути назовні, на материк."},{t="Спуск до пристані",b="Щоб дістатися Селища Рут'теран, треба ступити крізь сяйливе коріння західного порталу міста біля Храмових Садів. Ця брама спускається крізь Світове Древо до його коренів на рівні океану, де рибальські причали й сідала гіпогрифів пов'язують Тельдрассил з рештою Калімдору. Там Несса Шедовсонг порядкує своєю справою й готує вантажі для портового поселення Обердайн."}},faq={{q="Хто дає це завдання?",a="Завдання дає Мідраннул, що перебуває в Дарнасусі, на Терасі Воїна.",al={"хто дає завдання","де взяти завдання несси шедовсонг","де мідраннул"}},{q="Як дістатися до Селища Рут'теран?",a="Ідіть на захід від Храмових Садів у Дарнасусі. Ступіть у великий сяйний портал у дереві — і миттєво опинитеся внизу, у Селищі Рут'теран біля підніжжя Тельдрассилу.",al={"як дістатися рут'терана","портал рут'теран","вихід із дарнасуса"}},{q="Хто така Несса Шедовсонг?",a="Несса Шедовсонг — ельфійська постачальниця рибальського приладдя на причалах Селища Рут'теран. Вона наглядає за товарами й посилками, що курсують між Тельдрассилом і материковим Темним Узбережжям.",al={"роль несси шедовсонг","що робить несса","несса шедовсонг"}},{q="Куди веде цей ланцюжок завдань?",a="Розмова з Нессою одразу веде до завдання «Дари Тельдрассила», яке знайомить шукачів пригод із розпорядником польотів і дарує їм перший переліт через море до Обердайна.",al={"що після несси шедовсонг","наступне завдання ланцюжка","ланцюжок польотів тельдрассила"}},{q="Чи Несса родичка Маєв Шедовсонг?",a="Хоча в них спільне прізвище Шедовсонг, жодного відомого родинного зв'язку між Нессою, скромною торговкою рибою з пристані, і легендарною наглядачкою Маєв Шедовсонг немає.",al={"несса і маєв","родина шедовсонг","чи несса родичка маєв"}},{q="Чому це доручення важливе для молодих шукачів пригод?",a="Це головний дороговказ, що вчить нових героїв, як вибратися з крони Тельдрассилу, знайти причали внизу й навчитися літати гіпогрифами до материкового Калімдору.",al={"навіщо це завдання","значення завдання"}}},fp="16,310,26.391.0,23.390.0,22.85.0,35.171.0,24.179.0,33.183.0,37.175.0,51.198.0"}
P.entries["quest:6361"] = {n="Оберемок шкур",s="«Оберемок шкур» — вступне доручення з доставки в Пустках, яке дає таурен Джахан Гоквінг на Перехресті. Він просить мандрівників переправити вичинені шкури дичини через центральний Калімдор до Тандер Блафа для шкірників. Доручення знайомить нових гінців Орди із сідалом вітрокрилів на Перехресті й тим, як влаштовані перельоти.",h="«Оберемок шкур» — вступне доручення з доставки в Пустках, яке дає таурен Джахан Гоквінг на Перехресті.",kw={"оберемок шкур","джахан гоквінг","деврак","тандер блаф","вітрокрили","перехрестя"},ang={["faction:Horde"]="Ця доставка показує сполучення між базами Орди в Калімдорі, яке тримається на оркських приборкувачах звірів на кшталт Деврака, що долають відстані між союзними землями.",["race:Tauren"]="Для тауренів-мандрівників це доручення втілює давнє партнерство між мисливцями, що мандрують родовими Пустками, і майстрами, що осіли на великих столових горах Тандер Блафа."},sec={{t="Торгівля через савану",b="Перехрестя — гамірне серце торгівлі й подорожей по всіх Пустках, що поєднує орків, тролів і тауренів на посушливих рівнинах. Мисливці постійно здобувають шкури й м'ясо мандрівних звірів савани, але місцевим заставам бракує майстерень, щоб обробити всю сировину на місці. Джахан Гоквінг збирає шкури з навколишніх полювань і покладається на мандрівників, які доправлять їх на захід, до Тандер Блафа, де майстри-шкірники виготовлять потрібне Орді спорядження."},{t="У небо",b="Нести важкий вантаж пішки суворими стежками Пусток і далі вгору до Малгора — виснажлива подорож, повна засідок шипогривів і хижаків. Щоб пришвидшити торгівлю, Джахан скеровує гінців просто до Деврака, господаря вітрокрилів на Перехресті. Довіривши вантаж Девракові й злетівши на навченій виверні, гонець бачить, яка важлива мережа сполучення поєднує розкидані поселення Орди."}},faq={{q="Хто дає завдання «Оберемок шкур»?",a="Завдання дає Джахан Гоквінг, таурен із Перехрестя в Пустках. Він зібрав шкури місцевих звірів і шукає надійного кур'єра, який допоможе доправити їх до Тандер Блафа.",al={"хто дає оберемок шкур","видавець завдання","де взяти оберемок шкур"}},{q="Кому віднести оберемок шкур?",a="Оберемок треба віднести просто Девракові — орку, господареві вітрокрилів на сідалі Перехрестя. Він відає повітряним сполученням між Перехрестям та іншими головними осередками Орди.",al={"кому віднести шкури","куди нести шкури","з ким говорити"}},{q="Що буде, коли віддати шкури Девракові?",a="Деврак дає наступне завдання: сісти на вітрокрила й доправити вантаж просто до Агану, шкірника, що чекає на високих кручах Тандер Блафа.",al={"наступне завдання","що після оберемка шкур","продовження завдання"}},{q="Навіщо ці шкури везуть до Тандер Блафа?",a="Джахан Гоквінг співпрацює з товаришем на ім'я Агану з Тандер Блафа, який перетворює сирі шкури дичини з Пусток на готові шкіряні обладунки й вироби для тауренів та їхніх союзників з Орди.",al={"чому тандер блаф","шкури агану","для чого шкури"}},{q="Навіщо вітрокрил, а не пішки?",a="Іти пішки через безкраї Пустки й видиратися на величезну столову гору Тандер Блафа — довго й небезпечно. Вітрокрил швидко й безпечно перенесе вас над ворожими звірами савани та зграями шипогривів.",al={"чому летіти на вітрокрилі","політ вітрокрилом"}},{q="Чи потрібен для цього досвід польотів?",a="Це завдання задумане як раннє знайомство шукачів пригод Орди з розпорядниками польотів: воно знайомить вас із сідалом Деврака, щоб ви могли літати на вітрокрилах на далекі відстані.",al={"вимога польоту","чи потрібен маршрут польоту"}}},fp="17,347,24.480.0,19.410.0,38.193.0,42.185.0,46.168.0,48.184.0,40.212.0,49.202.0"}
P.entries["quest:6362"] = {n="Переліт до Тандер Блафа",s="Це завдання відправляє молодих шукачів пригод Орди в перший політ на вітрокрилі над Калімдором. Отримавши вантаж вичинених шкур, мандрівники вирушають із сухого роздоріжжя Пусток, щоб доставити цінні матеріали для шкірництва просто на висоти Тандер Блафа.",h="Це завдання відправляє молодих шукачів пригод Орди в перший політ на вітрокрилі над Калімдором.",kw={"переліт до тандер блафа","вітрокрил","деврак","агану","зброярня геви","шкури","тандер блаф"},ang={["faction:Horde"]="Надійні перельоти на вітрокрилах — запорука того, що віддалені застави в Пустках пов'язані з головними твердинями Дуротару й Малгору.",["race:Tauren"]="Для юних тауренів, що повертаються з Пусток, цей політ — легкий підйом просто на височенні кручі величної столиці їхнього народу."},sec={{t="Крила над саваною",b="Для багатьох мандрівників, що прямують Пустками, переліт, замовлений у Деврака, — перша подорож небом на спині вітрокрила. Ці крилаті виверни забезпечують життєво важливе повітряне сполучення між розкиданими поселеннями молодої Орди, оминаючи небезпечні наземні шляхи, де никають шипогриви й зграї кентаврів."},{t="Шкури для зброярні",b="Вантаж — це в'язка вичинених шкур, приготованих у Пустках і призначених для Агану, майстра, що працює в Зброярні Геви в Тандер Блафі. Агану, що влаштувався просто під великим гніздовищем вітрокрилів на центральній столовій горі, покладається на сировину з мисливських застав на рівнинах, щоб спорядити місцевих воїнів і мисливців."}},faq={{q="Хто дає завдання «Переліт до Тандер Блафа»?",a="Деврак, господар вітрокрилів на Перехресті в Пустках, дає це завдання мандрівникам, які принесли оберемок шкур.",al={"хто дає переліт до тандер блафа","де почати переліт до тандер блафа","де деврак"}},{q="Хто такий Агану і де його знайти?",a="Агану — таурен-ремісник у Зброярні Геви в Тандер Блафі, просто біля підніжжя міського сідала вітрокрилів.",al={"де агану","місце агану","збройова хеви"}},{q="Що перевозять у цій доставці?",a="Ви везете оберемок вичинених шкур із Пусток, які Агану одразу пустить на шкіряні вироби й обладунки.",al={"що я доставляю","оберемок шкур"}},{q="Навіщо вітрокрили, а не пішки?",a="Wind riders fly directly across the Barrens to Thunder Bluff's high mesas, avoiding the longer ground journey into Mulgore and landing at the city's wind rider tower.",al={"чому вітрокрили","користь маршруту польоту"}},{q="Де починається цей ланцюжок доставок?",a="Доставка починається з Джахана Гоквінга на Перехресті, який готує оберемок вичинених шкур у попередньому завданні — «Оберемок шкур».",al={"попереднє завдання","ланцюжок шкур"}},{q="Що далі, після доставки шкур?",a="Отримавши шкури, Агану скеровує мандрівників нагору — до Тала, Господаря Вітрокрилів Тандер Блафа.",al={"наступне завдання","продовження переліту до тандер блафа"}}},fp="21,284,25.339.0,20.343.0,42.141.0,39.134.0,43.148.0,39.166.0,37.143.0,43.127.0"}
P.entries["quest:6363"] = {n="Тал, господар вітрокрилів",s="«Тал, господар вітрокрилів» — просте доручення гінця, що пов'язує шкірників Малгору з торговцями в Пустках. Шкірник Агану довіряє вам пакунок готових шкіряних виробів, який треба відправити повітрям із Тандер Блафа. Доставляючи його просто до Тала, розпорядника польотів на столовій горі, молоді мандрівники Орди знайомляться з мережею перельотів на вітрокрилах.",h="«Тал, господар вітрокрилів» — просте доручення гінця, що пов'язує шкірників Малгору з торговцями в Пустках.",kw={"тал","господар вітрокрилів","агану","джахан гоквінг","перехрестя","вітрокрили","тандер блаф"},ang={["faction:Horde"]="Надійні повітряні шляхи між Пустками й Тандер Блафом дають змогу швидко перекидати підкріплення, товари й послання через центральний Калімдор.",["race:Tauren"]="Вітрокрили, що гніздяться на кручах Тандер Блафа, — життєво важлива ланка, яка вплітає відокремлений народ Кайрна Бладгуфа в ширший союз Орди."},sec={{t="Припаси для Перехрестя",b="Торгівля між Малгором і посушливими чагарниками Пусток життєво важлива для молодої Орди. Агану, шкірник, що продає свої вироби на нижньому узвишші Тандер Блафа, виготовляє міцні шкіряні речі для торгової ятки Джахана Гоквінга на Перехресті. Пішки дорога вниз із круч і через золоті рівнини забирає години, тож торговці покладаються на крилатих гінців, щоб ті переносили крихкі чи термінові пакунки через скелясті перевали."},{t="Господар гніздовища на столовій горі",b="На найвищому центральному ярусі Тандер Блафа Тал доглядає міську зграю вітрокрилів, яких також називають вивернами. Ці розумні звірі зі шкірястими крилами напрочуд добре пристосовані до мінливих висхідних потоків і скелястих вершин Калімдору. Тал організовує перельоти до застав, як-от Перехрестя, дбаючи, щоб гінці й вантажі швидко переміщалися між столицею тауренів і їхніми союзниками-орками."}},faq={{q="Хто такий Тал?",a="Тал — розпорядник польотів Тандер Блафа, що відає сідалом вітрокрилів на центральній столовій горі. Він влаштовує перельоти для мандрівників і кур'єрів до Пусток і далі.",al={"хто такий тал","тал тандер блаф","майстер вітрокрилів тал"}},{q="Хто такий Агану?",a="Агану — таурен-шкірник із Тандер Блафа. Він виготовляє великі партії шкіряних виробів і пакує їх для торговців на заставах по всьому Калімдору, зокрема для Джахана Гоквінга на Перехресті.",al={"агану","хто такий агану","агану тандер блаф"}},{q="Навіщо везти товари на Перехрестя?",a="Перехрестя — життєво важливий торговий і військовий вузол Пусток. Товари, виготовлені в мирному затишку Малгора, як-от шкури й шкіряний одяг, відправляють туди, щоб забезпечити мандрівників, мисливців і патрулі Орди.",al={"чому перехрестя","шкіряні вироби перехрестя","джахан шкіра"}},{q="Чи можу я полетіти з цією посилкою просто на Перехрестя?",a="Полетіти на Перехрестя можна лише тоді, коли ви вже побували в поселенні й познайомилися з Девраком, тамтешнім господарем вітрокрилів. Якщо цей маршрут ще не відкрито, доведеться йти пішки.",al={"чи можна летіти на перехрестя","маршрут тала","як летіти на перехрестя"}},{q="Хто такі вітрокрили?",a="Вітрокрили, яких зазвичай звуть вивернами, — розумні отруйні крилаті хижаки, що живуть у скелях Калімдору. Від часів Третьої війни вони союзники Орди й слугують їй головними летючими скакунами.",al={"віверни","що таке вітрокрил","скакуни тауренів"}},{q="Куди веде це кур'єрське доручення далі?",a="Коли ви доставите товари Талові, він доручить вам узяти вітрокрила й доправити посилку Агану через рівнини до Джахана Гоквінга, що чекає на Перехресті.",al={"наступне завдання","що після тала","куди шкіряні вироби далі"}}},fp="25,339,27.439.0,26.421.0,11.198.0,13.208.0,46.235.0,54.220.0,21.204.0,41.159.0"}
P.entries["quest:6364"] = {n="Повернення до Джахана",s="«Повернення до Джахана» — останній відрізок знайомства з мережею перельотів Орди на вітрокрилах між Малгором і Пустками. Доставивши шкури шкірникові Агану в Тандер Блаф, мандрівники летять на виверні назад на Перехрестя з готовими шкіряними виробами для торговця Джахана Гоквінга.",h="«Повернення до Джахана» — останній відрізок знайомства з мережею перельотів Орди на вітрокрилах між Малгором...",kw={"повернення до джахана","джахан гоквінг","агану","тал","вітрокрили","перехрестя","червоні скелі"},ang={["faction:Horde"]="Повітряні шляхи вітрокрилів між Малгором, Дуротаром і Пустками — життєво важливі артерії, що з'єднують володіння Орди в центральному Калімдорі.",["race:Tauren"]="Торгові ланцюжки між чинбарями Малгору й заставами Пусток показують, як об'єднані племена підтримують ширше освоєння прикордоння Ордою."},sec={{t="Крила над Калімдором",b="Для багатьох мандрівників це доручення — перший досвід польоту на навченому вітрокрилі. Тал, господар вітрокрилів, що оселився на центральній столовій горі Тандер Блафа, влаштовує перельоти над рівнинами центрального Калімдору. Якщо мандрівник уже знайомий із гніздовищем в іншому поселенні — як-от заставою Деврака на Перехресті, — ці крилаті звірі без зусиль долають ліги, які інакше довелося б іти небезпечним суходолом через Червоні Скелі й північ Пусток."},{t="Торгівля Перехрестя",b="Цей рейс гінця має й господарську мету, а не лише навчання польотам. Джахан Гоквінг торгує в гамірному поселенні Перехрестя, де щодня збираються мисливці, розвідники й найманці. Сирі шкури, надіслані до Агану на високі узвишшя Тандер Блафа, перетворюються на міцні обладунки й спорядження, а тоді повертаються повітрям на запилене роздоріжжя Пусток, щоб забезпечити прикордонні зусилля Орди, що невпинно ширяться."}},faq={{q="Хто такий Джахан Гоквінг?",a="Джахан Гоквінг — купець-таурен на Перехресті в Пустках. Він купує й продає шкіряні вироби й покладається на ремісників із Тандер Блафа, які перетворюють сирі шкури звірів на цінне спорядження для мандрівних шукачів пригод.",al={"джахан","переказ про джахана гоквінга","хто такий джахан"}},{q="Чому назад на Перехрестя треба летіти вітрокрилом?",a="Ця подорож показує, як працює мережа польотів. Господарі вітрокрилів, як-от Тал у Тандер Блафі, можуть відправляти кур'єрів і пасажирів лише до поселень, які самі розвідали чи з якими встановили зв'язок, — наприклад, до сідала Деврака на Перехресті.",al={"чому летіти назад","вітрокрил назад","як працюють маршрути польоту"}},{q="Хто такий Агану?",a="Агану — вправний шкірник і білувальник на високих кручах Тандер Блафа. Він приймає сирі шкури від мисливців із Пусток, робить із них готові вироби й відсилає назад на продаж.",al={"агану","агану тандер блаф","хто зробив вироби"}},{q="Хто такий Деврак?",a="Деврак — орк, господар вітрокрилів на Перехресті. Він відає сідалом, що з'єднує Пустки з головними твердинями Орди — Оргріммаром і Тандер Блафом.",al={"деврак","майстер польотів перехрестя","майстер вітрокрилів деврак"}},{q="Чи можна летіти на вітрокрилі, не поговоривши спершу з господарем у місці призначення?",a="Ні. Вітрокрилів можна відправити лише до застав, де мандрівник уже зустрівся з місцевим господарем вітрокрилів і відмітився в нього, — так встановлюється зв'язок між сідалами.",al={"правила польоту","відкрити майстра польотів","чи можна летіти куди завгодно"}},{q="Що буде, коли повернути шкіряні вироби Джаханові?",a="Доставка готових виробів завершує кур'єрський ланцюжок між Малгором і Пустками: мандрівники вже знають, як подорожувати повітрям, і можуть далі допомагати гарнізону й купцям Перехрестя.",al={"продовження завдання","що далі","після повернення до джахана"}}},fp="15,313,19.511.0,26.408.0,22.219.0,58.249.0,13.212.0,14.179.0,74.176.0,56.211.0"}
P.entries["quest:6365"] = {n="М'ясо до Оргріммара",s="«М'ясо до Оргріммара» — коротке вступне доручення з доставки від Зарга на Перехресті. Він просить молодих шукачів пригод — орків і тролів — віднести пакунок добірного м'яса з Пусток господареві вітрокрилів у поселенні, Девракові, і так знайомить їх із перельотами назад до столиці Орди.",h="«М'ясо до Оргріммара» — коротке вступне доручення з доставки від Зарга на Перехресті.",kw={"м'ясо до оргріммара","зарг","деврак","гришка","вітрокрили","оргріммар"},ang={["profession:Cooking"]="Свіже м'ясо з рівнин Пусток для корчми Гришки в Оргріммарі — запорука того, що ситні казани столиці не порожніють для воїнів, які заходять у гості.",["race:Orc"]="Для молодих орків, що покидають Дуротар, щоб полювати в Пустках, доставка пакунка Зарга — швидкий спосіб прокласти повітряний шлях просто назад до столиці Вождя.",["race:Troll"]="Тролі з Темного Спису, що працюють на Перехресті, завдяки цьому дорученню прив'язують нові застави в дикій глушині до шляхів постачання Оргріммара."},sec={{t="Свіжа дичина з Пусток",b="Неосяжні рівнини Пусток рясніють звіриною — від жевр і степових довгоступів до кодо й громоящерів. Зарг приготував кілька добірних шматків як особисту посилку для Гришки, клопітливої корчмарки з Долини Сили в Оргріммарі. Щоб м'ясо лишилося свіжим і не довелося довго брести курною дорогою через Річку Південної Люті в Дуротар, Зарг посилає гінців через Перехрестя просто до сідала вітрокрилів."},{t="Крила над степами",b="Зустріч із Девраком — перше офіційне знайомство молодого воїна Орди з мережею перельотів на вітрокрилах. Співпрацюючи з господарями вітрокрилів, Орда поєднує віддалені застави на кшталт Перехрестя просто зі своєю укріпленою столицею в Оргріммарі. Деврак готує гінця й вантаж до швидкого перельоту над саваною."}},faq={{q="Кому Зарг надсилає це м'ясо?",a="Зарг надсилає шматки м'яса своїй подрузі Гришці — улюбленій усіма корчмарці, що тримає головну таверну в Долині Сили в Оргріммарі.",al={"кому м'ясо","для кого м'ясо","отримувач м'яса від зарга"}},{q="Чому це завдання можуть узяти лише орки й тролі?",a="Це завдання — вступ до польотів для своїх: воно з'єднує орків і тролів Темного Спису з їхньою спільною столицею, Оргріммаром. Тауренів скеровують до Тандер Блафа через завдання «Оберемок шкур», а Відступники отримують «Постачання для Гробниці», що пов'язує їх зі Срібноліссям.",al={"чому таурени не можуть це взяти","завдання з м'ясом нежиті","обмеження за расою"}},{q="Хто такий Деврак?",a="Деврак — орк, господар вітрокрилів на Перехресті в Пустках. Він наглядає за вивернами, які переносять послання, припаси й мандрівників по всьому Калімдору.",al={"деврак перехрестя","хто такий деврак"}},{q="Що буде, коли віддати м'ясо Девракові?",a="Деврак приймає вантаж і влаштовує вам переліт на вітрокрилі до Небесної Вежі Оргріммара, щоб ви віднесли м'ясо Гришці до її корчми, — це наступне завдання, «Переліт до Оргріммара».",al={"наступне завдання після м'яса до оргріммара","що робить деврак"}},{q="Де знайти Зарга?",a="Зарг перебуває на Перехресті — головному торговому осередку Орди на центральному роздоріжжі Пусток.",al={"де зарг","місце зарга"}},{q="Навіщо вітрокрил, а не пішки?",a="Вітрокрили швидко переносять через суворі простори Пусток і річковий каньйон до Дуротару, тож делікатний вантаж на кшталт свіжого м'яса прибуває до Оргріммара, не встигнувши зіпсуватися.",al={"чому летіти до оргріммара","вітрокрил м'ясо"}}},fp="18,286,27.443.0,22.338.0,34.142.0,45.309.0,14.172.0,45.195.0,23.116.0,40.193.0"}
P.entries["quest:637"] = {n="Лист Саллі Баллу",s="Знайдений на потонулому кістяку під розбитими арками Мосту Тандол, цей розмоклий лист містить передсмертні слова дворфійського солдата на ім'я Саллі Баллу. Адресований його дружині Сарі в Айронфорджі, він несе останні думки захисника, що зник у крижаних водах річки під час боїв за міст.",h="Знайдений на потонулому кістяку під розбитими арками Мосту Тандол, цей розмоклий лист містить передсмертні...",kw={"саллі баллу","лист","міст тандол","сара баллу","айронфордж","удова","багнокрай"},ang={["faction:Alliance"]="Лист — зворушливе нагадування про особисту жертву рядових солдатів передової, які бережуть крихкі сухопутні зв'язки між південними й північними землями Альянсу.",["race:Dwarf"]="Для дворфів Айронфорджа повернути останні слова Саллі — означає вшанувати побратима, який поклав життя, обороняючи велику дворфійську кам'яну споруду від північних загроз."},sec={{t="Голос із річкового дна",b="Під масивними кам'яними опорами Мосту Тандол — важливої переправи, що з'єднує Багнокрай з Аратійським нагір'ям, — лежить потонулий кістяк полеглого дворфа. У кістлявій руці він досі стискає пошкоджений водою конверт, який ледве витримує дотик. Написані з болісною ретельністю серед пожеж бою, сторінки починаються ніжним «Моя люба Саро…», зберігаючи голос солдата довго після того, як його забрала вода."},{t="Ціна Мосту",b="Міст Тандол бачив запеклі бої між силами Альянсу та їхніми ворогами — від диверсантів Темного Заліза до розбійницьких ватаг, що зазіхають на прикордоння. Саллі Баллу був одним із багатьох дворфійських солдатів, посланих на північ боронити цю важливу переправу. Коли він загинув під хвилями, його доля лишалася невідомою родині в горах, доки нирець нарешті не дістав його прощальний заповіт."},{t="Удова в Айронфорджі",b="Повернення врятованого листа до Айронфорджа тихо спустошує вдову Саллі, Сару Баллу. Живучи серед гамірних зал дворфійської столиці, вона застигла між горем і крихкою надією, не знаючи, зник її чоловік безвісти чи втрачений назавжди. Побачивши його рукописні слова й дізнавшись про його могилу під водою, вона нарешті змушена зустрітися з гіркою правдою про його смерть."}},faq={{q="Де знайти лист Саллі Баллу?",a="Лист тримає в руці затоплений скелет, що лежить глибоко на дні річки просто під масивними кам'яними опорами Мосту Тандол, який з'єднує Багнокрай з Аратійським нагір'ям.",al={"де лист саллі баллу","де саллі баллу","скелет біля мосту тандол"}},{q="Ким був Саллі Баллу?",a="Саллі Баллу — солдат-дворф Альянсу, що поліг, захищаючи Міст Тандол. Притиснутий під крижаною водою під час боїв за переправу, він устиг написати останній лист своїй дружині Сарі, перш ніж помер.",al={"хто такий саллі","переказ про саллі баллу","ким був саллі баллу"}},{q="Хто така Сара Баллу?",a="Сара Баллу — вдова Саллі, що живе у великій столиці дворфів, Айронфорджі. Вона місяцями чекала звісток про долю чоловіка на північному кордоні.",al={"де сара баллу","хто така сара","місце сари баллу"}},{q="Що буде, коли доставити лист?",a="Отримавши гірке підтвердження смерті Саллі, Сара Баллу поринає в горе й просить увічнити пам'ять про нього — історія триває в наступному проханні в Айронфорджі.",al={"що далі","ланцюжок саллі","після доставки листа"}},{q="Чому лист уцілів під водою?",a="Лист захищав конверт, міцно стиснутий у руці загиблого. Коли його дістають, він уже частково розмоклий і розплився, але кілька сторінок, списаних старанним почерком, ще можна прочитати.",al={"чому лист читабельний","як конверт вцілів"}},{q="Що з реального світу надихнуло це завдання?",a="Завдання — данина пам'яті майорові Саллівану Балу з 2-го Род-Айлендського піхотного полку часів Громадянської війни в США: незадовго до загибелі в першій битві при Булл-Рані він написав дружині знаменитий поетичний прощальний лист.",al={"цікавинки саллі баллу","саллівен баллу","посилання на громадянську війну"}}},fp="21,327,25.455.0,21.403.0,20.428.1,37.197.0,21.214.0,19.167.0,42.203.1,43.229.0,49.228.0"}
P.entries["quest:6381"] = {n="Нове життя",s="«Нове життя» — цілюще завдання Орди від Таммри Віндфілд у Притулку Сонячної Скелі. Зібравши зачароване насіння, ви вирушаєте на захід, у попелясті руїни Обвугленої Долини, щоб посіяти його в родючу землю. Цей обряд має пробудити відродження краю попри ворожих елементалів і гарпій.",h="«Нове життя» — цілюще завдання Орди від Таммри Віндфілд у Притулку Сонячної Скелі.",kw={"нове життя","таммра віндфілд","насіння геї","обвуглена долина","земна мати","відродження"},ang={["class:Druid"]="Друїдам близька місія Таммри: відродження Обвугленої Долини для них — необхідне відновлення тендітної рівноваги природи.",["class:Shaman"]="Шамани розуміють: розлючені вогняні елементалі, що блукають Долиною, не знайдуть спокою, доки не почне загоюватися сама сплюндрована земля.",["profession:Herbalism"]="Травники цінують неабияку силу витривалого насіння, здатного виростити буйну зелень навіть із геть мертвої землі.",["race:Tauren"]="Для тауренів посів зачарованого насіння в поранену землю — духовне єднання із Земною Матір'ю й виконання священного обов'язку зцілювати скалічені краї."},sec={{t="Зцілення випаленої землі",b="Обвуглена Долина — трагічне свідчення недавнього спустошення: її душать кіптява, люті вогняні елементалі й гарпії-стерв'ятники. Таммра Віндфілд не дає краю скоритися руїні. Покладаючись на давню стійкість Земної Матері, вона посилає мандрівників у саме серце почорнілої долини — шукати Купи Землі Геї, клапті родючого ґрунту, що вціліли в пожарищі."},{t="Опора для майбутнього",b="Зачароване насіння Геї, посіяне у випалену землю, виведене так, щоб витримувати рештки стихійної скверни. Пустивши коріння, воно сплітає живу опору, яка опирається тліну й кличе рослини назад у долину. Таммра бачить попереду довге зцілення: коли живе коріння поволі відвоює улоговину, розлючені вогняні духи вгамуються, гарпії втратять своє похмуре гніздовище, а ненаситну лісорозробку Венчурної Компанії зрештою буде вигнано геть."}},faq={{q="Навіщо садити насіння Ґеї?",a="Зачароване насіння Ґеї має вкоренитися в пораненій землі Обвугленої Долини. Воно опирається скверні й закладає перший осередок буйного рослинного життя — основу, на якій ліс поступово відросте й загоїться.",al={"навіщо садити насіння","мета нового життя","що робить насіння ґеї"}},{q="Куди треба вирушити, щоб посадити насіння?",a="Вам треба податися на захід від Притулку Сонячної Скелі, в Обвуглену Долину. Насіння садять у невеликі земляні горбики Ґеї, розкидані по почорнілій улоговині.",al={"де обвуглена долина","де садити насіння ґеї","місця для насіння"}},{q="Хто така Таммра Віндфілд?",a="Таммра Віндфілд — тауренка-природознавиця з Притулку Сонячної Скелі в Горах Кам'яного Кігтя. Вона присвятила себе тому, щоб заспокоювати поранених духів землі й відновлювати місця, сплюндровані люттю стихій і промисловою жадібністю.",al={"хто дає нове життя","видавець таммра","переказ про таммру віндфілд"}},{q="Які загрози чатують в Обвугленій Долині під час садіння?",a="В Обвугленій Долині блукають здичавілі вогняні елементалі, розбурхані недавнім спустошенням, а також агресивні гарпії Бладф'юрі, що гніздяться серед обгорілих дерев.",al={"вороги обвугленої долини","хто нападає в обвугленій долині","небезпеки обвугленої долини"}},{q="Яке завдання передує «Новому життю»?",a="«Нове життя» йде одразу після завдання «Цикл переродження», у якому ви допомагаєте Таммрі зібрати все потрібне для зачарованого насіння Ґеї.",al={"попереднє завдання нового життя","цикл переродження","що веде до нового життя"}},{q="На що Таммра сподівається для Кам'яного Кігтя в майбутньому?",a="Таммра сподівається, що відроджена земля згодом угамує розлючених вогняних елементалів, витіснить хижих гарпій і переживе вирубки Венчурної Компанії, повернувши горам буйний і мирний ліс.",al={"майбутнє кам'яного кігтя","мета таммри","що буде з обвугленою долиною"}}},fp="8,321,26.399.0,25.486.0,47.240.0,41.153.0,24.235.0,50.166.0,33.152.0,58.228.0"}
P.entries["quest:6382"] = {n="Полювання в Ашенвалі",s="«Полювання в Ашенвалі» — настанова, що виводить досвідчених шукачів пригод Орди з посушливих Пусток на північ, у густі ліси Ашенвалю. Джорн Скайсір із Табору Тауражо посилає мандрівників на Заставу Розщепленого Дерева, щоб допомогти Сенані Тандергарт і перевірити своє вміння вистежувати в дикому, спірному краї.",h="«Полювання в Ашенвалі» — настанова, що виводить досвідчених шукачів пригод Орди з посушливих Пусток на...",kw={"полювання в ашенвалі","джорн скайсір","сенані тандергарт","застава розщепленого дерева","мисливці","завдання"},ang={["class:Hunter"]="Перехід із рівнин Калімдору до Ашенвалю — величезна зміна місцевості: під густим лісовим покровом на вас чекають екзотичні звірі, яких можна вистежувати, вивчати й приручати.",["faction:Horde"]="Ашенваль — вкрай важливий стратегічний рубіж: закріпившись тут, Орда отримує деревину й харчі, без яких не обійтися поселенням у Дуротарі та Пустках.",["race:Tauren"]="І Джорн Скайсір, і Сенані Тандергарт ведуть цю мандрівку, вбачаючи в полюванні не просто вбивство, а духовну рівновагу й спосіб ушанувати дику природу."},sec={{t="Під прадавній покров лісу",b="Довівши свою мисливську вправність на вибілених сонцем рівнинах Пусток, мисливці й воїни Орди вирушають на зовсім інше випробувальне поле. Джорн Скайсір бачить, коли мандрівник переріс місцеву дичину, і посилає його на північ, до Ашенвалю. Для молодої Орди ці прадавні ліси — і скарбниця ресурсів, і глибокий політичний та духовний рубіж, який вона мусить навчитися розуміти й здобути."},{t="Застава Розщепленого Дерева",b="Звивиста дорога на північ повз Вал Мор'шан приводить мандрівників до Застави Розщепленого Дерева — укріпленого табору Орди глибоко в лісі. Там тауренська мисливиця Сенані Тандергарт вітає досвідчених прибульців, що шукають суворіших випробувань на виживання. Щоб процвітати в Ашенвалі, Орда покладається на вправних слідопитів, які вміють давати раду не лише агресивним місцевим хижакам, а й ворожим пильним очам захисників лісу."}},faq={{q="Хто посилає мене на «Полювання в Ашенвалі»?",a="Джорн Скайсір, мисливець-таурен із Табору Тауражо на півдні Пусток, дає це завдання, коли ви покажете свою вправність у полюванні на місцевих звірів.",al={"хто дає полювання в ашенвалі","видавець полювання в ашенвалі","завдання йорна скайсіра"}},{q="Де розташована Застава Розщепленого Дерева?",a="Застава Розщепленого Дерева лежить у центрально-східному Ашенвалі. Якщо йти головною дорогою на північ із Пусток повз Вал Мор'шан і далі лісом, укріплена застава буде на північному боці дороги.",al={"де застава розщепленого дерева","де сенані тандергарт","знайти заставу розщепленого дерева"}},{q="Хто така Сенані Тандергарт?",a="Сенані Тандергарт — мисливиця-тауренка із Застави Розщепленого Дерева. Вона керує полюванням по всьому Ашенвалю й навчає новоприбулих шукачів пригод Орди вистежувати найлютіших хижаків і духів прадавнього лісу.",al={"сенані тандергарт","хто така сенані","мисливиця сенані"}},{q="Які ще застави Орди є поблизу в Ашенвалі?",a="Окрім Застави Розщепленого Дерева, Орда тримає Лісозаготівельний Табір Бойової Пісні на сході й Заставу Зорам'гар на далекому західному узбережжі Зорам.",al={"бази орди в ашенвалі","інші табори в ашенвалі"}},{q="Чому Орду цікавить полювання в Ашенвалі?",a="Дикі ліси дають м'ясо, шкури й ресурси, яких бракує посушливим землям Дуротару й Пусток. До того ж сутичка з небезпечними звірами лісу вважається важливим випробуванням волі й духовної сили для воїнів і мисливців Орди.",al={"чому полювання в ашенвалі","мотивація орди в ашенвалі"}},{q="Які випробування йдуть після цієї подорожі?",a="Сенані Тандергарт залучає досвідчених мисливців вистежувати відомих лісових хижаків і посилає їх у хащі полювати на найгрізніших: велетенського ведмедя Урсанґуса, кішку Шадумбру й гіпогрифа Шарпталона.",al={"наступне завдання після полювання","що дає сенані"}}},fp="18,317,23.443.0,17.452.0,35.159.0,35.225.0,27.226.0,50.149.0,52.252.0,36.227.0"}
P.entries["quest:6383"] = {n="Полювання в Ашенвалі",s="«Полювання в Ашенвалі» — давній обряд, за яким наглядає Сенані Тандергарт на Заставі Розщепленого Дерева. Мисливцям Орди кидають виклик: вистежити й здолати трьох легендарних лісових хижаків, що никають прадавнім лісом, — ведмедя Урсанґуса, нічного шаблезуба Шадумбру та лютого гіпогрифа Шарпталона. Це не просто випробування зброєю, а шлях до хитрості, шани й пізнання себе.",h="«Полювання в Ашенвалі» — давній обряд, за яким наглядає Сенані Тандергарт на Заставі Розщепленого Дерева.",kw={"полювання в ашенвалі","сенані тандергарт","урсанґус","шадумбра","шарпталон","завдання"},ang={["class:Hunter"]="Полювання — класичний обряд посвяти: слідопит мусить обнишпорити величезні простори лісу, читати місцевість і зійтися зі звірами, які легко здолають необачного розвідника.",["faction:Horde"]="На противагу руйнівним суцільним вирубкам Бойової Пісні полювання відкриває Орді шлях бойової честі та духовного вкорінення в спірному Ашенвалі.",["race:Tauren"]="Для тауренських мисливців полювання на Урсанґуса, Шадумбру й Шарпталона — вияв споконвічної шани до творіння Земної Матері, де повага до лютості природи врівноважується честю мисливця."},sec={{t="Тауренська традиція в прадавньому лісі",b="Поки Орда закріплюється глибоко в Ашенвалі, духовні науки Земної Матері знаходять голос у Сенані Тандергарт. На відміну від агресивної орківської лісозаготівлі, полювання Сенані ставиться до затінених лісів як до священного випробувального поля. Змагаючись розумом із верховними хижаками лісу, мисливець має поєднатися з неприборканою природою й виплекати тиху покору, без якої в Ашенвалі не вижити."},{t="Три великі звірі",b="Полювання зосереджене на трьох самотніх легендах, що блукають серед гілля. Біля Стежки Глибокого Кігтя бродить Урсанґус — величезний старий ведмідь, чия сила випробовує тілесну витривалість. Далі на схід, на межі біля Притулку Рейнвуд і невловимих сестер-реготух, чатує Шадумбра — потайна нічний шаблезуб, шанована за хитрість. І нарешті, на південь від Застави Розщепленого Дерева кружляє Шарпталон — лютий гіпогриф, чиє панування в кронах лісу завершує випробування."}},faq={{q="Хто починає «Полювання в Ашенвалі»?",a="Полювання очолює Сенані Тандергарт, мисливиця-тауренка в Ашенвалі. Вона кидає виклик мандрівникам Орди, які хочуть довести, що вміють виживати в дикій природі.",al={"видавець полювання в ашенвалі","хто дає полювання","завдання сенані тандергарт"}},{q="Яких звірів треба вистежити?",a="Треба вистежити й убити трьох легендарних хижаків: велетенського ведмедя Урсанґуса, нічну шаблезубу кішку Шадумбру й лютого гіпогрифа Шарпталона.",al={"яких тварин убити","три звірі","цілі полювання в ашенвалі"}},{q="Де знайти Урсанґуса?",a="Урсанґус блукає невеликою ділянкою трохи на захід від Стежки Глибокого Кігтя, серед інших диких ведмедів лісу.",al={"де урсанґус","де ведмідь","знайти урсанґуса"}},{q="Де нишпорить Шадумбра?",a="Шадумбра нишпорить на південь від Притулку Рейнвуд, полюючи біля дороги, де живуть дріади, відомі як Сміхотливі Сестри.",al={"де шадумбра","місце шадумбри","місце шаблезуба"}},{q="Де вистежити Шарпталона?",a="Шарпталон облітає широку територію на південь від Застави Розщепленого Дерева, проносячись між деревами й над галявинами.",al={"де шарпталон","місце шарпталона","місце гіпогрифа"}},{q="Навіщо Сенані Тандергарт посилає мисливців по цих звірів?",a="Сенані задумала полювання як почесне випробування, а не безглузду різанину. Мірячись силами з найсмертоноснішими мешканцями лісу, мисливці мають зрозуміти дику природу й пізнати власну внутрішню силу.",al={"навіщо полювання","мета полювання","переказ про полювання"}}},fp="18,403,39.442.0,22.458.0,30.191.0,36.144.0,29.119.0,28.127.0,32.115.0,61.244.0"}
P.entries["quest:6384"] = {n="Переліт до Оргріммара",s="Це доручення знайомить шукачів пригод Орди з повітряними подорожами Калімдором: ви наймаєте вітрокрила, щоб полетіти з Перехрестя до Оргріммара. Отримавши від Зарга свіжі шматки м'яса, мандрівники приземляються на небесній вежі столиці й несуть пакунок просто Корчмарці Гришці.",h="Це доручення знайомить шукачів пригод Орди з повітряними подорожами Калімдором: ви наймаєте вітрокрила, щоб...",kw={"вітрокрил","переліт","перехрестя","оргріммар","зарг","корчмарка гришка","деврак"},ang={["faction:Horde"]="Переліт на вітрокрилі між Перехрестям і Оргріммаром — головна життєва артерія, що з'єднує серце Пусток з осердям влади Вождя Тралла.",["profession:Cooking"]="Отримавши Заргів подарунок, Гришка не лишає жодних сумнівів щодо своїх кулінарних уподобань: найкращих звірів Калімдору слід подавати з кров'ю, щоб зберегти смак."},sec={{t="Крила над саваною",b="Долати пішки посушливі простори між Перехрестям і червоними скелями Дуротару — виснажлива справа, тож Орда тримає надійну мережу навчених вітрокрилів, які скорочують відстань. Деврак, розпорядник польотів на Перехресті, опікується цими вивернами: він відправляє гінців і мандрівників високо над запиленими стежками каньйонів, щоб важливі донесення й товари швидко потрапляли просто до столиці."},{t="Особлива доставка для Гришки",b="Цей політ — не просто прогулянка задля краєвидів, у ньому є особиста нотка. Зарг із Перехрестя приготував пакунок добірних сирих шматків м'яса для Корчмарки Гришки, що тримає заїзд у Долині Сили в Оргріммарі. Щойно вітрокрил сідає на центральну небесну вежу Оргріммара, до заїзду Гришки лишається кілька кроків. Там вона радо приймає подарунок і з теплотою зауважує, що Зарг таки знає шлях до жіночого серця."}},faq={{q="Навіщо цей переліт?",a="Подорож — практичне знайомство з мережею перельотів Орди на вітрокрилах. Ви платите Девракові за переліт із Перехрестя до Оргріммара, щоб доставити свіже м'ясо від Зарга Корчмарці Гришці.",al={"чому летіти до оргріммара","мета переліту до оргріммара","навіщо м'ясо до оргріммара"}},{q="Де в Оргріммарі сідає вітрокрил?",a="Вітрокрил сідає на Небесній Вежі Оргріммара, що здіймається високо над Долиною Сили. З майданчика вежі пандусами можна спуститися на головну площу, до найближчих торговців і корчми Гришки.",al={"де приземлятися в оргріммарі","місце скайтавера","місце посадки в оргріммарі"}},{q="Хто така Гришка?",a="Корчмарка Гришка тримає гамірну таверну в Долині Сили в Оргріммарі. Вона гостинно приймає втомлених мандрівників у столиці й тепло приятелює із Заргом, який регулярно постачає їй добірне сире м'ясо для кухні.",al={"корчмарка гришка","хто така гришка","де гришка"}},{q="Хто такий Деврак?",a="Деврак — господар вітрокрилів на Перехресті в Пустках. Він доглядає виверн і влаштовує повітряне сполучення між заставою в Пустках, Дуротаром та іншими поселеннями Орди.",al={"деврак перехрестя","хто такий деврак","майстер вітрокрилів перехрестя"}},{q="Чому Зарг надсилає Гришці сире м'ясо?",a="Зарг вважає свіжу дичину з Пусток цінним дарунком. Гришка надзвичайно тішиться ним і зауважує, що добірні шматки з кров'ю — найпевніший шлях до її серця.",al={"м'ясо зарга","чому м'ясо гришці","зарг і гришка"}},{q="Що робити після доставки м'яса?",a="Коли доставку в корчмі завершено, Гришка скеровує мандрівників назад до Небесної Вежі — поговорити з Дорасом, господарем вітрокрилів Оргріммара, і приготуватися до зворотного шляху.",al={"що після переліту до оргріммара","наступне завдання після гришки","куди далі після доставки"}}},fp="17,275,22.394.0,28.423.0,35.215.0,44.198.0,15.239.0,14.197.0,41.165.0,43.180.0"}
P.entries["quest:6385"] = {n="Дорас, господар вітрокрилів",s="Корчмарка Гришка з Оргріммара написала Заргові на Перехресті листа з подякою, і їй потрібен гонець, який доставить його повітрям назад у Пустки. Щоб домовитися про переліт, вона відсилає мандрівників на міську небесну вежу до Дораса — головного господаря вітрокрилів Орди.",h="Корчмарка Гришка з Оргріммара написала Заргові на Перехресті листа з подякою, і їй потрібен гонець, який...",kw={"дорас","вітрокрил","господар вітрокрилів","корчмарка гришка","зарг","оргріммар","долина сили"},ang={["faction:Horde"]="Мережа вітрокрилів з'єднує Оргріммар із ключовими залогами в різних краях і служить тим сухожиллям, що дає молодій Орді змогу перекидати сили й постачати припаси через нетрі Калімдору.",["race:Orc"]="Відколи орки ступили на землі Калімдору, вони встигли зріднитися з місцевими вивернами й покладаються на їхню спритність і силу — і як на крилатих верхових звірів, і як на в'ючних гінців."},sec={{t="Відповідь із гінцем",b="Отримавши свіжу партію м'яса, доставлену повітрям із мисливських угідь Пусток, Корчмарка Гришка складає офіційного листа з подякою м'ясникові Заргу. Не маючи часу самій вирушати суходолом через Дуротар, вона покладається на повітряну поштову мережу, що пов'язує головні поселення Орди в Калімдорі, щоб її послання швидко полетіло назад через прикордоння."},{t="Господар гніздовища",b="Дорас опікується гніздовищем вітрокрилів Оргріммара на вершині польотної вежі в Долині Сили. Його навчені виверни — життєва сила військового зв'язку й постачання Орди: вони долають небезпечну відстань між столицею й віддаленими заставами, як-от Перехрестя, за частку того часу, який забирає піша дорога чи віз, запряжений кодо."}},faq={{q="Хто такий Дорас?",a="Дорас — головний господар вітрокрилів в Оргріммарі. Він відає міськими навченими вивернами й влаштовує перельоти до віддалених осередків Орди по всьому центральному Калімдору.",al={"дорас","хто такий дорас","майстер польотів оргріммара"}},{q="Навіщо Корчмарка Гришка надсилає цього листа?",a="Гришка надсилає письмову подяку Заргові, м'ясникові з Перехрестя, на знак того, що м'ясо щасливо дісталося її таверни в Оргріммарі.",al={"навіщо лист","лист гришки","для чого лист"}},{q="Де знайти Дораса?",a="Дорас стоїть на верхівці центральної льотної вежі над Долиною Сили в Оргріммарі; туди можна піднятися дерев'яними пандусами всередині вежі.",al={"де дорас","місце дораса","знайти дораса"}},{q="Що буде, коли віддати лист Гришки Дорасові?",a="Коли ви поговорите з Дорасом, він приготує вітрокрила, щоб той відніс вас назад до Пусток і ви власноруч передали лист Гришки Заргові на Перехресті.",al={"що далі","після дораса","наступне завдання"}},{q="Хто такий Зарг?",a="Зарг — орк-м'ясник із Перехрестя в Пустках і друг Гришки, якій він надіслав у дарунок добірне м'ясо з Пусток.",al={"зарг","хто такий зарг"}},{q="Навіщо вітрокрили, а не пішки?",a="Подорож суходолом з Оргріммара через Дуротар і за Річку Південної Люті до Пусток — довга й повна небезпек. Приручені вітрокрили дають Орді швидкий і надійний спосіб пересилати розвідників, накази й гінців між поселеннями.",al={"чому летіти","навіщо вітрокрили","переказ про маршрути польоту"}}},fp="27,265,17.382.0,23.322.0,13.191.0,45.170.0,25.140.0,52.159.0,13.139.0,39.255.0"}
P.entries["quest:6386"] = {n="Повернення на Перехрестя",s="Це доручення завершує доставку між Дуротаром і Пустками: ви несете відповідь Гришки назад Заргові на Перехрестя. Воно показує, як вітрокрили стають життєво важливим повітряним хребтом, що пов'язує поселення Орди по всьому Калімдору.",h="Це доручення завершує доставку між Дуротаром і Пустками: ви несете відповідь Гришки назад Заргові на...",kw={"перехрестя","вітрокрил","зарг","гришка","дорас","деврак","пустки"},ang={["faction:Horde"]="Гніздовища вітрокрилів в Оргріммарі та на Перехресті утворюють господарський і транспортний хребет, що з'єднує столицю Орди з небезпечними рівнинами Калімдору.",["race:Orc"]="Ситні шматки свіжої дичини й досі лишаються одним із найкращих знаків прихильності й поваги, які орк-мисливець може піднести обраниці."},sec={{t="Крилате повернення",b="Доставивши добірне м'ясо Гришці в Оргріммар, ви отримуєте її письмову відповідь для Зарга. Дорас, господар вітрокрилів, що оселився на високих кручах Оргріммара, дає вам крилатого звіра до Пусток. Оскільки ви вже познайомилися з Девраком на Перехресті, виверни Дораса знають маршрут, і виснажливий перехід суходолом через Річку Південної Люті обертається стрімким польотом пустельним небом."},{t="Шлюби укладаються в Пустках",b="Сміливе кулінарне залицяння Зарга вдається. Тепла відповідь Гришки підтверджує, що ніщо так не вражає орка, як добрі харчі, — і Зарг, святкуючи, навіть починає мріяти про близьке весілля. А крім романтичного тріумфу, ця подорож відкриває мандрівникові доступ до головного вузла сполучення в Пустках."}},faq={{q="Чому повертатися треба на вітрокрилі?",a="Дорас на цій доставці показує, як працює мережа польотів Орди. Оскільки ви вже бували в Деврака на Перехресті, виверни можуть летіти просто між двома сідалами — це заощаджує час і береже шляхи постачання.",al={"чому летіти назад","потрібен вітрокрил","чи можна пішки"}},{q="Хто така Гришка?",a="Гришка — корчмарка в Долині Сили в Оргріммарі. Зарг надіслав їй добірне м'ясо з Пусток, сподіваючись завоювати її прихильність.",al={"переказ про гришку","хто така гришка","жінка з м'ясом в оргріммарі"}},{q="Чого Зарг хотів, надсилаючи м'ясо до Оргріммара?",a="Зарг хотів позалицятися до Гришки. В орків подарувати ситну, добірну дичину з диких рівнин Пусток вважається величним романтичним жестом.",al={"чому зарг надіслав м'ясо","мотивація зарга","лист зарга"}},{q="Де закінчується це завдання?",a="Завдання завершується на Перехресті в Пустках: там ви віддаєте Лист Ґришки Заргові біля сторожової вежі й стаєнь.",al={"де здати","місце повернення","хто отримає лист гришки"}},{q="Хто такий Дорас?",a="Дорас — господар вітрокрилів на сідалі над Долиною Сили в Оргріммарі; він відає летючими скакунами, що подорожують Калімдором.",al={"дорас вітрокрил","місце дораса","майстер польотів оргріммара"}},{q="Що буде після цього завдання?",a="Ця доставка завершує кур'єрський ланцюжок «М'ясо до Оргріммара». З'єднавши Оргріммар і Перехрестя, ви цілком готові вирушати вглиб Пусток.",al={"продовження ланцюжка","наступне завдання після повернення","продовження м'яса до оргріммара"}}},fp="25,247,15.438.0,27.314.0,44.220.0,15.145.0,51.154.0,26.132.0,13.159.0,30.172.0"}
P.entries["quest:6387"] = {n="Відмінники",s="Наставник гірничої справи Брок Стоунсікер нагороджує здібних молодих учнів у Телсамарі почесними гірничими кайлами. Щоб організувати доставку інструментів з Айронфорджа, він посилає шукачів пригод по допомогу до місцевого майстра грифонів Торґрума Боррелсона.",h="Наставник гірничої справи Брок Стоунсікер нагороджує здібних молодих учнів у Телсамарі почесними гірничими...",kw={"відмінники","брок стоунсікер","торґрум боррелсон","телсамар","почесні кайла","гірнича справа","грифони"},ang={["faction:Alliance"]="Це прохання знайомить мандрівників у Лох Модані з важливою мережею майстрів польотів і повітряних гінців Альянсу.",["profession:Mining"]="Доручення підкреслює повагу дворфів до гірничої справи як до суворого ремесла, де знання каменю й жил заслуговує на відчутне визнання від майстрів-наставників.",["race:Dwarf"]="Для дворфійських шукачів пригод це доручення показує міцний зв'язок між порубіжними поселеннями на кшталт Телсамара й глибокими гірськими залами столиці."},sec={{t="Шана рудокопа",b="У дворфійському містечку Телсамар гірнича справа — більше, ніж ремесло: це наріжний камінь щоденного виживання й дворфійської гордості. Брок Стоунсікер бачить, як крізь його навчання проходять десятки новачків, і муштрує їх у знанні гірських порід і безпеці в тунелях. Тих учнів, що вирізняються з-поміж інших, звичай велить відзначити вишуканим почесним кайлом. Місцеві запаси обмежені, тож по ці кайла доводиться звертатися через увесь Каз Модан, до самого серця Айронфорджа."},{t="У небо",b="Брок не довіряє повільному пішому шляху горами назад через Дун Мороґ, а покладається на повітряну поштову мережу королівства. Торґрум Боррелсон доглядає грифонове сідало біля Телсамара й пропонує швидкий переліт до столиці. Передавши замовлення Брока Торґрумові, ви запускаєте поштовий рейс, що з'єднує навчання на сільському порубіжжі з величними ливарнями дворфійської столиці."}},faq={{q="Хто такий Брок Стоунсікер?",a="Брок Стоунсікер — наставник гірничої справи, що живе в Телсамарі. Він навчає новачків основ копання й роботи з каменем.",al={"брок стоунсікер","хто такий брок","наставник гірників телсамар"}},{q="Навіщо Брокові кайла з Айронфорджа?",a="Брок складає список найкращих учнів-гірників, які заслужили почесні кайла. Щоб видати ці нагороди, замовлення треба доставити Ґолніру Болдерто, торговцеві гірничим приладдям в Айронфорджі.",al={"чому айронфордж","чому кайла","список брока"}},{q="Яку роль у цьому дорученні відіграє Торґрум Боррелсон?",a="Торґрум Боррелсон — розпорядник грифонів Телсамара. Брок велить кур'єрам нести список замовлення йому, щоб той швидко влаштував переліт до Айронфорджа.",al={"торґрум боррелсон","хто такий торґрум","майстер грифонів телсамар"}},{q="Хто отримує список в Айронфорджі?",a="Зрештою список призначений Ґолніру Болдерто в Айронфорджі, який готує урочисті кайла для видатних учнів Брока.",al={"хто отримує список","ґолнір болдерто","контакт айронфорджа"}},{q="Куди веде це доручення далі?",a="Коли ви поговорите з Торґрумом Боррелсоном, він влаштує переліт на грифоні просто до Айронфорджа, щоб ви власноруч передали замовлення Ґолніру Болдерто.",al={"наступний крок","що після відмінників","після списку брока"}},{q="Де відбувається це доручення?",a="Доручення починається й закінчується в поселенні Телсамар серед пологих пагорбів Лох Модану.",al={"місце завдання","де телсамар","де почати відмінників"}}},fp="14,251,13.512.0,19.394.0,25.138.0,41.212.0,52.168.0,35.136.0,33.146.0,32.112.0"}
P.entries["quest:6388"] = {n="Ґріт Турден",s="Це доручення знайомить шукачів пригод із мережею грифонів Айронфорджа: треба віднести в'язку церемоніальних знарядь міському грифонярові. Отримавши від Ґолніра Болдерто Почесні Кайла, гонець мусить доставити їх Ґрітові Турдену, щоб той відправив їх назад до Лох Модану.",h="Це доручення знайомить шукачів пригод із мережею грифонів Айронфорджа: треба віднести в'язку церемоніальних...",kw={"ґріт турден","грифони","почесні кайла","ґолнір болдерто","телсамар","лох модан"},ang={["faction:Alliance"]="Грифонячі сідала Айронфорджа — незамінний транспортний вузол для посланців Альянсу між Дун Мороґом, Лох Моданом і ширшими королівствами.",["profession:Mining"]="Це доручення допомагає учням-шахтарям Брока Стоунсікера в Лох Модані: їхнє ремесло вшановують почесними кайлами, викуваними в столиці.",["race:Dwarf"]="Для дворфів грифони — і предмет родової гордості, і практична потреба: вони пов'язують гірські зали понад підступними вершинами."},sec={{t="Гонець для шахтарів",b="Подолавши шлях із Лох Модану до Великої Кузні, гінці отримують від Ґолніра Болдерто в'язку Почесних Кайл для учнів-шахтарів Брока Стоунсікера. Щоб не тягтися пішки назад гірськими перевалами, Ґолнір радить скористатися дворфійською мережею грифонів і посилає посланця через усе місто до головного айронфорджського грифоняра."},{t="На крилах до Телсамара",b="Ґріт Турден керує грифонячими сідалами у великій гірській залі, що пов'язують Айронфордж із дворфійськими поселеннями по всьому Каз Модану. Турден погоджується влаштувати переліт назад до Торґрума Боррелсона в Телсамарі, якщо шукач пригод уже розвідав шлях і поговорив там із місцевим грифонярем. Це доручення показує новоспеченим героям, яку важливу роль відіграють повітряні гінці, що з'єднують дворфійське королівство в одне ціле."}},faq={{q="Для чого Почесні Кайла?",a="Почесні Кайла — урочисті інструменти, які Ґолнір Болдерто виготовив в Айронфорджі для учнів Брока Стоунсікера, наставника гірничої справи з Телсамара.",al={"почесні кайла","чому почесні кайла","кайла для брока"}},{q="Хто такий Ґріт Турден?",a="Ґріт Турден — головний розпорядник грифонів в Айронфорджі. Він відає маршрутами, що з'єднують столицю дворфів із поселеннями по всьому Каз Модану й далі.",al={"хто такий ґріт турден","майстер грифонів айронфорджа","переказ про ґріта турдена"}},{q="Де в Айронфорджі знайти Ґріта Турдена?",a="Ґріт Турден стоїть біля грифонячого сідала Великої Кузні, неподалік головної центральної вулиці й брами Айронфорджа.",al={"де ґріт турден","де знайти ґріта турдена","майстер польотів айронфорджа"}},{q="Чому спершу треба поговорити з Торґрумом Боррелсоном?",a="Розпорядники грифонів відправляють вершників лише прокладеними маршрутами. Щоб Ґріт Турден міг відправити вершника до Телсамара, мандрівник має спершу встановити зв'язок із Торґрумом Боррелсоном, розпорядником у Лох Модані.",al={"вимога торґрума боррелсона","чому потрібен маршрут телсамара","не можу летіти до телсамара"}},{q="Що буде, коли віддати кайла Ґрітові Турдену?",a="Оглянувши пакунок, Ґріт готує грифона, щоб ви повернулися до Телсамара й передали інструменти просто Брокові Стоунсікеру.",al={"що далі після ґріта турдена","наступне завдання після ґріта турдена"}},{q="Хто посилає вас до Ґріта Турдена?",a="Ґолнір Болдерто, ремісник, що працює біля Великої Кузні в Айронфорджі, дає вам кайла й скеровує до Ґріта.",al={"хто починає ґріта турдена","хто дає це завдання"}}},fp="13,303,24.384.0,24.418.0,32.164.0,21.185.0,44.120.0,50.216.0,53.149.0,31.126.0"}
P.entries["quest:6391"] = {n="Переліт до Айронфорджа",s="Переліт до Айронфорджа — вступне завдання гінця, що відправляє новоспечених шукачів пригод у перший політ на грифоні з Телсамара в Лох Модані до дворфійської столиці. Отримавши від Брока Стоунсікера список найкращих учнів-шахтарів, мандрівник несе депешу просто Ґолнірові Болдерто біля Великої Кузні.",h="Переліт до Айронфорджа — вступне завдання гінця, що відправляє новоспечених шукачів пригод у перший політ на...",kw={"переліт","грифон","брок стоунсікер","ґолнір болдерто","велика кузня","телсамар"},ang={["faction:Alliance"]="Мережа грифонячих перельотів — хребет логістики Альянсу в Каз Модані: вона легко з'єднує прикордонні гарнізони з величною столицею.",["profession:Mining"]="Це завдання показує традицію Гірничої гільдії Глибокої Гори — відзначати й увічнювати гравіюванням здібних шахтарів, що виходять із копалень Лох Модану.",["race:Dwarf"]="Для юних дворфів клану Бронзбірд політ на грифоні до Великої Кузні — гордий обряд посвяти, що пов'язує сільські застави із серцем королівства."},sec={{t="У небо",b="Для багатьох юних горян і мандрівників переліт із Телсамара до Айронфорджа — найперша подорож верхи на грифоні. Цей короткий маршрут, яким опікується Грифоняр Торґрум Боррелсон, проносить мандрівників над засніженими хребтами Дун Мороґа просто до печерної брами гірської фортеці."},{t="Відзнаки Гільдії Глибокої Гори",b="Саме доручення служить Гірничій гільдії Глибокої Гори. Брок Стоунсікер регулярно надсилає з Телсамара звістки про своїх найздібніших учнів-шахтарів. Біля Великої Кузні на них чекає Ґолнір Болдерто, який вирізьблює імена учнів на церемоніальних почесних кайлах — нагорода за сумлінну гірничу справу в каменоломнях і копальнях Лох Модану."}},faq={{q="Де починається й закінчується цей переліт?",a="Подорож починається в розпорядника польотів Торґрума Боррелсона в Телсамарі, у Лох Модані, і приносить вас просто на грифоняче сідало біля Великої Кузні в Айронфорджі.",al={"маршрут польоту","куди летіти","призначення польоту"}},{q="Що таке Список Брока?",a="Список Брока — перелік, складений наставником гірничої справи Броком Стоунсікером у Телсамарі. У ньому записано його найкращих учнів, щоб гільдія в Айронфорджі могла нагородити їх за старанність.",al={"переказ про список брока","хто такий брок","що за папір"}},{q="Хто такий Ґолнір Болдерто?",a="Ґолнір Болдерто — представник Гірничої Гільдії Глибокої Гори при Великій Кузні Айронфорджа. Він отримує списки від місцевих наставників і вирізьблює імена учнів на почесних кайлах.",al={"роль ґолніра","де ґолнір","хто такий ґолнір болдерто"}},{q="Що буде, коли доставити список?",a="Отримавши перелік, Ґолнір скеровує вас до Ґріта Турдена, головного розпорядника грифонів Айронфорджа, — так ви ближче знайомитеся з повітряною мережею королівства.",al={"наступне завдання","що робити після","продовження"}},{q="Навіщо грифон, а не пішки?",a="Хоча гірська дорога й тунелі ведуть просто до брами Айронфорджа, це завдання — практичний урок польотів на грифонах Альянсу: воно показує новим шукачам пригод, як швидко можна перелітати між поселеннями.",al={"чому летіти","чи можна пішки до айронфорджа","чому грифон"}},{q="Що таке почесне кайло?",a="Почесні кайла — урочисті інструменти, які виготовляє Гірнича Гільдія Глибокої Гори, щоб відзначити найкращих учнів гірничої справи, що під проводом місцевих наставників опанували основи копання й геології.",al={"почесні кайла","нагорода кайло","обряд кайла"}}},fp="17,325,19.309.0,33.326.0,37.169.0,21.177.0,25.207.0,40.175.0,37.214.0,25.193.0"}
P.entries["quest:6392"] = {n="Повернення до Брока",s="Доставивши послання Брока Стоунсікера в Айронфордж, ви отримуєте партію Почесних Кайл, які треба віднести назад до Телсамара. Скориставшись дворфійською повітряною мережею, ви сідаєте на грифона в Ґріта Турдена, щоб швидко повернутися через гори.",h="Доставивши послання Брока Стоунсікера в Айронфордж, ви отримуєте партію Почесних Кайл, які треба віднести...",kw={"брок стоунсікер","почесні кайла","ґріт турден","грифон","телсамар","шахтарі"},ang={["profession:Mining"]="Доставлені Почесні Кайла дають найновішим шахтарям Лох Модану необхідне знаряддя й підтримують дворфійську традицію розкопок і розвідки надр.",["race:Dwarf"]="Шлях між Айронфорджем і Телсамаром показує, як грифони Вайлдгаммерів і айронфорджські грифонярі допомагають згуртувати дворфійські твердині."},sec={{t="У небо",b="Велична гірська твердиня Айронфордж покладається на злагоджену мережу грифонячих сідал, щоб підтримувати зв'язок і торгівлю з віддаленими поселеннями на кшталт Лох Модану. Ґріт Турден, айронфорджський грифоняр, керує цими перельотами з головного майданчика міста. Оскільки мандрівник мусить спершу познайомитися з грифонярем гнізда, перш ніж летіти туди, Ґріт переконується, що ви вже поговорили з Торґрумом Боррелсоном у Телсамарі, і лише тоді сідлає грифона для зворотного шляху."},{t="Кайла для учнів",b="Ваша подорож має практичну мету, а не лише знайомить вас із польотами на грифонах: Брокові Стоунсікеру, шанованому наставникові шахтарів у Телсамарі, потрібне нове знаряддя для учнів. Коли Почесні Кайла опиняться в його руках, молоді шахтарі по всій долині зможуть узятися до багатих жил міді й олова, що тягнуться пагорбами довкола озера."}},faq={{q="Хто такий Брок Стоунсікер?",a="Брок Стоунсікер — дворф, наставник гірничої справи в Телсамарі, у Лох Модані. Він навчає молодих гірників добувати руду й камінь із навколишніх пагорбів.",al={"брок стоунсікер","хто такий брок","брок у телсамарі"}},{q="Чому для завершення цього завдання треба летіти на грифоні?",a="Завдання знайомить мандрівників із системою польотів Альянсу. Ґріт Турден пояснює, що грифони можуть віднести вас лише до тих гнізд, де ви вже особисто побували, — наприклад, до сідала Торґрума Боррелсона в Телсамарі.",al={"чому летіти на грифоні","завдання з польотом","політ грифоном"}},{q="Для чого Почесні Кайла?",a="Це щойно викувані гірничі інструменти, які Брок Стоунсікер замовив в Айронфорджі для своїх учнів-гірників, щоб ті працювали на багатих на руду скелях Лох Модану.",al={"почесні кайла","що таке кайла"}},{q="Хто такий Ґріт Турден?",a="Ґріт Турден — розпорядник грифонів Айронфорджа біля Великої Кузні. Він відає польотами зі столиці й до неї по всьому Каз Модану й далі.",al={"ґріт турден","майстер польотів айронфорджа"}},{q="Чи можна просто дійти до Телсамара пішки, а не летіти?",a="Хоча урок задуманий, щоб навчити вас користуватися маршрутами польотів, Брокові Стоунсікеру важливо лише, щоб ви безпечно доставили йому Почесні Кайла в Телсамар, — байдуже, як ви туди дістанетеся.",al={"чи можна пішки назад","чи треба брати грифона"}},{q="Де в Телсамарі знайти Брока?",a="Брок Стоунсікер стоїть просто неба біля кузні й ковадла в Телсамарі, готовий допомогти гірникам, що працюють у Лох Модані.",al={"де брок","місце брока стоунсікера","знайти брока"}}},fp="15,270,19.498.0,20.361.0,25.171.0,55.216.0,32.159.0,21.167.0,52.195.0,36.124.0"}
P.entries["quest:6395"] = {n="Останнє бажання Марли",s="Останнє бажання Марли — раннє завдання Відступників від Послушниці Елрет у Похоронному Подзвоні. Воно просить вас вистежити поневолені Погибеллю рештки Семюела Фіппса, щоб поховати його поруч із убитою ним дружиною Марлою. Завдання відображає прагнення молодого суспільства Відступників шанувати людські зв'язки й відрізнятися від безтямної Погибелі.",h="Останнє бажання Марли — раннє завдання Відступників від Послушниці Елрет у Похоронному Подзвоні.",kw={"останнє бажання марли","марла","семюел фіппс","елрет","поховання","похоронний подзвін"},ang={["class:Priest"]="Наполягання Послушниці Елрет на належному похоронному обряді прямо стосується духовного обов'язку жерців Відступників, які мають справу зі смертністю, горем і оскверненням мертвих Лордерону.",["race:Undead"]="Для новопіднятих Відступників виконати бажання Марли — емоційний якір у колишньому людському житті, доказ того, що співчуття і честь не загинули разом із Лордероном."},sec={{t="Трагічне возз'єднання",b="Перш ніж Третя війна спустошила Лордерон, Марла і Семюел Фіппси жили як чоловік і дружина. Коли їхніми землями прокотилася чума, Семюел піддався заразі й був піднятий безтямним рабом Погибелі. Марлу нежиття оминуло, та від самого Семюела вона втекти не змогла: у безтямному шалі він жорстоко вбив її. Попри загибель від рук чоловіка, в останні миті Марла не тримала зла. Її передсмертне бажання, яке запам'ятала Послушниця Елрет, — спочивати вічно поруч із чоловіком на цвинтарі Похоронного Подзвону."},{t="Повага до мертвих",b="Послушниця Елрет відряджає шукачів пригод із Відступників на північний схід від Похоронного Подзвону — знайти Семюела Фіппса, який досі блукає зруйнованим табором. Покласти край мукам Семюела означає подвійну користь: очистити долину від прислужника Погибелі, що насідає, і принести його тілесні рештки до місця спочинку Марли. Як наголошує Елрет, шана до покійних і повага до їхньої останньої волі — важлива моральна межа, що відділяє щойно звільнених Відступників від безтямної злоби Погибелі."}},faq={{q="Ким була Марла Фіппс?",a="Марла Фіппс жила в Лордероні й пережила першу хвилю чуми нежиття — лише для того, щоб загинути від рук свого чоловіка Семюела, коли той обернувся на безтямного гуля Погибелі. Її останнім бажанням було спочити поруч із ним.",al={"переказ про марлу фіппс","хто така марла","історія марли"}},{q="Хто такий Семюел Фіппс?",a="Семюел Фіппс до чуми був чоловіком Марли. Він піддався Погибелі, утратив розум, скорившись волі Короля-Ліча, і вбив свою дружину. Він блукає зруйнованим табором на північний схід від Похоронного Подзвону, доки його не впокоять шукачі пригод із Відступників.",al={"переказ про семюела фіппса","хто такий семюел фіппс","де семюел фіппс"}},{q="Чому Послушниці Елрет так важливо поховати їх разом?",a="Послушниця Елрет за життя приятелювала з Марлою. Та річ не лише в почуттях: Елрет вірить, що шанувати волю мертвих і гідно поводитися з останками — доказ того, що Відступники зберегли людяність і мораль, а отже, відрізняються від безтямної Погибелі.",al={"чому допомагати марлі","мотив послушниці елрет","чому ховати семюела"}},{q="Чи постала Марла Відступницею?",a="Ні. За словами Послушниці Елрет, нежиття Марлу оминуло. Вона померла звичайною смертю від рук чоловіка й похована на цвинтарі Похоронного Подзвону.",al={"чи марла нежить","чи марла стала відступницею","марла фіппс нежить"}},{q="Де могила Марли?",a="Могила Марли — у першому ряду цвинтаря просто біля головної каплиці Похоронного Подзвону.",al={"місце могили марли","де похована марла","де ховати семюела"}},{q="Де знайти Семюела Фіппса?",a="Семюел Фіппс блукає довкола зруйнованого табору при дорозі, що веде на північний схід від Похоронного Подзвону.",al={"місце семюела фіппса","знайти семюела фіппса","де семюел"}}},fp="17,339,16.550.0,19.517.0,20.225.0,20.235.0,56.265.0,27.162.0,31.96.0,32.97.0"}
P.entries["quest:64"] = {n="Забута реліквія",s="Фермер Фурлброу та його дружина Верна втекли з дому, коли розбійники в масках заполонили їхнє гарбузове поле у Вестфолі. У шаленому поспіху Фурлброу залишив у шафі свого фермерського будинку дорогу серцю родинну реліквію. Повернути кишеньковий годинник — рідкісна нагода врятувати щось особисте з хаосу, що дедалі більше охоплює край.",h="Фермер Фурлброу та його дружина Верна втекли з дому, коли розбійники в масках заполонили їхнє гарбузове поле...",kw={"забута реліквія","фермер фурлброу","кишеньковий годинник","бенні блаанко","верна фурлброу","вестфол"},ang={["faction:Alliance"]="Лихо родини Фурлброу показує, як глибоко занепав громадський лад у житниці королівства, тож мандрівникам Альянсу доводиться братися за справи, які занедбала корона.",["race:Human"]="Для людей Стормвінда бачити чесних фермерів, вигнаних жорстокими розбійниками за день ходу від столиці, — тверезе нагадування про внутрішні негаразди королівства."},sec={{t="Опівнічне вигнання",b="Як і багатьох господарів Вестфолу, Фермера Фурлброу та його дружину Верну вигнали з їхньої землі грубою силою. Розбуджене раптовими криками й насильством серед гарбузових грядок, подружжя мало лише кілька хвилин, щоб зібрати ті небагаті пожитки, які могло забрати, й утекти з ферми. У паніці Фурлброу мусив покинути кишеньковий годинник — подарунок батька Верни в день їхнього весілля, — і той лишився в шафі захопленого фермерського будинку."},{t="Хулігани в полях",b="Гарбузова ферма Фурлброу тепер кишить головорізами Дефіасу, мародерами й злодюжками-пройдисвітами на кшталт Бенні Блаанко, які нишпорять у рештках покинутих домівок. Для звичайних людей повернутися по особисті скарби — вірна смерть. Забравши годинник із шафи серед розгромлених кімнат, шукачі пригод повертають бодай дрібку гідності родині, яка втратила майже все інше через дедалі більше беззаконня."}},faq={{q="Чому кишеньковий годинник такий важливий для Фермера Фурлброу?",a="Кишеньковий годинник — весільний подарунок від батька Верни. Тепер, коли вони стали злиденними біженцями без засобів до життя, годинник — один із небагатьох дорогих серцю зв'язків із колишнім життям і родинною спадщиною.",al={"чому годинник важливий","значення годинника фурлброу","хто дав годинник фурлброу"}},{q="Хто прогнав Фурлброу з їхньої ферми?",a="Уночі ферму захопили розбійники й грабіжники Дефіас. Беззаконня, що охопило Вестфол, змусило багато фермерських родин під загрозою насильства покинути поля й домівки.",al={"хто напав на ферму","хто забрав ферму фурлброу","що сталося з фурлброу"}},{q="Де схований годинник?",a="Годинник лежить у шафі в спальні на садибі Фурлброу — біля гарбузових грядок на захід від придорожнього табору Фурлброу на півночі Вестфолу. Зараз будинок зайняли волоцюги й розбійники Дефіас.",al={"де кишеньковий годинник","знайти годинник","місце шафи"}},{q="Хто такий Бенні Блаанко?",a="Бенні Блаанко — розбійник, що разом зі спільниками з Дефіас тиняється фермерським будинком Фурлброу, грабує покинуте житло й стереже захоплену землю від тих, хто хотів би її повернути.",al={"переказ про бенні блаанко","хто чоловік у будинку"}},{q="Де тепер живуть Фурлброу?",a="Утікши зі своєї землі, Фермер Фурлброу й Верна застрягли край дороги у Вестфолі: вони ховаються біля свого воза й намагаються вижити серед загального занепаду краю.",al={"де фурлброу","де фермер фурлброу"}},{q="Чи надсилає Стормвінд вартових, щоб допомогти повернути такі ферми?",a="Військової присутності Стормвінда у Вестфолі майже немає через політичну байдужість і відсутність проводу в столиці. Народному ополченню на Сентінел Гіллі бракує людей, щоб відвойовувати окремі садиби, тож поселенці цілком беззахисні.",al={"допомога стормвінда вестфолу","чому немає вартових на фермі"}}},fp="22,354,19.491.0,23.440.0,56.214.0,45.197.0,26.226.0,21.190.0,36.174.0,59.275.0"}
P.entries["quest:6401"] = {n="Кая жива",s="«Кая жива» — коротке завдання Орди в Горах Кам'яного Кігтя, що завершує порятунок Каї Флетгуф. Безпечно провівши юну тауренку повз ворожих розбійників-Ґрімтотемів, ви несете радісну звістку про те, що вона жива, її стривоженій тітці Таммрі Віндфілд у Притулок Сонячної Скелі.",h="«Кая жива» — коротке завдання Орди в Горах Кам'яного Кігтя, що завершує порятунок Каї Флетгуф.",kw={"кая жива","кая флетгуф","таммра віндфілд","ґрімтотем","притулок сонячної скелі","макаба флетгуф"},ang={["faction:Horde"]="Гори Кам'яного Кігтя — спірна глушина, де сили Орди розтягнуто до межі; вісті про вцілілих допомагають зберігати єдність між розкиданими таборами.",["race:Tauren"]="Загроза Ґрімтотемів — болючий внутрішній розкол для шу'гало, тож порятунок невинних родичів, як-от Каї, для тауренів — справа глибоко особиста."},sec={{t="Полегшений подих",b="Гори Кам'яного Кігтя повні небезпек, особливо на спірних стежках, де безжально б'є плем'я Ґрімтотем. Коли на їхнє село напали, всі боялися, що юна Кая Флетгуф загинула або потрапила в полон до ренегатів. Те, що вона вижила й урятувалася, — рідкісна мить тріумфу й полегшення серед нескінченних племінних чвар у горах."},{t="До Притулку Сонячної Скелі",b="Щойно Кая в безпеці, Макаба Флетгуф доручає вам віднести звістку просто до Притулку Сонячної Скелі. Там на вісті зі стежок нетерпляче чекає Каїна тітка, Таммра Віндфілд. Звістка про те, що Кая жива й здорова, втішає розбиту родину й ще раз показує, як важливо, що мандрівні герої тримають зв'язок між віддаленими заставами Орди."}},faq={{q="Хто така Кая Флетгуф?",a="Кая Флетгуф — молода тауренка, яка загубилася й опинилася в небезпеці після жорстокого нападу загонів Ґрімтотем, що відкололися, на її поселення в Горах Кам'яного Кігтя.",al={"хто така кая","кая флетгуф","кая"}},{q="Хто така Таммра Віндфілд?",a="Таммра Віндфілд — тітка Каї, що живе в Притулку Сонячної Скелі в Горах Кам'яного Кігтя. Вона боялася, що небога загинула під час нападу Ґрімтотем.",al={"таммра віндфілд","хто така таммра","тітка каї"}},{q="Хто напав на село Каї?",a="На село Каї напав агресивний клан Ґрімтотем — відокремлене угруповання тауренів, відоме тим, що полює і на суперницькі племена, і на мандрівників у горах.",al={"хто напав на каю","напад на село","напад ґрімтотемів"}},{q="Що передує цьому завданню?",a="Це завдання йде одразу після завдання «Захисти Каю» — супроводу, під час якого ви боронете Каю Флетгуф, поки вона тікає від полонителів до безпечного місця.",al={"попереднє завдання","захистити каю","завдання з супроводом"}},{q="Де розташований Притулок Сонячної Скелі?",a="Притулок Сонячної Скелі сховався високо в центральних Горах Кам'яного Кігтя: туди веде головна дорога на захід, а далі вузька гірська ущелина до захищеної улоговини.",al={"місце притулку сонячної скелі","де сонячна скеля","знайти притулок сонячної скелі"}},{q="Чому Макаба Флетгуф посилає мене, а не йде сам?",a="Макаба лишається у своєму таборі біля південно-східного краю Кам'яного Кігтя й покладається на прудкого гінця, щоб той швидко заспокоїв їхню родину в Притулку Сонячної Скелі.",al={"чому макаба залишається","чому посилає мене"}}},fp="12,293,18.381.0,25.362.0,21.161.0,24.149.0,28.181.0,29.143.0,34.175.0,59.155.0"}
P.entries["quest:6421"] = {n="Яр Кам'яного Зсуву",s="Глибоко в Яру Кам'яного Зсуву, що в Горах Кам'яного Кігтя, місцеві кобольди гарячково взялися видобувати рідкісний підземний мінерал — резоніт. Відчуваючи, як наростає напруга в землі, таурен Мор'роґал посилає шукачів пригод з Орди дослідити печери яру й принести зразки мінералу, щоб з'ясувати, що поховано під скелею.",h="Глибоко в Яру Кам'яного Зсуву, що в Горах Кам'яного Кігтя, місцеві кобольди гарячково взялися видобувати...",kw={"яр кам'яного зсуву","резоніт","мор'роґал","кобольди","земляни","титани"},ang={["class:Shaman"]="Шамани, що вслухаються в землю, відчувають неприродний резонанс, який тремтить у скелі, поки кобольди розпечатують реліквії первісного стихійного ремесла титанів.",["profession:Mining"]="Резоніт, що його видобувають кобольди з Яру Кам'яного Зсуву, — не звичайна руда: його основу просякли давні чародійські рештки, лишені підземними будівничими сивої давнини.",["race:Tauren"]="Для тауренів, які шанують Земну Матір, розкопані під горами прадавні споруди титанів — ознака небезпечного порушення природної рівноваги Гір Кам'яного Кігтя."},sec={{t="Напруга в камені",b="Зі свого посту в Притулку Сонячної Скелі таурен Мор'роґал із глибокою тривогою стежить за вершинами Гір Кам'яного Кігтя. Сама земля здається стривоженою: з південного сходу йде неприродне хвилювання. Там, серед круч Яру Кам'яного Зсуву, місцеві кобольди покинули звичайне збиральництво й завзято розкопують рідкісний підземний мінерал — резоніт. Щоб з'ясувати, чому ці забобонні шкідники копають у такому відчайдушному шалі, Мор'роґал кличе розвідників Орди прорватися крізь їхню оборону, спуститися на саме дно печери й принести необроблені зразки мінералу."},{t="Пробудження прадавніх",b="Коли сирий резоніт роздивляються ближче, його справжня природа стає очевидною: кристали гудуть давньою магією землян. Наосліп вгризаючись у глибинний камінь, кобольди пробили прадавній шар світу й відкопали землянина — одну з первісних кам'яних істот, яких титани створили, щоб вимуровувати підземні основи Калімдору. Те, що кобольди мають за звичайну каменоломню, потривожило реліквію первісної історії, і тепер тауренам доводиться втрутитися, перш ніж поховане вирветься на волю."}},faq={{q="Де розташований Яр Кам'яного Зсуву?",a="Яр Кам'яного Зсуву врізається в гори на південний схід від Притулку Сонячної Скелі в Горах Кам'яного Кігтя. Він веде до звивистих печер, які заполонили кобольди Кам'яного Зсуву.",al={"де яр кам'яного зсуву","місце яру кам'яного зсуву","як знайти яр кам'яного зсуву"}},{q="Хто дає завдання «Яр Кам'яного Зсуву»?",a="Завдання дає Мор'роґал, таурен із Притулку Сонячної Скелі — головної застави Орди в Горах Кам'яного Кігтя.",al={"хто починає яр кам'яного зсуву","видавець яру кам'яного зсуву","завдання мор'роґала"}},{q="Що таке Кристали Резоніту?",a="Резоніт — рідкісний мінерал, який трапляється глибоко в печерах Кам'яного Зсуву. На ньому лишилися сліди магії землян, викуваних Титанами, тобто кристали утворилися поблизу підземних реліквій землян.",al={"що таке резоніт","переказ про резоніт","кристали резоніту"}},{q="Чому кобольди так шалено добувають резоніт?",a="Кобольди натрапили на резоніт, коли копали, і в ненаситній гонитві за блискучою рудою вгризлися так глибоко під гори, що потривожили прадавнього землянина, похованого в скелі.",al={"чому кобольди добувають","мета кобольдів яру","змова кобольдів кам'яного кігтя"}},{q="Хто такі земляни за переказами тауренів?",a="За давніми переказами, які пригадує Мор'роґал, земляни — вирубані з каменю істоти, яких давним-давно викували Титани, щоб різьбити й формувати саму кам'яну основу світу.",al={"що таке земляни","земляни і титани","хто такі земляни"}},{q="Що буде після виконання цього завдання?",a="Розпізнавши в Кристалах Резоніту магію землян, Мор'роґал готує зачарований засіб протидії й дає наступне завдання — «Земляни повстають», відправляючи вас назад у печеру протистояти пробудженій загрозі.",al={"наступне завдання після яру кам'яного зсуву","що після яру кам'яного зсуву","продовження яру кам'яного зсуву"}}},fp="19,347,20.608.0,22.489.1,37.181.0,40.125.0,27.225.1,51.193.1,44.165.0,41.225.1"}
P.entries["quest:6441"] = {n="Роги Сатира",s="«Роги сатира» — найманський контракт від мандрівної гоблінки Піксель на Заставі Розщепленого Дерева в Ашенвалі. Угледівши прибуткову торгову нагоду в портовому містечку Раджет, Піксель наймає вправних шукачів пригод Орди, щоб проредити місцеві осередки сатирів і зібрати їхні цінні роги.",h="«Роги сатира» — найманський контракт від мандрівної гоблінки Піксель на Заставі Розщепленого Дерева в...",kw={"роги сатира","піксель","сатири","раджет","сатирнаар","нічний потік","завдання"},ang={["class:Hunter"]="Вистежувати демонічних людиноподібних серед осквернених лісових руїн, як-от Сатирнаар і Нічний Потік, — небезпечне випробування мисливського вміння.",["class:Warlock"]="Сатири сповнені могутньої магії скверни, тож їхні тілесні рештки — цінні дивовижі для тих, хто вивчає демонічну силу.",["faction:Horde"]="Зачищення сатирів у центральному Ашенвалі послаблює небезпечні демонічні осередки, що загрожують хитким шляхам постачання Застави Розщепленого Дерева."},sec={{t="Прибуткова нагода",b="Відпочиваючи на передовому таборі Орди — Заставі Розщепленого Дерева, — заповзятлива гоблінка-мандрівниця на ім'я Піксель помітила вільну нішу на прикордонному ринку. Роги демонічних сатирів Ашенвалю мають великий попит у Раджеті, по той бік Пусток. Не бажаючи ризикувати власною шкурою в сутичках із зіпсованими істотами, Піксель наймає перехожих шукачів пригод, щоб ті зібрали шістнадцять цілих рогів до її повернення на південь."},{t="Лігва зіпсованих",b="Сатири Ашенвалю живуть у розкиданих по прадавньому лісі руїнах, просякнутих скверною, — пам'ятках їхньої зради за часів давнього Розколу. Щоб виконати замовлення Піксель, мисливців посилають до відомих оплотів сатирів — Нічного Потоку, укріпленого табору Сатирнаар і затінених гаїв Ксавіана. Будь-який із цих осередків дасть цінні демонічні трофеї, на які чекають на торгових пристанях Раджета."}},faq={{q="Хто така Піксель?",a="Піксель — заповзятлива гоблінка-мандрівниця, що тимчасово зупинилася на Заставі Розщепленого Дерева в Ашенвалі, перш ніж повернутися на південь, до нейтрального порту Раджет.",al={"хто дає завдання","переказ про піксель","гоблін біля розщепленого дерева"}},{q="Навіщо Раджету роги сатирів?",a="Піксель зауважує, що роги сатирів дорого цінуються в Раджеті: купці, алхіміки й збирачі дивовиж щедро платять за сирі демонічні реагенти й рідкісні матеріали з північних лісів.",al={"чому роги сатирів","для чого роги","роги сатирів раджет"}},{q="Де в Ашенвалі знайти роги сатирів?",a="Сатири населяють кілька осквернених місць в Ашенвалі. Серед відомих осередків — Нічний Потік на північний захід від Застави Розщепленого Дерева, Сатирнаар неподалік головної дороги до Азшари і Ксавіан на північному сході Ашенвалю.",al={"місця сатирів","де знайти сатирів","нічний біг ксавіан сатірнаар"}},{q="Хто такі сатири?",a="Сатири — прадавні нічні ельфи, які тисячі років тому піддалися демонічній скверні Палаючого Легіону. Перетворені на рогатих звірів із роздвоєними копитами, вони служать темним силам і невпинно оскверняють ліс довкола.",al={"що таке сатир","переказ про сатирів","чи сатири демони"}},{q="Чому цю угоду укладають на Заставі Розщепленого Дерева?",a="Застава Розщепленого Дерева — головна твердиня Орди в центральному Ашенвалі. Піксель використовує її як безпечний перепочинок між торговими шляхами й наймає воїнів Орди, які й так воюють із небезпеками лісу.",al={"сатири розщепленого дерева","чому лише орда"}},{q="Чи віддана Піксель Орді?",a="Ні. Піксель — незалежна гоблінська торговка, що шукає зиску. Як і багато гоблінів довкола Раджета, Піксель працює з будь-ким, хто може дати цінний товар, і не зважає на політику фракцій.",al={"чи піксель орда","фракція піксель"}}},fp="11,283,23.425.0,23.430.0,13.161.0,34.200.0,44.204.0,16.231.0,50.226.0,44.206.0"}
P.entries["quest:6442"] = {n="Наги на узбережжі Зорам",s="«Наги на узбережжі Зорам» — завдання Орди, у якому шукачам пригод доручено винищувати агресивних зміїних загарбників на північно-західному узбережжі Ашенвалю. Тролиця Марукай із Застави Зорам'гар прагне втримати спірний берег, відкинувши наг Гнівохвостих від затонулих руїн прадавнього Зорама.",h="«Наги на узбережжі Зорам» — завдання Орди, у якому шукачам пригод доручено винищувати агресивних зміїних...",kw={"наги на узбережжі зорам","марукай","застава зорам'гар","гнівохвості","наги","завдання"},ang={["faction:Horde"]="Утримання Застави Зорам'гар украй важливе для поширення Орди в Ашенвалі, тож очищення берега від наг — справа військового виживання.",["race:Orc"]="Пряма стратегія Марукай — жорстока відсіч — цілком пасує практичній бойовій культурі орків, що тримають прикордонні рубежі."},sec={{t="Хитка опора",b="Присутність Орди на Зорамському Узмор'ї хитка. Оточена ворожими землями нічних ельфів і запеклими лісовими сутичками Ашенвалю, застава забезпечує важливий вихід до моря. Та несподівана поява агресивних наг, що виповзають на берег, загрожує відрізати Орду від моря й захопити невеликий гарнізон, перш ніж його позицію встигнуть як слід укріпити."},{t="Відлуння приреченого Зорама",b="Піщані мілини узмор'я приховують розтрощені рештки Зорама — прадавнього ельфійського міста, яке тисячі років тому поглинув Великий Розкол. Марукай і захисники застави мало знають про те, чому зміїне плем'я Гнівохвостих саме тепер виповзло з глибоких западин, але їхній раптовий інтерес до затонулих руїн не віщує нічого доброго тим, хто ходить по суходолу."},{t="Ціна виживання",b="Марукай дивиться на все крізь призму простого виживання: коли оголено мечі й тризуби, причини не мають значення. Вимагаючи двадцять відтятих голів загарбників-Гнівохвостих, вона прагне самою лише силою відкинути зміїних чудовиськ назад у глибини й утримати берег для Орди."}},faq={{q="Хто дає завдання «Наги на узбережжі Зорам»?",a="Завдання дає Марукай, тролиця Темного Спису із застави Орди Зорам'гар на узбережжі Зорам у північно-західному Ашенвалі.",al={"хто дає наг на узбережжі зорам","видавець завдання","де марукай"}},{q="Яка історія узбережжя Зорам?",a="Тут спочиває прадавнє приречене місто Зорам. Його зруйнувало й поглинуло Велике Море ще за часів Розколу, і тепер його руїни лежать почасти під водою вздовж узбережжя Ашенвалю.",al={"що таке зорам","історія зорам","затоплене місто"}},{q="Чому наги нападають на берег?",a="Гарнізон Орди не знає, чому саме прибуло плем'я Гнівохвостих, — лише те, що ці істоти вийшли з океанських глибин, щоб захопити затонулі руїни й прогнати всіх суходільних мешканців.",al={"чому наги тут","мотив рат-хвостих","мета наг"}},{q="З якими ворогами треба битися в цьому завданні?",a="Треба вбивати наг із племені Гнівохвостих, що повзають пляжами й прибоєм узбережжя Зорам, і зібрати для Марукай двадцять їхніх відтятих голів.",al={"які наги","голови рат-хвостих","цільові вороги"}},{q="Яке завдання йде після «Наг на узбережжі Зорам»?",a="Більше завдань Марукай не дає: вона просто дякує вам і просить, щоб більше таких, як ви, допомогли втримати узбережжя.",al={"наступне завдання","продовження","марукай далі"}},{q="Чому Орді не байдужий цей віддалений пляж?",a="За Ашенваль запекло борються Орда й нічні ельфи. Надійний морський плацдарм на узбережжі Зорам дає Орді стратегічний доступ і шляхи постачання в обхід густих лісів углибині суходолу.",al={"чому орда тут","мета застави зорам'ґар"}}},fp="24,312,21.388.0,22.371.0,21.317.0,45.144.0,44.218.0,37.204.0,48.166.0,44.124.0,48.217.0"}
P.entries["quest:6461"] = {n="Кровопивці",s="«Кровопивці» — мисливське доручення Орди від Ксен'Зілли в Малака'джині, поселенні племені Темного Спису. Місцеві тролі знайшли на схилах Гір Кам'яного Кігтя вдосталь дичини, але запах розібраного м'яса зманив до їхніх таборів зграї хижих глибокомохових павуків.",h="«Кровопивці» — мисливське доручення Орди від Ксен'Зілли в Малака'джині, поселенні племені Темного Спису.",kw={"кровопивці","ксен'зілла","малака'джин","глибокомохові павуки","тролі","темний спис"},ang={["class:Hunter"]="Вистежувати небезпечних хижаків, які полюють краще за мешканців дружніх поселень і не дають їм спокою, — природна справа для вправних слідопитів, що мандрують кручами.",["faction:Horde"]="Малака'джин тримає шлях Орди з північних Пусток у Гори Кам'яного Кігтя; захистивши село, ви вбережете весь південний перевал.",["race:Troll"]="Мисливці Малака'джина — ваші родичі, які прагнуть вибороти собі самодостатній край у суворому нагір'ї Калімдору й не скоритися дикій природі."},sec={{t="Непрохані гості на вечері",b="Тролі, що заснували прикордонну заставу Малака'джин на південному сході Гір Кам'яного Кігтя, прийшли сюди по добре полювання. Скелясті схили справді виявилися щедрими, але м'ясо й дичина, яку вони приносили, незабаром привабили нічних хижаків. Глибокомохові павуки — агресивні членистоногі, що живуть у кручах і каньйонах на півночі, — почали під покровом темряви прокрадатися в табір, щоб поживитися запасами або самих мисливців обернути на здобич."},{t="Зачистка круч",b="Щоб убезпечити табір і вберегти припаси, Ксен'Зілла просить шукачів пригод вистежити хижаків на півночі, у гірських перевалах. Найгустіше глибокомохові повзуни й отрутоплюви кишать довкола скелястих ярів і павутиння Розколини. Прорідивши їх, ви відкинете виводок від меж Малака'джина, і село зможе спати спокійно, не боячись нападу з тіней."}},faq={{q="Хто дає завдання «Кровопивці»?",a="Ксен'Зілла, троль Темного Спису із селища Малака'джин на південному сході Гір Кам'яного Кігтя, дає це завдання мандрівним поборникам Орди.",al={"хто дає кровопивці","видавець кровопивців","завдання ксен'зілли"}},{q="Чому павуки нападають на Малака'джин?",a="Тролі Малака'джина багато полюють на місцеву дичину. Запах свіжої здобичі й в'ялення м'яса вночі приманює павуків Глибокого Моху з гірських перевалів: вони крадуть припаси й полюють на мешканців селища.",al={"чому павуки нападають","напади павуків на малака'джин","чому павуки вторгаються"}},{q="Де водяться павуки Глибокого Моху?",a="Повзуни й отрутоплюї Глибокого Моху никають центральними перевалами й скелями на північ від Малака'джина, а найгустіше вони кишать в обплутаному павутинням яру, відомому як Ущелина.",al={"де павуки глибокого моху","місця павуків глибокого моху","де глибокомохі слизькі"}},{q="Що таке Малака'джин?",a="Малака'джин — табір тролів Темного Спису в Горах Кам'яного Кігтя, біля їхнього південного входу, неподалік кордону з Пустками; це прикордонна мисливська база й застава Орди.",al={"що таке малака'джин","переказ про малака'джин","тролячий поселенець кам'яного кігтя"}},{q="Чи пов'язана з цими павуками більша загроза?",a="Глибоко в Ущелині серед павутиння живе величезна смертоносна павуча матріарх. Попереджувальний знак біля каньйону остерігає мандрівників і закликає збиратися гуртом, щоб її знищити.",al={"великий павук кам'яного кігтя","еліта ущелини павук","матріарх кам'яного кігтя"}},{q="Що буде, коли проріджувати павуків?",a="Коли повзунів і отрутоплюїв стане менше, Малака'джин зможе перевести подих: тролі-мисливці вбережуть запаси м'яса й ходитимуть табором уночі без постійних засідок.",al={"наслідки кровопивців","чи малака'джин безпечний"}}},fp="13,286,22.448.0,18.397.0,35.154.0,41.208.0,39.188.0,19.192.0,48.187.0,42.181.0"}
P.entries["quest:6462"] = {n="Тролячий Оберіг",s="«Тролячий оберіг» — завдання Орди, яке дає троль Темного Спису Міцува на Заставі Зорам'гар в Ашенвалі. Після того як загін тролів-мандрівників потрапив у засідку й загинув від рук фурболгів Будякохутрих, Міцува просить шукачів пригод проникнути в їхнє лігво й повернути священні талісмани, викрадені в загиблих.",h="«Тролячий оберіг» — завдання Орди, яке дає троль Темного Спису Міцува на Заставі Зорам'гар в Ашенвалі.",kw={"тролячий оберіг","міцува","темний спис","будякохутрі","лоа","завдання"},ang={["faction:Horde"]="Вторгнення на землі Будякохутрих — це удар у відповідь лісовим загрозам, що влаштовують засідки на шляхи постачання й мандрівників Орди в Ашенвалі.",["race:Troll"]="Повернути обереги — духовний обов'язок тролів Темного Спису: так священні речі предків вириваються з лап диких фурболгів."},sec={{t="Засідка на караван",b="Застава Зорам'гар — віддалений західний притулок Орди на узбережжі Ашенвалю, тож подорожі лісовими стежками сповнені небезпек. Загін тролів Темного Спису, що йшов до застави, так і не дійшов: на нього жорстоко напало плем'я фурболгів Будякохутрих, що люто стереже свої землі. Міцува сприймає смерть родичів як майбутню зустріч у потойбіччі, але осквернення й крадіжка їхніх священних оберегів — нестерпна образа."},{t="Священні дрібнички",b="У тролячій культурі обереги й талісмани глибоко пов'язані з особистістю, духовним захистом і зв'язком із лоа. Міцува вважає троля без оберега таким самим порожнім і нікчемним, як орка без бойових шрамів. Фурболги Будякохутрі затягли викрадені речі до Твердині Будякохутрих, глибоко в печери за Селом Будякохутрих, і поховали їх у скринях подалі від законних власників."}},faq={{q="Хто дає це завдання і де його знайти?",a="Завдання дає Міцува, троль Темного Спису із Застави Зорам'гар на узбережжі Зорам, на північно-західному березі Ашенвалю.",al={"хто дає завдання","де міцува","хто починає тролячий оберіг"}},{q="Чому тролячі обереги такі важливі для Міцуви?",a="Для тролів священні обереги мають глибоке духовне й культурне значення. Міцува порівнює троля без оберега з орком без бойових шрамів, і те, що ворожі фурболги тримають ці реліквії в себе, вважає обурливою наругою над його загиблими родичами.",al={"важливість оберегів","чому тролячі обереги важливі","значення оберегів"}},{q="Де знайти тролячі обереги?",a="Обереги зберігаються в скринях у Твердині Будякохутрих — глибоких печерах на північному краю Села Будякохутрих, що на північ від поселення нічних ельфів Астранаар.",al={"місця оберегів","де скрині","знайти обереги"}},{q="Хто викрав обереги?",a="Фурболги Будякохутрі напали із засідки й убили родичів Міцуви, коли ті йшли до Застави Зорам'гар, пограбували їхні речі й затягли священні обереги до своїх печер.",al={"хто забрав обереги","винуватці засідки"}},{q="Що сталося з тролями, які несли обереги?",a="Їх убили фурболги Будякохутрі на стежці. Міцува оплакує їх, але вірить, що зрештою возз'єднається з ними в потойбіччі, тож насамперед хоче повернути їхні священні реліквії.",al={"доля каравану","вбиті тролі","рідня міцуви"}},{q="Чи доступне це завдання Альянсу?",a="Ні. Завдання починається на Заставі Зорам'гар і доступне лише гравцям Орди, які допомагають племені Темного Спису.",al={"тролячий оберіг альянс","чи альянс може це"}}},fp="11,292,19.467.0,15.422.0,48.142.0,49.253.0,35.190.0,21.181.0,62.205.0,40.117.0"}
P.entries["quest:647"] = {n="Самогон МакКрила",s="«Самогон МакКрила» — швидке доручення від Фоґґі Маккріла, дворфа, що застряг на зруйнованій частині Мосту Тандол. Перебравши власного міцного трунку й проспавши свою варту, Фоґґі доручає мандрівникові з Альянсу якнайшвидше доставити свіжу партію до Гілсбреда, щоб розрахуватися з давнім боргом перед Броварником Білґером у Саутшорі.",h="«Самогон МакКрила» — швидке доручення від Фоґґі Маккріла, дворфа, що застряг на зруйнованій частині Мосту...",kw={"самогон маккріла","фоґґі маккріл","броварник білґер","саутшор","міст тандол","борг"},ang={["faction:Alliance"]="Цей швидкий суходільний рейс показує життєво важливий зв'язок між Мостом Тандол і Саутшором у Гілсбреді, який тримає Альянс.",["race:Dwarf"]="Дворфи одразу зрозуміють подвійну біду: нестерпне похмілля й несплачений пивоварський борг перед побратимом."},sec={{t="Похмілля вартового",b="Варта на зруйнованому Мосту Тандол — мокра, холодна й сумнозвісно нудна. Фоґґі Маккріл рятується від вогкого холоду власним саморобним самогоном — таким лютим, що його наслідки він порівнює з цілою бригадою облогових машин, що прокотилася йому по черепу. На біду Фоґґі, одна чарка виявилася зайвою — і він знепритомнів просто на посту. Оскільки дворфами, що обороняють міст, командує Лонґбрейд Похмурий, Фоґґі не може собі дозволити ще одного порушення дисципліни."},{t="Наввипередки з часом",b="Клопоти Фоґґі ускладнює давній борг перед Броварником Білґером у Саутшорі. Фоґґі пообіцяв Білґерові партію власного трунку, щоб звести рахунки, але через похмілля й службу він за лічені хвилини від того, щоб не дотримати слова. Покладаючись на грифонів і прудкі ноги, мандрівники мають мчати через Аратійське нагір'я до Саутшора й доставити глечик, поки Білґер не вирішив, що Фоґґі знову втік від свого боргу."}},faq={{q="Хто такий Фоґґі Маккріл?",a="Фоґґі Маккріл — дворф, якого можна знайти на зруйнованій частині Мосту Тандол, куди доходять з боку Аратійського нагір'я. Він славиться надзвичайно міцним саморобним самогоном і на варті надто охоче куштує власний виріб.",al={"фоґґі маккріл","хто такий фоґґі","видавець маккріл"}},{q="Чому ця доставка така термінова?",a="Фоґґі страшенно відстав від графіка, бо напився й заснув на варті. Він мусить до суворого терміну доставити самогон Броварникові Білґеру, щоб погасити давній борг, а на дорогу від Мосту Тандол до Саутшора лишилося ледве чверть години.",al={"чому є таймер","чому 15 хвилин","таймер самогону маккріла"}},{q="Хто такий Броварник Білґер?",a="Броварник Білґер — майстер-пивовар із дворфів, що займається своїм ремеслом у прибережному поселенні Саутшор у Передгір'ї Гілсбреда. Він цінує міцний трунок і має з Фоґґі Маккрілом давню ділову домовленість.",al={"броварник білґер","хто такий білґер","білґер саутшор"}},{q="Як устигнути доставити самогон до Саутшора вчасно?",a="Човен від Мосту до Саутшора не ходить. Найшвидше — податися в Аратійське нагір'я й, якщо ви знаєте цей маршрут, полетіти грифоном із Притулку до Саутшора, а тоді знайти в містечку Броварника Білґера, поки не сплив час.",al={"як доставити самогон","найшвидший шлях до саутшора","маршрут доставки самогону"}},{q="Хто такий Лонґбрейда?",a="Лонґбрейда Похмурий — дворф-командувач, що стоїть під Дун Модром у Багнокраї й очолює оборонців Мосту Тандол. Фоґґі до смерті боїться, що Лонґбрейда дізнається, як він упився до непритомності, коли мав стояти на варті.",al={"капітан лонґбрейда","лонґбрейда менетіл"}}},fp="20,347,18.478.0,24.441.0,22.235.0,31.267.0,26.229.0,53.246.0,17.248.0"}
P.entries["quest:6481"] = {n="Земельники повстають",s="Глибоко в Яру Кам'яного Зсуву шаман Мор'роґал виявляє сплячого землянина на ім'я Ґоґґерок, запечатаного в резонітовій скрині. Побоюючись, що прадавня кам'яна істота може обрушити на Калімдор свою первісну руйнівну силу, він посилає героя розбити скриню й повалити Ґоґґерока, перш ніж той відновить повну міць.",h="Глибоко в Яру Кам'яного Зсуву шаман Мор'роґал виявляє сплячого землянина на ім'я Ґоґґерок, запечатаного в...",kw={"земляни повстають","ґоґґерок","мор'роґал","яр кам'яного зсуву","резоніт","землянин"},ang={["class:Shaman"]="Мор'роґал спрямовує шаманську силу, щоб змінити резонітові кристали й порушити стихійну рівновагу, яка зберігає землянина в скрині.",["faction:Horde"]="Знищивши Ґоґґерока, герої Орди закріплюються серед спірних круч Гір Кам'яного Кігтя й здобувають тривку повагу провідників Тандер Блафа.",["race:Tauren"]="Гори Кам'яного Кігтя — священні мисливські угіддя предків для племен Тандер Блафа, і знешкодження прадавньої руйнівної сутності в глибинах гір захищає землю від загибелі."},sec={{t="Сон у камені",b="Досліджуючи навалу шкідників у Яру Кам'яного Зсуву, розвідники натрапили серед кобольдів на дивну реліквію — резонітову скриню, що випромінювала неземну силу. Мор'роґал, шаман-таурен у Горах Кам'яного Кігтя, збагнув, чим насправді є ця скриня: в'язницею і водночас прихистком для Ґоґґерока, сплячого землянина. Ці первісні кам'яні творіння сильніші за будь-якого смертного воїна, тож Ґоґґерок, що вільно блукає краєм, — загроза самому існуванню цих земель."},{t="Резонітовий Кристал",b="Пробуджений у повній силі землянин обернувся б лихом для Гір Кам'яного Кігтя. Щоб схилити шальки терезів, Мор'роґал змінив суміш принесених йому резонітових кристалів, наповнивши їх шаманською магією. Утворений зачарований кристал має розбити резонітову скриню з такою силою, щоб Ґоґґерок прокинувся різко ослабленим. Воякам Орди лишається розтрощити скриню й повалити ошелешену, титанами створену істоту, перш ніж вона струсить із себе століття заціпеніння."}},faq={{q="Хто такий Мор'роґал?",a="Мор'роґал — шаман-таурен у Горах Кам'яного Кігтя. Він вивчає негаразди в краї й за допомогою магії стихій розбирається з дивними прадавніми артефактами й загрозами, які викопали місцеві паразити.",al={"мор'роґал","хто видає завдання","орк шаман мор'роґал"}},{q="Хто такі земляни?",a="Земляни — прадавні істоти з живого каменю, творіння, які Титани лишили на світанку світу. Глибоко пов'язані із землею й наділені неймовірною фізичною силою, вони тисячоліттями спали, поховані по всьому Калімдору й Східних Королівствах.",al={"що таке земляни","переказ про землян","хто такі земляни"}},{q="Чому Мор'роґал хоче смерті Ґоґґерока?",a="Мор'роґал боїться, що незрівнянна сила пробудженого землянина накличе біду на Кам'яний Кіготь і весь Калімдор. Такі первісні істоти непередбачувані й надзвичайно могутні, тож він вважає, що знищити Ґоґґерока, поки той ослаблений після сну, — єдиний спосіб уберегти землю.",al={"чому вбити ґоґґерока","чи ґоґґерок злий","чому вбивати землян"}},{q="Де знайти Ґоґґерока?",a="Ґоґґерок замурований у резонітовій скрині глибоко в печерах Яру Кам'яного Зсуву, на південному сході Гір Кам'яного Кігтя, серед кобольдів Кам'яного Зсуву, що риють ходи в печерах.",al={"де діжка","місце ґоґґерока","знайти діжку з резонітом"}},{q="Як пробудити Ґоґґерока?",a="Застосуйте Зачарований Кристал Резоніту, який дає Мор'роґал, просто до резонітової скрині в печері. Магічно змінений кристал розколює вмістилище й змушує сплячого землянина вийти назовні.",al={"як призвати ґоґґерока","використати зачарований кристал резоніту","відкрити діжку"}},{q="Що буде після смерті Ґоґґерока?",a="Коли ви повернетеся до Мор'роґала з вісткою про смерть Ґоґґерока, глибокий страх шамана розвіється. Він славить вас як героя, чий подвиг відвернув величезне лихо, і це приносить вам велику шану серед тауренів Тандер Блафа.",al={"історія нагороди","реакція мор'роґала","здати земляни повстають"}}},fp="13,335,18.513.0,20.491.1,17.221.0,19.254.0,38.305.0,26.203.0,27.210.0,37.227.1"}
P.entries["quest:6482"] = {n="Свобода для Руула",s="Глибоко у Твердині Будякохутрих на півночі Ашенвалю замкнений у клітці ведмідь на ім'я Руул чекає порятунку від зіпсованих фурболгів Будякохутрих. Шукачі пригод з Орди можуть допомогти бранцеві пробитися з лігва фурболгів у безпечне місце.",h="Глибоко у Твердині Будякохутрих на півночі Ашенвалю замкнений у клітці ведмідь на ім'я Руул чекає порятунку...",kw={"свобода для руула","руул сноугуф","друїд","будякохутрі","порятунок","завдання"},ang={["class:Druid"]="Полон Руула — повчальне нагадування про ризики блукання дикими землями у звіриній подобі, де зіпсовані місцеві не відрізнять друга від здобичі.",["faction:Horde"]="Кожна душа, врятована із зіпсованих западин північного Ашенвалю, зміцнює хитку заставу Орди — Розщеплене Дерево.",["race:Tauren"]="Порятунок брата з Кола Кенарія, що опинився в біді, і полегшення тривоги його родини на Заставі Розщепленого Дерева шанують узи Земної Матері та Орди."},sec={{t="Друїд у кайданах",b="Мандруючи зіпсованими лісами північного Ашенвалю, друїд Руул Сноугуф у подобі ведмедя забрів надто близько до Твердині Будякохутрих. Зіпсовані фурболги, втративши мудрість предків і ведені дикою підозріливістю, сприйняли перевтіленого таурена за звичайного звіра. Замість поставитися до нього з шаною, вони замкнули його в клітці й морили голодом, виснажуючи його магічні сили, тож тепер він не може сам вирватися."},{t="Утеча з лігва",b="Знесилений голодом і неволею, Руул не може ні змінити подобу, ні сам пробитися крізь печерне поселення фурболгів. Звільнений союзником з Орди, він покладається на свого рятівника, щоб той проклав шлях крізь хвилі ворожих Будякохутрих. Безпечно діставшись околиць Застави Розщепленого Дерева, він ненадовго показує свою справжню тауренську подобу, щоб щиро подякувати, а тоді повертається в глушину відсипатися після виснаження."}},faq={{q="Чому фурболги замкнули Руула Сноугуфа?",a="Руул досліджував ліси у ведмежій подобі. Осквернені фурболги Будякохутрі не впізнали в ньому друїда, сприйняли за дикого звіра й замкнули в клітці, де морили голодом, доки в нього не лишилося сил утекти.",al={"чому руул у пастці","як руула схопили","чому в клітці"}},{q="Хто така Яма Сноугуф?",a="Яма Сноугуф — сестра Руула із Застави Розщепленого Дерева в Ашенвалі. Вона дуже тривожилася, відколи кілька днів тому Руул пішов у ліс і не повернувся.",al={"сестра руула","яма розщепленого дерева","хто така яма"}},{q="Чому Руул не міг просто вийти з ведмежої подоби й утекти?",a="Довгий полон і навмисне голодування, на яке прирекли його фурболги Будякохутрі, тяжко виснажили Руула. Без їжі й сил його запаси природної енергії цілком вичерпалися, і він був безпорадний, доки його не врятували.",al={"чому руул не змінив подобу","пастка для друїда-ведмедя"}},{q="Що буде, коли Руул опиниться в безпеці?",a="Коли ви виведете його з ворожого лігва до меж Застави Розщепленого Дерева, Руул ненадовго повертає собі подобу таурена, щоб подякувати, а тоді знову стає ведмедем і йде шукати тихе місце, щоб виспатися й оговтатися.",al={"куди йде руул","кінцівка руула"}},{q="Чи всі фурболги в Ашенвалі ворожі, як Будякохутрі?",a="Ні. Багато племен фурболгів мають шляхетне коріння й глибокий зв'язок із природою, але Будякохутрі з півночі Ашенвалю піддалися темним, згубним впливам, що зробили їх агресивними й непередбачуваними.",al={"чи всі фурболги злі","осквернення будякохутрих"}},{q="Де відбувається порятунок?",a="Руул ув'язнений у Твердині Будякохутрих — лігві фурболгів у пагорбах на північний захід від Застави Розщепленого Дерева й на північ від Астранаару в Ашенвалі.",al={"де руул","місце руула сноугуфа"}}},fp="15,223,17.433.0,19.421.1,48.238.1,21.176.0,56.235.1,39.229.1,59.215.0,33.145.0"}
P.entries["quest:65"] = {n="Братство Дефіас",s="Це доручення — перший крок до розплутування таємного угруповання, що тероризує Вестфол. Ґраян Стаутмантл із Сентінел Гілла відправляє мандрівників на схід, до Редріджу, — порадитися з темним знайомим, який може знати, де ховаються злодії.",h="Це доручення — перший крок до розплутування таємного угруповання, що тероризує Вестфол.",kw={"братство дефіас","ґраян стаутмантл","вайлі чорний","лейкшир","редрідж","вестфол"},ang={["class:Rogue"]="Стаутмантл розуміє, що звичайна солдатська муштра не зламає злочинного угруповання: потрібен той, хто знається на тінях і вуличних послугах, — і цей шлях веде просто до Вайлі Чорного.",["faction:Alliance"]="Довга дорога з Вестфолу до Редріджу показує, наскільки віддалені землі Стормвінда мусять покладатися одна на одну, поки столиця лишається байдужою."},sec={{t="Загроза в пилюці",b="Вестфол лежить у руїні: його врожаї розграбовано, а землі заполонили розбійники в червоних банданах. Ґраян Стаутмантл і Народне ополчення утримують Сентінел Гілл попри майже безперервні напади, але воюють наосліп. Стаутмантл розуміє: рубаючи поодиноких мародерів, край не врятувати — треба знайти внутрішнє коло угруповання й з'ясувати, хто ним командує."},{t="Знайомий з іншого краю",b="Замість покладатися на офіційні військові канали чи на вельмож Стормвінда, яких тут ніколи не буває, Стаутмантл згадує, хто перед ним у боргу. Він відправляє довірених шукачів пригод повз Елвінн у Гори Редріджу. У тихому приозерному селищі Лейкшир, на горішньому поверсі місцевої корчми, переховується пройдисвіт на ім'я Вайлі Чорний. Він знає підпілля значно краще за будь-якого капітана ополчення, тож саме Вайлі — перша ниточка, що допоможе розплутати схованки Братства."}},faq={{q="Хто такий Ґраян Стаутмантл?",a="Ґраян Стаутмантл — ватажок Народного ополчення, строкатого загону оборони на Сентінел Гіллі у Вестфолі. Поки Стормвінд нехтує прикордонням, він організовує захист небагатьох фермерів і біженців, що там лишилися.",al={"ґраян стаутмантл","хто дає це завдання","видавець вестфол"}},{q="Чому Стаутмантл посилає мене до Лейкшира?",a="Народне ополчення не має інформаторів у підпіллі самого Вестфолу. Стаутмантл просить давньої особистої послуги у Вайлі Чорного, розбійника, що мешкає в корчмі Лейкшира, сподіваючись, що зв'язки в злочинному світі допоможуть з'ясувати, хто веде злодіїв.",al={"чому лейкшир","чому йти до реджриджа","чому вайлі"}},{q="Хто такий Вайлі Чорний?",a="Вайлі Чорний — розбійник, що зупинився на другому поверсі Корчми Лейкшира в Горах Редріджу. Він винен Ґраянові Стаутмантлу послугу, тож через нього зручно дізнаватися підпільні чутки й шукати кримінальні зв'язки.",al={"хто такий вайлі","вайлі лейкшир","вайлі чорний"}},{q="Що таке Братство Дефіас?",a="Братство Дефіас — безжальне злочинне угруповання в червоних масках, що захопило ферми, дороги й покинуті копальні Вестфолу, виганяє поселенців і кидає виклик владі Стормвінда.",al={"братство дефіас","що таке дефіас","бандити з червоними пов'язками"}},{q="Де в Лейкширі знайти Вайлі?",a="Вайлі Чорний — нагорі, на другому поверсі Корчми Лейкшира, що стоїть біля мосту в містечку Лейкшир у Горах Редріджу.",al={"де вайлі","знайти вайлі","місце вайлі"}},{q="Чи доведеться битися в цьому завданні?",a="Ні. Цей перший крок — суто розвідувальний. Ви просто вирушаєте із Сентінел Гілла у Вестфолі через Ліс Елвінн до корчми в Лейкширі, щоб зв'язатися з Вайлі.",al={"чи важке це завдання","бій у завданні братство дефіас","вороги"}}},fp="22,253,22.387.0,22.453.0,25.238.0,43.236.0,23.210.0,31.221.0,36.149.0,35.171.0"}
P.entries["quest:6503"] = {n="Ашенвальські розвідниці",s="«Ашенвальські розвідниці» — завдання Орди на перехоплення дозорів, яке дає Курай'бін в Ашенвалі. Розвідниці нічних ельфів розійшлися від Застави Срібнокрилих, щоб збирати відомості про довколишні табори Орди, тож Орда завдає випереджального удару, щоб приховати оборону застави. Полюючи на цих потайних розвідниць, Орда засліплює місцеві сили Альянсу й відбиває охоту до нових вилазок.",h="«Ашенвальські розвідниці» — завдання Орди на перехоплення дозорів, яке дає Курай'бін в Ашенвалі.",kw={"ашенвальські розвідниці","курай'бін","застава срібнокрилих","розвідка","орда","завдання"},ang={["class:Hunter"]="Щоб вистежити розвідниць, що ховаються в лісовій гущавині, потрібні гостре чуття, загострений нюх слідопита й влучне око.",["class:Rogue"]="Знищення ворожих розвідниць обертає потайність нічних ельфів проти них самих і забезпечує лазутчикам Орди владу над тінями лісу.",["faction:Horde"]="Кожна розвідниця нічних ельфів, убита в Ашенвалі, захищає місцеві табори й лісозаготівлі від злагоджених контрнаступів Альянсу."},sec={{t="Очі в кронах",b="Ліси Ашенвалю лишаються спірним прикордонням, де пильно стежать за кожною стежкою й кожним гребенем. Розвідка тут смертоносна, як сокира, і донесення, що доходять до Курай'біна, підтверджують: розвідниці нічних ельфів, відомі як ашенвальські розвідниці, вислизнули з твердині Альянсу — Застави Срібнокрилих. Діючи в густій глушині на схід від своєї бази й на південь від місцевих володінь Орди, вони никають лісовими стежками, наносячи на мапу укріплення й стежачи за пересуванням військ."},{t="Засліпити Альянс",b="Щоб запобігти злагодженому нападу, Орда покладається на знищення ворожої розвідки, перш ніж та повернеться додому. Полюючи на розвідниць, звитяжці Орди позбавляють командирів Застави Срібнокрилих важливих знань про чисельність військ і оборону периметра застави. Утративши передові очі, нічні ельфи збиті з пантелику й значно менше схильні ризикувати сміливими маневрами в спірних лісах."}},faq={{q="Хто дає завдання «Ашенвальські розвідниці»?",a="Завдання дає Курай'бін, розвідник Орди в Ашенвалі, який організовує стеження за нічними ельфами в лісі й протидію їм.",al={"видавець завдання","хто дає завдання","завдання кураї'біна"}},{q="Де знайти ашенвальських розвідниць?",a="Розвідниці нишпорять лісами на схід від Застави Срібнокрилих і на південь від табору Курай'біна, пробираючись підліском, щоб збирати відомості.",al={"місця розвідниць","де розвідниці","де знайти розвідниць"}},{q="Чому розвідниці загрожують Орді?",a="Розвідниці — передові вивідувачки із Застави Срібнокрилих. Якщо вони нанесуть на мапу табори Орди й порахують її загони, Альянс зможе влаштувати точні набіги на вразливі позиції.",al={"чому вбивати розвідниць","загроза розвідниць","призначення розвідниць"}},{q="Що таке Застава Срібнокрилих?",a="Застава Срібнокрилих — помітний військовий пункт нічних ельфів в Ашенвалі, передова база сил Альянсу, що боронять ліс і протистоять поширенню Орди.",al={"переказ про заставу срібнокрилих","що таке застава срібнокрилих","срібнокрилі альянс"}},{q="Чи це завдання — частина довшої історії?",a="Здебільшого це окреме тактичне завдання, що має послабити розвідку Альянсу на цій ділянці; воно винагороджує бійців, які допомагають Курай'біну вберегти периметр.",al={"ланцюжок завдань","наступне завдання","ланцюжок розвідниць"}},{q="Чи можуть гравці Альянсу виконати це завдання?",a="Ні, це завдання лише для Орди. Курай'бін діє виключно в інтересах передової Орди в Ашенвалі.",al={"чи це лише для орди","версія для альянсу","чи альянс може це"}}},fp="20,388,20.476.0,21.423.0,41.151.0,43.148.0,45.204.0,27.180.0,41.179.0,41.119.0"}
P.entries["quest:6504"] = {n="Загублені сторінки",s="Коли оркиня Ґурда Рейджскар везла щойно придбаний гоблінський подрібнювач із Раджета до Лісозаготівельного Табору Бойової Пісні, раптовий порив вітру вирвав у неї посібник з керування машиною. Застрягши біля Застави Розщепленого Дерева, вона не може запустити це складне інженерне диво, поки не збере розкидані сторінки.",h="Коли оркиня Ґурда Рейджскар везла щойно придбаний гоблінський подрібнювач із Раджета до Лісозаготівельного...",kw={"загублені сторінки","ґурда рейджскар","подрібнювач","посібник","бойова пісня","завдання"},ang={["faction:Horde"]="Кожен подрібнювач, що дістається Лісозаготівельного Табору Бойової Пісні, пришвидшує заготівлю дорогоцінної деревини, потрібної для мурів, хатин і бойових кораблів Дуротару.",["profession:Engineering"]="Майстри добре зрозуміють клопіт Ґурди: керувати збудованим гоблінами подрібнювачем без настанов виробника — найпевніший шлях до катастрофічного вибуху котла.",["race:Orc"]="Ручна праця й воїнські традиції не залишають терпцю на докладну гоблінську паперову тяганину, тож роздратування Ґурди через загублені технічні аркуші цілком зрозуміле."},sec={{t="Порив невдачі",b="Клан Бойової Пісні значною мірою покладається на парові подрібнювачі, куплені в гоблінів із порту Раджет, щоб валити ліс по всьому Ашенвалю. Керувати цими примхливими, гучними штуковинами звичайному орку-воїнові зовсім не просто. Коли Ґурда Рейджскар вирушила на північ із новеньким подрібнювачем, раптовий порив вітру вирвав у неї з рук книжечку з інструкціями й розкидав дванадцять тендітних пергаментних аркушів по всьому лісі."},{t="Сторінки в глушині",b="Буйні вітри перенесли посібник через крони, і окремі сторінки опинилися в руках блукаючих істот, сектантів і лісових мешканців по всьому краю. Без усіх трьох розділів складна машина лишається мертвою брилою сталі з циркулярними пилками, а Ґурда застрягла на дорозі до Застави Розщепленого Дерева й не може стати до лісозаготівель."}},faq={{q="Хто така Ґурда Рейджскар?",a="Ґурда Рейджскар — робітниця Орди, якій доручили перегнати гоблінський шредер із торгового порту Раджет до Ашенвалю, щоб він долучився до робіт у Лісозаготівельному Таборі Бойової Пісні.",al={"ґурда","рейджскар","видавець завдання"}},{q="Навіщо Ґурді інструкція, щоб керувати шредером?",a="Гоблінська інженерія славиться примхливістю й нелогічністю: вибухонебезпечні котли, хитромудрі клапани тиску й складні важелі. Навіть завзятий орк не зможе безпечно керувати цією штуковиною, не прочитавши інструкції від виробника.",al={"навіщо інструкція","чому вона не може керувати","інструкція керування шредером"}},{q="Як сторінки інструкції опинилися по всьому Ашенвалю?",a="Коли Ґурда йшла лісовою дорогою на північ, сильний порив вітру вирвав книжку з її рук. Аркуші розлетілися лісом, і в неї лишилася тільки порожня обкладинка.",al={"як сторінки загубилися","вітер розніс сторінки"}},{q="Куди зрештою має потрапити шредер?",a="Машина призначена для Лісозаготівельного Табору Бойової Пісні, де Орда завзято вирубує ліс, щоб постачати деревину до Оргріммара й Дуротару.",al={"куди йде шредер","призначення шредера бойової пісні"}},{q="Де знайти загублені сторінки?",a="Вітер розніс сторінки далеко й широко, і їх підібрали різні гуманоїди та ворожі мешканці лісу, що блукають Ашенвалем.",al={"де знайти сторінки","хто дає сторінки"}},{q="Чому Орда купує машини в Раджеті?",a="Раджет — найближчий нейтральний порт із діяльними торговими зв'язками з гоблінськими картелями. Орда регулярно купує там спеціальне інженерне обладнання, підривні знаряддя й парові машини, щоб посилити своє військове постачання.",al={"гоблінські машини орди","торгівля орди з раджетом"}}},fp="14,296,18.449.0,23.388.0,22.180.0,64.235.0,61.195.0,42.159.0,37.143.0,51.225.0"}
P.entries["quest:6523"] = {n="Захисти Каю",s="«Захисти Каю» — завдання Орди із супроводу в Горах Кам'яного Кігтя. Знайшовши Каю Флетгуф у полоні ворожих тауренів-Ґрімтотемів, шукачі пригод проводять її небезпечними гірськими стежками до Табору Апараже. Звістка про те, що вона жива, приносить величезне полегшення її стривоженому батькові, Макабі Флетгуфу.",h="«Захисти Каю» — завдання Орди із супроводу в Горах Кам'яного Кігтя.",kw={"захисти каю","кая флетгуф","макаба флетгуф","табір апараже","ґрімтотем","супровід"},ang={["faction:Horde"]="Безпека родин у дорозі зміцнює тяжко здобуті опорні пункти й шляхи постачання Орди в Горах Кам'яного Кігтя.",["race:Tauren"]="Порятунок Каї — пряма допомога родичам, яких розлучила хижа агресія клану Ґрімтотем."},sec={{t="Бранка серед круч",b="У Горах Кам'яного Кігтя таурени мають чимало гірких суперечок, але жодна не така гостра, як ворожнеча довкола віроломного клану Ґрімтотем. Глибоко на ворожій землі Каю Флетгуф схопили й тримали в полоні. Щоб утекти пішки, треба пройти звивистими стежками, обабіч яких чатують хижаки й пильні вороги, тож збройний супровід — її єдина реальна надія дістатися своїх."},{t="Втеча до Табору Апараже",b="Табір Апараже лежить на сході Гір Кам'яного Кігтя, і звідти Кая знає дорогу додому. Вона прямує до табору, певна, що, діставшись його, далі дійде сама. Провівши її стежками, де на кожному кроці засідки, ви не дасте знову схопити її, перш ніж викрадачі помітять, що бранка втекла."},{t="Батькове полегшення",b="Чекаючи вістей біля південно-східного кордону Гір Кам'яного Кігтя, Макаба Флетгуф боїться найгіршого за свою зниклу доньку. Коли гінці приносять підтвердження, що Кая щасливо дісталася Табору Апараже, розпач Макаби змінюється безмежною вдячністю героям, які стали між його дитиною та її викрадачами."}},faq={{q="Хто така Кая Флетгуф?",a="Кая Флетгуф — молода тауренка, яку захопили в полон ворожі загони Ґрімтотем у Горах Кам'яного Кігтя. Вона покладається на мандрівних шукачів пригод Орди, щоб ті визволили її й провели в безпечне місце.",al={"хто така кая","переказ про каю флетгуф","кая"}},{q="Куди треба провести Каю?",a="Каю треба безпечно провести стежками до Табору Апараже на сході Кам'яного Кігтя, звідки вона вже сама знає дорогу додому.",al={"куди вести каю","куди супроводжувати каю","куди йде кая"}},{q="Хто такий Макаба Флетгуф?",a="Макаба Флетгуф — батько Каї, що з тривогою чекає біля південно-східного входу в Гори Кам'яного Кігтя. Він у розпачі через зниклу доньку, доки шукачі пригод не принесуть звістку про її порятунок.",al={"хто такий макаба","переказ про макабу флетгуфа","батько каї"}},{q="Хто захопив Каю?",a="Каю взяли в полон ворожі таурени Ґрімтотем, які мають табори й засідки по всіх скелях Кам'яного Кігтя.",al={"хто забрав каю","хто викрав каю","викрадачі каї"}},{q="Що буде, коли Кая дістанеться Табору Апараже?",a="Щойно Кая дістанеться Табору Апараже, вона далі піде сама, а гравцеві треба повернутися до Макаби Флетгуфа з радісною звісткою, що вона жива.",al={"після захисти каю","що далі після супроводу","продовження захисти каю"}},{q="Чи доступне це завдання гравцям Альянсу?",a="Ні. Родина Флетгуф належить до мирних тауренів, союзників Орди, тож ця рятувальна місія — лише для шукачів пригод Орди.",al={"чи альянс може захисти каю","чи кая лише для орди"}}},fp="12,311,22.400.0,22.295.0,17.322.1,21.195.0,36.131.0,23.190.0,18.115.0,45.162.0,44.137.0"}
P.entries["quest:6541"] = {n="Доповідь Кадраку",s="Торк на Перехресті скеровує вправних бійців Орди на північ, до сторожової вежі Кадрака біля кордону з Ашенвалем. Кадрак керує просуванням Орди в прадавній ліс і готує новобранців до сутичок, що чекають попереду.",h="Торк на Перехресті скеровує вправних бійців Орди на північ, до сторожової вежі Кадрака біля кордону з...",kw={"доповідь кадраку","кадрак","торк","ашенваль","застава розщепленого дерева","перехрестя"},ang={["faction:Horde"]="Це розпорядження знаменує перехід від оборони освоєних земель у Пустках до захисту життєво важливих ресурсних шляхів у спірних лісах на півночі.",["race:Orc"]="Ашенваль — важливе випробувальне поле для орків: тут вони здобувають деревину, потрібну, щоб зміцнити Оргріммар і збудувати тривкий дім у Калімдорі."},sec={{t="Дорога на північ",b="Поки Перехрестя дає раду шипогривам, кентаврам і місцевим розбійникам, ширші територіальні інтереси Орди звернені на північ — до густих лісів Ашенвалю. Торк править за посередника: він скеровує досвідчених бійців, що проявили себе в центральних Пустках, до північної прикордонної вежі, яку тримає Кадрак."},{t="Стратегія рубежу",b="Кадрак наглядає за південними підступами до Ашенвалю й організовує підкріплення для позицій Орди за кордоном. Завдяки новим таборам на кшталт Застави Розщепленого Дерева й застави на Зорамському Березі Орда рішуче зміцнює свою присутність у багатих на деревину лісах, попри запеклий опір місцевих нічних ельфів."}},faq={{q="Хто такий Торк?",a="Торк — орк-офіцер на Перехресті в Пустках. Він допомагає організовувати місцеву оборону й скеровує перспективних шукачів пригод на війну в інших краях, як-от у кампанію в Ашенвалі.",al={"торк перехрестя","хто дає доповідь кадраку","торк пустки"}},{q="Де знайти Кадрака?",a="Кадрак стоїть на північній сторожовій вежі в Пустках, просто біля головної дороги, що веде в ліси Ашенвалю.",al={"місце кадрака","де кадрак","вартова вежа кадрака"}},{q="Чому Орда просувається в Ашенваль?",a="Орді потрібні деревина й ресурси, щоб будувати нові міста в Дуротарі та Пустках. Розширення в Ашенваль дає життєво важливий ліс, хоч і ставить Орду у відкрите протистояння з нічними ельфами.",al={"чому ашенваль","орда в ашенвалі","вторгнення в ашенваль"}},{q="Які застави Орда заснувала в Ашенвалі?",a="Кадрак зауважує, що Орда заснувала Заставу Розщепленого Дерева біля центральної дороги в ліс і ще одну заставу далі на захід, на узбережжі Зорам.",al={"бази орди в ашенвалі","база зорамського узмор'я","розщеплене дерево"}},{q="Що далі, після доповіді Кадракові?",a="Коли ви доповісте Кадракові, він розповість вам про військову ситуацію в краї й доручить зібрати донесення з різних застав Бойової Пісні по всьому Ашенвалю.",al={"після кадрака","наступне завдання після кадрака","що дає кадрак"}},{q="Чи можна отримати це доручення деінде, крім Пусток?",a="Так. Майже такий самий наказ доповісти Кадракові отримують бійці Орди, що діють із Малака'джина в Горах Кам'яного Кігтя.",al={"інше завдання кадрака","завдання кадрака в кам'яному кігті"}}},fp="16,238,14.323.0,17.338.0,13.204.0,24.127.0,40.204.0,53.157.0,37.158.0,69.136.0"}
P.entries["quest:6542"] = {n="Доповідь Кадраку",s="Цей військовий наказ спрямовує воїнів Орди з Малака'джина в Горах Кам'яного Кігтя на сторожовий пост Кадрака на кордоні північних Пусток. Він знаменує перехід від оборони круч до підсилення суперечливої військової кампанії Орди в Ашенвалі. Доповівши Кадраку, вояки стають до лав, щоб підтримати передові табори — Заставу Розщепленого Дерева й Зорамське Узмор'я.",h="Цей військовий наказ спрямовує воїнів Орди з Малака'джина в Горах Кам'яного Кігтя на сторожовий пост Кадрака...",kw={"доповідь кадраку","кадрак","дарн талонґріп","ашенваль","застава розщепленого дерева","бойова пісня"},ang={["faction:Horde"]="Цей наказ залучає вас до ширших воєнних зусиль Вождя: досвідчених прикордонних бійців спрямовують у запеклу боротьбу за багатства Ашенвалю.",["race:Orc"]="Похід в Ашенваль вирішальний для клану Бойової Пісні й для виживання Дуротару, тож пост Кадрака — місце, де молоді орки-воїни доводять, чого варті.",["race:Tauren"]="Дозорці Орди, як-от орк Дарн Талонґріп, безпечно проводять мандрівників через гірські кордони й тримають зв'язок між землями Бладгуфів і північним фронтом Вождя."},sec={{t="Поклик північного фронту",b="На скелястому перевалі Малака'джин орк Дарн Талонґріп пильнує південні й гірські рубежі Орди. Та найбільший військовий тиск — на півночі, у прадавніх лісах Ашенвалю, де Вартові нічних ельфів безперестанку б'ються з лісорубами клану Бойової Пісні. Помічаючи загартованих у боях вояків, що проходять через Гори Кам'яного Кігтя, Дарн відсилає здібних новобранців до сторожової вежі в північних Пустках — допомогти в тривалих походах."},{t="Варта Кадрака",b="Орк Кадрак стоїть просто на північному порозі, де посушлива савана зустрічається із зеленим пологом Ашенвалю, і керує пересуванням військ Орди на спірну землю. Орда завзято закріплюється тут, утримуючи застави і на західному Зорамському Узмор'ї, і на півночі — Заставу Розщепленого Дерева. Кадрак — життєво важливий вузол, через який узгоджують постачання, війська й нагальні донесення вздовж цих обложених лісових рубежів."}},faq={{q="Хто посилає до Кадрака з Кам'яного Кігтя?",a="Дарн Талонґріп, орк із застави Орди Малака'джин у Горах Кам'яного Кігтя, дає це доручення вправним шукачам пригод, що прямують до лісового кордону.",al={"видавець доповіді кадраку","хто починає доповідь кадраку кам'яний кіготь","завдання дарна талонґріпа"}},{q="Де знайти Кадрака?",a="Кадрак стоїть на північній сторожовій вежі в Пустках і стереже головну дорогу, що веде на північ, в Ашенваль.",al={"місце кадрака","де кадрак","знайти кадрака"}},{q="Чому Орда набирає воїнів для Ашенвалю?",a="Орді потрібна деревина, щоб утримувати Оргріммар, і вона збудувала укріплені позиції, як-от на Зорамському Узмор'ї та на Заставі Розщепленого Дерева. Ці зусилля наражаються на запеклий опір корінних нічних ельфів, тож командирам постійно потрібне підкріплення, щоб утримати територію.",al={"чому орда набирає в ашенваль","похід орди в ашенваль","чому битися в ашенвалі"}},{q="Що буде після доповіді Кадракові?",a="Кадрак розповість вам про стратегічну ситуацію в Ашенвалі й доручить доставляти та збирати військові донесення по спірних заставах лісу — у завданні «Донесення Бойової Пісні».",al={"що далі після кадрака","донесення бойової пісні","продовження доповіді кадраку"}},{q="Чим це завдання відрізняється від версії з Пусток?",a="Обидва — завдання-дороговкази до Кадрака на кордоні Ашенвалю. Одне дають у Пустках (на Перехресті), а це — у Горах Кам'яного Кігтя; виконавши будь-яке з них, ви потрапите в сюжет Ашенвалю.",al={"пустки проти кам'яного кігтя кадрак","два завдання доповідь кадраку","дубль завдання кадрака"}},{q="Що таке Зорамське Узмор'я, про яке йдеться в донесенні?",a="Зорамське Узмор'я — прибережна місцевість на північному заході Ашенвалю, на березі Прихованого Моря. Орда збудувала там укріплену заставу на пляжі, щоб підтримувати тактичні переміщення й забезпечити доступ до моря.",al={"що таке зорамське узмор'я","застава зорамського узмор'я","пляжна база ашенвалю"}}},fp="16,398,28.440.0,14.447.0,40.174.0,24.128.0,51.274.0,39.186.0,49.221.0,51.197.0"}
P.entries["quest:6543"] = {n="Донесення Бойової Пісні",s="Це доручення дає Кадрак на прикордонній сторожовій вежі між північними Пустками й Ашенвалем: гінці мають узгодити польову розвідку по всьому спірному лісу. Шукачі пригод доставляють постійні накази й збирають розвіддані з передової від вершників, що стоять поблизу Азшари, на Заставі Розщепленого Дерева й на Зорамському Березі.",h="Це доручення дає Кадрак на прикордонній сторожовій вежі між північними Пустками й Ашенвалем: гінці мають...",kw={"донесення бойової пісні","кадрак","ашенваль","застава розщепленого дерева","застава зорам'гар","азшара"},ang={["class:Hunter"]="Пересування підступними дорогами Ашенвалю перевіряє вміння орієнтуватися й виживати в полі — і серед диких хижаків, і під прицілом прихованих ельфійських лучників.",["faction:Horde"]="Доставка цих донесень — один із перших справжніх кроків молодого воїна Орди в територіальній боротьбі з нічними ельфами на півночі Калімдору.",["race:Orc"]="Для орків підтримка клану Бойової Пісні — справа кланової честі й практична потреба: так деревина й далі надходить на будівництво Оргріммара."},sec={{t="Постачання рубежу",b="Стоячи на укріпленій сторожовій вежі на північному краю Пусток, Кадрак наглядає за рухом вузьким гірським каньйоном, що веде в Ашенваль. Для Орди вільний прохід через цей перевал — справа першорядна: посушливі степи не дадуть Оргріммару тих величезних запасів деревини, яких він потребує, тож клан Бойової Пісні мусить пробиватися глибоко в прадавні ельфійські ліси. Щоб розкидані передові дозори мали припаси й діяли злагоджено, потрібні надійні гінці, здатні ухилятися від засідок нічних ельфів на підступних лісових стежках Ашенвалю."},{t="Очі по всьому Ашенвалю",b="Доручення пролягає дугою через увесь прадавній ліс. На крайньому заході, на туманному узбережжі Зорамського Берега, гонець Бойової Пісні пильнує наг і прибережні загрози поблизу Застави Зорам'гар. Глибше в суходолі, на Заставі Розщепленого Дерева, розвідник керує обороною від безупинних набігів Вартових. Ще далі на схід, на звивистій дорозі до зруйнованих руїн Азшари, вершник стежить за східними підступами. Зібравши донесення з усіх трьох постів, Кадрак отримує цілісну картину пересувань військ нічних ельфів і слабких місць рубежу."}},faq={{q="Де починається це завдання?",a="Завдання починається з Кадрака, орка-офіцера на дерев'яній сторожовій вежі, що стереже гірський перевал на межі північних Пусток і південного Ашенвалю.",al={"видавець завдання","місце кадрака","хто дає донесення бойової пісні","де почати"}},{q="Чому Орда шпигує в Ашенвалі?",a="Орда значною мірою залежить від густих лісів Ашенвалю, щоб будувати й зміцнювати поселення на кшталт Оргріммара. Корінні нічні ельфи запекло боронять свої священні гаї, тож увесь край перетворився на зону бойових дій, де без постійної розвідки не втримати застав і шляхів постачання.",al={"чому орда шпигує","деревина бойової пісні","конфлікт в ашенвалі"}},{q="Де знайти трьох розвідників Бойової Пісні?",a="Бігун Бойової Пісні стоїть на Заставі Зорам'гар на узбережжі Зорам, далеко на північному заході. Розвідник Бойової Пісні — у гарнізоні Застави Розщепленого Дерева біля головної дороги. Передовий Вершник Бойової Пісні патрулює східну дорогу, що веде до кордону з Азшарою.",al={"місця розвідників","де розвідники","місце передового розвідника"}},{q="Хто такі передові вершники Бойової Пісні?",a="Передові вершники Бойової Пісні — розвідники й рейдери орківського клану Бойової Пісні. Славетні своєю лютою кіннотою й тактикою сутичок, вони очолюють поширення Орди, лісозаготівлі й оборону територій у лісах Ашенвалю.",al={"клан бойової пісні","хто передові вершники","клан бойової пісні в ашенвалі"}},{q="Що буде, коли повернути донесення?",a="Отримавши зібрані відомості, Кадрак використовує їх, щоб спланувати пересування загонів, посилити вразливі застави на кшталт Зорам'гару й Розщепленого Дерева і глибше закріпити Орду в лісі.",al={"здати донесення","наступний хід","що робить кадрак"}},{q="Чи безпечна дорога через Ашенваль для недосвідчених гінців?",a="Ні. На головному шляху через Ашенваль часто влаштовують засідки потайливі Вартові нічних ельфів, нападають ворожі звірі — скрадачі й ведмеді, — а також патрулі Альянсу з поселень на кшталт Астранаару.",al={"небезпека ашенвалю","чи безпечна дорога","засідки нічних ельфів"}}},fp="19,333,18.542.0,21.568.0,30.175.0,37.290.0,44.255.0,30.242.0,41.226.0,58.210.0"}
P.entries["quest:6544"] = {n="Напад Торека",s="«Напад Торека» — прямий наліт Орди з диких хащів Ашенвалю на сусідній гарнізон нічних ельфів на Заставі Срібнокрилих. Удар, який веде орк-нальотник Торек за наказом із Застави Розщепленого Дерева, має зламати опір місцевих вартових і вбити їхню командувачку, Дуріель Мунфаєр. Це одна з найзухваліших і найкривавіших сутичок у війні за кордони Ашенвалю.",h="«Напад Торека» — прямий наліт Орди з диких хащів Ашенвалю на сусідній гарнізон нічних ельфів на Заставі...",kw={"напад торека","торек","застава срібнокрилих","дуріель мунфаєр","ертоґ рейджтаск","завдання"},ang={["class:Warrior"]="Жорстокий лобовий ближній бій, що випробовує чисту тілесну витривалість проти досвідчених лучниць-вартових і майстрів клинка.",["faction:Alliance"]="Загибель Дуріель Мунфаєр оголює Заставу Срібнокрилих і ставить під загрозу родові лісові володіння нічних ельфів.",["faction:Horde"]="Для Орди прорватися повз Заставу Срібнокрилих — важливе випробування сили, що послаблює облогу нічних ельфів довкола Застави Розщепленого Дерева.",["race:NightElf"]="Наліт б'є в саме серце передового командування вартових і проливає ельфійську кров під гіллям Ашенвалю."},sec={{t="Удар із тіні",b="Ашенваль охоплений дедалі запеклішою прикордонною війною між лісозаготівельними таборами Орди й місцевими нічними ельфами. Прагнучи прорвати оборонний периметр Альянсу, Торек збирає загін нальотників із Розщепленого Дерева біля самої Застави Срібнокрилих. Не чекаючи контрнаступу, Торек готує лобову атаку, щоб розтрощити оборону застави, перш ніж нічні ельфи встигнуть розгорнути посилений похід на Заставу Розщепленого Дерева."},{t="Захоплення Срібнокрилих",b="Застава Срібнокрилих — укріплений лісовий бастіон, де стоять пильні Вартові Срібнокрилих і люті ельфійські воїни. Головна мета Торека — їхня очільниця, Дуріель Мунфаєр. Убивши Дуріель, нальотники обезголовлять місцеву військову ієрархію нічних ельфів і зможуть доповісти про криваву перемогу командирові Ертоґу Рейджтаску біля Річки Фалфаррен."}},faq={{q="Хто такий Торек?",a="Торек — запальний орк-рейдер із Застави Розщепленого Дерева в Ашенвалі. Лютий і спраглий бою, він очолює загін рейдерів, яким доручено нести війну просто до сил нічних ельфів, що окопалися в лісі.",al={"торек","хто такий торек","орк торек"}},{q="Що таке Застава Срібнокрилих?",a="Застава Срібнокрилих — укріплене поселення нічних ельфів в Ашенвалі. Його стережуть добірні Вартові й воїни, і воно слугує військовим оплотом, звідки стежать за пересуваннями загонів Орди лісовими стежками.",al={"застава срібнокрилих","що таке срібнокрилі"}},{q="Хто така Дуріель Мунфаєр?",a="Дуріель Мунфаєр — командувачка нічних ельфів, що обороняє Заставу Срібнокрилих. Як очільниця гарнізону, вона спрямовує місцевих Вартових проти вторгнень Орди — аж доки рейдери Торека не прориваються до табору, щоб її вбити.",al={"дуріель мунфаєр","дуріель"}},{q="Хто такий Ертоґ Рейджтаск?",a="Ертоґ Рейджтаск — офіцер Орди на Заставі Розщепленого Дерева. Він командир Торека, наглядає за військовими діями в краї й приймає звістки про перемоги над Альянсом.",al={"ертоґ рейджтаск","ертоґ"}},{q="Чому Орда нападає на Заставу Срібнокрилих?",a="Орда й нічні ельфи ведуть запеклу війну за територію по всьому Ашенвалю. Удар по Заставі Срібнокрилих знімає тиск зі шляхів постачання Орди й безпосередньо послаблює мережу оборони Вартових, що стереже глибину лісу.",al={"чому нападати на срібнокрилих","конфлікт ашенвалю зі срібнокрилими"}},{q="Де відбувається цей напад?",a="Наступ починається просто під Заставою Срібнокрилих, на захід від Річки Фалфаррен в Ашенвалі, а завершується всередині самого табору нічних ельфів.",al={"місце нападу торека","де торек"}}},fp="15,390,25.430.0,17.377.0,13.236.0,27.204.0,23.224.1,22.206.0,45.234.0,34.153.0"}
P.entries["quest:6545"] = {n="Оновлене Донесення Гінця Бойової Пісні",s="«Оновлене донесення гінця Бойової Пісні» — завдання Орди зі зв'язку, що поєднує передову оборону Ашенвалю з командирами на кордоні. Донесення, довірене гінцям і новобранцям, описує дедалі більший військовий тиск на розвідників Бойової Пісні, передусім агресію наг, що наступають.",h="«Оновлене донесення гінця Бойової Пісні» — завдання Орди зі зв'язку, що поєднує передову оборону Ашенвалю з...",kw={"донесення гінця","бойова пісня","кадрак","вал мор'шан","наги","завдання"},ang={["faction:Horde"]="На лісовому прикордонні важить кожен воїн, і зв'язок між Пустками й передовими заставами — питання виживання.",["race:Orc"]="Клан Бойової Пісні покладається на завзяття й пильність своїх гінців, щоб утримати землі, здобуті за наказом Вождя Тралла."},sec={{t="Донесення з передової",b="Клан Бойової Пісні тримає по всьому Ашенвалю мережу розвідників і гінців, щоб стежити за довколишніми ворогами й берегти шляхи постачання. Між прикордонними сутичками з вартовими нічних ельфів і суворою природою швидка розвідка — понад усе. Гінці з донесеннями з передової дбають, щоб віддалені гарнізони діяли злагоджено з такими командирами, як Кадрак на Валу Мор'шан."},{t="Загроза наг",b="Орда чекає запеклого опору від нічних ельфів серед дерев, але вартові застав доповідають про дедалі зухваліші напади наг. Ці зміїні загарбники б'ють із водних шляхів і прадавніх руїн, випробовуючи барикади застав і змушуючи захисників відволікатися від лісозаготівель і прикордонних дозорів. Донесення, принесене назад на Вал Мор'шан, б'є на сполох через ці злагоджені напади з води."}},faq={{q="Кому надсилають це донесення?",a="Донесення несуть просто Кадракові, наглядачеві на Валу Мор'шан, на межі Ашенвалю й північних Пусток.",al={"хто отримує донесення","звіт кадрака","куди йде донесення"}},{q="Які загрози згадано в донесенні?",a="Розвідник повідомляє, що застава вистояла під кількома нападами, і наголошує на дедалі більшій загрозі від ворожих наг у сусідніх водах.",al={"що в донесенні","зміст доповіді гінця","напади наг"}},{q="Чому Орда покладається тут на пішохідних гінців?",a="Густе листя, пильні стрільці нічних ельфів і відрізані застави роблять перельоти над частиною Ашенвалю важкими чи надто відкритими. Пішохідні гінці забезпечують швидкий і непомітний зв'язок захищеними стежками.",al={"чому гінці","переказ про гінців бойової пісні","чому не вівернами"}},{q="Хто такі гінці Бойової Пісні?",a="Це розвідники, кур'єри й передові бійці клану Бойової Пісні, яким доручено берегти шляхи постачання й стежити за ворогом на спірних межах лісу.",al={"клан бойової пісні в ашенвалі","хто гінці бойової пісні"}},{q="Де в Ашенвалі нападають наги?",a="Наги влаштували твердині в руїнах уздовж берегів і озер Ашенвалю й часто влаштовують засідки на мандрівників і набіги на сусідні табори.",al={"де наги","наги ашенвалю"}},{q="Яке призначення застави в цих місцях?",a="Застава слугує постом раннього попередження й оборонною опорою: вона не дає ворогам перерізати зв'язок між лісозаготівлями в глибині лісу й Пустками.",al={"чому тут застава","призначення табору орди"}}},fp="21,288,20.419.0,15.446.0,32.153.0,41.157.0,45.206.0,31.170.0,42.139.0,43.172.0"}
P.entries["quest:6546"] = {n="Оновлене Донесення Вершника Бойової Пісні",s="«Оновлене донесення вершника Бойової Пісні» — завдання Орди на доставку, що починається на небезпечних стежках східного Ашенвалю. Самотній розвідник Бойової Пісні довіряє шукачеві пригод важливі відомості про загрози з боку Альянсу поблизу, сатирів, що окопалися в лісі, і наг, що наступають у сусідній Азшарі.",h="«Оновлене донесення вершника Бойової Пісні» — завдання Орди на доставку, що починається на небезпечних...",kw={"донесення вершника","дозорці пісні війни","азшара","наги","сатири","завдання"},ang={["faction:Horde"]="Кожне донесення, що проходить уздовж рубежу Мор'шан, зміцнює хитку опору Орди в буйних лісах Ашенвалю.",["race:Orc"]="Клан Бойової Пісні пишається тим, що стоїть в авангарді, але його розвідники знають: сама відвага не зупинить ворогів, що оточують їх з усіх боків."},sec={{t="Очі на узліссі",b="Східний Ашенваль — спірне прикордоння, де шляхи постачання Орди повсякчас зазнають нападів. Дозорці Пісні Війни тримають пильну завісу по всіх лісах, розвідуючи пересування ворога задовго до того, як нальотники встигнуть ударити по таких заставах, як Вал Мор'шан чи Застава Розщепленого Дерева. Зустріти передового вершника в дозорі — означає опинитися просто на театрі розвідувальних дій, де відомості можуть вирішити, чи втримається укріплення, чи впаде від засідки."},{t="Загрози з усіх обріїв",b="Звіт, складений вершником, малює для Орди похмуру тактичну картину в центральних лісах Калімдору. Окрім повсякчасних сутичок із нічними ельфами та ширшим Альянсом, у східному Ашенвалі кишать хитрі демонічні сатири. На додачу розвідники виявили величезну присутність наг, що розповзаються зруйнованими прибережними землями сусідньої Азшари, і попереджають командирів: Орду майже з усіх боків оточують ворожі сили."}},faq={{q="Що таке Донесення Клану Бойової Пісні?",a="Це розвідувальне донесення, яке написав Передовий Вершник Бойової Пісні, з підсумком розташування ворожих загонів і небезпек краю. У ньому йдеться про загрози від сил Альянсу поблизу, діяльні ковени сатирів на сході Ашенвалю й нещодавно помічені пересування наг в Азшарі.",al={"донесення бойової пісні","що в донесенні","звіт розвідника"}},{q="Хто такий Кадрак?",a="Кадрак — командир Орди на Валу Мор'шан, укріпленій загороді, що стереже північний кордон між Пустками й Ашенвалем. Він приймає розвідників і керує передовими діями в лісі.",al={"хто такий кадрак","де кадрак","здати кадраку"}},{q="Чому згадано наг в Азшарі?",a="Азшара межує безпосередньо зі східним Ашенвалем. Передові вершники стежать за чужими пересуваннями на сусідніх землях, щоб великі вторгнення не заскочили фланги Орди, поки вона воює з нічними ельфами.",al={"зв'язок наг з азшарою","чому згадано азшару","загроза наг азшари"}},{q="Чому схід Ашенвалю такий небезпечний для Орди?",a="Край затиснутий між діяльними загонами Альянсу, прадавніми руїнами сатирів, просякнутими демонічною скверною, і дикими лісовими звірами, тож гінці й патрулі Орди вразливі до засідок з усіх боків.",al={"чому схід ашенвалю небезпечний","загрози ашенвалю","загроза сатирів"}},{q="Хто такі Дозорці Пісні Війни?",a="Дозорці Пісні Війни, або передові вершники, — це передовий загін і розвідувальна кіннота клану Бойової Пісні в Ашенвалі: вони стежать за пересуваннями нічних ельфів, прикривають лісозаготівельні табори й бережуть торгові шляхи.",al={"що таке передові вершники","розвідники бойової пісні","переказ про передових"}},{q="Чому вершник не може доставити донесення сам?",a="Вершникові доручено й далі стежити за стежкою, щоб бачити, як розвиваються ворожі пересування. Якщо він покине свій спостережний пункт, передова осліпне перед несподіваним наступом Альянсу чи сатирів.",al={"чому я доставляю донесення","чому не доставить сам"}}},fp="23,283,26.482.0,24.477.0,27.264.0,14.230.0,38.209.0,56.218.0,30.187.0,50.208.0"}
P.entries["quest:6547"] = {n="Оновлене Донесення Розвідника Бойової Пісні",s="«Оновлене донесення розвідника Бойової Пісні» — завдання Орди зі зв'язку, що поєднує командирів застав на кордонах Ашенвалю з передовими розвідниками, які стежать за спірним лісом. Несучи стратегічні накази Кадрака, гінці дбають, щоб клан Бойової Пісні пильно стежив за нічними ельфами, які влаштовують засідки. Завдання показує, як хитко й ворожо Орда тримається на щойно здобутих землях.",h="«Оновлене донесення розвідника Бойової Пісні» — завдання Орди зі зв'язку, що поєднує командирів застав на...",kw={"донесення розвідника","бойова пісня","кадрак","ашенваль","прикордоння","завдання"},ang={["faction:Horde"]="Кожен гонець, що несе накази між Кадраком і віддаленими розвідниками, допомагає вберегти опору Орди в Ашенвалі від невпинних засідок нічних ельфів.",["race:NightElf"]="Розвідники Бойової Пісні, що причаїлися на кордонах, — це тривале осквернення священних лісів Елуни, яке вартові прагнуть викорінити.",["race:Orc"]="Спадщину клану Бойової Пісні визначає його завзяття в Ашенвалі: він здобуває життєво потрібну деревину, попри ворожість землі та її прадавніх захисників."},sec={{t="Очі в тіні",b="Прикордоння Ашенвалю лишається пороховою бочкою, де жодна сторона не поступається й на крок. Сили Орди під проводом Кадрака дуже покладаються на розпорошених розвідників Бойової Пісні на небезпечних заставах: ті стежать за пересуваннями нічних ельфів і бережуть спірні шляхи постачання. Сам ліс дає природне укриття потайним вартовим Альянсу, тож регулярні звіти й письмові донесення вкрай важливі, щоб відокремлених розвідників не відрізали й не розгромили."},{t="Утримати землю",b="Для клану Бойової Пісні кожен клапоть вирубаного чи зайнятого лісу оплачено кров'ю. Розвідники невпинно стежать за відплатними набігами нічних ельфів, що прагнуть повернути ліси. Накази Кадрака запевняють авангард, що підкріплення й злагоджені дії не припиняються, і розвідники можуть доповісти, що їхні оборонні заходи діють, попри безупинний опір ельфів."}},faq={{q="Хто такий Кадрак?",a="Кадрак — командир Орди на межі Пусток і Ашенвалю. Він керує розвідувальними місіями, обороною кордону й постачанням для клану Бойової Пісні, що просувається в прадавній ліс.",al={"кадрак","хто такий кадрак","роль кадрака"}},{q="Чому розвідники Бойової Пісні так остерігаються нічних ельфів?",a="Нічні ельфи легко зливаються з тінями лісів своїх предків і раптово нападають на патрулі Орди із засідки. Клан Бойової Пісні рубає ліс і заселяє землю, яку ельфи вважають священною, тож розвідникам постійно загрожують смертельні несподівані атаки.",al={"чому боятися нічних ельфів","нічні ельфи в тінях","небезпека ельфів для розвідника"}},{q="Чому за Ашенваль точиться боротьба?",a="Орді потрібні деревина й ресурси Ашенвалю, щоб будувати Оргріммар і забезпечувати поселення в посушливих Пустках і Дуротарі. Корінні нічні ельфи вважають ліс священною землею й завзято воюють, щоб вигнати орківських лісорубів і гарнізони.",al={"чому воюють за ашенваль","війна за ашенваль","конфлікт орди в ашенвалі"}},{q="Яка роль клану Бойової Пісні тут?",a="Клан Бойової Пісні очолює поширення Орди й добування ресурсів в Ашенвалі. Ще під час Третьої війни його привів у ліси Ґром Хеллскрім, і відтоді клан міцно тут закорінився: тримає лісозаготівельні табори й безперестанку б'ється з Вартовими.",al={"клан бойової пісні в ашенвалі","роль бойової пісні"}},{q="Куди йде це донесення, коли дістанеться розвідника?",a="Отримавши оновлені вказівки Кадрака, розвідник надсилає назад звістку про свої успіхи у відбитті ельфійських контратак, щоб провід Орди добре знав, наскільки стійка передова.",al={"хто отримує донесення","звіт кадрака","результат донесення розвідника"}},{q="Чи вдаються плани Орди в Ашенвалі на цей момент?",a="Розвідники на передовій вважають свою оборону успішною: вони втримують укріплені позиції й відбивають удари ельфів, але край і далі лишається запеклим полем бою, де жодна сторона не має цілковитої переваги.",al={"чи орда перемагає в ашенвалі","поступ бойової пісні"}}},fp="20,404,19.450.0,18.405.0,14.224.0,57.279.0,35.261.0,37.283.0,51.212.0,60.242.0"}
P.entries["quest:6548"] = {n="Помсти за моє селище",s="Макаба Флетгуф ледве вижив у жорстокому нападі, коли розбійники з клану Ґрімтотем налетіли на його селище на південному сході Гір Кам'яного Кігтя. Відрізаний від родичів, серед загиблих, він просить мандрівників з Орди завдати удару у відповідь по табору головорізів-Ґрімтотемів і їхніх найманців і помститися за полеглий народ.",h="Макаба Флетгуф ледве вижив у жорстокому нападі, коли розбійники з клану Ґрімтотем налетіли на його селище на...",kw={"помсти за моє селище","макаба флетгуф","ґрімтотем","кайрн бладгуф","помста","гори кам'яного кігтя"},ang={["faction:Horde"]="Орда покладається на відкриті й безпечні перевали між Пустками та Горами Кам'яного Кігтя. Свавільна банда Ґрімтотемів, що вбиває мандрівників і нападає на союзні селища, загрожує шляхам постачання Вождя через гори.",["race:Tauren"]="Зрада клану Ґрімтотем найболючіше вдаряє по мандрівниках-тауренах. Бачити, як шу'гало вирізають свої ж, — гірке нагадування про розкол між кланами й про небезпеку, яку Ґрімтотеми становлять для об'єднаного народу Кайрна."},sec={{t="Кров серед круч",b="Неподалік кордону між Пустками й червонокам'яними перевалами Гір Кам'яного Кігтя стоїть Макаба Флетгуф — єдиний, хто вцілів у жорстокій різанині. Розбійники під темними стягами клану Ґрімтотем налетіли без попередження й вирізали майже всіх у селищі. Хоч Макаба люто оборонявся й поклав кількох нападників, зрештою йому довелося сховатися, не маючи нічого, крім власного життя й люті."},{t="Загроза Ґрімтотемів",b="Ґрімтотеми здавна були непокірною, агресивною скалкою в оці племен тауренів, об'єднаних під проводом Верховного Вождя Кайрна Бладгуфа. На відміну від мирних кочівників, що мандрують Малгором, бойові загони Ґрімтотемів часто наймають безжальних головорізів і найманців, ладних на все, щоб загарбувати землі й нападати на відрізані поселення. Для Макаби тепер нічого не важать ні переговори, ні кревна спорідненість племен: лише кров за кров може вгамувати його горе."}},faq={{q="Хто дав це завдання?",a="Його дає Макаба Флетгуф, таурен, що вцілів і отаборився біля південно-східного перевалу в Гори Кам'яного Кігтя. Він пережив жорстокий розгром свого селища кланом Ґрімтотем і прагне відплати нападникам.",al={"хто дає завдання","макаба флетгуф","хто такий макаба"}},{q="Чому Ґрімтотем нападають на інших тауренів?",a="Клан Ґрімтотем так і не прийняв по-справжньому єдності Орди чи мирного задуму Кайрна Бладгуфа. Затято ревниві до своєї землі, ворожі до чужинців і агресивні, вони відкрито грабують суперницькі поселення, вбивають сторонніх і за допомогою озброєних головорізів і найманців прагнуть панувати над краями на кшталт Кам'яного Кігтя.",al={"чому ґрімтотеми ворожі","таурени нападають на тауренів","переказ про клан ґрімтотем"}},{q="Де нападники Ґрімтотем?",a="Головорізи й найманці Ґрімтотем стоять табором трохи на захід від Макаби Флетгуфа на південному сході Кам'яного Кігтя, серед кам'янистих пагорбів над перевалом.",al={"де мисливці ґрімтотем","табір ґрімтотем","де знайти розбишак"}},{q="Хто такі найманці Ґрімтотем?",a="Клан Ґрімтотем часто доповнює власних воїнів найманими безжальними бійцями й продажними мечами, щоб мати досить сили тероризувати й захоплювати відокремлені поселення.",al={"найманці","найманці ґрімтотем","хто такі найманці"}},{q="Що буде після цього завдання?",a="Коли ви поріжете передових головорізів і найманців, Макаба попросить вас ударити по ватажкові різанини, Ґрундіґу Дарклауду, у наступному завданні «Убий Ґрундіґа Дарклауда».",al={"наступне завдання","що після помсти за селище","убити ґрундіґа дарклауда"}},{q="Де було селище Макаби?",a="Селище Макаби — відокремлений табір тауренів біля прикордонних перевалів на південному сході Кам'яного Кігтя. Набіг Ґрімтотем знищив його вщент, і Макаба — один із небагатьох відомих, хто вцілів.",al={"селище флетгуфа","де було селище","яке селище знищили"}}},fp="17,328,18.429.0,20.448.0,20.222.0,45.297.0,42.185.0,34.212.0,30.187.1,35.214.0"}
P.entries["quest:6561"] = {n="Лиходійство в Блекфатомі",s="«Лиходійство в Блекфатомі» — відчайдушне благання смертельно пораненого вояка Срібного Світанку, що опинився в пастці всередині Чорноглибинних Печер. Шукачі пригод Орди мають покінчити із сутінковим володарем Келрісом — ватажком культу, який влаштовує моторошні криваві жертвоприношення давньому чудовиську в руїнах унизу.",h="«Лиходійство в Блекфатомі» — відчайдушне благання смертельно пораненого вояка Срібного Світанку, що опинився...",kw={"келріс","молот присмерку","чорноглибинні печери","аку'май","срібний світанок","башана рунототем","таелрід"},ang={["class:Druid"]="Осквернення давнього місячного колодязя нічних ельфів культистами-поклонниками Порожнечі та нагами — болісна рана на тілі природного й духовного прихистку Калімдору.",["class:Shaman"]="Неспокій, який посіяли Келріс та Аку'май, ображає рівновагу стихій: чисті підземні води обертаються на гниле ложе тіні й жертвоприношень.",["faction:Horde"]="Для Орди така угода з розвідником Срібного Світанку — рідкісний випадок спільного інтересу перед лицем космічної пошесті, що приносить ранню прихильність Світанку.",["race:Tauren"]="Башана Рунтотем бачить у поразці Келріса важливий захист Земної Матері: світ очищено від мерзоти, що хотіла кинути природний лад у первісний хаос."},sec={{t="Останній відчайдушний опір",b="Розвідник Срібного Світанку Таелрід дістався підземного храму на узбережжі Ашенвалю й натрапив на жахіття, куди страшніші за звичайні набіги наг. Поранений і знесилений у печерах, нічний ельф розуміє, що сам місії не завершить. Щоб його розвідка не загинула разом із ним, він звертається до кожного звитяжця Орди, який наважиться вдарити по темних проводирях, що панують у затоплених залах."},{t="Жертви для глибин",b="Мета завдання — сутінковий володар Келріс, очільник культистів Молота Присмерку, які окопалися в зруйнованому Храмі Місяця. У союзі з місцевими нагами Келріс править темні обряди над оскверненим місячним колодязем і згодовує живих полонених Аку'маю — ненажерній гідрі, звірові Древніх Богів, — у божевільній гонитві за космічною силою та первісним хаосом."},{t="Звістка до Тандер Блафа",b="Срібний Світанок свого часу вважав Келріса загиблим або зниклим, тож підтвердити його смерть украй важливо. Замість того щоб гнати героїв аж до людських земель, Таелрід велить віднести доказ загибелі ватажка культу Башані Рунтотем на Узвишшя Старійшин у Тандер Блафі. Башана, глибоко пов'язана з природною рівновагою Земної Матері, шанує цю перемогу: вона загасила мерзенну порчу, що прагнула втягнути Калімдор у первісну руїну."}},faq={{q="Хто такий сутінковий володар Келріс?",a="Келріс — ватажок сектантів Молота Присмерку, що захопили Чорноглибинні Печери. Срібний світанок вважав його мертвим чи зниклим, а він тим часом потай набирався сили, приносячи живі жертви прадавній гідрі Аку'май в оскверненому місячному колодязі.",al={"келріс","хто такий келріс","сутінковий володар келріс"}},{q="Що член Срібного світанку робить у Чорноглибинних Печерах?",a="Срібний Вартовий Таелрід прийшов дослідити загрозу, що зростала в зруйнованому храмі нічних ельфів. Здоланий мешканцями печер і смертельно ослаблений, він застряг там і мусить покладатися на шукачів пригод, щоб ті виконали його обов'язок і знищили Келріса.",al={"страж срібного світанку телріт","чому телріт тут","срібний світанок у чорноглибинних печерах"}},{q="Що таке Аку'май?",a="Аку'май — жахлива прадавня багатоголова гідра, яку вважають первісним слугою Древніх Богів. Вона спала під затонулими руїнами й прокинулася, коли глибинна підземна скверна отруїла священні води храму, а тепер пожирає полонених, яких їй приводить Молот Присмерку.",al={"аку'май","хто такий аку'май","переказ про аку'мая"}},{q="Чому завдання треба здати Башані Рунтотем?",a="Таелрід скеровує поборників Орди до Башани Рунтотем на Узвишші Старійшин у Тандер Блафі. Башана, охоронниця рівноваги Земної Матері, підтримує зв'язок із тими, хто протистоїть прадавньому злу, і вважає поклоніння Келріса Древнім Богам огидною пошестю для Калімдору.",al={"башана рунтотем","чому тандер блаф","де здати лиходійство в блекфатомі"}},{q="Що сталося з руїнами Чорноглибинних Печер?",a="Колись давно цей підземний комплекс був священним храмом місячної богині Елуни. Катастрофічні потрясіння й прадавня темрява, що просочилася з надр, осквернили величний місячний колодязь, і затонулі святилища захопили наги й сектанти кінця світу для свого темного володаря Аку'май.",al={"історія чорноглибинних печер","руїни храму елуни","чому печери осквернені"}},{q="Чого прагне тут культ Молота Присмерку?",a="Молот Присмерку прагне, поклоняючись Древнім Богам, повернути світ у добу первісного хаосу. Келріс шукає особистої влади через темне єднання й кидає невинних у глибини, щоб здобути прихильність прадавніх сутностей.",al={"мотиви молота присмерку","чому культ у печерах","цілі келріса"}}},fp="20,291,22.427.0,22.381.0,21.422.1,28.273.0,54.252.0,16.279.0,43.278.0,48.281.0,52.231.0"}
P.entries["quest:6562"] = {n="Клопоти в Глибинах",s="«Клопоти в Глибинах» — заклик про допомогу, що летить із Гір Кам'яного Кігтя до далеких берегів Ашенвалю. Цунаман посилає шукачів пригод Орди до троля-вченого Дже'ню Санкреа на Заставу Зорам'гар і попереджає, що узбережжям блукають небезпечні сили.",h="«Клопоти в Глибинах» — заклик про допомогу, що летить із Гір Кам'яного Кігтя до далеких берегів Ашенвалю.",kw={"дже'ню санкреа","цунаман","застава зорам'гар","зорамське узмор'я","чорноглибинні печери","ашенваль"},ang={["class:Shaman"]="Неспокій під хвилями Зорамського Узмор'я загрожує рівновазі місцевих духів води, тож очистити цю гнилизну зможе лише той, хто має духовне прозріння.",["faction:Horde"]="Утримати Заставу Зорам'гар украй важливо, щоб захистити західний фланг Калімдору і від сил нічних ельфів, і від жахіть узбережжя.",["race:Troll"]="Відгукнувшись на поклик Дже'ню Санкреа, родичі з племені Темного Списа дістають чудову нагоду допомогти одному з найкращих своїх учених розкрити давні таємниці Калімдору."},sec={{t="Поклик до узбережжя",b="Серед посушливих скель Гір Кам'яного Кігтя Цунаман розуміє: темний гул на півночі вимагає уваги. Він доручає вправним мандрівникам Орди перейти до Ашенвалю — прадавнього лісу нічних ельфів — і зв'язатися з Дже'ню Санкреа. Той стоїть на Заставі Зорам'гар на далекому західному краю, відомому як Зорамське Узмор'я, і зіткнувся з дедалі грізнішою небезпекою, з якою без сторонньої допомоги не впоратися."},{t="Дорога до Зорамського Узмор'я",b="Дістатися західного берега Ашенвалю для мандрівників Орди — аж ніяк не дрібниця. Хоч крізь перевали Кручі Вітрорізу, де хазяйнують гобліни, хоч рушаючи на північ із Пусток — усе одно доведеться заходити у ворожий ліс, який запекло стережуть Вартові нічних ельфів. Далеко за густими кронами, на омитому бурями березі Зорамського Узмор'я, самотня застава чіпляється за життя й вдивляється в темні води неподалік."},{t="Шепіт під хвилями",b="На березі Дже'ню Санкреа відкриває, що корінь лиха — у підземному храмі Чорноглибинних Печер. Під товщею води зібралися давня порча, мерзенні водяні елементалі й культисти Молота Присмерку, які кличуть стародавнє зло назад у світ. Дже'ню покладається на звитяжців, що прибувають на узбережжя: лише вони можуть спуститися під воду й протистати первісному жахові, розбудженому в затоплених залах."}},faq={{q="Хто дає завдання «Клопоти в Глибинах»?",a="Завдання дає Цунаман у Горах Кам'яного Кігтя. Він розуміє, що союзникам на узбережжі Ашенвалю потрібне підкріплення, і скеровує мандрівних шукачів пригод Орди до моря.",al={"хто дає клопоти в глибинах","видавець завдання","цунаман"}},{q="Де знайти Дже'ню Санкреа?",a="Дже'ню Санкреа перебуває на Заставі Зорам'гар на узбережжі Зорам, на далекому західному березі Ашенвалю.",al={"де дже'ню","місце дже'ню санкреа","застава зорам'ґар"}},{q="Як дістатися з Кам'яного Кігтя до Застави Зорам'гар?",a="Можна йти на північний схід через Кручу Вітрорізу в Ашенваль або зробити гак на схід через Пустки й увійти в ліс із півдня. Із центрального Ашенвалю прямуйте точно на захід, доки не вийдете до відкритих вод узбережжя Зорам.",al={"шлях до ашенвалю","як дістатися зорамського узмор'я","дорога з кам'яного кігтя в ашенваль"}},{q="Які клопоти досліджує Дже'ню?",a="Дже'ню Санкреа стежить за сусідніми руїнами Чорноглибинних Печер, де сектанти й зіпсовані водяні істоти будять прадавні жахіття під поверхнею.",al={"що відбувається на зорамському узмор'ї","чому дже'ню потрібна допомога"}},{q="Яке завдання йде після «Клопотів у Глибинах»?",a="Розмова з Дже'ню Санкреа одразу веде до завдання «Сутність Аку'Май», яке відправляє шукачів пригод у Чорноглибинні Печери по сапфірово-синю сутність стихій.",al={"наступне завдання","продовження клопотів у глибинах"}},{q="Чому шлях через Ашенваль вважають небезпечним?",a="Ашенваль — володіння нічних ельфів, які запекло опираються будь-якому вторгненню Орди. Мандрівники в лісі ризикують наткнутися на ворожих вартових і невловимих засідників.",al={"небезпека ашенвалю","загроза нічних ельфів"}}},fp="20,265,22.435.0,24.425.0,24.420.1,41.195.0,32.121.0,51.230.0,37.161.0,40.162.0,57.194.0"}
P.entries["quest:6563"] = {n="Сутність Аку'Май",s="Дже'ню Санкреа на Заставі Зорам'гар помітив, що наги з Чорноглибинних Печер видобувають у підземеллях могутні сапфірові друзи. Стурбований їхніми магічними властивостями та енергією стихії води, шаман доручає шукачам пригод Орди забрати самоцвіти, перш ніж їх обернуть на зло.",h="Дже'ню Санкреа на Заставі Зорам'гар помітив, що наги з Чорноглибинних Печер видобувають у підземеллях могутні...",kw={"сапфіри аку'мая","дже'ню санкреа","наги","застава зорам'гар","духи води","чорноглибинні печери"},ang={["class:Shaman"]="Те, що Дже'ню Санкреа прочитав у кристалах, вказує на неспокійних духів води, ув'язнених у них, — тихе попередження, що під храмом спотворюють сили стихій.",["faction:Horde"]="Опорний пункт Орди на Заставі Зорам'гар у небезпеці; не давши сусідським нагам заволодіти сирою магічною силою, ви допоможете вберегти табір на березі.",["race:Troll"]="Дже'ню Санкреа — уважний містик із племені Темного Списа, який покладається на спілкування з духами та мудрість предків, щоб розібратися в дивних загрозах Калімдору."},sec={{t="Загроза в глибинах",b="На оповитих туманом берегах Зорамського Узмор'я шаман із племені Темного Списа Дже'ню Санкреа наглядає за давніми руїнами калдореїв, які тепер заполонили зловісні сили. Глибоко в затоплених залах Чорноглибинних Печер наги взялися добувати яскраві сапфірові нарости, що проростають на вологих стінах. Відчуваючи, що зміїсті загарбники хочуть приборкати цю мінливу силу, Санкреа прагне перехопити здобич, доки їхні задуми не здійснилися."},{t="Духи води й тайна сила",b="Сапфіри Аку'мая — аж ніяк не звичайні самоцвіти: вони бринять відлунням стихії, і в них тримаються духи води. У руках умілих чаклунів такі провідники можуть живити небезпечні тайні обряди чи посилювати вплив тіньової гідри Аку'мая, чия темна присутність просочує весь підземний храм. Якщо забрати ці друзи, наги втратять безцінний реагент, а узбережжя вбережеться від некерованої магії стихій."}},faq={{q="Хто дає це завдання?",a="Завдання дає Дже'ню Санкреа, шаман-троль Темного Спису із Застави Зорам'гар на узбережжі Зорам у північно-західному Ашенвалі.",al={"хто дає завдання","хто починає сутність аку'май","де дже'ню санкреа"}},{q="Навіщо нагам Сапфіри Аку'Май?",a="Їхній задум поки невідомий, але сапфіри мають потужну енергію стихії води й чисту магічну силу, тож для чаклунства наг це надзвичайно небезпечні реагенти.",al={"навіщо нагам сапфіри","для чого кристали","призначення сапфірів"}},{q="Де знайти скупчення сапфірів?",a="Вони вкривають стіни й дно печер у зовнішніх тунелях і затоплених проходах Чорноглибинних Печер, одразу за зруйнованим підземним входом на узбережжі Зорам.",al={"де знайти сапфіри","місце сапфірів аку'май","появи кристалів"}},{q="Що таке Аку'май?",a="Аку'май — жахлива триголова гідра, що живе глибоко в затоплених руїнах храму. Сектанти Молота Присмерку їй поклоняються, а інші бояться її як улюбленого вихованця Древніх Богів.",al={"хто такий аку'май","що таке аку'май","аку'май"}},{q="Чи треба вбивати когось із ватажків підземелля для цього завдання?",a="Ні. Скупчення сапфірів ростуть на стінах печер у перших затоплених тунелях, ще до зустрічі з головними ватажками Чорноглибинних Печер.",al={"чи потрібна повна група","чи можна сапфіри соло","вимога босів"}},{q="Чи пов'язане це завдання з іншими історіями?",a="Так. Воно йде після «Клопотів у Глибинах» і є частиною розслідування Дже'ню Санкреа про темряву й діяльність сектантів, що загніздилися в Чорноглибинних Печерах.",al={"ланцюжок завдань","попередні завдання","клопоти в глибинах"}}},fp="22,287,22.461.0,30.455.0,21.143.0,46.181.0,38.169.0,16.183.0,52.144.0,47.168.0"}
P.entries["quest:6564"] = {n="Вірність Прадавнім Богам",s="«Вірність Прадавнім Богам» — завдання Орди, що починається з розмоклого послання, знайденого в наг у Чорноглибинних Печерах. Віднісши записку Дже'ню Санкреа на Заставу Зорам'гар, ви розкриваєте зловісну змову з обрядом, що розгортається глибоко в затоплених руїнах Чорноглибинних Печер.",h="«Вірність Прадавнім Богам» — завдання Орди, що починається з розмоклого послання, знайденого в наг у...",kw={"вірність прадавнім богам","древні боги","чорноглибинні печери","аку'май","лорґус джетт","молот присмерку","завдання"},ang={["class:Shaman"]="Підкорення духів водяних елементалів у обрядових кристалах — тяжке збочення природної рівноваги, яке треба негайно виправити.",["faction:Horde"]="Викрита записка Лорґуса Джетта допомагає вберегти Заставу Зорам'гар від Молота Присмерку та його союзників-наг, що загрожують опорі Орди на західному узбережжі Ашенвалю.",["race:Troll"]="Допомагаючи своєму родичеві з Темного Спису Дже'ню Санкреа, ви викриваєте прадавні вселенські сутності, чиє повернення загрожувало б кожному племені Азерота."},sec={{t="Нашкрябана заява",b="Б'ючись із нагами в Чорноглибинних Печерах, розвідники Орди знаходять вологу зім'яту записку, списану гарячковим почерком. Нашкрябаний пергамент містить настанови для жриць наг: їм наказано збирати кристали водяних елементалів. Це зовсім не випадкове мародерство — кристали збирають, щоб живити закликання водних чаклунів-наг, які гуртують стихійні сили заради значно темнішої мети."},{t="Шепіт глибин",b="Знайдені накази розкривають, що наги прагнуть використати стихійну силу кристалів, щоб умилостивити й цілком закликати Аку'мая — жахливу гідру, улюбленицю прадавніх вселенських володарів. Записка зухвало проголошує, що це провістить повернення «найвеличнішої доби» світу — доісторичного панування Древніх Богів. Отримавши пергамент на Заставі Зорам'гар, містик Темного Спису Дже'ню Санкреа впізнає автора цієї змови — сектанта Молота Присмерку Лорґуса Джетта."}},faq={{q="Що таке Волога Записка?",a="Волога Записка — знайдені накази, які написав сектант Молота Присмерку Лорґус Джетт. У них жрицям наг велено збирати кристали, сповнені сили стихій, щоб посилити своїх аквамантів і викликати жахливого слугу Аку'май.",al={"волога записка","що в записці","переказ про записку"}},{q="Хто такий Дже'ню Санкреа?",a="Дже'ню Санкреа — провидець і вчений із тролів Темного Спису на Заставі Зорам'гар в Ашенвалі. Як представник Земляного Кільця, він досліджує розлад стихій і прадавні загрози, що постають із сусідніх руїн Чорноглибинних Печер.",al={"дже'ню санкреа","хто такий дже'ню","видавець застави зорам"}},{q="Хто такий Лорґус Джетт?",a="Лорґус Джетт — шаман-людина з культу Молота Присмерку, що діє в Чорноглибинних Печерах, де сектанти в союзі з нагами. Він наглядає за добуванням кристалів стихій, щоб посилити ритуали наг і знову пробудити темні прадавні жахіття.",al={"лорґус джетт","хто написав записку","ватажок наг зорам"}},{q="Що таке Аку'май?",a="Аку'май — велетенська триголова гідра, що живе в затоплених глибинах Чорноглибинних Печер. Тісно пов'язана з первісною темрявою Древніх Богів, ця істота шанована і культом Молота Присмерку, і нагами Чорноглибинних Печер.",al={"аку'май","хто такий аку'май","переказ про аку'мая"}},{q="Навіщо наги збирають водяні кристали?",a="Духи водяних елементалів, ув'язнені в кристалах, дають чисту силу аквамантам наг. Висмоктуючи цю магію стихій, вони сподіваються задобрити Аку'май і зібрати досить сили, щоб наблизити повернення Древніх Богів.",al={"навіщо наги кристали","стихійні кристали наг","кристали аквамантів"}},{q="Куди веде цей ланцюжок завдань?",a="Доставка записки Дже'ню Санкреа одразу веде до наступного доручення — вистежити й стратити Лорґуса Джетта, щоб зірвати ритуальні задуми культу в Чорноглибинних Печерах.",al={"що після вірності прадавнім богам","вірність прадавнім богам частина 2","наступне завдання"}}},fp="26,282,23.413.0,20.494.1,22.235.0,22.236.0,19.248.0,16.251.0,43.226.0,33.186.1"}
P.entries["quest:6565"] = {n="Вірність Прадавнім Богам",s="«Вірність Прадавнім Богам» — завдання Орди: шукачі пригод мають знищити Лорґуса Джетта в глибинах Чорноглибинних Печер. Його доручає провидець із племені Темного Списа Дже'ню Санкреа на Заставі Зорам'гар, щоб зірвати плани культистів Молота Присмерку, які прагнуть пробудити давні сили руйнування. Убивство Лорґуса — прямий удар по таємній діяльності культу під узбережжям Ашенвалю.",h="«Вірність Прадавнім Богам» — завдання Орди: шукачі пригод мають знищити Лорґуса Джетта в глибинах...",kw={"лорґус джетт","молот присмерку","древні боги","дже'ню санкреа","чорноглибинні печери","застава зорам'гар"},ang={["class:Shaman"]="Молот Присмерку прагне розв'язати лють стихій на служіння хаотичним Древнім Богам, тож викорінити його — першочергова справа для тих, хто разом із Земляним Кільцем присягнув берегти рівновагу стихій.",["faction:Horde"]="Знищивши Лорґуса Джетта, ви убезпечите околиці Застави Зорам'гар і захистите відрізаний табір Орди на узбережжі Ашенвалю від підступних задумів культистів.",["race:Troll"]="Допомагаючи Дже'ню Санкреа, ви вшановуєте мудрість шанованого провидця Темного Списа, який далеко від Островів Відлуння боронить первісних духів Азероту."},sec={{t="Загроза під Зорам'гаром",b="Застава Орди Зорам'гар, що примостилася на березі Ашенвалю, неспокійно стежить за Чорноглибинними Печерами. Затоплений храмовий комплекс став розсадником темного чаклунства: його заполонили наги, спотворені звірі й закутані в плащі фанатики Молота Присмерку. Дже'ню Санкреа, провидець Земляного Кільця, що стоїть на узбережжі, розуміє: культисти не шанують ні природної рівноваги, ні духів землі. Натомість вони присягають служити Древнім Богам — потворним сутностям хаосу, переможеним у прадавні часи, чий лиховісний дотик досі відчутний у забутих куточках Азероту."},{t="Кінець Лорґуса Джетта",b="Дже'ню доручає звитяжцям Орди проникнути в підземні руїни й вистежити Лорґуса Джетта, одного з ключових ватажків культу. Лорґус діє глибоко в кам'яних переходах між залами велетенської черепахи Ґаму-Ри та водяного елементаля Барона Аквеніса. Сам Дже'ню надто кволий, щоб іти в сиру темряву, тож смерть Лорґуса вкрай потрібна, аби обірвати темні обряди, які культист затівав під хвилями Ашенвалю."},{t="Відвернути хаос",b="Зі смертю Лорґуса Джетта нагальну загрозу обрядів для узбережжя стримано, але Дже'ню визнає, що Молот Присмерку далеко не викорінено. Тихе проникнення культу в давні святі місця свідчить про ширшу, підступну небезпеку, яка прагне ні багато ні мало повного повернення Древніх Богів. Для Орди в Зорам'гарі смерть Лорґуса — це дорогоцінний час, виграний у ворога, що ховається в тінях світу."}},faq={{q="Хто такий Лорґус Джетт?",a="Лорґус Джетт — один із чільних ватажків сектантів Молота Присмерку, що осіли в Чорноглибинних Печерах. Він керує обрядами культу, які мають наблизити повернення й панування Древніх Богів.",al={"лорґус джетт","хто такий лорґус","переказ про лорґуса джетта"}},{q="Де в Чорноглибинних Печерах знайти Лорґуса Джетта?",a="Лорґус Джетт патрулює затоплені коридори Чорноглибинних Печер, а саме переходи між залою Ґаму-Ра й вівтарем Барона Аквеніса.",al={"місце лорґуса джетта","де лорґус","знайти лорґуса джетта"}},{q="Хто такий Дже'ню Санкреа?",a="Дже'ню Санкреа — провидець із тролів Темного Спису, пов'язаний із Земляним Кільцем; він стоїть на Заставі Зорам'гар на узбережжі Зорам в Ашенвалі й стежить за розладом стихій і скверною в Чорноглибинних Печерах.",al={"дже'ню санкреа","хто дає вірність прадавнім богам","дже'ню"}},{q="Чому Дже'ню не байдужий Молот Присмерку?",a="Як провидець, що прагне збагнути природу й рівновагу стихій, Дже'ню бачить у Молоті Присмерку загрозу самому існуванню світу. Культ служить Древнім Богам — хаотичним прадавнім сутностям, чиє повернення зруйнувало б гармонію світу.",al={"чому битися з молотом присмерку","земляне кільце прадавні боги"}},{q="Хто такі Древні Боги?",a="Древні Боги — первісні істоти хаосу й руйнування, що панували над Азеротом у далекому минулому, доки їх не здолали й не поховали. Культ Молота Присмерку відкрито їм поклоняється й змовляється зламати їхні печаті та повернути їхнє згубне владарювання.",al={"переказ про прадавніх богів","хто такі прадавні боги","істоти хаосу"}},{q="Чому Дже'ню Санкреа не може сам убити Лорґуса Джетта?",a="Дже'ню визнає, що надто кволий і слабкий, щоб сам-один подолати небезпеки Чорноглибинних Печер, тож покладається на вправних поборників Орди, а сам із застави стежить за збуреннями в царині духів і стихій.",al={"чому дже'ню не йде","чи дже'ню слабкий"}}},fp="26,413,28.592.0,18.482.0,17.443.1,19.195.0,52.170.0,22.217.0,49.232.0,22.254.0,50.224.0"}
P.entries["quest:6571"] = {n="Припаси Бойової Пісні",s="«Припаси Бойової Пісні» — масштабне завдання Орди з постачання, яке дає Лок Окарр на Заставі Розщепленого Дерева. Щоб Лісозаготівельний Табір Бойової Пісні працював, треба повернути важливе лісорубське спорядження, розкидане по ворожих землях фурболгів і сатирів, а також забрати вантажі з далеких гоблінських портів.",h="«Припаси Бойової Пісні» — масштабне завдання Орди з постачання, яке дає Лок Окарр на Заставі Розщепленого...",kw={"припаси бойової пісні","лок окарр","линви","олія","пиляльні леза","сокири","завдання"},ang={["faction:Horde"]="Поширення Орди в Дуротарі цілком залежить від деревини, яку здобуває клан Бойової Пісні. Повертаючи ці знаряддя, ви безпосередньо зміцнюєте підвалини Оргріммара.",["profession:Engineering"]="Гоблінські складники цього вантажу показують, на якому важливому механічному ланцюгу постачання — від пиляльних лез Піксель до мастила для парових двигунів — тримається вирубка прадавніх лісів.",["race:Orc"]="Шанувати спадщину клану Бойової Пісні в Ашенвалі — означає тримати його сокири гострими, а табори забезпеченими, попри безупинні напади лісових мешканців."},sec={{t="Хай пилки крутяться",b="Похід клану Бойової Пісні за прадавньою деревиною Ашенвалю потребує безупинного потоку важких знарядь. Інтенданти Орди на Заставі Розщепленого Дерева повсякчас стикаються з перебоями в постачанні. Лок Окарр відповідає за те, щоб лісозаготівельний табір мав усе потрібне, але місцеві вантажі розсипалися під нападами місцевих звірів і демонічних сектантів, і робота лишилася без найважливішого спорядження."},{t="Розірваний ланцюг постачання",b="Здобути потрібне обладнання — справжнє випробування, що охоплює чималу частину Калімдору й сягає навіть за море. Циркулярні пиляльні леза чекають у гоблінки-кур'єрки Піксель просто на Заставі Розщепленого Дерева, а скриню важких сокир доведеться забрати в Начальника Пристані Лозґіла аж у Буті Бей. Решту необхідного доведеться вирвати просто з рук ворогів: міцні лісорубські линви захопили ворожі фурболги Гнилолісу й Будякохутрі, а бочки машинної олії Бойової Пісні викрали сатири Нічного Потоку, Сатирнаару й Ксавіана, щоб живити свої блюзнірські обряди."}},faq={{q="Які Припаси Бойової Пісні потрібні?",a="Локові Окарру потрібні чотири важливі речі: партія Пиляльних Лез Бойової Пісні, яку тримає в себе гоблінка Піксель, ящик Сокир Бойової Пісні, відправлений до Буті Бею, міцна Линва Лісоруба, яку поцупили місцеві фурболги, і бочки Олії Бойової Пісні, вкрадені сатирами Ашенвалю.",al={"список припасів бойової пісні","які предмети потрібні","потрібні припаси"}},{q="Хто такий Лок Окарр?",a="Лок Окарр — орк із Застави Розщепленого Дерева, що відповідає за доставку матеріалів до Лісозаготівельного Табору Бойової Пісні. Затримки йому не пробачать, тож він наймає мандрівних шукачів пригод Орди, щоб повернути розкидані вантажі.",al={"переказ про лока окарра","хто дає припаси бойової пісні","видавець розщепленого дерева"}},{q="Чому Орда везе спорядження з Буті Бею?",a="Орда покладається на нейтральні торгові мережі на кшталт картелю Стімвідл, щоб завозити спеціальні вироби, яких Дуротар і Пустки не можуть легко кувати у великих кількостях. Важкі лісорубні сокири, замовлені через гоблінські канали, ідуть через морські торгові осередки на кшталт Буті Бею, перш ніж дістатися Ашенвалю.",al={"чому буті бей","відправка сокир з буті бею","інструменти стімвідлів"}},{q="Навіщо сатирам Олія Бойової Пісні?",a="Не для машин: сатири, що населяють руїни на кшталт Сатирнаару, Нічного Потоку й Ксавіана, пускають украдену промислову олію на темні, осквернені обряди на честь Палаючого Легіону й скверни, що розповзається зі Сквернолісся.",al={"переказ про олію сатирів","чому у сатирів олія","ритуали олії бойової пісні"}},{q="Які фурболги вкрали Линву Лісоруба?",a="Линву Лісоруба відбили із засідки й забрали фурболги з племен Гнилолісу й Будякохутрих. Обидва племена запекло ворожі до суцільних вирубок, які Орда веде по всьому Ашенвалю.",al={"хто вкрав линву","переказ про линву фурболгів","линва будякохутрого"}},{q="Чому Лісозаготівельний Табір Бойової Пісні такий важливий для Орди?",a="Посушливі землі Дуротару майже не дають придатної для будівництва деревини. Клан Бойової Пісні відрядили на буйні прикордонні землі Ашенвалю саме для того, щоб рубати величезні дерева, потрібні для будівництва Оргріммара й розбудови військової сили Орди.",al={"чому збирати в ашенвалі","значення лісозаготівлі бойової пісні","орки рубають дерева"}}},fp="16,290,25.415.0,27.573.0,39.246.0,19.252.0,51.303.0,35.229.0,38.197.0,53.269.0"}
P.entries["quest:6581"] = {n="Пиляльні Леза Бойової Пісні",s="«Пиляльні леза Бойової Пісні» — доручення Орди на Заставі Розщепленого Дерева для лісозаготівельної кампанії клану Бойової Пісні. Щоб здобути важкі пиляльні леза, привезені з Раджета, шукачам пригод доведеться укласти неофіційну угоду з кур'єркою Піксель, яка вимагає особистого захисту, перш ніж віддати вантаж. Виконавши її умову, ви забезпечите обладнання, без якого лісопилки Орди в Ашенвалі не гудітимуть.",h="«Пиляльні леза Бойової Пісні» — доручення Орди на Заставі Розщепленого Дерева для лісозаготівельної кампанії...",kw={"пиляльні леза","піксель","смертоносний мушкетон","бойова пісня","раджет","завдання"},ang={["faction:Horde"]="Лісозаготівельні табори в Ашенвалі — опорний хребет розбудови Оргріммара, тож кожна доставка обладнання вкрай важлива для виживання Орди на Калімдорі.",["profession:Engineering"]="Смертоносний Мушкетон, якого вимагає Піксель, — звичний виріб умілих майстрів, і він показує, як гоблінська та інша інженерія рухає постачання на передовій.",["race:Orc"]="Клан Бойової Пісні під проводом Ґроммаша Хеллскріма поставив свою гордість на вирубку Ашенвалю; підтримувати оберти його промислових лез — означає шанувати незламну опору клану в лісі."},sec={{t="Хитрий обмін кур'єрки",b="Лісоруби Бойової Пісні в Ашенвалі цілком залежать від привізних важких машин, щоб прорубуватися крізь прадавню деревину глибокого лісу. Піксель успішно доставила вантаж спеціальних пиляльних лез просто з гоблінського порту Раджет на Заставу Розщепленого Дерева, але не збирається віддавати їх задарма. У небезпечній глушині Ашенвалю монета важить небагато, а особиста безпека — значно більше. Тож замість золота Піксель хоче обміняти важкі пиляльні леза на надійний Смертоносний Мушкетон, щоб убезпечити себе в небезпечних мандрах ворожими землями."},{t="Постачання для війни",b="Густі ліси Ашенвалю дуже цінні для Орди, якій гостро бракує деревини на посушливих рівнинах Дуротару й Пусток. Та вирубка прадавніх гаїв-охоронців швидко тупить звичайні сокири, тож без викуваних гоблінами промислових лез не обійтися. Вантаж Піксель безпосередньо живить роботу лісозаготівельних таборів Бойової Пісні, щоб Орда й далі могла будувати застави й бойові машини, попри запеклий опір нічних ельфів."}},faq={{q="Хто така Піксель і чому в неї пиляльні леза?",a="Піксель — кур'єрка, що зараз перебуває на Заставі Розщепленого Дерева; вона привезла партію промислових пиляльних лез просто з гоблінського порту Раджет. Вона притримує вантаж, доки не роздобуде надійну зброю для власного захисту.",al={"хто така піксель","піксель розщепленого дерева","гінець з пилками"}},{q="Чому Піксель хоче Смертоносний Мушкетон, а не золото?",a="Подорож через Пустки й углиб земель нічних ельфів в Ашенвалі надзвичайно небезпечна. Знаючи, що чатує на дорозі, Піксель ставить власний захист вище за гроші й вимагає вогнепальну зброю роботи інженера, щоб убезпечити свої мандри.",al={"чому мушкетон","торгівля піксель зброєю","чому хоче зброю"}},{q="Чому ці пиляльні леза такі важливі для Орди?",a="Орді потрібні величезні обсяги деревини, щоб будувати укріплення й бойові машини по всьому Калімдору. Звичайні різальні знаряддя швидко тупляться об прадавні залізні дерева Ашенвалю, тож привезені механічні пиляльні леза життєво важливі для лісорубних машин клану Бойової Пісні.",al={"чому леза потрібні","значення лісозаготівлі бойової пісні","чому припаси бойової пісні"}},{q="Звідки взялися пиляльні леза?",a="Пиляльні леза виготовили в Раджеті, нейтральному гоблінському порту на східному узбережжі Пусток, і відправили звідти, а потім суходолом доправили на Заставу Розщепленого Дерева.",al={"походження пиляльних лез","леза раджета","звідки леза"}},{q="Яке місце це завдання посідає в лісозаготівлях Бойової Пісні?",a="Це завдання — частина ширших зусиль зібрати Припаси Бойової Пісні для лісозаготівельних таборів в Ашенвалі. Повернувши пиляльні леза від Піксель, ви виконуєте одну з ключових вимог постачання, без яких лісозаготівлі Орди не втриматися.",al={"ланцюжок припасів бойової пісні","попередник пиляльних лез"}},{q="Чи будь-хто може зробити зброю, яку хоче Піксель?",a="Смертоносний Мушкетон виготовляють вправні інженери з мідних трубок, мідних болтів, дерев'яного ложа й шкіри, хоча кур'єри й воїни часто вимінюють його на місцевих ринках чи в інших шукачів пригод.",al={"як отримати мушкетон","джерело мушкетона","інженерна зброя"}}},fp="18,421,25.614.0,24.461.0,50.244.0,57.244.0,51.275.0,46.173.0,58.237.0,39.210.0"}
P.entries["quest:66"] = {n="Легенда про Сталвана",s="«Легенда про Сталвана» починається в Даркширі з лиховісного видіння міської віщунки Мадам Єви. Стривожена знаменням, що віщує смерть її онуці Аліссі, Єва звертається до карт і видінь у трансі — і дізнається одне-єдине ім'я: Сталван. Щоб розплутати цю нитку жаху, вона посилає мандрівників переглянути міські записи в Ратуші Даркшира.",h="«Легенда про Сталвана» починається в Даркширі з лиховісного видіння міської віщунки Мадам Єви.",kw={"легенда про сталвана","мадам єва","алісса","писар долтрі","ратуша даркшира","знамення"},ang={["class:Priest"]="Жерці, що ходять темними шляхами Даркшира, зважають на духовні застереження, тож моторошні знамення смерті від Мадам Єви — нагальна справа пастирського обов'язку.",["faction:Alliance"]="Сутінколісся бореться без регулярної підтримки армії Стормвінда, тож шукачі пригод з Альянсу часто допомагають міським старійшинам і захищають вразливі родини, як-от родину Мадам Єви."},sec={{t="Видіння смерті",b="У вічному мороці Сутінколісся Мадам Єва — місцева віщунка Даркшира, що тлумачить знамення й ворожить на картах стривоженим містянам. Прокинувшись від страшного неспокою, Єва звернулася до своєї ворожильної колоди — і витягла карту Смерті для своєї юної онуки Алісси. Поринувши в глибокий темний транс, щоб пробитися крізь морок, вона дізналася лише одну підказку: ім'я Сталван. Нажахана тим, що це знамення може означати для її родини й міста, вона просить вправних шукачів пригод піти за цією ниткою, доки не сталося лихо."},{t="Розпитати в ратуші",b="Єва знає: щоб дізнатися правду про Сталвана, треба зазирнути в писану історію Даркшира. Вона посилає шукачів пригод через площу до Ратуші Даркшира, до Писаря Долтрі — міського хранителя книг обліку й громадських архівів. Долтрі опікується запорошеними документами містечка, тож лише він може з'ясувати, чи був Сталван колишнім мешканцем, заїжджим мандрівником — чи чимось значно зловіснішим, похованим у минулому Сутінколісся."}},faq={{q="Хто така Мадам Єва?",a="Мадам Єва — ворожка й провидиця, що живе в Даркширі. Вона ворожить на картах і в трансі, щоб угледіти знамення майбутнього, і відчуває магічні збурення, що прокочуються Сутінколіссям.",al={"мадам єва","хто така єва","ворожка даркширу"}},{q="Чому Мадам Єві потрібна допомога?",a="Мадам Єві було жахливе видіння: її онука Алісса в смертельній небезпеці. Їй випала карта Смерті, а в трансі вона почула лише ім'я «Сталван», тож вона шукає допомоги, щоб дослідити загрозу.",al={"чому почати сталвана","видіння єви","чому допомагати єві"}},{q="Хто такий Писар Долтрі?",a="Писар Долтрі — міський архіваріус у Ратуші Даркшира. Він веде міські книги, реєстри й історичні документи, тож про незнайомі імена найкраще питати саме в нього.",al={"писар долтрі","долтрі","хто міський писар"}},{q="Що таке Ратуша Даркшира?",a="Ратуша Даркшира — адміністративний осередок містечка: тут сидять місцеві урядовці, зберігаються історичні записи й розташований штаб Нічної Варти.",al={"ратуша даркширу","ратуша сутінкового лісу"}},{q="Хто така Алісса?",a="Алісса — юна онука Мадам Єви, що живе в Даркширі. Ворожіння Єви показало, що над Аліссою нависло смертельне знамення, пов'язане з кимось на ім'я Сталван.",al={"алісса","онука мадам єви"}},{q="Куди веде це розслідування далі?",a="Розмова з Писарем Долтрі відкриває міські записи й давні розпити, з яких починається довге розслідування по всьому Сутінколіссю й сусідніх краях, щоб дізнатися історію й долю Сталвана.",al={"наступний крок сталвана","що каже долтрі"}}},fp="21,363,17.562.0,22.470.0,18.192.0,30.244.0,20.208.0,28.162.0,14.163.0,40.181.0"}
P.entries["quest:6608"] = {n="Ти надто добрий.",s="«Ти надто добрий» — завдання Орди від Лумака, наставника рибальства в Оргріммарі, яке він дає рибалці, що переріс звичайне навчання. Лумак відсилає свого вправного учня розшукати друга-людину Ната Паґла, що отаборився на відлюдному березі Багна Пилоброду. Це завдання знаменує перехід від звичайних уроків до вимогливого мистецтва справжнього майстра-рибалки.",h="«Ти надто добрий» — завдання Орди від Лумака, наставника рибальства в Оргріммарі, яке він дає рибалці, що...",kw={"рибальство","лумак","нат паґл","багно пилоброду","оргріммар","острів терамор","дружба"},ang={["faction:Horde"]="Це завдання показує, що й посеред війни фракцій часом зав'язується дружба через лінію фронту — завдяки нешкідливому ремеслу й спільним захопленням.",["race:Orc"]="Навіть у войовничій твердині Оргріммара Лумак доводить, що терпіння, добрий гумор і глибока повага до природи можуть допомогти оркові знайти друзів по той бік лінії фронту."},sec={{t="Межа Лумака",b="Лумак — головний наставник рибальства в Оргріммарі, що в Долині Честі, але навіть цей терплячий орк визнає, коли учень зрівнявся з ним у знанні вудки й котушки. Замість удавати, ніби має ще чого навчити, Лумак щиро зізнається, що рибалка став «надто добрий» для звичайних уроків. Щоб здобути ранг майстра, треба шукати за міськими мурами й за межами власного народу."},{t="Несподівана дружба",b="Попри тліючу ворожнечу між Ордою та Альянсом у Калімдорі, рибальство нерідко долає розбрат там, де дипломатія безсила. Лумак скеровує мандрівників до свого давнього знайомого, Ната Паґла, наполегливо застерігаючи, що людину не можна ні кривдити, ні їсти. Нат отаборився на острівці на південь від Острова Терамор у Багні Пилоброду й радо не зважає на політику, поки риба клює."}},faq={{q="Хто посилає мене на це завдання?",a="Лумак, наставник риболовлі, що стоїть біля води в Долині Честі в Оргріммарі, дає вам це завдання, коли ваше вміння риболовлі досить високе, щоб перейти вище рівня експерта.",al={"хто дає ти надто добрий","видавець лумак","де взяти ти надто добрий"}},{q="Де знайти Ната Паґла?",a="Нат Паґл живе на острівці біля узбережжя Багна Пилоброду, на південь від людського поселення Острів Терамор.",al={"де нат паґл","місце ната паґла","знайти ната паґла"}},{q="Звідки в орка друг-людина?",a="Рибалок по всьому Азероту часто єднає взаємна повага, що вища за війну фракцій. Лумак і Нат Паґл здружилися суто на ґрунті риболовлі, визнаючи пристрасть одне одного попри запеклу ворожнечу між орками й людьми.",al={"дружба лумака і ната паґла","чому нат паґл дружить з орком"}},{q="Що буде, коли я поговорю з Натом Паґлом?",a="Розмова з Натом Паґлом відкриває його вимогливе випробування для майстрів: вам доведеться мандрувати Азеротом і ловити рідкісну рибу, перш ніж він особисто навчить вас далі.",al={"чого навчає нат паґл","ремісниче рибальство завдання"}},{q="Чи безпечно Орді проходити через Терамор?",a="Ні, Терамор — місто-фортеця, яку пильно стереже Альянс. Шукачам пригод Орди доводиться обходити місто чи пробиратися узбережжям, щоб дістатися острова Ната й не накликати гніву вартових Терамора.",al={"чи орда може через терамор","дістатися ната паґла за орду"}},{q="Чому Лумак не може сам навчати мене далі?",a="Лумак навчив вас усього, що знав. Справжня майстерність у риболовлі потребує знань Ната Паґла, якого всюди вважають найлегендарнішим рибалкою відомого світу.",al={"чому лумак не вчить далі","експерт до майстра рибальство орда"}}},fp="13,350,14.413.0,22.406.0,27.165.0,27.118.0,36.227.0,39.176.0,44.197.0,41.164.0"}
P.entries["quest:6611"] = {n="Гайда до Ґаджетцана!",s="«Гайда до Ґаджетцана!» — мандрівка кухарів Орди, які прагнуть вийти за межі того, чого можуть навчити наставники столиці. За порадою Замджі з Оргріммара охочі кухарі вирушають на південь Калімдору, до Танарісу, щоб розшукати дивакуватого гобліна-м'ясника Дірджа Квіккліва. Це завдання-провідник знаменує перехід до справжньої майстерності в кулінарії.",h="«Гайда до Ґаджетцана!» — мандрівка кухарів Орди, які прагнуть вийти за межі того, чого можуть навчити...",kw={"кулінарія","ґаджетзан","дірдж квікклів","замджа","танаріс","кухар","картель стімвідл"},ang={["faction:Horde"]="Оргріммар покладається на сторонніх фахівців, як-от нейтральних гоблінів-кухарів, щоб його ремісники виходили за межі звичних племінних страв.",["profession:Cooking"]="Це завдання — віха, коли кухар переростає столичних наставників і мусить вирушити в небезпечні нетрі, щоб навчатися в справжнього майстра."},sec={{t="Кухар переростає Оргріммар",b="У Проході кухарка-троль Замджа годує незліченних воїнів і мандрівників, що проходять крізь червоні каньйони Дуротару. Та коли відданий кухар засвоює кожен рецепт і кожен прийом, яких може навчити Замджа, наставниця визнає поразку. Передавши все своє кулінарне моджо, вона відсилає досвідченого учня на південь, до пісків Танарісу: далі вести талановитого кухаря може лише справжній знавець дивного й екзотичного м'яса."},{t="М'ясник у пустелі",b="Пункт призначення — Ґаджетзан, торговий осередок на паровій тязі, яким керує картель Стімвідл. Там, у галасливій міській корчмі, хазяйнує Дірдж Квікклів. Гоблін із незвичайним смаком і без жодної кулінарної гидливості, Дірдж уславився на весь Калімдор тим, що перетворює страхітливу пустельну живність — а часом і клапті шкіри — на ситні страви, здатні підтримати сили загартованих шукачів пригод."}},faq={{q="Хто посилає мене до Ґаджетзана?",a="Замджа, тролиця-наставниця кулінарії рівня експерта, що стоїть біля вогнищ Проходу в Оргріммарі, дає це завдання кухарям, які опанували все, що вона знає.",al={"хто посилає до ґаджетзана","видавець завдання","завдання замджі"}},{q="Чому Замджа відсилає мене геть?",a="Замджа вичерпала всі рецепти й кулінарні прийоми, яких може навчити. Щоб досягти майстерного рівня кулінарії, вона скеровує обдарованих кухарів до Дірджа Квіккліва в Танарісі — ексцентричного знавця, що славиться вмінням готувати їстівні страви з найсуворіших пустельних інгредієнтів.",al={"чому ґаджетзан","чому дірдж квікклів","майстер кулінарії"}},{q="Хто такий Дірдж Квікклів?",a="Дірдж Квікклів — гоблін-м'ясник і наставник кулінарії майстерного рівня в корчмі Ґаджетзана. Він славиться крутою вдачею, дивними теоріями харчування — як-от що в старих шкіряних чоботях є білок — і майстерністю в найвишуканішій екзотичній кухні з дикої природи.",al={"дірдж","дірдж ґаджетзан"}},{q="Чи потрібне це завдання, щоб опанувати майстерну кулінарію?",a="Ні. Це завдання — лише дороговказ, що скеровує гравців Орди до Танаріса. Кухар із достатнім умінням може сам вирушити до Ґаджетзана й поговорити з Дірджем Квіккливом, не маючи рекомендації від Замджі.",al={"чи потрібне це завдання","хлібні крихти кулінарії","чи обов'язкове"}},{q="Де розташований Ґаджетзан?",a="Ґаджетзан — обнесена мурами пустельна застава картелю Стімвідл у північних пісках Танаріса, далеко на півдні материка Калімдор, нижче від Тисячі Голок.",al={"місце ґаджетзана","де дірдж"}},{q="Чи справді Замджа чогось учиться, коли я повертаюся?",a="Хоча Замджа жартома вимагає, щоб ви повернулися й навчили її, коли станете найкрутішим кухарем в окрузі, вона й далі лишається наставницею рівня експерта в Оргріммарі й підтримує свої вогнища для наступних поколінь мандрівників.",al={"чи замджа вчиться кулінарії","навчити замджу"}}},fp="20,356,25.422.0,25.395.0,27.158.0,29.269.0,24.267.0,48.224.0,27.179.0,51.206.0"}
P.entries["quest:6621"] = {n="Король Гнилолісу",s="«Король Гнилолісу» — військовий удар Орди, замовлений Каранґом Амаккаром на Заставі Зорам'гар. Прагнучи приборкати зіпсованих фурболгів Гнилолісу на південний схід від Астранаару, звитяжці Орди встромляють бойовий прапор просто на вершину священного тотемного пагорба племені, щоб виманити й стратити їхнього ватажка — Вождя Мурґута.",h="«Король Гнилолісу» — військовий удар Орди, замовлений Каранґом Амаккаром на Заставі Зорам'гар.",kw={"король гнилолісу","вождь мурґут","каранґ амаккар","село зеленолапів","фурболги","завдання"},ang={["class:Shaman"]="Спотворені тотеми й агресія Гнилолісу свідчать про невщухлий духовний розлад, що мучить споконвічні племена Ашенвалю після вторгнення Палаючого Легіону.",["faction:Horde"]="Каранґ Амаккар відкрито показує бойову перевагу, щоб залякати ворожі племена Ашенвалю й убезпечити центральні стежки для обозів Орди.",["race:Orc"]="Встромити прапор, щоб викликати ворожого ватажка на двобій, — класична орківська війна, де сила й рішуча сутичка важать більше, ніж затяжні перестрілки."},sec={{t="Показ сили",b="Поки нічні ельфи силкуються стримати зіпсовані племена Ашенвалю, Орда відповідає на загрозу розважливою агресією. Каранґ Амаккар із Застави Зорам'гар розуміє: хоч плем'я Гнилолісу й не може зрівнятися чисельністю з північними Будякохутрими, його неприборкана лють — прихована небезпека на південній дорозі. Не чекаючи засідок на дозори Орди, Каранґ наказує випереджально показати бойову перевагу й зламати волю племені."},{t="Осквернення й виклик",b="Удар спрямовано на Село Зеленолапів на північний схід від Озера Містраль. Каранґ виготовляє племінний бойовий прапор, який треба встромити просто в середину тотемного пагорба Гнилолісу, — непрощенна образа для духів предків і гордості племені. Захисники-фурболги у відчаї кидаються на пагорб, щоб зірвати зневажливий стяг, і змушують Вождя Мурґута вийти й обстояти свою честь у відкритому бою. Здобутий особистий тотем Мурґута розбиває провід племені й утверджує перевагу Орди в цьому краї."}},faq={{q="Хто наказує вбити Вождя Мурґута?",a="Каранґ Амаккар, орк із Застави Зорам'гар на західному узбережжі Ашенвалю, дає це доручення після того, як дослідив сусідніх фурболгів Будякохутрих.",al={"видавець короля гнилолісу","хто дає короля гнилолісу","завдання каранґа амаккара"}},{q="Де розташоване Село Зеленолапів?",a="Село Зеленолапів лежить на південний схід від поселення нічних ельфів Астранаар, на північний схід від Озера Містраль, трохи на південь від головного східного шляху Ашенвалю.",al={"де село зеленолапів","місце гнилолісу","де поставити прапор каранґа"}},{q="Навіщо Орда встромляє прапор у тотемний пагорб?",a="Встромити Прапор Каранґа просто в священний тотемний пагорб племені — навмисна провокація. Наруга над святинею змушує Гнилоліс у люті кинутися в бій, а Вождя Мурґута — битися відкрито, щоб не втратити свого становища.",al={"чому ставити прапор","призначення прапора на пагорбі","чому кидати виклик мурґуту"}},{q="Хто такі фурболги Гнилолісу?",a="Гнилоліс — одне з кількох племен фурболгів Ашенвалю, що після Третьої війни поринули в безумство й скверну. Хоч їх менше, ніж Будякохутрих, вони й далі жорстокі й ворожі до чужинців.",al={"що таке гниліліс","переказ про плем'я гнилолісу","хто вождь мурґут"}},{q="Що дає повернення Тотема Мурґута?",a="Тотем Вождя Мурґута, принесений на Заставу Зорам'гар, доводить, що вождя переможено. Без ватажка й зі зганьбленим священним пагорбом уцілілі фурболги Гнилолісу залякані й уникають нових сутичок з Ордою.",al={"призначення тотема мурґута","що буде після смерті мурґута"}},{q="Як це завдання пов'язане з попередніми розслідуваннями про фурболгів?",a="Це доручення йде одразу після завдання «Між каменем і Будякохутрими». Розібравшись із північним племенем Будякохутрих, Каранґ звертає погляд на південь, щоб завчасно розгромити Гнилоліс, перш ніж той почне злагоджені набіги.",al={"між каменем і будякохутрим","попередник короля гнилолісу"}}},fp="21,312,15.490.0,25.511.0,37.180.0,34.158.0,53.240.0,31.222.0,47.227.0,64.229.0"}
P.entries["quest:6623"] = {n="Травматологія Орди",s="«Травматологія Орди» — поклик, що скеровує вправних цілителів Орди до Гаммерфолла в Аратійському нагір'ї. Доктор Ґреґорі Віктор, головний лікар травматологічної служби Орди, шукає й перевіряє вмілі руки, здатні рятувати життя під шаленим тиском. Відгукнувшись на цей поклик, лікар потрапляє просто в похмуру й небезпечну дійсність польової хірургії на передовій.",h="«Травматологія Орди» — поклик, що скеровує вправних цілителів Орди до Гаммерфолла в Аратійському нагір'ї.",ang={["class:Priest"]="Божественна магія загоює рани миттєво, але звичайне медичне сортування вчить важливої дисципліни: визначати, кого ще можна врятувати, коли мана висохла до останньої краплі.",["faction:Horde"]="Військова міць Орди значною мірою тримається на загартованих польових хірургах, які латають бійців і повертають їх у стрій у жорстоких прикордонних сутичках, як-от в Аратійській Улоговині."},sec={{t="Поклик із Гаммерфолла",b="У Долині Духів в Оргріммарі орк Арнок, наставник першої допомоги, повідомляє вправним цілителям, що на них звернув увагу сам Доктор Ґреґорі Віктор. Віктор очолює травматологічну службу Орди в укріпленій заставі Гаммерфолл, що ховається серед спірних пагорбів Аратійського нагір'я. Арнок бачить у цьому поклику не просто наказ, а вершину професійного зростання для кожного польового хірурга."},{t="Жорстока робота польового сортування",b="Діставшись Гаммерфолла, новачки розуміють, що служба тут далеко не затишна. Віктор працює серед безперервних сутичок із Лігою Аратора та місцевими ворожими силами, і до нього потоком везуть поранених бійців, рейдерів і розвідників. Головний лікар не гає часу на люб'язності: новобранцям одразу наказують перевдягнутися в робочий одяг і довести, чого вони варті, під час жорсткого й швидкого сортування поранених."}},faq={{q="Що таке Травматологія Орди?",a="Травматологія Орди — окрема медична й хірургічна служба передової Орди. Нею керує Доктор Ґреґорі Віктор із Гаммерфолла, а її члени спеціалізуються на польовій медицині, сортуванні поранених і лікуванні тяжких бойових ран серед хаосу.",al={"фракція травматологія орди","що таке травматологія орди","хто травматологія орди"}},{q="Хто посилає мене на це доручення?",a="Виклик дає Арнок, орк-наставник першої допомоги в Долині Духів в Оргріммарі. Служити під проводом Доктора Ґреґорі Віктора він вважає найвищою честю, про яку може мріяти польовий лікар-початківець.",al={"quest giver horde trauma","who starts horde trauma","krenk choplimb","arnok"}},{q="Де знайти Доктора Ґреґорі Віктора?",a="Доктор Ґреґорі Віктор працює в лазареті Гаммерфолла — головної твердині Орди на північному сході Аратійського нагір'я.",al={"доктор ґреґорі віктор","де віктор","лікар гаммерфолла"}},{q="Що буде, коли я доповім у Гаммерфоллі?",a="Щойно ви прибудете, Доктор Віктор звелить вам перевдягтися в робочий одяг для наступного завдання — «Сортування поранених». На вас чекає напружене випробування: треба визначити черговість і вилікувати солдатів, яким швидко гіршає, перш ніж вони помруть від ран.",al={"що після травматології орди","наступне завдання після травматології","завдання сортування"}},{q="Чому Гаммерфоллу так бракує польових лікарів?",a="Гаммерфолл оточений ворогами в Араті: тут не вщухають сутички з людськими загонами, агентами Синдикату й місцевими звірами. Поранені безперервно прибувають до табору, і нечисленні лікарі бази працюють на межі сил.",al={"чому гаммерфоллу бракує лікарів","медична ситуація гаммерфолла"}},{q="Чи можуть гравці Альянсу взятися за це доручення?",a="Ні. Травматологія Орди — лише для членів Орди. В Альянсу є рівноцінне медичне випробування, яке проводить Доктор Ґустаф ВанГаузен у твердині Острів Терамор.",al={"чи альянс може травматологію орди","версія для альянсу травматології"}}},fp="12,389,25.427.0,37.419.0,21.279.0,32.206.0,39.149.0,43.262.0,48.240.0,42.180.0"}
P.entries["quest:6625"] = {n="Травматологія Альянсу",s="Травматологія Альянсу — виклик, що скеровує досвідчених польових лікарів на Острів Терамор у Багні Пилоброду. Наставники з першої допомоги в столицях Альянсу запрошують умілих цілителів навчатися в Доктора Ґустафа ВанГаузена, головного лікаря добірного медичного корпусу Альянсу.",h="Травматологія Альянсу — виклик, що скеровує досвідчених польових лікарів на Острів Терамор у Багні Пилоброду.",kw={"травматологія альянсу","перша допомога","ґустаф вангаузен","острів терамор","багно пилоброду","лікар"},ang={["faction:Alliance"]="Травматологія Альянсу дбає, щоб бійці на передовій у Калімдорі й Східних Королівствах мали вмілих польових лікарів, здатних під вогнем рятувати важкопоранених.",["race:Dwarf"]="Наставники на кшталт Нісси Файрстоун в Айронфорджі охоче шукають біля Великої Кузні здібних цілителів, щоб ті представляли найкращі медичні таланти Альянсу в Тераморі."},sec={{t="Поклик на передову",b="Коли лікар опановує основи, яких навчають у великих містах Альянсу, місцеві наставники вже мало що можуть йому дати. Про тих, хто виявляє винятковий хист до голки, бинтів і сортування поранених, звістку надсилають просто Докторові Ґустафу ВанГаузену. З прикордонної твердині на Острові Терамор ВанГаузен керує Травматологією Альянсу — організацією, що рятує життя в найжорстокіших зонах бойових дій Калімдору й поза ним."},{t="Дорога до Терамора",b="Наставники на кшталт Нісси Файрстоун в Айронфорджі вважають особистий виклик від ВанГаузена винятковою честю. На Острів Терамор постійно тиснуть місцеві загрози, сутички й суворі умови дикого краю, тож поранені вояки прибувають безперервним потоком. Щоб дістатися до лікарні ВанГаузена, доводиться довго плисти морем до Багна Пилоброду, і лише найвитриманіші польові хірурги можуть сподіватися пройти його суворі перевірки."}},faq={{q="Що таке Травматологія Альянсу?",a="Травматологія Альянсу — добірна медична служба, що відповідає за складну польову медицину й сортування поранених по всьому Альянсу. Очолює її головний Лікар Ґустаф ВанГаузен, і вона береться за тяжкі рани, з якими не впорається звичайна польова перев'язка.",al={"переказ про травматологію альянсу","хто травматологія альянсу"}},{q="Хто посилає на це завдання?",a="Наставники першої допомоги Альянсу, як-от Нісса Файрстоун біля Великої Кузні в Айронфорджі, відправляють обдарованих цілителів, щойно ті досягнуть вершини звичайного навчання.",al={"хто дає травматологію альянсу","видавець першої допомоги айронфорджа"}},{q="Куди треба вирушити?",a="Вам треба дістатися людської портової фортеці Острів Терамор на східному узбережжі Багна Пилоброду, на материку Калімдор.",al={"де ванґаузен","куди йти травматологія альянсу"}},{q="Хто такий Доктор Ґустаф ВанГаузен?",a="Доктор Ґустаф ВанГаузен — головний лікар Травматології Альянсу. Він працює у військовій лікарні в Тераморі, і його вважають одним із найбільших знавців невідкладної медицини й хірургічного сортування в Альянсі.",al={"ґустаф ванґаузен","головний лікар ванґаузен"}},{q="Що буде після доповіді Докторові ВанГаузену?",a="Коли ви прибудете до Терамора, ВанГаузен влаштує кандидатам суворе практичне випробування з сортування поранених: треба рятувати хвилю за хвилею вмирущих солдатів, і лише тоді він прийме вас до вищих лав польової медицини.",al={"що після травматології альянсу","наступне завдання сортування"}},{q="Чому лікарня в Тераморі, а не в Стормвінді чи Айронфорджі?",a="Терамор — діяльний прикордонний гарнізон серед ворожих боліт, небезпечних звірів і сутичок за землю. Тяжкопоранені вояки прибувають сюди безперервно, тож це ідеальне місце для напруженого навчання травматології.",al={"чому лікарня в тераморі","чому пилові болота"}}},fp="15,307,19.448.0,21.468.0,24.252.0,28.178.0,28.143.0,31.221.0,49.217.0,71.240.0"}
P.entries["quest:6627"] = {n="Випробування знань",s="«Випробування знань» — випробування розуму й історичної пам'яті, яке призначає відлюдник Брауґ Дімспіріт у Горах Кам'яного Кігтя. Здобувши прадавній том «Спадок Аспектів», мандрівники мають довести, що розуміють давню історію, відповівши на запитання Брауґа. Тих, хто не вчитався в текст, раптово відкидає через увесь Калімдор.",h="«Випробування знань» — випробування розуму й історичної пам'яті, яке призначає відлюдник Брауґ Дімспіріт у...",kw={"випробування знань","брауґ дімспіріт","спадок аспектів","нелтаріон","табір тауражо","аспекти-дракони"},ang={["class:Mage"]="Маги визнають телепортаційний оберіг Брауґа водночас і вражаючим, і каральним: відлюдники Гір Кам'яного Кігтя володіють давньою магією, щоб навчати розуму недбалих учнів.",["faction:Horde"]="Випробування Орди в Калімдорі вимагають більшого, ніж груба сила: і від воїнів, і від шаманів чекають розуміння давніх ран і драконячих сил, що сформували континент.",["race:Tauren"]="Це випробування втілює тауренську шану до мудрості предків і давньої історії, щоб молоді герої не йшли наосліп, не знаючи рівноваги світу."},sec={{t="Випробування мудрості",b="Випробування знань — частина ширшої низки випробувань, що починаються в Дорна Плейнстокера у Вивітреному Закутку, — зміщує увагу з виживання в бою чи сліпої довіри на розуміння давнього минулого світу. Брауґ Дімспіріт, що живе серед круч Гір Кам'яного Кігтя, вимагає від шукачів знайти давні тексти й по-справжньому засвоїти знання з їхніх сторінок."},{t="Спадок Аспектів",b="Урок присвячено створенню й розподілу Аспектів-драконів, а надто доленосній угоді, укладеній задовго до Великого Розколу. Брауґ перевіряє, що шукач запам'ятав про Охоронця Землі, Нелтаріона, чиє падіння в божевілля й зрада змінили обличчя Азероту. Тих, хто не шанує історію, не пускають далі шляхом мудрості."},{t="Ціна здогадок",b="Брауґ не терпить пустих здогадок. Шукача, що відповість неправильно, миттю виганяє містична сила — і він опиняється за багато миль, у Таборі Тауражо на півдні Пусток. Щоб повернути собі місце, доведеться довго чвалати назад угору, до Гір Кам'яного Кігтя, й удруге постати перед прискіпливим відлюдником."}},faq={{q="Яка правильна відповідь на запитання Брауґа Дімспіріта?",a="Брауґ питає, хто такий Вартовий Землі, описаний у книзі «Спадок Аспектів». Правильна відповідь — Нелтаріон, Чорний Аспект, який згодом обернеться проти інших драконів.",al={"відповідь брауґу","відповідь випробування знань","запитання про спадщину аспектів"}},{q="Що буде, якщо відповісти неправильно?",a="Якщо назвати Брауґові не те ім'я, магія миттю вижене вас геть — просто до Табору Тауражо в Пустках. Доведеться пройти весь шлях назад до його скелі в Горах Кам'яного Кігтя, щоб спробувати знову.",al={"неправильна відповідь випробування знань","провалив випробування знань","телепорт у тауражо"}},{q="Хто такий Брауґ Дімспіріт?",a="Брауґ Дімспіріт — старий відлюдник із Гір Кам'яного Кігтя, який перевіряє знання й обізнаність у переказах для Орди, продовжуючи низку духовних випробувань, що почалася в Тисячі Голок.",al={"брауґ дімспіріт","хто дає випробування знань"}},{q="Як це пов'язано з випробуваннями в Тисячі Голок?",a="Випробування почалося з Дорна Плейнстокера в Обвітреному Закутку в Тисячі Голок — з «Випробування віри». Дорн перевіряє тілесну й духовну довіру, а тоді посилає гідних учнів по всьому Калімдору, щоб інші мудрі старійшини перевірили їхній розум, рішучість і силу.",al={"зв'язок з дорном рівнинним","ланцюжок випробування віри"}},{q="Про яку книгу питає Брауґ?",a="Запитання перевіряє, як ви зрозуміли «Спадок Аспектів» — прадавній трактат про те, як титани благословили п'ятьох Великих Аспектів-драконів берегти Азерот.",al={"яка книга в брауґа","спадщина аспектів"}},{q="Куди веде цей ланцюжок завдань далі?",a="Склавши Брауґів іспит про Аспектів-драконів, ви переходите до дальших випробувань із давньої історії: шукачам доведеться обнишпорити далекі краї в пошуках загублених записів і знань предків.",al={"що після випробування знань","наступне завдання випробування знань"}}},fp="12,361,17.381.0,21.371.0,22.317.1,49.193.0,39.226.0,23.203.0,56.265.0,38.171.0,38.192.0"}
P.entries["quest:6628"] = {n="Випробування знань",s="Це випробування — перевірка розуму в ширшій низці духовних випробувань, що починаються в Тисячі Голок. Обшукавши світ у пошуках історичних текстів, посвячувані постають перед Парквалом Фінталласом в Андерсіті, щоб довести, що розуміють темні сторінки історії, які формують Азерот.",h="Це випробування — перевірка розуму в ширшій низці духовних випробувань, що починаються в Тисячі Голок.",kw={"випробування знань","парквал фінталлас","зародження загрози нежиті","нер'жул","король-ліч","андерсіті"},ang={["faction:Horde"]="Це випробування зміцнює зв'язки між племенами Калімдору й королівством під Лордероном і нагадує героям, що для виживання Орди мудрість така ж важлива, як і сила.",["race:Tauren"]="Посвячений за давньою традицією старійшин, цей іспит спонукає мандрівників-тауренів вивчити похмуру історію своїх північних союзників-Відступників і світу за межами Калімдору.",["race:Undead"]="Тема іспиту б'є в самісіньке серце самосвідомості Відступників: трагедія створення Нер'жула й народження прокляття, що сковувало їх, доки Сильвана не зламала хватку Короля-Ліча."},sec={{t="Випробування знань",b="Багато випробувань в Орді перевіряють бойову міць чи сиру витривалість, а Випробування знань вимагає наукової відданості. Шлях, що бере початок у духовному вишколі Дорна Плейнстокера у Вивітреному Закутку, веде претендентів далеко від вивітрених каньйонів Тисячі Голок — у затінені зали Андерсіті. Екзаменатором тут є Парквал Фінталлас, що вимагає від шукачів бездоганного знання історії."},{t="Як народилася Погибель",b="Щоб задовольнити Парквала, посвячуваний має вивчити «Зародження Загрози Нежиті» — текст про прокляте походження Погибелі в Лордероні. Головне в його допиті — хто панує на Крижаному Троні: колишній старійшина-шаман Нер'жул, чий дух Палаючий Легіон перекував на Короля-Ліча. Знати цей похмурий родовід вважають конче потрібним, щоб розуміти існування Відступників і небезпеки, що загрожують і Калімдору, і Східним Королівствам."}},faq={{q="Яка правильна відповідь на запитання Парквала?",a="Парквал Фінталлас питає, як звали Короля-Ліча спочатку. Правильна відповідь — Нер'жул, прадавній орк-шаман, чий дух прикували до Крижаного Трону.",al={"відповідь короля-ліча","запитання парквала","відповідь випробування знань"}},{q="Що буде, якщо відповісти неправильно?",a="Неправильна відповідь накладає на вас Знак Ганьби, і доведеться перечекати цю кару, перш ніж Парквал дозволить спробувати скласти іспит знову.",al={"знак ганьби","неправильна відповідь випробування знань"}},{q="Де починається цей ланцюжок завдань?",a="Загальне випробування починається з Дорна Плейнстокера в Обвітреному Закутку, серед стрімких скельних шпилів Тисячі Голок.",al={"де починається випробування знань","ланцюжок дорна рівнинного"}},{q="Де знайти Парквала Фінталласа?",a="Парквал Фінталлас живе в Андерсіті: він тиняється підземними бібліотеками й коридорами Відступників і там допитує охочих учнів.",al={"знайти парквала","місце парквала фінталласа"}},{q="На якому тексті засноване це випробування?",a="Іспит засновано на книзі «Зародження Загрози Нежиті», де розповідається про походження Чуми нежиття й створення Короля-Ліча.",al={"яка книга для випробування знань","книга початків"}},{q="Чому завдання з Тисячі Голок посилає до Андерсіті?",a="Випробування, засновані тауренами, мають перевірити шукача пригод з усіх боків. Щоб перевірити знання переказів, кандидатів відправляють за море шукати вчені записи, збережені в руїнах Лордерону.",al={"чому йти до андерсіті","тисяча голок андерсіті"}}},fp="12,297,20.430.0,21.495.1,41.162.0,46.165.0,34.130.0,35.155.0,33.152.0,60.208.0"}
P.entries["quest:6629"] = {n="Убий Ґрундіґа Дарклауда",s="«Убий Ґрундіґа Дарклауда» — завдання Орди від Макаби Флетгуфа на південно-східній стежці Гір Кам'яного Кігтя. Після того як ви розправилися з головорізами й найманцями-Ґрімтотемами, Макаба вказує вам на ватажка, що сплюндрував його дім, — Ґрундіґа Дарклауда. Знищивши Ґрундіґа та його почет громил, ви здобудете справедливість для спустошеного селища.",h="«Убий Ґрундіґа Дарклауда» — завдання Орди від Макаби Флетгуфа на південно-східній стежці Гір Кам'яного Кігтя.",kw={"ґрундіґ дарклауд","застава ґрімтотем","макаба флетгуф","ґрімтотем","помста","гори кам'яного кігтя"},ang={["faction:Horde"]="Гори Кам'яного Кігтя — життєво важлива земля для поширення Орди Калімдором, а войовничі ватажки Ґрімтотемів на кшталт Ґрундіґа загрожують шляхам постачання між Пустками й Притулком Сонячної Скелі.",["race:Tauren"]="Клан Ґрімтотем і далі сіє розбрат серед тауренів, і різанина, влаштована Ґрундіґом, показує: їхній безжальний екстремізм завжди противитиметься єдності під прапорами Орди."},sec={{t="М'ясник зі стежки",b="Макабі Флетгуфу вдалося вижити під час раптового, жорстокого нападу на його селище при стежці в Горах Кам'яного Кігтя, але горе його досі свіже. Переконавшись, що ви вмієте впоратися з рядовими бійцями Ґрімтотемів, він указує вам на того, хто стоїть за різаниною, — Ґрундіґа Дарклауда. На відміну від звичайних розбійників, що шукають легкої наживи, Ґрундіґ має відданий почет громил і сам очолив бійню, яка зрівняла селище із землею."},{t="Удар по Заставі Ґрімтотем",b="Ґрундіґ отаборився на Заставі Ґрімтотем, вище гірською дорогою на захід. Щоб помститися за родичів Макаби й убезпечити перевал від нового насильства, мандрівникам треба піднятися до твердині, прорубатися крізь найближчих громил Дарклауда й покласти край самому Ґрундіґу, перш ніж його загін спуститься на інші беззахисні табори."}},faq={{q="Хто такий Ґрундіґ Дарклауд?",a="Ґрундіґ Дарклауд — жорстокий командир Ґрімтотем із Застави Ґрімтотем на південному сході Гір Кам'яного Кігтя. Саме він задумав і очолив безжальний напад, що знищив селище Макаби Флетгуфа.",al={"ґрундіґ дарклауд","хто такий ґрундіґ","ватажок ґрімтотем"}},{q="Де знайти Ґрундіґа Дарклауда?",a="Ґрундіґ Дарклауд — на Заставі Ґрімтотем, що на гірській стежці трохи вище й на захід від табору Макаби Флетгуфа, неподалік кордону з Пустками.",al={"місце ґрундіґа","де ґрундіґ","місце застави ґрімтотем"}},{q="Що спонукає Макабу Флетгуфа дати це доручення?",a="Макаба бачив, як Ґрімтотем вирізали його дім і родичів. Уже поквитавшись почасти з їхніми головорізами й найманцями, він просить голову ватажка, Ґрундіґа Дарклауда, щоб нарешті здобути справжню відплату й спокій.",al={"чому вбити ґрундіґа","історія макаби","помста макаби"}},{q="Чому Ґрімтотем нападають тут на мирні поселення?",a="Клан Ґрімтотем глибоко зневажає інші племена тауренів, особливо тих, хто приєднався до Орди чи обрав лагідніший шлях. Засідками, набігами й неприхованою жорстокістю вони виганяють суперників із земель, якими хочуть заволодіти.",al={"чому ґрімтотеми нападають","ворожість ґрімтотем"}},{q="Що буде після вбивства Ґрундіґа Дарклауда?",a="Смерть Ґрундіґа Дарклауда та його громил завершує короткий ланцюжок помсти Макаби Флетгуфа. Коли кат загинув, Макаба нарешті може оплакати своє селище, знаючи, що справедливість восторжествувала.",al={"що після ґрундіґа","продовження ланцюжка флетгуфа"}},{q="Яке завдання треба виконати перед цим?",a="Спершу треба виконати «Помсти за моє селище»: у ньому Макаба Флетгуф перевіряє вашу рішучість, доручивши вбити головорізів і найманців Ґрімтотем, що стоять табором трохи на захід.",al={"попередник вбити ґрундіґа","завдання перед ґрундіґом"}}},fp="22,363,23.418.0,24.351.0,25.209.0,37.160.0,47.245.0,58.260.0,43.191.0,45.178.0"}
P.entries["quest:6641"] = {n="Ворша Шмагачка",s="Ворша Шмагачка — люта гідра, що тероризує опору Орди на Заставі Зорам'гар на узбережжі Ашенвалю. Місцеві наги шанують лютість цієї істоти й підтримують на острові неподалік від берега жертовну жаровню на її честь. Загасивши це священне полум'я, звитяжці Орди розлючують Воршу й виманюють її на берег, щоб покласти край її хижацьким нападам.",h="Ворша Шмагачка — люта гідра, що тероризує опору Орди на Заставі Зорам'гар на узбережжі Ашенвалю.",kw={"ворша шмагачка","гідра","наги","муґлаш","застава зорам'гар","завдання"},ang={["faction:Horde"]="Оборона Застави Зорам'гар вкрай важлива, щоб утримати північну опору постачання в Ашенвалі, де шляхи постачання повсякчас під ударом.",["race:Orc"]="Орки на кшталт Муґлаша не ховаються за абияк збитими частоколами — вони кидаються в прибій, щоб полювати на хижих звірів віч-на-віч."},sec={{t="Жах із глибин",b="Застава Зорам'гар стоїть на хиткій смужці узбережжя на північному заході Ашенвалю, у постійній облозі ворожих звірів, нічних ельфів і зміїних загарбників. Одна з найруйнівніших загроз Зорамського Узмор'я — Ворша Шмагачка, велетенська гідра, відома жорстокими нападами на заставу без жодної причини. Звір виринає з прибою, трощить укріплення й вирізає воїнів, а тоді зникає назад у глибоких хвилях."},{t="Жаровня наг",b="Сусідні наги не просто терплять ненажерливу гідру — вони щиро шанують її хижацьку злобу. На скелястому виступі біля узбережжя зміїні почвари підтримують жертовну жаровню, що безупинно горить на честь Ворші. Муґлаш, орк, який твердо вирішив покласти край постійним нападам на заставу, зрозумів: якщо осквернити це обрядове полум'я, розлючена гідра вирине на поверхню, і захисники зможуть заманити її в засідку, а не чекати наступної раптової різанини."}},faq={{q="Хто така Ворша Шмагачка?",a="Ворша Шмагачка — люта велетенська гідра, що чатує у водах біля узбережжя Зорам. Вона раз у раз без жодної причини нападає на Заставу Зорам'гар, руйнує укріплення табору й убиває людей Орди.",al={"ворша","що таке ворша","гідра ворша"}},{q="Чому наги шанують Воршу?",a="Наги узбережжя Зорам поважають Воршу за невгамовну лють і руйнівну ненажерливість. На острівці в морі вони підтримують вогонь у жаровні на честь її лихої вдачі й мають цю потвору за втілення дикого гніву моря.",al={"чому наги люблять гідру","жаровня наг ворша","чому поклоняються ворші"}},{q="Як виманити Воршу на бій?",a="Муґлаш веде напад на острівець, де наги доглядають жаровню Ворші. Згасле священне полум'я страшенно лютить і нагів-охоронців, і саму гідру, тож Ворша виринає з моря, щоб помститися.",al={"як призвати воршу","як викликати воршу","острів жаровні ворша"}},{q="Хто такий Муґлаш?",a="Муґлаш — орк із Застави Зорам'гар. Утомившись жити в страху перед Воршею, що без причини громить узбережжя, він придумує, як загасити обрядову жаровню наг і дати бій потворі разом із надійними союзниками.",al={"муґлаш","орк муґлаш","муґлаш зорам'ґар"}},{q="Чому Застава Зорам'гар вразлива для морських потвор?",a="Застава Зорам'гар — відокремлений і відкритий прикордонний табір просто на пляжах Ашенвалю. Наги панують у руїнах у морі, дикі гідри патрулюють прибій, тож близькість до води робить заставу відкритою для нападів із води з усіх боків.",al={"чому нападають на зорам'ґар","небезпека зорамського узмор'я"}},{q="Що буде після смерті Ворші?",a="Коли гідру вбито, про перемогу доповідають бігунам Бойової Пісні, що тримають оборону на Заставі Зорам'гар: прикордонним вартовим стає легше, а узбережжя поблизу вже не загрожує раптовий напад.",al={"здати воршу","кому доповісти про воршу"}}},fp="17,352,22.436.0,23.501.0,25.213.0,29.228.0,33.236.0,15.226.0,54.269.0,35.221.1"}
P.entries["quest:67"] = {n="Легенда про Сталвана",s="Це доручення від Писаря Долтрі з ратуші Даркшира започатковує паперовий слід у справі про долю Сталвана Містмантла. Найдавніші записи писаря вказують на захід, на покинуту Школу Мунбрука у Вестфолі, — і так починається класичне розслідування того, як звичайна людина зійшла з розуму.",h="Це доручення від Писаря Долтрі з ратуші Даркшира започатковує паперовий слід у справі про долю Сталвана...",kw={"легенда про сталвана","сталван містмантл","писар долтрі","школа мунбрука","покинутий дух","вестфол"},ang={["class:Mage"]="Покинутий дух, що стереже скриню, вдається до перетворення й виснажливих прокльонів — моторошна зустріч із прикутою до печалі магією у звичайнісінькому шкільному класі.",["faction:Alliance"]="Цей етап розслідування показує, як глибоко розкололися сільські містечка королівства: щоб розв'язати звичайний запит до реєстру Даркшира, героям доводиться пробиратися окупованим Дефіас Вестфолом."},sec={{t="Прохання міського писаря",b="Після перших розпитувань у Даркширі Писар Долтрі дістає міський реєстр, щоб знайти Сталвана Містмантла. На свій подив, він бачить, що реєстр не оновлювали роками, а останнім відомим місцем проживання Сталвана вказано школу в Мунбруку, далеко на заході. Не здогадуючись про зловісну природу розслідування, Долтрі сприймає це як звичайну канцелярську роботу й просить мандрівників перевірити адресу та зібрати записи, які допомогли б оновити запорошені архіви Даркшира."},{t="Руїни Мунбрука",b="Іти цим слідом означає покинути морок Сутінколісся й вирушити в беззаконний пил Вестфолу. Мунбрук, колись квітуче хліборобське поселення, тепер кишить розбійниками з Братства Дефіас. Ближче до центру занедбаного містечка стоїть покинута школа, тиха посеред бандитської окупації. У ній стара скриня зберігає перші відчутні підказки про колишнє життя Сталвана як учителя — а ще неспокійну печаль, прикуту до скрині."},{t="Трагічна примара",b="Потривожена стара скриня відкриває не лише забуті сторінки: вона викликає покинутого духа, що нападає на кожного, хто розкопує минуле Сталвана. Скорботна магія привида проклинає непроханих гостей і натякає на нерозв'язану трагедію, пов'язану з від'їздом учителя з Вестфолу, — і просте історичне дослідження обертається на справжню зустріч із потойбіччям."}},faq={{q="Хто такий Писар Долтрі?",a="Писар Долтрі — хранитель міських записів у Ратуші Даркшира в Сутінколіссі. Він допомагає шукати в місцевому реєстрі згадки про Сталвана Містмантла, але знаходить лише давні, застарілі записи.",al={"долтрі","писар даркширу","хто починає легенду про сталвана 2"}},{q="Де школа Мунбрука?",a="Школа стоїть у Мунбруку на південному заході Вестфолу. Будівлею вона схожа на ратушу Даркшира й височіє посеред міста, оточена ворожими бандитами Дефіас.",al={"місце школи мунбрука","де школа","де скриня сталвана"}},{q="Що в Старій скрині?",a="У скрині — давні записи й особисті речі Сталвана Містмантла з тих часів, коли він учителював у Мунбруку; вони дають наступну зачіпку в пошуках.",al={"скриня сталвана","що в скрині"}},{q="Чому, коли відкрити скриню, нападає привид?",a="Відкрита скриня викликає покинутого духа, що атакує перетвореннями й прокляттями. Неспокійна примара прив'язана до темної трагедії в минулому Сталвана та його від'їзду з Мунбрука.",al={"чому з'являється привид","знедолений дух","прокляття сталвана привид"}},{q="Чому Сталван покинув Вестфол?",a="Сталван був учителем у Мунбруку, а потім подався шукати місце приватного вчителя деінде в королівстві, лишивши свої шкільні речі замкненими в покинутому місті.",al={"чому сталван покинув мунбрук","історія сталвана в мунбруку"}},{q="Чи безпечно заходити в Мунбрук?",a="Ні. Мунбрук цілком під владою Братства Дефіас, тож кожному, хто шукає школу, доведеться пробиватися крізь озброєних злодіїв і розбійників.",al={"чи мунбрук небезпечний","істоти мунбрука"}}},fp="21,278,24.479.0,22.465.0,17.359.1,20.206.0,35.190.0,34.179.0,52.201.1,31.198.0,27.163.0"}
P.entries["quest:676"] = {n="Молот може впасти",s="Таллов із Таррен Мілла посилає поборників Орди через гори до Аратійського нагір'я, на допомогу обложеному поселенню Гаммерфолл. Перш ніж доповісти Драмові Фелу, шукачі пригод мусять довести свою бойову готовність у боях із брутальними ограми-Каменекулаками, що чатують біля руїн Стромґарда.",h="Таллов із Таррен Мілла посилає поборників Орди через гори до Аратійського нагір'я, на допомогу обложеному...",kw={"молот може впасти","таллов","гаммерфолл","драм фел","каменекулаки","аратійське нагір'я","завдання"},ang={["class:Warrior"]="Бій із кремезними силачами-Каменекулаками — класичне випробування для бійців передової, що прагнуть заслужити повагу досвідчених орочих командирів на кшталт Драма Фела.",["faction:Horde"]="Це завдання позначає головний перехід від місцевих суперечок Гілсбреда до ширшої оборони Аратійського нагір'я й зміцнює важливий плацдарм Гаммерфолла в краї.",["race:Orc"]="Гаммерфолл має для орків глибоке почуттєве й історичне значення: його заснували там, де Вождь Оргрім Думхаммер віддав життя під час визвольних походів."},sec={{t="Суворий заклик",b="У Таррен Міллі Таллов має обмаль терпіння до неперевірених шукачів пригод, що блукають передгір'ям. Бачачи, як недисципліновані новобранці байдикують, поки далекі союзники стікають кров'ю, він посилає вправних бійців на схід, крізь Мур Торадіна, до Аратійського нагір'я. Застава Орди Гаммерфолл в облозі з кількох боків, але Таллов не хоче посилати туди гарматне м'ясо, доки ті не доведуть, чого варті, проти серйозного супротивника."},{t="Випробування Каменекулаками",b="Замість дозволити новобранцям наосліп забрести до Гаммерфолла, Таллов вимагає показати бойову силу біля огрівського кургану на північний схід від Стромґарда. Плем'я Каменекулаків має в Араті чималу присутність: їхні кремезні огри й силачі — безпосередня загроза для кожного, хто мандрує гірськими стежками. Убивство цих громил і проріджує ворожі сили обабіч дороги, і гарантує, що до застави прибудуть лише вправні воїни."},{t="Доповідь у Гаммерфоллі",b="Коли табір Каменекулаків розчищено, шлях веде на північний схід до Гаммерфолла — застави, названої на згадку про Вождя Оргріма Думхаммера. Там командир Драм Фел зустрічає новоприбулих із утомленою недовірою. Хай Таллов хотів підсилити гарнізон чи просто послав дурнів на смерть, Драм Фел не гає часу й спрямовує перевірених бійців у нескінченні сутички, що загрожують виживанню застави."}},faq={{q="Де починається й закінчується це завдання?",a="Завдання дає Таллов у Таррен Міллі, що в Передгір'ї Гілсбреда. Коли ви вб'єте потрібних ворогів в Аратійському нагір'ї, здайте його Драмові Фелу на заставі Орди Гаммерфолл.",al={"де почати молот може впасти","місце здачі","хто дає молот може впасти"}},{q="Де живуть огри Каменекулаків?",a="Огри Каменекулаків займають помітний земляний пагорб і табір довкола нього на північний схід від руїн Стромґарда в Аратійському нагір'ї.",al={"місце огрів каменекулаків","де огри в араті","пагорб каменекулаків"}},{q="Що таке застава Гаммерфолл?",a="Гаммерфолл — укріплене поселення Орди на північному сході Аратійського нагір'я. Його назвали на честь колишнього Вождя Орґріма Думхаммера, що поліг у бою неподалік, визволяючи орків із таборів для інтернованих.",al={"що таке гаммерфолл","переказ про гаммерфолл","хто заснував гаммерфолл"}},{q="Чому Таллов змушує битися з ограми, перш ніж доповісти в Гаммерфоллі?",a="Гаммерфолл постійно в облозі й конче потребує вправних бійців. Таллов посилає новобранців проти огрів Каменекулаків як на суворе випробування, щоб кожен, хто прибуде на підмогу Драмові Фелу, справді вмів битися, а не став зайвим тягарем.",al={"чому спершу вбити огрів","мотив таллова","чому мене перевіряють"}},{q="Хто такий Драм Фел?",a="Драм Фел — досвідчений орк-воїн і командир у Гаммерфоллі в Аратійському нагір'ї; він організовує оборону від ворожих звірів, огрів, тролів і решток Альянсу.",al={"особа драма фела","командир гаммерфолла","хто такий драм фел"}},{q="Що йде після цього доручення?",a="Доповідь Драмові Фелу одразу веде до кампанії «До зброї!» — низки військових операцій, що мають очистити околиці від загроз, зокрема від племен тролів Сухокорів, які загрожують нагір'ю.",al={"наступне завдання","продовження молот може впасти","що після"}}},fp="19,317,15.441.0,20.463.0,23.415.1,36.207.0,40.143.0,34.212.0,68.259.0,16.198.0,29.206.0"}
P.entries["quest:68"] = {n="Легенда про Сталвана",s="Це розслідування відкриває забутий розділ темної історії Сталвана Містмантла. Запорошений невідправлений лист, витягнутий із занедбаної скрині в Мунбруку, дає відчутний доказ того, де він жив, перш ніж його слід охолов, — і веде назад до записів Даркшира.",h="Це розслідування відкриває забутий розділ темної історії Сталвана Містмантла.",kw={"легенда про сталвана","сталван містмантл","мунбрук","невідправлений лист","покинутий дух","писар долтрі"},ang={["class:Mage"]="Ворожа примара, що стереже скриню, орудує оманливими чарами на кшталт перетворення разом із нищівним прокляттям, натякаючи на протиприродні сили, що тягнуться слідом за Сталваном.",["class:Priest"]="Поява покинутого духа, прив'язаного до звичайної скрині з пам'ятними речами, свідчить про болісний душевний тягар, що не захотів спочити й після смерті.",["faction:Alliance"]="Розгадуючи таємницю Сталвана Містмантла, ви допомагаєте обложеному Даркширу облікувати темні постаті, що перетинали кордони краю."},sec={{t="Забутий слід у Мунбруку",b="Відтворюючи історію Сталвана Містмантла, слідчі знаходять у старій скрині, захованій у Мунбруку, важливий шматок головоломки — запорошений невідправлений лист. Мунбрук, колись квітуче хліборобське поселення, занепав і тепер кишить розбійниками й неспокійними привидами. Сталван пробув тут так недовго, що в людській пам'яті не лишилося й сліду, але цей занедбаний лист безперечно доводить, що він жив у містечку."},{t="Привид біля скрині",b="Порпання в речах Сталвана не минає непоміченим. Потривожена скриня збуджує з тіней покинутого духа, що прагне вберегти лишені таємниці. Привид б'є чарами, що затьмарюють розум, і виснажливим Прокляттям Сталвана, — і це підказує: хай яка доля спіткала цього чоловіка, печаль і темні чари міцно тримаються його речей."},{t="Оновлення міського реєстру",b="Лист, доставлений назад через кордон до Даркшира, дає Писареві Долтрі документ, якого бракувало. Долтрі дивується, що лист так і не відправили, але доказ незаперечний. Коли зв'язок із Мунбруком підтверджено, паперовий слід нарешті може вивести розслідування туди, куди Сталван утік далі."}},faq={{q="Що в старій скрині в Мунбруку?",a="У скрині — Запилений Невідправлений Лист, написаний тоді, коли Сталван Містмантл жив у Мунбруку. Це відчутний доказ того, що він мешкав у містечку, перш ніж зник.",al={"що я знайшов","вміст скрині","лист сталвана"}},{q="Чому, коли відкрити скриню, нападає дух?",a="Біля забутих речей Сталвана досі витає покинутий дух, що здіймається на кожного, хто потривожить скриню. Він володіє моторошною магією: наганяє жах, перетворює й накладає незгасне Прокляття Сталвана.",al={"чому нападає дух","знедолений дух","привид зі скрині"}},{q="Навіщо нести лист Писареві Долтрі?",a="Писар Долтрі відає міськими записами й реєстром у ратуші Даркшира. Йому потрібні певні документи, які підтверджують, де колись жив Сталван, перш ніж він зможе допомогти вистежити його далі.",al={"хто писар долтрі","чому долтрі","ратуша даркширу"}},{q="Чому важливо, що лист так і не відправили?",a="Те, що лист лишився схованим у покинутій скрині, натякає на раптовий від'їзд чи дедалі більшу параною й лише посилює моторошну таємничість, що оповиває мандри Сталвана.",al={"таємниця непослання листа","чому лист не відправили"}},{q="Що робить Прокляття Сталвана?",a="Прокляття Сталвана, яке накладає покинутий дух, що стереже скриню, — виснажливе закляття, яке на десять хвилин послаблює всі основні характеристики жертви.",al={"дебаф прокляття сталвана","прокляття духа"}},{q="Куди веде слід, коли віддати лист Долтрі?",a="Коли Писар Долтрі внесе цей доказ із Мунбрука до міського реєстру, він зможе скерувати ваші розпити туди, куди, як відомо, Сталван подався далі.",al={"що далі","куди після долтрі","наступна підказка"}}},fp="21,277,30.406.0,28.360.1,26.344.0,47.192.0,50.210.0,36.196.0,53.199.0,34.169.0,60.163.0"}
P.entries["quest:683"] = {n="Благання Сари Баллу",s="«Благання Сари Баллу» — сумне доручення від імені дворфійської вдови з Айронфорджа, що тужить за чоловіком. Не маючи сил постати перед своїм монархом у горі, Сара довіряє вам особисте звернення до Короля Маґні Бронзбірда щодо її полеглого чоловіка Саллі Баллу.",h="«Благання Сари Баллу» — сумне доручення від імені дворфійської вдови з Айронфорджа, що тужить за чоловіком.",kw={"сара баллу","благання","король маґні","бронзбірд","айронфордж","удова","саллі"},ang={["faction:Alliance"]="Передавати слово між скорботними громадянами й провідниками Альянсу — означає бачити особисту ціну, яку простий люд платить у війнах за збереження королівства.",["race:Dwarf"]="Доставити благання скорботної вдови просто вашому королю — означає торкнутися глибокої культурної ваги, якої дворфи надають каменю, роду й шануванню жертви предків."},sec={{t="Прохання вдови",b="Отримавши трагічний прощальний лист, піднятий із водних глибин там, де Міст Тандол забрав її чоловіка, Сара Баллу завмирає в жалобі. Не бажаючи, щоб жертва її чоловіка Саллі канула в забуття, вона пише благання, адресоване просто до трону Айронфорджа. Надто розбита горем, щоб самій постати перед придворним етикетом, вона довіряє запечатаний пергамент перевіреному захиснику Альянсу, аби той клопотав перед Королем Маґні Бронзбірдом від її імені."},{t="Аудієнція в короля",b="Нести приватне прохання до Високого Престолу Айронфорджа — не буденна справа, та Маґні Бронзбірд особисто цікавиться відважними захисниками Каз Модану. Отримавши послання, король відкладає державні справи, щоб прочитати скромне благання солдатської вдови, і цим показує свій зв'язок із простими дворфами, які збудували й боронять його гірське королівство."}},faq={{q="Хто така Сара Баллу?",a="Сара Баллу — дворфійка з Айронфорджа, чий чоловік, солдат Саллі Баллу, загинув під час трагедії на Мосту Тандол. Вона живе в місті й свято береже пам'ять про нього.",al={"сара баллу","хто така сара"}},{q="Чому Сара просить мене піти до короля, а не йде сама?",a="Сара вбита горем: вона нарешті дізналася напевно, що спіткало її чоловіка. Вона відчуває, що не зможе зберегти належного спокою, звертаючись до Короля Маґні Бронзбірда на Високому Престолі.",al={"чому сара не йде сама","горе сари"}},{q="Ким був Саллі Баллу?",a="Саллі Баллу — солдат-дворф, що обороняв Міст Тандол. Він загинув у боях на мосту, лишивши розмоклий лист своїй дружині.",al={"саллі баллу","чоловік сари"}},{q="Куди доставити Благання Сари Баллу?",a="Благання треба доставити просто Королю Маґні Бронзбірду на Високий Престол у самому серці Айронфорджа.",al={"де маґні","місце короля маґні","місце здачі"}},{q="Що буде, коли Король Маґні прочитає благання?",a="Благання Сари зворушує Короля Маґні, і він вирішує гідно вшанувати полеглого солдата — це веде просто до завдання «Королівська шана», щоб звести вічний пам'ятник.",al={"продовження завдання","наступне завдання"}},{q="Яка фракція може взятися за це доручення?",a="Це доручення — лише для членів Альянсу, адже йдеться про внутрішні справи дворфів і аудієнцію в Короля Маґні Бронзбірда.",al={"чи орда може це","вимога фракції"}}},fp="18,262,17.468.0,22.359.1,19.156.0,63.195.0,21.158.0,38.100.0,45.158.1,37.137.0"}
P.entries["quest:686"] = {n="Королівська шана",s="Королівська шана — завдання Альянсу, яке дає Король Маґні Бронзбірд на Високому Престолі Айронфорджа. Глибоко зворушений горем Сари Баллу, чий чоловік Саллі поліг, обороняючи Міст Тандол, король вирішує вшанувати загиблого вояка довговічним пам'ятником. Він посилає шукача пригод передати свій королівський наказ Великому Каменяреві Марблстену.",h="Королівська шана — завдання Альянсу, яке дає Король Маґні Бронзбірд на Високому Престолі Айронфорджа.",kw={"королівська шана","маґні бронзбірд","сара баллу","саллі баллу","міст тандол","пам'ятник","марблстен"},ang={["faction:Alliance"]="Полеглі на Мосту Тандол віддали життя, захищаючи важливі для Альянсу шляхи постачання між Каз Моданом і північними королівствами.",["race:Dwarf"]="Це завдання показує, як віддано Король Маґні дбає про свій народ: трон пам'ятає навіть найскромнішого дворфійського піхотинця."},sec={{t="Тягар володаря",b="Отримавши благання Сари Баллу, Король Маґні Бронзбірд не відмахується від скорботної вдови. Він визнає, що простому люду нелегко збагнути жорстоку необхідність війни, та втрата кожного вояка, що бився під стягом Альянсу, тяжко лягає на його сумління. Повернути тих, кого забрала смерть на передовій, Маґні не може, тож він дбає про те, щоб жертву Саллі Баллу ніколи не забули."},{t="Різець каменяра",b="Замість порожніх слів утіхи король вирішує звести на честь Саллі справжній пам'ятник. Він доручає шукачеві пригод донести свою королівську волю й посилає його через увесь Айронфордж до Великого Каменяра Марблстена. Отримавши особисте замовлення короля, майстер-каменяр готується викарбувати в камені пам'ять про полеглого захисника."}},faq={{q="Ким був Саллі Баллу?",a="Саллі Баллу — солдат-дворф, що поліг, воюючи за Альянс під час оборони Мосту Тандол. Його вдова, Сара Баллу, звернулася до Короля Маґні Бронзбірда, коли дізналася про його смерть.",al={"хто такий саллі","переказ про саллі баллу","хто загинув"}},{q="Чому Король Маґні замовляє пам'ятник?",a="Король Маґні несе тягар кожного життя дворфа, втраченого в нескінченних битвах Альянсу. Повернути Саллі вдові він не може, але хоче вшанувати відвагу солдата довговічним королівським пам'ятником.",al={"чому будувати пам'ятник","мотив маґні","мета королівської шани"}},{q="Хто такий Великий Каменяр Марблстен?",a="Великий Каменяр Марблстен — майстер-каменяр Айронфорджа, якому доручають великі міські й королівські будівельні справи. Саме йому Король Маґні довіряє витесати пам'ятник Саллі Баллу.",al={"хто такий марблстен","роль великого каменяра"}},{q="Де відбувається це завдання?",a="Завдання відбувається цілком в Айронфорджі: воно починається на Високому Престолі в Короля Маґні Бронзбірда й веде до Великого Каменяра Марблстена в іншій частині столиці.",al={"де це завдання","місце завдання"}},{q="Що передує цьому завданню?",a="Щоб отримати це завдання, шукач пригод має спершу виконати «Благання Сари Баллу» — передати щирий лист удови просто Королю Маґні Бронзбірду.",al={"попередні завдання","попереднє завдання"}},{q="Чи цей пам'ятник лише для Саллі Баллу?",a="Хоча його замовлено саме на честь Саллі Баллу, щоб утішити його вдову Сару, пам'ятник уособлює шану короля до кожного бійця-дворфа, що гине на службі Альянсу.",al={"кого вшановує пам'ятник","чи лише для саллі"}}},fp="16,352,20.431.0,18.361.0,21.205.0,42.213.0,30.205.0,33.167.0,29.154.0,39.193.0"}
P.entries["quest:689"] = {n="Королівська шана",s="Король Маґні Бронзбірд замовив пам'ятник Саллі Баллу — дворфійському солдату, що загинув, обороняючи Міст Тандол. Щоб ушанувати полеглого воїна з належною гідністю, Великий Каменяр Марблстен посилає мандрівників до Гілсбреду по бездоганний Альтеракський Граніт.",h="Король Маґні Бронзбірд замовив пам'ятник Саллі Баллу — дворфійському солдату, що загинув, обороняючи Міст...",kw={"королівська шана","марблстен","граніт","альтерак","гілсбред","пам'ятник","саллі баллу"},ang={["faction:Alliance"]="Здобуття матеріалів у Гілсбреді зміцнює присутність Альянсу на роз'єднаній півночі й водночас ушановує простого солдата, що віддав життя за спільну справу.",["profession:Mining"]="Гірники розуміють прискіпливість Марблстена: тверді, непіддатливі жили Альтеракського Граніту потребують досвідчених рук, щоб вийняти їх чисто, без тріщин.",["race:Dwarf"]="Ушанування Саллі Баллу торкається серця дворфійської культури, де каменярство, бойова жертва й непохитна вірність Королю Бронзбірду тісно переплетені."},sec={{t="Королівське замовлення",b="Коли Король Маґні Бронзбірд вирішив, що полеглий солдат Саллі Баллу заслуговує на вічну пам'ять, справа лягла просто на плечі найкращого майстра Айронфорджа — Великого Каменяра Марблстена. Баллу поклав життя під час лиха на Мосту Тандол — важливій артерії, що з'єднує дворфійські землі з північними королівствами і зазнала жорстоких нападів диверсантів Темного Заліза. Для Марблстена виконати королівський наказ означає створити скульптуру, яка витримає і час, і війну, щоб дворфійська жертва не лишилася непоміченою чи забутою у Великій Кузні."},{t="Камінь із півночі",b="Майстер-каменяр дворфів не вдовольниться звичайним кар'єрним каменем для королівського замовлення. Марблстен наполягає: подобу Саллі Баллу можна відтворити лише в Альтеракському Граніті — щільному, міцному камені, цінованому за довговічність і чисту фактуру. Складність у тому, щоб його здобути: найкращі поклади лежать довкола Пагорба Дарроу, серед спірних передгір'їв Гілсбреду. Вирушати вглиб неспокійної півночі небезпечно, та дворфійське каменярство вимагає матеріалів, гідних героїзму, який вони увічнюють."}},faq={{q="Хто такий Саллі Баллу?",a="Саллі Баллу — солдат Альянсу, що загинув, обороняючи Міст Тандол під час нищівної диверсії. Вражений його хоробрістю й листом, знайденим при тілі, Король Маґні Бронзбірд звелів звести на його честь вічну статую.",al={"саллі баллу","хто був саллі баллу","переказ про саллі баллу"}},{q="Хто такий Великий Каменяр Марблстен?",a="Великий Каменяр Марблстен — майстер-скульптор і каменяр Айронфорджа. Він працює в Громадській Залі міста, виконує королівські замовлення й страшенно пишається тим, що береться лише за найкращий камінь краю.",al={"великий каменяр марблстен","марблстен айронфордж","хто такий марблстен"}},{q="Навіщо потрібен Альтеракський Граніт?",a="Альтеракський Граніт славиться по всіх Східних Королівствах винятковою щільністю, дрібним зерном і стійкістю до вивітрювання. Марблстен наполягає, що лише камінь такої якості гідний королівського пам'ятника, який простоїть віки.",al={"навіщо альтеракський граніт","призначення альтеракського граніту","що таке альтеракський граніт"}},{q="Де Пагорб Дарроу?",a="Пагорб Дарроу — горбиста місцевість на півночі Передгір'я Гілсбреда, трохи нижче від мису й неподалік кордону Альтераку; Альтеракський Граніт трапляється там у печерах.",al={"де пагорб дарроу","місце пагорба дарроу","знайти пагорб дарроу"}},{q="Що сталося на Мосту Тандол?",a="На Міст Тандол — колосальний міст через прірву між Багнокраєм і Аратійським нагір'ям — напали диверсанти Темного Заліза: вони заклали вибухівку, щоб перерізати шляхи постачання Альянсу, і забрали життя багатьох оборонців.",al={"трагедія мосту тандол","катастрофа мосту тандол","що сталося з мостом тандол"}},{q="Що буде, коли принести граніт Марблстенові?",a="Отримавши Альтеракський Граніт, Марблстен завершує пам'ятник і просить вас доповісти Королю Маґні, що роботу закінчено.",al={"після здачі граніту","поступ статуї марблстена"}}},fp="16,272,18.565.0,18.498.0,20.240.0,30.213.0,30.242.0,21.161.0,34.232.0,54.131.0"}
P.entries["quest:69"] = {n="Легенда про Сталвана",s="Це доручення — переломний момент у пошуках невловимого Сталвана Містмантла: слідчі покидають морок Сутінколісся й вирушають назад до серця королівства. Поспіхом зроблений і закреслений запис у міському реєстрі Даркшира вказує за річку, на Ґолдшир. Далі слід веде до жвавої Корчми «Лев'яча Гордість», де можна дізнатися, куди подався загадковий учитель.",h="Це доручення — переломний момент у пошуках невловимого Сталвана Містмантла: слідчі покидають морок...",kw={"легенда про сталвана","сталван містмантл","ґолдшир","лев'яча гордість","шинкар фарлі","писар долтрі"},ang={["faction:Alliance"]="Розплутування місцевих історій і давно прохололих слідів на південних землях Альянсу вимагає мандрувати між прикордонними заставами на кшталт Даркшира й тихими селищами в серці королівства, як-от Ґолдшир.",["race:Human"]="Ідучи слідами Сталвана, ви проходите самим серцем Королівства Стормвінд і пов'язуєте прокляте прикордоння Сутінколісся зі знайомим затишком Лісу Елвінн."},sec={{t="Підказка в реєстрі",b="Переглядаючи записи Даркшира, Писар Долтрі помічає недогляд у міському реєстрі. Під давнішим записом про Сталвана Містмантла захований ще один пункт призначення — написаний поспіхом і частково закреслений, ніби хтось передумав або хотів приховати свої переміщення. Запис свідчить, що Сталван збирався вирушити на північний захід, до Лісу Елвінн, а саме — до Корчми «Лев'яча Гордість»."},{t="Шлях до Елвінна",b="Сонячні дороги Ґолдшира після похмурих гаїв Сутінколісся — разючий контраст, але тінь Сталванового минулого сягає й сюди. Корчма «Лев'яча Гордість» — жваве перехрестя Лісу Елвінн, що гостинно приймає мандрівників, купців і вояків. Шинкар Фарлі заправляє гамірною залою, тож саме його найкраще розпитати про освіченого мандрівника, що шукав нічлігу."}},faq={{q="Чому слід веде до Ґолдшира?",a="У реєстрі Даркшира під першим записом про Сталвана Писар Долтрі знайшов другу адресу, частково закреслену. З неї ясно видно, що Сталван прямував до Корчми «Лев'яча Гордість» у Ґолдширі.",al={"чому ґолдшир","чому йти до ґолдшира","сталван у ґолдширі"}},{q="Хто такий Писар Долтрі?",a="Писар Долтрі — хранитель записів у ратуші Даркшира. Він веде місцеві реєстри й допомагає відшукувати історичні документи про колишніх мешканців.",al={"долтрі","хто такий долтрі"}},{q="З ким говорити в Корчмі «Лев'яча Гордість»?",a="Вам треба поговорити просто із Шинкарем Фарлі, який тримає Корчму «Лев'яча Гордість» і пам'ятає мандрівників і гостей, що бувають у Ґолдширі.",al={"з ким говорити","контакт лев'ячої гордості","корчмар ґолдшира"}},{q="Чому запис у реєстрі закреслено?",a="Запис стерто лише частково — схоже на квапливу чи навмисну спробу приховати, що Сталван, покидаючи Сутінколісся, подався до Лісу Елвінн.",al={"закреслена примітка","чому закреслено"}},{q="Чи доведеться битися в цьому завданні?",a="Ні. Цей крок розслідування — суто подорож і розпити: ви безпечно йдете з Ратуші Даркшира до шинку в Ґолдширі.",al={"чи буде бій","чи битися з кимось"}},{q="Що таке Корчма «Лев'яча Гордість»?",a="Корчма «Лев'яча Гордість» — серце Ґолдшира в Лісі Елвінн. Це відомий перепочинок для мандрівників, що подорожують між Стормвіндом, Вестфолом і Сутінколіссям.",al={"лев'яча гордість","корчма ґолдшира"}}},fp="21,405,20.410.0,20.404.0,37.199.0,20.172.0,42.150.0,48.160.0,35.150.0,29.176.0"}
P.entries["quest:690"] = {n="Прохання Маліна",s="«Прохання Маліна» — завдання Альянсу від Архімага Маліна з Кварталу магів у Стормвінді. Малін просить досвідчених шукачів пригод вирушити далеко на північ, до Притулку в Аратійському нагір'ї, де експедиція намагається повернути цінні магічні реліквії, покинуті під час падіння Стромґарда.",h="«Прохання Маліна» — завдання Альянсу від Архімага Маліна з Кварталу магів у Стормвінді.",kw={"прохання маліна","архімаг малін","трелейн","притулок","аратійське нагір'я","стромґард"},ang={["class:Mage"]="Для магів, які навідуються до Святилища Чародія, допомога Маліну — це спосіб уберегти цінні арканні дослідження й реліквії, пов'язані зі спадщиною магів Аратора.",["faction:Alliance"]="Притулок — останній хиткий плацдарм Альянсу в Аратійському нагір'ї, тож кожне підкріплення зі Стормвінда вирішальне для утримання краю.",["race:Human"]="Стромґард був колискою людської цивілізації, тож повернення його скарбів — справа честі й збереження історії для синів і доньок Аратора."},sec={{t="Втрачене майно наставника",b="Архімаг Малін, що служить у Святилищі Чародія в Стормвінді, діє від імені свого колишнього наставника, Архімага Трелейна. Коли войовниче королівство Стромґард поринуло в хаос і руїну, Трелейн відчайдушно оборонявся у Вежі Аратора. Змушений покинути свій пост, коли місто впало під натиском ворогів, він залишив там могутні зачаровані речі. Прагнучи повернути ці втрачені артефакти, перш ніж до них дотягнуться ворожі руки, Малін відправляє здібних найманців на північ — на підмогу своїм людям на місці."},{t="Притулок на межі сил",b="Шлях до реліквій Трелейна пролягає через Притулок — обложений бастіон вірних Стромґардові людей у самому серці Аратійського нагір'я. Головний зв'язковий Маліна серед захисників — дворф Скуерто. Проте Притулок затиснули з усіх боків розбійники Синдикату, тролі Сухокори й огри Каменекулаки. Мандрівники швидко помічають, що сил у Скуерто й гарнізону застави геть замало, тож без негайної допомоги теплого прийому годі й чекати."}},faq={{q="Хто такий Архімаг Малін?",a="Архімаг Малін — старший чарівник-людина, що живе у Святилищі Чародія в Стормвінді. Колись він був учнем Архімага Трелейна зі Стромґарда, а тепер зі Стормвінда спрямовує зусилля, щоб повернути магічні напрацювання свого колишнього наставника.",al={"архімаг малін","хто такий малін","малін стормвінд"}},{q="Чому Малінові потрібна допомога в Араті?",a="Стромґард нещодавно впав під облогою, і Архімаг Трелейн мусив тікати з Вежі Аратора. Посланці Маліна в цьому краї намагаються повернути покинуті магічні реліквії Трелейна, але не дають ради й потребують підкріплення.",al={"чому йти до арати","мета місії маліна","чому арати"}},{q="Де знайти Скуерто?",a="Скуерто — дворф-розвідник у Притулку, укріпленому таборі Альянсу біля головного торгового шляху через центр Аратійського нагір'я.",al={"знайти скуерто","місце скуерто","де притулок"}},{q="Що сталося з Вежею Аратора?",a="Вежа Аратора була магічною твердинею в Стромґарді. Коли королівство занепало, Архімаг Трелейн намагався втримати укріплення від розбійників Синдикату й огрів Каменекулаків, але оборона не встояла, і йому довелося тікати.",al={"падіння вежі аратора","що сталося зі стромгардом","вежа трелейна"}},{q="Що буде після доповіді Скуерто?",a="Скуерто, заклопотаний по самі вуха, зустрічає вас неуважно й одразу скеровує до своїх товаришів у Притулку, щоб почати збирати розкидані речі Трелейна.",al={"продовження прохання маліна","наступне завдання після маліна","наступне завдання скуерто"}},{q="Хто такий Архімаг Трелейн?",a="Архімаг Трелейн — визначний маг Стромґарда й наставник Архімага Маліна. Він був одним із головних оборонців столиці Араті, перш ніж королівство впало.",al={"архімаг трелейн","хто такий трелейн","трелейн стромгард"}}},fp="15,296,26.512.0,37.492.0,22.238.0,35.238.0,25.161.0,38.253.0,40.168.0,24.163.0"}
P.entries["quest:6921"] = {n="Серед руїн",s="На прохання Дже'ню Санкреа із Застави Зорам'гар шукачі пригод Орди спускаються в затоплений храм Чорноглибинних Печер, щоб добути Глибинне Ядро. Земляне Кільце шукає цю реліквію, аби розкрити темні стихійні задуми культу Молота Присмерку, що вдерся сюди.",h="На прохання Дже'ню Санкреа із Застави Зорам'гар шукачі пригод Орди спускаються в затоплений храм...",kw={"глибинне ядро","дже'ню санкреа","земляне кільце","руїни місячної святині","молот присмерку","чорноглибинні печери"},ang={["class:Shaman"]="Здобувши Глибинне Ядро, ви безпосередньо послужите місії Земляного Кільця — не дати Молотові Присмерку підкорити духів води й землі.",["faction:Horde"]="Позбувшись загроз у Чорноглибинних Печерах, ви вбережете Заставу Зорам'гар і закріпите спірний опорний пункт Орди на узбережжі Ашенвалю.",["race:Troll"]="Допомагаючи Дже'ню Санкреа, ви підтримуєте родича з Темного Списа, що єднає Орду з охоронцями стихій із Земляного Кільця."},sec={{t="Загроза в глибині",b="Давній храм нічних ельфів у Чорноглибинних Печерах, колись присвячений Елуні, потрапив під владу зловісних сил. Глибоко в його затоплених переходах культисти Молота Присмерку влаштували собі твердиню. Дже'ню Санкреа, шаман із племені Темного Списа, що стоїть на продуваному вітрами березі біля Застави Зорам'гар в Ашенвалі, з дедалі більшою тривогою стежить, як шириться порча, і розуміє: культ хоче підкорити місцеві стихії й обернути їх проти землі та її захисників."},{t="Глибинний камінь",b="Щоб протидіяти задумам культу, Дже'ню доручає звитяжцям Орди здобути Глибинне Ядро з підводного глибинного каменя в Руїнах Місячної Святині. Якщо вправні шамани правильно його розшифрують, ядро відкриває вичерпний літопис стихійних течій і збурень. Маючи цей артефакт, Земляне Кільце сподівається зазирнути за завісу таємних дій Молота Присмерку й уберегти край від стихійної катастрофи."}},faq={{q="Хто дає завдання «Серед руїн»?",a="Завдання дає Дже'ню Санкреа, троль — представник Земляного Кільця на Заставі Зорам'гар на узбережжі Зорам у західному Ашенвалі.",al={"хто дає серед руїн","де взяти завдання","хто починає серед руїн"}},{q="Що таке глибинне ядро?",a="Глибинне ядро — особливий артефакт, схований у затопленому глибинному камені серед руїн. Коли його читають шамани, воно розкриває всю історію діяльності стихій і показує, як місцевих елементалів примушують і використовують.",al={"що таке глибинне ядро","призначення глибинного каменя","що робить ядро"}},{q="Чому Земляне Кільце непокоять Чорноглибинні Печери?",a="Земляне Кільце прагне рівноваги між стихіями. Сектанти Молота Присмерку, що захопили затоплені руїни, оскверняють стихії й силою змушують їх служити своїм темним цілям, загрожуючи стабільності всього краю.",al={"мотив земляного кільця","чому земляне кільце піклується","сектанти чорноглибинних печер"}},{q="Де лежить глибинний камінь?",a="Глибинний камінь лежить під водою в Руїнах Місячної Святині в Чорноглибинних Печерах, тож дослідникам доведеться пірнати, щоб дістати ядро.",al={"де камінь","місце глибинного ядра","руїни місячної святині ядро"}},{q="Чи можуть гравці Альянсу взяти це завдання?",a="Ні. Це завдання лише для Орди: Дже'ню Санкреа діє із застави Орди Зорам'гар і, окрім обов'язків у Земляному Кільці, підтримує присутність Орди в Ашенвалі.",al={"чи це лише для орди","версія для альянсу","чи альянс може серед руїн"}},{q="Хто захопив Чорноглибинні Печери?",a="Печерний храм захопив Молот Присмерку — культ кінця світу, відданий зловісним Древнім Богам, що прагне спотворити стихії й накликати катастрофу.",al={"хто в чорноглибинних печерах","вороги чорноглибинних печер","молот присмерку в печерах"}}},fp="17,251,20.481.0,16.434.0,38.159.0,22.241.0,58.254.0,34.166.0,37.193.0,42.189.0"}
P.entries["quest:6922"] = {n="Барон Аквеніс",s="Здолавши водяного елементаля Барона Аквеніса в Чорноглибинних Печерах, шукачі пригод знаходять Дивну Водяну Кулю з отруйною, смердючою рідиною. Для Дже'ню Санкреа із Земляного Кільця цей артефакт — важливий доказ стихійної порчі, що шириться під Ашенвалем. Дже'ню вірить, що куля покаже, хто зіпсував барона, і не здивується, якщо винними виявляться культисти Молота Присмерку, що ховаються в затоплених руїнах.",h="Здолавши водяного елементаля Барона Аквеніса в Чорноглибинних Печерах, шукачі пригод знаходять Дивну Водяну...",kw={"барон аквеніс","дивна водяна куля","дже'ню санкреа","земляне кільце","молот присмерку","елементаль води"},ang={["class:Shaman"]="Земляне Кільце вважає спотворення духів стихій тяжким порушенням природного ладу. З'ясувати, що отруїло Барона Аквеніса, — ключ до відновлення рівноваги стихій.",["faction:Horde"]="Дже'ню Санкреа діє разом із розвідниками Орди на Заставі Зорам'гар і шукає відважних звитяжців, які очистять зіпсовані води під узбережжям Ашенвалю."},sec={{t="Зіпсоване серце",b="Барон Аквеніс не був звичайним духом води — це могутній елементаль, якого спотворило мерзенне чаклунство в затоплених гротах Чорноглибинних Печер. Загинувши, він лишає по собі Дивну Водяну Кулю — непроникну сферу, в якій хлюпає смердюча рідина, що, схоже, живила й калічила природну сутність істоти. Кулю неможливо пошкодити, а енергії, що в ній таяться, глибоко тривожать тих, хто відчуває рівновагу стихій."},{t="Дослідження Земляного Кільця",b="Дже'ню Санкреа, шаман Земляного Кільця, що стоїть на Зорамському Узмор'ї, одразу впізнає в артефакті доказ протиприродного втручання. Він і його орден давно підозрювали, що Барон Аквеніс став жертвою темних сил, і прямо вказували на культистів Молота Присмерку, які засіли в затопленому храмі. Вивчивши кулю, Дже'ню сподівається не лише довести провину культу, а й з'ясувати, якими саме темними методами той підкоряє й викривлює духів стихій Азероту."}},faq={{q="Що таке Барон Аквеніс?",a="Барон Аквеніс — могутній водяний елементаль, що живе в підземних водах Чорноглибинних Печер. Він не блукає на волі: його осквернили й скували темні чаклуни, які оселилися в зруйнованому храмі.",al={"хто такий аквеніс","бос аквеніс","переказ про барона аквеніса"}},{q="Що таке Дивна Водяна Куля?",a="Дивна Водяна Куля — непроникна сфера, що лишається після перемоги над Бароном Аквенісом. У ній хлюпає мерзенна гнила рідина — джерело зіпсованої енергії, яка підживлювала осквернення елементаля.",al={"водяна куля","дивна водяна куля","предмет завдання аквеніса"}},{q="Навіщо Дже'ню Санкреа ця куля?",a="Як член Земляного Кільця, Дже'ню Санкреа стежить за збуренням стихій по всьому Ашенвалю. Він вивчає кулю, щоб переконатися, чи стоїть за оскверненням Молот Присмерку, і розгадати обряди, якими спотворюють духів.",al={"навіщо нести дже'ню","призначення дже'ню санкреа"}},{q="Хто стоїть за оскверненням Барона Аквеніса?",a="Головні підозрювані — сектанти Молота Присмерку, що загніздилися глибоко в Чорноглибинних Печерах. Їхня присутність у храмі збігається з наругою над святинею й темним єднанням із неприродними сутностями.",al={"хто осквернив аквеніса","аквеніс молот присмерку","сектанти чорноглибинних печер"}},{q="Де знайти Дже'ню Санкреа?",a="Дже'ню Санкреа — шаман Земляного Кільця, що отаборився на узбережжі Зорам на північно-західному березі Ашенвалю, неподалік входу до Чорноглибинних Печер.",al={"де дже'ню","здати аквеніса","куди здати кулю"}},{q="Що буде, коли здати це завдання?",a="Передача кулі веде до дальших розслідувань про збурення стихій у краї, тож шукачі пригод і далі допомагають Земляному Кільцю протистояти дедалі більшій пошесті.",al={"наступне завдання","стихійне лихо"}}},fp="13,454,17.461.0,27.500.1,22.235.0,32.221.0,39.238.0,46.203.0,32.170.0,39.192.0"}
P.entries["quest:6962"] = {n="Смаколики для Діда Зими",s="«Смаколики для Діда Зими» — святкове прохання, яке можна отримати під час Свята Зимової Завіси в Оргріммарі. Веселий символ свята, що сидить біля прилавка Пасовищ Димолісся, геть виснажився, вислуховуючи святкові побажання, тож просить послужливого шукача пригод принести свіжого імбирного печива й молока.",h="«Смаколики для Діда Зими» — святкове прохання, яке можна отримати під час Свята Зимової Завіси в Оргріммарі.",kw={"свято зимової завіси","дід зима","імбирне печиво","пасовища димолісся","кулінарія","долина сили","оргріммар"},ang={["faction:Horde"]="Свято, яке привезли до Оргріммара заповзятливі гобліни з Пасовищ Димолісся, дарує суворому місту воїнів рідкісну мить безтурботних домашніх радощів.",["profession:Cooking"]="Ця святкова традиція дає кухарям-початківцям легку нагоду повправлятися в простій випічці, перетворюючи дикі яйця й сезонні прянощі на святкове імбирне печиво."},sec={{t="Утомлений покровитель зими",b="Хоч Дід Зима й утілює міфічний дух зими та достатку по всьому Азероту, постать, що вітає гостей у Долині Сили, — працьовитий актор, якого найняли Пасовища Димолісся. Довгі зміни, коли доводиться слухати, як мрійливі городяни розповідають про святкові ласощі, неабияк розпалюють апетит. Утомившись лише говорити про сезонні смаколики, Дід Зима охоче доручає перехожим мандрівникам утамувати його жагу до теплої випічки й холодного напою."},{t="Святковий кулінарний дух",b="Щоб виконати прохання Діда Зими, доведеться трохи похазяйнувати на кухні. Шукачі пригод мають купити святкові прянощі в гоблінів-торговців Пасовищ Димолісся, назбирати дрібних яєць диких птахів у нетрях і спекти класичне імбирне печиво. Разом із глеком крижаного молока з місцевої корчми це скромне частування приносить пекареві святковий настрій і невеликий знак вдячності від організаторів свята."}},faq={{q="Хто такий Дід Зима в Оргріммарі?",a="Це актор, якого найняли Пасовища Димолісся, щоб він грав легендарного Діда Зиму під час Свята Зимової Завіси. Він сидить біля їхнього святкового прилавка в Долині Сили, вітає жителів Орди, вислуховує святкові побажання й дарує святковий настрій.",al={"хто дід зима в оргріммарі","дід зима оргріммар","чи це справжній дід зима"}},{q="Яких смаколиків просить Дід Зима?",a="Дід Зима просить п'ять щойно спечених імбирних печив і склянку Крижаного Молока, щоб пережити довгий, виснажливий день із нескінченними відвідувачами.",al={"чого хоче дід зима","яких смаколиків просить","яке печиво потрібне"}},{q="Як спекти імбирне печиво?",a="Рецепт і святкові прянощі продають торговці Пасовищ Димолісся біля святкового прилавка. Пекарі змішують Святкові Прянощі з маленькими яйцями диких птахів і печуть печиво на вогнищі.",al={"як отримати імбирне печиво","рецепт імбирного печива","інгредієнти печива"}},{q="Де взяти Крижане Молоко?",a="Крижане Молоко можна купити майже в будь-якого торговця їжею й напоями, корчмаря чи шинкаря в Оргріммарі та інших великих поселеннях.",al={"де взяти крижане молоко","купити молоко","торговець молоком"}},{q="Чому Дід Зима сам просить їжі?",a="Цілий день слухати, як діти й дорослі гомонять про їжу, подарунки й свята, — від такого актор неабияк голоднішає. Покинути свій пост у Долині Сили він не може, тож просить мандрівних шукачів пригод принести йому перекусити.",al={"чому дід зима просить їжі","чи дід зима голодний"}},{q="Чи є в цього завдання відповідник для Альянсу?",a="Так. Таке саме прохання має Дід Зима в Айронфорджі: він так само просить поборників Альянсу принести імбирне печиво й холодне молоко під час свята.",al={"версія для альянсу","смаколики айронфорджа"}}},fp="30,298,24.478.0,23.452.0,39.285.0,44.177.0,36.224.0,33.144.0,50.248.0,45.180.0"}
P.entries["quest:6981"] = {n="Сяйлива скалка",s="Сяйлива скалка — загадковий самоцвіт смарагдового відтінку, вирваний із темних глибин Печер Стогонів. Під його гладенькою поверхнею клубочиться димчаста сутність, і ця тривожна реліквія спонукає шукачів пригод шукати відповідей у Раджеті й далі.",h="Сяйлива скалка — загадковий самоцвіт смарагдового відтінку, вирваний із темних глибин Печер Стогонів.",kw={"сяйлива скалка","печери стогонів","спаттервалв","фалла сейджвінд","раджет","смарагдове жахіття"},ang={["class:Druid"]="Для друїдів смарагдовий полиск скалки й її димчасте осердя — похмурий доказ того, що Смарагдове Жахіття просочується у світ яви через їхніх полеглих побратимів у Печерах Стогонів.",["faction:Alliance"]="Навіть далеко від дому, у Калімдорі, дослідники з Альянсу розуміють, що темна сила, яка спотворює природу під Пустками, загрожує всьому світові.",["faction:Horde"]="Розкриваючи таємницю скалки, ви допомагаєте захистити життєво важливе перехрестя й торгові шляхи Пусток від неприродних загроз, що гнояться в підземних джерелах.",["race:Tauren"]="Рівновага Пусток дорога для шу'гало, і принесена Фаллі Сейджвінд неприродна реліквія допомагає збагнути скверну, що отруює землі їхніх предків."},sec={{t="Тривожна знахідка",b="Винесена з глибин Печер Стогонів, сяйлива скалка одразу бентежить кожного, хто бере її в руки. Яскраво-зелена й на вигляд суцільна, вона ховає під кришталевою гранню збурені, схожі на туман тіні. Кристал непомітно притягує до себе, вимагає уваги й водночас випромінює глибоко тривожну ауру, що натякає на спотворену природу сплячих друїдів і їхнього прихистку, заполоненого жахіттям."},{t="Пошук відповідей у Раджеті",b="Не знаючи, звідки взявся камінь і що він таке, шукачі пригод несуть артефакт до гоблінського порту Раджет. Там місцевий інженер Спаттервалв оглядає дивовижу й визнає, що її походження лежить поза межами гоблінської механіки й звичайної геології. Натомість він скеровує шукачів угору, на скелясті гребені над печерами, де містик-тауренка Фалла Сейджвінд пильнує неспокійних духів Пусток."}},faq={{q="Що таке Сяйлива Скалка?",a="Це осквернений світний зелений кристал, знайдений глибоко в Печерах Стогонів. Усередині його скляної оболонки клубочиться ледь помітний дим, і кожному, хто придивляється, стає моторошно.",al={"сяйлива скалка","що за зелений камінь","скалка з печер стенань"}},{q="Хто в Раджеті може оглянути скалку?",a="Скалку оглядає Спаттервалв, інженер, що стоїть біля розпорядника польотів у Раджеті. Хоч він інженер, а не друїд, він розпізнає дивну енергію й скеровує вас до того, хто розуміється на духовному.",al={"хто в раджеті огляне скалку","хто в раджеті про скалку","спаттервалв скалка"}},{q="Де знайти Фаллу Сейджвінд?",a="Фалла Сейджвінд стоїть табором на гірських вершинах просто над входом до Печер Стогонів у центрі Пусток.",al={"місце фалли сейджвінд","де фалла","гора над печерами стенань"}},{q="Чи є над головою Спаттервалва знак завдання?",a="Ні. Над Спаттервалвом немає позначки завдання. Треба поговорити з ним і вибрати в розмові пункт про дивну сяйливу скалку, щоб просунутися далі.",al={"спаттервалв без знаку питання","не можу здати спаттервалву","спаттервалв помилка"}},{q="Чому скалка ніби сповнена диму?",a="Димний вир у кристалі відбиває всеосяжну скверну, що спотворює Печери Стогонів, і безпосередньо пов'язаний зі Смарагдовим Жахіттям, яке вдирається в думки сплячих Друїдів Ікла.",al={"чому скалка димить","зелений дим у камені","осквернення в скалці"}},{q="Хто може продовжити ланцюжок після Фалли Сейджвінд?",a="Цей сюжет доступний шукачам пригод і Орди, і Альянсу. Знахідки Фалли Сейджвінд одразу ведуть до завдання «У кошмарах», яке посилає героїв по пораду до їхніх ватажків і старійшин.",al={"чи це лише для орди","сяйлива скалка альянс","хто веде до кошмарів"}}},fp="17,241,22.398.0,26.419.1,26.170.0,37.225.0,32.126.0,52.167.0,47.196.0,54.208.1"}
P.entries["quest:6984"] = {n="Подяка від «Лугів Димолісся»!",s="Це святкове завдання завершує зусилля Пасовищ Димолісся з повернення зимових припасів в Оргріммарі. Після того як шукачі пригод відбили вкрадені ласощі в Огидного Ґрінча, гоблін-торговець Кеймард Копперпінч скеровує їх отримати офіційний святковий знак вдячності від самого Діда Зими.",h="Це святкове завдання завершує зусилля Пасовищ Димолісся з повернення зимових припасів в Оргріммарі.",kw={"свято зимової завіси","дід зима","пасовища димолісся","кеймард копперпінч","ґрінч","подарунок","оргріммар"},ang={["faction:Horde"]="Святкування Зимової Завіси в Оргріммарі поєднує давнє шаманське вшанування зміни пір року з галасливою гоблінською комерцією.",["profession:Cooking"]="Сезонні припаси Пасовищ Димолісся — основа святкової кухні: вони пропонують екзотичні рецепти й святкові інгредієнти, на які кухарі щороку з нетерпінням чекають."},sec={{t="Корпоративне свято",b="Пасовища Димолісся прагнуть заробити на духові Свята Зимової Завіси, продаючи ласощі, рецепти й сезонні радощі по всіх столицях Азероту. Коли на засніжених пагорбах Гір Альтерак у них поцупили партію святкових товарів, торгівля застопорилася. Тепер ласощі повернуто, а з крадієм Ґрінчем розібралися, тож торговець Кеймард Копперпінч поспішає подбати, щоб помічники отримали повну корпоративну подяку — та ще й з належною урочистістю."},{t="Аудієнція в Діда Зими",b="Замість просто подати через прилавок звичайний гаманець з монетами, гобліни домовляються, щоб нагороду вручив сам Дід Зима. Приймаючи гостей біля святкової ялинки в Долині Сили, ця святкова постать є водночас покровителем традиції й почесним символом гулянь. Він шанує тих, хто врятував святкові припаси, сезонним благословенням і Особливим Подарунком Смоквуд Пасчерз."}},faq={{q="Хто посилає мене поговорити з Дідом Зимою?",a="Кеймард Копперпінч, представник Пасовищ Димолісся в Долині Сили в Оргріммарі, посилає вас до Діда Зими, коли ви повернете вкрадені святкові ласощі компанії.",al={"хто починає це завдання","видавець завдання","роль каймарда"}},{q="Чим я заслужив вдячність Пасовищ Димолісся?",a="Ви вистежили Огидного Ґрінча в Горах Альтерак і повернули вкрадені святкові ласощі, врятувавши гоблінам постачання до Свята Зимової Завіси.",al={"за що вдячність","які смаколики вкрали","історія гринча"}},{q="Де в Оргріммарі знайти Діда Зиму?",a="Він сидить під великою прикрашеною ялинкою Зимової Завіси в Долині Сили, просто біля прилавків Пасовищ Димолісся.",al={"місце діда зими","де дід мороз в оргріммарі","ялинка зимового покрову в оргріммарі"}},{q="Хто такий Дід Зима?",a="У давніх переказах Дід Зима — стихійний чи міфічний провісник зміни пір року, що вкриває землю зимовим снігом. На Свято Зимової Завіси смертні, що його заступають, вбираються в його традиційні червоні шати, щоб дарувати добро й роздавати ласощі дітям і шукачам пригод.",al={"хто такий дід зима","чи дід зима справжній","переказ про зимовий покров"}},{q="Що таке Пасовища Димолісся?",a="Пасовища Димолісся — гоблінська кулінарна й сільськогосподарська компанія. На Свято Зимової Завіси вона постачає святкові страви, сезонні інгредієнти й прикраси-дрібнички і Орді, і Альянсу.",al={"переказ про пасовища димолісся","хто такі пасовища димолісся","гоблінський продавець свята"}},{q="Чи отримаю я ще щось після розмови з ним?",a="Так. Від імені компанії Дід Зима вручає вам Особливий Подарунок Смоквуд Пасчерз, а ваші зусилля підвищують репутацію в картелі Стімвідл.",al={"нагорода завдання","набір маскування","подарунок поштою"}}},fp="32,308,19.481.0,33.410.0,47.210.0,52.167.0,50.128.0,27.272.0,27.214.0,51.154.0"}
P.entries["quest:7"] = {n="Зачистка табору кобольдів",s="«Зачистка табору кобольдів» — одне з перших військових завдань, яке Маршал Макбрайд дає щойно прибулим у Долину Нортширу новобранцям. Місія посилає добровольців у північні ліси — зачистити табір кобольдів і не дати агресивним підземним збирачам заполонити землі абатства. Для посвяченого це перше справжнє випробування в обороні кордонів Королівства Стормвінд.",h="«Зачистка табору кобольдів» — одне з перших військових завдань, яке Маршал Макбрайд дає щойно прибулим у...",kw={"зачистка","кобольди","табір","маршал макбрайд","нортшир","новобранці"},ang={["faction:Alliance"]="Заворушення в Нортширі показують, як напружені рідні землі Стормвінда: навіть дрібна навала збирачів вимагає термінового добровольчого ополчення.",["race:Human"]="Для людей Нортширу відігнати кобольдів — базовий громадський обов'язок: захистити абатство й поля від навали."},sec={{t="Долина під тиском",b="Долина Нортширу колись була тихим прихистком для молитви, землеробства й вишколу новачків, та останні роки розтягнули військо Стормвінда до краю. Король зник, королівські гарнізони розпорошені, і дикі істоти та пройдисвіти зухвало натискають на край цивілізованих земель. Маршал Макбрайд організовує місцеву оборону просто біля Абатства Нортшира, покладаючись на свіжих добровольців, щоб придушити загрози, перш ніж вони зірвуть життя абатства чи загрожуватимуть довколишнім виноградникам."},{t="Шкідники в лісі",b="Кобольди за природою боягузливі печерні мешканці, схиблені на свічках: зазвичай їм досить колупатися в підземних жилах подалі від сонця. Однак цілий клан просунувся до північного узлісся Нортширу. Якщо їх не спинити, сама їхня кількість обертає збиральництво на відверті набіги. Наказ Макбрайда полювати на кобольдів має подвійну мету: прорідити їхній авангард і перевірити, чи має новобранець рішучість, потрібну для захисту королівства."}},faq={{q="Хто наказує зачистити табір кобольдів?",a="Наказ дає Маршал Макбрайд. Він стоїть просто біля Абатства Нортшира й від імені Стормвінда відає набором новобранців і безпекою долини.",al={"хто дає це завдання","видавець завдання","роль маршала макбрайда"}},{q="Чому кобольди в північних лісах, а не в шахті?",a="Зазвичай кобольди живуть у норах і шахтах, але в Нортширі їх так розплодилося, що вони вихлюпнулися у відкритий ліс. Серед північних дерев вони влаштували примітивні табори й нишпорять біля краю обжитих земель.",al={"чому кобольди в лісах","кобольди над землею","чому ліси"}},{q="Чому ці кобольди загрожують Стормвінду?",a="Поодинці кобольди — полохливі й кволі шкідники. Але зграєю вони стають зухвалими злодіями: влаштовують засідки на мандрівників, грабують припаси й захоплюють беззахисні застави, а Стормвінд не може цього дозволити, коли його військо й так розпорошене.",al={"чи кобольди небезпечні","чому вбивати шкідників"}},{q="Куди веде це завдання далі?",a="Коли кобольдів на поверхні поменшає, Маршал Макбрайд просить новобранців зазирнути глибше — у Шахту Ехо-Рідж, де саме серце навали кобольдів.",al={"яке завдання далі","наступний крок","після зачистки табору"}},{q="Чи отримує Нортшир постійну допомогу королівського війська?",a="Ні. Через політичну напругу й нестачу війська по всьому королівству після зникнення короля Варіана місцевим командирам на кшталт Макбрайда доводиться покладатися на цивільних добровольців, шукачів пригод і новобранців, щоб берегти кордони.",al={"де вартові стормвінда","чому добровольці"}},{q="Чому кобольди так прив'язані до своїх свічок?",a="Кобольди шанують свічки як головний захист від задушливої темряви підземних тунелів. Полум'я для них означає безпеку, зір і власність, тож вони відомі тим, що люто кидаються на кожного, хто намагається його забрати.",al={"чому свічки","одержимість свічками"}}},fp="19,401,23.483.0,23.457.0,42.162.0,56.240.0,55.252.0,34.160.1,50.223.0,48.225.0"}
P.entries["quest:70"] = {n="Легенда про Сталвана",s="Цей етап розслідування веде шукачів до покинутого листа, що багато років тому лишився в корчмі Ґолдшира. Слід Сталвана Містмантла виводить із Лісу Елвінн до району Каналів Стормвінда.",h="Цей етап розслідування веде шукачів до покинутого листа, що багато років тому лишився в корчмі Ґолдшира.",kw={"легенда про сталвана","шинкар фарлі","лев'яча гордість","наглядач фолсом","канали","стормвінд"},ang={["faction:Alliance"]="Щоб розгадати таємницю Сталвана, доведеться мандрувати серцем Альянсу, відтворюючи давній слід від сонного Ґолдшира до величних каналів столиці.",["race:Human"]="Це розслідування оголює темніші течії Королівства Стормвінд: зло, що терзає Сутінколісся, має коріння, яке тягнеться аж до порога столиці."},sec={{t="Опівнічний жах",b="Коли Шинкаря Фарлі з Корчми «Лев'яча Гордість» питають про Сталвана Містмантла, він пригадує буремну ніч багато років тому. Мандрівний гонець сховався тут від зливи, а близько півночі збіг сходами в цілковитій паніці. У самій нічній сорочці він вибіг просто в темну бурю — і більше його ніхто не бачив."},{t="Покинутий пакунок",b="У панічній утечі гонець покинув сумку й особисту скриню в кімнаті нагорі. Серед забутого вантажу лежав невідправлений лист з ім'ям Сталвана, адресований комусь, хто мешкав у районі Каналів Стормвінда. Скриня стояла недоторкана біля ліжка, доки Фарлі не дозволив її відкрити."},{t="Холодний прийом",b="Давно запізнілий лист веде до Стормвінда, до Наглядача Фолсома, що доглядає майно вздовж каналів біля Парку. Замість вдячності за завершену доставку ім'я Сталвана й вигляд його почерку викликають у Фолсома відразу й ворожість — ознака глибоко прихованих скандалів, пов'язаних із відправником."}},faq={{q="Де зберігається недоставлений лист?",a="Лист лежить у скрині на верхньому поверсі Корчми «Лев'яча Гордість» у Ґолдширі. Підніміться сходами, поверніть праворуч і зайдіть до спальні з ліжком: скриня стоїть у ногах ліжка.",al={"знайти лист","місце скрині сталвана","де скриня"}},{q="Чому лист тоді так і не доставили?",a="Багато років тому кур'єр сховався від зливи в Корчмі «Лев'яча Гордість». Близько півночі щось налякало його так, що він утік у бурю в самій нічній сорочці, покинувши скриню й усі посилки.",al={"чому покинули лист","що налякало гінця","чому гонець втік"}},{q="Де в Стормвінді знайти Наглядача Фолсома?",a="Наглядач Фолсом стоїть біля Каналів у Стормвінді, неподалік краю кварталу Парк.",al={"місце фолсома","де наглядач фолсом","каналізаційний район здача"}},{q="Чому Наглядач Фолсом сердиться, отримавши лист?",a="Фолсом одразу впізнає почерк та ім'я Сталвана й обурюється. Сталван Містмантл лишив по собі гіркі спогади й обурення серед тих, хто знав його в Стормвінді.",al={"чому фолсом сердитий","реакція фолсома","вам вистачає зухвальства"}},{q="Як це пов'язано з бідою в Сутінколіссі?",a="Міська рада Даркшира розслідує зло, що досі не згасло й пов'язане з ім'ям Сталвана Містмантла. Щоб дізнатися, ким Сталван був за життя, треба простежити його колишні мандри й знайомства в Лісі Елвінн і Стормвінді.",al={"чому завдання сутінкового лісу в ґолдширі","як це пов'язано з сутінковим лісом"}},{q="Що буде, коли віддати лист Наглядачеві Фолсому?",a="Різка відповідь Наглядача Фолсома відкриває стормвіндський розділ розслідування: вам доведеться з'ясувати, де колись служив Сталван і які похмурі події сталися в шляхетній родині, якій він служив.",al={"наступний крок","що далі"}}},fp="21,218,17.344.0,19.334.0,16.348.1,37.203.0,46.226.0,46.99.0,57.200.0,49.228.0,57.204.1"}
P.entries["quest:700"] = {n="Королівська шана",s="Королівська шана — останній крок у вшануванні жертви полеглого дворфійського вояка Саллі Баллу. Коли з руїн Лордерону привозять добірний граніт, Великий Каменяр Марблстен з наказу Короля Маґні Бронзбірда висікає в Айронфорджі урочистий пам'ятник.",h="Королівська шана — останній крок у вшануванні жертви полеглого дворфійського вояка Саллі Баллу.",kw={"королівська шана","саллі баллу","марблстен","пам'ятник","граніт","маґні бронзбірд"},ang={["class:Warrior"]="Слова Маґні вшановують самовіддану звитягу вояків передової, таких як Саллі Баллу, що віддали в бою все.",["faction:Alliance"]="Пам'ятник гірко нагадує, якої тяжкої ціни коштували недавні війни Каз Модану й північним королівствам.",["race:Dwarf"]="Для дворфів увічнювати полеглих предків-воїнів у довговічному камені — одна з найсвященніших традицій."},sec={{t="Пам'ятник, висічений у скорботі",b="Король Маґні Бронзбірд замовив вічний пам'ятник на честь Саллі Баллу — хороброго дворфа, що віддав життя, служачи своєму народові. Великий Каменяр Марблстен висік його з добірного граніту, привезеного зі сплюндрованих війною земель Лордерону, і тепер меморіал стоїть в Айронфорджі як вічне свідчення про полеглих вояків, чиї жертви вберігають дворфійське королівство."},{t="Роздуми володаря",b="Почувши, що пам'ятник завершено, Маґні похмуро розмірковує про те, чого не здатен камінь, і про скінченність життя. Він визнає, що висічена скеля ніколи не зрівняється з життям хороброго дворфа, але сподівається, що пам'ятник простоїть віки і майбутні покоління на Азероті не забудуть героїв, які проливали кров, щоб здобути їм завтрашній день."}},faq={{q="Кого вшановує цей пам'ятник?",a="Пам'ятник зведено на згадку про Саллі Баллу, хороброго солдата-дворфа, що віддав життя, звитяжно б'ючись за свій народ і Альянс.",al={"кому цей пам'ятник","пам'ятник саллі баллу","хто загинув"}},{q="Чому камінь брали в Лордероні?",a="Великому Каменяреві Марблстену потрібен був найкращий граніт, гідний вічного королівського пам'ятника. Лордерон дає винятковий камінь, хоча сам цей край після Погибелі лежить у руїнах.",al={"чому камінь із лордерона","лордеронський граніт","камінь марблстена"}},{q="Де відбувається це завдання?",a="Завдання починається у Великого Каменяра Марблстена й закінчується в Короля Маґні Бронзбірда на Високому Престолі Айронфорджа.",al={"куди здати","хто завершує завдання"}},{q="Чому Король Маґні сам замовляє цей пам'ятник?",a="Маґні вважає, що володарі мусять шанувати простих вояків, які боронять їхні королівства. Пам'ятний камінь він бачить як важливе нагадування майбутнім поколінням про високу ціну, яку прості солдати заплатили за їхню безпеку.",al={"чому маґні дбає","маґні бронзобород саллі баллу"}},{q="Що буде, коли пам'ятник завершено?",a="Доповідь Королю Маґні завершує ланцюжок про пам'ятник. Викувана статуя лишається в Айронфорджі урочистим вічним знаком на честь Саллі Баллу.",al={"що далі","продовження королівської шани"}},{q="Яке значення статуя має для каменярства?",a="Великий Каменяр Марблстен — один із найвправніших дворфійських майстрів Айронфорджа. Обробивши привезений лордеронський граніт, він від імені монарха перетворив сирий камінь на гідний твір мистецтва для всього народу.",al={"роль марблстена","ремесло великого каменяра"}}},fp="16,279,26.381.0,24.333.0,38.142.0,42.209.0,33.116.0,55.206.0,44.143.0,47.209.0"}
P.entries["quest:7025"] = {n="Гостинці для Діда Зими",s="Під час Свята Зимової Завіси дворф, що грає Діда Зиму в Айронфорджі, втомлюється й просить перехожих про святковий гостинець. Хто принесе йому свіжих імбирних пряників і крижаного молока, отримає святкову нагороду й щиру вдячність.",h="Під час Свята Зимової Завіси дворф, що грає Діда Зиму в Айронфорджі, втомлюється й просить перехожих про...",kw={"дід зима","зимова завіса","імбирні пряники","молоко","айронфордж","свято"},ang={["faction:Alliance"]="Айронфордж — головний осередок Зимової Завіси для Альянсу: до святкової ялинки у Торгових Рядах з'їжджаються мандрівники з усіх Східних Королівств.",["profession:Cooking"]="Для цього завдання знадобиться трохи кулінарної вправності: замісити дрібні яйця й святкові спеції на імбирні пряники.",["race:Dwarf"]="Для дворфів Дід Зима — давня легенда, пов'язана з титанами й щедротами зими, хоча коли бачиш, як він хрумтить пряниками у Торгових Рядах, міф трохи спускається на землю."},sec={{t="Довгий день у кріслі",b="Хоч Зимова Завіса сягає корінням давніх переказів про титанів і дворфійських міфів про безсмертну постать, закутану в зимовий холод, сучасні гуляння значною мірою тримаються на комерційній підтримці Пасовищ Димолісся. Біля святкової ялинки у Торгових Рядах Айронфорджа звичайний дворф годинами сидить у вбранні Діда Зими й вислуховує святкові побажання і городян, і нетерплячої малечі."},{t="Святкова випічка",b="Цілий день вислуховуючи прохання про подарунки, тутешній Дід Зима неминуче й сам зголоднів. Він не просить нічого вишуканого — лише просту втіху: п'ять свіжих імбирних пряників зі святковими спеціями й склянку крижаного молока, щоб їх запити. Цей обмін дарує хвилинку перепочинку втомленому святковому працівникові й ширить добрий настрій засніженою столицею."}},faq={{q="Де в Айронфорджі знайти Діда Зиму?",a="Дід Зима сидить біля великої святкової ялинки й прилавка Пасовищ Димолісся в Громадській Залі Айронфорджа, серед святкових прикрас.",al={"де дід зима","місце діда зими в айронфорджі","дід мороз айронфордж"}},{q="Як спекти імбирне печиво?",a="Рецепт продають торговці Пасовищ Димолісся неподалік Діда Зими. Щоб спекти печиво, потрібні Уміння куховарити, святкові прянощі від торговця на святі й маленькі яйця диких птахів.",al={"де взяти імбирне печиво","рецепт імбирного печива","як спекти печиво"}},{q="Де взяти Крижане Молоко?",a="Крижане Молоко можна купити майже в будь-якого корчмаря, торговця їжею чи напоями у великих містах Альянсу, зокрема в шинках по всьому Айронфорджу.",al={"торговець крижаним молоком","де купити молоко","молоко айронфордж"}},{q="Чи цей Дід Зима — справжній міфічний персонаж?",a="Ні, це актор-дворф, якого Пасовища Димолісся найняли, щоб на святкуваннях Зимової Завіси він уособлював легендарного персонажа, пов'язаного з титанами.",al={"чи це справжній дід зима","хто чоловік в айронфорджі","чи він справжній дід зима"}},{q="Що дає Дід Зима, коли завдання виконано?",a="Отримавши печиво й молоко, Дід Зима вручає вам Подарунковий Набір Смоквуд Пасчерз — невеличку подяку за старання.",al={"нагорода гостинців для діда зими","пошта від діда зими","набір пасовищ димолісся"}},{q="Чи можуть гравці Орди виконати саме це завдання?",a="Саме це завдання дають в Айронфорджі гравцям Альянсу. У членів Орди є своє рівноцінне завдання — з Дідом Зимою в Оргріммарі.",al={"чи орда може це завдання","гостинці орди для діда зими"}}},fp="29,254,22.401.0,20.427.0,48.152.0,36.212.0,29.152.0,50.150.0,64.134.1,47.154.0"}
P.entries["quest:71"] = {n="Донесення Томасу",s="«Донесення Томасу» — завдання на сході Лісу Елвінн, пов'язане з розслідуванням Вартового Томаса щодо зниклих вартових Стормвінда біля східних річок. Шукач пригод допомагає Вартовому Томасу біля східного мосту: з'ясовує долю його зниклих товаришів і доповідає про становище вздовж річки.",h="«Донесення Томасу» — завдання на сході Лісу Елвінн, пов'язане з розслідуванням Вартового Томаса щодо зниклих...",kw={"донесення","вартовий томас","медальйони","мурлоки","рольф","малакай","ліс елвінн"},ang={["faction:Alliance"]="Загибель Рольфа й Малакая показує вразливість кордонів Лісу Елвінн, де через нестачу людей гинуть навіть звичайні річкові патрулі.",["race:Human"]="Повернуті медальйони полеглих вартових дають частку честі й завершення солдатам Стормвінда, що загинули, захищаючи внутрішні дороги королівства."},sec={{t="Гірке підтвердження",b="Вартовий Томас із жменькою людей тримає переправу, що з'єднує Ґолдшир і Лісозаготівельний Табір Східної Долини. Коли двоє його товаришів, Малакай і Рольф, зникли в прирічкових землях, лишалася надія, що їх просто відрізали або затримали. Повернуті на міст службові медальйони гасять цю надію й підтверджують: обох вартових убили біля річок."},{t="Загроза вздовж води",b="Місяцями керівництво Стормвінда здебільшого відмахувалося від мурлоків як від дрібної річкової прикрості, зосереджуючись на бандитах і далеких кордонах королівства. Розправа над двома озброєними вартовими Стормвінда біля внутрішніх струмків свідчить про організовану жорстокість. Із доказами в руках Томас розуміє, що східне прикордоння Елвінну зазнає справжнього наступу, і вимагає відповіді, перш ніж лісозаготівельні шляхи й поселення захлинуть."}},faq={{q="Де стоїть Вартовий Томас?",a="Вартовий Томас стоїть на кам'яному мосту через річку на сході Лісу Елвінн, на дорозі між Ґолдширом і Лісозаготівельним Табором Східної Долини.",al={"місце томаса","вартовий томас міст","де вартовий томас"}},{q="Ким були Рольф і Малакай?",a="Рольф і Малакай — вартові Стормвінда, яких послали патрулювати схід Лісу Елвінн. Обох здолали й убили мурлоки, що чаїлися на берегах річки й біля Озера Кам'яного Кургану.",al={"хто були рольф і малакай","зниклі вартові елвінн","хто такий рольф"}},{q="Навіщо були потрібні їхні медальйони?",a="Медальйони слугували офіційним посвідченням вартових Стормвінда. Повернувши їх, ви дали Вартовому Томасу незаперечний доказ, що його зниклі люди загинули при виконанні обов'язку.",al={"навіщо медальйони","призначення медальйонів вартових"}},{q="Чому напад мурлоків — така важлива подія?",a="Мурлоків зазвичай вважали примітивними, боягузливими шкідниками, а не смертельною загрозою для вишколених солдатів. Смерть двох озброєних вартових доводить, що річкові племена осміліли й здатні на злагоджені засідки.",al={"чому мурлоки загроза","чи мурлоки небезпечні в елвінні"}},{q="Що буде після доповіді Томасові?",a="Томас просить вас віднести донесення про загибель вартових і дедалі більшу загрозу від мурлоків Маршалові Дуґану в Ґолдшир. Отримавши це донесення, Дуґан пропонує вам обладунок як винагороду.",al={"наступне завдання після доповіді томасові","що робить томас далі"}},{q="Чому Вартовий Томас стоїть на мосту сам?",a="Військо Стормвінда розпорошене по всьому королівству: король Варіан Рінн зник, ресурсів бракує. На віддалених постах на кшталт східного мосту лишилося зовсім мало людей, щоб стерегти важливі шляхи.",al={"чому томас один","сам вартовий на мосту стормвінда"}}},fp="16,314,19.388.0,26.440.0,30.156.0,26.176.1,36.175.1,41.224.1,44.177.1,47.209.0"}
P.entries["quest:7162"] = {n="Випробування",s="«Випробування» — обряд посвяти, який Лейтенант Гаґґердін проводить для новобранців Альянсу, що вступають до Варти Стормпайків в Альтераку. Щоб здобути офіційну Відзнаку Стормпайків, претенденти мусять вирушити до Печер Крижаного Крила, що кишать гарпіями, і повернути встромлений там бойовий стяг. Довести свою мужність у печері — перший крок до просування військовими щаблями експедиції.",h="«Випробування» — обряд посвяти, який Лейтенант Гаґґердін проводить для новобранців Альянсу, що вступають до...",kw={"випробування","лейтенант гаґґердін","варта стормпайків","печери крижаного крила","відзнака стормпайків","долина альтерак","завдання"},ang={["faction:Alliance"]="Експедиція Стормпайків — головна військова справа Альянсу в Альтераку, що поєднує археологічні прагнення дворфів із захистом земель від Орди.",["race:Dwarf"]="Варту Стормпайків здебільшого очолюють дворфи Айронфорджа, що шукають реліквій предків і таємниць титанів, тож це випробування — вступ до одного з найславетніших військових загонів вашого народу."},sec={{t="Мірило мужності",b="Варта Стормпайків веде невпинну війну в Долині Альтерак проти Клану Морозного Вовка. Лейтенант Гаґґердін, що керує силами з табору Альянсу в Горах Альтерак, не хоче посилати зелених новобранців на поле бою без перевірки. Перш ніж дати будь-якому солдатові офіційне місце у Варті, Гаґґердін вимагає доказу вміння й витримки й посилає їх до підступних Печер Крижаного Крила на південний захід від Дун Балдара."},{t="Печери Крижаного Крила",b="Задум випробування простий, а виконання — смертельно небезпечне: прапор Стормпайків стоїть, устромлений глибоко в підземних крижаних тунелях. Печери не порожні: у промерзлих закутках гніздяться люті морозні гарпії, що охоче розривають необачних чужинців. Повернутися з неушкодженим стягом — означає показати, що новобранець уміє долати небезпечну місцевість, вистояти перед жорстокими хижаками й зберегти дисципліну під тиском."},{t="Відзнака Стормпайків",b="Той, хто виживе в печері й поверне стяг, отримує відзнаку новачка Стормпайків і офіційно вступає до експедиційних сил. Як обіцяє Гаґґердін, ця відзнака — не просто дрібничка: це знак звання, який можна вдосконалювати, здобуваючи дедалі більшу честь на полі бою, аж до легендарних відзнак на кшталт Ока Командування."}},faq={{q="Хто такий Лейтенант Гаґґердін?",a="Лейтенант Гаґґердін — офіцер Альянсу в Горах Альтерак, що відає набором і відзнаками Варти Стормпайків. Він випробовує охочих бійців і нагороджує їх за службу військовими знаками.",al={"лейтенант гаґґердін","гаґґердін","хто дає випробування"}},{q="Де Печери Крижаного Крила?",a="Печери Крижаного Крила лежать на південний захід від твердині Альянсу Дун Балдар, серед крижаних просторів Долини Альтерак. Це заплутаний лабіринт підземних тунелів, вирубаних у кризі й камені.",al={"місце печер крижаного крила","де печери крижаного крила","місце прапора"}},{q="Які загрози чатують у Печерах Крижаного Крила?",a="У печерах живуть люті крижані гарпії. Лейтенант Гаґґердін попереджає новобранців, що ці дикі істоти не вагаючись нападуть із засідки й перегризуть горлянку кожному, хто вдереться.",al={"гарпії","що в печерах крижаного крила","гарпії крижаного крила"}},{q="Навіщо Варті Стормпайків це випробування?",a="Битва з орками клану Морозного Вовка жорстока й не прощає помилок. Гаґґердін наполягає на тому, щоб відсіяти необстріляних новобранців, перш ніж вони стануть до основних лав, — так кожен солдат під їхнім прапором зможе битися в суворих умовах.",al={"навіщо випробування","навіщо випробування прапором","посвята стормпайків"}},{q="Яка нагорода за проходження випробування?",a="Пройшовши випробування, новобранець отримує знак посвяченого Стормпайків. Гаґґердін замінює цей знак на сильніші, коли солдат здобуває честь у Долині Альтерак.",al={"відзнака стормпайків","око командування","нагорода випробування"}},{q="Хто такі Морозні Вовки, про яких каже Гаґґердін?",a="Клан Морозного Вовка — клан орків, що живе в Долині Альтерак відтоді, як його вигнали кілька десятиліть тому. Варта Стормпайків вважає їх ворожими дикунами, що стоять на заваді інтересам Альянсу й розкопкам у долині.",al={"морозні вовки","хто морозні вовки","клан морозних вовків"}}},fp="15,389,20.439.0,19.426.0,22.372.0,28.231.0,30.191.0,46.183.0,47.226.0,53.189.0,47.224.0"}
P.entries["quest:72"] = {n="Легенда про Сталвана",s="Цей етап розслідування веде шукачів до Каналів Стормвінда, де Наглядач Фолсом доглядає рештки майна розореної родини Флінтріджів. Шукаючи відповідей про таємничого Сталвана Містмантла, шукачі пригод мусять порпатися в ящиках із родинним добром, протистоячи неспокійним духам, пов'язаним із давньою різаниною.",h="Цей етап розслідування веде шукачів до Каналів Стормвінда, де Наглядач Фолсом доглядає рештки майна розореної...",kw={"легенда про сталвана","наглядач фолсом","флінтріджі","тіллоа","канали","покинутий дух"},ang={["class:Priest"]="Зустріч із заплаканим покинутим духом біля міських каналів відкриває невгамовні муки безневинних душ, убитих передчасно, — і вони прагнуть спокою від Світла.",["faction:Alliance"]="Тиха трагедія родини Флінтріджів розгортається в самій столиці королівства й показує, що навіть найзахищеніші шляхетні роди Стормвінда може знищити насильство."},sec={{t="Відлуння різанини",b="Слід Сталвана виводить із темних гаїв Сутінколісся в саме серце Стормвінда. Біля міських каналів Наглядач Фолсом доглядає те небагато, що лишилося від дому Флінтріджів. За словами Фолсома, ще його батько служив цьому маєтку й мусив відмивати кров після жахливої різанини в домі — трагедії, у центрі якої був Сталван."},{t="Розпродаж зруйнованого дому",b="Родинні статки Флінтріджів вичерпано до дна, довкола кружляють королівські податкові стерв'ятники, тож уцілілі реліквії й спаковані речі родини мають піти з молотка. Пам'ятні речі й папери, що вціліли після кровопролиття, звалені у вантажні ящики на набережній каналу. Щоб натрапити на слід Сталвана, треба розкрити ці запечатані ящики, доки решту майна не розпорошили по колекціонерах усього королівства."},{t="Неспокійна примара",b="Порпання в ящиках померлих не минає непоміченим. Травма вбивств досі чіпляється за врятовані речі й проявляється мстивим покинутим духом, що нападає на кожного, хто нишпорить у родинному добрі. Ця заплакана примара — як вважають, дух юної Тіллоа Флінтрідж — люто прив'язана до речей зі свого раптово обірваного життя."}},faq={{q="Де знайти Наглядача Фолсома?",a="Наглядач Фолсом стоїть біля Каналів у Стормвінді, поруч із купою покинутих транспортних ящиків і хатнього скарбу край води.",al={"місце наглядача фолсома","де фолсом","де наглядач фолсом у стормвінді"}},{q="Що сталося з родиною Флінтріджів?",a="Флінтріджі були заможною родиною, яку знищила раптова й жорстока різанина. Як переказує наглядач, крові було стільки, що батькові Фолсома довелося відмивати маєток, а винним у злочині вважають Сталвана Містмантла.",al={"різанина флінтріджів","що за різанина","хто вбив родину флінтріджів"}},{q="Чому речі родини спаковані в ящики біля каналу?",a="Після трагедії статки Флінтріджів цілком вичерпалися. Під тиском королівських збирачів податків уцілілі речі маєтку спакували в ящики й виставили біля каналів, щоб продати з торгів.",al={"чому майно флінтріджів на аукціон","чому ящики в каналах","довіра флінтріджів"}},{q="Чому, коли відкрити ящик, нападає дух?",a="Жахіття різанини прив'язало душі загиблих до їхніх колишніх речей. Покинутий дух, що з'являється боронити ящики, — за поширеною думкою, тінь Тіллоа Флінтрідж, однієї з убитих дітей.",al={"знедолений дух стормвінд","хто знедолений дух","чому привид у каналах стормвінда"}},{q="Як це пов'язано із Сутінколіссям?",a="Розслідування почалося в Даркширі з розшуку зниклого Сталвана Містмантла. Простежуючи його минуле, слід привів до тих часів, коли він був учителем у родині Флінтріджів у Елвінні й Стормвінді, — аж поки кривава різанина не змусила його піти в тінь.",al={"сталван і сутінковий ліс","чому стормвінд у завданні сутінкового лісу","зв'язок легенди про сталвана з містом"}},{q="Що знаходять у запечатаному ящику?",a="Нишпорячи серед спакованих меблів і особистих речей, можна знайти документи й уривки щоденника, які ще більше розкривають збурений розум Сталвана та його одержимість цією родиною.",al={"що в ящику","підказка запечатаного ящика","вміст ящика флінтріджів"}}},fp="21,349,20.399.0,29.431.0,16.377.1,34.153.0,39.251.0,66.215.0,50.234.0,39.247.0,41.190.0"}
P.entries["quest:729"] = {n="Неуважний дослідник",s="Археолог Голлі втекла до Обердайна після того, як розкопки на півдні Темного Узбережжя заполонили ворожі кам'яні големи. Боячись за свого старшого колегу, вона просить мандрівників мерщій вирушити на південь і врятувати шукача Ремтревела — шанованого дворфського вченого, який, захопившись дослідженнями, геть не помічає смертельної небезпеки.",h="Археолог Голлі втекла до Обердайна після того, як розкопки на півдні Темного Узбережжя заполонили ворожі...",kw={"неуважний дослідник","шукач ремтревел","археолог голлі","кам'яні големи","ліга дослідників","темне узбережжя"},ang={["faction:Alliance"]="Ця місія показує спільну присутність дослідників з Айронфорджа, які намагаються вивчати незнайомі давні землі своїх союзників — нічних ельфів — у Калімдорі.",["race:Dwarf"]="Для дворфів Ремтревел утілює одержиму цікавість і тунельний зір Ліги Дослідників, готових ризикнути життям і здоров'ям заради неописаної скам'янілості."},sec={{t="Небезпечні розкопки",b="Ліга Дослідників за наказом майстра Ґрейвіскера послала археолога Голлі за море, і вона була в захваті, що стане ученицею шукача Ремтревела. Славетного в наукових колах Айронфорджа своїми новаторськими відкриттями Ремтревела відрядили дослідити давні руїни на диких берегах Темного Узбережжя. Та під час розкопок того, що скидалося на рештки давньої великої цивілізації, із землі вирвалися люті кам'яні големи й швидко заполонили розкопки."},{t="Байдужий до загибелі",b="Поки Голлі в паніці тікала по допомогу до порту нічних ельфів Обердайна, Ремтревел і оком не змигнув. Цілком поглинутий знайденими реліквіями, старий шукач стояв по коліна в уламках, анітрохи не зважаючи на незграбні конструкції, що оточили його табір. Хто дістанеться до нього на південь від Обердайна, побачить не переляканого дворфа, а буркотуна, що нарікає на загублені кам'яні щітки й засунуті кудись скам'янілості."}},faq={{q="Хто такий Шукач Ремтревел?",a="Шукач Ремтревел — славетний дослідник-дворф із Ліги Дослідників Айронфорджа. У дворфійських академіях він відомий своїми видатними відкриттями — і так само горезвісний тим, що геть не помічає нічого довкола, коли поруч цінні реліквії.",al={"ремтревел","переказ про шукача ремтревела","хто шукач"}},{q="Чому Археолог Голлі в Обердайні?",a="Голлі приставив до Ремтревела помічницею Майстер Ґрейвіскер. Коли на місці розкопок із землі повилазили небезпечні ґолеми, вона втекла на північ, до Обердайна, шукати підмогу для порятунку.",al={"археолог голлі","голлі оберіжин","чому голлі втекла"}},{q="Що дворфи розкопували на Темному Узбережжі?",a="Експедиція натрапила на сліди прадавнього розвиненого суспільства, похованого під Темним Узбережжям. Ремтревел знайшов загадкову скам'янілість і різні кам'яні артефакти, перш ніж місце розкопок захопили підземні конструкти.",al={"що розкопував ремтревел","місце розкопок на темному узбережжі","скам'янілість ремтревела"}},{q="Де знайти Шукача Ремтревела?",a="Ремтревел — на півдні Темного Узбережжя, серед прадавніх руїн на південь від Обердайна: довкола нього небезпечні ґолеми, а він затято шукає свою кам'яну щіточку й скам'янілість.",al={"де ремтревел","місце ремтревела","знайти шукача ремтревела"}},{q="Хто послав цю експедицію на Темне Узбережжя?",a="Експедицію організувала Ліга Дослідників в Айронфорджі, а призначив її безпосередньо Майстер Ґрейвіскер, який доручив Голлі допомагати Ремтревелу описувати прадавні дива краю.",al={"хто послав голлі","майстер ґрейвіскер","ліга дослідників темне узбережжя"}},{q="Чи справді Ремтревелу щось загрожує?",a="Так. Ворожі ґолеми нишпорять руїнами просто довкола нього. Ремтревел і гадки не має про небезпеку: він цілком поглинений описом знахідок і дивується, куди поділися його інструменти й помічниця.",al={"чи ремтревел мертвий","чи ремтревел живий","допомогти ремтревелу"}}},fp="28,330,14.516.0,17.417.0,28.273.0,41.210.0,46.222.0,40.180.0,38.198.0,30.214.0"}
P.entries["quest:730"] = {n="Біда на Темному узбережжі",s="«Біда на Темному узбережжі» — вступне завдання Альянсу від Головного Археолога Ґрейвіскера в Дарнасусі. Стурбований тим, що вже кілька тижнів не має вістей від команди розкопувачів, посланої за море, він просить мандрівників вирушити до Обердайна й з'ясувати, куди вони зникли. Це завдання поєднує дворфійську наукову експедицію з диким, похмурим краєм Темного Узбережжя.",h="«Біда на Темному узбережжі» — вступне завдання Альянсу від Головного Археолога Ґрейвіскера в Дарнасусі.",kw={"біда на темному узбережжі","головний археолог ґрейвіскер","археолог голлі","обердайн","ліга дослідників","розкопки","темне узбережжя"},ang={["faction:Alliance"]="Це завдання показує, як міцнішає співпраця між Айронфорджем і Дарнасусом, і веде мандрівників між Тельдрассилом і материковим Калімдором.",["race:Dwarf"]="Для дворфів це завдання торкається традиції Ліги Дослідників — копатися в переказах про титанів і давній історії на нових континентах.",["race:NightElf"]="Нічні ельфи можуть дивитися на дворфів із кайлами, що копирсаються в руїнах їхніх предків на узбережжі, з обережною усмішкою або тихою тривогою."},sec={{t="Експедиція, що замовкла",b="У величній столиці нічних ельфів Дарнасусі дворфійські дослідники з Айронфорджа розгадують давні таємниці Калімдору. Головний Археолог Ґрейвіскер послав через воду на Темне Узбережжя загін розкопувачів, щоб відкопати старовинні артефакти. Та минають тижні без жодного листа чи звіту, і Ґрейвіскер дедалі більше тривожиться: він боїться, що його польова команда наразилася на небезпеки, з якими сама не впорається."},{t="Відкопані загрози",b="Ґрейвіскер нарікає, що багато хто в Альянсі вважає дворфійську археологію лише дивацьким захопленням. Та знахідки в Каз Модані переконали його колег, що давня, страхітлива сила загрожує Азероту — від Лордерона до Калімдору. Розкопки в руїнах Темного Узбережжя — не просто наукова справа, а спроба збагнути давні катаклізми й глибоко вкорінені загрози, поховані під прадавньою землею."},{t="Зв'язкова в Обердайні",b="Перепливши протоку від Тельдрассилу до прибережного прихистку Обердайна, мандрівники знаходять у містечку Археолога Голлі, яка вже чекає на них. Із полегшею дізнавшись, що Головний Археолог прислав допомогу, Голлі розповідає, що експедиція справді в скрутному становищі: шукаючи давні реліквії, вона натрапила на біду далі вздовж узбережжя."}},faq={{q="Хто дає завдання «Біда на Темному узбережжі»?",a="Завдання дає Головний Археолог Ґрейвіскер у столиці нічних ельфів, Дарнасусі: він шукає сміливих шукачів пригод, які перевірять, що сталося з його зниклою командою.",al={"хто дає біду на темному узбережжі","видавець біди на темному узбережжі","де взяти біду на темному узбережжі"}},{q="Куди треба вирушити, щоб виконати це завдання?",a="Вам треба переплисти з Дарнасуса до портового містечка Обердайн на Темному Узбережжі, де ви знайдете Археолога Голлі.",al={"куди йти","місце здачі","кому здати"}},{q="Чому дворфійські археологи в Дарнасусі й на Темному Узбережжі?",a="Після нещодавніх відкриттів у Каз Модані дворфійські дослідники почали вивчати прадавні місця по всьому Калімдору, щоб знайти підказки про прадавні сили, які загрожують Азероту.",al={"чому дворфи в дарнасусі","дворфи на темному узбережжі","дворфійська археологія калімдор"}},{q="Що буде, коли знайти Археолога Голлі?",a="Розмова з Археологом Голлі в Обердайні одразу веде до завдання «Неуважний дослідник»: вам доведеться вирушити в дикі місця Темного Узбережжя, щоб знайти Шукача Ремтревела.",al={"що далі","наступне завдання","продовження"}},{q="Чому розкопувальна команда не повідомила про себе?",a="У польових умовах на Темному Узбережжі команда натрапила на несподівані небезпеки й негаразди: її члени розпорошилися й утратили зв'язок із Дарнасусом.",al={"що сталося з розкопками","чому зникли","зникла команда"}},{q="Про яку загрозу говорить Ґрейвіскер?",a="Ґрейвіскер має на увазі знахідки в Каз Модані, які вказують на прадавню всеосяжну небезпеку, що дрімає глибоко в історичних руїнах Азероту.",al={"яка прадавня загроза","попередження ґрейвіскера","загроза кхаз модана"}}},fp="21,355,19.426.0,16.439.0,20.335.1,42.153.0,45.134.0,58.172.0,48.181.0,45.167.0,48.149.0"}
P.entries["quest:731"] = {n="Неуважний дослідник",s="Глибоко в південних руїнах Темного Узбережжя шукач Ремтревел відмовляється покинути розкопки, не маючи чим похвалитися перед Лігою Дослідників. Попри жахливу забудькуватість і навалу ворожих трогів, він наполягає, що спершу відкопає таємничу скам'янілість, а вже тоді відступить. Якщо дворфський дослідник переживе свої безладні пошуки, звістка про те, що він живий, дійде до його помічниці в Обердайні.",h="Глибоко в південних руїнах Темного Узбережжя шукач Ремтревел відмовляється покинути розкопки, не маючи чим...",kw={"неуважний дослідник","шукач ремтревел","троги","розкопки ремтревела","ліга дослідників","темне узбережжя"},ang={["faction:Alliance"]="Убезпечивши Ремтревела та його знахідки, ви зберігаєте важливу дипломатичну й наукову співпрацю між дворфською Лігою Дослідників і нічними ельфами Тельдрассилу.",["race:Dwarf"]="Для дворфів Ремтревел утілює і невтомну пристрасть, і небезпечну впертість Ліги Дослідників — і показує, як відданість давнім знанням про титанів може засліпити вченого перед нагальною небезпекою.",["race:NightElf"]="Калдореї здебільшого насторожено ставляться до дворфських розкопок на Темному Узбережжі, а навала лютих трогів, яку відкопав Ремтревел, підтверджує їхні страхи щодо надто глибокого копання священної землі."},sec={{t="Небезпечні розкопки",b="Розкопки Ремтревела лежать далеко на півдні Темного Узбережжя, серед давніх руїн, які мали зберігати забуті таємниці. Натомість дворфи-копачі натрапили на кубла лютих трогів, які вигнали робітників і взяли табір в облогу. Більшість одразу втекла б до Обердайна, але шукач Ремтревел зациклився на тому, щоб урятувати свої знахідки. Не бажаючи йти з порожніми руками, він лізе просто в пащу небезпеки, щоб добути невловну скам'янілість і виправдати перед Лігою Дослідників витрати на експедицію."},{t="Плутана пам'ять і засідки трогів",b="Оберігати Ремтревела так само прикро, як і небезпечно. Через розпорошеність він ходить по колу розкопками, плутає щітки зі скам'янілостями й блукає між риштуванням і покинутими наметами. Кожна зупинка привертає увагу агресивних трогів, що чатують у затінених закутках кар'єру. Лише коли супровід відбиває хвилю за хвилею підземних бевзів, учений нарешті згадує, де його здобич: він уже віддав скам'янілість Голлі — і радісно повертається до роботи."}},faq={{q="Хто такий Шукач Ремтревел?",a="Шукач Ремтревел — старший польовий дослідник дворфійської Ліги Дослідників. Він працює на Темному Узбережжі, де мав розкопувати прадавні руїни вздовж берега, але через свою надзвичайну неуважність раз у раз опиняється на волосину від смерті.",al={"ремтревел","хто шукач","неуважний шукач"}},{q="Чому Ремтревел досі на місці розкопок?",a="Хоч розкопки заполонили троги, Ремтревел відмовляється повертатися до Дарнасуса без відчутних доказів своєї роботи. Він наполягає, що спершу знайде загадкову скам'янілість для Ліги Дослідників, а вже тоді подумає, чи покидати табір.",al={"чому лишитися на розкопках","чому ремтревел там","чому не втік"}},{q="Звідки взялися троги?",a="Як і чимало дворфійських експедицій, команда Ремтревела вгризлася глибоко в землю й ненароком проломилася до підземних порожнин, де жили троги. Примітивні істоти повалили юрбами й люто розгромили машини, намети й робітників.",al={"чому троги на темному узбережжі","троги темного узбережжя","троги на розкопках"}},{q="Хто така Археолог Голлі?",a="Археолог Голлі — колега й помічниця Ремтревела, що перебуває в прибережному містечку Обердайн. Стривожена довгою відсутністю свого наставника й добре знаючи, який він неуважний, вона наймає мандрівників, щоб ті розшукали його й подбали, щоб він повернувся живим.",al={"голлі","археолог голлі","помічниця ремтревела"}},{q="Що буде, коли знайдеться скам'янілість?",a="After helping Remtravel search the dig, report on his safety to Archaeologist Hollee in Auberdine.",al={"продовження завдання","що далі","після супроводу ремтревела"}}},fp="28,403,21.528.0,35.518.1,28.259.0,39.243.0,31.239.0,28.256.0,38.98.1"}
P.entries["quest:7321"] = {n="Заспокійливий Черепаховий Суп",s="«Заспокійливий Черепаховий Суп» — кулінарне доручення від Крістофа Джеффкоута в Таррен Міллі. Кухар-Відступник прагне спростувати думку, ніби нежиті бракує кулінарного хисту, і варить ситний суп із м'яса місцевих клацозубів. Шукачам пригод доведеться полювати на прісноводних черепах у водоймах Передгір'я Гілсбреда й на берегах Озера Лордамер, щоб опанувати його славетний рецепт.",h="«Заспокійливий Черепаховий Суп» — кулінарне доручення від Крістофа Джеффкоута в Таррен Міллі.",kw={"заспокійливий черепаховий суп","крістоф джеффкоут","таррен мілл","клацозуби","озеро лордамер","кулінарія","завдання"},ang={["faction:Horde"]="Підтримка гарнізону Таррен Мілла — не лише захист його кордонів: добрі припаси й високий бойовий дух допомагають Орді міцно стояти в спірному Гілсбреді.",["profession:Cooking"]="Це доручення дає кухарям змогу опанувати Заспокійливий Черепаховий Суп, перетворивши агресивних рептилій Озера Лордамер і річок Гілсбреда на відновлювальну страву.",["race:Undead"]="Крістоф Джеффкоут уособлює світліший, ремісничий бік Відступників і наполягає, що смерть не притупила його кулінарної пристрасті."},sec={{t="Гастрономія Відступників",b="Загальноприйнято вважати, що Відступники цілком зреклися життєвих утіх, зокрема й мистецтва вишуканої кухні. Крістоф Джеффкоут, що служить у Таррен Міллі, рішуче це заперечує. Хизуючись тим, що його наваристий, заспокійливий черепаховий суп досить смачний, щоб повернути душі з-за могили, Джеффкоут прагне довести, що руки нежиті здатні на тонку, зігрівальну серце майстерність навіть у краю, сплюндрованому чумою й війною."},{t="Полювання на клацозубів",b="Зазвичай Джеффкоут сам збирав складники у водоймах Передгір'я Гілсбреда й на східних берегах Озера Лордамер у сусідньому Альтераку. Проте обов'язки в Таррен Міллі й дедалі ближча присутність сил Альянсу прикували його до місця. Тож він покладається на заїжджих кухарів Орди, які вполюють клацозубів, добудуть їхнє м'ясо й принесуть його, щоб кулінарна традиція жила далі."}},faq={{q="Навіщо кухареві-Відступнику варити гарячий суп?",a="Відступникам не потрібна їжа так, як живим смертним, але такі, як Крістоф Джеффкоут, дуже пишаються своїм ремеслом. Джеффкоут хоче розвіяти упередження, ніби нежить не здатна на витончену майстерність, і жартує, що його фірмовий бульйон і мертвого підніме.",al={"кулінарія нежиті","навіщо суп","чи нежить їсть"}},{q="Де взяти черепахове м'ясо для цього рецепта?",a="Черепахове м'ясо добувають з агресивних черепах-клацунів, що живуть у річках Передгір'я Гілсбреда й Альтераку, а також на берегах Озера Лордамер.",al={"де черепахи","місця черепах","місця щелепників"}},{q="Чому Крістоф Джеффкоут не може сам зібрати інгредієнти?",a="Джеффкоут каже, що в Таррен Міллі в нього повно обов'язків. А ще його дратують сили Альянсу, що підступають неподалік: через них полювати самому стало набагато небезпечніше.",al={"чому крістоф не йде","джеффкоут застряг у місті"}},{q="Чи треба знатися на кулінарії, щоб узяти це завдання?",a="Так. Крістоф Джеффкоут ділиться своїм ремеслом і рецептом лише з тими, хто теж куховарить, хоча високої майстерності для початку не потрібно.",al={"чи потрібна кулінарія","вимога професії кулінарії"}},{q="Яке значення Таррен Мілл має для Орди в Гілсбреді?",a="Таррен Мілл — головна твердиня Орди в Передгір'ї Гілсбреда. Колись це було людське селище, а тепер — укріплена база Відступників та їхніх союзників, що раз у раз сходяться в сутичках із Саутшором і силами Альянсу в краї.",al={"що таке таррен мілл","переказ про таррен мілл"}},{q="Чи черепаховий суп є лише в Орди?",a="Кухарі Альянсу можуть отримати рецепт від місцевих кухарів-людей у Саутшорі, які теж готують із місцевих черепах, але особисте завдання й погляди Крістофа Джеффкоута — лише для Орди.",al={"версія для альянсу","чи альянс може черепаховий суп"}}},fp="22,366,19.433.0,20.388.0,54.306.0,47.175.0,56.200.0,49.170.0,59.255.0,37.208.0"}
P.entries["quest:74"] = {n="Легенда про Сталвана",s="Цей крок розслідування веде до старого ящика з реліквіями Флінтріджів біля каналів Стормвінда. Перебираючи запорошені речі, слідчі знаходять подерту сторінку щоденника — важливу рукописну підказку до минулого Сталвана Містмантла, яка веде до Маршала Гаґґарда в Лісі Елвінн.",h="Цей крок розслідування веде до старого ящика з реліквіями Флінтріджів біля каналів Стормвінда.",kw={"легенда про сталвана","подерта сторінка щоденника","маршал гаґґард","флінтріджі","канали","ліс елвінн"},ang={["faction:Alliance"]="Розслідування давніх нерозкритих справ у серці Елвінна показує, як глибоко особисті жахіття можуть прослизнути повз очі маршалів Стормвінда.",["race:Human"]="Маршал Гаґґард уособлює старше покоління ветеранів Стормвінда, що зберігає важливі спогади про королівство до того, як Перша й Друга війни розлучили родини."},sec={{t="Розкопуючи минуле",b="Порпаючись у запечатаному ящику, повному затхлих реліквій, старих мисливських трофеїв і родинних портретів, слідчі знаходять під керамічною вазою одну-єдину подерту сторінку щоденника. Написаний рукою самого Сталвана Містмантла, цей клапоть дає змогу зазирнути в думки відлюдного вченого ще до того, як сталася трагедія."},{t="Згасаючий зір маршала",b="Маршал Гаґґард, тепер літній і з дедалі слабшим зором, ледве розбирає письмо на пошарпаному пергаменті. Та навіть так характерний почерк тривожно відгукується в його пам'яті й нагадує про документи й події давніх літ — ще до того, як темрява забрала його зір."}},faq={{q="Де стоїть запечатаний ящик?",a="Запечатаний ящик стоїть біля Каналів Стормвінда, просто позаду Наглядача Фолсома, серед спакованих речей родини Флінтріджів. Знайдену там сторінку треба віднести Маршалові Гаґґарду на південний схід Лісу Елвінн.",al={"місце ящика","де ящик","ящик гаґґарда"}},{q="Що в запечатаному ящику?",a="У ящику — запорошені родинні реліквії, сімейний портрет, старі книжки, мисливські трофеї й керамічна ваза, під якою лежить вирвана сторінка зі щоденника Сталвана.",al={"вміст ящика","що в ящику","розірвана сторінка"}},{q="Хто такий Маршал Гаґґард?",a="Маршал Гаґґард — літній відставний офіцер Стормвінда, що самотньо живе на півдні Лісу Елвінн. Попри слабкий зір і кволість, він пам'ятає давні записи й мандрівників, тож він дуже важливий свідок минулих подій.",al={"хто такий гаґґард","переказ про маршала гаґґарда","старий маршал елвінна"}},{q="Чому ця сторінка щоденника важлива?",a="Вирвана сторінка — прямий доказ, написаний рукою самого Сталвана Містмантла. Його характерний почерк і думки, що досі бентежать, допомагають пов'язати розрізнені свідчення із Сутінколісся й Елвінна з його особистим падінням.",al={"чому сторінка важлива","підказка сторінки щоденника","щоденник сталвана"}},{q="Що станеться, коли відкрити ящик?",a="Якщо потривожити залишки минулого Сталвана, неспокійні мерці прокидаються: з'являється мстивий покинутий дух і нападає на тих, хто намагається розплутати трагедію.",al={"поява знедоленого духа","привид після ящика","чому напав привид"}},{q="Куди веде розслідування далі?",a="Коли ви покажете вирвану сторінку Маршалові Гаґґарду, він згадає цей почерк, і його спогади поведуть розслідування далі — до інших уцілілих уламків історії Сталвана.",al={"наступний крок","після розірваної сторінки","куди йти далі"}}},fp="21,309,19.331.0,24.276.1,34.227.0,32.158.0,23.226.0,35.215.0,38.163.0,39.173.0"}
P.entries["quest:741"] = {n="Неуважний дослідник",s="Це доручення доставляє дивний закам'янілий зразок, знайдений на диких пляжах Темного Узбережжя, до представництва Ліги Дослідників у Дарнасусі. Археолог Голлі не хоче покидати свого неуважного колегу в полі, тож довіряє перевезення зразка мандрівникові. Прибуття скам'янілості до столиці нічних ельфів одразу ж викликає жвавий інтерес головного археолога Ґрейвіскера.",h="Це доручення доставляє дивний закам'янілий зразок, знайдений на диких пляжах Темного Узбережжя, до...",kw={"неуважний дослідник","археолог голлі","головний археолог ґрейвіскер","дарнасус","скам'янілість","ліга дослідників"},ang={["faction:Alliance"]="Це завдання показує, як члени Альянсу залежать одне від одного: дворфські дослідники покладаються на мандрівних шукачів пригод, щоб безпечно поєднати віддалені береги Темного Узбережжя з висотами Дарнасуса.",["race:Dwarf"]="Доставляючи скам'янілість Ремтревела, ви виконуєте головну місію Ліги Дослідників: відкопувати найглибше минуле світу й доводити безмежну цінність дворфської завзятості.",["race:NightElf"]="Бачити, як дворфи-копачі виймають давні рештки зі священної землі Темного Узбережжя, буває неприємно, але співпраця з Лігою зберігає узи Альянсу."},sec={{t="Кур'єр до столиці",b="Розкопки шукача Ремтревела на імлистих берегах Темного Узбережжя виявили цікаву скам'янілість, але копати глибше для нього важливіше, ніж дотримуватися процедур. Археолог Голлі не хоче лишати шукача, що весь час кудись забрідає, самого серед небезпечних звірів і ворожих культистів узбережжя, тож лишається пильнувати його. Щоб знахідку задокументували, їй потрібен мандрівник Альянсу, який доставить зразок до Дарнасуса, де дворфська гільдія тримає наукову делегацію."},{t="Дворфська зацікавленість Калімдором",b="Дворфи з Айронфорджа масово перепливли Велике Море під прапором Ліги Дослідників, прагнучи відкопати давні реліквії й утрачену історію з-під землі Калімдору. Отримавши артефакт у столиці ельфів, головний археолог Ґрейвіскер одразу захоплюється хистом Ремтревела знаходити давні скарби. Нічні ельфи вважають свої ліси живими святилищами, а Ліга бачить у давніх землях величезні розкопки, що чекають, поки їх розгадають."}},faq={{q="Що таке загадкова скам'янілість?",a="Це невідомий скам'янілий зразок, який Шукач Ремтревел викопав на узбережжі Темного Узбережжя. Через свою давнину й дивну природу він — цінна знахідка для вчених Ліги Дослідників у Дарнасусі.",al={"загадкова скам'янілість","що за скам'янілість","скам'янілість ремтревела"}},{q="Чому Голлі лишається на Темному Узбережжі?",a="Археолог Голлі вважає своїм обов'язком наглядати за Шукачем Ремтревелом. Під час розкопок він має звичку кудись забрідати й не помічати небезпеки, тож вона не хоче лишати його самого в дикій місцевості, поки знахідки везуть до Дарнасуса.",al={"чому голлі не йде","голлі лишається","чому голлі лишається"}},{q="Хто такий Головний Археолог Ґрейвіскер?",a="Ґрейвіскер — старший представник Ліги Дослідників Айронфорджа, що керує археологічними експедиціями на півночі Калімдору. Він працює в Дарнасусі й вивчає реліквії, які приносять дворфи-копачі з польових робіт.",al={"ґрейвіскер","хто такий ґрейвіскер","головний ґрейвіскер"}},{q="Чому Ліга Дослідників працює в Дарнасусі?",a="Король Маґні Бронзбірд заснував Лігу Дослідників, щоб розкрити походження дворфійського народу й давню історію Азероту. Дружні дипломатичні зв'язки з нічними ельфами дають змогу дворфійським ученим розгортати експедиції з Дарнасуса й вивчати забуті землі Калімдору.",al={"дворфи в дарнасусі","ліга дослідників дарнасус","чому дворфи тут"}},{q="Куди потрапить скам'янілість після Дарнасуса?",a="Головний Археолог Ґрейвіскер оглядає знахідку в Дарнасусі, але відкриття такого масштабу мають описати чи передати далі каналами Ліги — аж до великого музею в Айронфорджі.",al={"куди скам'янілість","наступний крок скам'янілості"}},{q="Де Ремтревел знайшов зразок?",a="Ремтревел відкопав зразок на дикому узбережжі Темного Узбережжя, де повно корабельних уламків, прадавніх руїн і скам'янілих морських істот, старших за Великий Розкол.",al={"де знайшли зразок","місце розкопок ремтревела"}}},fp="28,412,24.493.0,29.498.0,30.220.0,41.236.0,39.222.0,52.284.0,46.205.0,38.177.0"}
P.entries["quest:742"] = {n="Полювання в Ашенвалі",s="«Полювання в Ашенвалі» — поклик для молодих чемпіонів Орди, що навідуються до Тандер Блафа: він кличе їх на північ, під густе склепіння Ашенвалю. Міські глашатаї передають заклик, що скеровує мандрівників до Сенані Тандергарт на Заставу Розщепленого Дерева, щоб узяти участь у випробувальному полюванні.",h="«Полювання в Ашенвалі» — поклик для молодих чемпіонів Орди, що навідуються до Тандер Блафа: він кличе їх на...",kw={"полювання в ашенвалі","сенані тандергарт","застава розщепленого дерева","ашенваль","скелебіжець вітроступ","берег зорам","мисливець"},ang={["class:Hunter"]="Неприборкані хижаки Ашенвалю дають мисливцям змогу опанувати вистежування в густому лісі — зовсім не такому, як сухі відкриті савани півдня.",["faction:Horde"]="Застава Розщепленого Дерева й Берег Зорам — важливі опорні пункти північних шляхів постачання Орди, що потребують свіжих новобранців, аби стримувати диких звірів і ворожих місцевих мешканців.",["race:Tauren"]="Для тауренів, що проходили свої випробування на відкритих рівнинах Малгору, густе й темне склепіння Ашенвалю — незвичне, священне випробування під пильним оком родичів, як-от Сенані."},sec={{t="Поклик із Високого Узвишшя",b="На спокійних висотах Тандер Блафа гінці тримають молоду Орду в курсі нагод за межами Малгору. Скелебіжець Вітроступ несе відкрите запрошення для бувалих шукачів пригод, які прагнуть серйозніших випробувань. Орда закріплюється глибоко в прадавньому лісі на північ від Пусток, тож молодих воїнів кличуть зміцнити ці застави й перевірити свої навички виживання в набагато суворішому краї."},{t="Північний рубіж",b="Ашенваль для Орди — це і багаті ресурси, і серйозна небезпека. Присутність фракції в цьому краї тримається на двох важливих таборах: Заставі Розщепленого Дерева при головному шляху та віддаленій заставі на західному узбережжі, на Березі Зорам. Прибувши на Заставу Розщепленого Дерева, новобранці потрапляють просто під крило Сенані Тандергарт — досвідченої мисливиці-слідопитки, що організовує велике полювання, аби приборкати нетрі й здобути славу для Орди."}},faq={{q="Хто дає це завдання в Тандер Блафі?",a="Це доручення дає мандрівним шукачам пригод Скелебіжець Вітроступ у Тандер Блафі. Його обов'язок — повідомляти вправних бійців про поширення Орди й скеровувати їх до віддалених застав, які потребують допомоги.",al={"хто починає полювання в ашенвалі","видавець полювання в ашенвалі","вітроходець тандер блафа"}},{q="Де розташована Застава Розщепленого Дерева?",a="Застава Розщепленого Дерева — укріплене поселення Орди на сході Ашенвалю. Щоб дістатися туди, ідіть просто на північ через кордон Пусток в Ашенваль, а тоді східною лісовою стежкою вглиб лісу.",al={"місце застави розщепленого дерева","як дістатися застави розщепленого дерева","де розщеплене дерево"}},{q="Хто така Сенані Тандергарт?",a="Сенані Тандергарт — досвідчена слідопитка-тауренка на Заставі Розщепленого Дерева. Вона керує полюванням в Ашенвалі й перевіряє силу й терпіння новобранців Орди в сутичках із місцевими хижаками.",al={"сенані тандергарт","хто така сенані","сенані"}},{q="Чому Орда полює в Ашенвалі?",a="Орда активно просувається в Ашенваль, щоб добувати деревину й закріпитися на стратегічних землях. Саме полювання проріджує небезпечних диких звірів, що загрожують її таборам, і дає молодим шукачам пригод змогу показати себе на незнайомій місцевості.",al={"чому полювати в ашенвалі","мета полювання в ашенвалі","цілі орди в ашенвалі"}},{q="Що таке узбережжя Зорам, про яке йдеться в донесенні?",a="Узбережжя Зорам — прибережний табір Орди на далеких західних берегах Ашенвалю, звернений до моря. Це другорядний морський плацдарм і оплот проти наг і ворожих лісових мешканців.",al={"що таке узбережжя зорам","застава узбережжя зорам","застава зорам"}},{q="Що буде після доповіді Сенані?",a="Коли ви доповісте Сенані Тандергарт, вона привітає вас на заставі й одразу долучить до ширших мисливських завдань, скерувавши вистежувати й долати найлютіших звірів Ашенвалю.",al={"що після полювання в ашенвалі","наступне завдання після сенані","продовження полювання"}}},fp="18,291,28.451.0,21.468.0,39.213.0,35.220.0,27.211.0,38.261.0,51.196.0,39.197.0"}
P.entries["quest:743"] = {n="Небезпека Вітрофурій",s="«Небезпека Вітрофурій» — обряд бойової готовності, який пропонує Руул Іглталон у Селі Бладгуф. Молодим тауренам і шукачам пригод Орди доручають битися з дикими гарпіями-Вітрофуріями, що гніздяться на південно-східних скелях Малгору. Полювання на цих лютих хижаків — важлива перевірка вправності й уміння вижити перед тим, як вирушити за межі племінної батьківщини.",h="«Небезпека Вітрофурій» — обряд бойової готовності, який пропонує Руул Іглталон у Селі Бладгуф.",kw={"вітрофурії","гарпії","руул іглталон","село бладгуф","малгор","воїн","випробування"},ang={["class:Warrior"]="Виклик Руула Іглталона особливо значущий для майбутніх воїнів, яким треба навчитися відбивати стрімкі удари з піке й долати лютих крилатих нападників твердою наземною дисципліною.",["faction:Horde"]="Союзники тауренів, які беруться за випробування Руула, засвідчують відданість захисту серця Орди й здобувають тривку повагу Села Бладгуф.",["race:Tauren"]="Для молодих тауренів розорення гнізд Вітрофурій — водночас захист рівнин і священний перехід до визнаної зрілості під пильним оком старійшин села."},sec={{t="Оцінка вчителя",b="У Селі Бладгуф ветеран-воїн Руул Іглталон приглядається до всіх мандрівників, що проходять серцем Малгору. Від тих, хто входить у зрілий вік або хоче довести готовність до ширших пригод, Руул вимагає відчутного доказу бойового чуття. Щоб вижити за межами затишних долин Малгору, потрібна витримка проти напористих і хитрих ворогів, тож Руул міряє гарт молоді найлютішими місцевими хижаками."},{t="Загроза Вітрофурій",b="Гарпії-Вітрофурії гніздяться вздовж гористого південно-східного краю Малгору — осторонь від уторованих стежок, але постійно загрожуючи звірині й самотнім подорожнім. Хижі й невситимо голодні до свіжої плоті, ці крилаті страхіття покладаються на стрімкі піке та гострі, мов бритва, пазурі. Перемога над ними й здобуті кігті засвідчують не лише силу здолати укорінену загрозу, а й швидкість, потрібну, щоб дати відсіч нападникам із повітря."}},faq={{q="Хто такий Руул Іглталон?",a="Руул Іглталон — досвідчений воїн і наставник-таурен із Села Бладгуф. Він опікується молодими шукачами пригод і влаштовує їм випробування, щоб переконатися, що вони мають досить сили, спритності й витривалості, перш ніж вирушати в ширші й небезпечніші куточки Калімдору.",al={"руул іглталон","хто дає небезпеку вітрофурій","руул"}},{q="Де в Малгорі живуть гарпії Вітрофурії?",a="Гарпії Вітрофурії гніздяться в південно-східних горах Малгора. Свої грубі гнізда вони мостять високо на кручах і схилах передгір'їв, подалі від головної дороги, що перетинає долину.",al={"місце гарпій вітрофурій","де гарпії вітрофурії","гніздо вітрофурій"}},{q="Чому гарпії Вітрофурії — природні вороги тауренів?",a="Гарпії — горезвісно агресивні падальниці, що ревно стережуть свою територію й нападають на кожного, хто наблизиться до їхніх гнізд. У Малгорі зграя Вітрофурій відома ненаситним апетитом до свіжого м'яса й невпинною люттю як до мандрівників, так і до пасовищних тварин, тож вони — вічна загроза для рівнин.",al={"чому таурени б'ються з гарпіями","загроза гарпій у мулґорі","переказ про вітрофурій"}},{q="Якого доказу полювання вимагає Руул Іглталон?",a="Руул просить принести вісім Кігтів Вітрофурій, знятих з убитих гарпій. Відтяті й принесені кігті доводять, що ви здолали головну природну зброю гарпій.",al={"доказ небезпеки вітрофурій","що збирати для руула","ціль небезпеки вітрофурій"}},{q="Чому шукачі пригод мусять пройти це випробування, перш ніж покинути Малгор?",a="Руул вважає лютих гарпій Вітрофурії ідеальною мірою бойової готовності. Якщо шукач пригод не впорається зі швидкістю, люттю й кігтями гарпії, у нього мало шансів проти смертоносніших небезпек, що чатують за захисними кручами Малгора.",al={"мета випробування","чому небезпека вітрофурій","випробування руула"}},{q="Де розташоване Село Бладгуф?",a="Село Бладгуф лежить у центрі Малгора біля Озера Кам'яного Бика, на південь від Великої Брами й Тандер Блафа. Це головний осередок культури, торгівлі й навчання для тауренів, що мандрують рівнинами.",al={"місце села бладгуф","де бладгуф","де руул"}}},fp="23,364,22.435.0,19.451.0,23.275.0,48.204.0,70.299.0,53.188.0,63.257.0,35.220.0"}
P.entries["quest:745"] = {n="Спільна земля",s="Доручене Бейном Бладгуфом у Селі Бладгуф, це завдання посилає молодих шукачів пригод Орди приборкати нищівне браконьєрство тутешніх гнолів-Блідоманів. Знищуючи їхніх чинбарів, білувальників і браконьєрів, ви захищаєте звірину Малгору й осягаєте тауренську філософію життя в рівновазі із Земною Матір'ю.",h="Доручене Бейном Бладгуфом у Селі Бладгуф, це завдання посилає молодих шукачів пригод Орди приборкати нищівне...",kw={"блідогриви","гноли","браконьєрство","бейн бладгуф","село бладгуф","малгор","рівновага"},ang={["class:Druid"]="Друїди розуміють, що нестримне браконьєрство збурює дух рівнин і потребує негайного втручання, щоб зцілити гармонію землі.",["class:Hunter"]="Білувальники й браконьєри Блідоманів — цілковита протилежність справжнього мисливця: вони вирізають диких створінь жорстоко й марнотратно, без жодної поваги.",["faction:Horde"]="Допомога Бейну Бладгуфу зміцнює зв'язок між новими шукачами пригод Орди та проводом молодої тауренської нації.",["race:Tauren"]="Для молодих тауренів відгукнутися на поклик Бейна — важливий крок до осягнення священного обов'язку боронити Малгор і шанувати рівновагу Земної Матері."},sec={{t="Земля без рівноваги",b="Таурени глибоко шанують природний світ: беруть від нього лише потрібне для виживання і в усьому вшановують Земну Матір. Гноли-Блідомани, що осіли на південь від Села Бладгуф і в печері на заході, такої поваги не знають. Замість полювати в міру, вони завзято вирізають звірину по всіх рівнинах, залишаючи по собі обдерті туші й зруйновані оселища. Для народу, що прагне збудувати мирну батьківщину в Малгорі, таку безоглядну різанину терпіти не можна."},{t="Коли слова безсилі",b="Бейн Бладгуф спершу сподівався залагодити справу мирно й намагався завести розмову з гнолами-зайдами. Блідомани відкинули всі пропозиції, відповівши на дипломатію ворожістю та новим спустошенням. Переконавшись, що перемовини марні, Бейн удається до сили. Молодих сміливців посилають просто в мисливські табори гнолів — приборкати браконьєрів, чинбарів і білувальників, доки трави не зазнали невиправної шкоди."},{t="Коло життя і смерті",b="Це доручення — водночас обряд посвяти й моральний урок для майбутніх звитяжців. Коли шукач пригод повертається після вилову, Бейн нагадує: відбирати життя не можна зі злоби — лише з потреби зберегти гармонію. Життя і смерть — єдине коло, де одне не може квітнути без другого; цю основоположну істину має нести далі кожен захисник Малгору."}},faq={{q="Хто дає це завдання?",a="Це завдання дає Бейн Бладгуф, син Верховного Вождя Кайрна Бладгуфа, у Селі Бладгуф у центрі Малгора.",al={"хто дає завдання","хто починає спільну землю","завдання бейна"}},{q="Чому таурени виступили проти гнолів Пейлмейн?",a="Гноли Пейлмейн бездумно винищують звірів Малгора, виснажуючи стада й не шануючи природної рівноваги. До того ж вони відкинули всі спроби тауренів мирно домовитися.",al={"чому вбивати гнолів","проблема пейлмейнів","що зробили гноли"}},{q="Де живуть ці гноли?",a="Пейлмейни мають табори на південь від Села Бладгуф і живуть у печерах Скелі Пейлмейн на заході.",al={"місця гнолів","табір пейлмейнів","де знайти пейлмейнів"}},{q="Чи намагалися таурени спершу помиритися?",a="Так. Бейн зауважує, що таурени кілька разів намагалися домовитися й поділити землю, але гноли зневажливо відкидали кожну мирну пропозицію.",al={"чи таурени розмовляли з гнолами","дипломатія з пейлмейнами"}},{q="Якого уроку Бейн намагається навчити?",a="Бейн хоче, щоб молоді оборонці зрозуміли: смерть і життя — це нерозривне коло. Іноді доводиться відбирати життя, щоб захистити рівновагу, але робити це слід завжди з глибокою шаною до Земної Матері.",al={"урок бейна","значення спільної землі"}},{q="Хто такі гноли Пейлмейн?",a="Це примітивне плем'я, схоже на гієн, що живе в Малгорі й відоме блідим хутром, ревною агресією до чужих на своїй землі та цілковитою зневагою до гармонії рівнин.",al={"хто такі пейлмейни","плем'я пейлмейнів"}}},fp="16,309,21.523.0,15.429.0,28.396.0,21.114.0,49.178.0,31.122.0,39.155.0,42.222.0,28.160.0"}
P.entries["quest:746"] = {n="Дворфські розкопки",s="«Дворфські розкопки» — завдання в Малгорі, яке дає Бейн Бладгуф у Селі Бладгуф. Побоюючись, що дворфські розкопки розлютять тутешніх звірів і споганять священну землю, Бейн доручає молодим захисникам Орди зірвати їхню роботу: відібрати й потрощити їхні кайла.",h="«Дворфські розкопки» — завдання в Малгорі, яке дає Бейн Бладгуф у Селі Бладгуф.",kw={"дворфи","розкопки","кайла","бейн бладгуф","село бладгуф","малгор","ліга дослідників"},ang={["class:Shaman"]="Шаман розуміє: недбалі розкопки, що тривожать підложжя, порушують рівновагу стихій і сіють неспокій серед духів і створінь землі.",["faction:Horde"]="Вторгнення дворфів, союзних Альянсу, в серце земель Орди підважує крихкий мир, усталений після Третьої війни, і зухвало нехтує племінними кордонами.",["profession:Mining"]="Гірники шанують багатства, приховані в камені, та дворфські методи в Малгорі оминають повагу й гармонію, обираючи безоглядне руйнування.",["race:Tauren"]="Тіло Земної Матері священне, і бачити, як чужинці вгризаються в пагорбисті степи Малгору, — образа, що вимагає негайної і твердої відповіді."},sec={{t="Зайди на пагорбах",b="На північний захід від Села Бладгуф дворфські старателі заходилися розмічати розкоп серед пагорбів Малгору. Ліга Дослідників та її землекопні бригади шукають реліквії титанів і таємниці земних надр по всьому Калімдору, та їхні роботи рідко зважають на землі й звичаї тубільців. Для тауренів земля — жива мати, яку належить шанувати, а не обдирати й видовбувати заради каміння й металу."},{t="Захист священної землі",b="Бейн Бладгуф розуміє: дворфські машини й безперервні вибухи загрожують крихкій гармонії рівнин. Окрім самого руйнування, гуркіт тривожить тутешню звірину й доводить рівнинних кодо до шалу. Розбиваючи знаряддя старателів просто біля їхніх кузень, таурени сподіваються послати недвозначне застереження й зупинити вторгнення, доки не сталося непоправного."}},faq={{q="Чому дворфи копають у Малгорі?",a="Дворфійські шукачі вірять, що глибоко в землі центрального Калімдору сховані таємниці й артефакти. Але через зневагу до племінних земель і грубі методи видобутку вони опинилися у відкритому протистоянні з тауренами.",al={"чому дворфи в мулґорі","чому шукачі тут","дворфійські розкопки мулґор"}},{q="Хто дає завдання «Дворфські розкопки»?",a="Завдання дає Бейн Бладгуф, юний син Верховного Вождя Кайрна Бладгуфа, у Селі Бладгуф у центрі Малгора.",al={"хто дає дворфські розкопки","видавець дворфських розкопок"}},{q="Чому Бейн хоче, щоб інструменти розбили, а не просто вкрали?",a="Бейн хоче зробити спорядження цілком непридатним, щоб негайно зупинити розкопки. Знищення інструментів у кузнях — ясний знак, і символічний, і практичний: ця земля не віддасть своїх таємниць грубій силі й нарузі.",al={"чому розбити кайла","знищення дворфійських інструментів"}},{q="Як розкопки впливають на звірів Малгора?",a="Гучне копання й глибокі рани в землі страшенно тривожать місцевих тварин, особливо величезних кодо, що блукають пагорбами: мирні стада стають дратівливими й агресивними.",al={"чому звірі розлючені","вплив розкопок на звірів"}},{q="Де можна розбити кайла?",a="Кайла можна розтрощити на брухт у будь-якій справній кузні. Гравці можуть скористатися кузнею просто в таборі дворфійських розкопок або віднести кайла до ковалів Тандер Блафа.",al={"де кузня","розбити кайла в кузні"}},{q="Чи пов'язане це завдання з ширшою присутністю Ліги Дослідників у Калімдорі?",a="Так. Експедиції дворфів з Айронфорджа заснували застави по всьому Калімдору — у Малгорі, Пустках і на півдні Калімдору, — і часто розпалюють сутички з расами Орди за володіння землями й святинями.",al={"ліга дослідників мулґор","айронфордж у калімдорі"}}},fp="15,289,24.392.0,26.388.0,35.232.0,36.137.0,63.245.0,52.187.0,31.201.0,75.232.0"}
P.entries["quest:747"] = {n="Полювання починається",s="«Полювання починається» — основоположний обряд посвяти для молодих шукачів пригод у Таборі Нарачі на Плато Червоної Хмари. За дорученням Ґрулла Гоквінда посвячені вирушають полювати на тутешніх довгоступів, щоб забезпечити селище м'ясом і пір'ям. Виконання цього завдання — перший крок до поваги Вождя Гоквінда й, зрештою, до права ввійти в Тандер Блаф.",h="«Полювання починається» — основоположний обряд посвяти для молодих шукачів пригод у Таборі Нарачі на Плато...",kw={"полювання","довгоступ","ґрулл гоквінд","табір нарачі","плато червоної хмари","вождь гоквінд","м'ясо"},ang={["class:Hunter"]="Вистежування прудких довгоступів Плато Червоної Хмари — найперша практична вправа у влучності, читанні слідів і шані до звірів, які вас годують.",["race:Tauren"]="Для молодих шу'хало перші вполювані довгоступи плато — важливий обряд посвяти, що підтверджує ваш зв'язок із землею та обов'язок годувати Табір Нарачі."},sec={{t="Прожиток племені",b="На висотах Плато Червоної Хмари виживання й традиція сплетені воєдино. Таурени полюють із потреби — щоб нагодувати й одягти свій народ, — але бачать у вистежуванні та гонитві й важливе випробування дисципліни, і змагання. Коли запаси Табору Нарачі убожіють, громада звертається до своєї молоді, щоб та добула свіжого м'яса довгоступів для кухні й міцного пір'я для племінного вбрання."},{t="Здобути визнання",b="Жоден майбутній герой не сходить із Плато Червоної Хмари на простори Малгору, не довівши своєї вартості. Ґрулл Гоквінд — перший суддя вдачі новачків: він наполягає, що спершу треба показати свою спроможність, а вже потім ставати перед його батьком, Вождем Гоквіндом. Чисте полювання засвідчує не лише самостійність, а й відданість підтримці племені."}},faq={{q="Хто дає це завдання?",a="Це завдання дає Ґрулл Гоквінд у Таборі Нарачі. Він син ватажка поселення, Вождя Гоквінда, і перший наставник молодих мисливців і шукачів пригод на Плато Червоної Хмари.",al={"хто дає завдання","хто починає полювання","ґралл гоквінд"}},{q="Чому полюють саме на рівнинних довгоступів, а не на інших звірів?",a="Рівнинних довгоступів на плато сила-силенна, і вони дають і поживне м'ясо, щоб поповнити запаси їжі, що тануть, і міцне пір'я для традиційного одягу й прикрас тауренів.",al={"чому довгоступи","м'ясо й пір'я довгоступів","полювання на довгоступів"}},{q="Чому я мушу показати себе, перш ніж побачу Вождя Гоквінда?",a="Таурени високо цінують практичну користь і вправність у полюванні. Ґрулл Гоквінд вимагає, щоб учні показали основи виживання й відданість поселенню, перш ніж вождь прийме їх і довірить глибші обов'язки.",al={"чому довести перед гоквіндом","схвалення вождя гоквінда","чому спершу полювання"}},{q="Яка ширша мета цих випробувань на Плато Червоної Хмари?",a="Плато — це місце випробувань. Щойно молодий таурен доведе свою спроможність Вождеві Гоквінду й старійшинам Табору Нарачі, його вважають готовим спуститися на широкі рівнини Малгора й увійти до столиці, Тандер Блафа.",al={"мета випробувань плато","чому на плато червоної хмари","вихід із плато червоної хмари"}},{q="Що далі, після цього полювання?",a="Принісши м'ясо й пір'я, ви здобуваєте схвалення Ґрулла — і це веде просто до завдання «Полювання триває», де учні вистежують більшу й невловимішу дичину на плато.",al={"наступне завдання","продовження","що після полювання починається"}},{q="Чи таурени полюють лише заради виживання?",a="Їжа й ресурси на кшталт шкіри, кісток і пір'я надзвичайно важливі, але таурени полюють і задля змагання та духовного єднання: так вони гострять чуття, що тримають їхні племена пильними й сильними.",al={"філософія полювання тауренів","полювання заради спорту","чому таурени полюють"}}},fp="15,361,20.383.0,19.382.0,21.181.0,53.182.0,59.252.0,59.239.0,27.181.0,33.203.0"}
P.entries["quest:748"] = {n="Отруйна вода",s="«Отруйна вода» відкриває зусилля тауренів очистити священні криниці Малгору від забруднення. За дорученням Малла Тандергорна в Селі Бладгуф молоді захисники Орди збирають на рівнинах природні складники для цілющого ритуального тотема.",h="«Отруйна вода» відкриває зусилля тауренів очистити священні криниці Малгору від забруднення.",kw={"отруйна вода","криниця","малл тандергорн","село бладгуф","малгор","тотем","гобліни"},ang={["class:Druid"]="Гобліни, що труять прісні джерела, — прямий напад на природну рівновагу, який вимагає негайної відповіді, щоб уберегти крихку флору й фауну Малгору.",["class:Shaman"]="Відновлення забруднених вод тотемами, наснаженими силою звірів, показує основи тауренського шаманізму: працювати разом із тутешньою звіриною, щоб залагодити збурення стихій.",["race:Tauren"]="Споганення прісної води б'є в самісіньке осердя дарів Земної Матері, тож обряд очищення — основний обов'язок кожного таурена, який дорослішає в Малгорі."},sec={{t="Споганена земля",b="Трав'янисті рівнини Малгору — священна земля тауренів, але підступні сили почали зазіхати на її життєдайну жилу. Малл Тандергорн, старійшина з Села Бладгуф, виявляє, що зайди-гобліни зі своїми посіпаками затруїли дорогоцінні криниці, які напувають племена й тутешню звірину. Це забруднення б'є просто в духовне серце кочового народу, що лише нещодавно тут осів."},{t="Збирання сутності природи",b="Проти промислової отрути Малл покладається на традиційний тауренський шаманізм, а не на грубі зілля. Щоб очистити Водяну Криницю Вінтергуфів, треба виготовити могутній ритуальний тотем, насичений життєвою силою корінних хижаків Малгору. Він посилає мисливців на південно-західні рівнини — по лапи степових вовків і кігті дорослих довгоступів, закликаючи міць самої землі, щоб та зцілила власні рани."}},faq={{q="Хто отруїв криниці в Малгорі?",a="Священні водопої по всьому Малгору забруднили гоблінські загарбники та їхні наймити. Їхнє руйнівне промислове виробництво й зневага до природної рівноваги загрожують і племенам тауренів, і місцевим звірам.",al={"хто отруїв криниці","хто отруїв мулґор","хто забруднив воду"}},{q="Навіщо Маллові Тандергорну вовчі лапи й пазурі рівнинних довгоступів?",a="Малл виготовляє традиційні очисні тотеми з частин, узятих від місцевих звірів Малгора. Залучаючи природних духів і силу хижаків рівнин, він створює осередок сили, якого досить для обряду очищення води.",al={"чому вовчі лапи","чому кігті довгоступів","матеріали тотема"}},{q="Яку криницю готується очистити це завдання?",a="Це завдання збирає матеріали саме для очисного тотема для Водяної Криниці Вінтергуфів — першої з низки забруднених криниць, які треба обрядово очистити.",al={"яка криниця","яка водяна криниця"}},{q="Де знайти Малла Тандергорна?",a="Малл Тандергорн живе в Селі Бладгуф — головному поселенні тауренів у центрі Малгора, біля вод Озера Кам'яного Бика.",al={"місце малла тандергорна","де малл","де здати отруйну воду"}},{q="Де знайти потрібних вовків і рівнинних довгоступів?",a="Степові вовки й дорослі рівнинні довгоступи блукають пологими рівнинами на південний захід від Села Бладгуф.",al={"де степові вовки","місця довгоступів","мисливські угіддя"}},{q="Що буде, коли Малл отримає лапи й пазурі?",a="Малл з'єднує зібрані частини в Тотем Очищення Вінтергуф і доручає вам віднести його просто до Водяної Криниці Вінтергуфів, щоб звершити обряд очищення.",al={"наступне завдання після отруйної води","що робити далі"}}},fp="12,238,17.428.0,26.435.0,40.234.0,65.236.0,46.172.0,34.141.0,58.96.0,53.172.0"}
P.entries["quest:749"] = {n="Сплюндрований караван",s="Морін Клаудсталкер посилає мандрівників оглянути рештки каравану Венчурної Компанії, розгромленого біля північного берега Озера Кам'яного Бика. Хоч таурени й спалили валку, помщаючись за втрачених товаришів, гоблінські збирачі повернулися по вцілілий вантаж. Огляд уцілілих ящиків із припасами відкриває справжній промисловий розмах дій Венчурної Компанії в Малгорі.",h="Морін Клаудсталкер посилає мандрівників оглянути рештки каравану Венчурної Компанії, розгромленого біля...",kw={"караван","венчурна компанія","морін клаудсталкер","озеро кам'яного бика","малгор","гобліни","гірнича справа"},ang={["faction:Horde"]="Нестримне корпоративне просування в Малгор загрожує стабільності Тандер Блафа, тож розвідники Орди мають зірвати постачання Венчурної Компанії.",["profession:Mining"]="Міцні ящики й супровідні записи свідчать про напористу розвідку й видобуток руд, які Венчурна Компанія розгорнула по всьому Малгору.",["race:Tauren"]="Споганення рівнин машинами Венчурної Компанії та вирубка лісу б'ють просто по вашій прабатьківщині, тож повернути й знищити їхні припаси конче важливо для захисту Малгору."},sec={{t="Відплата біля озера",b="Обгорілі рештки на північному березі Озера Кам'яного Бика — слід стрімкого удару тауренів. Оплакуючи двох товаришів, убитих у попередній сутичці, Морін Клаудсталкер зі своїми воїнами влаштував засідку на озброєну валку з припасами Венчурної Компанії. Прагнучи знищити справу зайд, таурени підпалили вози й покинули димуче згарище, певні, що вогонь поглине все, що гобліни хотіли вивезти."},{t="Незавершена справа",b="Невдовзі таурени помітили збирачів Венчурної Компанії, які нишпорили серед почорнілих уламків, — отже, вогонь не знищив найважливішого вантажу. Не бажаючи наосліп ризикувати новими життями, Морін посилає розвідників оглянути згарище. Серед закіптюжених уламків лежать цілі ящики з тавром гірничого відділу Венчурної Компанії — спаковані й призначені для центральних переробних потужностей."}},faq={{q="Чому караван знищили?",a="Морін Клаудсталкер і його воїни-таурени влаштували засідку й підпалили караван на відплату за двох своїх розвідників, загиблих у попередній сутичці з Венчурною Компанією.",al={"хто знищив караван","чому караван спалено","напад на караван"}},{q="Де Сплюндрований Караван?",a="Обгорілі вози стоять на північному березі Озера Кам'яного Бика, на схід від Села Бладгуф у Малгорі.",al={"місце каравану","де караван","місце сплюндрованого каравану"}},{q="Чому гобліни повертаються до решток каравану?",a="Венчурна Компанія прислала збирачів, бо вогонь знищив не весь вантаж. Вони намагаються забрати міцні ящики з припасами, позначені для відправки до їхніх головних переробних підприємств.",al={"чому гобліни тут","збирачі венчурної компанії","чого хочуть гобліни"}},{q="Що в ящиках із припасами?",a="Ящики мають знак Відділу гірничої справи Венчурної Компанії, а всередині — мінеральна сировина з позначками для очищення й переробки на головних заводах компанії.",al={"вміст ящиків","що в ящику","запечатаний ящик з припасами"}},{q="Хто такий Морін Клаудсталкер?",a="Морін Клаудсталкер — розвідник і слідопит-таурен, що стоїть на схід від Села Бладгуф; йому доручено стежити за ворожими вторгненнями в центральний Малгор, насамперед з боку Венчурної Компанії.",al={"хто такий морін","роль моріна клаудсталкера"}},{q="Що цей караван розкриває про Венчурну Компанію?",a="Він показує, що Венчурна Компанія в Малгорі — не просто розвідувальна команда, а організоване промислове видобування з озброєними шляхами постачання й мережею переробки.",al={"присутність венчурної компанії в мулґорі","чому гобліни в мулґорі"}}},fp="19,390,23.438.0,19.408.0,30.169.0,37.102.0,46.197.0,33.171.0,26.190.0,56.201.0"}
P.entries["quest:7493"] = {n="Подорож тільки починається",s="«Подорож тільки починається» — завдання Орди в Оргріммарі для вправних шкірників після перемоги над Оніксією. Володар Рунтак визнає майстерність героя й відкриває йому рідкісну техніку виготовлення захисних плащів із луски матері виводку. Це важливе ремесло готує Орду до смертоносного полум'я Шпилю Блекрок.",h="«Подорож тільки починається» — завдання Орди в Оргріммарі для вправних шкірників після перемоги над Оніксією.",kw={"оніксія","плащ з луски оніксії","шкірництво","володар рунтак","нефаріан","шпиль блекрок","гора блекрок"},ang={["faction:Horde"]="Для Орди захисне спорядження з решток поваленого ворога — запорука того, що її воїнів не спіткає нове драконяче спустошення."},sec={{t="Спадок матері виводку",b="Падіння Оніксії — тріумф для Орди, але воно не знаменує кінця загрози з боку чорного драконячого роду. Луската шкура матері виводку напрочуд стійка до драконячого полум'я. Тож замість дати таким матеріалам пропасти, провідники Орди шукають майстрів, здатних перетворити рештки драконихи на захисні обладунки."},{t="Щит від тіньового полум'я",b="Володар Рунтак учить обдарованих шкірників зшивати Плащ з Луски Оніксії. Ці знання потрібні не для показу чи престижу. Глибоко в Горі Блекрок брат Оніксії, Нефаріан, видихає нищівне полум'я. Без зачарованого захисту, який дає луска самої Оніксії, будь-який загін, що зійдеться з Володарем Блекрока, обернеться на попіл."}},faq={{q="Хто дає це завдання і де його знайти?",a="Завдання дає Володар Рунтак в Оргріммарі. Він відзначає поборників Орди, які стали майстрами шкірництва й допомогли здолати Оніксію.",al={"видавець натой","де володар натой","початок завдання"}},{q="Яка умова, щоб отримати це завдання?",a="Завдання дають лише вправним шкірникам, які пройшли переможний фінал після загибелі Оніксії, як-от «Перемога Орди» чи «Вельми загадкова обставина».",al={"вимога шкірництва","як отримати завдання","попередні умови"}},{q="Чого навчає Володар Рунтак?",a="Володар Рунтак навчає шкірника, як виготовити Плащ з Луски Оніксії з луски, знятої з полеглої матері виводку.",al={"рецепт з нагороди","викрійка плаща оніксії","чого я навчуся"}},{q="Чому Плащ з Луски Оніксії такий важливий?",a="Плащ захищає власника від смертоносного вогняного подиху Нефаріана, Володаря Блекрока. Без його особливих захисних властивостей сутичка з господарем виводку стала б смертельною.",al={"чому робити плащ","призначення плаща","плащ нефаріана"}},{q="Хто такий Володар Блекрока?",a="Володар Блекрока — Нефаріан, могутній чорний дракон і брат Оніксії, що з висот Гори Блекрок плете змови, аби підкорити смертні раси.",al={"хто володар блекрока","особа нефаріана","володар блекрока"}},{q="Чому завдання каже, що подорож тільки починається?",a="Хоча Оніксію вбито, ширша війна проти чорного драконячого роду й підступів Нефаріана в Горі Блекрок лише розгоряється.",al={"значення назви","чому подорож тільки починається"}}},fp="26,347,22.359.0,27.396.1,49.178.0,49.183.0,33.152.0,40.186.0,29.159.0,57.145.0"}
P.entries["quest:7497"] = {n="Подорож тільки починається",s="Це завдання — заслужене визнання досвідченого майстра після перемоги над Оніксією. Майор Меттінґлі передає важливе вміння, потрібне, щоб виготовити Плащ з Луски Оніксії, — і рештки полеглої праматері виводку стають надійним захистом від її брата.",h="Це завдання — заслужене визнання досвідченого майстра після перемоги над Оніксією.",kw={"оніксія","плащ з луски оніксії","майор меттінґлі","нефаріан","шкірництво","чорні дракони"},ang={["faction:Alliance"]="Це завдання поєднує тяжко здобуту перемогу Стормвінда над Оніксією з неминучим наступом на її брата Нефаріана в Горі Блекрок."},sec={{t="Рідкісна майстерність",b="Багато героїв може похвалитися участю в поваленні праматері виводку Оніксії, але лише одиниці мають і бойову звитягу, і майстерність шкіряника, потрібну, щоб обробити її грізну шкуру. Коли герой із таким поєднанням талантів з'являється до Майора Меттінґлі в Стормвінді, офіцер визнає, наскільки ці ремісничі вміння важливі для битв, що ще попереду."},{t="Захист від чорного драконячого роду",b="Смерть Оніксії не кладе край загрозі чорного драконячого роду. Меттінґлі вчить майстра, як вичинити й зшити луску праматері виводку в Плащ з Луски Оніксії. Цей особливий одяг захищає від нищівного вогняного подиху брата Оніксії — Нефаріана, Володаря Блекрока."}},faq={{q="Хто дає завдання «Подорож тільки починається»?",a="Це завдання дає Майор Меттінґлі в Стормвінді героям Альянсу, які проявили себе в кампанії проти Оніксії й стали майстрами шкірництва.",al={"хто дає подорож тільки починається","де взяти подорож тільки починається","видавець подорожі тільки починається"}},{q="Чого навчає це завдання?",a="Це завдання навчає майстрів-шкірників рецепта Плаща з Луски Оніксії — виробу, пошитого саме з луски Оніксії.",al={"який рецепт я отримаю","рецепт плаща оніксії","нагорода подорожі тільки починається"}},{q="Навіщо потрібен Плащ з Луски Оніксії?",a="Плащ особливо оброблено, щоб захищати власника від смертоносного вогняного подиху Нефаріана, Володаря Блекрока, тож без нього не обійтися в сутичці з рештою ватажків чорного драконячого роду.",al={"навіщо плащ оніксії","для чого плащ з луски оніксії","захист від тіньового полум'я"}},{q="Хто такий Володар Блекрока, про якого каже Майор Меттінґлі?",a="Володар Блекрока — Нефаріан, могутній чорний дракон і брат Оніксії. Він панує над Шпилем Блекрок і продовжує підступи чорного драконячого роду.",al={"хто володар блекрока","хто такий нефаріан","попередження меттінґлі про дракона"}},{q="Чому герой має бути шкірником, щоб отримати це знання?",a="Щоб зняти, загартувати й зшити луску драконів, не зруйнувавши її природного магічного захисту, потрібна глибока майстерність досвідченого майстра-шкірника.",al={"чому лише шкірник","чи кожен може це завдання","вимога шкірника"}},{q="Чи смерть Оніксії усуває загрозу чорних драконів для Стормвінда?",a="Ні. Сама Оніксія загинула, але її брат Нефаріан і далі панує в Горі Блекрок і плете змови проти Альянсу й смертних рас.",al={"чи стормвінд тепер безпечний","оніксія мертва що далі","чорний дракон після оніксії"}}},fp="26,276,14.360.0,41.323.1,48.169.0,27.153.0,40.206.0,58.168.0,63.179.0,65.161.1"}
P.entries["quest:75"] = {n="Легенда про Сталвана",s="Розслідування справи Сталвана Містмантла виводить із Сутінколісся до відлюдного дому на південному сході Лісу Елвінн. Маршал Гаґґард, літній ветеран із дедалі гіршим зором, посилає вас до скрині на горищі зі старою в'язкою паперів, що лишилися там, коли він сюди переїхав.",h="Розслідування справи Сталвана Містмантла виводить із Сутінколісся до відлюдного дому на південному сході Лісу...",kw={"легенда про сталвана","маршал гаґґард","сталван містмантл","скриня","покинутий дух","ліс елвінн"},ang={["faction:Alliance"]="Розплутуючи спадок Сталвана, ви відкриваєте темні сторінки, тихо заховані в мирному сільському прикордонні Елвінна.",["race:Human"]="Шлях Сталвана в'ється звичайними людськими поселеннями — це пересторога про самотність і злобу, що ховаються в усіх на виду."},sec={{t="Горище ветерана",b="Маршал Гаґґард живе далеко від міста, на південно-східних околицях Лісу Елвінн, біля кордонів із Сутінколіссям і Редріджем. Переїхавши до свого відлюдного дому, він знайшов нагорі скриню, напхану старими пергаментами. Зір його дедалі каламутнішав, тож він покинув спроби їх прочитати, і документи лежали недоторкані, доки не прийшов слідчий із питаннями про Сталвана."},{t="Тіні, що не зникають",b="Папери в скрині на горищі — не звичайний хатній мотлох. Хто тривожить речі Сталвана, той щоразу збуджує неспокійну магію, що викликає покинутого духа, прив'язаного до минулого Містмантла. Сторінка щоденника, захована всередині, — прямий запис особистих роздумів Сталвана й переконливий доказ того, що відлюдний учений лишив свій слід в Елвінні, перш ніж зник."}},faq={{q="Хто такий Маршал Гаґґард?",a="Маршал Гаґґард — літній, майже сліпий ветеран, що тихо живе у відлюдній хатині на південному сході Лісу Елвінн. Він зберігає давно забуті папери, знайдені в його будинку, що належали Сталванові Містмантлу.",al={"маршал гаґґард","гаґґард елвінн","хто такий гаґґард"}},{q="Чому слід привів назад до Лісу Елвінн?",a="Зачіпки, зібрані в Даркширі й Мунбруку, вказують на мандри Сталвана південними землями Стормвінда. На садибі Гаґґарда лишилися старі речі, які Сталван викинув чи покинув, перш ніж поринув у безумство.",al={"чому ліс елвінн","сталван елвінн","чому йти до гаґґарда"}},{q="Що в скрині нагорі?",a="У скрині — вицвіла сторінка щоденника Сталвана Містмантла, що збереглася серед стосу пергаментів, які Гаґґард так і не зміг як слід переглянути.",al={"скриня нагорі","вицвіла сторінка щоденника","що в скрині"}},{q="Чому, коли відкрити скриню, нападає дух?",a="Над реліквіями колишнього життя Сталвана витає покинутий дух, що люто з'являється, коли чужинець тривожить його особисті записи й спогади.",al={"знедолений дух","чому дух нападає","привид у домі гаґґарда"}},{q="Як це просуває розслідування про Сталвана?",a="Вицвіла сторінка — свідчення з перших рук, написане самим Сталваном; вона допомагає скласти трагічну хронологію його служби, нерозділеної одержимості й зрештою кривавих убивств.",al={"таємниця сталвана","що відкриває сторінка","крок ланцюжка сталвана"}},{q="Чому Маршал Гаґґард не міг сам прочитати папери?",a="Із віком зір Гаґґарда затуманився й ослаб, тож він не може розібрати дрібного чи вицвілого почерку на старих документах.",al={"гаґґард сліпий","чому гаґґарду потрібна допомога"}}},fp="21,280,17.391.0,17.382.1,23.216.0,45.212.0,34.157.0,50.144.0,48.172.1,53.140.0"}
P.entries["quest:751"] = {n="Сплюндрований караван",s="Огляд розбитої валки в Малгорі відкриває, що гоблінські промисловці незаконно закріпилися на землях тауренів. Діставши документи із запечатаного ящика, розвідники підтверджують: Венчурна Компанія планомірно вигрібає мінеральні багатства краю. Це відкриття спонукає Скороходів Бладгуф стати на дієвий захист прабатьківських рівнин.",h="Огляд розбитої валки в Малгорі відкриває, що гоблінські промисловці незаконно закріпилися на землях тауренів.",kw={"караван","венчурна компанія","документи","морін клаудсталкер","скороходи","село бладгуф","малгор"},ang={["class:Druid"]="Друїди мають рівновагу землі за святиню, тож нищівний, задимлений відкритий видобуток Венчурної Компанії — споганення, яке належить очистити.",["faction:Horde"]="Орда покладається на вірність і стабільність Малгору; дозволити чужим купецьким картелям спустошувати його пагорби означало б загрожувати безпеці самого Тандер Блафа.",["profession:Mining"]="Високоякісні руди в ящику доводять: східні пагорби Малгору ховають багаті підземні жили, до яких уже рвуться чужинці.",["race:Tauren"]="Для тауренів бачити, як груба промислова машинерія роздирає прабатьківські рівнини Малгору, — образа Земній Матері й оголошення війни їхньому новознайденому миру."},sec={{t="Докази визиску",b="Рештки сплюндрованого каравану на схід від Села Бладгуф розповідають тривожну історію. У запечатаному ящику з припасами лежить щільний сховок видобутої руди й мінералів, а поруч — підшивка документів Венчурної Компанії. Ці папери — незаперечний доказ того, що захланна Венчурна Компанія розпочала недозволений видобуток у глибині тихих долин Малгору."},{t="Варта Скороходів",b="Морін Клаудсталкер і його побратими-Скороходи обачно пильнують кордони Малгору, пам'ятаючи про чужі угруповання, що прагнуть нажитися на їхній мирній батьківщині. Передані документи підтверджують найгірші побоювання Моріна: дим над східними передгір'ями знаменує дедалі ширше торгове вторгнення. Тауренам не лишається вибору, окрім як дати відсіч плюндрувальникам, доки їхні пагорби не випотрошено дощенту."}},faq={{q="Що в запечатаному ящику з припасами?",a="Якщо відкрити ящик, там знайдеться всяка видобута руда, сира мінеральна сировина й стос документів Венчурної Компанії з описом її діяльності.",al={"здобич ящика з припасами","що в ящику","вміст ящика"}},{q="Хто такий Морін Клаудсталкер?",a="Морін Клаудсталкер — таурен-гонець, що стоїть на дорозі на схід від Села Бладгуф, у бік кордону з Пустками; йому доручено патрулювати Малгор і вистежувати чужі загрози.",al={"хто такий морін","роль моріна клаудсталкера","розвідник морін"}},{q="Чому Венчурна Компанія в Малгорі?",a="Венчурна Компанія прагне безжально виснажити багаті природні ресурси й рудні жили Малгора, врізаючись у пагорби без жодної поваги до землі й корінного народу.",al={"чому гобліни тут","мета венчурної компанії в мулґорі","чого хочуть гобліни"}},{q="Звідки йшов караван?",a="Караван належав Венчурній Компанії: він віз видобуту руду й робочі документи з її копалень у передгір'ях, доки його не знищили на стежці.",al={"чий це був караван","звідки караван","хто напав на караван"}},{q="Куди веде це розслідування далі?",a="Маючи документи, Морін Клаудсталкер посилає воїнів кинути виклик проводу Венчурної Компанії й зруйнувати її копальні в східних передгір'ях.",al={"що далі","наступне завдання після сплюндрованого каравану","продовження каравану"}},{q="Чому це загрожує тауренам?",a="Таурени вважають землю священною й шанують Земну Матір. Безоглядний відкритий видобуток і промислове забруднення Венчурної Компанії оскверняють незайманий край Малгора.",al={"чому таурени переймаються","загроза венчурної компанії","загроза мулґору"}}},fp="19,373,24.371.0,21.434.0,39.146.0,26.176.0,38.180.0,32.169.0,40.178.1,34.178.0"}
P.entries["quest:752"] = {n="Скромне завдання",s="«Скромне завдання» — ранній обряд обов'язку, який дає Вождь Гоквінд у Таборі Нарачі. Поки вождь залагоджує нагальні племінні справи на Плато Червоної Хмари, він просить молодого шукача пригод піти на південний схід і навідати його стару матір біля тутешньої криниці. Прохання підкреслює спільну відповідальність, шану до старших і повсякденну гармонію, без якої немислиме життя тауренів.",h="«Скромне завдання» — ранній обряд обов'язку, який дає Вождь Гоквінд у Таборі Нарачі.",kw={"скромне завдання","вождь гоквінд","прамати гоквінд","табір нарачі","криниця","плато червоної хмари","малгор"},ang={["faction:Horde"]="Тихий, пасторальний характер доручень Нарачі показує, як лагідна громадська філософія тауренів відрізняється від суворішої, гартованої виживанням вдачі решти молодої Орди.",["race:Tauren"]="Для молодих тауренських сміливців відгукнутися на поклик вождя означає втілити основи науки Земної Матері: шану до старших і беззастережну відданість спільному добробуту племені."},sec={{t="Громадська злагода й обов'язок",b="У затінку Табору Нарачі кожен член племені має нести свою частку й долучатися до злагоди життя. Для молодих тауренів, що входять у зрілість, племінний обов'язок міряється не лише бойовою вправністю проти шипогривів і хижаків — він починається з простої суспільної відповідальності. Вождь Гоквінд показує це власним прикладом: прикутий до свого поста клопотами управління й оборони, він довіряє новачкам доглянути вразливих старійшин громади."},{t="Криниця на південний схід від Нарачі",b="Плато Червоної Хмари в Малгорі живиться природними криницями, розкиданими за межами табору. Рано-вранці Прамати Гоквінд сама вийшла із селища по свіжу воду до південно-східного джерела. У краю, де підстерігає територіальна звірина й зазіхають шипогриви-Щетиноспини, кількагодинна відсутність старої жінки будить тиху тривогу, тож Гоквінд посилає когось переконатися, що з нею все гаразд."}},faq={{q="Хто дає це завдання і де його знайти?",a="Завдання дає Вождь Гоквінд, ватажок Табору Нарачі на Плато Червоної Хмари в Малгорі. Він стоїть у центральному наметі табору й опікується місцевими справами.",al={"хто дає скромне завдання","де взяти завдання","місце вождя гоквінда"}},{q="Де знайти Праматір Гоквінд?",a="Прамати Гоквінд — трохи на південний схід від Табору Нарачі, біля криниці на нижній частині плато.",al={"місце праматері гоквінд","де мати","місце криниці"}},{q="Чому Вождь Гоквінд сам не навідається до матері?",a="Вождь Гоквінд мусить лишатися в Таборі Нарачі, щоб вирішувати нагальні справи племені й наставляти молодих воїнів. Як ватажок, він покладається на спільну відповідальність племені й довіряє молодим шукачам пригод подбати про справи поселення замість нього.",al={"чому вождь не йде сам","чому гоквінд не перевіряє","вождь гоквінд зайнятий"}},{q="Чи загрожує щось Праматері Гоквінд біля криниці?",a="Хоча на навколишніх рівнинах водяться агресивні гірські пуми й рівнинні довгоступи, Праматір Гоквінд знаходять живою й неушкодженою біля криниці — і приємно здивованою, що хтось навмисне прийшов провідати старійшину.",al={"чи вона в безпеці","чи на праматір напали","небезпека біля криниці"}},{q="Яке культурне значення має це завдання для тауренів?",a="Таурени надзвичайно цінують родину, згуртованість громади й шану до старших. Завдання вчить молодих героїв, що справжня сила вкорінена в скромному служінні й захисті рідних, а не в гонитві за особистою славою.",al={"культура тауренів скромне завдання","чому це скромне завдання","старійшини тауренів"}},{q="Що буде, коли знайти Праматір Гоквінд?",a="Коли ви поговорите з Праматір'ю Гоквінд, завдання виконано, а вона попросить ще допомогти віднести повний глечик води назад до табору.",al={"наступне завдання","продовження скромного завдання","що робити після знаходження матері"}}},fp="13,384,25.487.0,29.432.0,47.166.0,38.125.0,55.242.0,46.215.0,64.231.0,48.151.0"}
P.entries["quest:753"] = {n="Скромне завдання",s="«Скромне завдання» — вступний обряд служіння на Плато Червоної Хмари, де старійшина випробовує смирення й старанність новачка. Несучи свіжу криничну воду через рівнини до провідника Табору Нарачі, молоді таурени осягають: служіння народові починається з найпростіших обов'язків.",h="«Скромне завдання» — вступний обряд служіння на Плато Червоної Хмари, де старійшина випробовує смирення й...",kw={"скромне завдання","прамати гоквінд","вождь гоквінд","вода","табір нарачі","плато червоної хмари","тандер блаф"},ang={["faction:Horde"]="Уроки родини Гоквіндів показують, як таурени зберігають єдність і виживають у Малгорі, утворюючи мирний, але непохитний наріжний камінь Орди Тралла.",["race:Tauren"]="Принести води своїм старшим — утілення основоположної тауренської чесноти громадської турботи; це знак, що ви готові ступити на шлях Земної Матері."},sec={{t="Сила молодості",b="Прамати Гоквінд пройшла за довге життя багато стежок, і хоч дух її лишається твердим, ноги вже не носять її рівнинами з колишньою прудкістю. Облаштувавшись біля криниці на південному краю Плато Червоної Хмари, вона терпляче й рішуче дбає про свої обов'язки. Коли її стежку перетинають майбутні захисники племені, вона спрямовує їхню молоду снагу на практичні потреби громади, даючи змогу довести свою вартість служінням, а не насильством."},{t="Служіння племені",b="Завдання просить посвяченого віднести наповнений глек води назад на північний захід, до Табору Нарачі, й передати його просто в руки провідникові поселення — Вождеві Гоквінду, синові Праматері. У тауренському суспільстві виживання на посушливих рівнинах Малгору вимагає спільної праці й надійних запасів прісної води. Виявити шану до старійшин громади, беручи на себе їхній тягар, вважається наріжним каменем становлення справжнього захисника племені."},{t="Шлях до Тандер Блафа",b="Коли молодий мандрівник приходить із водою від його матері, Вождь Гоквінд бачить у цьому більше, ніж виконану дрібну роботу. За звичаєм тауренів, готовність боронити свій народ на ширших землях починається зі смирення й неспонуканого бажання допомогти. Виявивши цю тиху дисципліну, посвячений привертає увагу вождя й здобуває рекомендацію до прадавніх Обрядів Земної Матері — справжніх духовних випробувань, що відчиняють брами Тандер Блафа."}},faq={{q="Хто така Прамати Гоквінд?",a="Прамати Гоквінд — старійшина родини Гоквінд, що перебуває біля криниці на Плато Червоної Хмари. Вона мати ватажка Табору Нарачі, Вождя Гоквінда, і вчить молодих тауренів скромності й цінностей племені.",al={"праматір гоквінд","хто дає скромне завдання","старійшина гоквінд"}},{q="Де криниця?",a="Криниця — на південний схід від Табору Нарачі, на трав'янистих рівнинах Плато Червоної Хмари. Біля неї стоять глеки зі свіжою водою, щоб мандрівники й доглядачі табору могли їх віднести.",al={"місце криниці","де криниця","знайти глечик"}},{q="Хто такий Вождь Гоквінд?",a="Вождь Гоквінд — ватажок Табору Нарачі на Плато Червоної Хмари. Він керує навчанням і духовними обрядами молодих тауренів, готуючи їх вирушити в світ і служити всьому племені в Малгорі.",al={"вождь гоквінд","хто вождь","ватажок табору нараше"}},{q="Чому цю буденну справу вважають важливим випробуванням?",a="Таурени високо цінують скромність, взаємодопомогу в громаді й шану до старших. Виконуючи непоказні щоденні обов'язки, шукач пригод доводить, що дбає про добробут свого народу, а не лише про власну славу в бою.",al={"чому носити воду","чому скромне завдання","чи це завдання важливе"}},{q="Що буде після «Скромного завдання»?",a="Виконавши це завдання, ви доводите Вождеві Гоквінду свою дисципліну, і він скеровує вас до Обрядів Земної Матері — низки традиційних випробувань, які проходить кожен таурен, що дорослішає.",al={"що далі","наступне завдання","після скромного завдання"}},{q="Куди зрештою веде цей шлях?",a="Здобувши повагу старійшин Табору Нарачі, ви будете готові покинути відлюдне плато й вирушити на широкі рівнини Малгора, а зрештою — до високих столових гір столиці, Тандер Блафа.",al={"майбутня мета","куди ми йдемо","мета тандер блафа"}}},fp="13,288,21.500.0,20.469.0,27.468.0,28.220.0,32.178.0,22.203.0,47.236.0,42.202.0,37.209.0"}
P.entries["quest:754"] = {n="Очищення Вінтергуф",s="«Очищення Вінтергуф» — обряд, який Малл Тандергорн у Селі Бладгуф довіряє шукачам пригод Орди. Після того як гоблінські роботи споганили тутешні джерела, освячений тотем треба пронести на землі Венчурної Компанії, щоб очистити Водяну Криницю Вінтергуфів. Відновлення цього джерела — перший важливий крок до зцілення отруєних вод центрального Малгору.",h="«Очищення Вінтергуф» — обряд, який Малл Тандергорн у Селі Бладгуф довіряє шукачам пригод Орди.",kw={"очищення","вінтергуф","криниця","тотем","малл тандергорн","венчурна компанія","малгор"},ang={["class:Druid"]="Негайне повернення спраглої звірини до очищеного джерела доводить, як важливо зцілювати природу всюди, де цивілізація загрожує її сплюндрувати.",["class:Shaman"]="Спрямовувати духів через тотеми, щоб повернути назад неприродне промислове споганення, — сама суть зв'язку шамана з водною стихією.",["faction:Horde"]="Убезпечення запасів прісної води Малгору зміцнює серце земель новоосілих тауренів — південну опору молодої Орди.",["race:Tauren"]="Криниці Малгору — священні джерела життя, даровані Земною Матір'ю; боронити їх від гоблінської захланності — і громадський, і святий обов'язок кожного таурена."},sec={{t="Сплюндрована земля",b="Трав'янисті рівнини Малгору тримаються на тонкій мережі прабатьківських криниць, що напувають і дичину, і розпорошені племена тауренів. Нещодавно безжальні промислові найманці Венчурної Компанії осіли на пагорбах на південний схід від Села Бладгуф. Їхні роботи забруднили тутешні водоносні шари, і Водяна Криниця Вінтергуфів стала смердючою та отруйною. Дикі звірі цураються затруєної води, а поблизькі табори опиняться перед лихом, якщо скверна поповзе землею далі."},{t="Обряд очищення вод",b="Щоб протистояти промисловому бруду, Малл Тандергорн вирізьблює й зачаровує ритуальний тотем очищення, наснажений благословенням Земної Матері. Та щоб доставити ці ліки, доведеться пройти повз озброєних посіпак Венчурної Компанії, які заявили права на джерело. Поставивши тотем просто біля джерела, шукач пригод розвіює огидні стоки, і з надр землі знову здіймається чиста, життєдайна вода."}},faq={{q="Де Водяна Криниця Вінтергуфів?",a="Водяна Криниця Вінтергуфів — у пагорбах на південний схід від Села Бладгуф у Малгорі. Її пильно патрулюють гобліни-робітники й найманці Венчурної Компанії.",al={"місце криниці вінтергуфів","де криниця вінтергуфів","як знайти криницю вінтергуфів"}},{q="Чому криницю отруїли?",a="Венчурна Компанія розгорнула неподалік копальні й розкопки, і отруйні промислові стоки та відходи просочилися просто у водоносний шар, тож природне джерело стало непридатним для пиття і для звірів, і для тауренів.",al={"хто отруїв воду","чому криниця брудна","криниця венчурної компанії"}},{q="Хто такий Малл Тандергорн?",a="Малл Тандергорн — духовний старійшина в Селі Бладгуф. Він тонко відчуває здоров'я землі й виготовляє обрядові тотеми, щоб загоїти рани, яких природі завдали чужі загарбники.",al={"хто такий малл","роль малла тандергорна"}},{q="Що буде, коли криницю очищено?",a="Щойно вода у Водяній Криниці Вінтергуфів знову стане чистою, а звірі зможуть безпечно з неї пити, Малл Тандергорн зверне вашу увагу на інші отруєні криниці Малгора, почавши з «Тотема Громового Рогу».",al={"що далі","після очищення вінтергуф","що робить малл далі"}},{q="Хто стереже криницю?",a="Криницю зайняли робітники й наймити Венчурної Компанії — безсовісного синдикату під проводом гоблінів, що виснажує землі, не зважаючи на місцеву природу.",al={"хто стереже криницю","вороги біля криниці"}},{q="Як діє очисний тотем?",a="Різьблений за священними обрядами тауренів і вкритий охоронними знаками, тотем закликає природних духів і благословення Земної Матері, щоб вигнати з джерела неприродне хімічне забруднення.",al={"переказ про очисний тотем","як діє тотем малла"}}},fp="20,358,16.505.0,30.432.0,43.191.0,32.227.0,24.205.0,40.212.1,31.195.0,34.192.0"}
P.entries["quest:756"] = {n="Тотем Громового Рогу",s="«Тотем Громового Рогу» — завдання від Малла Тандергорна в Селі Бладгуф: виготовити священний тотем очищення. Щоб побороти гоблінське забруднення, що розповзається криницями Малгору, молоді звитяжці Орди мають зібрати кігті степових хижаків і вплести первісну міць землі в ритуальне дерево.",h="«Тотем Громового Рогу» — завдання від Малла Тандергорна в Селі Бладгуф: виготовити священний тотем очищення.",kw={"тотем","громорог","тандергорн","пазурі","степовий переслідувач","пума","малл тандергорн","малгор"},ang={["class:Hunter"]="Щоб зібрати пазурі, треба розуміти корінних хижаків рівнин і шанувати здобич, оберігаючи рівновагу живого світу.",["class:Shaman"]="Відновлення тотемами спирається на заклик до живих духів землі, щоб очистити воду, споганену неприродним, недбалим промислом.",["race:Tauren"]="Захист водоносних шарів Малгору від чужоземного визиску — священний племінний обов'язок, що відбиває заповіт Земної Матері жити в рівновазі, а не грабувати."},sec={{t="Полювання на степових хижаків",b="Поки промисловий визиск Венчурної Компанії труїть дорогоцінні джерела Малгору, Малл Тандергорн поспіхом готує ліки. Для Очисного Тотема Громорога потрібна природна сутність найзосередженіших мисливців рівнин — степових переслідувачів і рівнинних пум. Беручи пазурі цих хижаків, що блукають на схід і захід від Села Бладгуф, обряд спрямовує сиру, неспотворену хижу снагу звірини просто в тотем."},{t="Природа полювання",b="Тауренська традиція глибоко розрізняє полювання заради прожитку чи духовної рівноваги й гуртове плюндрування, яке чинять гобліни. Малл наголошує: чистота, з якою полюють корінні хижаки, конче потрібна, щоб очистити споганену землю. Там, де гоблінські машини отруюють джерела мастилом і промисловими відходами, природна сила звірів, що змагаються із землею, стає духовним каталізатором для відновлення Водяної Криниці Тандергорнів."}},faq={{q="Навіщо Маллові Тандергорну кігті хижаків?",a="Малл використовує кігті степових скрадачів і рівнинних пум, щоб вкласти в очисний тотем чистий первісний дух хижаків рівнин. Він вірить, що чистий дух природних мисливців протидіє штучній промисловій скверні.",al={"навіщо кігті","призначення кігтів скрадачів","призначення кігтів пум"}},{q="Хто отруює воду в Малгорі?",a="Землю й воду забруднюють гобліни Венчурної Компанії, що хазяйнують у Малгорі. Їхній безоглядний видобуток і бурові установки пускають отруйний мул у водоносні шари, що живлять криниці племен.",al={"хто отруїв криницю","чому криниця отруєна","що отруїло мулґор"}},{q="Де водяться степові скрадачі й рівнинні пуми?",a="Обидва звірі блукають відкритими рівнинами центрального Малгора, здебільшого на пологих саванах просто на схід і на захід від Села Бладгуф.",al={"місце скрадачів","де пуми","місця кігтів пум"}},{q="Що буде, коли тотем Громового Рогу виготовлено?",a="Коли Малл виріже тотем із кігтями й зачарує його, він посилає вас просто до отруєної Водяної Криниці Тандергорнів, щоб звершити обряд очищення й вигнати отруту.",al={"що далі","після тотема громового рогу","продовження тотема"}},{q="Як це пов'язано з попереднім очищенням криниці Вінтергуфів?",a="Це частина спільних зусиль племені вберегти священні води Малгора. Водяну Криницю Вінтергуфів очистили першою, а тепер отрута загрожує криниці Тандергорнів далі на півночі.",al={"зв'язок з вінтергуфами","попереднє завдання тотема"}},{q="Чому таурени не обходяться травами, а беруть кігті звірів?",a="Обрядове ремесло тауренів спирається на різні стихійні й тілесні прояви природи. Гостра чистота найгрізніших хижаків дає діяльну, войовничу духовну силу, яка потрібна саме для того, щоб пробитися крізь агресивні промислові отрути гоблінів.",al={"чому не трави","шаманські матеріали тотема"}}},fp="17,307,28.469.0,22.465.0,46.237.0,39.200.0,58.146.0,50.174.1,66.195.0,72.236.0"}
P.entries["quest:757"] = {n="Обряд Сили",s="Обряд Сили — перше випробування в традиційних Обрядах Земної Матері, які проходять молоді таурени в Таборі Нарачі. Щоб довести хоробрість і готовність боронити плем'я, посвячені мають винищити шипогривів-Щетиноспинів, що зазіхають на Яр Тернистого Клинка, і піднести їхні пояси Вождеві Гоквінду.",h="Обряд Сили — перше випробування в традиційних Обрядах Земної Матері, які проходять молоді таурени в Таборі...",kw={"обряд сили","обряди земної матері","шипогриви","щетиноспини","віщун ґрейтанг","вождь гоквінд","яр тернистого клинка"},ang={["faction:Horde"]="Оборона плато вбезпечує одне з головних місць, де Орда гартує поповнення, щоб молоді воїни й шамани могли спокійно змужніти на допомогу новому союзові.",["race:Tauren"]="Кожен молодий таурен починає свою подорож із цих прадавніх обрядів, доводячи готовність захистити свій народ від загрози шипогривів перед тим, як покинути Плато Червоної Хмари."},sec={{t="Перше випробування",b="Для молодого таурена, що прагне визнання племінних старійшин і, зрештою, прийняття в Тандер Блафі, пройти Обряди Земної Матері — неодмінний обов'язок. Обряд Сили, який дає Віщун Ґрейтанг, слугує відправним випробуванням. Він вимагає тілесної відваги й рішучих дій на захист Плато Червоної Хмари і перевіряє, чи здатен посвячений не здригнувшись стати перед смертельними ворогами племені."},{t="Загроза Щетиноспинів",b="Горнилом цього випробування обрано Яр Тернистого Клинка — зарослу колючками розколину на схід від Табору Нарачі, яку зайняли шипогриви-Щетиноспини. Ці напасливі зайди раз у раз вдираються на прабатьківські землі, нападають із засідок на мисливські загони й під покровом темряви грабують табірні запаси. Убивати їх і забирати їхні пояси — і доказ доблесті, і конечний захід, щоб поселення лишалося в безпеці."}},faq={{q="Навіщо Обряд Сили?",a="Це перший крок Обрядів Земної Матері, що має перевірити хоробрість молодого таурена в бою. Знищивши ворогів, які загрожують табору, учень здобуває право рухатися далі до справжньої пошани в Тандер Блафі.",al={"навіщо обряд сили","переказ про обряд сили","мета обряду сили"}},{q="Хто призначає й оцінює це випробування?",a="Віщун Ґрейтанг дає учневі доручення й пояснює духовні й практичні вимоги випробування. Коли зібрано дванадцять поясів Щетиноспинів, доказ звитяги треба віднести просто Вождеві Гоквінду в Таборі Нарачі.",al={"хто дає обряд сили","кому здати обряд сили"}},{q="Де Яр Тернистого Клинка?",a="Яр Тернистого Клинка лежить просто на схід від Табору Нарачі на Плато Червоної Хмари. Це колючий каньйон, що кишить ворожими шипогривами Щетиноспинами.",al={"де яр тернистого клинка","місце тернистого клинка"}},{q="Чому саме Щетиноспини?",a="Щетиноспини вдираються на прадавні мисливські угіддя племені. Вони раз у раз влаштовують засідки на мисливців-тауренів і поночі крадуть припаси з Табору Нарачі, тож вони — прямі вороги племені.",al={"чому щетиноспини","що зробили вепролюди"}},{q="Чому треба збирати пояси, а не інші трофеї?",a="Пояси — відчутні знаки переможених воїнів: вони доводять, що учень зійшовся із шипогривами врукопаш і здолав дорослих бійців, а не просто підбирав здобич здалеку.",al={"чому пояси","чому саме пояси"}},{q="Що буде після Обряду Сили?",a="Пройшовши Обряд Сили, учень доводить свою звитягу й може братися до наступних випробувань Земної Матері, продовжуючи урочистий шлях до дорослості й духовного становища в племені.",al={"що після обряду сили","наступний обряд земної матері"}}},fp="16,303,15.399.0,22.404.0,44.234.0,34.237.0,37.150.0,40.223.0,44.196.0,49.201.0"}
P.entries["quest:758"] = {n="Очищення Громорога",s="«Очищення Громорога» — важливий духовний обряд у Малгорі, що доручає мандрівникам очистити споганену Водяну Криницю Тандергорнів. Озброєні ритуальним тотемом, який приготував Малл Тандергорн, шукачі пригод відновлюють затруєне джерело, життєво важливе для тутешнього племені. Успішне очищення здобуває щиру вдячність предків Тандергорнів.",h="«Очищення Громорога» — важливий духовний обряд у Малгорі, що доручає мандрівникам очистити споганену Водяну...",kw={"очищення","громорог","тандергорн","криниця","тотем","малл тандергорн","предки","малгор"},ang={["class:Druid"]="Очищення отруєних вод зупиняє поширення скверни живим світом Малгору й зберігає природну гармонію рівнин.",["class:Shaman"]="Спрямовувати силу предків через тотеми, щоб зцілити споганені природні джерела, — сама основа шаманського покликання.",["faction:Horde"]="Допомога тауренам із їхніми священними джерелами зміцнює зв'язок між молодою Ордою та її гордими союзниками шу'хало.",["race:Tauren"]="Відновлення священних джерел вшановує Земну Матір і захищає ваших родичів, поки вони здобувають собі постійний мирний дім у Малгорі."},sec={{t="Затруєна життєва жила",b="Криниці на розлогих рівнинах Малгору — життєві жили кочових племен тауренів, що нещодавно осіли серед трав. Коли підземні джерела затруюють огидні отрути, і звірина, і поблизькі поселення опиняються перед нищівними наслідками. Водяна Криниця Тандергорнів на північ від Села Бладгуф, що стала жертвою забруднення, потребує свідомого духовного втручання, щоб зцілити стражденну землю."},{t="Очищення предків",b="Щоб здолати скверну, Малл Тандергорн виготовляє освячений Очисний Тотем, наснажений духовною силою. Принісши цю реліквію просто до отруєних вод, шукачі пригод спрямовують у джерело силу предків, розсіюють отруту й повертають первозданну природну рівновагу. Малл дістає пряме підтвердження успіху, коли духи предків Тандергорнів навідуються до нього уві сні, щоб висловити свою незгасну вдячність."}},faq={{q="Де Водяна Криниця Тандергорнів?",a="Водяна Криниця Тандергорнів — на рівнинах на північ від Села Бладгуф у Малгорі. Це один із кількох життєво важливих водопоїв, що живлять місцеві клани тауренів.",al={"місце криниці тандергорнів","де криниця","де використати тотем"}},{q="Хто розпочинає цей обряд очищення?",a="Обряд розпочинає Малл Тандергорн. Його можна знайти в Селі Бладгуф, де він виготовляє особливі тотеми, щоб зцілити скривджену природу Малгора.",al={"хто дає завдання","місце малла тандергорна","видавець завдання"}},{q="Чому криниці Малгора треба очищати?",a="Криниці по всьому Малгору стали жертвою неприродного отруєння й скверни, що загрожує тендітній рівновазі рівнин і виживанню племен тауренів, яким потрібна чиста вода.",al={"чому очищати криниці","що сталося з водою","чому криниця отруєна"}},{q="Звідки Малл знає, що обряд вдався?",a="Коли обряд біля криниці звершено, духи предків клану Тандергорн являються Маллові уві сні, славлять подвиг шукача пригод і передають подяку предків.",al={"сон предків","звідки малл знає","результат очищення криниці"}},{q="Що йде після очищення криниці Тандергорнів?",a="Очищення криниці Тандергорнів — частина ширших зусиль уберегти джерела Малгора. Далі Малл посилає мандрівників допомогти ще одному стражденному місцю, виготовивши «Тотем Вайлдмейнів».",al={"що далі","наступне завдання після тандергорнів","тотем вайлдмейнів далі"}},{q="Що таке Очисний Тотем Громорога?",a="Очисний Тотем Громорога — обрядово вирізьблений духовний осередок, який Малл Тандергорн виготовив саме для того, щоб очистити отруєні води прадавньої криниці свого клану.",al={"очисний тотем","що за тотем","тотем малла"}}},fp="21,345,18.422.0,19.447.0,44.167.0,36.161.0,48.196.0,45.184.0,51.191.0,40.180.0"}
P.entries["quest:759"] = {n="Тотем Вайлдмейнів",s="«Тотем Вайлдмейнів» — третій, останній етап зусиль Малла Тандергорна виготовити тотеми очищення для отруєних криниць Малгору. Щоб відновити Криницю Вайлдмейнів, обряд вимагає підношень від найлютіших природних хижаків краю — ватажків степових вовків.",h="«Тотем Вайлдмейнів» — третій, останній етап зусиль Малла Тандергорна виготовити тотеми очищення для отруєних...",kw={"тотем","вайлдмейн","степові вовки","ватажок","зуби","малл тандергорн","тандер блаф","малгор"},ang={["class:Hunter"]="Вистежування хитрих вовків-ватажків довкола високих стрімчаків випробовує повагу мисливця до дикого краю та його найгостріших хижаків.",["class:Shaman"]="Шаман цінує тонкі обряди, що узгоджують тотеми хижаків зі стихією води, щоб вигнати отруйну заразу.",["race:Tauren"]="Очищення прабатьківських криниць підкреслює обов'язок тауренів виправляти порушену рівновагу довкілля й шанувати жертви, яких вимагає Земна Матір."},sec={{t="Остання криниця",b="Після того як зібрано все потрібне для освячення тотемів криниць Вінтергуфів і Тандергорнів, у центральному Малгорі лишається одне уражене джерело — Криниця Вайлдмейнів. Отруєна вода на рівнинах загрожує і мандрівній звірині, і поселенням, тож для відновлення природної рівноваги землі потрібні могутні первісні складники."},{t="Сила хижака",b="Щоб здолати стійку скверну, що затаїлася в північних водах, Маллу Тандергорну потрібна жертва лютості. Ватажки степових вовків нишпорять травами, надто довкола високих стрімчаків під Тандер Блафом. Їхні зуби вливають невпинний запал і витривалість верховних мисливців Малгору просто у виготовлення тотема очищення."},{t="Жертва й рівновага",b="У духовній традиції тауренів звертання до створінь землі має і чуттєву, і стихійну вагу. Малл бачить у збиранні зубів ватажків не завоювання, а скорботну необхідність, коли жертва хижаків Малгору допомагає зцілити уражені води Земної Матері."}},faq={{q="Для чого потрібен Тотем Вайлдмейнів?",a="Малл Тандергорн виготовляє цей тотем, щоб очистити Криницю Вайлдмейнів — останнє отруєне джерело, що загрожує тауренам Малгора.",al={"навіщо тотем вайлдмейнів","мета тотема вайлдмейнів"}},{q="Чому потрібні саме ікла ватажків степових вовків?",a="Щоб очистити глибоку отруту в Криниці Вайлдмейнів, треба закликати люту, незламну силу найгрізнішого хижака. Ікла ватажків зграй дають потрібну первісну силу.",al={"чому ікла вовків","призначення іклів ватажків"}},{q="Де в Малгорі водяться ватажки степових вовків?",a="Ватажки степових вовків блукають північними рівнинами Малгора й часто нишпорять луками біля підніжжя Тандер Блафа.",al={"місце ватажків степових вовків","де ватажки"}},{q="Хто виготовляє тотем?",a="Малл Тандергорн, духовний старійшина в Селі Бладгуф, виготовляє кожен очисний тотем, коли учень збере потрібні пожертви.",al={"хто робить тотем","видавець тотема"}},{q="Що буде, коли Тотем Вайлдмейнів готовий?",a="Щойно Малл Тандергорн зробить тотем із іклів ватажків, вас із ним відправлять на північ — звершити саме очищення в Криниці Вайлдмейнів.",al={"що далі","наступне завдання тотема вайлдмейнів"}},{q="Як цей обряд відбиває вірування тауренів?",a="Таурени вважають, що відібрати в звіра життя — це урочистий обмін із природою. Малл визнає жертву вовків: і сумує через їхню смерть, і пишається тим, що вони допомогли зцілити землю.",al={"вірування тауренів у тотемі","вірування малла тандергорна"}}},fp="14,272,14.339.0,23.367.0,21.277.0,38.141.0,55.192.0,47.130.0,21.146.0,48.147.0,44.199.0"}
P.entries["quest:76"] = {n="Яшмова копальня",s="Коли з'ясувалося, що кобольди захопили Копальню Фарґодіп, Маршал Дуґан доручає розвідникам оглянути Яшмову копальню далі на схід. На місці підтверджується найгірше: навала поширилася на життєво важливі рудні жили Елвінну й розтягнула решту захисників Стормвінда понад усяку межу.",h="Коли з'ясувалося, що кобольди захопили Копальню Фарґодіп, Маршал Дуґан доручає розвідникам оглянути Яшмову...",kw={"яшмова копальня","кобольди","маршал дуґан","вежа азори","розвідка","фарґодіп"},ang={["faction:Alliance"]="Одночасна втрата Фарґодіпу та Яшмової копальні оголює, якими крихкими стали рідні землі Стормвінда без централізованої королівської підтримки.",["profession:Mining"]="Для рудокопа бачити багаті підземні жили в лапах шкідників — гірке видовище. Тунелі Яшмової копальні зберігають цінні поклади, та щоб їх добути, доведеться пробиватися крізь рої кобольдів, які бережуть свою територію.",["race:Human"]="Розвідники з людей на власні очі бачать, як повільно розвалюється сільське господарство Елвінну, коли ресурси прикордоння падають просто біля столиці."},sec={{t="Друге вторгнення",b="Здобувши докази, що кобольди заполонили тунелі Фарґодіпу на південь від Ґолдшира, Маршал Дуґан побоювався, що навала не була поодиноким випадком. Яшмова копальня, що притулилася в скелястих передгір'ях на північний схід від Вежі Азори, — ще одне важливе джерело каменю й металу для королівства. Не маючи змоги зняти регулярних вартових Стормвінда з міських патрулів, Дуґан покладається на незалежних шукачів пригод: ті мають рушити на схід і з'ясувати, чи не впало й це місце перед підземними шкідниками зі свічками."},{t="Перенапружена оборона",b="Розвідка глибоких камер Яшмової копальні показує, що кобольди цілком витіснили людей-рудокопів, окопалися й укріпили темні переходи. Для Маршала Дуґана цей похмурий звіт — ще один удар у кризі, що наростає. Король Варіан Рінн зник, королівські війська не доходять до віддалених земель, і місцевому гарнізону бракує людей, щоб зачистити копальні, — серце королівства лишається економічно знекровленим і затиснутим з усіх боків."}},faq={{q="Де розташована Яшмова копальня?",a="Копальня лежить у північних передгір'ях східної частини Лісу Елвінн. Щоб дістатися туди, ідіть головною дорогою на схід повз Ґолдшир до Вежі Азори, а тоді зверніть на північ, у пагорби.",al={"де яшмова копальня","місце яшмової копальні","як знайти яшмову копальню"}},{q="Чому Маршалові Дуґану потрібен розвідник, а не вартові?",a="Варті Стормвінда в Елвінні гостро бракує людей через політичний безлад у столиці й зникнення короля Варіана Рінна. Місцеві сили й так розпорошені на захист ферм і містечок від бандитів і гнолів, тож Маршал Дуґан мусить покладатися на розвідників із цивільних.",al={"чому послати мандрівників","чому немає вартових стормвінда","де вартові"}},{q="Чому кобольди захоплюють копальні Елвінна?",a="Кобольди — природжені копачі, яких вабить до підземних рудних жил і вологих печер. Коли військова присутність Стормвінда послабла, вони осміліли й нахабно вдерлися в людські копальні на кшталт Фарґодіпу та Яшмової, щоб загарбати золото, руду й землю.",al={"чому кобольди в яшмовій копальні","чого хочуть кобольди","причина навали кобольдів"}},{q="Що буде після розвідки Яшмової копальні?",a="Коли ви доповісте Маршалові Дуґану, що Яшмова копальня впала, він визнає похмуру правду: Елвінн в облозі з кількох боків. Східні копальні втрачено, тож його увага переходить на захід Елвінна, де на Гарнізон Вестбрук тиснуть гноли Річколапів.",al={"що після яшмової копальні","продовження яшмової копальні"}},{q="Чому втрата Яшмової копальні важлива для Стормвінда?",a="Копальні Елвінна дають руду й камінь, потрібні для господарства Стормвінда й для кування зброї та обладунків. Утрата і Фарґодіпу, і Яшмової копальні зупиняє видобуток і тяжко підриває відновлення королівства.",al={"чому яшмова копальня важлива","значення яшмової копальні"}},{q="Кому належить Вежа Азори неподалік?",a="Вежа Азори — невелика вежа магів при східній дорозі в Лісі Елвінн; нею опікується Теокрітус, Архімаг Азори, а порядкують там слуги Азори. Це орієнтир для мандрівників, що прямують до східних передгір'їв.",al={"що таке вежа азори","хто живе у вежі азори"}}},fp="19,314,18.518.0,21.456.0,37.191.0,63.268.0,43.266.0,48.280.0,60.230.0,35.246.0"}
P.entries["quest:760"] = {n="Очищення Вайлдмейнів",s="«Очищення Вайлдмейнів» вінчає ритуальні зусилля тауренів очистити життєво важливі водопої Малгору. За дорученням Малла Тандергорна в Селі Бладгуф герої несуть довершений Тотем Вайлдмейнів на північ, щоб очистити останню отруєну криницю. Вигнання гоблінської отрути повертає рівновагу рівнинам і забезпечує пастуший прожиток племен тауренів.",h="«Очищення Вайлдмейнів» вінчає ритуальні зусилля тауренів очистити життєво важливі водопої Малгору.",kw={"очищення","вайлдмейн","криниця","тотем","малл тандергорн","венчурна компанія","тандер блаф","малгор"},ang={["class:Druid"]="Повернення назад руйнування довкілля гоблінами прямо відбиває заповіт Кола Кенарія зцілювати уражені оселища й захищати зелені пасовища.",["class:Shaman"]="Застосування ритуальних тотемів, щоб скасувати механічне забруднення, — зразок шаманського обов'язку підтримувати злагоду між природними стихіями й живими громадами.",["race:Tauren"]="Відновлення трьох прабатьківських криниць Малгору — основоположний обряд посвяти, що доводить відданість молодого сміливця збереженню дарів Земної Матері."},sec={{t="Очищення дару Земної Матері",b="Вода — священна життєва кров сонячних рівнин Малгору: вона живить стада, ґрунт і кочові племена, що нещодавно зібралися довкола Тандер Блафа. Коли Венчурна Компанія та зайди-гобліни взялися забруднювати ці водоносні шари отруйними промисловими стоками, старійшини тауренів побачили в цьому загрозу самому існуванню. Після очищення криниць Вінтергуфів і Тандергорнів Водяна Криниця Вайлдмейнів лишається третім, останнім споганеним місцем, що потребує духовного втручання."},{t="Тотем Вайлдмейнів",b="Виготовлений із особливих складників, зібраних по всьому краю, Тотем Очищення Вайлдмейн спрямовує відновлювальну силу духів предків і стихії землі. Поставлений біля огидних вод на північ від Тандер Блафа, він розсіює бридкі хімікати, витягає отруту й оживлює природний плин. Довершивши обряд, таурени вберігають свій народ від хвороб і посилають недвозначне послання: плюндрування їхньої священної землі не терпітимуть."}},faq={{q="Чому отруїли Водяну Криницю Вайлдмейнів?",a="Гоблінські підприємства, які женуться за промисловою наживою й рубають ліс, запустили мерзенну отруту й хімічні відходи в підземні води Малгора, загрожуючи і місцевим звірам, і поселенням племен.",al={"хто отруїв криницю","чому криниця брудна","отрута гоблінів"}},{q="Де Водяна Криниця Вайлдмейнів?",a="Водяна Криниця Вайлдмейнів стоїть на рівнинах просто на північ від високих столових гір Тандер Блафа.",al={"місце криниці вайлдмейнів","де криниця вайлдмейнів","пошук криниці вайлдмейнів"}},{q="Хто розпочинає цей обряд очищення?",a="Малл Тандергорн, старійшина із Села Бладгуф, учить вас виготовляти тотеми й посилає очищати криниці.",al={"хто дає очищення вайлдмейнів","видавець завдання","місце малла тандергорна"}},{q="Які ще криниці очищають у межах цих зусиль?",a="Криниця Вайлдмейнів — третя з трьох життєво важливих джерел; до неї були Водяна Криниця Вінтергуфів і Водяна Криниця Тандергорнів, обидві південніше.",al={"інші криниці","криниці мулґору","криниці вінтергуфів і тандергорнів"}},{q="Як діє очисний тотем?",a="Тотем сповнений магії предків і очищених стихій природи: він спрямовує цілющу духовну силу у водоносний шар і знешкоджує гоблінське забруднення.",al={"як працює очисний тотем","як тотем очищає воду"}},{q="Що означає завершення цього обряду для Села Бладгуф?",a="Очищення трьох криниць дає чисту питну воду всім племенам центрального Малгора й виконує священний обов'язок тауренів — зцілювати Земну Матір від промислового визиску.",al={"наслідок завдання","навіщо очищати криниці","значення для тауренів"}}},fp="18,371,33.509.0,18.481.0,41.206.0,41.104.0,36.139.0,54.153.0,34.166.0,60.179.0"}
P.entries["quest:761"] = {n="Полювання на стрімкокрилів",s="«Полювання на стрімкокрилів» — обряд вистежування й влучності, який пропонує Гаркен Віндтотем у Селі Бладгуф. Щоб довести кмітливість і терпіння, мисливцям і мандрівникам пропонують вистежити невловимих птахів на пагорбистих рівнинах Малгору. Повернутися з бездоганними трофейними перами означає виявити і відданість полюванню, і повагу до природних випробувань Земної Матері.",h="«Полювання на стрімкокрилів» — обряд вистежування й влучності, який пропонує Гаркен Віндтотем у Селі Бладгуф.",kw={"стрімкокрил","полювання","пера","гаркен віндтотем","село бладгуф","малгор","мисливець"},ang={["class:Druid"]="Вистежування стрімкокрилів на вітряних плато зближує друїдів із хижими птахами, які підтримують рівновагу в небі Малгору.",["class:Hunter"]="Це полювання — ранній майстер-клас із випередження крилатої здобичі, читання її звичок і точних ударів по пильних хижаках.",["race:Tauren"]="Для тауренської молоді й мандрівників полювання на прудких стрімкокрилів Малгору — шанований обряд посвяти, що гострить чуття слідопита й підтримує прадавні мисливські звичаї."},sec={{t="Випробування гострого ока",b="Трав'янисті степи Малгору кишать звіриною, та мало хто випробовує чуття переслідувача так, як тутешній Стрімкокрил. Ці великі хижі птахи непомітно зливаються з небокраєм і рівнинами, кружляючи вгорі чи низько шугаючи над високою травою. На відміну від вайлуватих довгоступів чи кодо на пасовищі, стрімкокрили вимагають гострої уваги й прудких ніг, щоб їх наздогнати, тож їхнє переслідування — традиційна вправа для молодших мисливців, які прагнуть здобути становище серед племен."},{t="Відзнаки полювання",b="Для Гаркена Віндтотема збирання трофейних пер — не так вилов звірини, як виховання дисципліни. У культурі тауренів носити знаки важко здобутого полювання означає кмітливість і наполегливість. Піднести ці бездоганні пера старійшинам у Селі Бладгуф — значить показати, що шукач пригод здатен годувати й боронити громаду, що його копита прудкі, а чуття досить гострі, щоб опанувати ширший світ."}},faq={{q="Навіщо полювати на стрімкокрилів для Гаркена Віндтотема?",a="Гаркен Віндтотем доручає мисливцям вистежувати стрімкокрилів по всьому Малгору, щоб перевірити їхню кмітливість, швидкість і відданість. Цілі трофейні пера — визнаний доказ мисливської вправності, що приносить шану серед тауренів Села Бладгуф.",al={"навіщо полювати на стрімкокрилів","мета завдання гаркена","мета полювання на стрімкокрилів"}},{q="Де зазвичай трапляються стрімкокрили?",a="Стрімкокрилів можна побачити по всіх відкритих рівнинах Малгора: вони ширяють над преріями чи видивляються здобич у траві довкола поселень на кшталт Села Бладгуф.",al={"де стрімкокрили","місця стрімкокрилів у мулґорі","знайти стрімкокрилів"}},{q="Чому на стрімкокрилів важко полювати?",a="На відміну від стадних тварин, що разом пересуваються рівнинами, стрімкокрили — прудкі, пильні хижі птахи, які тримаються розрізнено й усе помічають. Щоб їх вистежити, потрібен гострий зір, аби помітити, куди вони летять, і швидкий крок, аби збити їх, перш ніж вони втечуть.",al={"чому важко ловити стрімкокрилів","поведінка стрімкокрилів"}},{q="Що трофейні пера означають для тауренів?",a="За традиціями тауренів, трофейні пера стрімкокрилів уособлюють терпіння, гострий зір і вдале переслідування. Хто їх показує, той доводить, що має чуття, потрібне, щоб годувати й захищати плем'я.",al={"що означають трофейні пера","значення пер"}},{q="Хто такий Гаркен Віндтотем?",a="Гаркен Віндтотем — шанований таурен із Села Бладгуф, що придивляється до новачків і молодих мисливців і оцінює їхню винахідливість традиційними випробуваннями на рівнинах.",al={"хто дає полювання на стрімкокрилів","переказ про гаркена віндтотема"}},{q="Чи порушує це полювання рівновагу природи в Малгорі?",a="Таурени ставляться до полювання як до священної розмови із Земною Матір'ю, а не як до безглуздого вбивства. Збір пер — виважене випробування дисципліни, що шанує кмітливість здобичі й водночас береже рівновагу племені.",al={"чи полювання надмірне","рівновага стрімкокрилів мулґору"}}},fp="13,385,19.466.0,18.451.0,59.252.0,39.172.0,41.246.0,48.215.0,24.192.0,55.222.0"}
P.entries["quest:763"] = {n="Обряди Земної Матері",s="«Обряди Земної Матері» знаменують перехід молодого таурена з відлюдного Плато Червоної Хмари на широкі рівнини Малгору. Коли ви довели свій гарт у Таборі Нарачі, Вождь Гоквінд посилає вас на північ, до Села Бладгуф, із різьбленим тотемом — продовжити прадавні випробування під проводом Бейна Бладгуфа.",h="«Обряди Земної Матері» знаменують перехід молодого таурена з відлюдного Плато Червоної Хмари на широкі...",kw={"обряди земної матері","тотем","вождь гоквінд","бейн бладгуф","село бладгуф","плато червоної хмари","табір нарачі"},ang={["faction:Horde"]="Традиційні обряди зміцнюють племінну єдність по всьому Малгору й гарантують, що нові захисники Орди мають і бойову вправність, і глибоке духовне підґрунтя.",["race:Tauren"]="Кожен молодий таурен має пройти шлях Земної Матері, щоб довести свою вартість старійшинам і знайти місце серед об'єднаних племен."},sec={{t="Прощання з плато",b="Поколіннями молоді таурени випробовували свою силу в безпечній колисці Табору Нарачі на Плато Червоної Хмари. Пройдені перші випробування доводять дисципліну й рішучість вижити, але священні Обряди Земної Матері вимагають значно більшого, ніж уміння впоратися з місцевою звіриною. Вождь Гоквінд бачить, коли посвячений переріс затишні мисливські угіддя плато й має ступити в ширшу громаду."},{t="Знак для Бейна",b="Щоб з'єднати шлях від Нарачі до центральних поселень, Вождь Гоквінд дає різьблений власноруч тотем як знак рекомендації. Несучи цю відзнаку звивистою стежкою до Села Бладгуф, ви стаєте перед Бейном Бладгуфом — молодим вождем села й сином Верховного Вождя Кайрна Бладгуфа. Тотем засвідчує вашу готовність до обрядів духу й мудрості, що чекають попереду."}},faq={{q="Навіщо це завдання?",a="Це обряд посвяти, що виводить вас зі стартового Табору Нарачі й скеровує до Села Бладгуф, — так починається наступний розділ обрядових випробувань тауренів.",al={"навіщо обряди земної матері","що робить це завдання","мета завдання"}},{q="Хто такий Бейн Бладгуф?",a="Бейн Бладгуф — син Верховного Вождя Кайрна Бладгуфа. Він очолює Село Бладгуф як шанований місцевий вождь і наглядає за духовними й бойовими випробуваннями молодих тауренів.",al={"хто такий бейн","переказ про бейна","син керна"}},{q="Що таке Тотем Гоквінда?",a="Це дерев'яний тотем, який власноруч вирізьбив Вождь Гоквінд із Табору Нарачі. Він слугує офіційною рекомендацією й знаком схвалення: він доводить Бейнові Бладгуфу, що ви заслужили благословення Гоквінда на подальші обряди.",al={"тотем гоквінда","тотем гоквінд","різьблений тотем"}},{q="Які обряди йдуть після цього?",a="Коли ви прибудете до Села Бладгуф і зустрінетеся з Бейном, на вас чекає Обряд видіння, що перевіряє вашу духовну чуйність через священні видіння предків.",al={"наступні обряди","що далі","наступне завдання"}},{q="Де розташоване Село Бладгуф?",a="Село Бладгуф лежить на північ від Табору Нарачі, на берегах Озера Кам'яного Бика в центрі Малгора. Мандрівникам досить спуститися з плато головною дорогою й іти на північ.",al={"де село бладгуф","як знайти бладгуф","шлях до бладгуфа"}},{q="Чому треба пройти обряди Земної Матері?",a="Обряди Земної Матері — глибоко священні традиції тауренів. Пройшовши всі їхні етапи, учень показує тілесну витривалість, духовний зв'язок і мудрість і здобуває справжнє визнання старійшин Тандер Блафа.",al={"чому обряди земної матері","мета випробувань тауренів","переказ про обряди земної матері"}}},fp="24,305,16.421.0,17.420.0,34.199.0,23.201.0,30.219.0,27.170.0,35.185.0,44.246.0"}
P.entries["quest:764"] = {n="Корпорація «Венчур»",s="Огляд сплюндрованого каравану Венчурної Компанії в Малгорі відкриває, що гобліни Венчурної Компанії напористо вгризаються у східні пагорби. Коли їхні офіційні прохання про дозвіл на видобуток рішуче відхилили, компанія все одно взялася довбати землю Земної Матері, і Морін Клаудсталкер замовив смертельну відповідь.",h="Огляд сплюндрованого каравану Венчурної Компанії в Малгорі відкриває, що гобліни Венчурної Компанії напористо...",kw={"венчурна компанія","гобліни","видобуток","морін клаудсталкер","малгор","наглядачі","вторгнення"},ang={["faction:Horde"]="Захист Малгору від торгового визиску скріплює вашу відданість народові Кайрна Бладгуфа, що намагається закріпитися на новій батьківщині.",["profession:Mining"]="Венчурна Компанія діє лише грубим видобутком: зрізає кути й розхитує землю без жодної поваги до природної рівноваги чи безпечного гірничого ремесла.",["race:Tauren"]="Для тауренів Земна Матір священна. Відкритий видобуток Венчурної Компанії — не просто вторгнення, а брутальне споганення прабатьківського дому, що вимагає негайного й рішучого вигнання."},sec={{t="Промислове вторгнення",b="Таурени Малгору шанують землю як продовження Земної Матері й бережуть її незаймані рівнини та врівноважену звірину. Коли Венчурна Компанія звернулася до племен по право підривати й розкопувати пагорби заради сирої руди, її клопотання відхилили беззастережно. Не зважаючи ні на племінні ухвали, ні на чужу територіальну владу, невідступний картель потай завіз важку техніку, робітників і наглядачів просто на східні кряжі Малгору, щоб добувати руду поза законом."},{t="Недвозначне послання",b="Тауренські розвідники на кшталт Моріна Клаудсталкера розуміють: коли кайла вже б'ють у камінь, корпоративну захланність дипломатичними зверненнями не вгамуєш. Маючи документи зі сплюндрованого каравану Венчурної Компанії, які підтверджують її гірничі роботи, Морін посилає звитяжців Орди вирізати і наглядачів, що ляскають батогами, і робітників, що крутять бури. Кривава відплата має змусити Венчурну Компанію порахувати, що ціна вторгнення надто висока."}},faq={{q="Чому Венчурна Компанія в Малгорі?",a="Венчурна Компанія незаконно збудувала заставу й копальню на східних пагорбах Малгора, щоб добувати мінерали й природні ресурси. Таурени офіційно відмовили їй у праві на видобуток, але картель знехтував владою племен і все одно розгорнув роботи.",al={"чому гобліни в мулґорі","мотив венчурної компанії","чого хоче венчурна компанія"}},{q="Хто наказав напасти на гірників?",a="Наказ дає Морін Клаудсталкер, таурен, що вартує неподалік Села Бладгуф. Те, що картель не визнав відмови племен, він вважає прямим порушенням, на яке треба відповідати силою, а не розмовами.",al={"хто дає завдання","роль моріна клаудсталкера","видавець завдання"}},{q="Де копальня Венчурної Компанії?",a="Головна Шахта Венчурної Компанії — у передгір'ях на схід від Сплюндрованого Каравану й Села Бладгуф. Менший гурт людей компанії можна зустріти також на заставі, захованій серед круч на північний схід від північних підйомників Тандер Блафа.",al={"місце копальні венчурної компанії","де наглядачі","де знайти венчурну компанію"}},{q="Чи намагалися таурени домовитися з гоблінами?",a="Так. Венчурна Компанія просила тауренів про офіційне право на видобуток у Малгорі. Ватажки племен не дозволили обдирати відкритим способом землі предків, але гобліни просто стали копати без дозволу.",al={"чи таурени дозволили копати","права на видобуток мулґор","чи гобліни питали дозволу"}},{q="Чи ці гобліни — частина картелю Стімвідл?",a="Ні. Венчурна Компанія — незалежний і горезвісно хижацький промисловий картель, окремий від нейтральних торгових спілок на кшталт картелю Стімвідл. Скрізь, де вона виснажує ресурси, вона ворогує з місцевими мешканцями.",al={"чи це гобліни раджета","чи венчурна компанія дружня","фракція венчурної компанії"}},{q="Як це пов'язано зі сплюндрованими караванами?",a="Сплюндрований Караван був обозом Венчурної Компанії, який знищили таурени. Ящики гірничого відділу й документи, знайдені серед решток, розкрили діяльність компанії в Малгорі — і це спонукало до удару по її копальні.",al={"зв'язок з караванами","чи напали на каравани","зв'язок зі сплюндрованим караваном"}}},fp="15,339,20.472.0,23.485.0,38.269.0,40.215.0,42.253.0,54.219.0,50.237.0,46.224.0"}
P.entries["quest:765"] = {n="Наглядач Фіззпрокет",s="Наглядач Фіззпрокет — високопоставлений доглядач Венчурної Компанії, що засів у гірничих тунелях Малгору. За дорученням Моріна Клаудсталкера покласти край розрахованому грабунку гоблінського підприємства шукачі пригод Орди входять до копальні, щоб знищити його й забрати його докладну дошку з записами.",h="Наглядач Фіззпрокет — високопоставлений доглядач Венчурної Компанії, що засів у гірничих тунелях Малгору.",kw={"фіззпрокет","наглядач","венчурна компанія","копальня","морін клаудсталкер","малгор","гобліни"},ang={["faction:Horde"]="Допомога тауренам проти корпоративних грабіжників зміцнює захист Орди над щойно здобутими серцевинними землями Калімдору.",["race:Tauren"]="Відкритий задум Венчурної Компанії виселити ваше плем'я й розграбувати священну землю робить убивство Фіззпрокета актом життєво важливої оборони території."},sec={{t="Змова проти рівнин",b="Документи зі знищеного каравану Венчурної Компанії відкрили: Венчурна Компанія не просто копала руду — вона свідомо виношувала плани цілком вигнати тауренів із Малгору. Викорінивши тубільців, захланна корпорація прагнула нестримної свободи обдирати пагорби й глибокі підземні жили до останньої крихти природних багатств."},{t="Удар по старшому",b="Морін Клаудсталкер, розлючений корпоративними звірствами, замисленими проти його народу, посилає звитяжців до копальні Венчурної Компанії одразу на схід від сплюндрованих торгових возів. Глибоко в правих тунелях, в оточенні робітників і менших начальників, роботами керує Наглядач Фіззпрокет. Здолати Фіззпрокета й забрати його дошку з записами означає розірвати місцеву злагодженість і здобути важливі відомості про подальші задуми компанії."}},faq={{q="Хто такий Наглядач Фіззпрокет?",a="Наглядач Фіззпрокет — бос Венчурної Компанії, що керує роботами в шахтних тунелях на сході Малгора. Він наглядає за робітниками, які вгризаються в землю, і втілює задуми компанії, як поширити її діяльність по всьому краю.",al={"фіззпрокет","хто такий фіззпрокет","переказ про фіззпрокета"}},{q="Чому Морін Клаудсталкер хоче смерті Фіззпрокета?",a="На розграбованому каравані Морін знайшов документи, що доводять: Венчурна Компанія задумала заради наживи вигнати тауренів із землі предків. Фіззпрокет — безпосередній наглядач, що втілює ці розраховані плани визиску.",al={"чому вбивати фіззпрокета","мотив моріна клаудсталкера"}},{q="Де знайти Наглядача Фіззпрокета?",a="Він у копальні Венчурної Компанії просто на схід від Сплюндрованого Каравану в Малгорі. У копальні йдіть крайнім правим тунелем до зали, де він стоїть серед робітників і наглядачів.",al={"де фіззпрокет","місце копальні фіззпрокета","карта фіззпрокета"}},{q="Якого доказу перемоги над Фіззпрокетом вимагає Морін?",a="Морін Клаудсталкер вимагає особистий планшет Фіззпрокета з книгами обліку й записами, які можуть розкрити дальші задуми Венчурної Компанії в Малгорі.",al={"доказ смерті","планшет фіззпрокета"}},{q="Чому Венчурна Компанія в Малгорі?",a="Венчурна Компанія — безсовісний торговий картель, що прагне обібрати незаймані землі до нитки: деревину, мінерали й цінні підземні багатства, — геть не зважаючи на корінних мешканців чи рівновагу природи.",al={"венчурна компанія в мулґорі","чому гобліни в мулґорі"}},{q="Чи смерть Фіззпрокета остаточно прожене Венчурну Компанію?",a="Ні. Загибель Фіззпрокета розладнує місцевий провід і дає Морінові Клаудсталкеру важливі записи про їхні плани, але Венчурна Компанія лишається вкоріненою загрозою на пагорбах Малгора.",al={"чи пішла венчурна компанія","після смерті фіззпрокета"}}},fp="22,298,25.371.0,21.456.1,30.251.0,50.232.0,40.207.0,54.160.0,38.219.0,67.204.0"}
P.entries["quest:766"] = {n="Маззранаш",s="Маур Рейнколлер із Села Бладгуф став жертвою отруйного укусу Маззранаша — легендарного степового довгоступа, що жахав його діда ще покоління тому. Охоплений гарячкою й маячними кошмарами, таурен потребує сильних ліків, зварених із дарів дикої природи Малгору, поки зараження не забрало його життя.",h="Маур Рейнколлер із Села Бладгуф став жертвою отруйного укусу Маззранаша — легендарного степового довгоступа...",kw={"маззранаш","маур рейнколлер","село бладгуф","степовий довгоступ","ліки","малгор","мисливець"},ang={["class:Hunter"]="Вистежування степових вовків, кугуарів, довгоступів і стрімкокрилів у Малгорі — практичний урок читання рівнин і розуміння самобутньої живої природи савани.",["faction:Horde"]="Захист Села Бладгуф від суворих небезпек Малгору життєво важливий для миру й стабільності на батьківщині тауренів.",["race:Tauren"]="Ліки, які готує Маур, відображають прадавню практику тауренів черпати зцілення просто з рослин і тварин Земної Матері."},sec={{t="Спадок рівнин",b="Роками Маур Рейнколлер вважав Маззранаша лише моторошною родинною байкою, яку переказував його дід. Старий таурен розповідав про надзвичайно лютого степового довгоступа із сяйливими червоними очима, гострими як бритва пазурами й отруйним укусом — геть не схожого на мирних звірів Малгору. Коли Маур натрапив на звіра серед відкритих трав, легенда виявилася аж надто справжньою: він дістав тяжку рану й ледве дібрався до безпечного місця."},{t="Наввипередки із зараженням",b="Отрута звіра діє швидко, викликаючи сильну гарячку й кошмарну маячню. Щоб вигнати отруту, поки вона не стала смертельною, традиційна медицина тауренів покладається на життєву силу місцевих звірів. Маурові потрібні серце степового вовка, стегнова кістка рівнинного кугуара, луска степового довгоступа й шлунок стрімкокрила. Поєднавши сутності цих різних мисливців і падальників, він зможе зварити зілля, здатне зупинити омертвіння й повернути йому здоров'я."}},faq={{q="Що таке Маззранаш?",a="Маззранаш — горезвісний рівнинний довгоступ, що блукає луками Малгора. На відміну від звичайних рівнинних довгоступів, він відомий яскравим пір'ям, демонічними червоними очима, лютими пазурами й надзвичайно отруйним укусом. Він тероризує мандрівників уже кілька поколінь.",al={"хто такий маззранаш","що за звір маззранаш","переказ про маззранаша"}},{q="Хто такий Маур Рейнколлер?",a="Маур Рейнколлер — таурен із Села Бладгуф. Коли він ішов через Малгор, Маззранаш напав на нього й укусив у плече, і тепер Маур прикутий до ліжка з небезпечним для життя отруєнням.",al={"маур рейнколлер","хто дав це завдання","хто хворий таурен"}},{q="Навіщо Маурові частини чотирьох різних звірів?",a="Традиційні ліки тауренів спираються на природну силу й духовну суть звірів рівнин, щоб знешкоджувати сильні отрути. Вовче серце, густий кістковий мозок зі стегнової кістки пуми, луска рівнинного довгоступа й шлунок стрімкокрила разом дають протиотруту, досить сильну проти отрути Маззранаша.",al={"чому вовче серце і стегно пуми","чому тваринні інгредієнти","інгредієнти ліків маззранаша"}},{q="Чи дід Маура вбив Маззранаша?",a="Ні. Дід Маура колись бився з цим лютим рівнинним довгоступом, але не зміг його здолати: він лише вижив і переказав нащадкам застережні історії про його яскраве пір'я й жорстокі напади.",al={"чи дід переміг маззранаша","дід маура маззранаш","хто раніше бився з маззранашем"}},{q="Чи треба в цьому завданні полювати на самого Маззранаша?",a="Ні. Для Маура зараз головне — пережити гарячку. Завдання цілком зосереджене на зборі складників для його ліків, а не на полюванні на легендарного птаха.",al={"чи вбивати маззранаша","де маззранаш","полювання на маззранаша"}},{q="Де розташоване Село Бладгуф?",a="Село Бладгуф лежить у центрі Малгора, на південь від Тандер Блафа й трохи на схід від Озера Кам'яного Бика. Це головне поселення для молодих воїнів-тауренів, що вирушають на широкі рівнини.",al={"де село бладгуф","місце села бладгуф"}}},fp="11,313,22.471.0,20.462.0,20.251.0,23.208.0,52.303.0,40.198.0,55.180.0,35.193.0"}
P.entries["quest:767"] = {n="Обряд видіння",s="Обряд видіння — ключове випробування дорослішання в Обрядах Земної Матері, що перевіряє духовну зрілість молодого шукача пригод. Розпочате Бейном Бладгуфом, завдання спрямовує претендентів по пораду до сільського провидця Зарлмана Ту-Мунса. Ця подорож неодмінна для кожного, хто прагне благословення й поваги старійшин на узвишшях Тандер Блафа.",h="Обряд видіння — ключове випробування дорослішання в Обрядах Земної Матері, що перевіряє духовну зрілість...",kw={"обряд видіння","обряди земної матері","зарлман ту-мунс","бейн бладгуф","село бладгуф","провидець","духи"},ang={["class:Druid"]="Єднання з видіннями Земної Матері прямо зміцнює друїдське покликання уважно слухати мудрість і шепіт живого світу.",["class:Shaman"]="Пошук Зарлмана Ту-Мунса й шлях видінь глибоко суголосні шаманському обов'язку узгоджувати мирські справи з волею предків.",["faction:Horde"]="Проходження цих традиційних священних обрядів доводить вашу вірність і культурну шану тауренським старійшинам, які допомагають вести Орду.",["race:Tauren"]="Обряд видіння — неодмінна культурна віха для кожного молодого таурена, що знаменує ваше перетворення на довіреного захисника й духоходця племен."},sec={{t="Священна сходинка",b="Поколіннями кочові таурени зверталися до Земної Матері, щоб вона вела їхній народ рівнинами Калімдору. Тепер, зібравшись у безпечних межах Малгору, вони зберігають духовні традиції як наріжний камінь свого суспільства. Обряд видіння — одне з прадавніх випробувань, відомих як Обряди Земної Матері. Якщо попередні випробування перевіряють тілесну силу посвяченого і зв'язок із полюванням, то Обряд видіння вимагає подорожі всередину себе й спрямовує молодих тауренів і шанованих союзників безпосередньо до єднання з духами."},{t="Настанова провидця",b="Перш ніж шукати будь-якого духовного видіння, посвяченого має підготувати хтось обізнаний у прадавній мудрості. У Селі Бладгуф цей обов'язок лягає на шанованого шамана Зарлмана Ту-Мунса. Бейн Бладгуф довірив йому готувати мандрівників, і Зарлман має гострий зір, щоб розпізнати тих, хто ступає шляхом предків, і провести попередні обряди та священні приготування, потрібні, щоб пронизати заслону тілесного світу."}},faq={{q="Що таке Обряд видіння?",a="Обряд видіння — священний ритуал серед Обрядів Земної Матері. Він має розширити духовний зір шукача пригод, щоб той зміг єднатися з духами предків і показати старійшинам Тандер Блафа свою духовну готовність.",al={"завдання обряд видіння","що таке обряд видіння","переказ про обряд видіння"}},{q="Хто дає це завдання?",a="Завдання дає Бейн Бладгуф, син Верховного Вождя Кайрна Бладгуфа. Бейн опікується поселенням Село Бладгуф і скеровує гідних мандрівників до духовних старійшин селища.",al={"хто дає обряд видіння","видавець обряду видіння"}},{q="Хто такий Зарлман Ту-Мунс?",a="Зарлман Ту-Мунс — досвідчений шаман-таурен і духовний провідник Села Бладгуф. Він готує мандрівників і учнів, які прагнуть пройти священні випробування на кшталт Обряду видіння.",al={"хто такий зарлман","переказ про зарлмана ту-мунса"}},{q="Чому Обряди Земної Матері важливі для тауренів?",a="Обряди Земної Матері — традиційна посвята для тауренів, що дорослішають. Пройшовши їх, учень доводить тілесну спроможність, духовну чуйність і незмінну шану до землі й здобуває повагу верховних старійшин.",al={"значення обрядів земної матері","чому обряди земної матері"}},{q="Чи можуть Обряд видіння пройти не таурени?",a="Так. Союзникам з Орди, які мандрують Малгором і здобули довіру племені Бладгуф, дозволено пройти шляхом Земної Матері: вони виказують повагу до традицій тауренів і натомість здобувають прихильність старійшин.",al={"чи орки можуть обряд видіння","не таурени земна матір"}},{q="Де відбувається це випробування?",a="Випробування починається в Селі Бладгуф — помітному поселенні тауренів біля берегів Озера Кам'яного Бика в центрі Малгора, на південь від Тандер Блафа.",al={"де обряд видіння","місце обряду видіння"}}},fp="14,381,23.535.0,19.443.0,27.255.0,22.205.0,25.190.0,61.255.0,44.208.0,33.154.0"}
P.entries["quest:768"] = {n="Збір шкур",s="«Збір шкур» — просте торгове прохання від Верена Толлстрайдера на узвишшях Тандер Блафа. Щоб забезпечувати столицю й випробовувати молодих мисливців, Верен приймає в'язки вичинених легких шкур в обмін на готові вироби. Це завдання показує глибоко вкорінену традицію тауренів перетворювати плоди полювання на рівнинах на необхідний одяг і обладунки.",h="«Збір шкур» — просте торгове прохання від Верена Толлстрайдера на узвишшях Тандер Блафа.",kw={"збір шкур","верен толлстрайдер","легка шкіра","шкірництво","тандер блаф","полювання","малгор"},ang={["class:Hunter"]="Мисливці, що вирушають на рівнини Малгору, природно вправні у вистежуванні здобичі й заготівлі легких шкур, потрібних Веренові.",["faction:Horde"]="Постачання сировини ремісникам Тандер Блафа зміцнює молоду столицю, поки вона розбудовує оборону й торгові зв'язки.",["race:Tauren"]="Для мисливців-тауренів ушанувати полеглого звіра, перетворивши його шкуру на корисні речі, — важлива культурна дисципліна, що передається з покоління в покоління."},sec={{t="Опора Тандер Блафа",b="У молодій столиці на високих столових горах Малгору ремесло й виживання йдуть пліч-о-пліч. Верен Толлстрайдер перетворює шкури на одяг і захисні обладунки, яких потребує дедалі більше населення Тандер Блафа. Замість заготовляти все сам, він заохочує молодих шукачів пригод, що вирушають на рівнини, приносити свою здобич, — і звичайне полювання стає почесною службою громаді."},{t="Шлях полювання",b="Для тауренів полювання на звірів у степах — не забава, а почесна справа, що годує, одягає й дає прихисток племені. Верен Толлстрайдер шукає мисливців, які прагнуть принести честь своєму кланові, і просить саме легкої шкіри, знятої з місцевих звірів. За дванадцять добре збережених шкур він віддячує мисливцеві міцними виробами, зміцнюючи взаємну підтримку, на якій тримається суспільство тауренів."}},faq={{q="Хто такий Верен Толлстрайдер?",a="Верен Толлстрайдер — шкірник із Тандер Блафа. Він шиє одяг і захисні обладунки для тауренів і вимінює свої вироби в мисливців, які приносять йому свіжі шкури з рівнин.",al={"верен толлстрайдер","хто дає збір шкур","видавець шкір тандер блаф"}},{q="Що потрібно Веренові Толлстрайдеру?",a="Верен просить дванадцять шматків легкої шкіри, знятої зі звірів, що блукають Малгором і сусідніми землями, щоб пошити вироби для Тандер Блафа.",al={"вимоги збору шкур","що принести веренові","матеріали збору шкур"}},{q="Де відбувається це завдання?",a="Завдання починається й закінчується у Верена Толлстрайдера нагорі, в Тандер Блафі, але щоб його виконати, доведеться полювати на диких звірів на луках унизу.",al={"де верен толлстрайдер","місце збору шкур"}},{q="Чому таурени надають такого значення полюванню на звірів?",a="Таурени бачать у полюванні священну рівновагу із Земною Матір'ю. Кожна частина вбитого звіра йде в діло: м'ясо годує плем'я, а з кісток і вичинених шкур роблять знаряддя, намети й міцні обладунки.",al={"культура полювання тауренів","чому полювати за шкірою","переказ про шкіру тауренів"}},{q="Чи може будь-який шукач пригод Орди взятися за це доручення?",a="Так, допомогти Веренові зібрати шкіру може кожен мандрівник, відданий Орді, якого Верен вважає охочим випробувати себе на рівнинах.",al={"хто може зібрати шкури","чи збір шкур лише для орди"}},{q="Що буде, коли доставити шкіру?",a="Верен перевіряє якість шкур, хвалить мисливця за роботу й чесно обмінює їх на виготовлену ним річ зі спорядження.",al={"здати збір шкур","нагорода верена толлстрайдера"}}},fp="17,360,24.407.0,19.436.0,25.210.0,33.153.0,33.147.0,61.219.0,45.137.0,43.128.0"}
P.entries["quest:769"] = {n="Сумка зі Шкіри Кодо",s="«Сумка зі Шкіри Кодо» — торгове завдання від Верена Толлстрайдера, вправного шкірника-таурена на високих столових горах Тандер Блафа. В обмін на основні ремісничі матеріали він передає традиційну техніку рівнин — як зшивати міцні дорожні торби з цупкої звіриної шкури. Це одне з перших випробувань для учнів-шкірників у Малгорі.",h="«Сумка зі Шкіри Кодо» — торгове завдання від Верена Толлстрайдера, вправного шкірника-таурена на високих...",kw={"сумка зі шкіри кодо","верен толлстрайдер","кодо","шкірництво","тандер блаф","малгор"},ang={["faction:Horde"]="Ремісники Тандер Блафа постачають необхідні речі, завдяки яким мисливці, розвідники й воїни Орди завжди споряджені в центральному Калімдорі.",["race:Tauren"]="Для шу'гало навчитися виготовляти надійне спорядження з могутнього кодо — важливий крок до вшанування щедрот Земної Матері й збереження звичаїв предків."},sec={{t="Урок на столовій горі",b="На ремісничих узвишшях Тандер Блафа Верен Толлстрайдер береже давню кочову традицію нічого не марнувати з того, що дає полювання. Щоб заслужити його науку, молодий шкірник має принести йому вичинену легку шкіру й міцні нитки. Показавши вправність з основними матеріалами, учні доводять, що готові виготовляти речі, гідні носити спорядження для виживання суворими просторами Калімдору."},{t="Дух кодо",b="Для тауренів кодо — символ витривалості, сили й незламної рішучості. Його товста шкура захищає і від колючок, і від пронизливого вітру, і від пазурів звірів. Виготовляти сумки й одяг зі шкіри кодо — не просто практична справа, а вияв шани до тварини, що годувала й носила шу'гало незліченні покоління рівнинами Малгору."}},faq={{q="Хто дає завдання «Сумка зі Шкіри Кодо»?",a="Завдання дає Верен Толлстрайдер, таурен — наставник шкіряної справи й торговець у Тандер Блафі.",al={"видавець завдання","де взяти завдання сумки зі шкіри кодо","де верен толлстрайдер"}},{q="Хто може взятися за це доручення?",a="Отримати це навчальне доручення від Верена Толлстрайдера можуть лише шукачі пригод, що навчаються Шкіряній справі й досягли щонайменше 10-го рівня вміння учня.",al={"хто може взяти завдання","вимоги завдання","вимога професії"}},{q="Які матеріали потрібні Веренові Толлстрайдеру?",a="Йому потрібні чотири шматки Легкої Шкіри й чотири котушки Грубої Нитки, щоб поповнити свої запаси, перш ніж він поділиться викрійкою.",al={"які предмети потрібні","матеріали сумки зі шкіри кодо","предмети для здачі"}},{q="Чому шкіра кодо така важлива для майстрів-тауренів?",a="Кодо уособлюють витривалість і фізичну міць — риси, які таурени глибоко шанують. Виготовлення міцного спорядження з їхніх шкур шанує дух звіра й водночас дає надійну річ мандрівникам, що перетинають рівнини.",al={"чому шкіра кодо","значення кодо для тауренів","важливість кодо"}},{q="Чого навчає Верен Толлстрайдер, коли завдання виконано?",a="Отримавши матеріали, Верен навчає майстра особливих знань, потрібних, щоб пошити Сумку зі Шкіри Кодо.",al={"нагорода завдання","що я отримаю","викрійка сумки"}},{q="Де взяти потрібні матеріали?",a="Легку Шкіру знімають зі звірів низьких рівнів по всьому Малгору й сусідніх землях, а Грубу Нитку можна купити просто в торговців товарами для ремесел і кравецтва.",al={"де взяти легку шкіру","де взяти грубу нитку"}}},fp="13,362,20.426.0,18.388.0,35.113.0,39.149.0,46.133.0,59.224.0,50.125.0,46.176.0"}
P.entries["quest:770"] = {n="Плащ зі шрамом від демона",s="Плащ зі шрамом від демона — Демоноспоганений Плащ, подерта шкура легендарного білого вовка на ім'я Примарне Виття, що блукає трав'янистими рівнинами Малгору. Позначена незагойною раною від давніх сутичок із Палаючим Легіоном, шкура свідчить, що звіра звільнено від мук. Принести її старійшинам Села Бладгуф означає завершити історію трагічної місцевої легенди.",h="Плащ зі шрамом від демона — Демоноспоганений Плащ, подерта шкура легендарного білого вовка на ім'я Примарне...",kw={"примарне виття","вовк","плащ","демон","палаючий легіон","скорн вайтклауд","село бладгуф","малгор"},ang={["class:Druid"]="Друїди бачать у споганеній демоном шкурі похмуре нагадування: земля та її дикі мешканці досі носять незагоєні рани від демонічного вторгнення в Калімдор.",["class:Hunter"]="Вистежити самотнього пошрамованого ватажка, як-от Примарне Виття, — неодмінний обряд посвяти, що здобуває високу похвалу й дарунок майстра-мисливця від старійшини Скорна Вайтклауда.",["race:Tauren"]="Для шу'хало полювання на Примарне Виття — не жорстокість і не завоювання, а скорботний обряд, що дарує змученому створінню спокій від незгасної скверни Палаючого Легіону."},sec={{t="Реліквія ран Скверни",b="Примарне Виття — невловимий білий вовк, відомий по всьому Малгору і лютістю, і тужливим виттям. Коли звіра вбивають, по ньому лишається шкура, помітно пошрамована огидною демонічною скверною. Ці незгасні сліди сягають відчайдушних боїв вовка з демонами-загарбниками Палаючого Легіону — зіткнення, що лишило Примарне Виття зраненим і тілом, і духом ще довго після кінця Третьої війни."},{t="Спокій для змученого духу",b="Таурени Малгору глибоко шанують диких звірів своєї батьківщини як дітей Земної Матері. Піднесений Скорну Вайтклауду в Селі Бладгуф пошрамований плащ підтверджує загибель змученого хижака. Скорн визнає, якої величезної майстерності треба, щоб вистежити й здолати Примарне Виття, і висловлює скорботну надію: у смерті замордований дух вовка нарешті знайшов спокій."}},faq={{q="Що таке Демоноспоганений Плащ?",a="Це пошарпана шкура Примарного Виття, легендарного білого вовка Малгора. Хутро помітно пооране шрамами від енергії Скверни, що лишилися після давньої битви з Палаючим Легіоном.",al={"що таке демоноспоганений плащ","предмет демоноспоганений плащ","шкура примарного виття"}},{q="Звідки на плащі демонічні шрами?",a="Примарне Виття дістав ці рани в сутичках із Палаючим Легіоном, коли демонічні загарбники наступали Калімдором під час Третьої війни.",al={"чому примарне виття зі шрамами","як примарне виття отримало шрами","примарне виття легіон"}},{q="Кому віднести плащ?",a="Плащ треба віднести Скорну Вайтклауду, старому мисливцеві-таурену, що живе в Селі Бладгуф у Малгорі.",al={"кому віднести плащ","де здати плащ зі шрамом","скорн вайтклауд здача"}},{q="Чому Скорнові Вайтклауду не байдуже Примарне Виття?",a="Скорн Вайтклауд — мисливець на спочинку, який знає Примарне Виття як грізного звіра, що тяжко постраждав від демонічної скверни. Він шанує вправність, потрібну, щоб звалити таку істоту, і сподівається, що її дух нарешті спочине.",al={"чому скорну небайдуже примарне виття","переказ про скорна вайтклауда"}},{q="Де знайти Примарне Виття?",a="Примарне Виття — рідкісний білий вовк, що блукає пологими рівнинами Малгора; найчастіше його бачать на північних чи центральних відкритих полях між Плато Червоної Хмари й Тандер Блафом.",al={"де примарне виття","місце примарного виття","поява примарного виття"}},{q="Чому таурени сподіваються, що дух вовка знайде спокій?",a="Таурени наголошують на гармонії з природою й шануванні диких духів. Демонічна скверна принесла Примарному Виттю нескінченні муки, тож його загибель вважають милосердним поверненням до Земної Матері.",al={"віра тауренів у примарне виття","дух примарного виття"}}},fp="23,378,21.424.0,27.421.0,32.174.0,49.141.0,28.104.0,48.224.0,26.172.0,53.220.0"}
P.entries["quest:771"] = {n="Обряд видіння",s="Обряд видіння — основоположне духовне випробування, яке проходять молоді таурени, виходячи з Плато Червоної Хмари у великий Малгор. Щоб пронизати заслону й дістати настанову духів предків, посвячені мають зібрати природні складники й зварити Воду Провидців під пильним оком Зарлмана Ту-Мунса в Селі Бладгуф.",h="Обряд видіння — основоположне духовне випробування, яке проходять молоді таурени, виходячи з Плато Червоної...",kw={"обряд видіння","вода провидців","зарлман ту-мунс","криничні камені","бурштиновий жолудь","село бладгуф","малгор"},ang={["class:Druid"]="Друїди глибоко шанують бурштинові жолуді й криничні камені, бачачи в них прямі прояви рослинності й життєдайних вод, що підтримують рівновагу Малгору.",["class:Shaman"]="Шаман упізнає в приготуванні Води Провидців традиційний обряд укорінення, що настроює дух читати незриме перед прямою розмовою з духами.",["race:Tauren"]="Для тауренів Обряд видіння — неодмінна культурна віха, що пов'язує майбутнього воїна, мисливця чи містика з духовним спадком Земної Матері й предків."},sec={{t="Складники землі",b="Перш ніж дістати видіння, посвячений має показати глибоке знання природних дарів Малгору. Зарлман Ту-Мунс велить шукачеві зібрати криничні камені біля священних громадських криниць і бурштинові жолуді, що впали під корінням прадавніх дерев Малгору. Для тауренів це не прості речі: вони містять приховану магію й життєву кров Земної Матері, готову влитися в обряд."},{t="Варіння Води Провидців",b="Із зібраних каменів і бурштинових жолудів Зарлман готує могутню Воду Провидців. Випитий біля племінного вогню села, цей обрядовий напій прояснює розум і прикликає безтілесного провідника. Іти за цією проявою через рівнини — справжнє серце обряду, що випробовує здатність посвяченого ходити між тілесним світом і духовним шепотом землі."}},faq={{q="Навіщо Обряд видіння?",a="Обряд видіння — духовне випробування для тауренів, що дорослішають і шукають свого шляху. Приготувавши й випивши Воду Провидців, учень вчиться єднатися з духами й іти за знаменнями предків рівнинами Малгора.",al={"що таке обряд видіння","навіщо обряд видіння","мета обряду видіння"}},{q="Хто такий Зарлман Ту-Мунс?",a="Зарлман Ту-Мунс — шаман і провидець-таурен у Селі Бладгуф. Він проводить духовні випробування для молодих шукачів пригод, готує обрядові напої на кшталт Води Провидців і тлумачить знаки Земної Матері.",al={"хто такий зарлман","роль зарлмана ту-мунса","видавець зарлман"}},{q="Де знайти камінці з криниць і бурштинові жолуді?",a="Камінці збирають на землі біля криниць зі свіжою водою, розкиданих по Малгору. Бурштинові жолуді лежать біля підніжжя великих розлогих дерев, що тут і там ростуть серед навколишніх лук.",al={"де бурштинові жолуді","місце камінців із криниць","реагенти обряду видіння"}},{q="Що буде, коли випити Воду Провидців?",a="Якщо випити напій біля вогнища племені, у того, хто пив, відкривається духовний зір і з'являється примарний звір-провідник. Шукач має йти за цим духом рівнинами, щоб відкрити наступний етап свого священного шляху.",al={"що далі в обряді видіння","дія води провидців","продовження обряду видіння"}},{q="Чому таурени так глибоко шанують криниці?",a="Вода — кров Малгора й дорогоцінний дар Земної Матері. Криниці — священні осередки громади, що живлять і землю, і стада, тож камінці, зібрані біля них, сповнені духовної сили.",al={"криниці тауренів","чому криниці священні","вода мулґору"}},{q="Чи веде це завдання до інших обрядів?",a="Так. Це доручення — частина багатоетапного обряду. Коли Зарлман приготує Воду Провидців, учні мають випити її, піти за видінням і стати перед старійшинами Малгора.",al={"наступне завдання обряду видіння","чи обряд видіння ланцюжок","ланцюжок обрядів тауренів"}}},fp="14,335,24.476.0,30.397.0,42.238.0,25.234.0,42.210.0,51.214.1,47.219.0,38.207.1"}
P.entries["quest:772"] = {n="Обряд видіння",s="Обряд видіння — духовна кульмінація прадавнього випробування, яке проходять молоді таурени в Селі Бладгуф. Випивши священну Воду Провидців біля племінного багаття, посвячені прикликають примарного провідника, який веде їх назустріч долі.",h="Обряд видіння — духовна кульмінація прадавнього випробування, яке проходять молоді таурени в Селі Бладгуф.",kw={"обряд видіння","вода провидців","примарний вовк","віщун вайзраннер","зарлман ту-мунс","село бладгуф","малгор"},ang={["class:Druid"]="Обряд зміцнює шану до природного світу й духовне смирення перед проводом звіриних подоб.",["class:Shaman"]="Іти за духовним вовком предків — ранній урок ходіння між світами, що закорінює зв'язок шамана з духами, які ведуть Орду.",["race:Tauren"]="Для молодих тауренів Обряд видіння — глибоко священний перехід у зрілість, що засвідчує єднання з предками й покору духовному проводу."},sec={{t="Вода Провидців",b="Коли потрібне обрядове зілля зібрано, а перші випробування віри пройдено, сільський шаман Зарлман Ту-Мунс дарує посвяченому Воду Провидців. Цей могутній напій треба випити перед ревучим племінним вогнем у серці Села Бладгуф. Спожиті із зосередженим і шанобливим розумом, священні води розширюють сприйняття питця поза тілесний зір, перекидаючи міст через заслону між матеріальним і духовним світами."},{t="Слідом за примарним вовком",b="Щойно напій випито, полум'я являє безтілесну з'яву — примарного вовка предків. Дух не говорить і не б'ється, а мовчки біжить на північний захід пагорбистими рівнинами Малгору. Справжній посвячений має зважати на його тиху стежку, йдучи за ним геть від села в глиб скелястих пагорбів, де в усамітненому спогляданні чекає відлюдник Віщун Вайзраннер."},{t="Хода до мудрості",b="Дістатися Віщуна Вайзраннера біля входу до його гірської печери означає успішно завершити видіння. Ця подорож трав'янистими пагорбами випробовує терпіння посвяченого, довіру до проводу предків і єднання із Земною Матір'ю. Пройдений обряд дає молодому шукачеві пригод право на останнє випробування зрілості — Обряд Мудрості."}},faq={{q="Що буде, коли я вип'ю Воду Провидців?",a="Якщо випити її біля вогнища племені в Селі Бладгуф, вода відкриває ваші духовні чуття. Невдовзі перед полум'ям з'являється примарний вовк-дух, щоб показати вам шлях.",al={"як діє вода провидців","випити воду провидців","що робить вода"}},{q="Куди веде мене дух-провідник?",a="Примарний вовк біжить на північний захід від Села Бладгуф пагорбами Малгора й веде просто до кам'янистої печери, де живе Віщун Вайзраннер.",al={"куди йде вовк-дух","до кого веде вовк","куди веде вовк"}},{q="Хто такий Зарлман Ту-Мунс?",a="Зарлман Ту-Мунс — визначний шаман-таурен у Селі Бладгуф, якому доручено готувати учнів до духовної дорослості обрядами предків і священними настоями.",al={"хто дає обряд видіння","роль зарлмана ту-мунса"}},{q="Хто такий Віщун Вайзраннер?",a="Віщун Вайзраннер — старий таурен-містик, що живе в спогляданні серед круч на північний захід від Села Бладгуф. Учні, які йдуть за своїм духовним видінням, знаходять його, щоб завершити випробування.",al={"хто такий віщун вайзраннер","віщун у печері мулґору"}},{q="Чому воду треба пити біля вогнища племені?",a="Вогнище племені — священна опора для духів предків Села Бладгуф. Освячене полум'я разом зі святою водою дає видінню змогу перейти у світ яви.",al={"чому племінне вогнище","багаття обряду видіння"}},{q="Який обряд іде після Обряду видіння?",a="Завершивши Обряд видіння з Віщуном Вайзраннером, учні вирушають на Обряд Мудрості — останнє духовне випробування їхнього раннього шляху в Малгорі.",al={"наступне завдання після обряду видіння","що далі"}}},fp="14,249,22.467.0,24.371.0,16.362.0,49.192.0,36.150.0,25.171.0,23.189.0,49.197.0,41.173.0"}
P.entries["quest:773"] = {n="Обряд Мудрості",s="Обряд Мудрості — завершальне випробування в традиційних Обрядах Земної Матері, які проходять молоді шукачі пригод у Малгорі. Очистивши свій зір Обрядом видіння, прохачі вирушають до священного поховання Червоних Скель, щоб поєднатися з Духом предків і дістати благословення мертвих.",h="Обряд Мудрості — завершальне випробування в традиційних Обрядах Земної Матері, які проходять молоді шукачі...",kw={"обряд мудрості","червоні скелі","дух предків","поховання","обряди земної матері","тандер блаф","кайрн бладгуф"},ang={["class:Druid"]="Обряд показує рівновагу між живим світом і вічним колом, яке наглядає Земна Матір, і закорінює молодих друїдів у їхньому обов'язку перед землею.",["class:Shaman"]="Пряме єднання з Духом предків зміцнює основний шаманський обов'язок шанувати мертвих і берегти вірність духам, що пильнують Малгор.",["race:Tauren"]="Для шу'хало прийняти мантію від предків на Червоних Скелях — вершина переходу в повну зрілість і визнання серед племінних старійшин."},sec={{t="Випробування Червоних Скель",b="Прояснивши сприйняття Обрядом видіння, молоді захисники вирушають на схід від Тандер Блафа, до Червоних Скель. Це прадавнє поховання береже тлінні рештки й незгасні духи тих, хто бився й поліг, щоб вибороти мирне життя в Малгорі. Щоб пройти випробування, треба наблизитися до місця спочинку з належною шаною і єднанням, здолавши будь-які територіальні загрози, що блукають пагорбами, і просити поради в шанованих мертвих."},{t="Передання мантії",b="На вершині Червоних Скель єднання з Духом предків — випробування не бойової сили, а духовної готовності й тяглості. Духи, що спочивають там, — покоління, яке билося пліч-о-пліч із Кайрном Бладгуфом, щоб заснувати Тандер Блаф і вберегти племена. Діставши їхнє благословення, прохач офіційно успадковує урочистий обов'язок захищати місто й здобуває місце визнаного дорослого й захисника, гідного з гордістю ввійти в Тандер Блаф."}},faq={{q="Навіщо Обряд Мудрості?",a="Обряд Мудрості завершує Обряди Земної Матері й пов'язує юнацьке єднання з видіннями з урочистими обов'язками дорослості. Здобувши благословення духів предків, учні доводять, що шанують жертви тих, хто жив раніше, і готові боронити Тандер Блаф.",al={"навіщо обряд мудрості","що робить обряд мудрості","мета обряду мудрості"}},{q="Хто посилає на Обряд Мудрості?",a="Віщун Вайзраннер у своїй печері на північний захід від Села Бладгуф посилає учнів на це випробування, коли вони пройдуть Обряд видіння й нап'ються Води Провидців.",al={"хто дає обряд мудрості","де почати обряд мудрості"}},{q="Де знайти Духа предків?",a="Дух предків перебуває на Червоних Скелях — прадавньому цвинтарі тауренів серед скелястих круч просто на схід від Тандер Блафа.",al={"місце духа предків","де дух","де знайти духа предків"}},{q="Чому спершу треба пройти Обряд видіння?",a="Лише ті, хто напився Води Провидців і очистив свій духовний зір, можуть побачити прадавніх духів на Червоних Скелях і прийняти їхнє благословення.",al={"чому спершу обряд видіння","умова обряду видіння","вимога води провидців"}},{q="Що буде після Обряду Мудрості?",a="Здобувши схвалення предків, учні отримують наказ урочисто вирушити на високі кручі Тандер Блафа.",al={"що після обряду мудрості","наступне завдання після обряду мудрості"}},{q="Які істоти загрожують Червоним Скелям?",a="На священний цвинтар Червоних Скель вдерлися агресивні гноли Пейлмейн, що чатують на кам'янистих стежках до прадавнього місця поховань.",al={"вороги червоних скель","хто охороняє червоні скелі","гноли на червоних скелях"}}},fp="14,321,22.468.0,18.492.0,42.310.0,36.186.0,39.137.0,41.175.0,49.138.0,49.160.0"}
P.entries["quest:775"] = {n="Подорож до Громового Бескиду",s="«Подорож до Громового Бескиду» — завершальне паломництво, що знаменує кінець випробувань молодого героя в Малгорі. Пройшовши священні Обряди Земної Матері під проводом духів, шукач пригод дістає аудієнцію у Верховного Вождя тауренів Кайрна Бладгуфа в Тандер Блафі.",h="«Подорож до Громового Бескиду» — завершальне паломництво, що знаменує кінець випробувань молодого героя в...",kw={"тандер блаф","кайрн бладгуф","верховний вождь","високе узвишшя","обряди земної матері","дух предків","паломництво"},ang={["faction:Horde"]="Готовність тауренів приймати будь-кого з союзних народів, хто пройде їхні священні традиції, промовляє про взаємну повагу, що тримає молоду Орду вкупі.",["race:Tauren"]="Для молодого таурена стати перед Кайрном Бладгуфом після обрядів Земної Матері — остаточний поріг зрілості й племінної честі."},sec={{t="Завершений обряд посвяти",b="Перш ніж будь-який мандрівник чи молодий воїн зможе по праву сказати, що довів себе в Малгорі, він має пройти прадавні Обряди Земної Матері. Ці випробування перевіряють силу, зір і мудрість на пагорбистих рівнинах і прабатьківських місцях краю. Щойно Дух предків визнає останній обряд, посвяченого вважають гідним увійти до міста Тандер Блаф не простим гостем, а шанованим захисником народу тауренів."},{t="Сходження на Високе Узвишшя",b="Завдання веде мандрівника зі священної землі, де блукають духи, просто на височінь Тандер Блафа. Місто, що вмостилося на верхівках плато, — маяк миру, витесаний із червоного каменю й з'єднаний розмашистими мотузяними мостами та величезними дерев'яними підйомниками. Там, на Високому Узвишші, Верховний Вождь Кайрн Бладгуф чекає, щоб особисто привітати тих, хто пройшов шляхом предків."}},faq={{q="Хто посилає в цю подорож?",a="Завдання дає Дух предків, коли ви завершите Обряд Мудрості — останній крок традиційних Обрядів Земної Матері.",al={"хто дає завдання","завдання духа предків","видавець завдання"}},{q="Де знайти Кайрна Бладгуфа?",a="Кайрн Бладгуф живе на Високому Узвишші — центральній піднесеній столовій горі Тандер Блафа, з якої видно навколишні червоні плато й рівнини.",al={"де кайрн","місце кайрна","ватажок тандер блафа"}},{q="Що означає виконання цього завдання?",a="Це урочисте завершення перших пригод у Малгорі. Ставши перед Кайрном, ви здобуваєте повне визнання проводу тауренів і готові братися до обов'язків по всій Орді.",al={"чому відвідати кайрна","значення обрядів","значення подорожі до громового бескиду"}},{q="Чи цю подорож проходять лише таурени?",a="Це глибоко традиційна посвята тауренів, але кожен член Орди, що довів свою відданість, пройшовши Обряди Земної Матері, удостоюється тієї самої честі й прямує на зустріч із Верховним Вождем.",al={"чи лише таурени","чи орки можуть це","які раси"}},{q="Що буде після розмови з Кайрном?",a="Кайрн вітає вас у своєму домі, визнає ваші подвиги й скеровує вас далі — у ширші протистояння, з якими Орда стикається по всьому Калімдору.",al={"наступне завдання","що після кайрна","після подорожі до громового бескиду"}},{q="Як дістатися до Високого Узвишшя в Тандер Блафі?",a="Підніміться з рівнин великими механічними підйомниками на столові гори, а тоді перейдіть мотузково-дерев'яними мостами до центрального майданчика Високого Узвишшя, де стоїть оселя Вождя.",al={"як дістатися високого узвишшя","як дістатися кайрна","ліфти тандер блафа"}}},fp="26,296,27.451.0,26.407.0,30.141.0,34.138.0,50.216.0,37.208.0,38.141.0,48.197.0"}
P.entries["quest:776"] = {n="Обряди Земної Матері",s="Це випробування особисто призначає Верховний Вождь Кайрн Бладгуф: молоді герої мають вистежити могутнього кодо Арра'чеа на рівнинах Малгора. Навіть коли новачок уже пройшов традиційні обряди посвяти, Кайрн чекає, що його народ знову й знову доводитиме свою силу, вправність слідопита й відданість племені. Ріг Арра'чеа — доказ того, що мандрівник готовий служити всій Орді й далеко за межами рідних плато.",h="Це випробування особисто призначає Верховний Вождь Кайрн Бладгуф: молоді герої мають вистежити могутнього...",kw={"кайрн бладгуф","арра'чеа","кодо","малгор","тандер блаф","обряд посвяти","полювання"},ang={["class:Hunter"]="Вистежувати самотнього мандрівного велетня на кшталт Арра'чеа золотими рівнинами — це втілення давньої мисливської мудрості, яку таурени-слідопити передають із покоління в покоління.",["faction:Horde"]="Вполювавши Арра'чеа, ви даєте Тандер Блафу харчі, шкури й матеріали — і показуєте ту спільну волю до виживання, на якій тримається молода Орда.",["race:Tauren"]="Постати перед Кайрном Бладгуфом із рогом Арра'чеа — найвищий обряд посвяти для молодого шу'гало: так ви доводите, що ваша вправність шанує і предків, і стада Малгора."},sec={{t="Мірило вождя",b="Коли молодий таурен сягає Тандер Блафа, його безтурботна юність скінчилася. Та Верховний Вождь Кайрн Бладгуф не дає молодим мисливцям спочивати на лаврах. Для Кайрна місце серед високих скель — лише початок обов'язку перед Об'єднаними племенами тауренів. Замість того щоб посилати новачків на дрібних шкідників, він вимагає доказу справжньої вправності: вистежити й чисто вполювати одного з найславетніших мандрівних звірів Малгора."},{t="Полювання на Арра'чеа",b="Здобич — Арра'чеа, велетенський легендарний кодо, що кружляє золотими травами на північний схід від Тандер Блафа. Щоб звалити таке створіння, самої лише сили замало: треба терпляче скрадатися відкритою саваною й шанувати цього велета рівнин. Ріг Арра'чеа, принесений на вершину, дарує не тільки особисту славу, а й припаси для міста: Кайрн одразу посилає білувальників і збирачів, щоб жодна частина священного звіра не пропала марно."}},faq={{q="Хто дає це завдання?",a="Це доручення дає сам Верховний Вождь Кайрн Бладгуф зі свого місця на Високому Узвишші Тандер Блафа.",al={"хто дає завдання","хто дає обряди земної матері","завдання кайрна"}},{q="Хто такий Арра'чеа?",a="Арра'чеа — грізний, знаменитий кодо, що блукає рівнинами Малгора. Його великий ріг — доказ уміння мисливця вистежувати й битися.",al={"хто такий арра'чеа","що таке арра'чеа","переказ про арра'чеа"}},{q="Де знайти Арра'чеа?",a="Арра'чеа зазвичай ходить широким колом на північний схід від круч Тандер Блафа, повільно обходячи відкриті пологі рівнини за годинниковою стрілкою.",al={"де арра'чеа","місце арра'чеа","шлях до арра'чеа"}},{q="Чому Кайрн просить про це полювання, коли ранні обряди вже пройдено?",a="У тауренів здобути своє перше місце — ще не кінець обов'язку. Кайрн навчає, що силу, скромність і мисливську вправність треба доводити знову й знову, щоб плем'я жило.",al={"чому це завдання","чому вбивати арра'чеа","сенс обрядів"}},{q="Що буде з тілом Арра'чеа, коли ріг узято?",a="За традицією тауренів шанувати свою здобич, Кайрн посилає людей забрати м'ясо й шкуру полеглого звіра, щоб ця здобич нагодувала й одягла Тандер Блаф.",al={"м'ясо арра'чеа","що буде з кодо","переказ про тушу"}},{q="Чи це те саме завдання, що й перші обряди?",a="Ні. Ранні випробування в Таборі Нарачі навчають учня основ Обрядів Земної Матері, а це завершальне випробування в Тандер Блафі — особиста перевірка Кайрна, чи ви й далі гідні звання мисливця.",al={"різниця обрядів земної матері","яке завдання обрядів","обряди табору нараше"}}},fp="24,439,21.449.0,22.491.0,21.108.0,18.161.0,27.154.0,78.183.0,57.183.0,50.204.0"}
P.entries["quest:7781"] = {n="Володар Блекрока",s="«Володар Блекрока» — завдання Альянсу, яке починається, щойно герой здобуде відрубану голову чорного дракона Нефаріана в Лігві Чорнокрила. Доставити цей жахливий трофей Верховному Лордові Болварові Фордрагону у Фортецю Стормвінда — означає сповістити про загибель господаря Гори Блекрок. Це один із найвеличніших військових тріумфів, які Альянс святкував за останні роки.",h="«Володар Блекрока» — завдання Альянсу, яке починається, щойно герой здобуде відрубану голову чорного дракона...",kw={"нефаріан","володар блекрока","лігво чорнокрила","болвар фордрагон","голова дракона","гора блекрок"},ang={["faction:Alliance"]="Голова чорного дракона Нефаріана — одне з найвеличніших бойових досягнень Альянсу: вона знаменує остаточний крах задумів драконячого роду проти людських земель.",["race:Human"]="Стормвінд зазнав незліченних нападів і змов, задуманих у Горі Блекрок; поразка її господаря дає королівству довгоочікувану відплату й полегшення."},sec={{t="Пам'ятник перемозі",b="Нефаріан, підступний володар Чорного драконячого роду й правитель Верхнього Шпиля Блекрока, довго кидав моторошну тінь на довколишні людські королівства. Убити його — це не лише питання виживання: це остаточний крах його збочених дослідів і підступів. Велетенська, посічена в боях голова, принесена до Стормвінда, — незаперечний доказ того, що Володар Блекрока загинув від рук найкращих героїв Альянсу."},{t="Аудієнція у Фортеці Стормвінда",b="Моторошний трофей приносять просто до Верховного Лорда Болвара Фордрагона, що править королівством із тронної зали Фортеці Стормвінда. Раптова поява відрубаної драконячої голови при королівському дворі приголомшує присутніх і викликає благоговіння. Королівству, яке й так потерпає від внутрішніх політичних чвар і зовнішніх загроз, ця перемога дає могутнє піднесення духу й назавжди вписується в літописи Альянсу."}},faq={{q="Про що завдання «Володар Блекрока»?",a="Це завдання починається, коли шукачі пригод здобувають відтяту Голову Нефаріана в Лігві Чорнокрила. Воно велить переможцеві віднести цей величний трофей до Стормвінда й від імені королівства вручити його Верховному Лордові Болвару Фордрагону.",al={"завдання володар блекрока","голова нефаріана альянс","голова нефаріана стормвінд"}},{q="Хто такий Нефаріан?",a="Нефаріан — великий чорний дракон, син Детвінга. Панував з висот Лігва Чорнокрила в Горі Блекрок, командував орками Блекрок і проводив зловісні досліди, щоб створити хроматичний драконячий рід.",al={"хто такий нефаріан","володар блекрока","переказ про нефаріана"}},{q="Хто такий Верховний Лорд Болвар Фордрагон?",a="Верховний Лорд Болвар Фордрагон — паладин, що за відсутності короля Варіана Рінна править Стормвіндом як регент: він приймає в тронній залі Фортеці Стормвінда й опікується юним принцом Андуїном Рінном.",al={"болвар фордраґон","хто такий болвар","верховний лорд болвар"}},{q="Чому цей трофей несуть до Фортеці Стормвінда?",a="Влада Нефаріана в Горі Блекрок смертельно загрожувала королівству Стормвінд і всьому південному материку. Трофей, принесений просто військовому проводу королівства, підтверджує загибель дракона й дає змогу всій державі згуртуватися довкола цього подвигу.",al={"чому стормвінд","чому нести голову до фортеці","чому болвар"}},{q="Що буде, коли віддати голову Болвару?",a="Верховний Лорд Болвар Фордрагон приголомшений подвигом і проголошує, що цей тріумф навіки ввійде в історію. Це веде просто до наступного етапу події, коли голову вивішують привселюдно, щоб її бачив увесь Стормвінд.",al={"що далі","володар блекрока частина 2","здати голову нефаріана"}},{q="Чи впливає здача голови на все місто?",a="Так. Коли Голову Нефаріана доставляють до столиці й підіймають над міською брамою, усі городяни й вояки дізнаються про загибель дракона, і захисників Стормвінда сповнює переможна рішучість.",al={"бонус для міста","бойовий клич","бонус голови нефаріана"}}},fp="21,369,21.471.0,26.462.0,42.234.0,16.232.0,33.202.0,45.280.0,45.243.0,48.221.0"}
P.entries["quest:7782"] = {n="Володар Блекрока",s="Це завдання — фінальний акорд кампанії проти сил Гори Блекрок. Доповівши Великому Адміралові Джес-Терету у Фортеці Стормвінда, герої вирушають до Долини Героїв, де Польовий Маршал Стоунбрідж влаштовує біля міської брами всенародне вшанування, щоб його побачив увесь Альянс.",h="Це завдання — фінальний акорд кампанії проти сил Гори Блекрок.",kw={"володар блекрока","нефаріан","долина героїв","польовий маршал стоунбрідж","бойовий клич драконоборця","стормвінд"},ang={["class:Warrior"]="Могутнє бойове натхнення від Бойового Клича Драконоборця додає снаги воїнам, що вирушають боронити королівство.",["faction:Alliance"]="Голова Нефаріана в Долині Героїв об'єднує всі раси Альянсу й нагадує громадянам Айронфорджа, Дарнасуса й Гномреґана, що темні сили, які терзають Східні Королівства, можна зламати.",["race:Human"]="Для королівства Стормвінд перемога над господарем Блекрока усуває смертельну драконячу загрозу, що чаїлася просто на його північному кордоні."},sec={{t="Тріумф міста",b="Кампанія проти клану Блекрок і виводку Чорного драконячого роду завершується всенародним святом перемоги. Після того як голову Нефаріана представили у Фортеці Стормвінда, Верховний Лорд Болвар Фордрагон скеровує героїв через усе місто до Долини Героїв. Там на них чекає Польовий Маршал Стоунбрідж, щоб прийняти моторошний трофей і розпочати святкування по всьому місту."},{t="Згуртування Альянсу",b="Коли Польовий Маршал Стоунбрідж підносить відрубану голову Нефаріана на великих арках головного входу до Стормвінда, це відчуває все місто. Видовище супроводжує Бойовий Клич Драконоборця, що надихає міських захисників, знатних гостей і простих городян звісткою: виводок Детвінга зазнав нищівного удару."}},faq={{q="Що буде, коли виконати це завдання?",a="Польовий Маршал Стоунбрідж вивішує відтяту голову Нефаріана високо на кам'яній арці брами в Долині Героїв. Це накладає на весь Стормвінд Бойовий клич драконоборця, що посилює бойову міць усіх дружніх гравців і вартових.",al={"здати голову нефаріана","що робить стоунбрідж","запуск бойового клича"}},{q="Хто такий Польовий Маршал Стоунбрідж?",a="Польовий Маршал Стоунбрідж — високий військовий чин армії Стормвінда, що стоїть у Долині Героїв, біля входу до міста. Він влаштовує привселюдне вшанування великих військових перемог, зокрема вивішує голови переможених драконів-загроз.",al={"стоунбрідж","польовий маршал стоунбрідж"}},{q="Чому Верховний Лорд Болвар Фордрагон посилає мене сюди?",a="Отримавши в тронній залі підтвердження загибелі Нефаріана, Болвар велить вам віднести звістку до міської брами, щоб військо Альянсу відкрито показало перемогу й підняло дух усієї столиці.",al={"болвар","чому йти до долини героїв"}},{q="Чи впливає це на все місто?",a="Так. Коли Стоунбрідж бере трофей, Стормвіндом лунає урочисте проголошення, і Бойовий клич драконоборця отримує кожен у межах міста.",al={"світовий бонус нефаріана","чи стормвінд отримує бонус"}},{q="Де Долина Героїв?",a="Долина Героїв — велична вхідна дорога до Стормвінда, обабіч якої стоять високі статуї на честь героїв Другої війни, що пройшли крізь Темний Портал.",al={"місце долини героїв","де стоунбрідж"}},{q="Хто такий «Володар Блекрока»?",a="Володар Блекрока — чорний дракон Нефаріан, старший син Детвінга й володар верхніх шпилів Гори Блекрок.",al={"хто такий володар блекрока","особа нефаріана"}}},fp="21,326,16.395.1,21.375.0,42.263.1,33.273.0,49.210.1,40.173.1,38.167.0,32.128.2"}
P.entries["quest:7783"] = {n="Володар Блекрока",s="Це завдання знаменує кульмінацію штурму Лігва Чорнокрила: чемпіони мають доставити до Оргріммара відрубану голову Нефаріана. Принісши цей жахливий трофей Вождеві Траллу, вони дають незаперечний доказ того, що виводок чорного драконячого роду зламано. Це мить величного тріумфу Орди над одним із її найпідступніших ворогів.",h="Це завдання знаменує кульмінацію штурму Лігва Чорнокрила: чемпіони мають доставити до Оргріммара відрубану...",kw={"нефаріан","володар блекрока","лігво чорнокрила","тралл","детвінг","гора блекрок","чорні дракони"},ang={["class:Warrior"]="Принести величезну відрубану голову володаря драконів самому Вождеві — одна з найвищих відзнак бойової слави.",["faction:Horde"]="Перемога над Нефаріаном відновлює честь Орди й звільняє край Блекрок із пазурів дракона, який поневолив Темну Орду ренегатів.",["race:Orc"]="Для орків вручення голови Нефаріана Траллові — відплата звірові, який смикав за ниточки Ренда Блекгенда й поневолював орчі клани заради своїх експериментів."},sec={{t="Трофей загибелі",b="Нефаріан, натхненник Лігва Чорнокрила й ватажок виводку чорних драконів у Східних Королівствах, нарешті впав. Його величезна, посічена в боях голова — беззаперечний доказ його загибелі. Для воїнів Орди винести таку грандіозну здобич із палаючих висот Гори Блекрок і доправити через Велике Море до Дуротару — справжній подвиг, що вкриває славою."},{t="Суд Вождя",b="Трофей вручають самому Вождеві Траллу. Тралл знає скверну, що панує в Горі Блекрок, як мало хто: він визволив свій народ із таборів для інтернованих і вивів його з-під демонічної кровожерливості старої Орди. Побачити сина Детвінга поваленим означає переконатися, що роки боротьби були недарма, і покласти край жорстокому пануванню темного дракона над орками клану Блекрок."},{t="Тіні батька",b="Смерть Нефаріана кладе край збоченим експериментам чорного драконячого роду над живою плоттю, проте не усуває всіх небезпек. Глянувши на обезголовленого дракона, Тралл зауважує, що сам Детвінг, певно, заворушився, почувши про загибель сина. Перемога справжня, та вона суворо нагадує про більші жахи, що дрімають під поверхнею світу."}},faq={{q="Хто такий Нефаріан?",a="Нефаріан — великий чорний дракон, син Детвінга. Зі свого гнізда високо в Лігві Чорнокрила на вершині Гори Блекрок він проводив покручені досліди, щоб створити хроматичний драконячий рід, і маніпулював смертними расами — особливо Темною Ордою, — змушуючи їх виконувати свою волю.",al={"історія нефаріана","хто такий нефаріан","володар чорних драконів"}},{q="Чому трофей несуть Траллові?",a="Тралл — Вождь Орди. Він вивів орків із таборів для інтернованих і звільнив від демонічної кровожерності Старої Орди, тож доказ загибелі дракона, що поневолив орків Блекрок і Темну Орду, має опинитися саме в його руках.",al={"чому тралл","хто отримує голову"}},{q="Що відбувається в Оргріммарі, коли здають голову?",a="Коли Голову Нефаріана приносять і вивішують в Оргріммарі, усе місто святкує. Уся столиця отримує Бойовий клич драконоборця, що посилює бойову міць усіх членів Орди поблизу.",al={"бонус голови","світовий бонус оргріммара","бонус бойового клича"}},{q="Чи є в цього завдання відповідник для Альянсу?",a="Так, герої Альянсу виконують схоже завдання з тією самою назвою — «Володар Блекрока»: вони приносять Голову Нефаріана Верховному Лордові Болвару Фордрагону у Фортецю Стормвінда, щоб їхнє місто отримало те саме благословення.",al={"версія для альянсу","відповідник альянсу"}},{q="Чому Детвінг становить загрозу?",a="Детвінг — батько Нефаріана й праотець чорного драконячого роду. Перемога над його сином не усуває небезпеки, яку становить сам драконячий батько.",al={"лихий прокидається","хто лихий"}},{q="Звідки береться голова?",a="Завдання починається, коли ви знімаєте Голову Нефаріана з його трупа, здолавши дракона на вершині Лігва Чорнокрила.",al={"як отримати голову нефаріана","предмет початку завдання"}}},fp="21,364,16.380.0,23.395.0,21.372.1,16.273.0,38.243.0,53.225.0,44.200.0,27.147.0,30.135.0"}
P.entries["quest:7784"] = {n="Володар Блекрока",s="Це завдання — остання доставка відрубаної голови Нефаріана провідникам Оргріммара. Довівши Траллові, що чорний дракон загинув, чемпіони вирушають до Верховного Володаря Саурфанга в Долині Сили, щоб виставити трофей перед усією Ордою.",h="Це завдання — остання доставка відрубаної голови Нефаріана провідникам Оргріммара.",kw={"нефаріан","володар блекрока","верховний володар саурфанг","долина сили","тралл","бойовий клич драконоборця","оргріммар"},ang={["faction:Horde"]="Привселюдний показ голови Нефаріана зміцнює новий лад Тралла й доводить міць оновленої Орди перед чорним драконом, який маніпулював орками Гори Блекрок.",["race:Orc"]="Для орків загибель дракона, що тримав клан Блекрок у неволі, приносить глибоке очищення, змиваючи безчесну тінь, що впала на їхній народ."},sec={{t="Трофей для Орди",b="Коли чорного дракона Нефаріана вбито на вершині Лігва Чорнокрила, його голову приносять до Оргріммара як доказ поразки. Вождь Тралл підтверджує загибель сина Детвінга й відсилає переможця до Верховного Володаря Саурфанга в Долину Сили. Там моторошні рештки готують до привселюдного показу — як застереження ворогам і бойовий заклик для справжньої Орди."},{t="Здобута спадщина",b="Нефаріан панував на висотах Гори Блекрок, схиляючи до своєї волі орків Блекрок і Темну Орду. Перемігши його й піднявши його голову високо над Долиною Сили, Орда Вождя Тралла завдає могутнього удару чорному драконячому роду, а Саурфанг закликає весь Оргріммар радіти «Бойовому кличу драконоборця»."}},faq={{q="Навіщо це завдання?",a="Це завершальна здача за вбивство Нефаріана. Показавши доказ Траллові, ви доповідаєте Верховному Володареві Саурфангу в Долині Сили в Оргріммарі, щоб отримати почесті й вивісити відтяту голову на загальний огляд.",al={"що робить це завдання","здати володаря блекрока","чому йти до саурфанга"}},{q="Хто такий Верховний Володар Саурфанг?",a="Верховний Володар Саурфанг — досвідчений орк-воїн і один із найбільших поборників Орди. Він стоїть у Долині Сили в Оргріммарі, де приймає голову й велить вивісити її, щоб усі бачили.",al={"хто такий саурфанг","роль верховного володаря саурфанга"}},{q="Навіщо вивішують голову Нефаріана?",a="Вивішена голова чорного дракона без жодних сумнівів доводить, що господар Гори Блекрок упав. Це підносить дух захисників Оргріммара, а Бойовий клич драконоборця отримує кожен у місті.",al={"навіщо виставляти голову нефаріана","голова нефаріана оргріммар"}},{q="Ким був Нефаріан?",a="Нефаріан — великий чорний дракон, син Детвінга. З Лігва Чорнокрила на вершині Гори Блекрок він командував орками Блекрок і Темною Ордою й виводив хроматичний драконячий рід.",al={"ким був нефаріан","переказ про нефаріана"}},{q="Де знайти Верховного Володаря Саурфанга?",a="Саурфанг стоїть на варті в Долині Сили — центральному вхідному кварталі Оргріммара.",al={"де саурфанг","місце саурфанга"}},{q="Яку роль тут відіграє Тралл?",a="Голову спершу отримує Вождь Тралл. Переконавшись, що Нефаріан мертвий, він посилає вас до Саурфанга, щоб офіційно вивісити трофей.",al={"чому тралл","участь тралла"}}},fp="21,264,22.393.0,19.348.1,34.226.0,30.206.0,38.233.0,17.190.0,40.95.0,35.139.0"}
P.entries["quest:78"] = {n="Легенда про Сталвана",s="Це доручення — поворотний момент у з'ясуванні історії Сталвана Містмантла: воно посилає слідчих із Лісу Елвінн назад до похмурого Даркшира. Керуючись спогадами Маршала Гаґґарда про часи служби, ви несете знайдену сторінку щоденника Шинкареві Смітсу до Таверни «Багряний Крук», щоб упізнати моторошний почерк.",h="Це доручення — поворотний момент у з'ясуванні історії Сталвана Містмантла: воно посилає слідчих із Лісу...",kw={"легенда про сталвана","маршал гаґґард","шинкар смітс","багряний крук","почерк","даркшир"},ang={["faction:Alliance"]="Це завдання показує міцні зв'язки між колишніми захисниками королівства: відставні вартові Стормвінда пов'язані з хранителями громад по всьому Королівству Стормвінд.",["race:Human"]="Цей крок відкриває похмурі спогади, що таяться в людських поселеннях, і показує, що давні трагедії Великого Селища й Даркшира не хочуть лишатися похованими."},sec={{t="Підказка від маршала",b="Ви знаходите в скрині Маршала Гаґґарда в Лісі Елвінн вивітрену, подерту сторінку щоденника, але відставний командир через слабкий зір не може прочитати вицвіле письмо. Розуміючи, що слід веде назад за річку, Гаґґард згадує, як командував Вартою Стормвінда, і пригадує вечори в Таверні «Багряний Крук» у Даркширі. Він посилає вас до Шинкаря Смітса, що за довгі роки за шинквасом став неофіційним хранителем місцевої історії й чуток."},{t="Назад до «Багряного Крука»",b="Знову пройшовши похмурим лісом Сутінколісся, ви показуєте Смітсові за шинквасом вицвілий рукопис. Почувши ім'я свого давнього знайомого Гаґґарда, Смітс одразу м'якне, хоч і бідкається, що здоров'я ветерана згасає. Та щойно він кидає погляд на пергамент, його безтурботність миттю змінюється тривогою: він без жодного сумніву впізнає характерний почерк — і розслідування наближається до жахливої правди про божевілля Сталвана."}},faq={{q="Чому Маршал Гаґґард посилає мене назад до Даркшира?",a="Маршал Гаґґард старий і майже сліпий, тож не може сам роздивитися знайдену сторінку щоденника. Він пригадує, що Шинкар Смітс із Таверни «Багряний Крук» добре знався на місцевих переказах та історії, коли Гаґґард служив у Варті Стормвінда, тож Смітс — найкращий, хто може впізнати почерк.",al={"чому йти до даркширу","гаґґард до даркширу","чому смітс"}},{q="Де знайти Шинкаря Смітса?",a="Шинкар Смітс стоїть за шинквасом у Таверні «Багряний Крук» на східному боці Даркшира в Сутінколіссі.",al={"де смітс","місце смітса","місце таверни червоного крука"}},{q="Що треба віднести Шинкареві Смітсу?",a="Ви несете Вицвілу Сторінку Щоденника — уривок із загубленого щоденника Сталвана Містмантла, який раніше знайшли в скрині Маршала Гаґґарда.",al={"який предмет","вицвіла сторінка щоденника","сторінка щоденника сталвана"}},{q="Чи впізнає Шинкар Смітс почерк?",a="Haggard sends the page to Smitts because of the barkeep's knowledge of local history. Smitts must inspect the handwriting before he can offer another lead.",al={"чи смітс впізнає почерк","реакція смітса на щоденник"}},{q="Звідки Смітс знає Маршала Гаґґарда?",a="Багато років тому Гаґґард водив патрулі Варти Стормвінда в Сутінколісся й частенько заходив випити до Таверни «Багряний Крук», де Смітс його й пригощав.",al={"стосунки смітса і гаґґарда","звідки смітс знає гаґґарда"}},{q="Що далі в пошуках Сталвана?",a="Bring the faded journal page to Smitts at the Scarlet Raven Tavern and follow the lead he provides.",al={"що далі","наступний крок сталвана","ланцюжок сталвана далі"}}},fp="21,343,23.491.0,27.485.1,51.311.0,35.119.0,44.152.0,49.155.0,37.145.0,42.99.0"}
P.entries["quest:780"] = {n="Бойові вепри",s="«Бойові вепри» — мисливське завдання-посвята, яке дає Ґрулл Гоквінд у Таборі Нарачі. Молодим тауренам доручають винищити лютих, вишколених для війни вепрів Яру Тернистого Клинка, щоб захистити племінні землі й нагодувати молодь поселення.",h="«Бойові вепри» — мисливське завдання-посвята, яке дає Ґрулл Гоквінд у Таборі Нарачі.",kw={"бойові вепри","ґрулл гоквінд","табір нарачі","яр тернистого клинка","шипогриви","щетиноспини","юшка"},ang={["class:Hunter"]="Зіткнення зі звірами, яких Щетиноспини вишколили для злоби, вчить молодих мисливців гострої різниці між природною звіриною й тваринами, перекрученими на зброю війни.",["profession:Cooking"]="Прохання про боки й рила показує основу тауренської кухні: грубе, жорстке м'ясо завжди можна уварити в ситну, поживну юшку.",["race:Tauren"]="Це завдання втілює тауренську рівновагу: боронити землі Земної Матері й не марнувати нічого здобутого в бою, обертаючи бойових звірів ворога на харч для телят табору."},sec={{t="Загроза на кордоні",b="На схід від Плато Червоної Хмари лежить Яр Тернистого Клинка — зарослий колючками рубець, який тримають шипогриви-Щетиноспини. Поки напруга між шу'хало й шипогривами переростає у відкриту війну, Щетиноспини вишколили лютих бойових вепрів, щоб промацувати тауренські рубежі й тероризувати їхні споконвічні мисливські угіддя. Якщо їх не спинити, ці напасливі звірі загрожують не лише стежкам дичини, а й безпеці самого Табору Нарачі."},{t="Нагодувати плем'я",b="Для тауренів полювання — і оборонна потреба, і прожиток громади. Ґрулл Гоквінд велить посвяченим принести рила й боки вбитих бойових вепрів. Навіть звірів, вишколених руками шипогривів, не марнують: їхнє м'ясо й хрящі йдуть на ситну юшку для молоді племені, і зброя шипогривів обертається на поживу для наступного покоління захисників-тауренів."}},faq={{q="Чому бойові вепри нападають на плато?",a="Бойових вепрів навмисне виводять і навчають шипогриви Щетиноспини з Яру Тернистого Клинка. Шипогриви використовують їх як ударних звірів, щоб дошкуляти тауренам і вдиратися на мисливські угіддя племен на Плато Червоної Хмари.",al={"агресія бойових вепрів","чому бойові вепри ворожі","бойові вепри нападають"}},{q="Хто посилає гравців на це полювання?",a="Ґрулл Гоквінд, визначний мисливець і старійшина Табору Нарачі, веде молодих тауренів крізь завершальні випробування їхнього першого навчання.",al={"хто дає бойових вепрів","видавець бойових вепрів","роль ґралла гоквінда"}},{q="Де водяться бойові вепри?",a="Вони блукають біля Яру Тернистого Клинка й у ньому самому — у порізаному каньйоні трохи на схід від Табору Нарачі, на східному краю Плато Червоної Хмари.",al={"місця бойових вепрів","де бойові вепри","вепри яру тернистого клинка"}},{q="Що буде з м'ясом, зібраним із вепрів?",a="Боки й рила бойових вепрів приносять до Табору Нарачі, щоб зварити юшку для дітей і старих поселення, — за традицією тауренів пускати в діло все, що вполювали.",al={"для чого боки вепрів","навіщо м'ясо вепра","рагу з вепра"}},{q="Як це завдання пов'язане з місцевим протистоянням із шипогривами?",a="Це раннє знайомство з відкритою ворожнечею між тауренами й племенем Щетиноспинів. Винищення їхніх бойових звірів — пряме попередження шипогривам, перш ніж почнуться відкриті сутички із самими Щетиноспинами.",al={"війна тауренів з вепролюдами","конфлікт щетиноспинів","переказ про вепролюдів"}},{q="Яке завдання передує «Бойовим вепрам»?",a="Перед ним іде завдання «Полювання триває» — попереднє доручення Ґрулла Гоквінда, у якому ви знайомитеся з мисливськими угіддями Плато Червоної Хмари.",al={"попередник бойових вепрів","попереднє завдання бойових вепрів","ланцюжок полювання далі"}}},fp="15,237,22.418.0,17.402.0,43.234.0,31.147.0,32.137.0,50.191.0,57.232.0,36.132.0"}
P.entries["quest:781"] = {n="Напад на Табір Нараче",s="«Напад на Табір Нараче» — важливе відкриття, зроблене в лігві шипогривів у Яру Тернистого Клинка. Забруднена мапа відкриває, що напасливе плем'я Щетиноспинів діяльно замишляє злагоджену облогу Табору Нарачі. Доставка цих планів Вождеві Гоквінду вчасно попереджає Табір Нарачі, щоб той прикликав допомогу із Села Бладгуф.",h="«Напад на Табір Нараче» — важливе відкриття, зроблене в лігві шипогривів у Яру Тернистого Клинка.",kw={"напад","табір нарачі","мапа","шипогриви","щетиноспини","вождь гоквінд","облога","яр тернистого клинка"},ang={["faction:Horde"]="Збереження опори тауренів у Малгорі гарантує Орді її життєво важливий південний якір у центральному Калімдорі.",["race:Tauren"]="Для молодих тауренських сміливців, що проходять перші обряди на плато, перехоплення цієї мапи доводить вашу вірність племені й захищає родичів від раптової різанини."},sec={{t="Змова в терновищі",b="Розвідуючи глибини печер Яру Тернистого Клинка, молоді тауренські шукачі пригод знаходять на кам'яній долівці грубу, забруднену мапу. Придивившись, вони бачать на пергаменті свідомі тактичні позначки шипогривів-Щетиноспинів. Замість принагідних сутичок шипогриви готують повномасштабну тривалу облогу Табору Нарачі."},{t="Застерегти вождя",b="Принесені до Табору Нарачі плани нападу дають Вождеві Гоквінду вкрай важливі відомості. Усвідомлюючи грізну загрозу для майже беззахисного табору та його молодих посвячених, Гоквінд готується послати до Села Бладгуф по підкріплення. Перехоплена мапа обертає те, що могло стати згубною засідкою, на підготовлену оборону."}},faq={{q="Де знайти плани нападу Щетиноспинів?",a="Плани — це заплямована брудом карта в печері в Яру Тернистого Клинка, трохи вище стежкою праворуч від хижі Вождя Шарптаска.",al={"де карта","де заплямлена карта","знайти плани"}},{q="Кому віддати плани нападу Щетиноспинів?",a="Плани треба віднести просто Вождеві Гоквінду в центрі Табору Нарачі.",al={"кому здати","хто отримує карту","кінець завдання"}},{q="Чому шипогриви Щетиноспини цілять у Табір Нарачі?",a="Плем'я Щетиноспинів хоче прогнати тауренів із Плато Червоної Хмари й повернути собі мисливські угіддя та священні рівнини Малгора.",al={"чому нападають на табір нараше","мотиви вепролюдів у мулґорі","облога щетиноспинів"}},{q="Як Вождь Гоквінд збирається відбити облогу?",a="Завдяки перехопленій карті Вождь Гоквінд дізнається про напад завчасно й збирається покликати родичів із Села Бладгуф, щоб посилити плато й відбити наступ.",al={"план гоквінда","підкріплення табору нараше"}},{q="Чи треба з кимось говорити, перш ніж підібрати карту?",a="Ні. Завдання починається просто із Заплямованої Брудом Карти, що лежить на долівці печери в Яру Тернистого Клинка: коли ви її підберете, вона стане планами битви.",al={"хто починає завдання","початок із заплямованої карти","як почати напад на табір нараше"}},{q="Що буде, якщо Табір Нарачі впаде?",a="Табір Нарачі — головний притулок для молодих воїнів-тауренів і їхніх обрядів посвяти; його втрата підірвала б безпеку Плато Червоної Хмари й відрізала б Малгор від місця духовного навчання.",al={"що ставиться на карту табору","чому захищати нараше"}}},fp="22,330,22.393.0,21.361.0,45.143.0,42.85.0,56.152.0,50.168.0,69.149.0,35.185.0"}
P.entries["quest:783"] = {n="Загроза зсередини",s="«Загроза зсередини» — початок служби для захисників, що відгукнулися на поклик Стормвінда в Долині Нортширу. Направлені в Абатство Нортшира до Маршала Макбрайда, свіжі добровольці дізнаються: військо королівства розпорошене за кордоном, і місцеві гарнізони не впораються з домашніми клопотами без допомоги цивільних.",h="«Загроза зсередини» — початок служби для захисників, що відгукнулися на поклик Стормвінда в Долині Нортширу.",kw={"загроза зсередини","маршал макбрайд","нортшир","новобранці","абатство","стормвінд"},ang={["faction:Alliance"]="Завдання підкреслює напругу, з якою стикається Великий Альянс: військові зобов'язання на далеких територіях лишають навіть найбезпечніші серцевинні землі вразливими до розпаду зсередини.",["race:Human"]="Нортшир — початкова долина для захисників із людей, тож відгукнутися на поклик Маршала Макбрайда означає скласти свою першу офіційну обітницю захищати батьківщину й Королівство Стормвінд."},sec={{t="Королівство, розтягнуте до краю",b="Долина Нортширу колись була тихим притулком, присвяченим молитві, землеробству й чернечій науці. Сьогодні вона — перша лінія оборони від внутрішніх заворушень у Лісі Елвінн. Регулярні сили Стормвінда розкидані далекими фронтами, і серце столичних земель небезпечно оголене. Офіційних солдатів на місці обмаль, тож вартові Стормвінда мусять набирати кожного охочого добровольця, що з'являється біля брами абатства."},{t="Поклик маршала",b="В Абатстві Нортшира Маршал Макбрайд керує обороною долини під дедалі більшим тиском з усіх боків. Поки чужоземні небезпеки загрожують Альянсу здалеку, бандити, шкідники й підземні паразити користаються з безвладдя просто на порозі королівства. Відгукнутися на цей поклик означає одразу стати до військової служби: спершу очистити найближчі околиці абатства, а потім узятися за глибшу гниль, що пускає коріння по всьому Елвінну."}},faq={{q="Навіщо це завдання?",a="Це вступний виклик для щойно прибулих новобранців у Долині Нортширу. Вам велять зайти до Абатства Нортшира й доповісти Маршалові Макбрайду, щоб долучитися до місцевої оборони.",al={"навіщо це завдання","загроза зсередини","вступне завдання нортширу"}},{q="Хто такий Маршал Макбрайд?",a="Маршал Макбрайд — старший офіцер Варти Стормвінда в Абатстві Нортшира. Він керує обороною долини, організовує новобранців і роздає доручення, щоб приборкати загрози, що постають поблизу.",al={"маршал макбрайд","хто такий макбрайд","командир абатства"}},{q="Чому Стормвінд набирає добровольців, а не посилає регулярних солдатів?",a="Регулярні війська Стормвінда відрядили в далекі походи боронити інтереси Альянсу. Через такі великі зобов'язання за морем гарнізонам у серці королівства гостро бракує людей, і місцевим командирам доводиться покладатися на щойно прибулих шукачів пригод і добровольців, щоб боронити власні домівки.",al={"чому добровольці","де вартові","чому стормвінду бракує людей"}},{q="Які загрози нависли зараз над Долиною Нортширу?",a="Долина потерпає водночас від кількох бід: агресивні кобольди заполонили сусідні копальні й пагорби, хворі чи хижі шкідники дошкуляють навколишнім виноградникам, а організовані банди розбійників і злочинців користаються з того, що місцевий гарнізон поріділий.",al={"загрози долини","що нападає на нортшир","проблеми нортширу"}},{q="Куди веде це доручення далі?",a="Доповідь Маршалові Макбрайду відкриває кілька негайних доручень у Нортширі: новобранцям треба відбити вторгнення кобольдів у пагорбах, допомогти місцевим фермерам і робітникам і розвідати, звідки взялися організовані бандити.",al={"наступне завдання","що після загрози зсередини","продовження макбрайда"}},{q="Чому Абатство Нортшира стало військовим штабом?",a="Хоча Абатство Нортшира — святе місце навчання й віри, його укріплені кам'яні стіни й розташування посередині роблять його єдиною придатною базою в долині. Коли місцева влада опинилася під тиском, Варта Стормвінда влаштувала командування просто в його залах.",al={"чому військо в абатстві","військова церква нортширу","святі солдати абатства"}}},fp="15,323,24.457.0,18.466.0,34.210.0,23.230.0,75.292.0,54.256.0,37.227.0,62.272.0"}
P.entries["quest:784"] = {n="Знищити зрадників",s="Знищити зрадників — військовий удар Орди, який наказує Ґар'Ток із Гострого Пагорба, щоб відбити Фортецю Тіраґард у людських загарбників. Сили Кул Тірасу під проводом лейтенанта Бенедикта знову зайняли твердиню, відверто порушивши крихкий мир між Дуротаром і Терамором. Знищення їхнього гарнізону вкрай важливе, щоб убезпечити східне узбережжя орківської батьківщини.",h="Знищити зрадників — військовий удар Орди, який наказує Ґар'Ток із Гострого Пагорба, щоб відбити Фортецю...",kw={"ґар'ток","фортеця тіраґард","бенедикт","кул тірас","гострий пагорб","праудмур"},ang={["faction:Horde"]="Окупація Фортеці Тіраґард Кул Тірасом — це тривалий акт війни просто на порозі Дуротару. Знищення сил Бенедикта доводить, що Орда здатна захистити щойно заселений дім від чужоземних флотів.",["race:Orc"]="Орки шанують перемир'я, укладене з Джайною на горі Гіджал, та Кул Тірас повертає гіркі спогади про Другу війну. Відбиття морських піхотинців Бенедикта — справа виживання й гордості предків.",["race:Troll"]="Фортеця Тіраґард лежить тривожно близько до поселення Темного Списа — Села Сен'джин. Вибивши звідти ворожих моряків, ви напряму захищаєте вразливий новий дім тролів."},sec={{t="Розірване перемир'я",b="Коли Тралл повів Орду через Велике Море до Калімдору, він уклав непевний союз із леді Джайною Праудмур, щоб здолати Палаючий Легіон на горі Гіджал. Той мир розбився, коли відчужений батько Джайни, великий адмірал Дейлін Праудмур, прибув із грізним флотом Кул Тірасу. Звинувачуючи всіх орків у звірствах Старої Орди, адмірал вторгся в Дуротар і захопив прибережні опорні пункти, зокрема Фортецю Тіраґард. Хоч Дейлін зрештою загинув у Тераморі, рештки його флоту відмовляються шанувати будь-яку угоду чи зректися своєї ненависті."},{t="Відродження Бенедикта",b="Після загибелі великого адмірала Фортеця Тіраґард ненадовго впала, та резерви Кул Тірасу під проводом лейтенанта Бенедикта відтоді знову захопили твердиню. З цього укріпленого редуту між Гострим Пагорбом і Селом Сен'джин моряки й морські піхотинці нападають на подорожніх і загрожують східним морським підступам. Ґар'Ток бачить у їхніх окопаних позиціях безпосередню небезпеку для Дуротару й закликає воїнів Орди вдарити просто по командуванню Бенедикта."}},faq={{q="Чому люди з Кул Тірасу нападають на Дуротар?",a="Це рештки експедиційного флоту, яким командував Великий Адмірал Дейлін Праудмур. Адмірал не визнавав мирного співіснування людей і орків і прагнув цілком знищити Дуротар. Навіть після його смерті віддані йому вояки тримають прибережні укріплення на кшталт Фортеці Тіраґард наперекір Орді.",al={"чому люди кул тірасу в дуротарі","напад кул тірасу","переказ про людей тіраґарда"}},{q="Хто такий Лейтенант Бенедикт?",a="Лейтенант Бенедикт — командир резервів Кул Тірасу, що зараз утримують Фортецю Тіраґард. Після поразки Великого Адмірала Праудмура Бенедикт згуртував уцілілих морських піхотинців і моряків, відбив прибережне укріплення й веде проти орків безупинні дії.",al={"хто такий бенедикт","лейтенант бенедикт","ватажок тіраґарда"}},{q="Чи підтримує цих людей Джайна Праудмур?",a="Ні. Джайна уклала з Вождем Траллом угоду про спільне виживання й, щоб зберегти мир, виступила проти загарбницького походу свого батька. Вояки у Фортеці Тіраґард — рештки Кул Тірасу, що відкололися: вони відкидають дипломатію Терамора й вважають перемир'я Джайни зрадою.",al={"чи джайна підтримує їх","терамор і кул тірас","джайна праудмур тіраґард"}},{q="Чому їх називають «зрадниками»?",a="Ґар'Ток вважає їх зрадниками, бо їхнє вторгнення прямо порушило домовленість, якої Тралл і Джайна Праудмур дійшли, щоб здолати Архімонда в Третій війні. Їхня військова присутність на землях Орди зневажає повоєнні кордони, встановлені в Калімдорі.",al={"чому зрадники","хто кого зрадив","значення зрадників"}},{q="Де Фортеця Тіраґард?",a="Фортеця Тіраґард стоїть на східному узбережжі Дуротару, на південь від Гострого Пагорба й трохи на північний схід від Села Сен'джин. Її високі кам'яні мури височіють над прибережними водами, тож загарбники мають стратегічну базу поблизу поселень Орди.",al={"місце тіраґарда","де фортеця тіраґард","де бенедикт"}}},fp="22,366,17.559.0,21.469.0,43.323.0,27.292.0,43.277.0,32.304.0,32.240.0"}
P.entries["quest:786"] = {n="Зупинити агресію Колкарів",s="Зупинити агресію Колкарів — життєво важлива оборонна місія Орди, яку доручає розвідник Лар Праултаск біля Села Сен'джин. Гравцям належить проникнути на Кручу Колкарів і знищити три комплекти узгоджених планів вторгнення, перш ніж клан кентаврів ударить по молодих поселеннях Дуротару.",h="Зупинити агресію Колкарів — життєво важлива оборонна місія Орди, яку доручає розвідник Лар Праултаск біля...",kw={"колкари","кентаври","лар праултаск","круча колкарів","село сен'джин","вторгнення"},ang={["faction:Horde"]="Зрив наступу Колкарів рятує молоду Орду від виснажливої війни на кілька фронтів просто на порозі її нового дому.",["race:Orc"]="Долина Випробувань — місце, де молоді орки проходять обряди дорослішання, тож агресія кентаврів там — це образа самої суті орківської воїнської культури.",["race:Troll"]="Уже втративши свій давній острівний дім, тролі Темного Списа не можуть дозволити, щоб Село Сен'джин затопили кентаври-грабіжники."},sec={{t="Нависла навала",b="Розвідуючи західний Дуротар, троль-слідопит Лар Праултаск під покровом ночі прокрався на Кручу Колкарів. Те, що він побачив, стривожило його: кентаври Колкари не просто чинили безладні набіги на узбережжя, а готували зухвале вторгнення трьома ударами, націлене просто на землі орків і Темного Списа. Воєначальники кентаврів розділили свої бойові задуми між трьома ватажками, маючи намір ударити по Долині Випробувань, Селу Сен'джин і самих воротах Оргріммару."},{t="Удар по каньйонах",b="Щоб відвернути спустошливу війну серед сухих червоних каньйонів Дуротару, новобранців посилають углиб Кручі Колкарів відтяти голову змії. Проникнення в запилений табір і спалення трьох сувоїв з планами нападу ламає ланцюг командування кентаврів. Хоч Лар Праултаск упевнений, що Орда неминуче розчавила б будь-яке повномасштабне вторгнення, знищення цих документів позбавляє захисників Дуротару дорогої ціни крові, поки їхня молода держава ще тільки стає на ноги."}},faq={{q="Хто дає завдання «Зупинити агресію Колкарів»?",a="Завдання дає Лар Праултаск, розвідник-троль Темного Спису, що стоїть одразу за Селом Сен'джин на південних кручах Дуротару.",al={"видавець завдання","хто дає завдання","місце лара пролтаска"}},{q="На що збираються напасти кентаври Колкари?",a="Бойові плани Колкарів описують злагоджений наступ у три удари: на Долину Випробувань, Село Сен'джин і столицю Орди, Оргріммар.",al={"цілі кентаврів","плани нападу","три цілі"}},{q="Де Круча Колкарів?",a="Круча Колкарів — розпечений сонцем лабіринт каньйонів трохи на захід за скелястими хребтами від Села Сен'джин, на півдні Дуротару.",al={"місце кручі колкарів","де круча","село кентаврів дуротар"}},{q="Де в Кручі знайти плани нападу?",a="Три сувої з планами вторгнення тримають троє різних ватажків Колкарів, що стережуть окремі табори по всій Кручі.",al={"місця планів нападу","де сувої","ватажки кентаврів"}},{q="Чому Колкари хочуть вторгнутися в Дуротар?",a="Колкари — агресивний загарбницький клан кентаврів із посушливих земель Калімдору. Прибулих орків і тролів Темного Спису вони вважають чужинцями, що зазіхають на їхню землю й мисливські угіддя.",al={"чому кентаври нападають","мотив кентаврів","переказ про колкарів"}},{q="Що буде, коли плани знищено?",a="Знищені документи зривають злагоджену облогу: наступ Колкарів розладнується, а вразливі поселення Дуротару вберігаються від раптового розгрому.",al={"наслідки завдання","чи припиниться напад кентаврів"}}},fp="27,294,18.498.0,20.475.0,49.137.0,55.154.0,29.121.0,49.157.0,41.207.0,43.179.0"}
P.entries["quest:787"] = {n="Нова Орда",s="Нова Орда — вступне завдання в Долині Випробувань, яке дає воїн-ветеран Ейтріґґ. Воно скеровує новобранців до Ґорнека в Лігві, щоб розпочати навчання. Через цей короткий виклик Ейтріґґ ділиться власною історією та провідним баченням Тралла — Орди, що здобула спокуту.",h="Нова Орда — вступне завдання в Долині Випробувань, яке дає воїн-ветеран Ейтріґґ.",kw={"ейтріґґ","нова орда","тралл","ґорнек","долина випробувань","лігво"},ang={["faction:Horde"]="Це завдання втілює засадничий дух правління Тралла: цілковитий розрив із демонічним рабством на користь честі, виживання й сутності предків.",["race:Orc"]="Для молодих орків, що ступають у Долину Випробувань, Ейтріґґ — жива пам'ять про трагічне минуле їхнього народу та його спокуту під проводом Тралла.",["race:Troll"]="Тролі Темного Списа навчаються пліч-о-пліч з орками в Долині Випробувань, прийнявши бачення Тралла про спільне виживання й честь."},sec={{t="Повернення ветерана",b="Ейтріґґ стоїть у Долині Випробувань за наказом Вождя Тралла, щоб оцінювати й наставляти найновіших претендентів Орди. Покинувши Стару Орду після Другої війни, розчарований її розбещенням Палаючим Легіоном, Ейтріґґ жив у тихому вигнанні, доки його не полонили люди. Врятований Траллом, він вирішив повернутися, дізнавшись про мрію молодого Вождя: шляхетна Орда, вкорінена в шаманізмі предків і цілком відірвана від демонічних господарів."},{t="Прибуття до Лігва",b="Перш ніж будь-який новобранець зможе вийти за межі суворих каньйонів Долини Випробувань, він має довести свою стійкість. Ейтріґґ посилає новачків у затінену печеру, відому як Лігво, поговорити з Ґорнеком. Хоч Ґорнек рідко добирає слова, говорячи про жалюгідний стан новоприбулих, його нагляд дбає про те, щоб у ширші землі Дуротару пускали лише тих, хто опанував дисципліну й виживання."}},faq={{q="Хто такий Ейтріґґ?",a="Ейтріґґ — старий орк-ветеран, що на власні очі бачив, як Стара Орда занепала під впливом Палаючого Легіону. Розчарований, він сам пішов у вигнання до Лордерону. Коли його схопили люди, а згодом визволив Тралл, він присягнув на вірність оновленій Орді Тралла й тепер допомагає наглядати за навчанням новобранців у Долині Випробувань.",al={"хто такий ейтріґґ","історія ейтріґґа","переказ про ейтріґґа"}},{q="Чому Ейтріґґ говорить про «Нову Орду»?",a="Першу Орду обдурила й поневолила демонічна кровожерність під владою Палаючого Легіону. Нову Орду Тралла викували, щоб скинути демонічне ярмо, відродити давні шаманські звичаї й збудувати для орків та їхніх союзників у Калімдорі шляхетне, незалежне майбутнє.",al={"що таке нова орда","різниця старої і нової орди","значення нової орди"}},{q="Де знайти Ґорнека?",a="Ґорнек стоїть одразу за входом до Лігва — помітної печери, видовбаної в північній скельній стіні Долини Випробувань.",al={"де ґорнек","знайти ґорнека","місце ґорнека"}},{q="Що буде після доповіді Ґорнекові?",a="Ґорнек приймає вас як одного з учнів Ейтріґґа й дає перші польові доручення: ви боронитимете долину й доводитимете, що готові служити Орді.",al={"наступне завдання після нової орди","що робить ґорнек","завдання ґорнека"}},{q="Чому Ейтріґґ пішов у вигнання?",a="Ейтріґґ покинув Орду, бо йому стало гидко від демонічної скверни й безглуздої різанини, яку в попередніх війнах влаштовували чорнокнижники на службі Палаючого Легіону.",al={"чому ейтріґґ у вигнанні","чому ейтріґґ пішов","ейтріґґ демонічне осквернення"}},{q="Чому новобранців навчають у Долині Випробувань?",a="Долина Випробувань — відлюдна сувора місцина в Дуротарі, де молоді орки й новоприбулі союзники можуть зійтися з небезпечними звірами й скорпідами під пильним оком досвідчених наставників, перш ніж вирушити в ширший світ.",al={"чому долина випробувань","мета долини випробувань","навчання в долині випробувань"}}},fp="13,299,18.465.0,20.397.0,15.378.0,44.288.0,24.139.0,39.181.0,23.179.0,49.232.0"}
P.entries["quest:79"] = {n="Легенда про Сталвана",s="Це завдання — мить, коли розрізнені чутки про Сталвана Містмантла складаються в незаперечний доказ жорстокого злочину. Шинкар Смітс віддає давно приховані брудні сторінки щоденника й посилає слідчого просто до Командира Нічної Варти Алтеї Ебонлок.",h="Це завдання — мить, коли розрізнені чутки про Сталвана Містмантла складаються в незаперечний доказ жорстокого...",kw={"легенда про сталвана","шинкар смітс","брудні сторінки щоденника","алтея ебонлок","маршал гаґґард","нічна варта"},ang={["class:Paladin"]="Винести на світло давно поховані вбивства — покликання паладина: це вимога відповідальності за безневинні життя, жорстоко обірвані в тінях Сутінколісся.",["class:Rogue"]="Зіставлення зразків почерку з таверн і запорошених скринь — терпляча слідча робота, без якої часто не вистежити невловиму здобич.",["faction:Alliance"]="Розслідування показує, як південним землям доводиться спиратися на мандрівних героїв Альянсу, щоб вершити правосуддя, коли офіційної підтримки Стормвінда немає зовсім."},sec={{t="Прорив у Даркширі",b="Роками похмура доля заїжджої шляхетної родини лишалася нерозкритою трагедією Сутінколісся. Шинкар Смітс і Маршал Гаґґард, тоді один із командирів Варти Стормвінда, першими оглянули місце різанини й знайшли кілька подертих, заляпаних багнюкою сторінок щоденника. Без зразків почерку чи підтверджувальних паперів записи лежали без руху й не могли офіційно викрити відлюдника, що, за чутками, жив у глушині. Докази, зібрані в Елвінні, Вестфолі й Сутінколіссі, нарешті пов'язують почерк зі Сталваном Містмантлом — і міські плітки обертаються на очевидну справу про вбивство."},{t="До Варти",b="Даркшир живе в постійній облозі нежиті, диких звірів і ще гірших жахіть, що блукають лісовим мороком. Командир Алтея Ебонлок не має терпіння до байок чи безпідставних підозр, коли виживання її міста висить на волосині. Доставлені брудні сторінки перекидають місток від прохололої історії до негайного військового правосуддя. Маючи переконливий доказ різанини на землі Сутінколісся, Нічна Варта нарешті мусить визнати Сталвана Містмантла не дивакуватим відлюдником чи героєм страшних оповідок, а небезпечним утікачем, що заслуговує на відплату."}},faq={{q="Який доказ увесь цей час мав Шинкар Смітс?",a="Багато років тому Смітс разом із Гаґґардом розслідував різанину заїжджих шляхтичів. На місці злочину вони знайшли подерті, забрьохані сторінки щоденника, але досі не мали зразків почерку, щоб довести, що їх писав Сталван Містмантл.",al={"сторінки щоденника смітса","заплямовані сторінки","що знайшов смітс"}},{q="Чому Смітс не повідомив про це Командира Ебонлок раніше?",a="Не маючи доказів, що почерк на брудних сторінках належить відлюдному вчителеві, Смітс і Гаґґард мали лише непрямі уривки. Неперевірені чутки Командир Ебонлок відкинула б як марну трату й без того обмеженого часу Нічної Варти.",al={"чому чекав так довго","чому приховував сторінки","чому смітс не сказав вартовим"}},{q="Хто така Командир Алтея Ебонлок?",a="Командир Алтея Ебонлок — очільниця Нічної Варти, знесиленої міської варти, що стереже Даркшир і патрулює дороги Сутінколісся від Погибелі й лісових хижаків.",al={"хто такий ебонлок","роль алтеї ебонлок","командир даркширу"}},{q="Яка різанина сталася в Сутінколіссі?",a="Кілька років тому в Сутінколіссі по-звірячому вбили заїжджу шляхетну родину. Чутки вказували на їхнього колишнього вчителя, Сталвана Містмантла, але місцевим слідчим спершу бракувало незаперечних доказів, щоб його звинуватити.",al={"яка різанина","різанина дворян","кого вбили"}},{q="Яке місце цей крок посідає в усьому розслідуванні?",a="Цей крок — перехід від приватного розслідування до офіційного правосуддя. Обнишпоривши реєстри, шкільні записи й родинні скрині в трьох краях, ви передаєте зібрані докази місцевій владі, щоб та дала дозвіл діяти проти Сталвана.",al={"крок ланцюжка сталвана","як далеко завдання","чи це кінець завдання"}},{q="Чому Нічна Варта так неохоче береться за давні злочини?",a="Даркширу щодня загрожує загибель від блукаючих гидот, зграй воргенів і павуків. Командир Ебонлок мусить кинути кожного вартового на виживання, тож за давні справи вона візьметься, лише коли матиме незаперечні докази.",al={"чому ебонлок зайнята","пріоритет оборони даркширу","пріоритети нічної варти"}}},fp="21,266,27.595.0,22.573.1,51.232.0,61.273.0,34.200.0,37.217.0,56.266.0,62.245.0"}
P.entries["quest:79008"] = {n="... і та записка, яку ви знайшли",s="Ця обпалена записка, знайдена серед жаринок згасаючого багаття у Вестфолі, — єдина загадкова підказка. Її обвуглене послання натякає на місце, що чекає десь у світі, й закликає того, хто її знайде, шукати «землю-близнючку».",h="Ця обпалена записка, знайдена серед жаринок згасаючого багаття у Вестфолі, — єдина загадкова підказка.",kw={"записка","багаття","земля-близнючка","загадка","таємниця","вестфол"},ang={["class:Rogue"]="Розгадувати загадкові підказки, залишені в прихованих таборах, — звична справа для тих, хто живе шепотом, таємницями й прихованими посланнями.",["faction:Alliance"]="Для шукачів пригод, які намагаються повернути лад у Вестфол, невідомий табір і загадковий шифр — ще одна таємниця, що розгортається на прикордонні королівства."},sec={{t="Згасаюче багаття",b="Серед покинутих полів, розграбованих ферм і обвітрених рівнин Вестфолу мандрівники часто натрапляють на табори волоцюг, розбійників чи зневірених бурлак. Та цей невеликий табір покинули поспіхом або потай: припаси кинуто, а жаринки ще ледь жевріють. Серед розкиданого мотлоху лежить обвуглений клаптик пергаменту, що вцілів у вогні."},{t="Загадкове послання",b="На обпаленій записці — лише два коротких речення: «Не все, що горить, утрачено. Знайди землю-близнючку — знайдеш і місце». Оповиті таємницею, ці слова водночас і загадка, і запрошення: вони ведуть геть від спустошених полів Вестфолу до іншого краю, пов'язаного з ним назвою, розташуванням чи долею."}},faq={{q="Що написано в записці?",a="У записці, вкритій пухирями від жару, написано: «Не все, що горить, утрачено. Знайди землю-близнючку — знайдеш і місце». Це єдина зачіпка, що лишилася на покинутому таборищі.",al={"текст записки","що написано на записці","слова обпаленої записки"}},{q="Де знаходять цю записку?",a="Записку знаходять серед решток нещодавнього багаття й розкиданих припасів у дикій місцевості Вестфолу.",al={"де записка","місце записки","місце багаття"}},{q="Хто розпалив це багаття?",a="Автор невідомий. Хто б не розпалив вогонь, він пішов недавно, лишивши розкидані припаси й обвуглене послання серед жарин.",al={"хто залишив записку","чиє багаття","автор записки"}},{q="Що означає «земля-близнючка»?",a="Це загадка, що вказує на інший край світу — схожий на землю, де знайдено записку, чи пов'язаний із нею, — але обвуглена записка більше нічого не пояснює.",al={"що означає земля-близнючка","що таке земля-близнючка","де земля-близнючка"}},{q="Чому записка обгоріла?",a="Записка вкрилася пухирями й обвуглилася в жаринах багаття: схоже, хтось або квапливо намагався її знищити, або недбало кинув, коли вогонь згасав.",al={"чому записка обгоріла","чи хтось хотів спалити записку","обвуглена записка"}},{q="Чи пов'язано це з Братством Дефіас?",a="Хоча Вестфол заполонили Братство Дефіас і злиденні волоцюги, загадковість послання натякає на щось темніше, ніж звичайне листування бандитів.",al={"записка дефіас","чи це дефіас","багаття братства"}}},fp="27,250,12.383.0,19.311.0,23.150.0,25.118.0,22.142.0,35.187.0,24.172.0,44.179.0"}
P.entries["quest:791"] = {n="Внеси свою частку",s="Внеси свою частку — вступне завдання, яке пропонує Фурл Скорнброу з вершини сторожової вежі над Гострим Пагорбом. Надто старий, щоб битися на передовій, укритий шрамами ветеран просить молодих шукачів пригод Орди здобути полотно в тутешніх ворожих людей і кентаврів, щоб пошити спорядження на поміч у їхній дорозі.",h="Внеси свою частку — вступне завдання, яке пропонує Фурл Скорнброу з вершини сторожової вежі над Гострим...",kw={"фурл скорнброу","гострий пагорб","полотно","ветеран","сторожова вежа","торби"},ang={["faction:Horde"]="Кожен молодий воїн у Дуротарі покладається на загартованих ветеранів, як-от Фурл Скорнброу, які нагадують новачкам: шанувати Орду — означає виконувати будь-який обов'язок, якого вимагає батьківщина, чи то вартувати заставу, чи шити полотно.",["profession:Tailoring"]="Фурл показує практичне, суворе кравецтво рубежу: він перетворює покинуте грубе полотно людських загарбників і кентаврів-нападників на міцне спорядження для виживання в дикій природі.",["race:Orc"]="Фурл утілює старше покоління орків, які вирвалися з демонічного розбещення, перетнули море з Траллом і тепер присвячують останні роки вихованню майбутнього своєї молодої держави."},sec={{t="Покликання ветерана",b="Фурл Скорнброу — ветеран Третьої війни, що крокував пліч-о-пліч із Вождем Траллом під час освоєння Дуротару й відчайдушної оборони гори Гіджал. Нині, сповільнений віком і старими ранами, він більше не здіймає сокиру в бою. Натомість він несе невпинну варту на сторожовій вежі Гострого Пагорба, здіймаючи тривогу при вторгненнях і підтримуючи нове покоління захисників."},{t="Здобуте полотно",b="Що міцніше Орда тримає цей край, то рідше лунає сигнальний ріг, тож Фурл заповнює години виготовленням корисного спорядження. Міцне полотно важко дістати в посушливих каньйонах Дуротару, та його вдосталь мають і кул-тіраські зайди на східному узбережжі, і кочові кентаври Колкари, що блукають рівнинами. Клапті, здобуті в цих ворожих сил, дають Фурлові тканину, щоб зшивати практичні торби для розвідників на службі."}},faq={{q="Хто такий Фурл Скорнброу?",a="Фурл Скорнброу — старий орк-ветеран на сторожовій вежі над Гострим Пагорбом. Він бився пліч-о-пліч із Траллом, коли засновували Дуротар, і стояв у спільних лавах, що здолали Архімонда на Горі Гіджал. Битися на передовій він уже не може, тож служить вартовим і на дозвіллі виготовляє польове спорядження для молодих воїнів Орди.",al={"хто такий фурл","переказ про фурла скорнброу","хто дає внеси свою частку"}},{q="Де в Дуротарі знайти клапті полотна?",a="Клапті полотна збирають із людей Кул Тірасу, що засіли у Фортеці Тіраґард на узбережжі Дуротару, і з кентаврів Колкарів, що стоять таборами на рівнинах. І ті, і ті мають цупкі ткані матеріали, які можна забрати з їхніх таборів і пожитків.",al={"де клапті полотна","хто лишає клапті полотна","місця клаптів полотна"}},{q="Де вежа, на якій стоїть Фурл?",a="Вежа Фурла височіє на високих скелястих кручах просто на північний захід від Гострого Пагорба. Звивиста стежка позаду поселення веде на вершину, де стоїть дерев'яна дозорна вежа.",al={"де фурл скорнброу","місце вежі разор гілл","знайти вежу разор гілл"}},{q="Що Фурл шиє з клаптів полотна?",a="Із зібраних клаптів Фурл зшиває міцну торбу. Молодим шукачам пригод, що мандрують Дуротаром, без зайвого місця для провіанту, пайків і здобутої зброї в суворій глушині не вижити.",al={"що шиє фурл","для чого полотно","нагорода за клапті полотна"}},{q="Чому старий воїн шиє торби, а не б'ється?",a="Десятиліття безперервних боїв підточили тіло Фурла, і йому вже не дорівнятися швидкістю й силою до тих, хто воює в полі. Замість жалітися на відставку, він бачить честь у тому, щоб пильнувати Гострий Пагорб і робити спорядження, яке допомагає молодшим бійцям боронити край.",al={"чому фурл шиє","чому фурл у вежі","чому фурл не б'ється"}},{q="У якій війні бився Фурл?",a="Фурл воював під проводом Вождя Тралла в Третій війні: брав участь у заснуванні Дуротару й у вирішальній битві за Гору Гіджал проти Палаючого Легіону. Він гордо згадує, як відгукнувся на бойовий клич під час вимушеного тимчасового перемир'я між Ордою, нічними ельфами й Альянсом, укладеного, щоб здолати Архімонда.",al={"історія битви фурла","що фурл робив раніше","фурл і аркімонд"}}},fp="17,302,19.390.0,16.458.0,22.359.0,44.251.0,46.190.0,44.239.0,56.310.0,27.327.0"}
P.entries["quest:79192"] = {n="Крок за кроком",s="«Крок за кроком» — розслідування, що починається з потертої записки, приколотої серед суворої глушини Пусток. На нашкрябаному пергаменті сказано, що двоє гінців розвозили вантажі для Нової Чуми, а те, що з ними сталося, названо звичайними аптекарськими нещасними випадками. Таємничий автор закликає кожного, хто знайде записку, розшукати відлюдний гірський сховок на кордоні з Пустограєм.",h="«Крок за кроком» — розслідування, що починається з потертої записки, приколотої серед суворої глушини Пусток.",kw={"крок за кроком","нова чума","записка","пустограй","королівське аптекарське товариство","розслідування"},ang={["class:Rogue"]="Вистежувати анонімних інформаторів і перевіряти таємні схованки в глушині між Пустограєм і Пустками — звична справа для тих, хто має справу з кинджалами й розвідданими.",["faction:Horde"]="Мандрівникам Орди в Пустках доведеться вирішити, чи шепіт про смертоносні поставки чуми на землі Калімдору загрожує їхнім землям і союзам.",["race:Undead"]="Для мандрівників-Відступників будь-яка неконтрольована згадка про Королівське Аптекарське Товариство та його дослідження помори — нагальна справа безпеки або небезпечна змова зсередини."},sec={{t="Записка в глушині",b="Абияк приколоте до дерев'яної дошки в таборі серед глушини, це послання впадає в око на тлі суворої природи Пусток. Тут часто тихо змінюють одне одного найманці, головорізи й волоцюги, шукаючи тимчасового притулку подалі від цікавих очей Перехрестя чи Раджета. Подерта записка одразу вирізняється з-поміж буденного гомону глушини — це запрошення, сповнене інтриги й темних натяків."},{t="Шепіт про Нову Чуму",b="Автор записки повідомляє, що обидва посланці розвозили вантажі для Нової Чуми, а те, що з ними сталося, називає звичайними аптекарськими нещасними випадками. Гінці, що перевозять нестійку помору по Калімдору, неабияк ризикують, і автор пропонує затишну місцину в горах між Пустками й Пустограєм як безпечне місце для розмови."}},faq={{q="Про що йдеться в записці із завдання «Крок за кроком»?",a="Записка розповідає, що кур'єри, які везли матеріали, пов'язані з Новою Чумою Відступників, раптово загинули. Автор називає це звичайними нещасними випадками з аптекарями, але пропонує місце зустрічі в горах, щоб безпечно про це поговорити.",al={"записка кроку за кроком","про що записка","текст кроку за кроком"}},{q="Куди записка велить іти?",a="Автор запрошує читача до схованого табору високо в горах між Пустками й Пустограєм, далеко від звичних шляхів патрулів і торгових доріг.",al={"куди йти кроком за кроком","затишне місце в горах","місце кроку за кроком"}},{q="Що за Нова Чума, про яку йдеться в листі?",a="Нова Чума — смертоносне вариво, яке в Андерсіті розробляє Королівське Аптекарське Товариство Відступників. Вона має знищити і Погибель, і живих ворогів, тож її випробування й перевезення між материками оповиті таємницею й смертельною небезпекою.",al={"що таке нова чума","королівські аптекарі чума","доставки аптекарів"}},{q="Хто написав записку, прибиту до дошки?",a="Послання лишили анонімно на грубій дерев'яній дошці в глухому таборі. Автор не називається й лише пропонує затишне місце в горах між Пустками й Пустограєм, де можна безпечно поговорити.",al={"хто написав записку","автор кроку за кроком","хто чекає в горах"}},{q="Що кур'єри Відступників роблять у Калімдорі?",a="Аптекарі Відступників часто збирають екзотичні отрути, спори й реагенти з суворих рослин і звірів Калімдору, відправляючи вантажі через застави Орди й дикими шляхами.",al={"відступники в пустках","чому нова чума в калімдорі","аптекарі в пустках"}},{q="Чому для таких записок обирають глухі табори?",a="Пустки величезні, і поза великими поселеннями влади там майже немає. Нейтральні придорожні стоянки, перепочинки найманців і табори волоцюг дають мандрівникам, контрабандистам і донощикам змогу непомітно лишати звістки, не привертаючи уваги Орди чи місцевих дозорних постів.",al={"переказ про глухі табори","табори найманців пустки"}}},fp="15,374,19.427.0,26.331.1,56.229.0,35.175.0,47.261.0,39.206.0,51.192.0,51.273.0"}
P.entries["quest:792"] = {n="Мерзенні прислужники",s="Мерзенні прислужники — раннє завдання, яке Зуріта Фарґейз дає щойно прибулим героям у Долині Випробувань. Наглядаючи за випробуваннями долини, Зуріта виявила підступний ковен Палаючого Клинка, що ховається в сусідній печері. Щоб спинити їхнє раптове поширення, новобранців посилають винищувати демонічних прислужників, які виповзають на червону землю Дуротару.",h="Мерзенні прислужники — раннє завдання, яке Зуріта Фарґейз дає щойно прибулим героям у Долині Випробувань.",kw={"зуріта фарґейз","палаючий клинок","прислужники","біси","долина випробувань","демони"},ang={["class:Warlock"]="Чорнокнижники-орки й тролі мають зіткнутися з правдою про відступників-тіньовиків, які зловживають демонічними угодами заради руйнування, замість спрямовувати сили скверни на виживання Орди.",["faction:Horde"]="Палаючий Клинок — одна з найгостріших внутрішніх загроз Дуротару: він прагне згноїти молоду Орду зсередини, перш ніж вона міцно утвердить свою незалежність.",["race:Orc"]="Для орків, що прагнуть шанувати Траллову відмову від демонічного рабства, зустріч зі скверною на їхніх священних тренувальних землях — гірке нагадування, що спадок Ради Тіней досі гноїться."},sec={{t="Тінь над долиною",b="Долина Випробувань має бути місцем, де молоді орки й тролі Темного Списа доводять свою силу, дисципліну й вірність Орді Тралла. Її призначення — випробовувати новобранців проти тутешніх хижаків, як-от скорпідів і вепрів, а не проти демонічного розбещення. Та в печері на північному сході агенти, що звуть себе Палаючим Клинком, заснували таємний ковен просто під пильним оком наглядачів долини."},{t="Винищення бісів",b="Зуріта Фарґейз, наставниця, послана допомагати новачкам біля Лігва, помітила ледь відчутну скверну, перш ніж та встигла затопити каньйон. Дрібні демонічні створіння, відомі як мерзенні прислужники, почали виповзати з пащі печери, жбурляючи вогонь і погрожуючи кожному, хто підійде надто близько. Перш ніж Орда зможе викорінити господарів, що ховаються в тінях, молодим новобранцям доручають винищити цих нижчих слуг, щоб долина лишалася безпечною."}},faq={{q="Хто дає завдання «Мерзенні прислужники»?",a="Завдання дає Зуріта Фарґейз. Вона стоїть одразу біля входу до Лігва в центрі Долини Випробувань.",al={"хто дає мерзенних прислужників","видавець мерзенних прислужників","де взяти мерзенних прислужників"}},{q="Хто такі мерзенні прислужники?",a="Мерзенні прислужники — маленькі демонічні істоти, схожі на бісів, яких викликають і підкоряють сектанти Палаючого Клинка. Вони — дрібні посіпаки й вихованці, що вогнем дошкуляють непроханим гостям.",al={"що таке мерзенні прислужники","переказ про мерзенних прислужників","тип істот мерзенні прислужники"}},{q="Де Ковен Палаючого Клинка?",a="Ковен ховається в печері на північному сході Долини Випробувань, за плямистими вепрами й скорпідами-трудівниками, що там блукають.",al={"місце ковену палаючого клинка","де ковен","печера в долині випробувань"}},{q="Що Палаючий Клинок робить у Долині Випробувань?",a="Палаючий Клинок — таємний культ, що прагне підточити нову Орду Тралла й поширити демонічну скверну. Пробравшись у Долину Випробувань, сектанти можуть потай чатувати там і загрожувати наймолодшому поколінню бійців Орди.",al={"чому палаючий клинок тут","мотиви палаючого клинка","чого хоче палаючий клинок"}},{q="Що буде після завдання «Мерзенні прислужники»?",a="Коли прислужників біля печери поменшає, Зуріта Фарґейз скерує вас углиб печери — зійтися з ватажком сектантів і здобути Медальйон Палаючого Клинка.",al={"що після мерзенних прислужників","продовження мерзенних прислужників","завдання медальйона палаючого клинка"}},{q="Чи треба заходити глибоко в печеру, щоб знайти прислужників?",a="Ні. Хоча вони живуть у печері, чимало мерзенних прислужників кишить біля входу й на дні каньйону просто перед печерою.",al={"чи прислужники в печері","де вбивати прислужників","фарм прислужників"}}},fp="14,360,22.441.0,16.434.0,35.126.0,24.175.0,41.139.0,49.232.0,45.174.1,57.140.0"}
P.entries["quest:794"] = {n="Медальйон Палаючого Клинка",s="Доручене чорнокнижницею Зурітою Фарґейз, це завдання посилає молодих новачків Орди вглиб печери Ковену Палаючого Клинка в Долині Випробувань. Там гравцям належить зустрітися з прихованим культистом і здобути артефакт темної магії, відомий як Медальйон Палаючого Клинка. Місія відкриває, що демонічне розбещення пускає коріння просто під носом в Орди.",h="Доручене чорнокнижницею Зурітою Фарґейз, це завдання посилає молодих новачків Орди вглиб печери Ковену...",kw={"медальйон","палаючий клинок","ярроґ бейншедов","зуріта фарґейз","ковен","чорнокнижник"},ang={["class:Shaman"]="Здобуття опоганеної реліквії допомагає Зуріті Фарґейз викрити демонічне розбещення, що оскверняє землю Дуротару.",["class:Warlock"]="Зустріч із Ярроґом — суворе нагадування про небезпеку свавільного поклоніння демонам поза дозволеними, ретельно прихованими угодами, укладеними під владою Тралла.",["faction:Horde"]="Ця місія — останнє випробування молодих новобранців, що знаменує їхню готовність вийти в ширші нетрі Дуротару на захист молодої держави.",["race:Orc"]="Полювання на Ярроґа Бейншедова висвітлює внутрішню боротьбу нової Орди — очистити тренувальні землі від демонічної скверни старих звичаїв."},sec={{t="Прихована загроза в долині",b="Поки молоді орки й тролі проходять основні випробування бою й виживання в Долині Випробувань, у тінях чаїться підступна загроза. Через свої ворожіння чорнокнижниця Зуріта Фарґейз відчуває, що мерзенні прислужники, які кишать на північних кручах, — лише передовий загін темнішої присутності. Глибоко в сусідній печері культ Палаючого Клинка заснував таємний ковен, де практикує темні мистецтва й переховує небезпечні реліквії демонічної сили."},{t="Зустріч із Ярроґом Бейншедовом",b="Сам медальйон тримає в пазурах Ярроґ Бейншедов, орк-чорнокнижник, що діє як агент Палаючого Клинка. Сховавшись на високому виступі глибоко в підземному лігві, Ярроґ командує звірами скверни й темною магією далеко від пильних очей наглядачів долини. Убивство його й захоплення медальйона ламає місцеве керівництво культу, перш ніж їхні ритуали розповзуться далі в серце Дуротару."},{t="Тінь, що не зникає",b="Здобутий талісман підтверджує найгірші побоювання Зуріти Фарґейз. Хоч ковен у Долині Випробувань розгромлено, медальйон — доказ того, що Палаючий Клинок діє організовано й цілеспрямовано. Його досяг простягається далеко за межі земель посвяти, а це означає, що молоду Орду чекають значно ширші демонічні змови по всьому Дуротару."}},faq={{q="Де знайти Ковен Палаючого Клинка?",a="Ковен Палаючого Клинка — у печері, захованій серед круч на північ і захід від Лігва в Долині Випробувань; довкола кишать мерзенні прислужники, схожі на бісів.",al={"місце печери ковену","де печера","печера палаючого клинка долина випробувань"}},{q="Хто носить Медальйон Палаючого Клинка?",a="Медальйон носить Ярроґ Бейншедов, орк-сектант, що відколовся від Орди; він — глибоко в печері, на підвищеному скельному виступі за мілкою водоймою.",al={"хто дає медальйон","яррог банешедоу","хто має медальйон"}},{q="Що таке Палаючий Клинок?",a="Палаючий Клинок — підступний культ орків і чорнокнижників, зіпсованих Скверною й відданих демонічним силам, що зі схованих лігв і таборів плете змови проти нової Орди Тралла.",al={"хто палаючий клинок","культ палаючого клинка","що таке палаючий клинок"}},{q="Чому медальйон такий важливий для Зуріти Фарґейз?",a="Зуріта угледіла медальйон у своїх віщуваннях. Це річ сили, що живить темні обряди культу, і незаперечний доказ того, що демонічні посланці пробираються в Долину Випробувань.",al={"чому зуріта хоче медальйон","що за медальйон","зуріта фарґейз медальйон"}},{q="Чи смерть Ярроґа кладе край культу в Дуротарі?",a="Ні. Загибель Ярроґа очищає печеру в Долині Випробувань, але Зуріта попереджає: цей ковен — лише невеличкий осередок, а задуми Палаючого Клинка в Дуротарі набагато ширші.",al={"чи культ знищений","чи вони зникли","після медальйона палаючого клинка"}},{q="Що буде, коли здати медальйон?",a="Довівши свою вартість убивством Ярроґа й поверненням реліквії, ви готові покинути Долину Випробувань, і вас скеровують доповісти в Селі Сен'джин на південному узбережжі Дуротару.",al={"наступне завдання","що далі","після цього завдання"}}},fp="23,363,29.453.0,29.434.1,20.361.1,40.168.0,44.165.0,26.180.0,54.208.0,53.189.0,44.190.0"}
P.entries["quest:8"] = {n="Угода з пройдисвітом",s="На позір дрібна послуга Келвіну Монтеґ'ю в Похоронному Подзвоні виводить мандрівника на дорогу до Таверни «Шибеничний Кінець» у Бріллі. Доручення полягає в тому, щоб доставити загадкове послання без адреси Корчмарці Рене під виглядом звичайної кур'єрської справи.",h="На позір дрібна послуга Келвіну Монтеґ'ю в Похоронному Подзвоні виводить мандрівника на дорогу до Таверни...",kw={"угода з пройдисвітом","келвін монтеґ'ю","корчмарка рене","лист","таверна","брілл"},ang={["class:Rogue"]="Приватне кур'єрське доручення Келвіна Монтеґ'ю дає зазирнути в неофіційні оборудки, що ведуться довкола Похоронного Подзвону та Брілла.",["faction:Horde"]="Доставка веде просто до Брілла, знайомлячи новоприбулих союзників із регіональним серцем управління і перепочинку Відступників у Тірісфалі.",["race:Undead"]="Для нещодавно піднятих Відступників це доручення — найперша подорож від безпечного цвинтаря Похоронного Подзвону до жвавого осередку Брілла."},sec={{t="Дружня послуга",b="Розлігшись серед похмурих могил і зруйнованих каплиць Похоронного Подзвону, Келвін Монтеґ'ю вдає з себе виснаженого бійця, якому забагато зомбі Погибелі та повзучих павуків. Запевняючи, що йому просто потрібна допомога з доставкою послання до Брілла, він довіряє перехожим шукачам пригод непідписаний лист. Його безтурботна манера й обіцянка щедрої монети роблять доручення схожим на невинну послугу, що просто вказує щойно пробудженим Відступникам дорогу до головного містечка краю."},{t="Таверна «Шибеничний Кінець»",b="Дорога веде на схід крізь спустошені дерева Галявин Тірісфалю, повз Маєток Холодного Вогнища, до поселення Брілл. За шинквасом місцевої таверни Корчмарка Рене спершу зустрічає прибульців із бентежно сонячною привітністю, упадаючи коло вигод своїх гостей. Та щойно вона отримує листа від Монтеґ'ю, її гостинність миттю тріскає. Відкинувши вимушені люб'язності, вона вдає, ніби отримала звістку від любої матінки, а тоді шпетить кур'єра за цікавість і вимагає щось купити або забиратися. Повернення до Келвіна приносить ще один сюрприз: замість мирно віддати обіцяну платню він викликає кур'єра на дуель."}},faq={{q="Хто такий Келвін Монтеґ'ю?",a="Келвін Монтеґ'ю — розбійник у Похоронному Подзвоні, який просить щойно пробуджених мандрівників віднести лист Корчмарці Рене до Брілла. Він подає це як просту послугу й обіцяє добре заплатити.",al={"келвін монтеґ'ю","хто дає угоду з пройдисвітом","видавець завдання"}},{q="Що в Непримітному Листі?",a="Що саме в листі, не записано. Келвін дає кур'єрові лист без жодних позначок, щоб той доставив його Корчмарці Рене в Бріллі.",al={"вміст листа","що в листі","лист келвіна"}},{q="Чому Корчмарка Рене поводиться так дивно?",a="Рене тримає корчму в Бріллі й наполягає, що її листування — приватна справа. Як вона відреагує на доставку, ви дізнаєтеся, принісши їй лист Монтеґ'ю.",al={"чому рене така дивна","ставлення корчмарки рене","рене вдає"}},{q="Чи Келвін Монтеґ'ю справді платить за доставку?",a="Монтеґ'ю обіцяє добре заплатити за доставку. Коли лист доходить до Рене, вона пропонує їжу чи воду; потім поверніться до Келвіна, щоб продовжити справу з обіцяною платою.",al={"чи келвін платить","де мої гроші","нагорода монтеґ'ю"}},{q="Де розташований Брілл?",a="Брілл лежить на північний схід від Похоронного Подзвону. Мандрівники йдуть головною дорогою на схід зі стартової долини, звертають праворуч повз Маєток Холодного Вогнища й переходять критим мостом до поселення.",al={"як дістатися бріллу","дорога до бріллу","напрям до бріллу"}},{q="Що буде, коли віддати лист Рене?",a="Далі йде ще одне завдання з тією самою назвою — «Угода з пройдисвітом». Поверніться до Келвіна Монтеґ'ю в Похоронний Подзвін, щоб продовжити з ним справи.",al={"наступне завдання","продовження угоди з пройдисвітом","що робити після рене"}}},fp="14,250,18.483.0,23.691.1,23.180.0,38.130.0,40.160.0,51.182.0,23.181.0,46.130.1"}
P.entries["quest:80"] = {n="Легенда про Сталвана",s="Цей вирішальний крок розслідування справи Сталвана Містмантла виносить зібрані докази на розгляд влади Даркшира. Маючи на руках закривавлену сторінку щоденника, Командир Алтея Ебонлок посилає слідчого до Писаря Долтрі, щоб раз і назавжди засвідчити почерк.",h="Цей вирішальний крок розслідування справи Сталвана Містмантла виносить зібрані докази на розгляд влади...",kw={"легенда про сталвана","алтея ебонлок","писар долтрі","закривавлена сторінка","почерк","нічна варта"},ang={["faction:Alliance"]="Розслідування показує, як прикордонні міста на кшталт Даркшира намагаються зберегти закон, порядок і міські записи, попри облогу нежиті й темних звірів.",["race:Human"]="Для людей південних королівств це завдання торкається переплетених трагедій, що пов'язують знать Стормвінда, поселенців Сутінколісся й розкидані маєтки Елвінна."},sec={{t="Сіті стягуються",b="Ідучи слідом сторінок щоденника, знайдених по всьому Сутінколіссю й довколишніх людських землях, Нічна Варта нарешті має те, що схоже на нищівний доказ проти невловимого вчителя Сталвана Містмантла. Командир Алтея Ебонлок давно підозрювала цього чоловіка, але офіційний вирок потребує абсолютної певності. Однієї закривавленої сторінки замало, щоб засудити, доки не доведено поза всяким сумнівом, що моторошні каракулі вийшли з-під руки самого Сталвана."},{t="Око писаря",b="Щоб від підозри перейти до певності, Нічна Варта покладається на міського архіваріуса Даркшира — Писаря Долтрі. Роками ведучи міський реєстр, Долтрі переглянув безліч книг обліку й підписів і став знавцем почерків. Звіривши нововиявлену сторінку щоденника з давніми підписами Сталвана в міських записах, він отримує остаточний, незаперечний збіг, що підтверджує темне падіння Сталвана і його провину."}},faq={{q="Навіщо Командирові Ебонлок підтвердження Писаря Долтрі?",a="Командир Алтея Ебонлок хоче переконатися в провині Сталвана поза всяким сумнівом, перш ніж діяти остаточно. Писар Долтрі веде міський реєстр Даркшира й має великий досвід у звірянні підписів, тож саме він може перевірити, чи збігається почерк на закривавленій сторінці з почерком Сталвана в міських записах.",al={"чому долтрі","чому перевіряти почерк","навіщо писар долтрі"}},{q="Яке місце цей крок посідає в історії «Легенда про Сталвана»?",a="Це одинадцятий розділ довгого розслідування. Він іде одразу після того, як знайдено закривавлену сторінку щоденника, і є останньою перевіркою доказів, перш ніж Нічна Варта рішуче виступить проти Сталвана.",al={"яка це частина","як далеко в ланцюжку","порядок ланцюжка сталвана"}},{q="Де в Даркширі знайти Писаря Долтрі?",a="Писар Долтрі — у ратуші Даркшира, де веде місцеві записи й реєстри майна громади.",al={"місце долтрі","де писар долтрі","знайти долтрі"}},{q="Який доказ слідчий приніс до Даркшира?",a="Слідчий несе закривавлену сторінку щоденника, знайдену під час пошуків Сталвана. У ній описано його похмурі думки й пережите, але почерк треба звірити з офіційними записами.",al={"які докази","що за сторінка","переказ про закривавлену сторінку"}},{q="Чи підтверджує Писар Долтрі, що це почерк Сталвана?",a="Daltry must compare the bloodstained page with Stalvan's entries in the town registry. Ebonlocke wants that comparison before she takes final action.",al={"чи збігається почерк","чи це сталван","чи сталван це написав"}},{q="Чому Нічна Варта так обережно звинувачує Сталвана?",a="Навіть у неспокійному, відрізаному від світу Сутінколіссі Нічна Варта прагне берегти законний порядок. Щоб звинуватити колишнього вченого в жахливих злочинах, потрібні певні докази, які можна перевірити, а не чутки чи здогади.",al={"чому потрібні докази","чому не вбити сталвана","підозра ебонлок"}}},fp="21,281,15.511.0,15.474.1,62.349.0,62.242.0,43.125.0,54.237.0,55.149.1,58.219.0"}
P.entries["quest:804"] = {n="Саркот",s="Помстившись за пораненого троля Гана'зуа вбивством жахливого скорпіда Саркота, шукач пригод має віднести звістку про його біду назад до Лігва. Треба попередити Ґорнека, щоб допомога дісталася до ураженого розвідника, перш ніж отруйні рани заберуть його життя.",h="Помстившись за пораненого троля Гана'зуа вбивством жахливого скорпіда Саркота, шукач пригод має віднести...",kw={"саркот","гана'зуа","ґорнек","скорпід","лігво","долина випробувань"},ang={["faction:Horde"]="Нова Орда збудована на спільному виживанні в суворому, безжальному краї; не кидати товариша — засаднича настанова, якої вчать від перших кроків новачка.",["race:Orc"]="Орківська культура цінує особисту силу, та стати на захист честі знесиленого союзника — ось що доводить серце справжнього воїна.",["race:Troll"]="Молодий союз між племенем Темного Списа й орками Тралла міцнішає через такі вчинки братерства, як порятунок Гана'зуа від повільної смерті від отрути."},sec={{t="Біда розвідника",b="Застряглий на високих кручах Долини Випробувань, розвідник Темного Списа Гана'зуа був уражений отрутою й не міг сам спуститися підступними стежками. Хоч помсту Саркотові — страхітливому скорпідові, що звалив його, — вже здійснено, сама гордість не перенесе отруєного воїна через посушливе каміння. Прикутий до своєї скелі, він покладається на новачка, що проходив повз, аби той відніс звістку вниз до тренувального табору."},{t="Честь у Лігві",b="Повернення до Ґорнека в Лігво завершує випробування. Ґорнек одразу усвідомлює, яку загрозу становив Саркот, і швидко організовує допомогу для Гана'зуа. В очах командирів Орди відкласти власне навчання, щоб відстояти честь і врятувати полеглого незнайомця, — це втілення справжньої честі, що доводить гідність новачка задовго до того, як він вирушить у справжній Дуротар."}},faq={{q="Хто такий Гана'зуа і чому він застряг?",a="Гана'зуа — молодий розвідник-троль Темного Спису, що забрів у верхні частини Долини Випробувань, де на нього напав і отруїв жахливий скорпід Саркот. Він надто слабкий, щоб сам спуститися вниз, і потребує порятунку.",al={"ґана'зуа","хто такий ґана'зуа","чому троль поранений"}},{q="Хто такий Ґорнек?",a="Ґорнек — орк-наглядач у Лігві в Долині Випробувань. Він оцінює новобранців, дає їм завдання на виживання й організовує допомогу, коли учні натрапляють у яру на смертельну небезпеку.",al={"ґорнек","де ґорнек","ватажок лігва"}},{q="Що таке Саркот?",a="Саркот — горезвісний переросток-скорпід, що живе на скелястих кручах над Долиною Випробувань. Через отруту й неймовірну лють він — легендарна небезпека серед випробувань молодих орків і тролів.",al={"звір саркот","що за чудовисько саркот"}},{q="Чи виживе Гана'зуа після ран?",a="Так. Почувши вашу доповідь, Ґорнек одразу посилає на кручі рятувальний загін, щоб вилікувати його від отрути й безпечно провести назад до табору.",al={"чи троль виживе","чи ґана'зуа гаразд","ґана'зуа врятований"}},{q="Чому Ґорнек так високо цінує цей вчинок?",a="Пройти випробування — це те, чого від вас і чекають. А відкласти власні завдання, щоб битися за честь незнайомця й урятувати йому життя, — це саме ті цінності, які нова Орда прагне виховати у своїх воїнах.",al={"чому ґорнек цінує","промова ґорнека про честь"}},{q="Де розташоване Лігво?",a="Лігво — головна навчальна печера й збірний пункт у самому серці Долини Випробувань на південному заході Дуротару.",al={"де лігво","місце лігва в дуротарі"}}},fp="7,254,16.425.0,16.363.0,39.228.0,14.201.0,16.197.0,33.141.1,43.198.0,25.125.0"}
P.entries["quest:805"] = {n="Доповідь у село Сен'джин",s="Доповідь у село Сен'джин — мить, коли молоді новачки Орди залишають усамітнену Долину Випробувань, щоб попередити тролів Темного Списа про діяльність демонічного культу. Посланці, яким довірилася Зуріта Фарґейз, несуть звістку про Палаючий Клинок Майстрові Ґадріну — і дізнаються, що тіньова магія вже загрожує сусідньому узбережжю.",h="Доповідь у село Сен'джин — мить, коли молоді новачки Орди залишають усамітнену Долину Випробувань, щоб...",kw={"село сен'джин","майстер ґадрін","зуріта фарґейз","палаючий клинок","темний спис","доповідь"},ang={["faction:Horde"]="Це завдання показує життєво важливу співпрацю між расами-засновницями Орди Тралла: обмін відомостями заради захисту молодих поселень одне одного.",["race:Orc"]="Для молодих орків вихід із Долини Випробувань на поміч Темному Спису — рання перевірка честі й солідарності з союзниками, що стояли поруч із Траллом за Великим Морем.",["race:Troll"]="Повернення до Села Сен'джин ставить шукачів пригод Темного Списа віч-на-віч із вигнанням їхнього народу й триваючою боротьбою за повернення Островів Відлуння."},sec={{t="Прощання з Лігвом",b="Довівши свою бойову стійкість і здобувши темні медальйони Ковену Палаючого Клинка в Долині Випробувань, новачків оголошують готовими до ширшого світу. Зуріта Фарґейз розуміє, що демонічна присутність на священних землях посвяти — не поодинока прикрість, а ознака пошесті, що повзе по всьому Дуротару. Вона посилає молодих шукачів пригод на схід повз гирло ущелини й далі на південь до узбережжя — попередити плем'я Темного Списа."},{t="Тіні над узбережжям",b="Прибувши до прибережного поселення — Села Сен'джин, подорожні передають своє застереження Майстрові Ґадріну, старому знахареві, що веде Темний Спис у вигнанні. Ґадрін підтверджує, що сам Палаючий Клинок не ступав на піски села, та відкриває, що темна магія вже пустила коріння поруч — на Островах Відлуння. Доповідь оголює, яким крихким лишається плацдарм молодої Орди: навіть поки союзники поспішають на захист одне одного, давні племінні зради та скверна б'ють у їхні фланги водночас."}},faq={{q="Чому Зуріта Фарґейз відсилає учнів із Долини Випробувань?",a="Викривши демонічну діяльність у Долині Випробувань, Зуріта Фарґейз боїться, що культ Палаючого Клинка — організована загроза для всього Дуротару. Вона посилає випробуваних учнів за межі долини, щоб попередити союзні поселення й з'ясувати, наскільки далеко сягає вплив культу.",al={"чому йти з долини","чому в сен'джин","накази зуріти фарґейз"}},{q="Хто такий Майстер Ґадрін?",a="Майстер Ґадрін — старий знахар і духовний провідник тролів Темного Спису в Селі Сен'джин. Він радник вождя Вол'джина й опікується справами племені, протистоячи загрозам, що нависли над їхнім тимчасовим прибережним притулком.",al={"переказ про ґадріна","хто такий ґадрін"}},{q="Чи нападав Палаючий Клинок на Село Сен'джин?",a="Ні, на Село Сен'джин Палаючий Клинок прямо не нападав. Але Майстер Ґадрін зауважує, що неподалік, на Островах Відлуння, вкоренилися споріднені темні чари й зрада, тож тролям загрожує власна небезпека.",al={"чи палаючий клинок у сен'джині","культ у сен'джині"}},{q="Де розташоване Село Сен'джин?",a="До Села Сен'джин ідіть на схід через головний вихід із каньйону Долини Випробувань, а на роздоріжжі зверніть на південь — село лежить на південно-східному узбережжі Дуротару.",al={"як дістатися сен'джина","напрям до села сен'джин"}},{q="Про яку загрозу на Островах Відлуння згадує Майстер Ґадрін?",a="Майстра Ґадріна непокоїть темна зрада Залазана — знахаря-троля, що підступними закляттями поневолив своїх родичів і захопив Острови Відлуння, вигнавши вцілілих із Темного Спису на материковий берег.",al={"лихо на островах відлуння","що сталося на островах відлуння"}},{q="Що буде після доповіді Майстрові Ґадріну?",a="Вислухавши вашу доповідь і розповівши про біду тролів, Ґадрін просить вас допомогти проти небезпек, що загрожують узбережжю, а дальші накази відправляють вас на північний захід — до Орґніла Соулскара на Гострому Пагорбі.",al={"наступне завдання після доповіді сен'джин","що робити після ґадріна"}}},fp="25,322,15.449.0,22.510.1,70.285.0,21.259.0,47.227.0,33.168.0,57.234.0,46.216.0"}
P.entries["quest:806"] = {n="Темні бурі",s="Темні бурі — важливе завдання від Орґніла Соулскара з Гострого Пагорба: знищити чорнокнижника-відступника, що оскверняє землю. Гоблін на ім'я Фіззл Дарксторм окопався на Громовому Хребті на службі підступного культу Палаючого Клинка. Його усунення життєво важливе, щоб уберегти Дуротар від демонічного відродження, перш ніж культисти розповзуться далі.",h="Темні бурі — важливе завдання від Орґніла Соулскара з Гострого Пагорба: знищити чорнокнижника-відступника, що...",kw={"фіззл дарксторм","громовий хребет","орґніл соулскар","палаючий клинок","гоблін","чорнокнижник"},ang={["class:Shaman"]="Темні обряди Фіззла та його поплічників порушують природних духів Громового Хребта, роз'ятрюють його звірів і вимагають відновлення рівноваги стихій.",["class:Warlock"]="Фіззл Дарксторм показує безоглядну небезпеку неконтрольованої відданості скверні — він ганьба й загроза, яких дисципліновані практики Орди терпіти не можуть.",["faction:Horde"]="Убезпечивши серце Дуротару від демонічного підриву, молода Орда може спрямувати оборону назовні, замість розвалюватися зсередини.",["race:Orc"]="Палаючий Клинок — це темне минуле, яке орки щодня борються подолати. Знищення культистів-лазутчиків на кшталт Фіззла необхідне, щоб зберегти вільну державу Тралла."},sec={{t="Загроза на хребті",b="Поки молоді захисники Орди патрулюють кордони Дуротару, внутрішнє розбещення гноїться просто в них під носом. Орґніл Соулскар, що веде розслідування з Гострого Пагорба, виявив: Громовий Хребет на північному заході підпав під владу темної магії. Ущелина кишить культистами Палаючого Клинка, що несуть руїну й хаос тутешній звірині та землі."},{t="Фіззл Дарксторм",b="Діяльністю культистів на хребті керує Фіззл Дарксторм — гоблін-чорнокнижник і пристосуванець, що зв'язався з Палаючим Клинком. Замість служити торгівлі чи інтересам картелю, Фіззл спрямовує силу скверни просто на підривні цілі культу. Його смерть і здобутий скручений пазур доводять Орґнілові, що безпосереднє керівництво культу в ущелині зламано."},{t="Викорінення культу",b="Палаючий Клинок утілює все, що нова Орда Тралла прагне лишити позаду: демонічне рабство, безоглядне розбещення й кровожерне безумство. Удар по Фіззлу усуває діяльного змовника з глибини Дуротару, та водночас показує, що тінь над орківською батьківщиною сягає значно глибше за поодинокі табори."}},faq={{q="Хто такий Фіззл Дарксторм?",a="Фіззл Дарксторм — гоблін-чорнокнижник на службі культу Палаючого Клинка. Він і його сектанти сховалися на Громовому Хребті й сіють демонічний хаос у ярі, доки Орґніл Соулскар не наказує його стратити.",al={"хто такий фіззл","переказ про фіззла дарксторма","гоблін фіззл"}},{q="Де Громовий Хребет?",a="Громовий Хребет — порізаний каньйон на північному заході Дуротару, на північ від Гострого Пагорба й трохи на південний захід від Оргріммара. Він горезвісний тим, що там кишать звірі, сповнені сили блискавок, і табори сектантів Палаючого Клинка.",al={"де громовий хребет","місце громового хребта","як знайти громовий хребет"}},{q="Що Палаючий Клинок робить у Дуротарі?",a="Палаючий Клинок прагне підточити Орду Тралла й знову поставити орків під владу демонів. Сектанти потай діють зі схованих ярів, печер і каньйонів по всьому Дуротару, щоб сіяти скверну зсередини.",al={"палаючий клинок у дуротарі","чому сектанти в дуротарі","мотиви палаючого клинка"}},{q="Чому Орґнілу Соулскару потрібен саме кіготь Фіззла?",a="Орґнілу потрібен безсумнівний доказ, що чорнокнижника знищено. Кіготь Фіззла підтверджує, що ватажок кліки сектантів на Громовому Хребті більше не зможе керувати їхніми діями.",al={"чому кіготь фіззла","значення кігтя фіззла","доказ смерті фіззла"}},{q="Що буде після смерті Фіззла?",a="Перемога над Фіззлом усуває безпосередню загрозу на Громовому Хребті, і Орґніл Соулскар посилає вас до шамана Марґоза, який знає більше про скверну Палаючого Клинка, щоб викорінити й інші змови культу.",al={"що після темних бур","продовження темних бур","наступне завдання після темних бур"}},{q="Чому гоблін служить Палаючому Клинку?",a="Багато гоблінів шукають золота через торгові картелі, але декого вабить сира сила, вплив і темні мистецтва, які дає тіньова магія. Фіззл прийняв чаклунство Скверни й віддав свою безжальну хитрість просто сектантам.",al={"гоблін у палаючому клинку","чому фіззл з культом","чорнокнижник фіззл"}}},fp="11,352,21.362.0,16.385.0,20.328.1,24.237.0,31.216.0,36.211.0,57.194.0,35.221.1,46.223.0"}
P.entries["quest:808"] = {n="Череп Міншіни",s="Майстра Ґадріна з Села Сен'джин переслідують відчайдушні крики його покійного брата Міншіни. Убитий і підданий темній магії знахарем-відступником Залазаном на Островах Відлуння, Міншіна й досі ув'язнений душею у власному відтятому черепі. Щоб звільнити полеглого троля, треба проникнути на ритуальні землі Залазана, повернути реліквію й визволити його дух від вічних мук.",h="Майстра Ґадріна з Села Сен'джин переслідують відчайдушні крики його покійного брата Міншіни.",kw={"міншіна","череп","залазан","майстер ґадрін","острови відлуння","вуду","душа"},ang={["class:Priest"]="Жерці розуміють глибоку святість душі, що відійшла, і бачать жах ритуальної некромантії, яка не дає полеглому братові знайти вічний спокій.",["class:Shaman"]="Шамани шанують духів предків; розірвати коло Залазана й звільнити закатовану душу — означає відновити рівновагу між світом духів і світом живих.",["faction:Horde"]="Допомога Майстрові Ґадріну вшановує зв'язок між новою Ордою та племенем Темного Списа й доводить, що горе союзника — спільне для всіх.",["race:Troll"]="Для троля Темного Списа повернути череп Міншіни — священний обов'язок перед родиною та племенем і удар по тому, як Залазан спотворює традиції вуду предків."},sec={{t="Благання з тіней",b="Майстер Ґадрін — одна з духовних опор племені Темного Списа в Селі Сен'джин, та його розум мучать темні видіння. Його брат Міншіна став жертвою зради Залазана, коли божевільний чаклун захопив владу над Островами Відлуння. Міншіна загинув у тій боротьбі, та в тролівській традиції та містиці вуду тілесна смерть не завжди дарує спокій. Змучений голос Міншіни промовляє в снах Ґадріна, благаючи порятунку від долі, гіршої за смерть."},{t="Коло сили Залазана",b="Залазан не просто вбиває колишніх побратимів — він ловить їхні душі, щоб живити своє темне чаклунство. Сутність Міншіни ритуально прив'язали до його власного черепа, який тепер лежить посеред блюзнірського кола сили на найбільшому з Островів Відлуння. Під охороною зурочених тролів, у мерехтінні ритуальних свічок, череп слугує осередком для покрученого моджо зрадника. Доки він лежить у колі, Міншіна лишається вічним бранцем волі Залазана."},{t="Свобода у смерті",b="Щоб урятувати Міншіну, відважний герой має перетнути води на схід від Села Сен'джин до південних околиць Островів Відлуння, прорватися в ритуальне коло й вирвати череп з-під впливу знахаря. Повернення останків Майстрові Ґадріну розриває темні пута: вдячний дух Міншіни на мить постає, шанобливо вклоняється й нарешті відходить у царство предків."}},faq={{q="Ким був Міншіна?",a="Міншіна був братом Майстра Ґадріна, відомого знахаря й старійшини із Села Сен'джин. Під час заколоту на Островах Відлуння його вбив Залазан, а тоді осквернив його останки темним чаклунством.",al={"особа міншіни","хто такий міншіна","брат ґадріна"}},{q="Чому дух Міншіни ув'язнений у його черепі?",a="Залазан темним вуду й магією чорнокнижників поневолює духів загиблих тролів Темного Спису. Прив'язавши душу Міншіни просто до його черепа й поклавши череп у ритуальне коло сили, Залазан закрив йому шлях до потойбіччя й підкорив його дух.",al={"чому череп ув'язнює","пастка душі залазана","душа міншіни"}},{q="Де коло сили?",a="Місце обряду — на пагорбі на найпівденнішому й найбільшому з Островів Відлуння, біля південно-східного узбережжя Дуротару. Його легко впізнати за ритуальними свічками, зачаклованими тролями, що танцюють, і виставленими черепами.",al={"де коло сили","місце черепа","місце черепа міншіни"}},{q="Що буде, коли принести череп до Села Сен'джин?",a="Щойно Майстер Ґадрін отримує череп, некромантські кайдани розпадаються. Примарна постать Міншіни з'являється перед братом і шукачем пригод, вдячно вклоняється й зникає, щоб мирно спочити з предками.",al={"здати завдання","що буде з міншіною","чи з'явиться міншіна"}},{q="Хто такий Залазан і навіщо він це зробив?",a="Залазан колись був шанованим знахарем поряд із Ґадріном і Вол'джином. Збожеволівши від жаги влади, він повстав проти свого племені, закляттями підкорив волю братів і сестер і вигнав решту біженців Темного Спису на материк, у Дуротар.",al={"хто такий залазан","чому залазан злий","переказ про залазана"}},{q="Чому Ґадрін не може сам забрати череп?",a="Майстер Ґадрін — опора, на якій тримається Село Сен'джин. Він наставляє молодий провід Темного Спису, радить вождеві Вол'джину й постійно протидіє закляттям Залазана, що поширюються узбережжям, тож не може лишити поселення без захисту.",al={"чому ґадрін не йде сам","обов'язки ґадріна"}}},fp="16,388,23.481.0,26.459.0,16.402.1,17.226.0,46.270.0,37.212.0,63.214.1,39.252.0,44.254.0"}
P.entries["quest:809"] = {n="Ак'Зелот",s="«Ак'Зелот» — одне з ранніх завдань Орди, яке дає чорнокнижник Ніру Файрблейд із глибин Тіньової Розколини Оргріммара. Маючи докази того, що демонічна скверна досі не зникла, Ніру відсилає шукачів пригод у Пустки на зустріч зі своїм посланцем, що чатує біля кордону.",h="«Ак'Зелот» — одне з ранніх завдань Орди, яке дає чорнокнижник Ніру Файрблейд із глибин Тіньової Розколини...",kw={"ак'зелот","ніру файрблейд","демонічне насіння","палаючий клинок","далека дозорна застава","пік жахливої імли","пустки"},ang={["class:Warlock"]="Чорнокнижники, знайомі з ученням Ніру Файрблейда, можуть розгледіти тонку дволичність свого наставника, коли його помічник ставить під сумнів наказ знищити демонічну реліквію.",["faction:Horde"]="Убезпечити Далеку Дозорну Заставу й очистити Пік Жахливої Імли вкрай важливо для захисту молодих торгових і транспортних шляхів, що пов'язують Дуротар із Пустками.",["race:Orc"]="Орки запекло боролися, щоб вирватися з лап Палаючого Легіону, тож будь-яка ознака культу Палаючого Клинка й демонічних реліквій на їхньому порозі — нагальна загроза."},sec={{t="Тіньовий слід",b="Після того як у Дуротарі знайшли нашийник-відзнаку Палаючого Клинка, Ніру Файрблейд заявляє, що полює на рештки демонів, які загрожують Орді, що щойно осіла на цих землях. Видаючи себе за вартового, який стереже від скверни, Ніру скеровує шукачів пригод на посушливі рівнини Пусток і застерігає, що довкола мерзенного артефакту, відомого як Демонічне Насіння, збирається темний культ."},{t="Посланець на заставі",b="Щоб узгодити удар по культу, шукачі пригод мають розшукати Ак'Зелота — помічника Ніру, що чатує біля Далекої Дозорної Застави на кордоні Дуротару й Пусток. Та коли вони прибувають, Ак'Зелот зустрічає доручення з тихим скепсисом: він уголос дивується, чому це його господар насправді прагне знищити артефакт, — а тоді пояснює, як упоратися з Демонічним Насінням на вершині Піку Жахливої Імли."}},faq={{q="Хто дає це завдання?",a="Завдання дає Ніру Файрблейд, чорнокнижник, що мешкає в похмурій печері Тіньової Розколини під Оргріммаром, — одразу після того, як ви покажете йому нашийник Палаючого Клинка.",al={"видавець завдання","де взяти ак'зелот","завдання ніру файрблейда"}},{q="Де знайти Ак'Зелота?",a="Ак'Зелот — одразу за Далекою Дозорною Заставою, на східному кордоні Пусток, де міст перекинуто з Дуротару.",al={"місце ак'зелота","де ак'зелот","знайти ак'зелота"}},{q="Що таке Демонічне Зерно?",a="Демонічне Зерно — мерзенний артефакт демонічної сили, який культ Палаючого Клинка тримає на вершині Піку Жахливої Імли, зловісної гори на півночі Пусток.",al={"переказ про демонічне зерно","що за зерно"}},{q="Чому накази Ніру здаються Ак'Зелотові дивними?",a="Ак'Зелот нічого не пояснює. Він лише зауважує, що дивно, ніби Ніру хоче знищити Демонічне Зерно, а тоді погоджується розповісти вам, як його позбутися.",al={"чому ак'зелот здивований","дивна реакція ак'зелота"}},{q="Яке завдання йде після цього?",a="Розмова з Ак'Зелотом одразу веде до завдання «Демонічне Зерно», яке доручає вам піднятися на Пік Жахливої Імли й знешкодити згубну реліквію.",al={"наступне завдання після ак'зелота","продовження ак'зелота"}},{q="Чи це завдання — частина історії про Палаючий Клинок?",a="Так. Воно — важливий місток між місцевими змовами сектантів, викритими в Дуротарі, і ширшою, організованою діяльністю культу, що закорінився в Пустках.",al={"ланцюжок палаючого клинка","культ оргріммара завдання"}}},fp="9,278,17.373.0,19.390.1,21.184.0,27.143.0,23.156.0,47.152.1,28.158.0,50.161.0"}
P.entries["quest:812"] = {n="Потреба в ліках",s="Застряглий серед суворих скель північно-західного Дуротару, троль Темного Списа Рінаґ лежить отруєний жалом отруйнохвостого скорпіда. Часу до того, як отрута доб'є його, лишилося обмаль, тож він покладається на гінця, що помчить до Оргріммару й принесе ліки від Кор'ґана.",h="Застряглий серед суворих скель північно-західного Дуротару, троль Темного Списа Рінаґ лежить отруєний жалом...",kw={"рінаґ","кор'ґан","скорпід","отрута","ліки","тіньова розколина","оргріммар"},ang={["faction:Horde"]="Скелястий край Дуротару суворий і безжальний — невпинне випробування вогнем для щойно прибулих захисників молодої держави Тралла.",["race:Troll"]="Страх Рінаґа повернутися до Села Сен'джин підкреслює сувору гордість племені Темного Списа, де необережність в основах виживання в дикій природі накликає нещадні кпини рідних."},sec={{t="Жало скорпіда",b="У посушливих каньйонах Дуротару кишать отруйнохвості скорпіди — агресивні хижаки, чиє жало несе швидкий, знесилювальний нейротоксин. Рінаґ припустився помилки, втративши пильність у бою з цими тварюками біля прикордоння. Знаючи, що отрута в його жилах уб'є його менш ніж за годину, він не здатен сам дійти до міських воріт і мусить віддати своє життя в руки того, хто проходитиме повз його віддалений табір."},{t="Таємниці в тінях",b="Замість довіритися звичайному аптекареві чи шаманові, Рінаґ посилає подорожніх глибоко під Оргріммар, у затінені підземні печери Тіньової Розколини. Там живе Кор'ґан — загадковий знавець суворих отрут пусток Дуротару. Кор'ґан має знання, потрібні, щоб зварити дієву протиотруту, хоч рідко дає допомогу задарма тим, хто ще не довів своєї стійкості."}},faq={{q="Хто такий Рінаґ?",a="Рінаґ — троль-шукач пригод із Темного Спису, що ледве тримається за життя на північно-західних кручах Дуротару. Його вжалив отрутохвостий скорпід, і він боїться і неминучої смерті, і глуму родичів у Селі Сен'джин, якщо повернеться таким принженим.",al={"переказ про рінаґа","хто такий рінаґ","троль рінаґ"}},{q="Що Кор'ґан робить у Тіньовій Розколині?",a="Кор'ґан живе в Тіньовій Розколині — похмурій печері під Оргріммаром, де чорнокнижники, розбійники й інші знавці темних мистецтв займаються своїм ремеслом подалі від очей шанованих воїнів Тралла. Його знання отруйних настоїв і виснажливих випробувань якраз пасують до цього підземелля.",al={"де кор'ґан","хто такий кор'ґан","місце кор'ґана"}},{q="Чому Рінаґ просто не звернеться до шамана чи цілителя в Селі Сен'джин?",a="Рінаґ визнає, що його стримує гордість. Він боїться, що, повернувшись до Села Сен'джин отруєним через власну необачність, не дочекається від інших тролів нічого, крім глуму, тож воліє потай отримати ліки від Кор'ґана.",al={"чому не до сен'джина","чому рінаґ уникає сен'джина"}},{q="Що буде, коли Рінаґ отримає протиотруту?",a="Рінаґ випиває протиотруту й одужує, але на цьому його клопоти не закінчуються. Знаючи Кор'ґана, цілитель вимагатиме, щоб Рінаґ довів себе в нових виснажливих випробуваннях — убивав вепрів і збирав хвости скорпідів, — перш ніж знову заслужить його прихильність.",al={"чи рінаґ виживе","наслідки для рінаґа"}},{q="Де знайти Рінаґа?",a="Він серед порізаних круч північно-західного Дуротару, неподалік прикордонних перевалів, що ведуть на захід, до Пусток.",al={"місце рінаґа","де рінаґ"}},{q="Чому з цими ліками такий поспіх?",a="Отрута отрутохвостого скорпіда надзвичайно сильна: без лікування жертва має менше ніж годину, перш ніж отрута вразить її життєво важливі органи.",al={"чому таймер","таймер отрути рінаґа"}}},fp="15,260,17.452.0,22.425.0,14.270.0,39.310.0,67.251.0,48.282.1,26.127.0,47.148.0"}
P.entries["quest:813"] = {n="Пошук протиотрути",s="Пошук протиотрути — невідкладне завдання для Кор'ґана в Оргріммарі: зварити ліки для отруєного мисливця Рінаґа. Часу обмаль — отрута ось-ось стане смертельною, тож шукач пригод має зібрати отруйні мішечки отруйнохвостих скорпідів за міськими мурами. Завдання підкреслює безжальну природу живності Дуротару й потребу готуватися до походів у дику природу.",h="Пошук протиотрути — невідкладне завдання для Кор'ґана в Оргріммарі: зварити ліки для отруєного мисливця...",kw={"протиотрута","кор'ґан","рінаґ","скорпід","отрута","оргріммар"},ang={["class:Hunter"]="Кор'ґан — суворе нагадування всім мисливцям: знати отруту звіра й носити при собі потрібні ліки не менш важливо, ніж ваш лук і вміння вистежувати.",["faction:Horde"]="Орда в Дуротарі дбає про своїх: самотні слідопити й розвідники на околицях можуть покластися на твердиню Оргріммару по допомогу.",["race:Orc"]="Виживання в Дуротарі випробовує витривалість щойно оселених орків і показує, що навіть бувалий розвідник може впасти від тутешніх небезпек, якщо втратить обережність."},sec={{t="Перегони з отрутою",b="Полюючи в Дуротарі, троль Темного Списа на ім'я Рінаґ припустився небезпечної помилки — зчепився з тутешніми отруйнохвостими скорпідами, не маючи при собі протиотрути. Ужалений і швидко слабнучи від їхніх сильних токсинів, він мусив послати по негайну допомогу. Завдання лягає на Кор'ґана, досвідченого мисливця з Оргріммару: змішати цілющий напій, перш ніж отрута завершить свою справу."},{t="Виготовлення ліків",b="Щоб створити протиотруту, треба здобути саме джерело недуги — отруйні мішечки дорослих отруйнохвостів, що чаяться за воротами Оргріммару. Кор'ґан зауважує, що докори Рінаґові за недбалість доведеться відкласти, адже кожна мить на вагу золота. Щойно мішечки швидко здобуто й принесено до міста, Кор'ґан готує напій, щоб його чимдуж доправили до вмирущого мисливця."}},faq={{q="Хто такий Рінаґ?",a="Рінаґ — троль-мисливець Темного Спису в Дуротарі, якого тяжко пожалили місцеві отрутохвости, коли він вистежував звірів. Протиотрути в нього з собою не було, тож він злягає й покладається на кур'єрів, які мають принести ліки з Оргріммара, поки отрута його не здолала.",al={"переказ про рінаґа","хто отруєний","кому потрібна протиотрута"}},{q="Хто такий Кор'ґан?",a="Кор'ґан — досвідчений троль-мисливець Темного Спису з Тіньової Розколини в Оргріммарі. Він добре знає звірів Дуротару й має алхімічні знання, потрібні, щоб зварити дієву протиотруту із сирих отруйних мішечків отрутохвостів.",al={"кор'ґан","хто такий кор'ґан","кор'ґан оргріммар"}},{q="Звідки беруться потрібні отруйні мішечки?",a="Отруйні мішечки знімають просто з отрутохвостих скорпідів, що нишпорять скелястими посушливими рівнинами одразу за головними південним і східним входами до Оргріммара.",al={"де веномтейли","місце отруйних мішечків","мішечки скорпідів"}},{q="Чому на це доручення є обмеження в часі?",a="Квапитися треба через те, що Рінаґові гіршає. Отрута отрутохвостів надзвичайно сильна й діє швидко, тож Кор'ґан має отримати інгредієнти й зварити ліки, перш ніж мисливець помре від загального отруєння.",al={"чому є таймер","потреба таймера ліків","завдання з таймером"}},{q="Якого уроку вчить Кор'ґан під час цього полювання?",a="Кор'ґан попереджає: кожен мисливець має старанно вивчити звички й смертельні небезпеки своєї здобичі, перш ніж нападати. Іти в дикі краї без належної підготовки чи засобів протидії — недогляд, що легко може коштувати воїнові життя.",al={"урок кор'ґана","урок полювання","порада кор'ґана"}},{q="Як це доручення пов'язане з «Потребою в ліках»?",a="«Потреба в ліках» — початкове доручення, що запускає надзвичайну ситуацію й відлік часу. «Пошук протиотрути» — проміжний крок, у якому гравець збирає сирі складники, щоб Кор'ґан зварив готові ліки.",al={"зв'язок з потребою в ліках","попереднє завдання","як це пов'язано"}}},fp="20,368,24.397.0,17.405.0,14.266.0,16.259.0,43.165.0,47.242.0,53.250.0,46.238.0"}
P.entries["quest:816"] = {n="Втрачене, та не забуте",s="Втрачене, та не забуте — сумне завдання, яке дає Міша Тор'крен у своїй садибі на північний захід від Гострого Пагорба. Відчайдушно прагнучи бодай якоїсь певності, вона просить подорожніх обшукати небезпечні береги Річки Південної Люті, щоб знайти хоч якийсь слід її впертого сина Крона.",h="Втрачене, та не забуте — сумне завдання, яке дає Міша Тор'крен у своїй садибі на північний захід від Гострого...",kw={"міша тор'крен","крон","кроколіски","річка південної люті","амулет","горе"},ang={["class:Hunter"]="Для мисливців Крон — застережна історія про слідопита, який не оцінив лютості своєї здобичі й сам став її обідом.",["faction:Horde"]="Життя в ранньому Дуротарі суворе й непоступливе: звичайні родини борються з безжальним краєм і смертоносними хижаками, що блукають його кордонами.",["race:Orc"]="Доля Крона — трагічне нагадування: хоч гордість і воїнська слава — осердя орківської культури, безоглядна зарозумілість без поваги до небезпечних звірів веде до негеройської смерті."},sec={{t="Материнський страх",b="На північний захід від Гострого Пагорба, у посушливих червоних пустках Дуротару, стоїть скромна садиба Тор'кренів. Тут живе Міша Тор'крен, орчиха-мати, скута горем і тривогою. Кілька днів тому її син Крон оголосив, що йде на захід до Річки Південної Люті на кордоні зі Пустками полювати на лютих річкових кроколісків. Попри її застереження про смертоносних звірів, уперта гордість погнала Крона геть доводити свою силу. Відтоді його ніхто не бачив."},{t="Гірке підтвердження",b="Міша просить перехожих шукачів пригод прочесати береги Річки Південної Люті в пошуках будь-якого знаку про долю Крона — і навіть радить зазирнути в черева кроколісків. На жаль, її найтемніші передчуття справджуються. У вбитих кроколісків-страхопащ біля води знаходиться проковтнутий амулет Крона. Повернення цієї пам'ятки Міші гасить останню надію, що її хлопець вижив, але нарешті дає згорьованій матері певність, потрібну, щоб почати оплакувати сина."}},faq={{q="Хто така Міша Тор'крен?",a="Міша Тор'крен — орчиха-фермерка й мати, що живе на відлюдній садибі на північний захід від Гострого Пагорба в Дуротарі. Змучена горем і тривогою, вона просить мандрівників пошукати будь-який слід її зниклого сина, Крона.",al={"міша тор'крен","хто дає втрачене та не забуте","мати крона"}},{q="Ким був Крон?",a="Крон був упертим сином Міші Тор'крен. Прагнучи довести свою силу, він знехтував материними пересторогами й пішов полювати на небезпечних кроколісків біля Річки Південної Люті, де й загинув передчасно.",al={"хто такий крон","що сталося з кроном","син міші"}},{q="Де зник Крон?",a="Крон подався на захід через Дуротар до кордону з Пустками, щоб полювати на берегах Річки Південної Люті.",al={"де крон","де шукати крона","місце крона"}},{q="Як довести Міші, що сталося з Кроном?",a="Проковтнутий амулет Крона ви знайдете в рештках кроколісків Жахощелепів, що нишпорять у водах Річки Південної Люті. Повернена Міші родинна реліквія підтверджує його смерть.",al={"амулет крона","знак долі крона","шлунок кроколіска"}},{q="Яку нагороду дає Міша?",a="Міша дарує вам подарунок, який колись приготувала Кронові, щоб відсвяткувати його переможне повернення з полювання. Дізнавшись про його смерть, вона не може на нього дивитися й віддає шукачеві пригод, що приніс їй нарешті певність.",al={"нагорода втраченого та не забутого","подарунок міші"}},{q="Чому Крон узагалі пішов?",a="Крона гнала вперта гордість і бажання довести свою мисливську вправність. Коли мати застерегла, що кроколіски надто люті й небезпечні, він розлютився й усе одно пішов на них полювати.",al={"чому крон пішов","гордість крона"}}},fp="22,244,16.475.0,19.465.1,22.201.0,13.202.1,26.114.0,38.184.1,28.224.1,38.212.0"}
P.entries["quest:817"] = {n="Практична здобич",s="Практична здобич — мисливське завдання від шкіряника Вел'ріна Фанга в Селі Сен'джин. Населення зростає, а запаси тануть, тож плем'я Темного Списа мусить добути міцні тигрові шкури на сусідніх Островах Відлуння, щоб виготовити необхідні намети, одяг і спорядження.",h="Практична здобич — мисливське завдання від шкіряника Вел'ріна Фанга в Селі Сен'джин.",kw={"вел'рін фанг","тигри","шкури","село сен'джин","острови відлуння","полювання"},ang={["class:Hunter"]="Розповідь Вел'ріна про цілий день мовчазного вистежування перед тим, як захлопнути пастку, напряму говорить про головні чесноти, яких навчають усіх молодих мисливців: терпіння й точність.",["faction:Horde"]="Підтримка молодого анклаву Темного Списа необхідними товарами допомагає закріпити південний фланг Орди вздовж Великого Моря.",["race:Troll"]="Для вигнанців Темного Списа полювання на Островах Відлуння — гірке нагадування про втрачений дім, де, щоб прогодувати плем'я, доводиться ступати землею, яку вкрав Залазан."},sec={{t="Питання виживання",b="Життя на посушливому узбережжі Дуротару суворе, і тролі Темного Списа, вигнані до Села Сен'джин, мають використовувати кожен ресурс сповна. Тигрові шкури — один із найуніверсальніших матеріалів: без них не зшити наметів, важких ковдр і підсиленої броні. Поселення переповнюється біженцями й розвідниками, що повертаються, запаси вичерпалися, і ремісники на кшталт Вел'ріна Фанга змушені замовляти нові полювання."},{t="Рівновага й полювання",b="Темний Спис підтримує виважені стосунки з хижаками своїх земель. Замість винищувати тутешніх тигрів Дуротару, тролі здебільшого дають хижакам жити спокійно й відстрілюють їх лише тоді, коли племінні комори потребують поповнення. Переправа через воду на Острови Відлуння, щоб вистежити цих хижаків, — водночас і практична потреба, і традиційне випробування терпіння, дисципліни та вміння виживати в дикій природі."}},faq={{q="Хто такий Вел'рін Фанг?",a="Вел'рін Фанг — троль-ремісник Темного Спису із Села Сен'джин, що працює з хутром і шкірою. Він посилає мисливців по шкури, без яких племені не мати ні одягу, ні притулку, ні спорядження.",al={"вел'рін фанг","хто дає практичну здобич","вел'рін"}},{q="Навіщо Селу Сен'джин тигрове хутро?",a="Населення Села Сен'джин зростає, і наявних запасів уже не вистачає. Тигрові шкури — міцний матеріал для теплих ковдр, надійних наметів і шкіряних обладунків, що захистять мешканців від суворої погоди.",al={"навіщо тигрове хутро","мета практичної здобичі","для чого хутра"}},{q="Де водяться дуротарські тигри?",a="Тигри скрадаються дикими хащами Островів Відлуння — архіпелагу трохи віддалік від південно-східного узбережжя Дуротару.",al={"де тигри","місця тигрів","тигри островів відлуння"}},{q="Чому тролі не винищують усіх тигрів поблизу?",a="Вел'рін пояснює, що Темний Спис свідомо врівноважує свої потреби з місцевою природою. Він дає хижакам плодитися, щоб їх не поменшало, і проріджує їх лише тоді, коли потреби селища в матеріалах перевищують запаси.",al={"чому не винищити тигрів","чому тигри розплоджуються"}},{q="Чи важливе полювання на тигрів для культури Темного Спису?",a="Так. Вистежування тигра вважають обрядом терпіння й хитрості. Вел'рін тепло згадує, як майже цілий день нерухомо чекав у заростях Островів Відлуння, перш ніж здобув свою першу велику мисливську перемогу.",al={"традиція полювання на тигрів","перше полювання на тигра"}},{q="Навіщо мисливцям іти на Острови Відлуння, якщо їх тримає Залазан?",a="Хоча зрадник-знахар Залазан і його зачакловані посіпаки займають більшу частину архіпелагу, диких звірів на островах сила-силенна. Полювання й пошуки на зовнішніх берегах — ризик, на який Темному Спису доводиться йти.",al={"тигри на островах відлуння","чому йти на острови відлуння"}}},fp="14,280,20.430.0,20.432.0,20.197.0,41.219.0,35.127.0,48.256.0,51.212.0,65.231.0"}
P.entries["quest:818"] = {n="Спиртовий розчинник",s="Майстер Ворнал із Села Сен'джин випробовує шукачів пригод-початківців, вимагаючи реагентів, щоб відшкодувати слабкий зір. Він посилає можливих учнів збирати очі макрур і слиз крабів на узбережжі Дуротару. Хоч він глузує з самої думки взяти учня, це завдання — свідоме випробування терпіння й рішучості.",h="Майстер Ворнал із Села Сен'джин випробовує шукачів пригод-початківців, вимагаючи реагентів, щоб відшкодувати...",kw={"майстер ворнал","алхімія","макрури","слиз","село сен'джин","реагенти"},ang={["faction:Horde"]="Узбережжя Дуротару лишається небезпечним для молодої Орди; винищення агресивних макрур і прибійних крабів убезпечує рибальські береги довкола Села Сен'джин.",["race:Orc"]="Ворнал відкрито сумнівається, чи здатні орки на тиху дисципліну, потрібну для алхімії, тож це завдання — нагода довести, що єдність Орди сягає й ученого терпіння.",["race:Troll"]="Для Темного Списа, що відбудовується в Селі Сен'джин, довести свою гідність старшим майстрам, як-от Майстер Ворнал, життєво важливо, щоб понести далі містичні й алхімічні традиції племені."},sec={{t="Згаслий зір майстра",b="Майстер Ворнал сидить у Селі Сен'джин, обтяжений віком і згасанням зору. Там, де первісна магія колись сама текла до його пальців, він тепер тяжко спирається на алхімію, щоб загострити чуття й творити своє мистецтво. Попри дедалі більшу тілесну неміч, упертий троль відмовляється брати учня, заявляючи, що ні Темний Спис, ні орки Дуротару не породили нікого, гідного його науки."},{t="Випробування невипробуваних",b="Замість прямого навчання Ворнал вимагає сирих матеріалів із суворого узбережжя: цілих очей макрур і флаконів слизу крабів-повзунів. Щоб здобути неушкоджені очі в броньованих клешнястих макрур, потрібні точні удари, а збирання достатньої кількості слизу перевіряє готовність шукача пригод терпіти нудну, чорну роботу. Для Ворнала полювання на цих прибережних створінь — не стільки про реагенти, скільки про відсіювання тих, кому бракує зосередженості."},{t="Міра волі",b="Для Майстра Ворнала час і терпіння — остаточна міра сили. Він чекає, що нетерплячі юнаки піддадуться роздратуванню або й зовсім покинуть цю марудну справу. Повернення до Села Сен'джин із бездоганними інгредієнтами доводить не лише вміння виживати серед небезпечних рифів протоки Островів Відлуння, а й дисципліну, потрібну, щоб опанувати тонке мистецтво алхімії."}},faq={{q="Хто такий Майстер Ворнал?",a="Майстер Ворнал — старий троль-алхімік і заклинач із Села Сен'джин. Із віком його зір слабне, тож йому доводиться вдаватися до алхімічних розчинників і настоїв, щоб творити магію, яка колись давалася легко.",al={"майстер ворнал","хто такий ворнал","переказ про ворнала"}},{q="Навіщо Ворналові очі макрур і слиз повзунів?",a="Ворнал покладається на алхімічні суміші, що допомагають його магії й заступають згасаючий зір. Слиз і цілі очі макрур — реагенти для його сумішей, а заразом і вступне випробування для охочих стати учнем.",al={"навіщо слиз повзунів","чому очі макрур","що робить ворнал"}},{q="Чому Ворнал так неохоче бере учня?",a="Ворнал має високі вимоги й мало терпить зарозумілість. Він вважає, що жоден троль чи орк ще не виявив справжньої відданості й терпіння, щоб у нього вчитися, і бачить у більшості охочих учнів пихатих і легко розчаровуваних.",al={"учень ворнала","чому немає учня","чи ворнал шукає учня"}},{q="Де біля Села Сен'джин водяться ці істоти?",a="Повзуни й макрури блукають мілинами вздовж Побережжя Темного Списа й живуть у протоках, що відділяють материк від Островів Відлуння неподалік берега.",al={"де макрури","де повзуни","звірі узбережжя дарґспір"}},{q="Чому очі макрур мають бути цілими?",a="Алхімічні настої, що загострюють чуття, потребують неушкоджених органів чуття. Грубі удари в бою можуть розчавити ніжні очі макрури, тож мисливцеві потрібні точність і стриманість.",al={"ціле око","цілі очі макрур","чому цілі очі"}},{q="Якого уроку намагається навчити Ворнал?",a="Ворнал вірить, що терпіння — справжня перевірка вдачі. Доручивши одноманітну й брудну роботу збирача на прибої, він хоче побачити, чи новачок піддасться слабкості й поспіху, чи збереже спокійну зосередженість алхіміка.",al={"урок ворнала","сенс завдання","випробування терпіння"}}},fp="16,336,23.409.0,20.445.0,17.369.0,21.225.0,52.240.0,50.245.0,55.146.0,42.197.0,38.240.0"}
P.entries["quest:819"] = {n="Порожнє Барильце Ченя",s="Серед диких просторів Пусток лежить покинуте порожнє барильце з написом Ченя Бурештофа. Знахідка дає початок подорожі в минуле славетного мандрівного бровара, що колись допомагав своєю бойовою вправністю заснувати Дуротар.",h="Серед диких просторів Пусток лежить покинуте порожнє барильце з написом Ченя Бурештофа.",kw={"порожнє барильце ченя","чень бурештоф","дрон","раджет","рекссар","дуротар"},ang={["faction:Horde"]="Ченя Бурештофа пам'ятають як шанованого союзника, що бився пліч-о-пліч із Рекссаром і Рокханом, щоб заснувати Дуротар і захистити Орду в її найперші дні.",["profession:Cooking"]="Барильце — спадщина майстра-бровара, чий легендарний смак і пошуки рідкісних складників надихали ремісників по всьому Калімдору."},sec={{t="Мандрівна реліквія",b="Час від часу мандрівники натрапляють серед посушливих просторів Пусток на покинуту дерев'яну діжку. На відміну від звичайних бочок, які лишають шипогриви-Гостромани чи кентаври-Колкари, ця діжка ретельно зроблена й має виразну табличку з написом: «Чень Бурештоф — хай твій дух буде піднесений, а чарка — піднята!» Така незвична реліквія, що печеться під сонцем Калімдору, спонукає кожного допитливого шукати знавця броварства, щоб з'ясувати, як вона тут опинилася."},{t="Відлуння заснування Дуротару",b="Принесене Майстрові Броварства Дрону в Раджет, барильце розкриває своє походження. Дрон одразу впізнає роботу: воно належало Ченю Бурештофу — легендарному пандаренові-мандрівникові, що разом із Рекссаром брав участь у вирішальних битвах, які вибороли Дуротар для Орди Тралла. Хоч минули роки відтоді, як Чень ходив червоною землею Калімдору, його легендарні рецепти й мандрівна вдача досі живуть у пам'яті досвідчених броварів."}},faq={{q="Що таке Порожнє Барильце Ченя?",a="Це покинута пивоварна бочка, знайдена в Пустках. На ній напис-присвята мандрівному пандаренові, майстрові броварства Ченю Бурештофу.",al={"порожнє барильце","барильце ченя","що за бочка"}},{q="Хто такий Чень Бурештоф?",a="Чень Бурештоф — невловимий пандарен, майстер броварства, що багато мандрував Калімдором. Найбільше він відомий тим, що допомагав мок'наталові, володареві звірів Рекссару, боронити й засновувати Дуротар.",al={"хто такий чень","переказ про ченя","пандарен-броваря"}},{q="Кому віднести барильце?",a="Барильце можна віднести Майстрові Броварства Дрону, орку-броварові, що стоїть при дорозі біля Раджета: він упізнає знак Ченя й знає, як відтворити його рецепти.",al={"де здати барильце","кому потрібне барильце ченя","здати барильце"}},{q="Чому барильце Ченя лежить у Пустках?",a="Багато років тому Чень мандрував Калімдором у пошуках екзотичних інгредієнтів для свого пива — зокрема тоді, коли допомагав молодій Орді відстояти нову батьківщину від сил Адмірала Праудмура.",al={"чому барильце в пустках","як барильце потрапило сюди"}},{q="Чи з'являється Чень Бурештоф власною персоною?",a="Ні. Чень давно покинув ці краї, і в Калімдорі його вже давно не бачили. Лишилися тільки його старі барильця, рецепти й теплі спогади таких союзників, як Дрон і Рекссар.",al={"чи можна знайти ченя","де чень бурештоф","чи чень у класиці"}},{q="Що Майстер Броварства Дрон робить із барильцем?",a="Дрон у захваті від реліквії й користається нагодою, щоб кинути виклик мандрівникам-сміливцям: зібрати складники з місцевих звірів, щоб він відтворив міцні легендарні напої Ченя.",al={"лінія завдань дрона","що далі з барильцем"}}},fp="16,243,17.517.0,28.455.0,25.151.0,23.204.0,29.159.0,43.205.0,38.176.0,43.185.0"}
P.entries["quest:821"] = {n="Порожнє Барильце Ченя",s="Це завдання продовжує легендарний родовід пандаренського броварства в Пустках. Майстер Броварства Дрон у Раджеті пропонує відтворити знаменитий міцний напій Ченя Бурештофа, якщо ви зберете дикі складники з місцевих звірів, що блукають саваною.",h="Це завдання продовжує легендарний родовід пандаренського броварства в Пустках.",kw={"порожнє барильце ченя","чень бурештоф","дрон","раджет","пиво","пустки"},ang={["faction:Horde"]="Чень Бурештоф бився пліч-о-пліч із Рекссаром, допомагаючи заснувати Дуротар, тож будь-який слід його мандрів має для Орди особливе значення.",["profession:Cooking"]="Кулінари-мандрівники оцінять сміливе — хоч і бентежне — поєднання прикордонного різництва й вишуканого броварства, з якого народжуються легендарні трунки Калімдору.",["race:Orc"]="Дрон показує, як орки перейняли давні броварські традиції, передані просто від мандрівників, що ходили цією землею разом із молодою Ордою."},sec={{t="Спадщина в барильці",b="Коли покинуте барильце з пандаренським написом потрапляє до рук Майстра Броварства Дрона в Раджеті, воно будить теплі спогади про легендарного мандрівника Ченя Бурештофа. Чень передав таємниці свого фірмового пива Дроновому наставникові, а той довірив їх Дронові. Хоч для небровара це й дивно, рецепт вимагає сирих, міцних складників, здобутих просто з лютих звірів Пусток."},{t="Урожай савани",b="Щоб зварити міцний трунок Ченя, потрібен незвичний набір складників: нирки степових довгоступів, ікла левів савани й ріг громоящера. Щоб їх здобути, доведеться полювати на запорошених рівнинах — і пересвідчитися, що лише найвитриваліші звірі здатні дати той удар, без якого немає справжнього пандаренського пива. Коли все зібрано, Дрона охоплює ностальгія: він зауважує, що відроджена стара формула гріє йому шлунок майже так само, як колишні партії трогського пива."}},faq={{q="Хто такий Майстер Броварства Дрон?",a="Майстер Броварства Дрон — орк-бровар у портовому містечку Раджет. Мистецтва броварства він навчився в наставника, який отримав рецепти особисто від легендарного мандрівника Ченя Бурештофа.",al={"майстер броварства дрон","хто такий дрон","дрон раджет"}},{q="Навіщо в рецепті пива нирки й роги звірів?",a="Пандаренські традиції броварства — та й переробки, які вигадали грубуваті прикордонні бровари, — часто спираються на сильні, незвичні складники від місцевих звірів, щоб надати міцним напоям снаги, удару й своєрідного природного присмаку.",al={"чому частини тварин","нирки довгоступів для пива","ікла лева для пива"}},{q="Де знайти потрібні інгредієнти?",a="Усі три складники добувають із місцевих звірів Пусток. Рівнинні довгоступи й саванні леви блукають відкритими луками, а громоящери зазвичай пасуться на посушливіших чи кам'янистіших ділянках рівнин.",al={"де знайти ікла","де громові ящери","знайти інгредієнти пива"}},{q="Хто такий Чень Бурештоф?",a="Чень Бурештоф — мандрівний пандарен, майстер броварства, що подорожував Калімдором, коли засновували Дуротар: він допомагав Орді й водночас шукав екзотичні рідкісні інгредієнти, щоб довести до досконалості своє міцне пиво.",al={"хто такий чень","переказ про ченя бурештофа","чень"}},{q="Що буде, коли принести інгредієнти Дронові?",a="Левові ікла, нирки рівнинних довгоступів і ріг громоящера тішать Дрона, нагадують йому давні дні броварства й ведуть просто до останнього етапу відтворення легендарного напою.",al={"наступне завдання після порожнього барильця","нагорода дрона","що далі"}},{q="Що за трогове варево, яке згадує Дрон?",a="Побачивши дикі інгредієнти, Дрон тепло згадує давній напій, відомий як трогове варево, — свідчення його химерного минулого, коли він заброджував на прикордонні суворі й незвичні суміші.",al={"трогове пиво","трогове варево дрона","пиво трогів"}}},fp="16,247,17.400.0,23.473.1,24.197.0,56.232.0,44.237.0,24.202.0,53.205.0,38.191.0"}
P.entries["quest:822"] = {n="Порожнє Барильце Ченя",s="Після того як зварено міцний «Бурештоф», Майстер Броварства Дрон у Раджеті пропонує приготувати ще один незвичний рецепт, перейнятий від невловимого мандрівника-пандарена Ченя Бурештофа. Цей міцний напій, відомий як трогське пиво, вимагає рідкісних органів і залоз, здобутих із місцевих звірів Пусток.",h="Після того як зварено міцний «Бурештоф», Майстер Броварства Дрон у Раджеті пропонує приготувати ще один...",kw={"порожнє барильце ченя","трогське пиво","дрон","чень бурештоф","раджет","громояструб"},ang={["faction:Horde"]="Чень Бурештоф бився разом з Ордою під час оборони Дуротару й залишив глибокий слід у пам'яті орків на кшталт Дрона, які зустріли його в ті ранні дні.",["profession:Cooking"]="Кулінарні пуристи можуть скривитися від трогського пива, але використання ситних субпродуктів і міцних залоз відповідає прикордонній кухарській традиції: нічого зі здобичі не пропадає.",["race:Orc"]="Майстер Броварства Дрон — орк незвичного фаху: він обрав екзотичні броварські методи Ченя замість традиційного шляху воїна й веде свою справу в Раджеті."},sec={{t="Друга пандаренська формула",b="Допомігши Майстрові Броварства Дрону відтворити перший трунок легендарного Ченя Бурештофа, шукач пригод дізнається від орка-бровара, що мандрівний пандарен поділився не однією таємницею. Дрон має рецепт дивакуватого напою, відомого як трогське пиво. На відміну від звичайних трунків, які переганяють із зерна, це дивне пиво цілком тримається на міцних органічних реагентах, здобутих із найлютіших звірів центрального Калімдору."},{t="Складники Трогського пива",b="Щоб зварити цей їдкий і бадьорливий трунок, Дронові потрібні громові складники: блискавкові залози бурешкурів, слинна залоза великого громояструба й ситна печінка кодо, що бродять рівнинами. Після перегонки суміш дає надзвичайно бадьорливий напій, створений для виживання в дикій глушині."},{t="Тривала співпраця",b="Ремесло Дрона не обмежується однією партією. Знаючи, який попит на трунок серед мандрівних шукачів пригод і найманців, що проходять через нейтральний порт Раджет, Дрон лишає домовленість відкритою: він охоче зварить свіже трогське пиво щоразу, як дослідник принесе нову партію звірячих нутрощів."}},faq={{q="Хто такий Чень Бурештоф?",a="Чень Бурештоф — невловимий мандрівний пандарен, майстер броварства, що подорожував Калімдором, коли засновували Дуротар. Дорогою він поділився кількома своїми міцними рецептами з Дроном у Раджеті, а тоді рушив мандрувати далі.",al={"хто такий чень","переказ про ченя","пандарен чень"}},{q="Де знайти Майстра Броварства Дрона?",a="Майстер Броварства Дрон живе в нейтральному портовому містечку Раджет на східному узбережжі Пусток. Він днями вдосконалює химерні напої, яких навчився після зустрічі з Ченем.",al={"місце дрона","де майстер броварства дрон","дрон"}},{q="Що таке трогове пиво?",a="Трогове пиво — незвичний і міцний напій, якого Чень навчив Дрона. Замість звичайного хмелю в ньому залози й нутрощі звірів, тож воно горезвісне своїм ударом і пасує лише загартованим шукачам пригод.",al={"трогове пиво","що за напій","що вариться в дрона"}},{q="Де взяти блискавичні залози?",a="Блискавичні залози добувають із грозошкурих звірів, що нишпорять посушливими просторами Пусток і носять у тілі природний електричний заряд.",al={"джерело блискавичної залози","місце штормової шкури","де взяти блискавичну залозу"}},{q="З яких звірів падають слинні залози громояструбів?",a="Ці залози збирають саме з великих громояструбів — величних хижих птахів, що б'ють блискавицями й полюють у відкритому небі над Пустками.",al={"слинна залоза громояструба","де великі громояструби","місце громояструбів"}},{q="Чи можна зварити трогове пиво не раз?",a="Так. Майстер Броварства Дрон завжди охоче зварить нову партію пива, щойно шукачі пригод принесуть йому свіжі залози й печінку кодо.",al={"чи повторюване","чи можна ще раз","повторити трогове пиво"}}},fp="16,301,25.422.0,28.339.0,23.303.1,23.246.0,34.193.0,18.215.0,37.154.0,43.158.0,36.146.0"}
P.entries["quest:823"] = {n="Доповідь Орґнілу",s="Доповідь Орґнілу — раннє завдання Орди, яке доручає Майстер Ґадрін із Села Сен'джин. Воно посилає шукачів пригод-початківців на північ до Гострого Пагорба — попередити Орґніла Соулскара про підступну руку культу Палаючого Клинка. Ця доповідь допомагає узгодити розрізнену оборону Дуротару проти демонічного розбещення, що визріває просто на батьківщині орків.",h="Доповідь Орґнілу — раннє завдання Орди, яке доручає Майстер Ґадрін із Села Сен'джин.",kw={"орґніл соулскар","майстер ґадрін","гострий пагорб","палаючий клинок","доповідь","дуротар"},ang={["faction:Horde"]="Це завдання знаменує життєво важливий зв'язок і співпрацю між новими союзниками — тролями Темного Списа й орками Дуротару — перед спільними загрозами.",["race:Orc"]="Орґніл Соулскар — передова оборона вашої нової батьківщини: він дбає, щоб демонічна скверна не вкоренилася в межах Дуротару.",["race:Troll"]="Хоч Темний Спис поглинутий боротьбою із Залазаном, Майстер Ґадрін показує відданість тролів Орді, попереджаючи орківських ватажків про небезпеки в краї."},sec={{t="Узгоджена оборона",b="Поки Село Сен'джин бореться з власними бідами — передусім зі зрадою Залазана на Островах Відлуння, — Майстер Ґадрін розуміє, що звістки про культ Палаючого Клинка означають значно ширшу небезпеку. Шепіт демонічного розбещення було викрито в Долині Випробувань, і знахар Темного Списа знає: з такими загрозами не впоратися поодинці. Він посилає мандрівних героїв на північ запиленою дорогою до Гострого Пагорба, де тутешня орківська влада тримає ширшу варту над Дуротаром."},{t="Орґніл Соулскар",b="Розміщений у військовому таборі Гострого Пагорба, Орґніл Соулскар — орк, якому доручено викорінювати внутрішнє зло й берегти серце краю. Коли шукачі пригод передають застереження Ґадріна, Орґніл не гаючись зводить докупи звістки з Долини Випробувань і Села Сен'джин. Усвідомивши, що тінь Палаючого Клинка нависла небезпечно близько, він швидко збирає сили, щоб розгромити культистів, перш ніж їхні темні ритуали похитнуть молоду державу."}},faq={{q="Хто дає завдання «Доповідь Орґнілу»?",a="Майстер Ґадрін, знахар і духовний провідник Темного Спису із Села Сен'джин, дає вам це доручення, коли ви допоможете тролям із першими місцевими негараздами.",al={"хто дає доповідь орґнілу","де взяти доповідь орґнілу","видавець доповіді орґнілу"}},{q="Де знайти Орґніла Соулскара?",a="Орґніл Соулскар — на Гострому Пагорбі, укріпленому поселенні на північ від Села Сен'джин у центрі Дуротару.",al={"де орґніл соулскар","місце орґніла соулскара","знайти орґніла соулскара"}},{q="Чому Майстер Ґадрін посилає вас на Гострий Пагорб?",a="Майстер Ґадрін розуміє, що демонічна діяльність культу, викрита в Долині Випробувань і по всьому Дуротару, загрожує всім, а не лише тролям. Він скеровує вас до Орґніла Соулскара — орка, відповідального за те, щоб берегти край від Палаючого Клинка.",al={"чому доповісти орґнілу","чому йти на гострий пагорб","мета доповіді орґнілу"}},{q="Що таке Палаючий Клинок, про який ідеться в завданні?",a="Палаючий Клинок — підступний культ демонопоклонників, що діє в тіні по всьому Дуротару й поза ним. Їхня таємна присутність у сусідніх каньйонах і печерах загрожує безпеці й стабільності молодої Орди.",al={"хто такі палаючий клинок","культ палаючого клинка","що таке палаючий клинок"}},{q="Яке завдання йде після «Доповіді Орґнілу»?",a="Коли ви доповісте Орґнілу Соулскару на Гострому Пагорбі, він одразу дасть вам завдання «Темні бурі», щоб розвідати й дати відсіч загрозі сектантів, що дедалі зростає.",al={"наступне завдання після доповіді орґнілу","продовження доповіді орґнілу","що після доповіді орґнілу"}},{q="Що треба виконати, щоб отримати це завдання?",a="Воно природно йде після вашого прибуття до Села Сен'джин у завданні «Доповідь у село Сен'джин» і пов'язує перші відкриття в Долині Випробувань із ширшою кампанією в Дуротарі.",al={"попереднє завдання доповіді орґнілу","як відкрити доповідь орґнілу","завдання перед доповіддю орґнілу"}}},fp="16,347,21.502.0,15.482.0,37.175.0,33.120.0,46.258.0,49.215.0,36.165.0,64.169.0"}
P.entries["quest:824"] = {n="Дже'неу з Земного Кільця",s="Це доручення посилає шукачів пригод Орди віднести зіпсовану водяну кулю, здобуту з елементалів Ашенвалю, до Дже'ню Санкреа із Земляного Кільця. Шаман, відданий гармонії стихій, прагне зрозуміти порчу, що шириться Зорамським Узмор'ям і Чорноглибинними Печерами. Вивчення реліквії дає надію зупинити протиприродну пошесть, яка отруює води краю.",h="Це доручення посилає шукачів пригод Орди віднести зіпсовану водяну кулю, здобуту з елементалів Ашенвалю, до...",kw={"дже'ню санкреа","земляне кільце","масток врайлгісс","водяна куля","ашенваль","елементалі"},ang={["class:Shaman"]="Це завдання прямо стосується шаманського обов'язку берегти рівновагу стихій. Віднісши зіпсовану кулю, ви допоможете побратимові із Земляного Кільця розпізнати небезпечну духовну недугу.",["faction:Horde"]="Поки Орда зводить укріплені табори на кшталт Застави Зорам'гар в Ашенвалі, з'ясувати темні причини ворожості місцевих елементалів украй важливо для безпеки узбережжя.",["race:Troll"]="Дже'ню Санкреа втілює глибоку духовну мудрість Темного Списа: свій родовий зв'язок із духами він віддає на службу Земляному Кільцю."},sec={{t="Посланець стихій",b="Коли по всьому Ашенвалю почали з'являтися дивні отруєні елементалі, розвідники помітили протиприродну силу, що їх оживлювала. Серед решток лежала забруднена водяна куля — ціла посудина, що пульсувала зіпсованою магією. Знаючи, що звичайні вояки й розвідники не мають духовного прозріння, аби розгадати таку аномалію, Масток Врайлгісс скерував мандрівників Орди до того, хто глибоко знає давні легенди й таємниці стихій, — до Дже'ню Санкреа."},{t="Очі Земляного Кільця",b="Дже'ню Санкреа належить до Земляного Кільця — ордену шаманів, які присвятили себе збереженню рівноваги між первісними силами Азероту. Поки війська Орди стережуть рубіж на Зорамському Узмор'ї, Дже'ню зосереджується на духовній рані, що гноїться в сусідніх руїнах храму в Чорноглибинних Печерах. Для нього елементаль, що черпає силу з отруєної посудини, — не просто окрема загроза, а тривожна прикмета: незримі давні сили викривлюють природний лад."}},faq={{q="Хто такий Дже'ню Санкреа?",a="Дже'ню Санкреа — шаман-троль, представник Земляного Кільця на півночі Калімдору. Він присвятив життя єднанню зі стихіями та їх вивченню й отаборився біля узбережжя Зорам, щоб дослідити темні збурення, що здіймаються з Чорноглибинних Печер.",al={"хто такий дже'ню","переказ про дже'ню санкреа","що робить дже'ню тут"}},{q="Що таке Земляне Кільце?",a="Земляне Кільце — спілка шаманів, що прагнуть тримати первісні стихії Азероту в злагоді. Вони заглиблюються в давні знання, забутих духів і старі легенди, щоб гасити хаос стихій і зцілювати духовну скверну по всьому світу.",al={"що таке земляне кільце","хто земляне кільце","переказ про земляне кільце"}},{q="Де знайти Дже'ню Санкреа?",a="Дже'ню можна знайти на Заставі Зорам'гар на узбережжі Зорам в Ашенвалі, де він вивчає збурення стихій, що здіймаються із сусідніх Чорноглибинних Печер.",al={"де дже'ню","місце дже'ню","знайти дже'ню санкреа"}},{q="Що таке Опоганена Водяна Куля?",a="Куля — магічний провідник, через який могутні водяні елементалі спрямовують свою силу. Знайдена ціла, але осквернена куля свідчить, що темні сили в цих краях навмисне спотворюють і поневолюють місцевих духів.",al={"що за куля","переказ про опоганену кулю","водяна куля"}},{q="Хто посилає поговорити з Дже'ню?",a="Масток Врайлгісс, офіцер Орди в Ашенвалі, скеровує шукачів пригод віднести осквернену реліквію Дже'ню, зрозумівши, що військо не може розгадати її дивну магічну природу.",al={"хто починає це завдання","завдання мастока"}},{q="Що Дже'ню зробить із кулею?",a="Дже'ню бере посудину під свою опіку, щоб Земляне Кільце дослідило природу її скверни, сподіваючись, що ці пошуки підкажуть, як очистити води й повернути спокій стривоженим елементалям краю.",al={"що станеться з кулею","зцілити осквернення"}}},fp="26,392,28.454.0,28.469.0,22.254.0,25.242.0,34.169.0,33.219.0,35.185.0,35.207.0"}
P.entries["quest:8249"] = {n="Потрібні скрині з мотлохом",s="У Маєтку Рейвенголдт Вінстоун Вульф постійно потребує міцних замкнених скринь, щоб навчати молодих розбійників гільдії. Оскільки навчальні замки від власного майстра маєтку надто прості для досвідчених учнів, Вульф обмінює особливі метальні ножі на справжні важкі скрині з мотлохом.",h="У Маєтку Рейвенголдт Вінстоун Вульф постійно потребує міцних замкнених скринь, щоб навчати молодих...",kw={"потрібні скрині з мотлохом","вінстоун вульф","маєток рейвенголдт","зламування замків","метальні ножі","розбійники","завдання"},ang={["class:Rogue"]="Добувати ці важкі скрині можна лише мистецтвом обчищення кишень досвідчених супротивників, тож Рейвенголдт — найкраще місце, де розбійник обміняє свої незаконні вміння.",["faction:Alliance"]="Хоча Рейвенголдт захований на спірних землях Лордерону, він діє незалежно й приймає замовлення від мандрівників з Альянсу, не зважаючи на фракційні межі.",["faction:Horde"]="Агенти Орди, що наважуються піднятися в гори Гілсбреда, бачать, що Рейвенголдтові цілком байдужа фракційна вірність: понад усе він цінує корисний незаконний товар."},sec={{t="Гострити кігті Рейвенголдту",b="У прихованому редуті Маєтку Рейвенголдт, серед гір над Передгір'ям Гілсбреда, навчання не припиняється ніколи. Майстер-злодій Вінстоун Вульф наглядає за вишколом агентів гільдії й особливо цінує практичну майстерність зламування замків. Зан дає новобранцям навчальні пристрої, але Вульф вважає ту грубу роботу цілком непридатною для досвідчених агентів, яким у полі доведеться зламувати справжні, вперті механізми."},{t="Напрочуд відкрита домовленість",b="Щоб маєток мав справжні механізми, Вульф скуповує важкі скрині з мотлохом, поцуплені в небезпечних цілей по всьому Азероту. Хоча витягти такі скрині з кишень жертв можуть лише вправні злодії, Вульф торгує не тільки з розбійниками. Кожен, хто принесе партію цих замкнених скринь — навіть уже обчищених від головних цінностей, — здобуває прихильність Вульфа й запас ідеально збалансованих смертоносних метальних клинків маєтку, аби тільки всередині лишилася якась монетка для заохочення учнів."}},faq={{q="Навіщо Вінстоунові Вульфу ці скрині з мотлохом?",a="Учням-розбійникам Рейвенголдта потрібні справжні механізми, щоб тренуватися відмикати замки. Навчальні скрині, які робить місцевий майстер маєтку, Зан, Вульф вважає надто примітивними для будь-кого, хто вже не зовсім новачок, тож потрібні справжні скриньки, видобуті в небезпечних жертв.",al={"навіщо скрині з мотлохом","призначення скринь з мотлохом","чому вульфу скрині"}},{q="Де відбувається це доручення?",a="Обмін відбувається в Маєтку Рейвенголдт — таємному притулку гільдії злодіїв, захованому в горах на північ від Передгір'я Гілсбреда.",al={"де це завдання","місце вінстоуна вульфа","рейвенголдт"}},{q="Чи можуть здати це завдання лише розбійники?",a="Самі важкі скрині з мотлохом спершу здобувають розбійницьким мистецтвом крадіжки з кишень, але Вінстоун Вульф приймає їх від будь-кого, хто зможе принести їх до маєтку.",al={"чи це лише для розбійників","чи кожен може скрині з мотлохом","інші класи скрині з мотлохом"}},{q="Чому в скринях мають лишатися монети?",a="Вульф наполягає, щоб у кожній скрині лишалося кілька монет, бо навіть розбійникам-учням потрібна відчутна винагорода, яка підганяла б їх учитися відмикати замки.",al={"чому лишати монети в скринях","чи скриням потрібна здобич","порожні скрині з мотлохом"}},{q="Що Рейвенголдт дає натомість?",a="Вульф винагороджує тих, хто приносить скрині, репутацією в гільдії й добре виготовленими метальними ножами, які, як він уїдливо бажає, нехай знайдуть собі місце просто в чиємусь серці.",al={"нагорода за скрині з мотлохом","що дає вульф","метальні ножі рейвенголдта"}},{q="Хто такий Зан, на якого скаржиться Вульф?",a="Зан — постачальник замків при Рейвенголдті. Вульф вважає навчальні механізми Зана грубими й придатними хіба що для найзеленіших новачків, а не для серйозних виконавців.",al={"хто такий зан","зан рейвенголдт","замки зана"}}},fp="16,328,30.439.0,28.518.0,45.266.0,32.151.0,35.185.0,52.167.0,39.158.0,38.167.0"}
P.entries["quest:825"] = {n="З уламків…",s="Ґар'Ток із Гострого Пагорба посилає розвідників Орди обшукати затонулі рештки флоту великого адмірала Праудмура біля Дріботливого Узбережжя. Здобувши з підводних уламків досконалі Гномські Інструменти, Орда сподівається розібрати інженерію Альянсу й обернути цю технічну перевагу собі на користь.",h="Ґар'Ток із Гострого Пагорба посилає розвідників Орди обшукати затонулі рештки флоту великого адмірала...",kw={"ґар'ток","гномські інструменти","уламки","дріботливе узбережжя","праудмур","флот"},ang={["faction:Horde"]="Ґар'Ток бачить у кожному клапті металу Альянсу подвійну здобич: знання, щоб відбити майбутні вторгнення, і матеріал, щоб будувати молоду державу Дуротар.",["profession:Engineering"]="Для інженерів здобуття Гномських Інструментів висвітлює раннє технічне суперництво між механічною точністю Альянсу та ремеслами Орди, що лише зароджуються.",["race:Gnome"]="Хоч гноми невеликі на зріст, вони лишають слід усюди, куди пливе Альянс; їхнє витончене спорядження Орда шанує настільки, що відряджає по нього окремі місії."},sec={{t="Відлуння флоту",b="Коли великий адмірал Дейлін Праудмур привів морську міць Кул Тірасу до Калімдору, його судна забили берегову лінію біля Фортеці Тіраґард. Після його поразки розтрощені корпуси осіли вздовж Дріботливого Узбережжя. Поки вцілілі вояки Кул Тірасу укріплюють саму фортецю, рештки їхньої армади лежать розбиті на мілинах і повільно гниють під припливом."},{t="Гномські пристрої",b="Орківська війна традиційно спирається на грубу силу, залізо й кров, та Орда визнає небезпечну перевагу, яку дає винахідливість Альянсу. Гномські техніки супроводжували експедиційні флоти, оснащуючи судна Альянсу складними механізмами й точними приладами. Ґар'Ток прагне дістати ці затонулі інструменти, щоб Орда розгадала механіку, яка за ними стоїть."},{t="Дорога до Оргріммару",b="Здобуті інструменти не мають припадати пилом у Гострому Пагорбі. Ґар'Ток домовляється, щоб караван доправив їх просто до Оргріммару. Розбираючи гномські прилади, ремісники й тактики Орди прагнуть краще протистояти пристроям Альянсу в прийдешніх зіткненнях і водночас зміцнити власну молоду промисловість."}},faq={{q="Навіщо Орда збирає інструменти з цих уламків?",a="Орда хоче зрозуміти передові технології, якими користується Альянс. Гноми будують хитромудрі машини для людських військ, і, вивчаючи їхні інструменти, тактики Орди можуть з'ясувати, як протидіяти пристроям Альянсу, а корисні механізми перейняти для власних ремісників.",al={"навіщо збирати гномські інструменти","навіщо розбирати уламки","навіщо ґар'току інструменти"}},{q="Чиї кораблі розбилися біля Дріботливого Узбережжя?",a="Затонулі судна належали флотові Кул Тірасу під проводом Великого Адмірала Дейліна Праудмура. Флот висадився на берегах Дуротару, щоб воювати з щойно заснованою державою Тралла, і кілька кораблів загинули біля узбережжя трохи на схід від Фортеці Тіраґард.",al={"чиї це кораблі","хто розбив кораблі в дуротарі","уламки флоту праудмура"}},{q="Куди йдуть знайдені інструменти після Гострого Пагорба?",a="Ґар'Ток відправляє знайдені Гномські Інструменти з найближчим караваном до Оргріммара. Там інженери й ремісники зможуть ретельно вивчити ці пристрої, щоб зміцнити оборону й ремесла столиці.",al={"що з інструментами","куди йдуть гномські інструменти","хто отримує знахідки"}},{q="Звідки гномські інструменти на людських бойових кораблях?",a="Гноми — близькі союзники людей у Великому Альянсі: вони часто забезпечують морські експедиції механічними знаннями, облоговим спорядженням і точними інструментами для обслуговування, щоб бойові флоти були на ходу.",al={"чому гноми з людьми","гноми на кораблях праудмура","гномська техніка альянсу"}},{q="Що таке Дріботливе Узбережжя?",a="Дріботливе Узбережжя — східний берег Дуротару, що тягнеться повз Фортецю Тіраґард. Назву він дістав від напівзатоплених і затонулих суден, якими після битв з експедицією Праудмура всіяні мілкі води.",al={"де дріботливе узбережжя","місце дріботливого узбережжя","район затоплених кораблів дуротару"}},{q="Як це доручення пов'язане із загрозою у Фортеці Тіраґард?",a="Вибивши морських піхотинців Кул Тірасу під час штурму Фортеці Тіраґард, Ґар'Ток користається нагодою забрати решту ресурсів Альянсу. Обібравши сусідні уламки кораблів, Орда отримує зиск із ворожої поразки, перш ніж усе розтягнуть мародери чи винесе приплив.",al={"зв'язок з тіраґардом","зв'язок з перемогою над зрадниками","чому після тіраґарда"}}},fp="21,302,19.363.0,20.378.0,22.336.0,51.283.0,46.249.0,49.208.0,46.210.0,26.220.0,58.272.0"}
P.entries["quest:826"] = {n="Залазан",s="Майстер Ґадрін із Села Сен'джин доручає героям Орди вирушити на Острови Відлуння й покласти край зраді знахаря Залазана. Збожеволілий від темної магії, Залазан поневолив своїх одноплемінників і захопив законний дім тролів Темного Списа, змусивши їх до вигнання на узбережжі Дуротару.",h="Майстер Ґадрін із Села Сен'джин доручає героям Орди вирушити на Острови Відлуння й покласти край зраді...",kw={"залазан","знахар","острови відлуння","майстер ґадрін","темний спис","вол'джин","зрада"},ang={["class:Shaman"]="Залазан спотворює духовні мистецтва й первісні сили, якими володіють тролівські шамани та знахарі, обертаючи магію поневолення проти власних побратимів.",["faction:Horde"]="Це зіткнення — одне з перших великих випробувань єдності молодої Орди: воно доводить, що союзники з усього Дуротару стануть на захист вигнаного племені Темного Списа.",["race:Troll"]="Для троля Темного Списа вбити Залазана — глибоко особистий акт помсти й обов'язку: кара зраднику, що вкрав законний дім вашого народу й поневолив ваших братів."},sec={{t="Зрада на островах",b="Коли плем'я Темного Списа втекло зі свого затонулого острівного дому й рушило за Траллом через Велике Море, воно оселилося на Островах Відлуння біля південно-східного узбережжя Дуротару. Залазан, шанований і могутній знахар племені, піддався жадобі влади. Опанувавши прокляття, що поневолюють розум, він підкорив багатьох своїх родичів і підняв криваве повстання. Решту вільних тролів Темного Списа на чолі з Вол'джином вигнали з таборів предків за водою, і вони мусили збудувати тимчасовий притулок — Село Сен'джин."},{t="Муки племені",b="Залазанові було замало просто прогнати плем'я. Зі свого редуту на пагорбі центрального острова він раз у раз посилає загони через протоку, щоб викрадати нових тролів Темного Списа й затягувати їх у своє рабство. Уражені стають бездумними зуроченими рабами вуду, назавжди втраченими для племені. Майстер Ґадрін бачить у цьому не просто захоплення землі, а загрозу самому існуванню: доки відтяту голову Залазана не принесуть старійшинам, жоден троль Темного Списа не буде по-справжньому в безпеці."}},faq={{q="Хто такий Залазан?",a="Залазан колись був знаним знахарем серед тролів Темного Спису. Зіпсований жагою темної сили, він обернувся проти родичів: підкорюючи розум одноплемінників закляттями вуду, він поневолив їх і загарбав Острови Відлуння.",al={"переказ про залазана","хто бос островів відлуння","знахар залазан"}},{q="Чому Темний Спис утік з Островів Відлуння?",a="Залазан влаштував на островах раптовий переворот і мерзенним чаклунством перетворив братів і сестер на безтямних рабів. Вол'джину й уцілілим вільним тролям Темного Спису забракло сил проти зачаклованих родичів, тож вони відступили на материк, у Дуротар, і заснували Село Сен'джин як тимчасовий притулок.",al={"чому дарґспіри втекли","чому тролі в сен'джині","як тролі втратили острови відлуння"}},{q="Що стається з тролями під владою Залазана?",a="Сильні закляття цілком ламають розум тролів, яких він підкорив. Вони стають лише безтямними слугами Залазана: патрулюють острови й роблять набіги на материк, щоб захопити нових жертв. Майстер Ґадрін вважає їх навіки втраченими для племені, тож єдине милосердя для них — смерть.",al={"причарувані тролі","тролі вуду","чи можна вилікувати слуг залазана"}},{q="Де знайти Залазана?",a="Залазан має лігво на найбільшому острові Островів Відлуння, трохи на схід від південного узбережжя Дуротару. Він ходить між високою вершиною центрального пагорба й скупченням тролячих хиж просто під ним.",al={"де залазан","знайти залазана","місце залазана"}},{q="Хто дає завдання вбити Залазана?",a="Завдання дає Майстер Ґадрін, старійшина племені із Села Сен'джин на південному березі Дуротару, — після того, як ви прибудете з Долини Випробувань і виконаєте перші доручення з місцевими загрозами.",al={"хто дає залазана","де взяти завдання залазана"}},{q="Чому Вол'джин сам не веде наступ?",a="Вол'джин править племенем і разом із Вождем Траллом в Оргріммарі керує обороною Темного Спису, а Село Сен'джин лишається під місцевим проводом старійшин на кшталт Майстра Ґадріна. Ґадрін дбає про щоденне виживання й залучає вправних шукачів пригод, щоб ударити по зрадливому знахареві.",al={"де вол'джин","чому вол'джин не б'ється"}}},fp="8,295,21.525.0,17.490.0,16.236.0,42.307.0,52.300.0,26.227.0,37.208.0,46.307.0"}
P.entries["quest:827"] = {n="Череп-скеля",s="Доручене відлюдником Марґозом, це завдання посилає шукачів пригод Орди в печеру Череп-скелі одразу на схід від Оргріммару. Печеру захопив культ Палаючого Клинка, чиї прибічники болісними демонічними пристроями прив'язують себе до темної магії. Здобувши ці прокляті артефакти, Марґоз зможе вивчити присутність культу просто на порозі столиці.",h="Доручене відлюдником Марґозом, це завдання посилає шукачів пригод Орди в печеру Череп-скелі одразу на схід...",kw={"череп-скеля","марґоз","палаючий клинок","пекучі нашийники","культ","оргріммар"},ang={["class:Warlock"]="Пекучі Нашийники показують грубі, але могутні пута скверни й дають темним практикам зазирнути в те, як культ перетворює демонічну жертву на сиру силу.",["faction:Horde"]="Демонічний культ, що гноїться одразу за мурами Оргріммару, загрожує самому серцю й безпеці молодої Орди.",["race:Orc"]="Палаючий Клинок — це темне минуле, яке орки щодня борються лишити позаду; вичистити його зі скель Дуротару — справа виживання й честі."},sec={{t="Лігво тіней",b="Череп-скеля — похмура морська печера серед скелястого східного узбережжя Дуротару. На позір відлюдна, вона лежить тривожно близько до могутніх воріт Оргріммару. Замість диких звірів чи простих розбійників печери дають притулок осередку Палаючого Клинка — тіньового демонічного культу, що здавна отруює орківське суспільство. У цих тьмяних тунелях культисти чинять нечестиві ритуали просто під носом у розвідників Вождя."},{t="Налаштування на демонів",b="Культисти в Череп-скелі носять Пекучі Нашийники — обручі, створені, щоб палити й таврувати їхню власну плоть. За словами Марґоза, ця самокатівня — аж ніяк не бездумна жорстокість: пекуча мука й чаклунство скверни, вплавлене в метал, налаштовують носіїв на демонічну силу. Здобувши ці артефакти, Марґоз має намір розгадати точні закляття й пута, що живлять лави Палаючого Клинка."},{t="Загроза, що нависає",b="Розкриття таємниці нашийників підтверджує: присутність культу в Дуротарі свідома й організована. Палаючий Клинок — не просто розсіяні розбійники: їхнє чаклунство сягає глибоко й становить діяльну, підступну загрозу щойно заснованим землям Орди. Вивчення нашийників запускає ланцюг розслідувань, що веде просто до тіньових кіл самого Оргріммару."}},faq={{q="Де Череп-скеля?",a="Череп-скеля — прибережна печера на північному сході Дуротару, на березі на схід від Оргріммара й на північ від Села Сен'джин. Її впізнають за щербатою кручею, що обрамлює вхід.",al={"місце череп-скелі","де череп-скеля","печера череп-скеля дуротар"}},{q="Хто такі Палаючий Клинок?",a="Палаючий Клинок — небезпечний культ орків і поклонників Скверни, відданих демонічним сутностям і темній магії. Хоча нинішня Орда звільнилася від служіння демонам, відступницькі угруповання на кшталт Палаючого Клинка й далі правлять заборонені обряди, щоб із тіні роз'їдати Орду.",al={"що таке палаючий клинок","хто сектанти палаючого клинка","переказ про палаючий клинок"}},{q="Навіщо сектантам Пекучі Нашийники?",a="Сектанти носять ці розпечені металеві обручі на шиї, щоб пекти власну плоть. Марґоз підозрює, що цей обрядовий біль разом із демонічними чарами дає їм змогу спрямовувати темну енергію Скверни й налаштовуватися на неї.",al={"навіщо пекучі нашийники","чому носять пекучі нашийники","що за пекучі нашийники"}},{q="Хто такий Марґоз?",a="Марґоз — орк-відлюдник, що живе в невеликому таборі на кручах Дуротару, неподалік Череп-скелі. Він пильно стежить за пересуваннями сектантів на узбережжі й намагається зруйнувати темні задуми Палаючого Клинка.",al={"хто такий марґоз","марґоз дуротар","видавець марґоз"}},{q="Чому Орда терпить культ так близько від Оргріммара?",a="Свідомо вона його не терпить. Культ діє в глибокій таємниці, ховаючись у морських печерах і безлюдних ярах, куди звичайні патрулі рідко доходять. Шукачів пригод посилають розвідати саме тому, що сектантам вдається приховувати свої осередки, доки не почнуться їхні темні обряди.",al={"чому череп-скеля біля оргріммара","палаючий клинок біля оргріммара"}},{q="Що буде, коли Марґоз огляне нашийники?",a="Марґоз збирається оглянути Пекучі Нашийники. Розслідування триває в завданні «Ніру Файрблейд» в Оргріммарі.",al={"наступне завдання після череп-скелі","куди ведуть нашийники","закляття марґоза"}}},fp="10,347,16.438.0,18.420.0,18.403.1,28.201.0,25.286.0,49.217.0,14.217.0,56.283.0,47.119.1"}
P.entries["quest:828"] = {n="Марґоз",s="Марґоз — завдання Орди, яке доручає шукачам пригод розшукати відлюдного орка-шамана, що пильнує північні околиці Дуротару. Після сутички зі скверною в каньйоні Орґніл Соулскар посилає героїв порадитися з Марґозом, перш ніж штурмувати сусідню твердиню культистів. Мудрий відлюдник дає важливу пораду щодо тіні Палаючого Клинка, яка дедалі більшає.",h="Марґоз — завдання Орди, яке доручає шукачам пригод розшукати відлюдного орка-шамана, що пильнує північні...",kw={"марґоз","шаман","відлюдник","череп-скеля","орґніл соулскар","палаючий клинок"},ang={["class:Shaman"]="Марґоз утілює давню, терплячу мудрість шаманізму: він вартує на околицях дикої природи, щоб відчути духовне розбещення, перш ніж воно вибухне війною.",["faction:Horde"]="Застереження Марґоза висвітлює вразливість Оргріммару й доводить, що демонічні культи чаяться на відстані удару від серця Орди.",["race:Orc"]="Зустріч із Марґозом нагадує воїнам-оркам про спокусу сили скверни, що не минає, і закликає нове покоління йти чистим і чесним шляхом."},sec={{t="Варта відлюдника",b="Виявивши глибину скверни на Громовому Хребті, Орґніл Соулскар розуміє, що самої грубої сили замало, щоб очистити Дуротар. Він скеровує своїх героїв до Марґоза — досвідченого орка-шамана, що тримає самотній табір серед скель на північний схід від Гострого Пагорба. Розташувавшись між зубчастими висотами Яру Сухої Балки та східним морем, Марґоз пильнує темні знамення, які метушливі воїни Оргріммару часто не помічають."},{t="Загроза Череп-скелі",b="Марґоз володіє важливими відомостями про справжню опору Палаючого Клинка в північному Дуротарі: приховану систему печер, відому як Череп-скеля, вирубану просто в гірських кручах за південними воротами Оргріммару. Порадившись із Марґозом, подорожні дізнаються, що культисти діють значно ближче до столиці Тралла, ніж гадає сторожа Вождя. Шаман дбає, щоб той, кого пошлють очистити ковен, не ступив наосліп у демонічну засідку."}},faq={{q="Хто такий Марґоз?",a="Марґоз — мудрий орк-шаман, відданий Орді, що живе у відлюдному таборі на північному сході Дуротару. Він вивчає рух темної магії й стежить за демонічною скверною, що розповзається краєм.",al={"переказ про марґоза","хто такий марґоз","марґоз"}},{q="Де знайти Марґоза?",a="Марґоз отаборився серед порізаних пагорбів на північному сході Дуротару, між Яром Сухої Балки й східним узбережжям, трохи на південний схід від Оргріммара.",al={"місце марґоза","знайти марґоза","де марґоз"}},{q="Чому Орґніл Соулскар посилає мене до Марґоза?",a="Орґніл знає, що Марґоз довго вивчав місцевих сектантів Палаючого Клинка. Перш ніж посилати вас штурмувати їхню твердиню, Орґніл хоче, щоб ви отримали від Марґоза духовну мудрість і практичну пораду.",al={"чому говорити з марґозом","орґніл соулскар марґоз"}},{q="Що таке Череп-скеля?",a="Череп-скеля — схована гірська печера трохи на південь від східних мурів Оргріммара. Це укріплений ковен Палаючого Клинка, де демонопоклонники правлять обряди просто під носом в Орди.",al={"переказ про череп-скелю","що таке череп-скеля"}},{q="Що буде, коли знайти Марґоза?",a="Коли ви доповісте Марґозові, він визнає, що ви набралися сили, і одразу доручить вам увійти до Череп-скелі, щоб перебити сектантів і забрати їхні осквернені відзнаки.",al={"наступне завдання після марґоза","продовження марґоза"}},{q="Чи Марґоз належить до Палаючого Клинка?",a="Ні. Марґоз — відданий шаман Орди, що прагне викорінити демонічний вплив і втримати молодих поборників на шляхетному, незіпсованому шляху.",al={"чи марґоз злий","чи марґоз сектант"}}},fp="6,392,16.446.0,24.462.0,14.205.0,23.154.0,43.222.0,19.209.0,34.174.1,36.147.0"}
P.entries["quest:829"] = {n="Ніру Файрблейд",s="Це завдання веде шукачів пригод Орди від Марґоза в Дуротарі до темного підчерев'я Оргріммара. Отримавши демонічний Пекучий Нашийник, здобутий у культу Палаючого Клинка, ви вирушаєте до Ніру Файрблейда — впливового чорнокнижника з Тіньової Розколини, який запевняє, що вивчає темні мистецтва лише заради захисту Орди.",h="Це завдання веде шукачів пригод Орди від Марґоза в Дуротарі до темного підчерев'я Оргріммара.",kw={"ніру файрблейд","марґоз","пекучий нашийник","палаючий клинок","тіньова розколина","череп-скеля","шаман"},ang={["class:Shaman"]="Визнання Марґоза чітко окреслює межу між шаманізмом і демонічною магією: стихії не мають справи з артефактами Скверни, тож без допомоги чорнокнижника не обійтися.",["class:Warlock"]="Прийшовши до Тіньової Розколини по пораду Ніру Файрблейда, ви знайомитеся з найвпливовішим чорнокнижником Оргріммара — і переконуєтеся, що ваше заборонене ремесло має для Орди практичну цінність.",["faction:Horde"]="Це завдання показує хиткий мир усередині Оргріммара, де шаманам Вождя часом доводиться звертатися до темних вигнанців із Тіньової Розколини, щоб уберегти Дуротар від загибелі."},sec={{t="Межа шамана",b="Здобувши Пекучі Нашийники в культистів, що ховаються в Череп-скелі, шаман Марґоз розуміє, що розплутати їхнє мерзенне чаклунство не під силу мистецтву його предків. Шамани спілкуються з духами стихій і землею, а від цих артефактів так і тхне неприхованою демонічною скверною. Розуміючи, що збагнути пристрої Палаючого Клинка зможе лише знавець окультного, Марґоз відсилає вас розшукати чорнокнижника, що живе в столиці."},{t="До Тіньової Розколини",b="Під червоними кручами Оргріммара лежить Тіньова Розколина — тьмяно освітлена печера, де майстри забороненої магії займаються своїм ремеслом під насторожливим оком Тралла. Там живе Ніру Файрблейд, впливовий орк-чорнокнижник, який запевняє, що опановує силу Скверни лише для того, щоб відбивати демонічні загрози. Нашийник-зразок одразу розпалює його цікавість — і розслідування діяльності культу в Дуротарі переноситься просто в серце громади чорнокнижників."}},faq={{q="Чому Марґоз посилає мене до чорнокнижника?",a="Марґоз — шаман, чия сила походить від стихій і духів предків. Пекучі Нашийники, забрані з Череп-скелі, мають суто демонічну природу, а щоб розгадати їхні чари й походження, потрібен той, хто навчений магії Скверни й темним мистецтвам.",al={"чому чорнокнижник","чому ніру","марґоз чорнокнижник"}},{q="Де знайти Ніру Файрблейда?",a="Ніру Файрблейд — у Тіньовій Розколині, підземному лабіринті печер під Оргріммаром, де збираються чорнокнижники, розбійники й тіньові заклиначі.",al={"місце ніру","де ніру файрблейд","ущелина тіней ніру"}},{q="Чи можна довіряти Ніру Файрблейду?",a="Сам Марґоз має сумніви: він зауважує, що Ніру запевняє, ніби його окультні пошуки нешкідливі й служать лише боротьбі з демонами, але правда це чи ні — ще побачимо. Тралл дозволяє чорнокнижникам бути в Оргріммарі під суворим наглядом, проте обережність не завадить.",al={"чи ніру злий","чи ніру надійний","чи можна довіряти файрблейду"}},{q="Що таке Зразковий Нашийник?",a="Зразковий Нашийник — один із Пекучих Нашийників, забраних у сектантів Палаючого Клинка в Череп-скелі. Марґоз дає його вам, щоб ви віднесли просто Ніру Файрблейду для магічного дослідження.",al={"зразковий нашийник","що за нашийник","предмет пекучий нашийник"}},{q="Що буде, коли віддати нашийник Ніру?",a="Ніру уважно оглядає нашийник, і це веде до завдання «Ак'Зелот», у якому він посилає вас глибше розслідувати тіньову присутність культу в Дуротарі.",al={"наступне завдання після ніру","що робить ніру","ланцюжок після ніру"}},{q="Чому Орда терпить чорнокнижників в Оргріммарі?",a="Вождь Тралл терпить чорнокнижників із практичної потреби: він тримає їх у підземній Тіньовій Розколині, щоб їхні небезпечні пошуки були під наглядом і контролем, а часом і допомагали зрозуміти демонічних ворогів.",al={"чому чорнокнижників терплять","чорнокнижники в ущелині тіней","тралл і чорнокнижники"}}},fp="15,317,17.439.0,24.451.0,37.267.0,33.151.0,31.258.0,27.185.0,46.160.0,47.234.0"}
P.entries["quest:83"] = {n="Червоні лляні вироби",s="«Червоні лляні вироби» — завдання в Лісі Елвінн від швачки Сари Тімберлейн, чия майстерня — Лісозаготівельний Табір Східної Долини. Їй потрібна тканина, тож вона просить шукачів пригод, що проходять повз, полювати на місцевих бандитів Дефіас і знімати з них лляні бандани. Навзамін із повернутої тканини вона шиє корисні речі для мандрівників.",h="«Червоні лляні вироби» — завдання в Лісі Елвінн від швачки Сари Тімберлейн, чия майстерня — Лісозаготівельний...",kw={"червоні лляні вироби","сара тімберлейн","бандани","дефіас","кравецтво","східна долина"},ang={["faction:Alliance"]="Зачистка бандитів Дефіас, що заполонили гаї Елвінну, не лише дає Східній Долині корисну здобич, а й реально послаблює хватку Братства на серці королівства.",["profession:Tailoring"]="Ремесло Сари Тімберлейн показує сувору правду сільського кравецтва: сувоїв тканини бракує, і місцевим швачкам доводиться знімати полотно просто зі спин місцевих бандитів."},sec={{t="Бандити й мішковина",b="Якщо дрібні розбійники Дефіас, що зчиняють сутички в Долині Нортширу, обходяться дешевими масками з мішковини, то організовані злочинці, які никають рештою Лісу Елвінн, носять добірніші бандани з багряного льону. Для місцевих ремісників, яким бракує сировини, ці знаки банди — напрочуд практичне джерело придатної тканини."},{t="Здобич у таборі",b="Сара Тімберлейн працює там, де гуде Лісозаготівельний Табір Східної Долини, біля східного кордону Елвінну, і завжди шукає придатні тканини. Заохочуючи шукачів пригод проріджувати табори Дефіас, сховані по лісах, вона забезпечує своє кравецьке ремесло сировиною й водночас допомагає стримати зухвалий наступ Братства."}},faq={{q="Хто дає завдання «Червоні лляні вироби»?",a="Це завдання дає Сара Тімберлейн, місцева швачка з Лісозаготівельного Табору Східної Долини на сході Лісу Елвінн.",al={"хто дає червоні лляні вироби","видавець червоних лляних виробів","завдання сари тімберлейн"}},{q="Що потрібно для завдання «Червоні лляні вироби»?",a="Треба зібрати 6 червоних лляних бандан, які можна зняти з бандитів Дефіас, розкиданих по всьому Лісу Елвінн.",al={"що збирати для червоних лляних виробів","предмети червоних лляних виробів","потрібні бандани"}},{q="Де в Лісі Елвінн знайти бандитів Дефіас?",a="Розбійники Дефіас живуть у невеликих таборах, розкиданих по Лісу Елвінн, зокрема довкола Гарбузової Ділянки Брекуеллів, Ферми Стоунфілдів і в лісі біля Пристані Джерода.",al={"місця дефіас в елвінні","де табори дефіас","де взяти червоні бандани"}},{q="Чому Дефіас в Елвінні носять льон, а не мішковину?",a="За словами Сари Тімберлейн, рядові Дефіас у Нортширі носять грубі маски з мішковини, а краще споряджені члени, що діють по всьому Елвінну, — червоний льон: це знак вищого рівня організації й постачання в Братстві.",al={"чому червоний льон","мішковина чи льон дефіас","матеріал масок дефіас"}},{q="Навіщо Сарі Тімберлейн бандитські бандани?",a="Сарі бракує тканини для кравецтва. Льон із масок Дефіас, який можна відпрати, вона пускає на практичні речі для лісорубів і мандрівників у таборі.",al={"навіщо збирати бандани","що сара робить з масками"}},{q="Де Лісозаготівельний Табір Східної Долини?",a="Лісозаготівельний Табір Східної Долини — на крайньому сході Лісу Елвінн, трохи на північ від головної дороги, що веде до мосту в Гори Редріджу.",al={"місце східної долини","де східна долина","як знайти сару тімберлейн"}}},fp="15,310,18.315.0,19.337.0,37.120.0,42.122.0,49.185.0,54.246.0,46.182.0,43.142.0"}
P.entries["quest:830"] = {n="Накази адмірала",s="Здобуті із замкненої скрині на вершині Фортеці Тіраґард, ці потерті папери несуть особисту печатку покійного великого адмірала Дейліна Праудмура. Знайдені накази відкривають, що людський гарнізон Кул Тірасу на узбережжі Дуротару значно глибше окопався й краще організований, ніж прості вцілілі з кораблетрощі. Доставка їх Ґар'Току в Гострий Пагорб викриває приховані військові плани, що загрожують молодій державі орків.",h="Здобуті із замкненої скрині на вершині Фортеці Тіраґард, ці потерті папери несуть особисту печатку покійного...",kw={"накази","праудмур","фортеця тіраґард","ґар'ток","кул тірас","бенедикт"},ang={["faction:Horde"]="Викриті накази Праудмура доводять, що присутність Альянсу на берегах Дуротару була спланованою кампанією винищення, і зайвий раз пояснюють, чому Орда має пильно боронити свій новий дім.",["race:Orc"]="Для орків, що борються за майбутнє в Дуротарі, ці документи — суворе нагадування про невгамовну ненависть Дейліна Праудмура й про недобитків, які досі прагнуть їх знищити."},sec={{t="Запечатаний спадок",b="Схований у важкій скрині на верхніх поверхах Фортеці Тіраґард, старий конверт уцілів під наглядом лейтенанта Бенедикта. Запечатаний гербом великого адмірала Дейліна Праудмура, пергамент містить прямі морські накази, видані під час кривавого вторгнення Кул Тірасу в Дуротар. Навіть після того, як великий адмірал поліг у Тераморі, його офіцери тримали укріплення, вперто чіпляючись за свою місію — винищити поселення Орди."},{t="Тривога в Гострому Пагорбі",b="Доставка знайдених документів Ґар'Току, командирові Гострого Пагорба, підтверджує найгірші побоювання тутешніх захисників. Люди, що окопалися вздовж східного узбережжя, — не безцільні викинуті на берег моряки, а усталений плацдарм, що чекає підкріплення. Ґар'Ток одразу усвідомлює: зруйнувати командування Тіраґарду — невідкладна справа виживання Дуротару."}},faq={{q="Де знайти Накази адмірала?",a="Накази лежать у Пожовклому Конверті в замкненій скрині на третьому поверсі Фортеці Тіраґард у Дуротарі. Щоб відімкнути скриню, спершу треба здолати Лейтенанта Бенедикта на другому поверсі й забрати в нього ключ.",al={"місце наказів адмірала","де конверт","знайти накази адмірала"}},{q="Ким був Адмірал Праудмур?",a="Великий Адмірал Дейлін Праудмур — правитель Кул Тірасу й верховний командувач морського флоту Альянсу в Другій війні. Не вірячи, що орки колись зможуть жити мирно, він приплив до Калімдору, щоб вести проти Дуротару війну на знищення, і загинув у Тераморі.",al={"хто адмірал","переказ про дейліна праудмура","хто видав накази"}},{q="Чому вояки Кул Тірасу досі у Фортеці Тіраґард?",a="Вторгнувшись у Дуротар, Дейлін Праудмур заснував укріплені прибережні плацдарми на кшталт Фортеці Тіраґард. Після його поразки вцілілі офіцери й морські піхотинці під проводом Лейтенанта Бенедикта лишилися на своїх постах, налаштовані продовжувати його похід проти Орди.",al={"чому люди кул тірасу в дуротарі","вояки тіраґарда","кул тірас у дуротарі"}},{q="Чому Ґар'Тока так непокоять ці накази?",a="Як військовий командир Гострого Пагорба, Ґар'Ток мусить берегти центральний Дуротар. Знайдені впорядковані морські накази доводять, що Фортеця Тіраґард — діяльна, продумана військова загроза батьківщині орків, а не розгублені вцілілі, що застрягли на березі.",al={"реакція ґар'тока","чому ґар'ток переймається"}},{q="У кого ключ від скрині адмірала?",a="Ключ, потрібний, щоб відімкнути скриню з Пожовклим Конвертом, носить Лейтенант Бенедикт, командир Кул Тірасу на другому поверсі Фортеці Тіраґард.",al={"ключ бенедикта","хто має ключ"}},{q="Що буде, коли віддати накази Ґар'Току?",a="Переглянувши накази, Ґар'Ток розуміє нагальну стратегічну небезпеку й наказує діяти далі: знешкодити решту людського проводу й зруйнувати їхні задуми в Дуротарі.",al={"що далі з наказами адмірала","наступне завдання"}}},fp="20,412,15.452.0,19.385.1,37.221.0,27.293.0,51.255.0,48.265.0,41.180.0,49.194.0"}
P.entries["quest:8311"] = {n="Ласощі Кануна Дня всіх святих для Джеспера!",s="На Переддень Усіх Святих юний сирота Джеспер лежить хворий у сиротинці Стормвінда й мріє долучитися до святкових забав. Він надто слабкий, щоб вийти надвір, тож просить шукачів пригод з Альянсу обійти світ і зібрати ласощі замість нього.",h="На Переддень Усіх Святих юний сирота Джеспер лежить хворий у сиротинці Стормвінда й мріє долучитися до...",kw={"джеспер","переддень усіх святих","ласощі","сиротинець","талваш дель кіссель","стормвінд"},ang={["faction:Alliance"]="Ця святкова справа поєднує далекі столиці: героям доводиться мандрувати від величних вулиць Стормвінда до гірських залів Айронфорджа й гілля Дарнасуса, щоб потішити дитину-сироту.",["race:Gnome"]="Відколи гноми втратили свій дім через трогів і радіацію, участь вашого народу у святі тримається на Талваші Дель Кісселі в Айронфорджі — він дбає, щоб Желейки з Гномреґана й далі діставалися всім."},sec={{t="Дитина під опікою",b="Джеспер живе в сиротинці на Соборній Площі Стормвінда, і цього Переддня Усіх Святих він захворів. Позбавлений простої дитячої радості — збирати солодощі з усього Азерота, — Джеспер сидить у чотирьох стінах і сподівається, що мандрівні шукачі пригод перейняться святковим духом і назбирають ласощів замість нього."},{t="Витівки за ласощі по всьому Альянсу",b="Щоб зібрати святковий частунок, про який мріє Джеспер, шукачеві пригод доведеться вирушити далеко за межі Лісу Елвінн. Завдання вимагає навідати корчмарів Стормвінда, Айронфорджа й Дарнасуса, а також гнома-вигнанця Талваша Дель Кісселя. Кожен дорослий хоче вистави, перш ніж віддати свій гостинець: мандрівникам доводиться кудкудакати, як кури, танцювати, хизуватися м'язами чи пихкати, як потяг, — в обмін на місцеві ласощі, як-от Нугу зі Стормвінда та Желейки з Гномреґана."}},faq={{q="Хто такий Джеспер?",a="Джеспер — маленький сирота з притулку Стормвінда. На Переддень Усіх Святих йому дуже хочеться святкових солодощів, але він надто хворий, щоб піти по них сам.",al={"джеспер стормвінд","сирота джеспер","хто такий джеспер"}},{q="Чому Джеспер не може сам піти колядувати по солодощі?",a="Джеспер хворий, і недуга тримає його в притулку, поки все місто святкує Переддень Усіх Святих.",al={"чому джеспер не може піти","чи джеспер хворий","джеспер солодощі"}},{q="Яких ласощів хоче Джеспер?",a="Він просить чотири різні місцеві солодощі: Нугу зі Стормвінда, М'ятні Льодяники із Залізокузні, Марципан із Дарнасуса й Мармеладку з Гномреґану.",al={"ласощі джеспера","список ласощів кануна дня всіх святих","які цукерки потрібні"}},{q="Де взяти Мармеладку з Гномреґану?",a="Гномреґан досі заражений і захоплений ворогами, тож мармеладку роздає гном-біженець Талваш Дель Кіссель, що зараз живе в Кварталі містиків Айронфорджа.",al={"мармеладка з гномреґану","де мармеладка","цукерка талваша"}},{q="Які витівки змушують робити корчмарі?",a="За солодощі корчмарі вимагають кумедних витівок: напружити м'язи в Стормвінді, потанцювати в Дарнасусі, покудкудакати, як курка, в Айронфорджі й погудіти, як потяг, для Талваша.",al={"витівки корчмарів","витівки заради ласощів","ласощі альянсу за витівки"}},{q="Що Джеспер дає натомість за солодощі?",a="Отримавши всі чотири святкові ласощі, Джеспер радо віддає мандрівникові гарбузові смаколики, які приберіг.",al={"нагорода джеспера","завершення ласощів джеспера"}}},fp="31,240,17.293.0,37.450.0,14.156.0,46.114.0,30.127.0,43.170.0,47.187.0,50.131.0"}
P.entries["quest:832"] = {n="Палаючі тіні",s="Здобутий у культиста Палаючого Клинка Ґазз'уза в глибинах Череп-скелі, цей загадковий сяйливий кулон шепоче в розум носія настійливі застереження. Голос відверто погрожує Ґазз'узу гнівом Ніру Файрблейда — орка-чорнокнижника, що живе в Оргріммарі.",h="Здобутий у культиста Палаючого Клинка Ґазз'уза в глибинах Череп-скелі, цей загадковий сяйливий кулон шепоче в...",kw={"око палаючої тіні","ґазз'уз","ніру файрблейд","палаючий клинок","череп-скеля","кулон"},ang={["class:Warlock"]="Для чорнокнижника, що навчається в Тіньовій Розколині, почути, як Палаючий Клинок згадує ім'я іншого практика, — суворе нагадування про те, яка тонка межа між дозволеним державою вивченням скверни та відкритою зрадою.",["faction:Horde"]="Викриті перешіптування культистів одразу за воротами столиці показують, що демонічне розбещення Старої Орди досі гноїться тривожно близько до серця Дуротару.",["race:Orc"]="Орки, що билися пліч-о-пліч із Траллом, щоб очиститися від скверни Легіону, бачать у присутності Палаючого Клинка в Дуротарі нестерпне осквернення своєї нової батьківщини."},sec={{t="Голос у камені",b="Після вбивства Ґазз'уза глибоко в Череп-скелі з його останків дістають зловісний кулон, відомий як Око Палаючої Тіні. Це не мертва магічна дрібничка: камінь тремтить від думкомови. Владний голос промовляє просто в розум кожного, хто його тримає, вимагаючи звітів від Ґазз'уза й попереджаючи, що його таємні справи на схід від Оргріммару викрито."},{t="Дивна погроза",b="Що заскочує зненацька будь-якого вірного розвідника Орди, то це відчайдушний ультиматум голосу: відповідай, інакше Ніру Файрблейда повідомлять, щоб він вистежив Ґазз'уза зі швидкою жорстокістю. Ніру Файрблейд відкрито живе в Тіньовій Розколині Оргріммару, нібито практикуючи темні мистецтва під суворим наглядом Тралла. Коли талісман приносять Ніру, той удає подив і цікавість, дивуючись, що його ім'ям лякали культистів, наче страховиськом."}},faq={{q="Що таке Око Палаючої Тіні?",a="Око Палаючої Тіні — зачарований кулон, що падає з ватажка Палаючого Клинка Ґазз'уза в Череп-скелі. Він слугує двобічним телепатичним зв'язком між посланцями культу та їхніми незримими володарями.",al={"око палаючої тіні","що за кулон","око ґазз'уза"}},{q="Хто говорить через кулон?",a="Якийсь невідомий старший із Ради Тіней чи ієрархії Палаючого Клинка намагається зв'язатися з Ґазз'узом, не знаючи, що сектанта вже вбито в Череп-скелі.",al={"хто говорить із кулона","хто говорив зі мною","голос у кулоні"}},{q="Чому голос погрожує Ґазз'узові Ніру Файрблейдом?",a="Голос заявляє, що Ніру Файрблейд жорстоко розправиться з Ґазз'узом, якщо той не доповість. На перший погляд, це подає Ніру як грізного відданого кара Тралла, але знайомство культу з Ніру натякає на глибші підводні течії.",al={"чому згадано ніру","загроза ніру файрблейда","зв'язок з ніру"}},{q="Куди віднести Око Палаючої Тіні?",a="Віднесіть кулон Ніру Файрблейду, якого можна знайти над казанами й фоліантами глибоко в Тіньовій Розколині в Оргріммарі.",al={"куди здати палаючі тіні","де ніру файрблейд"}},{q="Як реагує Ніру Файрблейд, отримавши око?",a="Ніру вдає, ніби нічого не знає, і дивується, чому сектанти згадують його ім'я. Він бере кулон нібито для того, щоб вивчити його магію й з'ясувати, чому Палаючий Клинок має назву, таку схожу на назву його власного клану.",al={"реакція ніру","що каже ніру"}},{q="Де знайти Ґазз'уза?",a="Ґазз'уз чатує в найглибшому кутку Череп-скелі — печери, схованої серед круч на східному узбережжі Дуротару, трохи на схід від Оргріммара.",al={"де ґазз'уз","місце ґазз'уза","бос череп-скелі"}}},fp="15,272,20.410.0,16.454.1,34.200.0,36.174.0,57.252.0,42.134.0,50.210.1,25.136.0"}
P.entries["quest:833"] = {n="Священне поховання",s="«Священне поховання» — завдання від Хранителя Знань Рейнтотема, що доручає шукачам пригод Орди захистити Червоні Скелі у східному Малгорі. Священне поховання предків заполонили мародери — шипогриви-Щетиноспини, які плюндрують могили шанованих воїнів-тауренів. Вигнання цих зайд повертає честь і спокій тим, хто віддав життя, засновуючи й боронячи Тандер Блаф.",h="«Священне поховання» — завдання від Хранителя Знань Рейнтотема, що доручає шукачам пригод Орди захистити...",kw={"священне поховання","червоні скелі","хранитель знань рейнтотем","шипогриви","щетиноспини","предки","малгор"},ang={["class:Shaman"]="Споганення священної землі збурює духів шанованих предків, тож ваше втручання потрібне, щоб повернути землі рівновагу.",["faction:Horde"]="Допомога тауренським старійшинам в убезпеченні їхніх священних пам'яток скріплює обітницю Орди боронити Малгор разом із союзниками.",["race:Tauren"]="Захист Червоних Скель — справа глибокої честі перед предками: воїни, завдяки яким ваш народ здобув об'єднану батьківщину, мають спочивати непотривоженими."},sec={{t="Святиня шу'хало",b="Червоні Скелі — одна з найшанованіших святинь усього Малгору. Схована серед бескидів під східними горами, це місце останнього спочинку, призначене лише для найдоблесніших тауренів. Поховані тут герої — легендарні воїни, що проливали кров, захищаючи свої племена, підтримуючи вождів і здобуваючи постійну батьківщину на плато Тандер Блафа. Для шу'хало потривожити їхній спокій — образа не лише традиції, а й самої Земної Матері."},{t="Споганення Щетиноспинами",b="Кочові шипогриви племені Щетиноспинів уперто заперечують владу тауренів над центральним Калімдором, але їхнє нещодавнє вторгнення до Червоних Скель — серйозне загострення. Ватаги зайд-Щетиноспинів прокралися на святу землю, розриваючи ґрунт і тривожачи місця спочинку. Оскільки сторож Хранитель Знань Рейнтотем надто старий, щоб самотужки вигнати нападників, молоді звитяжці Орди мають узятися до зброї, очистити святиню від зайд і захистити шанованих мертвих."}},faq={{q="Що таке Червоні Скелі?",a="Червоні Скелі — священний цвинтар предків у східних горах Малгора. Його відведено саме для найзвитяжніших воїнів-тауренів, особливо тих, хто загинув, захищаючи свої племена й засновуючи Тандер Блаф.",al={"де червоні скелі","червоні скелі мулґор","поховання тауренів"}},{q="Хто такий Хранитель Знань Рейнтотем?",a="Хранитель Знань Рейнтотем — старий таурен, якому доручено доглядати й берегти священну землю Червоних Скель. Розуміючи, що його найкращі роки минули й сам він не відіб'є Щетиноспинів, він кличе вправних шукачів пригод захистити мертвих.",al={"рейнтотем","хранитель знань рейнтотем","хто дає священне поховання"}},{q="Що шипогриви Щетиноспини роблять на Червоних Скелях?",a="Плем'я Щетиноспинів безупинно тисне на землі тауренів по всьому Малгору й Пустках. Відчайдушно прагнучи земель і ресурсів, ватаги загарбників вдерлися на кручі Червоних Скель і при цьому осквернили могили.",al={"чому вепролюди на червоних скелях","нападники щетиноспини","вторгнення вепролюдів"}},{q="Чому ця наруга така образлива для тауренів?",a="Таурени надзвичайно шанують предків і прагнуть жити в злагоді з духами полеглих. Дозволити диким шипогривам плюндрувати землю й тривожити кістки героїв, що загинули за Тандер Блаф, — глибока духовна образа.",al={"поховальні звичаї тауренів","чому таурени дбають про поховання"}},{q="Куди веде це завдання далі?",a="«Священне поховання» — окреме оборонне доручення від Хранителя Знань Рейнтотема. Коли з загарбниками Щетиноспинами покінчено, наругу зупинено, хоча інші завдання на Червоних Скелях заглиблюються в духовний неспокій серед круч.",al={"продовження священного поховання","що після священного поховання"}},{q="Хто похований на Червоних Скелях?",a="Тут ховають видатних тауренів, що боролися за виживання своїх племен і вождів, — особливо тих, чиї жертви уможливили заснування й оборону Тандер Блафа.",al={"хто тут похований","могили червоних скель"}}},fp="15,401,31.497.0,27.505.0,18.233.0,28.262.0,46.243.0,51.257.0,32.248.0,27.196.0"}
P.entries["quest:834"] = {n="Вітри в пустелі",s="Резлаку, інженерові, найнятому з підприємств Ґазлоу, потрібна допомога: гарпії в Дуротарі вкрали важливі будівельні матеріали. Караван, що прямував до Оргріммару, потрапив у засідку в Каньйоні Гострого Вітру, і мішки з припасами розкидало по скелях.",h="Резлаку, інженерові, найнятому з підприємств Ґазлоу, потрібна допомога: гарпії в Дуротарі вкрали важливі...",kw={"резлак","гарпії","каньйон гострого вітру","припаси","ґазлоу","караван"},ang={["faction:Horde"]="Кожен вантаж, утрачений через звірів каньйону, загрожує швидкому розширенню й укріпленню твердині Орди в Дуротарі.",["profession:Engineering"]="Резлак утілює практичну винахідливість інженерів картелю Стімвідл, яких значно більше хвилюють креслення й вчасні поставки, ніж клопоти з місцевою живністю.",["race:Orc"]="Орки покладаються на гоблінський досвід і чужоземні припаси, щоб перетворити суворий, сухий ґрунт Дуротару на укріплену батьківщину."},sec={{t="Гоблін і терміни",b="Резлака послав сам Головний Інженер Ґазлоу з Раджета — допомагати Орді з її зухвалими будівельними проєктами по всьому Дуротарі. Зводити укріплення на суворій, пустельній землі й без того важко, не кажучи вже про провали постачання, та вантажі Резлака раз у раз зникають, не дійшовши до будівництв. Без важливого вантажу вся робота стає, і дратівливий гоблін-наглядач лишається без нічого, з чого можна будувати."},{t="Засідка в каньйоні",b="Останній життєво важливий вантаж, обіцяний Резлакові, перехопили гарпії Пилового Вітру, що живуть у Каньйоні Гострого Вітру. Ці крилаті падложерки гніздяться на високих уступах ущелини обабіч дороги між Гострим Пагорбом і Оргріммаром і пікірують на необережні вози. Замість з'їсти чи знищити вантаж, гарпії складають ящики й мішки довкола своїх гнізд, залишаючи його цілим для кожного, кому стане відваги пробитися на їхню територію."}},faq={{q="Хто такий Резлак?",a="Резлак — гоблін-робітник, найманий Ґазлоу, босом Раджета. Ґазлоу послав його до Дуротару допомагати оркам із будівництвом під брамою Оргріммара.",al={"резлак","хто такий резлак","хто дав завдання"}},{q="Чому гобліни допомагають будувати в Дуротарі?",a="Ґазлоу й картель Стімвідл мають із Вождем Траллом давнє торгове й інженерне партнерство. Гоблінські інженери й машини допомогли закласти підвалини Оргріммара, і Ґазлоу досі постачає Орді найманих робітників і матеріали за договором.",al={"чому гобліни допомагають орді","газлоу дуротар","співпраця гоблінів і орди"}},{q="Звідки взялися припаси?",a="Резлак не каже, звідки вантаж. Він лише пояснює, що це припаси, доставлені караваном, — потрібні для його роботи на допомогу оркам у Дуротарі.",al={"звідки припаси","звідки караван"}},{q="Що гарпії роблять у Дуротарі?",a="Гарпії Курного Вітру — агресивні хижі падальниці, що кишать на кручах і в ярах центрального Дуротару. Вони дошкуляють мандрівникам, грабують торгові обози в Каньйоні Гострого Вітру й тягнуть до гнізд усе блискуче чи корисне.",al={"чому гарпії в дуротарі","гарпії пилового вітру","гарпії гострого вітру"}},{q="Де Каньйон Гострого Вітру?",a="Каньйон Гострого Вітру відгалужується просто від головної південної ущелини, що з'єднує Оргріммар із Гострим Пагорбом. Яри врізаються і в східну, і в західну скельні стіни, утворюючи високі гнізда, де гарпії Курного Вітру ховають украдений вантаж.",al={"місце каньйону гострого вітру","де припаси","місце мішків з припасами"}},{q="Чому вартові-орки не вберегли караван?",a="Резлак каже, що каравани важко вберегти й що цей вантаж обіцяли доставити неодмінно. Він не пояснює, яка варта його супроводжувала і чому вона не встояла проти гарпій Курного Вітру.",al={"чому караван не вберегли","безпека дуротару","орківські каравани"}}},fp="19,251,22.451.0,20.454.0,14.186.0,41.264.0,33.151.0,38.234.0,34.233.0,46.215.0"}
P.entries["quest:835"] = {n="Убезпечити шляхи",s="Убезпечити шляхи — завдання, яке дає Резлак біля Каньйону Гострого Вітру, щоб захистити важливі гоблінські шляхи постачання через Дуротар. Гарпії, що гніздяться в Яру Сухої Балки, невпинно перехоплюють і грабують каравани, тож роздратований гоблін наймає бійців, щоб їх вибити.",h="Убезпечити шляхи — завдання, яке дає Резлак біля Каньйону Гострого Вітру, щоб захистити важливі гоблінські...",kw={"резлак","гарпії","яр сухої балки","каньйон гострого вітру","каравани","постачання"},ang={["faction:Horde"]="Усунення загрози гарпій у східній частині Каньйону Гострого Вітру зберігає потік товарів і підкріплень між прикордонними заставами Дуротару й прибережними торговими осередками.",["profession:Engineering"]="Захист вантажів Резлака дбає, щоб новітні гоблінські деталі й далі йшли з Раджета до рук місцевих інженерів."},sec={{t="Шлях, обсаджений гарпіями",b="Сухі долини Дуротару й так суворі, а тут ще й агресивні гарпії пікірують на необережних подорожніх. Гоблін Резлак, що працює на свого боса Ґазлоу, наглядає за постачанням у краї. На жаль, гарпії Пилового Вітру, що оселилися в Яру Сухої Балки, перетворили Каньйон Гострого Вітру на смертельну пастку: вони регулярно грабують каравани й захоплюють вантажі, перш ніж ті дійдуть до мети."},{t="Справа й кров",b="Резлак живе за гоблінським правилом: за належну ціну можна зробити що завгодно. Замість самому лізти в каньйон, він наймає шукачів пригод зламати хребет гніздовищу, винищивши дикунок Пилового Вітру та штормових відьом Пилового Вітру. Очищення від гарпій тримає торгові коридори відкритими, убезпечує поставки інженерних пристроїв і вказує корисним подорожнім на більші можливості в Раджеті."}},faq={{q="На кого працює Резлак?",a="Резлак працює на Ґазлоу — головного інженера й боса нейтрального гоблінського порту Раджет. Ґазлоу керує великими торговими й будівельними справами по всьому Дуротару й Пустках.",al={"бос резлака","на кого працює резлак","роботодавець резлака"}},{q="Чому гарпії нападають на каравани?",a="Гарпії Курного Вітру звили велике гніздовище в Яру Сухої Балки, що тягнеться просто вздовж головних шляхів через Каньйон Гострого Вітру. Вони люто кидаються на непроханих гостей і грабують вози й товари, що проходять поблизу.",al={"чому гарпії нападають","мотив гарпій пилового вітру","чому яр сухої балки"}},{q="Де Яр Сухої Балки?",a="Яр Сухої Балки ховається глибоко в східній частині Каньйону Гострого Вітру на півночі Дуротару, врізаний у посушливі багряні пагорби.",al={"місце яру сухої балки","де яр сухої балки","як знайти суху балку"}},{q="Що буде, коли допомогти Резлакові?",a="Коли гарпій Курного Вітру поменшає, а шлях постачання вбезпечено, Резлак скеровує шукачів пригод до Раджета за кордоном, у Пустках, і радить звернутися до Ґазлоу по нові вигідні угоди.",al={"після убезпечення шляхів","продовження резлака","що після резлака"}},{q="Чому гарпіями займаються гобліни, а не Орда?",a="Орда має застави в Дуротарі, але її сили розпорошені на кентаврів, шипогривів і потреби власних поселень. Гоблінським купцям на кшталт Резлака часто швидше й дешевше найняти незалежних шукачів пригод, щоб ті захистили їхню приватну справу.",al={"чому наймають гоблінів","чому оргріммар не займається","орда і гарпії"}},{q="Які гарпії живуть у Яру Сухої Балки?",a="Гніздовище складається переважно з диких дикунок Курного Вітру, що б'ються впритул, і відьом бурі Курного Вітру, що спрямовують вітер і блискавки на каравани, які наважуються туди сунутися.",al={"види гарпій","види гарпій пилового вітру","вороги сухої балки"}}},fp="18,283,26.418.0,22.418.0,26.197.0,39.239.0,33.139.0,34.208.0,60.281.0,48.169.0"}
P.entries["quest:8353"] = {n="Кудкудак за льодяник",s="Кудкудак за льодяник — жартівливе сезонне завдання Альянсу, яке можна отримати в Айронфорджі на Переддень Усіх Святих. Щоб здобути традиційний М'ятний Льодяник із Залізокузні для маленького сироти Джеспера, шукачам пригод доведеться забути про загартовану в боях гідність: махати руками й кудкудакати, як курка, на втіху відвідувачам таверни. Шинкар Файрбрю охоче винагороджує кожного, хто проковтне гордість, аби подарувати дитині свято.",h="Кудкудак за льодяник — жартівливе сезонне завдання Альянсу, яке можна отримати в Айронфорджі на Переддень...",kw={"переддень усіх святих","джеспер","шинкар файрбрю","м'ятний льодяник","курка","айронфордж"},ang={["faction:Alliance"]="Це сезонне доручення показує товариство столиць Альянсу: дворфійська гостинність Айронфорджа допомагає звеселити осиротілу дитину в Стормвінді.",["race:Dwarf"]="Дворфи цінують добрий жарт, міцний напій і святкові традиції, а вимога Файрбрю доводить: жоден завсідник Айронфорджа не сприймає себе аж надто серйозно."},sec={{t="Традиція Переддня Усіх Святих",b="На Переддень Усіх Святих по всьому Азероту панує піднесений настрій: народи відзначають межу між жнивами й зимою маскарадними гуляннями та святковими ласощами. Бувалі герої зазвичай вважають себе застарими, щоб ходити від дверей до дверей і випрошувати цукерки, але біда хворих чи осиротілих дітей — шляхетна причина. У Стормвінді малий Джеспер мріє про святкові солодощі, і поборники Альянсу збирають для нього знамениті місцеві ласощі в шинкарів по всіх столицях Альянсу."},{t="Ціна Шинкаря Файрбрю",b="За шинквасом гамірної айронфорджської таверни стоїть Шинкар Файрбрю, охоронець славетних М'ятних Льодяників із Залізокузні. Він нікому не дає легко відбутися й не віддасть ласощі лише на прохання. Він вимагає розваги: загартовані воїни й незворушні чарівники мусять махати руками й кудкудакати, як домашня птиця, перш ніж отримають нагороду. Усе це — заради святкових веселощів, щоб відвідувачі таверни могли добряче посміятися з героя."}},faq={{q="Чому Шинкар Файрбрю хоче, щоб я кудкудакав, як курка?",a="Шинкар Файрбрю перейнявся грайливим духом Переддня Усіх Святих. Досвідчені шукачі пригод надто дорослі, щоб просто ходити по солодощі, тож він вимагає кумедної витівки, перш ніж віддати ласощі. Вважаючи, що могутній поборник, який махає руками й кудкудаче, — чудова розвага для шинку, він радо міняє М'ятний Льодяник із Залізокузні на трохи привселюдного сорому.",al={"чому кудкудакати","причина курки файрбрю","чому я маю кудкудакати"}},{q="Хто такий Джеспер і чому я збираю для нього льодяники?",a="Джеспер — хворий сирота в Стормвінді, який не може сам узяти участь у святкуваннях Переддня Усіх Святих у місті. Щоб потішити його, шукачі пригод Альянсу виконують святкові доручення по всьому світу й збирають чотири особливі святкові солодощі з кожного великого міста Альянсу, зокрема хрусткий М'ятний Льодяник із Залізокузні з Дун Мороґа.",al={"хто такий джеспер","чому збирати льодяники","сирота джеспер"}},{q="Яке місце це завдання посідає у святі Переддня Усіх Святих?",a="Це одне з чотирьох місцевих доручень, пов'язаних із загальним святковим завданням «Ласощі Переддня Усіх Святих для Джеспера!», поряд із проханнями корчмарів Стормвінда й Дарнасуса та Талваша Дель Кісселя в Айронфорджі. Кожен із них вимагає певної кумедної чи театральної витівки, перш ніж віддати фірмові солодощі свого міста.",al={"ланцюжок переддня всіх святих","ланцюжок цукерок джеспера","порядок завдань"}},{q="Де знайти Шинкаря Файрбрю?",a="Шинкар Файрбрю стоїть за шинквасом біля вогнища в Таверні «Кам'яний Вогонь» у Громадській Залі Айронфорджа: наливає напої й дає притулок мандрівникам у самому серці столиці дворфів.",al={"де файрбрю","місце файрбрю","корчмар айронфорджа"}},{q="Що я отримаю за кудкудакання?",a="Коли ви покудкудачете, Шинкар Файрбрю дасть вам М'ятний Льодяник із Залізокузні — святкову цукерку, яку можна здобути лише під час свята й яку треба віднести до Стормвінда, щоб скласти Джесперові набір ласощів на Переддень Усіх Святих.",al={"нагорода завдання","що за льодяник","льодяник айронфорджа"}},{q="Чи можуть гравці Орди виконати це доручення?",a="Ні, це завдання лише для Альянсу. У шукачів пригод Орди є свій відповідник — сирота Спупс, що посилає поборників по столицях Орди збирати солодощі в корчмарів Оргріммара, Андерсіті й Тандер Блафа.",al={"чи це лише для альянсу","завдання з куркою орда","чи орда може це"}}},fp="27,441,24.481.0,26.479.0,60.373.0,49.311.0,56.337.0,36.186.0,31.185.0,37.240.0"}
P.entries["quest:8354"] = {n="Кудкудакання за льодяник",s="У святкову пору Переддня Усіх Святих Корчмар Норман з Андерсіті дає цукерку мандрівникам, які допомагають хворій дитині. Щоб заробити М'ятний Льодяник з Андерсіті, шукачам пригод доведеться забути про гідність і помахати руками, як курка.",h="У святкову пору Переддня Усіх Святих Корчмар Норман з Андерсіті дає цукерку мандрівникам, які допомагають...",kw={"кудкудакання за льодяник","переддень усіх святих","корчмар норман","м'ятний льодяник з андерсіті","спупс","торговий квартал","сирота"},ang={["faction:Horde"]="На Переддень Усіх Святих шукачі пригод Орди обходять усі столиці й у кожній терплять якусь кумедну ганьбу, аби принести радість дитині-сироті.",["race:Undead"]="Знайти дурнуватий жарт серед трухлявих зал Андерсіті — велика рідкість, тож святкова вимога Нормана стає химерною перервою в буденному некромантичному прагматизмі."},sec={{t="Рідкісна мить веселощів",b="Андерсіті, зведене визволеними Відступниками під руїнами Лордерона, мало знане смішками чи теплом. Та коли приходить Переддень Усіх Святих, навіть похмурі мешканці Торгового Кварталу долучаються до свята. Корчмар Норман береже запас М'ятних Льодяників з Андерсіті для тих, хто збирає ласощі для малого Спупса — хворого сироти, якому бракує святкової радості."},{t="Заробити ласощі",b="Норман не збирається просто так віддавати цукерку загартованим шукачам пригод і вимагає трохи сміховинного дійства. Він вважає, що дорослі воїни й заклиначі мусять заслужити свої солодощі, тож не віддасть льодяника, доки прохач не покудкудакає, як курка на подвір'ї, просто перед його прилавком."}},faq={{q="Чому Корчмар Норман хоче, щоб я кудкудакав, як курка?",a="Корчмар Норман вважає, що дорослим поборникам не личить ходити по солодощі, не влаштувавши вистави. Щоб звеселити всіх на Переддень Усіх Святих, він вимагає смішного номера — махати руками й кудкудакати, як курка, — і лише тоді віддає свої святкові ласощі.",al={"чому емоція курки","чому кудкудакати норману","танець курки нормана"}},{q="Для кого ці ласощі?",a="М'ятний Льодяник з Андерсіті збирають для Спупса, хворого сироти, що лежить в Оргріммарі й не може сам ходити по солодощі під час свята Переддня Усіх Святих.",al={"для кого льодяник","навіщо льодяник","чому льодяник андерсіті"}},{q="Де знайти Корчмаря Нормана?",a="Корчмар Норман тримає головну таверну в Торговому Кварталі Андерсіті й обслуговує Відступників і заїжджих мандрівників Орди.",al={"місце нормана","де корчмар андерсіті"}},{q="Чи це завдання святкового фестивалю?",a="Так. Це завдання — частина щорічних святкувань Переддня Усіх Святих, які відзначають по всьому Азероту і Орда, і Альянс.",al={"чи це завдання свята","коли доступне завдання"}},{q="Чи святкують Відступники Переддень Усіх Святих?",a="Відступники святкують Переддень Усіх Святих із великим запалом: вони спалюють величезного плетеного велетня під руїнами Лордерону на згадку про своє визволення й розрив із колишнім смертним життям.",al={"свято відступників","свято нежиті"}},{q="Що буде, коли отримати М'ятний Льодяник з Андерсіті?",a="Льодяник додають до інших фірмових ласощів, зібраних у столицях рас Орди, щоб скласти повний святковий подарунок для малого Спупса.",al={"наступне завдання","що робити з льодяником"}}},fp="27,239,19.389.0,17.301.0,58.273.0,30.167.0,34.142.0,34.125.0,44.192.0,46.146.0"}
P.entries["quest:8355"] = {n="Мармеладка на підході",s="Мармеладка на підході — сезонне завдання Переддня Усіх Святих в Айронфорджі, яке дає гном-майстер Талваш Дель Кіссель. Щоб отримати святкові ласощі для хворої дитини в Стормвінді, шукачі пригод мусять спершу кумедно зобразити потяг на втіху захопленому гномові.",h="Мармеладка на підході — сезонне завдання Переддня Усіх Святих в Айронфорджі, яке дає гном-майстер Талваш Дель...",kw={"переддень усіх святих","талваш дель кіссель","мармеладка","джеспер","потяг","ласощі"},ang={["faction:Alliance"]="Пошуки святкової мармеладки ведуть героїв Альянсу через королівства, щоб і хвора дитина в Стормвінді відчула свято.",["race:Gnome"]="Для гномів-вигнанців у Містечку Майстрів Мармеладка з Гномреґану на Переддень Усіх Святих — радісне нагадування про дім і механічну винахідливість серед поневірянь."},sec={{t="Дивакувате мито",b="Під час осіннього свята Переддня Усіх Святих ласуни, що ходять від дверей до дверей, обходять великі твердині Альянсу й збирають особливі місцеві солодощі. У Кварталі містиків Айронфорджа гном Талваш Дель Кіссель зберігає жадану Мармеладку з Гномреґану. Він співчуває малому сироті, що мріє про неї, але, перш ніж розлучитися з ласощами, наполягає на святковому дусі пустощів і вимагає від кожного прохача переконливо зобразити потяг."},{t="Святкова доброчинність",b="Це завдання — частина більшої сезонної справи: звеселити Джеспера, хворого сироту, що лежить у Стормвінді. Джеспер мріє про чотири різні ласощі з усіх земель Альянсу: нугу зі Стормвінда, м'ятний льодяник з Айронфорджа, марципан із Дарнасуса й мармеладку з Гномреґана. Пихкаючи, мов паровоз, на втіху Талвашеві, поборники здобувають гномські ласощі й виконують святкове бажання хлопчика."}},faq={{q="Що треба зробити, щоб виконати завдання «Мармеладка на підході»?",a="Треба зобразити потяг для Талваша Дель Кісселя: виберіть його ціллю й скористайтеся жестом потяга. Почувши, як ви гудете, він радо віддасть Мармеладку з Гномреґану.",al={"як виконати мармеладку на підході","мета мармеладки на підході","витівка талваша"}},{q="Хто такий Талваш Дель Кіссель?",a="Талваш Дель Кіссель — гном-ювелір із Гномреґану, що живе в Кварталі містиків гірського міста дворфів Айронфорджа. На Переддень Усіх Святих він роздає для Альянсу фірмові мармеладки Гномреґану.",al={"хто такий талваш","переказ про талваша дель кісселя"}},{q="Для чого Мармеладка з Гномреґану?",a="Мармеладка з Гномреґану — одна з чотирьох різних святкових цукерок, які збирають, щоб виконати прохання на Переддень Усіх Святих від Джеспера, хлопчика-сироти з притулку Стормвінда.",al={"призначення мармеладки з гномреґану","для чого мармеладка"}},{q="Де знайти Талваша Дель Кісселя?",a="Талваша можна знайти в Кварталі містиків Айронфорджа.",al={"де талваш","місце талваша"}},{q="Чому Талваш змушує зображати потяг?",a="Переддень Усіх Святих — свято, вкорінене в звичаї ходити по солодощі з витівками. Талваш жартома вимагає невинної витівки — зобразити паротяг, — і лише тоді віддає святкові ласощі.",al={"чому шум потяга","чому зображати потяг для талваша"}},{q="Чи доступне це завдання цілий рік?",a="Ні, це завдання доступне лише під час щорічного осіннього свята Переддня Усіх Святих.",al={"чи можна коли завгодно","чи це сезонне завдання"}}},fp="16,265,16.467.0,15.447.0,50.184.0,26.222.0,40.177.0,38.53.0,42.185.0,35.83.0"}
P.entries["quest:8356"] = {n="М'язи за нугу",s="Під час осіннього свята Переддня Усіх Святих шукачі пригод, що навідуються до Стормвінда, можуть допомогти місцевому сироті зібрати святкові солодощі. Щоб отримати шматочок Нуги зі Стормвінда від Корчмарки Еллісон у «Позолоченій Троянді», гостям доводиться жартома показати могутні м'язи — лише тоді вона віддасть ласощі.",h="Під час осіннього свята Переддня Усіх Святих шукачі пригод, що навідуються до Стормвінда, можуть допомогти...",kw={"нуга зі стормвінда","корчмарка еллісон","переддень усіх святих","позолочена троянда","джеспер","ласощі"},ang={["class:Warrior"]="Для кремезних воїнів, звиклих до кривавих полів битви, показати біцепси на прохання корчмарки — невинна, хоч і трохи незручна для гідності демонстрація сили.",["faction:Alliance"]="Цей грайливий обмін показує легший, добросусідський дух, що розквітає в Стормвінді на сезонних святах, як-от Переддень Усіх Святих, і збирає городян і мандрівних героїв разом, щоб від душі посміятися.",["race:Human"]="Для людей Стормвінда потішити дітей і обміняти витівку на ласощі — улюблений сезонний звичай, що ненадовго відволікає від темніших загроз, які нависли над королівством."},sec={{t="Традиція Переддня Усіх Святих",b="Переддень Усіх Святих приносить на вулиці Стормвінда рідкісну легкість. Хоч давнє коріння свята пов'язане зі зміною пір року й відганянням темних духів, простий люд святкує його перевдяганнями, гулянням і ходінням від дверей до дверей по ласощі. Корчмарі по всьому Альянсу долучаються й роздають традиційні солодощі — якщо охочі до свята згодні в обмін на гостинець утнути якусь невинну витівку."},{t="Розваги для корчмарки",b="У «Позолоченій Троянді», що в гамірному Торговому Кварталі, Корчмарка Еллісон дбає, щоб ніхто не отримав святкових цукерок задарма — навіть якщо виконує доручення для хлопчика-сироти на кшталт Джеспера. Оглянувши спорядження чи вбрання шукача пригод, Еллісон жартома коментує його статуру й наполягає, щоб він напружив м'язи їй на втіху. Лише коли гість продемонструє свою силу, вона винагороджує його шматочком тягучої Нуги зі Стормвінда."}},faq={{q="Чому Корчмарка Еллісон змушує напружувати м'язи?",a="Переддень Усіх Святих обертається довкола звичаю витівок і ласощів. Шукач пригод приходить від імені сироти, що шукає солодощів, тож Корчмарка Еллісон наполягає, щоб він заробив цукерку кумедною витівкою — а саме показав свої м'язи.",al={"чому напружувати м'язи заради нуги","чого хоче еллісон","чому емоція м'язів"}},{q="Де відбувається це завдання?",a="Прохання дають і виконують цілком у корчмі «Позолочена Троянда» в самому серці Торгового Кварталу Стормвінда, де за шинквасом стоїть Корчмарка Еллісон.",al={"де м'язи за нугу","місце еллісон","корчмарка позолоченої троянди"}},{q="Для кого Нуга зі Стормвінда?",a="Нуга призначена для Джеспера, хлопчика-сироти в Стормвінді. Він мріє скуштувати традиційні святкові ласощі з кожного великого міста Альянсу на Переддень Усіх Святих.",al={"для кого нуга","хто хоче нугу зі стормвінда","цукерки джеспера"}},{q="Що таке Нуга зі Стормвінда?",a="Нуга зі Стормвінда — місцеві солодощі, які корчмарі Стормвінда роздають на Переддень Усіх Святих; серед гостей свята вони відомі як чи не найхарактерніші ласощі людського королівства.",al={"переказ про нугу зі стормвінда","нуга кануна дня всіх святих","цукерка стормвінда"}},{q="Чи можуть гравці Орди отримати ці ласощі від Еллісон?",a="Ні. Корчмарка Еллісон живе в самому серці Стормвінда під владою Альянсу й обслуговує лише членів Альянсу. Шукачі пригод Орди виконують свої святкові витівки для корчмарів у власних столицях.",al={"чи орда може напружувати м'язи","версія орди для нуги"}},{q="Чи буває це завдання цілий рік?",a="Ні. Корчмарка Еллісон дає це прохання лише під час сезонного свята Переддня Усіх Святих, коли містами заволодіває звичай ходити по солодощі з витівками.",al={"коли доступні м'язи за нугу","чи завдання сезонне","час кануна дня всіх святих"}}},fp="18,302,24.432.0,26.460.0,44.253.0,33.173.0,38.167.0,25.184.0,49.208.0,34.145.0"}
P.entries["quest:8357"] = {n="Танець за марципан",s="Коли надходить Переддень Усіх Святих, шукачам пригод, що проходять через Дарнасус, доручають зібрати святкові ласощі для хворого сироти зі Стормвінда. Корчмар Селієнн повною мірою шанує традицію «цукерки або капость»: перш ніж розлучитися зі своїм дорогоцінним Марципаном із Дарнасуса, вона вимагає імпровізованого танцю.",h="Коли надходить Переддень Усіх Святих, шукачам пригод, що проходять через Дарнасус, доручають зібрати святкові...",kw={"переддень усіх святих","марципан","танець","селієнн","джеспер","дарнасус","стормвінд"},ang={["faction:Alliance"]="Це святкове завдання показує єдність і безжурне товариство столиць Альянсу: ласощі з далекого Тельдрассила мандрують аж до юного сироти в Стормвінді.",["race:NightElf"]="Для нічних ельфів участь у Передодні Усіх Святих — зворушливе переймання сезонних звичаїв Альянсу, що поєднує їхнє безтурботне лісове життя з грайливими гульбищами."},sec={{t="Традиція, якої дотримуються",b="Навіть у священному лісовому місті Дарнасусі гульбища Переддня Усіх Святих додають легкості довговічним нічним ельфам. Коли мандрівники прибувають по святкові ласощі для Джеспера — хворої дитини, що одужує в Стормвінді, — Корчмар Селієнн наполягає, щоб правила свята лишалися непорушними. Доброчинність чи ні, а перш ніж дістати цукерку, треба показати капость."},{t="Ціна марципану",b="Щоб заслужити ніжний Марципан із Дарнасуса, шукачам пригод доводиться відкласти поважний вигляд і влаштувати виставу просто на підлозі корчми. Селієнн вимагає ні більше ні менше як танцю й охоче винагороджує тих, хто ладен поступитися гордістю й поринути у святкові веселощі, ласощами, яких бракує для міжконтинентального святкового пакунка."}},faq={{q="Навіщо завдання «Танець за марципан»?",a="Це завдання — частина сезонних святкувань Переддня Усіх Святих в Альянсі. Ви танцюєте для Корчмаря Селієнн у Дарнасусі, щоб отримати Марципан із Дарнасуса — одні з кількох святкових ласощів, потрібних, щоб потішити хворого сироту Джеспера в Стормвінді.",al={"чому танцювати за марципан","що за завдання","завдання марципан"}},{q="Хто така Корчмар Селієнн?",a="Корчмар Селієнн тримає корчму в Дарнасусі, даючи притулок і спочинок мандрівникам під гіллям Тельдрассилу. На Переддень Усіх Святих вона роздає місцеві святкові солодощі тим, хто готовий підіграти традиції.",al={"хто такий селієнн","переказ про селієнн"}},{q="Чому Селієнн наполягає на танці?",a="Селієнн суворо тримається духу Переддня Усіх Святих. Хоча ласощі призначені хворій дитині, вона непохитно дотримується звичаю «витівка чи ласощі» й жартома вимагає показати танцювальну вправність як витівку, перш ніж віддати солодощі.",al={"чому танцювати","чому селієнн хоче танець"}},{q="Куди марципан іде далі?",a="Отриманий Марципан із Дарнасуса додають до святкових солодощів, зібраних у корчмах Айронфорджа й Стормвінда та в Талваша Дель Кісселя в Айронфорджі, щоб виконати завдання й порадувати малого Джеспера в Стормвінді.",al={"кому марципан","що робити з марципаном"}},{q="Що таке Марципан із Дарнасуса?",a="Марципан із Дарнасуса — солодкі ласощі, які готують у столиці нічних ельфів. Це фірмові святкові ласощі Дарнасуса для гостей, що ходять по солодощі на Переддень Усіх Святих.",al={"переказ про марципан із дарнасуса","що за цукерка"}},{q="Чи можуть гравці Орди виконати це завдання?",a="Ні. «Танець за марципан» — сезонне завдання лише для Альянсу. Дарнасус — твердиня Альянсу, а марципан збирають саме для сироти з Альянсу, що одужує в Стормвінді.",al={"чи це лише для альянсу","завдання марципан орда"}}},fp="20,314,18.375.0,21.343.0,44.247.0,27.253.0,37.261.0,38.238.0,27.178.0,38.194.0"}
P.entries["quest:8359"] = {n="М'язи за нугу",s="Під час Переддня Усіх Святих, осіннього свята, Корчмарка Гришка в Оргріммарі пригощає сезонними ласощами тих, хто готовий підіграти. Щоб заробити шматочок Нуги з Оргріммару для прикутої до ліжка дитини, чемпіонам Орди доведеться проковтнути воїнську гордість і за командою похизуватися м'язами.",h="Під час Переддня Усіх Святих, осіннього свята, Корчмарка Гришка в Оргріммарі пригощає сезонними ласощами тих...",kw={"переддень усіх святих","нуга з оргріммару","корчмарка гришка","спупс","м'язи","свято","оргріммар"},ang={["class:Warrior"]="Воїнам, які пишаються нищівними подвигами на передовій, може видатися кумедним — або трохи принизливим — позувати, мов артисти на сцені, заради квадратика святкових ласощів.",["faction:Horde"]="Навіть бувалі чемпіони, які дивилися в очі смертоносним полководцям, мусять грати біцепсами перед корчмаркою, щоб назбирати святкових солодощів для дітей Орди.",["race:Orc"]="Корчмарка Оргріммара чекає вражаючої демонстрації м'язів — це суто орче випробування гордості, перетворене на веселу святкову виставу."},sec={{t="Фокус за ласощі",b="Переддень Усіх Святих приносить у гамірні столиці Азероту веселощі, витівки й збирання солодощів. Героям-мандрівникам не раз доводиться битися з драконами й темним чаклунством, але традиції осіннього свята вимагають значно легшої руки. Корчмарка Гришка, що порядкує в загальній залі оргріммарського заїзду, охоче ділиться запасом святкових ласощів — але тільки з тими, хто дотримується найдавнішого правила свята: покажи фокус або йди ні з чим."},{t="М'язи напоказ",b="Потішаючись із будь-якого вбрання чи обладунку, в якому з'являється шукач пригод, Гришка вимагає показати справжню орчу силу. Перш ніж віддати бодай шматочок Нуги з Оргріммару, призначеної для малого Спупса, вона наполягає, щоб могутній мандрівник став у позу силача. Це жартівливе нагадування: навіть найгрізніших бійців Орди можна змусити розважати простий люд заради цукерки."}},faq={{q="Хто просить напружити м'язи?",a="Корчмарка Гришка, господиня головної таверни в Долині Сили в Оргріммарі, вимагає цієї витівки, перш ніж віддати свої святкові солодощі.",al={"хто дає завдання","гришка","корчмарка гришка"}},{q="Чому я маю напружувати м'язи заради цукерок?",a="За звичаєм Переддня Усіх Святих, хто ходить по солодощі, мусить показати невеличку витівку в обмін на ласощі. Гришка вирішує подражнити шукача пригод і просить показати свою неабияку фізичну силу, перш ніж нагородити.",al={"чому напружувати м'язи","яка витівка","умова нуги"}},{q="Для чого Нуга з Оргріммару?",a="Нуга — одні з чотирьох різних солодощів, які збирають по столицях Орди, щоб потішити Спупса, хворого хлопчика-сироту, що не може сам ходити по солодощі.",al={"навіщо нуга","вжиток нуги","цукерка"}},{q="Де живе Корчмарка Гришка?",a="Її можна знайти за шинквасом головної корчми в Долині Сили в Оргріммарі, де вона обслуговує і втомлених мандрівників, і місцевих.",al={"де гришка","місце корчмарки оргріммара"}},{q="Чи може будь-який член Орди взяти в цьому участь?",a="Так, будь-який член Орди може на Переддень Усіх Святих навідатися до Корчмарки Гришки, стати в позу й отримати святкові солодощі.",al={"хто може напружувати м'язи","обмеження фракцій","лише орда"}},{q="Частиною якого свята це є?",a="Це доручення — частина Переддня Усіх Святих, осіннього свята, що відзначає кінець жнив і виклик смертності маскарадом, витівками й солодощами.",al={"яке це свято","яка подія","завдання кануна дня всіх святих"}}},fp="18,305,17.451.0,17.396.0,27.154.0,32.213.0,38.159.0,36.136.0,41.128.0,31.155.0"}
P.entries["quest:8360"] = {n="Танці за марципан",s="«Танці за марципан» — святкове завдання Переддня Усіх Святих, яке дає Корчмарка Пала в Тандер Блафі. Щоб дістати ласощі для хворого сироти, мандрівникам доведеться забути про загартовану в боях гідність і весело потанцювати для корчмарки. Це завдання показує грайливий, щирий дух свята навіть на продуваних вітрами плато Малгора.",h="«Танці за марципан» — святкове завдання Переддня Усіх Святих, яке дає Корчмарка Пала в Тандер Блафі.",kw={"переддень усіх святих","корчмарка пала","марципан","танець","тандер блаф","сирота","свято"},ang={["faction:Horde"]="Світла мить серед суворих буднів Орди: мандрівники обходять столиці, щоб принести святкову радість сироті, — і в цьому видно серце вашої фракції.",["race:Tauren"]="Корчмарка Пала приносить у Малгор традиційні святкові веселощі й доводить, що навіть могутні, стримані таурени не проти потанцювати заради доброї справи."},sec={{t="Танець на скелях",b="Під час осіннього свята Переддня Усіх Святих увесь Азерот охоплює піднесений настрій — навіть спокійні висоти Тандер Блафа. Корчмарка Пала, що дбає про гостей на високих плато, теж перейнялася святковим духом: перш ніж роздавати ласощі, вона вимагає якоїсь витівки. Навіть коли мандрівник приходить заради хворої дитини, звичай непорушний: Пала хоче побачити святковий танець, а вже тоді віддасть свій цінний Марципан з Громового Стрімчака."},{t="Витівки за ласощі",b="Святковий звичай обмінювати розвагу на солодощі відкриває рідкісний, безтурботний бік культури Орди. Прохання Пали зовсім просте: вийти вперед, струсити дорожню втому й показати найкращі свої рухи. Добряче розважившись, корчмарка охоче віддає марципан і передає щирі побажання хворому малюкові, який чекає на гостинець."}},faq={{q="Навіщо завдання «Танці за марципан»?",a="Завдання доручає вам станцювати для Корчмарки Пали в Тандер Блафі. Натомість вона дає вам Марципан з Громового Стрімчака — частину більшого набору святкових ласощів, які збирають для хворого сироти на Переддень Усіх Святих.",al={"чому танцювати за марципан","мета танців за марципан","завдання танцю за марципан"}},{q="Хто дає це завдання?",a="Це завдання на свято Переддня Усіх Святих дає Корчмарка Пала, тауренка, що обслуговує гостей і місцевих у Тандер Блафі.",al={"хто починає танці за марципан","завдання пали","корчмарка пала тандер блаф"}},{q="Чому Пала наполягає на танці, якщо цукерки для хворої дитини?",a="Пала наголошує, що святкові традиції треба шанувати навіть у шляхетній справі. За звичаєм ходити по солодощі, щоб заслужити солодку нагороду, треба показати витівку — так Переддень Усіх Святих лишається радісним і жвавим.",al={"чому я маю танцювати","чому пала хоче танець"}},{q="Яку нагороду дають за танець?",a="Ви отримуєте Марципан з Громового Стрімчака — місцеві святкові ласощі, потрібні, щоб скласти загальний набір солодощів на Переддень Усіх Святих для хворої дитини.",al={"нагорода за танець","предмет танців за марципан"}},{q="Чи можуть гравці Альянсу виконати це завдання?",a="Ні. Корчмарка Пала — торговка Орди в самому серці Тандер Блафа, тож ця зупинка на шляху за святковими ласощами доступна лише членам Орди.",al={"чи це лише для орди","танці за марципан альянс"}},{q="Коли доступне це завдання?",a="Це завдання доступне лише під час щорічного осіннього свята Переддня Усіх Святих, коли корчмарі по всьому Азероту пропонують особливі солодощі й святкові забави.",al={"коли можна марципан","завдання марципан кануна дня всіх святих"}}},fp="20,356,20.447.0,17.386.0,44.250.0,21.137.0,65.223.0,39.160.0,41.168.0,29.156.0"}
P.entries["quest:84"] = {n="Назад до Біллі",s="«Назад до Біллі» — ще один крок у тривалій ворожнечі родин Стоунфілдів і Маклурів у центрі Лісу Елвінн. Зібравши складники для пирога з грудинкою, ви несете щойно спечену страву малому Біллі Маклуру, щоб витягти з нього, куди поділося намисто Берніс Стоунфілд.",h="«Назад до Біллі» — ще один крок у тривалій ворожнечі родин Стоунфілдів і Маклурів у центрі Лісу Елвінн.",kw={"біллі маклур","пиріг","грудинка","стоунфілди","маклури","намисто","ліс елвінн"},ang={["faction:Alliance"]="Навіть мирний Ліс Елвінн потерпає від буденних чвар; розбиратися зі сварливими людськими садибами — звична робота для мандрівників, що допомагають місцевим.",["profession:Cooking"]="Пиріг з грудинкою — класична домашня страва елвіннських фермерів, яку готують із м'яса диких вепрів, що блукають лісом."},sec={{t="Гіркий пиріг",b="Сварка Стоунфілдів і Маклурів тягнеться поколіннями й не лишає місця для сусідської ласки. Тітонька Берніс Стоунфілд знехотя спекла замовлений пиріг з грудинкою лише тому, що малий Біллі Маклур відмовився без нього розповідати, що знає про її родинну реліквію. Навіть передаючи теплу випічку, вона не приховує роздратування й просить кур'єра переказати хлопчиськові Маклурів: нехай удавиться кожним шматком."},{t="Хабар для хлопчиська",b="Через дорогу, на Виноградниках Маклюрів, Біллі Маклур чекає з порожнім животом і напрочуд зручною дірою в пам'яті. Цей обмін показує вперту дріб'язковість, що розділяє дві садиби: тут навіть діти вчаться міняти плітки й поцуплені дрібнички на сільські ласощі. Щойно пиріг доставлено, пам'ять Біллі дивовижно прояснюється — і починаються пошуки справжнього місця, де лежить намисто."}},faq={{q="Навіщо ця доставка?",a="Біллі Маклур заявив, що знає, де загублене намисто Тітоньки Берніс Стоунфілд, але відмовлявся говорити, доки не отримає домашнього пирога зі свинячою грудинкою. Доставивши пиріг, ви виконуєте його вимогу, і він розповість, куди поділася реліквія.",al={"навіщо доставка пирога","чого хоче біллі","мета завдання назад до біллі"}},{q="Чому Тітонька Берніс так сердиться на Біллі?",a="Родини Стоунфілдів і Маклюрів роками ворогують по-сільському запекло. Берніс обурена, що мусить пекти ласощі для капосного малого Маклура лише заради того, щоб повернути реліквію, яка зникла на межі їхніх земель.",al={"чому берніс сердиться на біллі","сварка стоунфілдів і маклурів","чому йому подавитися"}},{q="Де, за словами Біллі, насправді намисто?",a="Умявши пиріг, Біллі зізнається, що намиста в нього немає. Воно потрапило до рук Золотозуба — горезвісного кобольда, що чатує в Копальні Фарґодіп.",al={"де насправді намисто","хто взяв намисто","зв'язок з ґолдтусом"}},{q="Де знайти Біллі Маклура?",a="Біллі Маклур — на Виноградниках Маклюрів, трохи на південь від дороги в центрі Лісу Елвінн, навпроти Ферми Стоунфілдів.",al={"місце біллі маклура","де біллі","знайти біллі"}},{q="Хто спік Пиріг зі Свинячою Грудинкою?",a="Пиріг спекла Тітонька Берніс Стоунфілд на Фермі Стоунфілдів, після того як ви принесли свіжі шматки вепрятини з навколишніх диких місць.",al={"хто спік пиріг","кухар пирога"}},{q="Чи кладе це завдання край ворожнечі родин?",a="Ні. Доставлений пиріг лише вдовольняє особистий хабар Біллі. Глибока ворожнеча між дорослими Стоунфілдами й Маклюрами лишається такою ж запеклою, як і була.",al={"чи скінчиться ворожнеча","мир стоунфілдів і маклурів"}}},fp="13,296,12.426.0,13.394.1,37.233.0,42.221.0,46.169.1,31.129.0,29.138.0,54.157.0"}
P.entries["quest:840"] = {n="Доброволець Орди",s="«Доброволець Орди» — вступне перехідне завдання, що веде молодих шукачів пригод з Орди з Дуротару в неосяжну глушину Пусток. Його дає розвідник Такрін Патсікер на західній дорозі від Гострого Пагорба: він посилає новобранців за Річку Південної Люті, на прикордонну заставу Каргала Баттлскара.",h="«Доброволець Орди» — вступне перехідне завдання, що веде молодих шукачів пригод з Орди з Дуротару в неосяжну...",kw={"доброволець орди","такрін патсікер","каргал баттлскар","вербувальний лист","дуротар","новобранці"},ang={["faction:Horde"]="Цей призов знаменує перехід воїна від місцевого захисника Дуротару до визнаного оборонця ширших земель Орди в Калімдорі.",["race:Orc"]="Для молодих орків, що покидають тренувальні угіддя в Долині Випробувань і на Гострому Пагорбі, відгукнутися на заклик Каргала Баттлскара — важливий обряд посвяти на службі Вождеві.",["race:Troll"]="Тролі з Темного Спису, що б'ються пліч-о-пліч зі своїми союзниками-орками, через це призначення допомагають Орді розширюватися й убезпечити землі на березі Великого моря."},sec={{t="Через Південну Лють",b="Щойно молодий солдат Орди доведе свою силу довкола Гострого Пагорба, потреби всієї держави кличуть його на захід. Такрін Патсікер стежить за ґрунтовим шляхом, що виходить із Дуротару, і оцінює мандрівників від імені свого друга, ветерана Каргала Баттлскара. Узяти в Такріна вербувальний лист — перше офіційне доручення новобранця за межами рідного оркського краю."},{t="Оборона кордону",b="Прикордонна застава за мостом стоїть на межі між червоними каньйонами Дуротару й посушливими просторами Пусток. Каргалові Баттлскару доручено збирати новобранців, щоб утримувати рубежі, хоча прикордонна варта — лише початок. Оскільки кентаври, шипогриви й експедиції Альянсу раз у раз промацують кордон, свіжі сили терміново спрямовують до поселення на Перехресті."}},faq={{q="Куди віднести лист про вербування?",a="Ідіть західною дорогою з Гострого Пагорба в Дуротарі через дерев'яний міст над Річкою Південної Люті. Каргал Баттлскар стоїть на сторожовій вежі застави Орди одразу за кордоном, з боку Пусток.",al={"куди йти","місце каргала баттлскара","місце здачі"}},{q="Хто такий Такрін Патсікер?",a="Такрін Патсікер — розвідник Орди, що стоїть на західній дорозі за Гострим Пагорбом. Він пильнує шлях і помічає вправних воїнів, щоб посилати їх на захід, до свого товариша Каргала Баттлскара.",al={"роль такріна","хто дає завдання","видавець завдання"}},{q="Хто такий Каргал Баттлскар?",a="Каргал Баттлскар — суворий офіцер-ветеран, що відає дозорним постом на сході Пусток. Він оглядає новоприбулих добровольців, підписує їхні папери про призов і скеровує їх углиб савани на допомогу Перехрестю.",al={"хто такий каргал","переказ про баттлскара"}},{q="Що буде, коли Каргал підпише лист?",a="Каргал приймає лист і одразу записує вас на подальшу службу в завданні «Призов на Перехресті», наказуючи йти головною дорогою на захід і доповісти Серґрі Даркторн на Перехресті.",al={"наступне завдання","що після добровольця орди","куди далі"}},{q="Чому Орда набирає вояків для Пусток?",a="Пустки — відкрите прикордоння, життєво важливе для зв'язку Оргріммара з Малгором. Люті племена шипогривів, кентаври-грабіжники й підступні вторгнення Альянсу загрожують шляхам постачання, тож Орді потрібні всі руки, здатні тримати зброю, щоб берегти дороги.",al={"чому орда вербує","небезпека пусток","чому вербування"}},{q="Чи доступне це завдання гравцям Альянсу?",a="Ні. Це завдання лише для членів Орди, що переходять від перших завдань у Дуротарі до Пусток.",al={"чи альянс може це","чи це лише для орди"}}},fp="22,320,22.382.0,14.392.0,39.218.0,25.195.0,25.214.0,43.215.0,53.249.0,44.121.0"}
P.entries["quest:842"] = {n="Призов на Перехресті",s="«Призов на Перехресті» скеровує щойно завербованих новобранців Орди з прикордонної застави в серце Пусток. З підписаним листом від Каргала Баттлскара шукачі пригод з'являються просто до Серґри Даркторн у важливому стратегічному вузлі — на Перехресті.",h="«Призов на Перехресті» скеровує щойно завербованих новобранців Орди з прикордонної застави в серце Пусток.",kw={"призов на перехресті","серґра даркторн","каргал баттлскар","вербувальний лист","перехрестя","новобранці"},ang={["class:Shaman"]="Серґра Даркторн показує, що шамани в Орді Тралла — не лише містичні порадники, а й справжні військові командири та очільники ключових стратегічних застав.",["faction:Horde"]="Це призначення — звичний обряд посвяти для молодих бійців Орди, що переходять із безпечних рідних земель у спірну глушину Пусток.",["race:Orc"]="Суперечка між Каргалом і Серґрою показує, як змінюються суспільні звичаї в оновленій Орді Тралла, де заслуги й духовна прозорливість кидають виклик старим клановим звичкам простої солдатської служби."},sec={{t="Прибути на службу",b="Довівши свою гідність Каргалові Баттлскару на Далекій Дозорній Заставі на кордоні Дуротару, новобранці отримують підписаний вербувальний лист і вирушають на захід. Шлях пролягає утоптаною ґрунтовою дорогою через посушливі чагарники Пусток аж до центрального роздоріжжя. На цьому випаленому сонцем перетині доріг стоїть Перехрестя — важливий вузол постачання Орди, що поєднує північ Калімдору з південною глушиною."},{t="Шаманка Перехрестя",b="На новоприбулих чекає Серґра Даркторн — гостра на язик оркська шаманка, яку Вождь Тралл особисто обрав керувати справами на Перехресті. Попри бурчання бувалих ветеранів на кшталт Каргала Баттлскара, який вважає її важкою в спілкуванні й надто балакучою, Тралл високо цінує Серґру. Запальна й непохитна, вона не забуває нагадати новобранцям — особливо пихатим чоловікам, — що в Орді Тралла жінки-воїни й очільниці стоять цілком нарівні й жодного зухвальства не терпітимуть."}},faq={{q="Хто посилає мене на це завдання?",a="Це доручення дає Каргал Баттлскар, орк-ветеран із Далекої Дозорної Застави трохи на захід від мосту між Дуротаром і Пустками.",al={"хто дає призов на перехресті","видавець призову на перехресті","завдання каргала"}},{q="Де знайти Серґру Даркторн?",a="Серґра Даркторн стоїть просто в центрі Перехрестя, біля роздоріжжя, де зустрічаються каравани й гінці.",al={"місце серґри даркторн","де серґра","знайти серґру даркторн"}},{q="Чому Каргал скаржиться на Серґру?",a="Серґра дратує Каргала: він називає її зловредною шаманкою, яка ходить колами, перш ніж дасть комусь узятися до справжньої роботи. Але попри своє роздратування він шанує наказ Вождя Тралла посилати до неї новобранців.",al={"чому каргал скаржиться на серґру","каргал проти серґри","прокляти її шкуру"}},{q="Чому Серґра говорить із чоловіками й жінками по-різному?",a="Серґра Даркторн дуже пишається наказом Тралла, що встановив у новій Орді цілковиту рівність для жінок-воїнів. Жінок-новобранців вона тепло хвалить за те, що наважилися, а чоловіків-новобранців попереджає, що не терпітиме неповаги чи зухвалості.",al={"розмова серґри чоловіки жінки","діалог серґри даркторн","серґра на рівних"}},{q="Яким шляхом дістатися до Перехрестя?",a="Ідіть головною дорогою на захід від Далекої Дозорної Застави до Т-подібного роздоріжжя, а тоді зверніть ліворуч і йдіть південною дорогою просто до поселення Перехрестя.",al={"як дістатися перехрестя","напрям до перехрестя","шлях до перехрестя"}},{q="Що буде після доповіді Серґрі Даркторн?",a="Прийнявши вас, Серґра одразу залучає вас допомагати Перехрестю: відбиватися від місцевих загроз, полювати й берегти заставу по всьому центру Пусток.",al={"що після призову на перехресті","наступне завдання серґри","наступні новобранці пусток"}}},fp="23,265,18.412.0,28.496.0,27.153.0,34.139.0,38.216.0,64.259.0,49.173.0,49.186.0"}
P.entries["quest:843"] = {n="Ґанн повертає своє",s="«Ґанн повертає своє» — завдання Орди, яке дає мандрівний тауренський вигнанець Ґанн Стоунспайр на півдні Пусток. Глибоко скривджений дворфійськими археологічними розкопками в Бель Модані, що вигнали його плем'я, Ґанн кличе мандрівників ударити у відповідь: убивати робітників розкопок і здобути щоденник їхнього очільника.",h="«Ґанн повертає своє» — завдання Орди, яке дає мандрівний тауренський вигнанець Ґанн Стоунспайр на півдні...",kw={"ґанн повертає своє","ґанн стоунспайр","бель модан","шукач хазґорм","ліга дослідників","таурени"},ang={["class:Shaman"]="Вибухи й глибокі траншеї в Бель Модані ранять довколишніх духів землі, тож кампанія Ґанна — необхідне очищення від стихійного безладу.",["faction:Horde"]="Бель Модан — укріплена твердиня Альянсу глибоко в землях Калімдору, тож підтримка Ґанна в його правах — і справа честі, і стратегічне стримування.",["race:Tauren"]="Для шу'гало біда Ґанна — обурливе нагадування про те, як мало Альянс шанує Земну Матір, коли динамітом і залізними шестернями роздирає родові поховання."},sec={{t="Вигнане плем'я",b="Ще до того, як гармати й кайла Шукача розворушили землю, червоні кручі на півдні Пусток були родовою колискою й мисливськими угіддями клану Ґанна Стоунспайра. Коли з Айронфорджа прибула Ліга Дослідників, щоб заснувати Бель Модан, тауренів жорстоко вигнали або вбили, щоб звільнити місце для величезних кар'єрів і траншей. Мирні протести лишилися непочутими, дипломатію вичерпано, і тепер Ґанн самотньо бреде запорошеною південною дорогою, обмірковуючи криваву відплату за полеглих родичів."},{t="Руїни Бель Модану",b="Дворфійська експедиція в Бель Модані мало зважає на землю чи її охоронців. Розпорюючи схили паровими машинами й потужною вибухівкою, експедиція під проводом Шукача Хазґорма вгризалася глибоко в землю в пошуках прадавніх реліквій Титанів. Завдання Ґанна просте й безкомпромісне: прорідити ряди копачів і виконробів Бел'дуна, що шматують священний ґрунт, убити самого Хазґорма й забрати особисті записи шукача про розкопки, щоб дізнатися, чого насправді шукають загарбники з Альянсу."}},faq={{q="Хто такий Ґанн Стоунспайр?",a="Ґанн Стоунспайр — самотній таурен, що вцілів із племені, яке колись жило на півдні Пусток. Після того як дворфи-копачі вигнали його народ і вбили тих, хто опирався, Ґанн став ходити південним шляхом, прагнучи справедливості й помсти проти табору розкопок Альянсу, що загарбує землю.",al={"ґанн","хто дає ґанн повертає своє","переказ про ґанна стоунспайра"}},{q="Що дворфи роблять у Пустках?",a="Дворфи — з експедиції Бель'дуна, яку відрядила Ліга Дослідників Айронфорджа. Натхненні нещодавнім відкриттям своєї спадщини від Титанів, вони заснували Бель Модан, щоб розкопувати поховані прадавні реліквії й руїни, геть не зважаючи на корінних мешканців-тауренів.",al={"чому дворфи в бель модані","мета бель модана","айронфордж у пустках"}},{q="Хто такий Шукач Хазґорм?",a="Шукач Хазґорм — ватажок дворфів, що керує розкопками на південь від фортеці Бель Модан. Ґанн вважає його прямим винуватцем наруги над землею своїх предків і вимагає його щоденник як доказ його смерті.",al={"шукач хазґорм","хазґорм","ватажок бель модана"}},{q="Де знайти Ґанна Стоунспайра?",a="Ґанн Стоунспайр ходить дорогою на крайньому півдні Пусток, на захід від фортеці Бель Модан і на північ від дороги до Великого Підйомника й Тисячі Голок.",al={"місце ґанна стоунспайра","знайти ґанна","де ґанн"}},{q="Чи намагався Ґанн вирішити все мирно?",a="Так. Ґанн прямо каже, що пробували дипломатією зупинити руйнування земель його предків, але дворфи знехтували цими зусиллями й далі підривали пагорби, тож йому довелося вдатися до сили.",al={"чи таурени пробували дипломатію","дипломатія ґанна"}},{q="Що буде після цього завдання?",a="Отримавши щоденник Хазґорма, Ґанн вивчає записи, щоб зрозуміти технології й задуми дворфів, і це веде просто до низки завдань «Помста Ґанна», щоб зруйнувати їхні важкі машини.",al={"наступне завдання після ґанн повертає своє","продовження ґанна"}}},fp="18,312,17.508.0,23.509.0,23.283.0,35.277.0,27.259.0,35.171.0,40.228.0,30.198.1"}
P.entries["quest:844"] = {n="Загроза рівнинних довгоступів",s="«Загроза рівнинних довгоступів» — вступне мисливське доручення від Серґри Даркторн на Перехресті. Новоприбулих шукачів пригод з Орди посилають проредити місцевих степових довгоступів, що нишпорять уздовж шляхів постачання поселення, — це водночас і боротьба зі шкідниками, і перша перевірка мисливської вправності.",h="«Загроза рівнинних довгоступів» — вступне мисливське доручення від Серґри Даркторн на Перехресті.",kw={"загроза рівнинних довгоступів","степовий довгоступ","серґра даркторн","перехрестя","полювання","мисливець"},ang={["class:Hunter"]="Для молодих мисливців випробування Серґри — важлива основа: як скрадатися, вистежувати й валити здобич на відкритій савані.",["faction:Horde"]="Перехрестя — важливий вузол постачання, і захист його харчових запасів від звірини дає Орді змогу втримувати свої позиції в Калімдорі.",["race:Orc"]="Орки шанують дисципліну полювання, і Серґра чекає, що кожен новачок доведе свій гарт у сутичках із місцевими звірами, перш ніж братися за серйозніші обов'язки."},sec={{t="Захист Перехрестя",b="Перехрестя — серце постачання Калімдору, звідки спрямовують каравани через сувору савану. Проте в посушливому краї місцева звірина відчайдушно шукає поживи. Зграї високих нелітаючих степових довгоступів, що бродять трохи на схід від застави, взялися дзьобати ящики з харчами й порушувати життєвий ритм поселення. Щоб захистити вразливі припаси, шаманка Серґра Даркторн посилає мандрівників проредити зухвалих птахів, перш ніж вони завдадуть серйозної шкоди коморам застави."},{t="Перше полювання",b="Боротьба зі шкідниками — нагальна практична мета, але Серґра бачить у степових довгоступах ще й мірило для новачків. Вона вважає цих птахів простою здобиччю — легкою дичиною, що має навчити молодих мисливців виживати в суворих умовах і вистежувати звіра на випалених сонцем рівнинах. Принесені гострі дзьоби доводять, що мисливець має терпіння й основну бойову вправність, потрібні, щоб зустрітися з лютішими звірами Пусток."}},faq={{q="Чому полюють саме на рівнинних довгоступів?",a="Зграї рівнинних довгоступів на схід від Перехрестя так осміліли, що грабують запаси їжі й дошкуляють обозам, що проходять повз. Серґра Даркторн наказує їх проріджувати, щоб уберегти життєво важливий провіант поселення.",al={"чому вбивати довгоступів","проблема довгоступів","що зробили довгоступи"}},{q="Хто така Серґра Даркторн?",a="Серґра Даркторн — досвідчена шаманка-орчиха на Перехресті. Вона проводить мисливські випробування поселення: навчає новоприбулих шукачів пригод і посилає їх проти диких звірів, що загрожують справам Орди.",al={"хто така серґра","роль серґри даркторн","видавець перехрестя"}},{q="Навіщо Серґрі саме їхні дзьоби?",a="Твердий гострий дзьоб — головна зброя й знаряддя рівнинного довгоступа, яким він порпається в пошуках поживи. Відтяті дзьоби — незаперечний доказ, що цих птахів-грабіжників убито.",al={"чому дзьоби довгоступів","доказ дзьобів довгоступів"}},{q="Що йде після цього полювання?",a="Коли з рівнинними довгоступами покінчено, Серґра перевіряє вас на прудкішій і жвавішій здобичі, посилаючи полювати на жевр, що блукають рівнинами.",al={"що далі","наступне завдання після довгоступів","порядок полювання"}},{q="Де водяться ці рівнинні довгоступи?",a="Вони блукають луками савани одразу на схід і південний схід від Перехрестя, шукаючи поживи вздовж торгових доріг.",al={"де довгоступи","місця довгоступів","мисливські угіддя"}},{q="Чи це частина більшої низки полювань?",a="Так. Це доручення — самий початок мисливських випробувань Серґри Даркторн у Пустках, які поступово ведуть до дедалі небезпечніших звірів савани.",al={"ланцюжок полювань пусток","ланцюжок серґри"}}},fp="19,292,23.516.0,14.423.0,35.207.0,24.221.0,46.172.0,27.143.0,38.116.0,40.174.0"}
P.entries["quest:845"] = {n="Жеври",s="«Жеври» — раннє мисливське випробування від Серґри Даркторн на Перехресті. У межах поступової перевірки бойової вправності на саванах Пусток молодим мисливцям доручено вистежити прудких жевр і здобути їхні потужні копита.",h="«Жеври» — раннє мисливське випробування від Серґри Даркторн на Перехресті.",kw={"жеври","копита жеври","серґра даркторн","перехрестя","полювання","мисливець"},ang={["class:Hunter"]="Для стрільців і слідопитів, що набираються досвіду в Пустках, вистежування прудких стад жевр — важлива польова практика переслідування й влучності.",["faction:Horde"]="Перехрестя покладається на мандрівних шукачів пригод, щоб тримати в межах навколишню звірину й не дати їй перекрити шляхи постачання поселення.",["race:Tauren"]="Серґра окремо наголошує, що удар жеври може збити дорослого таурена з ніг, тож це випробування — слушне нагадування, що навіть степові травоїди заслуговують на повагу."},sec={{t="Крок угору на савані",b="Після першого прорідження розплоджених степових довгоступів Пусток Серґра Даркторн спрямовує молодих воїнів Орди до дещо грізнішої дичини. Смугасті жеври бродять стадами північними й південними рівнинами. Вони не верховні хижаки савани, але це прудконогі стадні звірі, відомі впертою витривалістю й потужними ударами копит, що трощать кістки."},{t="Випробування Даркторн",b="Для Серґри це полювання — не стільки здобування краму, скільки перевірка того, як гострішає хист шукача пригод. Вона вимагає чотири цілі копита як речовий доказ здобичі й попереджає, що удар задньої ноги цього звіра досить сильний, щоб збити дорослого таурена з ніг. Довівши себе в сутичках із цими прудкими звірами, мисливець здобуває право на ще смертоносніші випробування — проти хижих нишпорок рівнин."}},faq={{q="Хто доручає це полювання?",a="Це випробування дає Серґра Даркторн, досвідчена шаманка-орчиха на Перехресті в центрі Пусток, щоб перевірити молодих воїнів Орди.",al={"хто дає завдання жевр","видавець жевр","завдання серґри даркторн"}},{q="Де водяться жеври?",a="Прудкі жеври блукають відкритими рівнинами на північ і на південь від Перехрестя по всьому центру Пусток.",al={"де жеври","місця жевр","карта жевр у пустках"}},{q="Навіщо Серґрі копита жевр?",a="Копита — трофейний доказ вдалого полювання. Ноги в жевр напрочуд сильні, і чотири принесені копита доводять, що мисливець здатен здолати звіра, який може збити з ніг навіть могутнього таурена.",al={"чому копита жевр","доказ копит жевр","чому полювати на жевр"}},{q="Що йде після цього завдання?",a="Коли ви покажете себе на жеврах, Серґра перевірить вас на справжніх хижаках у завданні «Хижаки Пусток».",al={"наступне завдання після жевр","продовження жевр","наступне завдання даркторн"}},{q="Чи небезпечні жеври?",a="Здебільшого жеври — мирні пасовищні тварини, але ноги в них неймовірно сильні. Серґра попереджає: один прямий удар переляканої чи загнаної в кут жеври може повалити кремезного таурена на спину.",al={"чи жеври небезпечні","небезпека жевр","удар жеври"}},{q="Чому перед цим полювали на рівнинних довгоступів?",a="Серґра будує свої випробування так, щоб складність зростала поступово. Рівнинні довгоступи — перша вправа в стрільбі, жеври — прудкіша й фізично сильніша здобич, а вже тоді черга агресивних скрадачів савани.",al={"попереднє завдання","зв'язок із загрозою довгоступів"}}},fp="10,267,24.378.0,23.404.0,22.145.0,27.102.0,35.211.0,28.123.0,22.198.0,42.235.0"}
P.entries["quest:846"] = {n="Помста Ґанна",s="«Помста Ґанна» — завдання Орди на півдні Пусток, у якому скорботний тауренський вигнанець Ґанн Стоунспайр задумує відплату експедиції Бель Модану. Покінчивши з Шукачем Хазґормом, Ґанн посилає мандрівників у дворфійську фортецю по нестійкі боєприпаси для вибухового контрудару.",h="«Помста Ґанна» — завдання Орди на півдні Пусток, у якому скорботний тауренський вигнанець Ґанн Стоунспайр...",kw={"помста ґанна","ґанн стоунспайр","бель модан","нітрогліцерин","вибухівка","шукач хазґорм"},ang={["faction:Horde"]="Знешкодження дворфійських робіт на півдні Пусток не дає Альянсові створити військовий плацдарм і перерізати шляхи між Малгором, Перехрестям і південним рубежем.",["profession:Engineering"]="Поєднання нітрогліцерину, нітрату натрію й деревної маси — класичний дворфійський рецепт промислового динаміту, нашвидкуруч пристосований до партизанської війни.",["race:Tauren"]="Для тауренів Бель Модан — тяжка рана, завдана Земній Матері, тож диверсія проти дворфійських машин — і духовний, і територіальний обов'язок."},sec={{t="Їхньою ж зброєю",b="Смерть Шукача Хазґорма завдала розкопкам у Бель Модані удару, але Ґанн Стоунспайр знає, що це лише тимчасово. Дворфійські роботи рідко зупиняються надовго, і незабаром прибуде новий виконроб, щоб наглядати за машинами, які патрають його родову землю. Не бажаючи дивитися, як земля страждає від нових розкопок, Ґанн вирішує вдарити у відповідь технікою самих загарбників. Перетворивши їхнє підривне спорядження на знаряддя диверсії, він задумує розірвати їхню твердиню зсередини."},{t="Набіг на фортецю",b="Фортеця Бель Модану — водночас база розкопок і укріплений гарнізон із солдатами, стрільцями й офіцерами, що захищають інтереси дворфів у Пустках. Ґанн дізнається, що оборонці запасають матеріали для промислових підривів: нітрогліцерин, деревну масу й нітрат натрію. Він доручає союзникам з Орди пробратися за периметр і відібрати ці нестійкі складники просто в дворфів, назбиравши досить сировини, щоб зібрати нищівний підривний заряд."}},faq={{q="Чому Ґанн Стоунспайр прагне помсти?",a="Дворфи з Айронфорджа в Бель Модані захопили прабатьківщину Ґанна, осквернили землю й вигнали його народ, щоб розгорнути розкопки. Убивши головного шукача й забравши його щоденник, Ґанн хоче назавжди зупинити їхнє нищення.",al={"чому ґанн прагне помсти","мотив ґанна стоунспайра","що дворфи зробили ґанну"}},{q="Де знайти вибухові матеріали?",a="Складники носять дворфи, що обороняють Бель Модан. Стрільці, солдати й офіцери в укріпленому таборі розкопок на півдні Пусток і довкола нього мають при собі флакони з нітрогліцерином, в'язки деревної маси й зразки натрієвої селітри.",al={"де нітрогліцерин","де деревна маса","де нітрат натрію"}},{q="Навіщо Ґаннові деревна маса й хімікати?",a="Дворфійські креслення розкопок показують: якщо стабілізувати нестійкий нітрогліцерин деревною масою й змішати з натрієвою селітрою, вийде надійна промислова вибухівка. Ґанн хоче зробити власний підривний заряд, щоб рознести ключові споруди дворфів.",al={"навіщо деревна маса","що робить ґанн","інгредієнти бомби ґанна"}},{q="Що буде, коли припаси зібрано?",a="Щойно ви принесете складники, Ґанн збере вибуховий заряд і доручить вам підірвати ним летючу машину дворфів на розкопках Бель Модану — важливу частину всього табору.",al={"що далі після помсти ґанна","після збору інгредієнтів"}},{q="Чому смерть Хазґорма не кладе край загрозі від дворфів?",a="Хазґорм був лише головним шукачем. Військова присутність дворфів у Бель Модані глибоко вкорінена: тут оборонні мури й шляхи постачання. Айронфордж просто надішле іншого старшого, щоб копати далі, якщо вся база не зазнає нищівного удару.",al={"чому смерть хазґорма не допомогла","чи бель модан зупинено"}},{q="Чим Бель Модан загрожує Орді стратегічно?",a="Хоча спершу Бель Модан збудували як укріплений табір розкопок, щоб відкопувати прадавні артефакти титанів, тепер це багатолюдний оплот Альянсу. Стоячи при торгових шляхах на півдні Пусток, він становить відкриту військову загрозу для поселень Орди в Калімдорі поблизу.",al={"чому орда дбає про бель модан","загроза бель модана"}}},fp="15,306,29.495.0,16.500.0,39.274.0,40.250.0,43.257.0,42.208.1,52.270.0,51.284.0"}
P.entries["quest:848"] = {n="Грибні Спори",s="Аптекар Гелбрім із Королівського Аптекарського Товариства доручає шукачам пригод з Орди зібрати грибні спори довкола оаз Пусток. Дивні енергії змін, що струмують цими джерелами, перетворили місцеві рослини на могутні реагенти. Гелбрім хоче зібрати ці незвичні зразки, щоб приготувати суміші для своєї колеги в Тандер Блафі.",h="Аптекар Гелбрім із Королівського Аптекарського Товариства доручає шукачам пригод з Орди зібрати грибні спори...",kw={"грибні спори","аптекар гелбрім","аптекарка замах","оази","королівське аптекарське товариство","тандер блаф"},ang={["class:Druid"]="Оази таять неприродно бурхливий сплеск магії природи, що спричиняє агресивні мутації в навколишньому довкіллі.",["faction:Horde"]="Дослідження збурених вод Пусток допомагає захистити важливі шляхи, що поєднують Оргріммар, Перехрестя й Тандер Блаф.",["profession:Herbalism"]="Налиті гриби довкола оаз Пусток показують, як раптовий приплив енергії довкілля може перетворити звичайні рослини на могутні реагенти.",["race:Undead"]="Навіть далеко від Лордерону дослідники-Відступники продовжують свою алхімічну роботу, обертаючи природні аномалії Калімдору на службу цілям Королівського Аптекарського Товариства."},sec={{t="Буйна й змінена флора",b="Пустки здебільшого — посушлива, випалена сонцем савана, але її оази — як-от Забуті ставки, Оаза Буйних Вод і Застояна Оаза — аж бурлять неприродною життєвою силою. З цих вод струмує дивний сплеск життєвої енергії, що спотворює й наснажує рослини та звірів, які з них п'ють. Налиті гриби, що ростуть на мулистих берегах, вбирають ці потужні потоки, і їхні спори набувають рідкісних властивостей, які розпалюють цікавість мандрівних алхіміків."},{t="Королівське Аптекарське Товариство в Калімдорі",b="Хоч Аптекар Гелбрім служить далеко від Андерсіті, на Перехресті, він і далі відданий дослідженням Королівського Аптекарського Товариства. Помітивши дивну силу місцевих реагентів Калімдору, він збирає ці змінені спори, щоб створювати могутні суміші. Зібрані тут зразки призначені для Аптекарки Замах у Тандер Блафі — свідчення тихих, але далекосяжних наукових зусиль, які Відступники ведуть на союзних землях."}},faq={{q="Де ростуть ці грибні спори?",a="Спори збирають із рясних грибів, що ростуть біля самої води в оазах Пусток, зокрема у Забутих ставках, Оазі Буйних Вод і Застояній оазі.",al={"де гриби спори","місця грибних спор","місце грибів"}},{q="Чому гриби біля оаз змінилися?",a="Водами оаз Пусток тече потужна хвиля життєвої енергії. Замість підтримувати звичайний ріст рослин, ця енергія бурхливо підстьобує й змінює навколишніх звірів і рослини.",al={"чому гриби змінилися","життєва енергія оаз","що не так з оазами"}},{q="Хто такий Аптекар Гелбрім?",a="Аптекар Гелбрім — член Королівського Аптекарського Товариства Відступників на Перехресті в Пустках. Він вивчає незвичну природу краю й збирає місцеві матеріали для алхімічних досліджень.",al={"переказ про гелбріма","хто такий гелбрім","аптекар на перехресті"}},{q="Що Гелбрім збирається робити зі спорами?",a="Гелбрім робить із сильних спор особливу суміш, яку збирається надіслати своїй колезі-дослідниці, Аптекарці Замах, у місто тауренів Тандер Блаф.",al={"для чого спори","призначення грибних спор"}},{q="Що аптекарі Відступників роблять у Пустках?",a="Як частина союзу Орди, дослідники Відступників вивчають чужі краї й незвичні рослини по всьому Калімдору, шукаючи нових реагентів для ліків, отрут і сумішей.",al={"чому нежить у пустках","королівське аптекарське товариство в калімдорі"}},{q="У якій оазі найбезпечніше збирати спори?",a="У Забутих ставках на північний захід від Перехрестя водяться слабші звірі, ніж в Оазі Буйних Вод чи Застояній оазі на півдні, тож збирати гриби там найбезпечніше.",al={"легка оаза для спор","найбезпечніша оаза пусток"}}},fp="13,353,25.469.0,40.448.0,34.180.0,45.206.0,26.208.0,45.173.0,55.176.0,49.213.0"}
P.entries["quest:849"] = {n="Помста Ґанна",s="«Помста Ґанна» — останній удар у кровній помсті Ґанна Стоунспайра дворфам Бель Модану. Озброєний особливим вибуховим зарядом, створеним за викраденими дворфійськими кресленнями, посланець Орди має підірвати цінну літальну машину експедиції, щоб помститися за полеглих тауренів Стоунспайр.",h="«Помста Ґанна» — останній удар у кровній помсті Ґанна Стоунспайра дворфам Бель Модану.",kw={"помста ґанна","ґанн стоунспайр","вибухова шашка ґанна","гірокоптер","бель модан","диверсія"},ang={["faction:Horde"]="Знищення літальної машини Бель Модану знешкоджує повітряну зброю Альянсу, здатну розвідувати й завдавати ударів глибоко на півдні Пусток.",["profession:Engineering"]="Вибухівку для машини зроблено за кресленнями Айронфорджа й обернено проти гірокоптера — іронічний шедевр польової диверсії.",["race:Tauren"]="Помста за клан Стоунспайр знищенням дворфійських бойових машин глибоко зворушить кожного таурена, що боронить родову землю від наруги."},sec={{t="Символ панування",b="Розкопки в Бель Модані — не просто нахабна копальня, а озброєна фортеця, поставлена просто на родових землях вигнаних тауренів Стоунспайр. Ключ до досяжності й військової сили Шукачів — їхній гірокоптер. Ця механічна літальна машина, що стоїть на сторожовій вежі над розкопками, оглядає навколишні Пустки, захищає шляхи постачання й ширяє в небі як символ зухвалого вторгнення Альянсу на землю Калімдору."},{t="Обернена проти творців",b="Здобувши креслення Шукача Хазґорма, Ґанн Стоунспайр виготовляє особливий вибуховий заряд — Вибухову Шашку Ґанна. Заклавши цей нестійкий боєприпас на літальну машину, Ґанн обертає технічну пиху дворфів на їхню ж погибель. Вибух знищує важливе військове знаряддя, завдає принизливого удару загону з Бел'дуна й вшановує духів загиблого племені."}},faq={{q="Чому Ґанн хоче знищити саме летючу машину?",a="Летюча машина — і бойова зброя, і важлива частина Бель Модану: вона дає дворфам розвідку з повітря. А для Ґанна вона ще й зухвалий символ дворфійської сили, що образливо височіє над землею, яку колись називало домом його вирізане плем'я.",al={"чому знищити літаючу машину","призначення літаючої машини","чому ціль літаюча машина"}},{q="Де в Бель Модані стоїть летюча машина?",a="Летюча машина стоїть на дерев'яному майданчику вежі посередині схилу, що веде до головного котловану розкопок, а не всередині чи поряд із головною фортецею дворфів.",al={"де літаюча машина","місце літаючої машини","місце гірокоптера бель модана"}},{q="Як Ґанн зробив вибуховий пристрій?",a="Ґанн виготовив Вибухову Шашку Ґанна за технічними кресленнями й інженерними планами, нещодавно здобутими в Шукача Хазґорма, — тож обернув власні задуми дворфів проти них самих.",al={"як ґанн зробив бомбу","походження вибухівки","плани вибухівки хазґорма"}},{q="До якого племені належить Ґанн?",a="Ґанн із племені Стоунспайр — клану тауренів, що споконвіку жив на півдні Пусток, доки розкопки дворфів з Айронфорджа жорстоко не вигнали їх і не знищили їхнє поселення.",al={"плем'я ґанна","що за плем'я стоунспайрів","хто такі таурени стоунспайри"}},{q="Чи знищення машини назавжди зупиняє розкопки?",a="Воно тяжко б'є по повітряній перевазі й господарству Бель Модану й дає Ґаннові особисту відплату, але глибоко закорінені дворфи-копачі та їхня фортеця лишаються діяльним оплотом Альянсу в краї.",al={"чи бель модан зупинено","чи падає бель модан","чи ґанн переміг"}},{q="Яке визнання пропонує Ґанн, коли доручення виконано?",a="Ґанн проголошує, що героя, який знищив машину, шануватимуть у Тандер Блафі як захисника священних земель тауренів і вічного поборника його втраченого племені.",al={"завершення ґанна","кінець завдання ґанна","що каже ґанн"}}},fp="15,303,22.481.0,22.425.1,62.298.0,50.180.0,41.183.0,31.196.0,60.226.0,61.167.1"}
P.entries["quest:85"] = {n="Загублене намисто",s="«Загублене намисто» — вступне завдання на півдні Лісу Елвінн від «Тітоньки» Берніс Стоунфілд. Підозрюючи в крадіжці бешкетного хлопчиська з ворожого роду, Берніс посилає шукачів пригод через дорогу — притиснути Біллі Маклура й повернути її зниклу реліквію.",h="«Загублене намисто» — вступне завдання на півдні Лісу Елвінн від «Тітоньки» Берніс Стоунфілд.",kw={"загублене намисто","берніс стоунфілд","біллі маклур","крадіжка","стоунфілди","маклури"},ang={["faction:Alliance"]="Для новачків Альянсу, що починають свій шлях у Лісі Елвінн, залагоджувати дрібні чвари між сварливими Стоунфілдами й Маклурами — найхарактерніший смак місцевого життя на прикордонні.",["race:Human"]="Ворожнеча Стоунфілдів і Маклурів показує, що не всі чвари в Королівстві Стормвінд ідуть від злочинців Дефіас чи загонів гнолів: давні сільські сусідські сварки сягають не менш глибоко."},sec={{t="Сусідське звинувачення",b="Родини Стоунфілдів і Маклурів володіють сусідніми землями на півдні Лісу Елвінн, та доброї волі між ними майже немає. Виявивши, що її улюблене намисто зникло, «Тітонька» Берніс Стоунфілд не гаючись тицяє пальцем у наймолодшого з ворожого дому. Переконана, що малий Біллі Маклур прокрався на її ферму й поцупив прикрасу, озлоблена вдова просить будь-якого охочого мандрівника піти на виноградники, знайти хлопця й вимагати повернення."},{t="Хлопчисько з апетитом",b="Розмова з Біллі Маклуром на сусідньому винограднику швидко все ускладнює. Біллі обурено заперечує, що брав намисто, і запевняє, що він не злодій. Однак із хитрою посмішкою натякає: він, може, і знає, що насправді сталося з дрібничкою, — якщо спершу хтось утамує його бурчливий живіт свіжим пирогом зі свининою."}},faq={{q="Хто така Тітонька Берніс Стоунфілд?",a="Тітонька Берніс Стоунфілд — літня вдова, що живе на Фермі Стоунфілдів на півдні Лісу Елвінн. Вона глибоко не довіряє сусідам Маклюрам, особливо їхньому синові-шибеникові, Біллі.",al={"хто тітонька берніс","берніс стоунфілд","хто дає загублене намисто"}},{q="Чи справді Біллі Маклур украв намисто?",a="Коли Біллі прямо питають, він рішуче заперечує, що злодій. Сам він намиста не брав, але зізнається, що бачив, хто чи що його взяло, — тільки не скаже, доки його як слід не нагодують.",al={"чи біллі злодій","чи біллі вкрав","чи біллі взяв намисто"}},{q="Де знайти Біллі Маклура?",a="Біллі Маклур зазвичай байдикує серед виноградних лоз на Виноградниках Маклюрів, просто на схід через дорогу від Ферми Стоунфілдів.",al={"місце біллі маклура","де біллі","знайти біллі маклура"}},{q="Чому Стоунфілди й Маклюри не люблять одне одного?",a="Дві сусідні родини роками ворогують по-сільському запекло. Напругу підігрівають суперечки за землю, гордість і давні особисті образи, тож обидві сторони одразу підозрюють одна одну в найгіршому.",al={"родинна ворожнеча","ворожнеча стоунфілдів і маклурів","чому вони ненавидять одне одного"}},{q="Що буде після розмови з Біллі Маклуром?",a="Біллі наполягає, що надто голодний, щоб пригадати, куди поділося намисто, і відсилає вас назад до Тітоньки Берніс — спекти йому пиріг зі свининою в обмін на відомості.",al={"що далі","після загубленого намиста","наступне завдання"}},{q="Де відбувається це завдання?",a="Завдання відбувається цілком на півдні Лісу Елвінн: ви ходите туди й назад між Фермою Стоунфілдів і сусідніми Виноградниками Маклюрів.",al={"зона завдання","де загублене намисто"}}},fp="13,264,23.485.0,22.334.1,33.211.0,46.185.1,31.146.0,55.225.0,44.171.1,33.144.0"}
P.entries["quest:850"] = {n="Ватажки Колкарів",s="«Ватажки Колкарів» відкриває кампанію під проводом орка Реґтара Дезґейта, що має розгромити нових кентаврських воєначальників у Пустках. Кочові Колкари поколіннями дошкуляли тауренам, але нові вожді згуртовують розрізнені ватаги в справжню військову загрозу. Реґтар доручає звитяжцям Орди вбити Барака Кодобейна біля Забутих ставків, перш ніж його вплив пошириться.",h="«Ватажки Колкарів» відкриває кампанію під проводом орка Реґтара Дезґейта, що має розгромити нових...",kw={"ватажки колкарів","реґтар дезґейт","барак кодобейн","колкари","кентаври","забуті ставки"},ang={["faction:Horde"]="Перехрестя в Пустках — життєво важлива артерія, що поєднує Малгор, Дуротар і віддаленіші застави Орди. Знешкодження верхівки Колкарів захищає вразливі каравани з припасами від нищівних засідок.",["race:Orc"]="Тралл присягнув, що Орда захищатиме тауренів, і бувалі ветерани на кшталт Реґтара Дезґейта серйозно ставляться до цієї кровної клятви, вважаючи кентаврських паліїв війни прямою стратегічною загрозою оркській владі в Пустках.",["race:Tauren"]="Для тауренів убивство командирів Колкарів — питання виживання й помсти. Кентаврські клани десятиліттями вирізали племена й зганяли шу'гало з родових пасовищ, перш ніж Орда закріпилася в Калімдорі."},sec={{t="Загроза, що зростає в посушливих землях",b="Незліченні роки кентаври з кінським тулубом тероризували Калімдор і майже винищили кочових тауренів, доки Орда Тралла не прибула й не переломила хід подій. У Пустках панівне плем'я Колкарів зазвичай кочує розпорошеними, розрізненими ватагами мародерів. Проте останнім часом войовничі вожді почали єднати ці ватаги, перетворюючи прості загони нападників на згуртовану військову силу, здатну кинути виклик укріпленим заставам Орди."},{t="Відтяти голову звірові",b="Отаборившись на захід від Перехрестя, оркський воїн Реґтар Дезґейт зрозумів, що згуртованість Колкарів тримається переважно на хвацькості й грубій силі. Без сильних командирів їхні нападники гризуться між собою. Щоб зупинити їхній наступ, Реґтар посилає шукачів пригод з Орди відтяти змії голову — і почати з Барака Кодобейна, честолюбного ватажка, що отаборився біля зелених вод Забутих ставків."},{t="Перший із багатьох",b="Смерть Барака Кодобейна завдає відчутного удару північним таборам Колкарів, але Реґтар знає, що Барак — лише передовий загін ширшого руху. Його усунення — перший залп злагодженої кампанії, що має розібрати верхівку Колкарів, і відкриває шлях до полювання на інших вождів — Вероґа Дервіша й Гезрула Бладмарка — по всіх Пустках."}},faq={{q="Хто такий Барак Кодобейн?",a="Барак Кодобейн — лютий ватажок кентаврів Колкарів, що зібрав грабіжників довкола Забутих ставків на північ від Перехрестя. Відомий кмітливістю й жорстокістю, він виявився набагато небезпечнішим за звичайних кочових рейдерів, бо згуртував розрізнені клани в наступальну загрозу для Орди.",al={"барак","хто такий барак","переказ про барака кодобейна"}},{q="Де знайти Барака Кодобейна?",a="Барак Кодобейн тримає табір у Забутих ставках — буйній оазі на північ від Перехрестя в центрі Пусток. Довкола нього зазвичай віддані вартові Колкари.",al={"місце барака","де барак","забуті озерця барак"}},{q="Хто такий Реґтар Дезґейт?",a="Реґтар Дезґейт — орк-ветеран, що стоїть у невеликому таборі з бліндажем трохи на захід від Перехрестя. Він стежить за пересуваннями кентаврів у Пустках і завдає випереджальних ударів, щоб уберегти поселення Орди від організованих набігів.",al={"реґтар","хто дає ватажків колкарів","реґтар дезґейт"}},{q="Чому Колкари — така проблема для Орди?",a="Кентаври поколіннями ведуть безжальну, майже винищувальну війну проти тауренів. Таурени — повноправні члени Орди й покладаються на союзників, щоб уберегти свої прадавні мисливські угіддя й торгові шляхи через Пустки від дальшого наступу кентаврів.",al={"чому битися з колкарами","загроза колкарів","суперництво кентаврів і орди"}},{q="Що буде після смерті Барака?",a="Перемога над Бараком Кодобейном розкриває, що інші вожді збирають сили деінде в Пустках. Реґтар одразу посилає вас убити Вероґа Дервіша в Застояній оазі, потім Гезрула Бладмарка в Оазі Буйних Вод, а все завершується обороною від прямого наступу Колкарів.",al={"наступне завдання після барака","продовження ватажків колкарів","що далі"}},{q="Чому Колкари збираються довкола оаз?",a="Вода й родюча земля — справжні скарби в посушливих Пустках. Захоплюючи природні джерела на кшталт Забутих ставків, Колкари забезпечують собі воду й водночас позбавляють мандрівників і мисливців-тауренів важливих місць для перепочинку.",al={"чому колкари біля оаз","вода колкарів","кентаври забутих озерець"}}},fp="14,401,31.466.0,22.446.0,17.360.1,22.286.0,32.176.0,25.231.0,48.268.0,35.299.1,42.250.0"}
P.entries["quest:851"] = {n="Вероґ Дервіш",s="Вероґ Дервіш — невловимий ватажок кентаврів-Колкарів, що кочує південними рівнинами Пусток. Щоб покласти край його набігам, Реґтар Дезґейт посилає звитяжців Орди напасти на командний намет кентаврів біля Застояної Оази й змусити кочового командира вийти на відкрите місце.",h="Вероґ Дервіш — невловимий ватажок кентаврів-Колкарів, що кочує південними рівнинами Пусток.",kw={"вероґ дервіш","реґтар дезґейт","застояна оаза","колкари","кентаври","пустки"},ang={["faction:Horde"]="Влада над оазами — запорука виживання в посушливих Пустках; винищення кентаврських командирів гарантує, що водні шляхи лишаться відкритими для караванів із припасами.",["race:Orc"]="Реґтар Дезґейт вважає усунення воєначальників Колкарів необхідним, щоб убезпечити для мандрівників із Дуротару дорогу між Перехрестям і Горами Кам'яного Кігтя.",["race:Tauren"]="Колкари поколіннями полювали на кочових тауренів і дошкуляли їм на цих рівнинах, тож страта ватажків на кшталт Вероґа — довгоочікувана відплата."},sec={{t="Виманити дервіша",b="Після загибелі Барака Кодобейна оркський воїн Реґтар Дезґейт бере на приціл решту воєначальників племені Колкарів. На відміну від Барака, що відкрито стояв біля північних вод Забутих ставків, Вероґ Дервіш блукає випаленими сонцем рівнинами вздовж і впоперек і рідко надовго затримується в одному таборі. Вистежувати його на такому неосяжному просторі — марна справа, тож розвідникам Орди лишається єдина дієва стратегія: змусити командира самому прийти до них."},{t="Застояна Оаза",b="Вероґ діє з кентаврського командного пункту біля Застояної Оази, на південний схід від Перехрестя. Реґтар велить шукачам пригод напасти просто на табір і вбивати воїнів-Колкарів біля командного намету, доки паніка не змусить засурмити в ріг. Ця хитрість обертає кентаврську гордість проти них самих: варто вирізати досить підлеглих Вероґа на їхній же землі — і дервіш помчить назад боронити свою заставу, просто під клинки Орди, що на нього чекають."}},faq={{q="Хто такий Вероґ Дервіш?",a="Вероґ Дервіш — мандрівний воєначальник кентаврів Колкарів у Пустках. Він керує справами із Застояної оази, але багато часу блукає південними пустками, тож загнати його в кут нелегко.",al={"хто такий вероґ","переказ про вероґа","вероґ дервіш"}},{q="Чому Вероґ не сидить у своєму таборі?",a="Вірний своєму прізвиську «Дервіш», Вероґ — кочовий ватажок, що мандрує безлюдними куточками Пусток, а не сидить без діла в одному таборі. Рухливість береже його від організованих загонів Орди, тож вороги мусять виманити його, щоб він показався.",al={"де вероґ","чому вероґ блукає","вероґ зник"}},{q="Як викликати Вероґа?",a="Вероґ повертається до свого штабу, коли його племені загрожує небезпека. Коли шукачі пригод нападають на кентаврів довкола помітного командного намету в Застояній оазі, здіймається такий переполох, що вцілілі Колкари б'ють на сполох, і Вероґ мчить назад боронити свій намет.",al={"як викликати вероґа","знайти вероґа","вероґ не з'являється"}},{q="Хто наказує вбити Вероґа?",a="Наказ стратити Вероґа дає Реґтар Дезґейт, орк-ветеран, що отаборився на захід від Перехрестя при головній дорозі до Гір Кам'яного Кігтя. Він хоче зламати хребет Колкарам, методично вистежуючи кожного з їхніх місцевих командирів.",al={"хто дає завдання","реґтар дезґейт"}},{q="Що буде, коли Вероґ упаде?",a="Принісши Реґтарові відтяту голову Вероґа, ви даєте оркові змогу додати її до своєї колекції поряд із головою Барака Кодобейна. Тоді Реґтар бере на приціл Гезрула Бладмарка — воєначальника кентаврів, що панує в Оазі Буйних Вод на півдні.",al={"що далі","після вероґа"}},{q="Чому кентаври Колкари — така проблема в Пустках?",a="Колкари — агресивні хижаки, що ревно бережуть свою землю й захоплюють життєво важливі джерела води по всіх Пустках. Їхні часті набіги на каравани, застави й стада корінних тауренів — пряма загроза самому існуванню молодої присутності Орди в центральному Калімдорі.",al={"чому колкари проблема","загроза колкарів"}}},fp="17,270,23.494.0,18.475.0,25.225.0,35.281.0,24.287.0,25.245.0,31.231.1,57.269.0"}
P.entries["quest:852"] = {n="Гезрул Бладмарк",s="«Гезрул Бладмарк» — доручення оркського ветерана Реґтара Дезґейта знищити верховного воєначальника кентаврів-Колкарів у Пустках. Здобувши голову Гезрула в Оазі Буйних Вод, Орда прагне раз і назавжди зруйнувати командну ієрархію загарбників.",h="«Гезрул Бладмарк» — доручення оркського ветерана Реґтара Дезґейта знищити верховного воєначальника...",kw={"гезрул бладмарк","реґтар дезґейт","оаза буйних вод","колкари","кентаври","перехрестя"},ang={["faction:Horde"]="Щоб утримати Перехрестя й Пустки, треба розірвати кентаврську хватку на трьох великих оазах, без яких неможливі подорожі краєм.",["race:Orc"]="Реґтар Дезґейт дивиться на боротьбу з Колкарами крізь призму оркського військового мистецтва: кентаври люті, але їхній дикій нестямі бракує залізної дисципліни, яку виплекала Орда.",["race:Tauren"]="Поколіннями кочові таурени терпіли від кентаврів жорстоке вигнання й кровопролиття; кінець таких воєначальників, як Гезрул, — важко вистраждана відплата."},sec={{t="Обезголовити Колкарів",b="Після загибелі Барака Кодобейна й Вероґа Дервіша серед Колкарів Пусток лишився тільки один верховний вождь — Гезрул Бладмарк. Реґтар Дезґейт вважає Гезрула жорстоким і хитрим вістрям, що спрямовує кентаврські набіги по всій савані. Убивство Гезрула має посіяти хаос і непоправно розколоти їхні ряди — відтяти голову й без того мінливому звірові, перш ніж кентаври змітуть поселення Орди."},{t="Твердиня Буйних Вод",b="Гезрул командує своїми загонами з Оази Буйних Вод, що на південь від Перехрестя. Влада над нечисленними водопоями Пусток — запорука виживання, тож оаза — стратегічний вузол і вихідний пункт для загонів нападників-Колкарів. Зустрівшись із Гезрулом на його власній землі, звитяжці Орди позбавляють кентаврів найважливішого прихистку й розривають їхню хватку на південних стежках краю."},{t="Небезпечні наслідки",b="Реґтар хвалить перемогу над Гезрулом, зауважуючи, що кентаврам бракує зосередженої дисципліни орків, але вбивство ватажка не втихомирює клан. Замість того щоб мирно розбігтися, розлючені Колкари збирають решту сил для відчайдушного повномасштабного нападу просто на табір Реґтара — у пошуках кривавої помсти."}},faq={{q="Хто такий Гезрул Бладмарк?",a="Гезрул Бладмарк — верховний вождь кентаврів Колкарів у Пустках. Орда знає його як лютого, хитрого й жорстокого ватажка, що зі своєї твердині в Оазі Буйних Вод керує різними кланами й рейдерами.",al={"хто такий гезрул","переказ про гезрула бладмарка","ватажок кентаврів пусток"}},{q="Де знайти Гезрула Бладмарка?",a="Гезрул ходить півднем Пусток берегами Оази Буйних Вод, на південь від Перехрестя, в оточенні охоронців-Колкарів.",al={"де гезрул","місце гезрула","де знайти гезрула"}},{q="Хто дає завдання вбити Гезрула?",a="Доручення дає Реґтар Дезґейт, орк-воїн у невеликому таборі на захід від Перехрестя, при дорозі до Гір Кам'яного Кігтя.",al={"хто дає гезрула бладмарка","завдання реґтара дезґейта","видавець гезрула"}},{q="Чому Орда хоче смерті Гезрула?",a="Колкари постійно загрожують торговим шляхам і поселенням Орди. Реґтар вірить, що знищення їхнього головного вождя розколе єдність клану й набагато послабить його здатність вести злагоджену війну.",al={"чому вбити гезрула","мета гезрула бладмарка","загроза колкарів у пустках"}},{q="Що буде після смерті Гезрула?",a="Замість здатися, вцілілі Колкари в сліпій люті об'єднуються й одразу йдуть у контрнаступ на заставу Реґтара Дезґейта на захід від Перехрестя.",al={"контратака після гезрула","що далі","наслідки вбивства гезрула"}},{q="Як Гезрул пов'язаний із Бараком і Вероґом?",a="Барак Кодобейн і Вероґ Дервіш були підлеглими ватажками Колкарів, що відали окремими оазами й загонами, а Гезрул Бладмарк був верховним ватажком, що командував усім кланом по всіх Пустках.",al={"барак вероґ гезрул","вожді колкарів","три ватажки кентаврів"}}},fp="16,272,23.452.0,24.397.0,21.356.1,24.230.0,36.136.0,35.148.0,36.221.0,35.164.1,42.210.0"}
P.entries["quest:853"] = {n="Аптекарка Замах",s="Це доручення змушує мандрівника мчати з посушливих Пусток до Тандер Блафа з нестійкою грибною емульсією. Аптекар Гелбрім хоче, щоб цю сильнодійну суміш якнайшвидше доставили його колезі, Аптекарці Замах, що ховається в похмурих глибинах під Узвишшям Духів.",h="Це доручення змушує мандрівника мчати з посушливих Пусток до Тандер Блафа з нестійкою грибною емульсією.",kw={"аптекарка замах","аптекар гелбрім","емульсія","озера видінь","узвишшя духів","королівське аптекарське товариство","тандер блаф"},ang={["faction:Horde"]="Швидкий зв'язок між заставами в Пустках і високим плато Тандер Блафа не дає розірватися ланцюгам постачання в краї.",["race:Tauren"]="Хоч таурени й прихильні до нових союзників, вірні звичаям члени племені часто скоса поглядають на дивні булькотливі зілля, які Відступники готують глибоко в священних Ставках Видінь.",["race:Undead"]="Доставивши працю Гелбріма до Замах, ви зміцнюєте таємну дослідницьку мережу, яку Королівське Аптекарське Товариство розкинуло курявними прикордонними землями центрального Калімдору."},sec={{t="Крихкий вантаж",b="Вивчивши дивні грибні нарости, що буяють довкола оаз Пусток, Аптекар Гелбрім виварює з них делікатну емульсію. Щойно її приготовано, нестійке вариво швидко втрачає силу. Самому вирушити до Малгора Гелбрімові ніколи, тож він довіряє пляшечку надійному гінцеві: той має піднятися на скелі, перш ніж розчин розгубить свою дію."},{t="Під поглядами шаманів",b="Аптекарка Замах облаштувала лабораторію далеко від відкритих рівнин Малгора — в усамітненні Ставків Видінь. Ця підземна печера лежить глибоко під священними висотами Узвишшя Духів, і ділять її потайні чорнокнижники та заглиблені в роздуми провидці. Тут, під самим святилищем тауренів, Королівське Аптекарське Товариство тихо провадить свої дослідження, використовуючи сировину, зібрану по всьому континенту."}},faq={{q="Чому на цю доставку є обмеження в часі?",a="Грибна емульсія, яку зварив Гелбрім, хімічно нестійка. Якщо надто довго тримати її відкритою чи необробленою, сполуки розпадаються й втрачають силу, і для роботи Замах суміш стає непридатною.",al={"чому є таймер","таймер завдання","таймер оброблених спор"}},{q="Де знайти Аптекарку Замах?",a="Аптекарка Замах — у Ставках Видінь у Тандер Блафі. Вхід до цієї печери трохи захований на Узвишші Духів і веде вниз, під намети шаманів.",al={"де замах","місце замах","знайти замах"}},{q="Хто такий Аптекар Гелбрім?",a="Аптекар Гелбрім — алхімік від Королівського Аптекарського Товариства на Перехресті в Пустках. Він досліджує місцеві рослини й тварин, щоб з'ясувати, як корінні організми Калімдору можуть прислужитися Відступникам.",al={"хто такий гелбрім","гелбрім на перехресті"}},{q="Що Королівське Аптекарське Товариство робить у Тандер Блафі?",a="Як союзники в Орді, Відступники тримають у Тандер Блафі своїх представників на кшталт Замах. Тихо працюючи в підземних Ставках Видінь, вони досліджують зразки, зібрані по всьому Калімдору, і підтримують зв'язки постачання з іншими заставами.",al={"чому відступники в тандер блафі","аптекарі в озерцях видінь"}},{q="Для чого спершу збирали грибні спори?",a="Спори ростуть довкола буйних оаз Пусток і неприродно розквітають серед пустелі. Гелбрім переробив їх, щоб вивчити їхні біологічні властивості й алхімічне застосування, а тоді передати Замах.",al={"навіщо спори","використання грибів пусток"}},{q="Що буде, якщо час вийде?",a="Якщо час сплине, емульсія розкладеться й зіпсується. Доведеться повернутися до Аптекаря Гелбріма на Перехресті по свіжу партію, щоб доставити її до Тандер Блафа.",al={"провалений таймер","спори зіпсувалися"}}},fp="16,277,15.372.0,30.416.0,43.195.0,34.185.0,26.219.0,60.243.0,48.214.0,35.165.0"}
P.entries["quest:854"] = {n="Подорож до Перехрестя",s="«Подорож до Перехрестя» — важливий обряд посвяти для молодих шукачів пригод з Орди, що покидають мирні луки Малгора. За вказівкою тауренського містика Кірґе Стернгорна в Таборі Тауражо мандрівники вирушають на північ, на Перехрестя, допомагати оркському наглядачеві Торкові. Це мить, коли новачок виходить на ширшу сцену рубежів Калімдору.",h="«Подорож до Перехрестя» — важливий обряд посвяти для молодих шукачів пригод з Орди, що покидають мирні луки...",kw={"подорож до перехрестя","кірґе стернгорн","торк","табір тауражо","малгор","перехрестя"},ang={["faction:Horde"]="Завдання показує, як поглиблюється співпраця між племенами Тандер Блафа й передовими загонами Вождя в центральному Калімдорі.",["race:Orc"]="Торк прагне підкріплення з півдня, щоб утримати хиткі позиції, які розвідники Тралла здобули в Пустках.",["race:Tauren"]="Для тауренів-шукачів пригод ця подорож знаменує справжнє прощання з прихистком священної столової гори Земної Матері й вихід у ширшу боротьбу Орди."},sec={{t="Покинути колиску",b="Для багатьох тауренів, що покидають рідний Малгор, Табір Тауражо — перше справжнє знайомство із суворими, продутими вітрами рівнинами Пусток. Відразу за гірським перевалом із Малгора містик Кірґе Стернгорн пильнує мандрівників, що спускаються в ці сухі степи. Відчуваючи їхню зростаючу силу, Стернгорн радить багатообіцяльним звитяжцям вирушати далі на північ запорошеним торговим шляхом, а не затримуватися на околиці."},{t="Спільні узи",b="Завдання підкреслює життєво важливі узи між тауренами Тандер Блафа й новою Ордою Тралла. Кірґе зауважує, що долі обох народів тепер переплетені, а оркам, які виборюють собі заставу на Перехресті, конче потрібне підкріплення. Коли мандрівники дістаються застави, Торк тепло вітає гостей аж із високих столових гір, охочих випробувати свою силу в боротьбі з небезпеками савани."}},faq={{q="Хто дає завдання «Подорож до Перехрестя»?",a="Завдання дає Кірґе Стернгорн, таурен із Табору Тауражо на півдні Пусток, трохи на схід від гірського перевалу з Малгора.",al={"хто дає це завдання","видавець завдання","завдання кірґе стернгорна"}},{q="Де знайти Торка?",a="Торк стоїть за частоколом Перехрестя — головного поселення Орди в Пустках, на північ головною дорогою від Табору Тауражо.",al={"де торк","місце торка","знайти торка"}},{q="Чому Кірґе Стернгорн посилає мандрівників на Перехрестя?",a="Кірґе відчуває, що шукач пригод готовий до більших випробувань, і розуміє, що доля тауренів і орків тепер переплетена. Гарнізон орків на Перехресті постійно відбиває місцеві загрози й гостро потребує вправних союзників.",al={"чому на перехрестя","призначення перехрестя","чому послати до орків"}},{q="Що таке Перехрестя?",a="Перехрестя — головний стратегічний осередок і торговий пункт Орди в центральному Калімдорі. Збудоване там, де перетинаються великі шляхи з півночі на південь і зі сходу на захід, воно слугує опорою для приборкання дикого прикордоння.",al={"що таке перехрестя","поселення перехрестя","центр пусток"}},{q="Чи це доручення дають лише тауренам?",a="Воно походить від таурена в Таборі Тауражо й згадує шлях із Тандер Блафа, але вирушити до Торка може будь-який молодий шукач пригод Орди, що прибув із Малгора.",al={"чи лише для тауренів","хлібні крихти орди"}},{q="Які загрози чатують на дорозі до Перехрестя?",a="Дорога на північ іде посушливими рівнинами, де водяться агресивні рівнинні довгоступи, крадуться саванні леви й блукають ватаги шипогривів Гостроманів. Хто тримається битого шляху, той оминає найревніших до своєї території хижаків центральної савани.",al={"чи дорога небезпечна","шлях з тауражо до перехрестя"}}},fp="25,350,18.434.0,13.437.0,37.151.0,23.155.0,58.252.0,23.228.0,33.203.0,52.245.0"}
P.entries["quest:855"] = {n="Наручі Кентавра",s="«Наручі Кентавра» — військова нагорода, яку пропонує Реґтар Дезґейт на захід від Перехрестя. Вона доручає звитяжцям Орди проредити ряди войовничих кентаврів-Колкарів, що оскаржують владу над центральними Пустками.",h="«Наручі Кентавра» — військова нагорода, яку пропонує Реґтар Дезґейт на захід від Перехрестя.",kw={"наручі кентавра","реґтар дезґейт","колкари","кентаври","нагорода","перехрестя"},ang={["faction:Horde"]="Винищення Колкарів захищає життєво важливі шляхи постачання між Оргріммаром і Тандер Блафом.",["race:Orc"]="Для орків захист околиць Дуротару від кочових нападників — запорука того, що нова батьківщина стане постійною й безпечною.",["race:Tauren"]="Кентаври століттями несли тауренським племенам спустошення й винищення; прорідити їхні лави в Пустках — особиста відплата."},sec={{t="Убезпечити рівнини",b="Молода Орда веде широку боротьбу за безпечні землі в Калімдорі, а Пустки — життєво важливе роздоріжжя між Дуротаром і Малгором. Проте жорстокі кочові племена кентаврів-Колкарів оскаржують кожен водопій і кожну рівнину, нападаючи на обози з припасами й розвідувальні загони. Зі свого бункера на захід від Перехрестя оркський воїн Реґтар Дезґейт керує обороною, щоб стримати їхній невпинний наступ."},{t="Моторошний облік",b="Порожнім доповідям Реґтар не вірить і вимагає відчутного доказу дій проти кінських племен. Воїнам, що вирушають на землі Колкарів, доручено приносити наручі, зняті просто з убитих кентаврів-воїнів. Цей похмурий облік слугує і підтвердженням для нагород Орди, і обдуманим посланням, що має залякати вцілілих нападників-Колкарів."}},faq={{q="Хто такий Реґтар Дезґейт?",a="Реґтар Дезґейт — орк-командир в укріпленому бліндажі на захід від Перехрестя. Він очолює місцеві зусилля Орди, щоб приборкати ватаги кентаврів-рейдерів по всіх Пустках.",al={"хто такий реґтар","переказ про реґтара дезґейта","хто дає наручі кентавра"}},{q="Навіщо Орді наручі кентаврів?",a="Наручі кентаврів — незаперечний речовий доказ ворожих воїнів, убитих у полі. Збираючи їх, Орда платить винагороду лише за справжні втрати, завдані ворожим племенам Колкарів.",al={"навіщо наручі","для чого наручі кентаврів","навіщо збирати наручі"}},{q="Чому Колкари нападають на Орду?",a="Колкари — жорстокий загарбницький клан кентаврів із центрального Калімдору. Вони вважають Пустки своїми мисливськими угіддями й запекло опираються новим поселенням, таборам і союзам орків і тауренів.",al={"чому кентаври ненавидять орду","конфлікт із кентаврами","агресія колкарів"}},{q="Де в Пустках табори кентаврів Колкарів?",a="Табори рейдерів Колкарів скупчуються довкола важливих оаз і порізаних хребтів у центрі й на півдні Пусток, де за доступ до води й шляхів раз у раз спалахують сутички.",al={"де знайти кентаврів","місця колкарів","табори кентаврів"}},{q="Чи збирання наручів зупиняє напади Колкарів?",a="Ні. Реґтар сподівається, що проріджування налякає вцілілих рейдерів, але відверто сумнівається, що дикі Колкари колись самі зупинять свої криваві наступи.",al={"чи наручі спрацювали","чи кентаври зупиняться"}},{q="Яке стратегічне значення має Перехрестя?",a="Перехрестя — головний вузол шляхів, що з'єднує батьківщину орків, Дуротар, рівнини тауренів у Малгорі й північні шляхи в Ашенваль. Знешкодити бойові загони кентаврів поблизу конче потрібно, щоб уберегти шляхи постачання Орди.",al={"чому захищати перехрестя","значення перехрестя"}}},fp="15,207,19.444.0,21.381.0,25.196.0,40.215.0,39.224.0,53.175.0,54.179.0,46.235.0"}
P.entries["quest:8569"] = {n="Минулі зусилля в Ущелині Бойової Пісні",s="«Минулі зусилля в Ущелині Бойової Пісні» — військова відзнака, яку здають офіцерам у столицях на знак визнання служби на передовій. Вона вшановує не беззастережну перемогу, а ветеранів, що звитяжно боролися й жертвували собою в спірних лісах Ашенвалю. Міські командири приймають ці знаки, щоб підтримувати бойовий дух і винагороджувати відданість в обох фракціях.",h="«Минулі зусилля в Ущелині Бойової Пісні» — військова відзнака, яку здають офіцерам у столицях на знак...",kw={"ущелина бойової пісні","ашенваль","стрічка самопожертви","вартові срібнокрилих","дозорці пісні війни","військова відзнака"},ang={["class:Warrior"]="Бійці передової, які вистояли в жорстокій рукопашній в ущелині, краще за будь-кого знають: справжня дисципліна — це битися люто навіть тоді, коли перемога висить на волосині.",["faction:Alliance"]="Для сил Альянсу стрічки, здані Бригадному Генералові, — це знову підтверджена присяга боронити прадавні ліси й підтримувати союзників, нічних ельфів, проти навали клану Пісні Війни.",["faction:Horde"]="Для Орди знаки, передані міським Воєводам, — доказ того, що кров, пролита за деревину й виживання в Ашенвалі, лилася не марно."},sec={{t="Шана полеглим і звитяжним",b="Війна між Вартовими Срібнокрилих і Дозорцями Пісні Війни рідко приносить чисті чи легкі перемоги. На південних рубежах Ашенвалю сутички жорстокі, криваві й часто закінчуються без вирішального тріумфу. Розуміючи, що бойовий дух не може триматися лише на бездоганних успіхах, командири Стормвінда, Оргріммара та інших столиць запровадили відзнаки за непохитну службу. Стрічка Самопожертви вшановує тих, хто кидався в бій, хоч би якими були шанси."},{t="Війна в тилу",b="Столичні урядовці — як-от Бригадні Генерали Альянсу й Воєводи Орди — керують мобілізацією далеко від передової. Поки вербувальники скеровують свіжу кров на поля битв на кшталт Ущелини Бойової Пісні, інтенданти й тактики мусять подбати про бійців, що повертаються з виснажливих походів. Визнаючи особисту відвагу й жертви навіть у нічиїх чи поразках, проводирі дбають, щоб вояки на передовій і далі тримали Ашенваль."}},faq={{q="Навіщо ця відзнака?",a="Відзнака вшановує бійців передової, які віддали всі сили в сутичках в Ущелині Бойової Пісні. Столичні командувачі приймають докази звитяжної боротьби, щоб винагородити витривалість і підтримати бойовий дух по всьому королівству.",al={"навіщо минулі зусилля","мета минулих зусиль","що значать минулі зусилля"}},{q="Хто приймає ці знаки жертовності?",a="Їх приймають старші військові посланці у великих містах — бригадні генерали Альянсу в містах на кшталт Стормвінда й Вісники Війни Орди в містах на кшталт Оргріммара.",al={"хто приймає минулі зусилля","куди здати минулі зусилля","хто бригадний генерал"}},{q="Чому військо винагороджує зусилля, що не принесли перемоги?",a="Командувачі розуміють, що безупинні бої в лісах Ашенвалю забирають тяжку данину. Винагорода за відданість і витримку нагадує бійцям, що їхню кров і жертви цінують, навіть коли битва не закінчилася повною перемогою.",al={"чому нагороджувати поразку","чому стрічка жертовності","сенс героїчних зусиль"}},{q="Де точиться боротьба за Ущелину Бойової Пісні?",a="Ущелина Бойової Пісні лежить на південному кордоні Ашенвалю, де орки — Дозорці Пісні Війни — заготовляють ліс і стикаються із запеклим опором нічних ельфів, Вартових Срібнокрилих.",al={"де ущелина бойової пісні","місце ущелини бойової пісні","що таке ущелина бойової пісні"}},{q="Чи можуть узятися за це і члени Альянсу, і Орди?",a="Так. Обидві фракції мають у своїх столицях рівноцінне військове командування, що вшановує вояків, які повертаються з кривавих сутичок за лісозаготівлі в Ашенвалі.",al={"чи це для обох фракцій","альянс чи орда минулі зусилля","чи орда може здати"}},{q="Що означає Стрічка Жертовності?",a="Стрічка Жертовності — відзнака, яку вручають бійцям, що витримали запеклі сутички в Ущелині Бойової Пісні, або яку ті носять при собі: вона свідчить про їхню непохитну готовність битися за свій народ.",al={"переказ про стрічку жертовності","що таке стрічка жертовності","стрічка жертовності"}}},fp="29,385,35.488.0,22.456.0,41.222.0,38.174.0,66.243.0,52.191.0,58.169.0,44.199.0"}
P.entries["quest:857"] = {n="Сльоза Місяців",s="Високо над південними Пустками збожеволілий дворф на ім'я Фіґлі Вигнанець вимагає повернути загадкову реліквію, відкопану в Бель Модані. Цей артефакт, відомий як Сльоза Місяців, довів Фіґлі до божевілля й одержимості, і Генерал Твінбрейд звелів замкнути його як лиховісне прокляття.",h="Високо над південними Пустками збожеволілий дворф на ім'я Фіґлі Вигнанець вимагає повернути загадкову...",kw={"сльоза місяців","фіґлі вигнанець","генерал твінбрейд","бель модан","ліга дослідників","троги"},ang={["faction:Horde"]="Удар по Бель Модану заради реліквії дає Орді змогу зірвати дворфійські роботи, що прямо зазіхають на Пустки."},sec={{t="Відкопана в Бель Модані",b="Коли дворфійські Шукачі з Ліги Дослідників почали врізатися в пагорби південного Калімдору, щоб збудувати Бель Модан, Сльоза Місяців стала їхньою першою великою знахідкою. Розкопки нібито мали простежити давню спадщину титанів, але дивний артефакт одразу здобув могутню й тривожну владу над Фіґлі, одним із робітників експедиції."},{t="Карантин Твінбрейда",b="Фіґлі запевняв, що Сльоза дарує йому величезну особисту силу, і люто накидався на товаришів, захищаючи свій скарб. Побачивши згубний вплив реліквії, Генерал Твінбрейд затаврував її як прокляту, вирвав із чіпких рук Фіґлі й надійно сховав у фортеці. Вигнаний із табору розкопок, Фіґлі знайшов притулок серед скель, де його роз'їдає гірка одержимість, і благає мандрівників викрасти реліквію назад."},{t="Страшна ціна",b="Застереження Твінбрейда виявляються куди буквальнішими, ніж гадав Фіґлі. Щойно Фіґлі отримує назад Сльозу Місяців, його радість обривається: прихована магія перетворення реліквії поглинає його. Замість того щоб звеличити дворфа, артефакт жорстоко перетворює його на дикого трога й обриває його життя за кілька миттєвостей після того, як він повернув свій скарб."}},faq={{q="Що таке Сльоза Місяців?",a="Це прадавня, могутня реліквія, яку дворфи-копачі відкопали під час перших розкопок у Бель Модані на півдні Пусток. Вона п'янить і розбещує тих, хто її торкається.",al={"що таке сльоза місяців","реліквія сльоза місяців","артефакт бель модана"}},{q="Хто такий Фіґлі Вигнанець?",a="Фіґлі колись був копачем в експедиції Генерала Твінбрейда в Бель Модані. Коли знайшли Сльозу Місяців, Фіґлі став одержимим і буйним, тож Твінбрейд вигнав його з фортеці.",al={"хто такий фіґлі","переказ про фіґлі","дворф фіґлі"}},{q="Чому Генерал Твінбрейд замикає Сльозу?",a="Генерал Твінбрейд побачив в артефакті небезпечне прокляття, а не безневинну історичну знахідку. Подивившись, як Фіґлі накинувся на товаришів-копачів, Твінбрейд надійно замкнув реліквію у твердині Бель Модану.",al={"чому твінбрейд замкнув сльозу","прокляття твінбрейда","реліквія фортеці бель модана"}},{q="Що буде, коли повернути Сльозу Фіґлі?",a="Повернена реліквія доводить одержимість Фіґлі до краю. Що буде далі, стає ясно, коли він бере її до рук.",al={"що з фіґлі","кінець фіґлі","повернути сльозу"}},{q="Чи до кінця зрозуміла магія Сльози?",a="Генерал Твінбрейд називає її проклятою, а Фіґлі прагне сили, яку вона нібито дає. Як саме діє магія реліквії, завдання не пояснює.",al={"магія сльози","прокляття сльози місяців","як діє сльоза"}},{q="Чому це завдання для Орди, якщо Фіґлі — дворф?",a="Фіґлі — вигнанець, що ховається в Пустках і зневажає сили Альянсу, які засіли в Бель Модані. Шукачі пригод Орди й так ворожі до розкопок Твінбрейда, тож Фіґлі просить саме їх напасти на твердиню й повернути артефакт.",al={"чому орда","чи фіґлі з орди","бель модан орда"}}},fp="21,290,23.375.0,22.417.0,17.336.1,30.194.0,25.209.0,46.232.0,48.116.1,37.149.1,47.238.0"}
P.entries["quest:858"] = {n="Запалювання",s="«Запалювання» починається, коли шукач пригод натрапляє на агента, що застряг у подрібнювачі Венчурної Компанії на півночі Пусток. Зопалу викравши машину без ключа запалювання, пілот потребує когось, хто принесе ключ від наглядача ділянки, перш ніж його розкриють.",h="«Запалювання» починається, коли шукач пригод натрапляє на агента, що застряг у подрібнювачі Венчурної...",kw={"запалювання","подрібнювач","венчурна компанія","спаттервалв","ключ запалювання","пустки"},ang={["faction:Horde"]="Безоглядне вирубування лісів Венчурною Компанією загрожує північним кордонам Пусток, тож будь-яка диверсія чи крадіжка їхньої важкої техніки лише на користь.",["profession:Engineering"]="Механіка подрібнювача Венчурної Компанії напрочуд досконала: тонке керування маніпуляторами й чутливі регулятори повороту перевершують звичайні вироби майстрів Раджета."},sec={{t="Пограбування пішло шкереберть",b="Глибоко серед метушливих бурових ділянок Венчурної Компанії на півночі Пусток честолюбне пограбування наштовхнулося на ганебну заминку. Агентові, якого прислав Спаттервалв, вдалося прослизнути в один із новітніх подрібнювачів корпорації, щоб захопити машину й вивчити її нутрощі. Проте злодій проґавив одну головну дрібницю: рульова й ходова колонка надійно заблокована без окремого ключа запалювання."},{t="Блеф під тиском",b="Коли підозріливий колега-гоблін спитав, чому щойно зайнятий подрібнювач стоїть без руху, зайда запанікував і збрехав про раптову поломку двигуна. Замкнений під скляним ковпаком кабіни, поки поруч никають цікаві робітники, викрадач просить шукачів пригод пробратися на центральну бурову вежу. Наглядач ділянки тримає запасні ключі запалювання в диспетчерській угорі — це єдиний квиток на волю, поки брехня не розкрилася."},{t="Корпоративна заздрість",b="Коли з наглядачем покінчено, а ключ повернуто в замку, злодій не так присоромлений, як зачарований. Керування подрібнювачем Венчурної Компанії — з точними важелями руху маніпуляторів, керуванням поворотом і стабілізаторами — далеко перевершує незграбні машини, що працюють нині в Раджеті. Повернути подрібнювач — уже не лише питання виживання: це безцінна здобич промислового шпигунства."}},faq={{q="Хто сидить у шредері?",a="Шредером керує агент, пов'язаний зі Спаттервалвом, інженером у нейтральному портовому містечку Раджет. Пілот пробрався на об'єкт Венчурної Компанії, щоб викрасти одну з її найновіших лісорубних машин.",al={"пілот шредера","хто в шредері","віззлкренк"}},{q="Чому шредер не може просто поїхати?",a="Без ключа запалювання ходова частина шредера механічно заблокована. Хоча викрадачеві вдалося залізти в кабіну, машина не зрушить і не втече, доки ключ не відімкне керування ходом.",al={"чому шредер не їде","чому потрібен ключ","шредер замкнений"}},{q="Де знайти Ключ Запалювання?",a="Ключ запалювання в наглядача Венчурної Компанії, що керує лісозаготівлею. Наглядач сидить у пункті керування на верхівці великої дерев'яної бурової вежі неподалік.",al={"де ключ запалювання","де наглядач","як знайти ключ"}},{q="Навіщо Раджету шредер Венчурної Компанії?",a="Венчурна Компанія має інженерні розробки, що набагато перевершують звичайні моделі, якими користуються інженери Раджета. Захопивши цілу машину, місцеві майстри зможуть розібрати її й відтворити тонке керування маніпуляторами, регулятори швидкості й системи стійкості.",al={"чому красти шредер","шредер раджета","шредер спаттервалва"}},{q="Хто такий Спаттервалв?",a="Спаттервалв — гоблін-інженер і агент із Раджета, що стежить за хижацьким поширенням Венчурної Компанії й прагне заволодіти її механічними винаходами.",al={"хто такий спаттервалв","хто послав віззлкренка","спаттервалв раджет"}},{q="Що буде, коли шредер заведено?",a="Поворот ключа відмикає ходову частину, і одразу починається шалений супровід: пілот намагається вивести викрадену машину з ворожого лісозаготівельного табору в безпечне місце.",al={"що далі після запалювання","після ключа запалювання","продовження запалювання"}}},fp="8,297,21.453.0,23.447.0,18.419.1,27.234.0,41.212.0,32.204.0,49.259.0,20.170.0,43.200.1"}
P.entries["quest:86"] = {n="Пиріг для Біллі",s="«Пиріг для Біллі» — доручення, що потрапило під перехресний вогонь давньої ворожнечі родин Стоунфілдів і Маклурів у Лісі Елвінн. Малий Біллі Маклур відмовляється розповідати про зникле намисто тітоньки Берніс Стоунфілд, поки не отримає навзамін пиріг з грудинкою. Шукачам пригод доведеться вполювати місцевих вепрів і зібрати м'ясо, щоб Берніс спекла вимаганий хабар.",h="«Пиріг для Біллі» — доручення, що потрапило під перехресний вогонь давньої ворожнечі родин Стоунфілдів і...",kw={"пиріг для біллі","біллі маклур","берніс стоунфілд","вепри","грудинка","кулінарія"},ang={["profession:Cooking"]="Тітонька Берніс зауважує: м'ясо дикого вепра буває жорстким і прісним, але правильні прянощі й повільне тушкування роблять із нього чудову начинку для пирога.",["race:Human"]="Ця сварка показує вперте, замкнуте суперництво, що квітне серед сільських господарів Елвінну просто на південь від брами Стормвінда."},sec={{t="Хабар для хлопчиська",b="Коли Біллі Маклура розпитують про крадіжку родинного намиста тітоньки Берніс Стоунфілд, він не виявляє й тіні каяття, на яке міг би сподіватися старший. Замість повернути реліквію чи зізнатися, хлопець користається з нагоди догодити своєму апетиту. Він вимагає свіжоспеченого пирога з грудинкою, перш ніж скаже бодай слово про те, у кого намисто, — чудово знаючи, що тітонька Берніс — найкраща куховарка в долині."},{t="Випічка попри давню кров",b="Маклури й Стоунфілди поколіннями обмінюються образами, бійками та звинуваченнями через гарбузові грядки. Хоч її глибоко обурює потреба годувати шибеника, який украв родинну прикрасу, тітонька Берніс погоджується розпалити піч. В обмін на ніжне м'ясо вепрів, уполюваних на сусідніх пасовищах, вона проковтує гордість, щоб задобрити неслухняного хлопця й повернути свій скарб."}},faq={{q="Чому Біллі хоче пирога, перш ніж говорити?",a="Біллі Маклур — хитрий фермерський хлопчак, що користається тим, що знає про вкрадене намисто Тітоньки Берніс. Знаючи, що Берніс пече чудові пироги зі свинячою грудинкою, він не скаже, в кого реліквія, доки не наїсться.",al={"чому біллі хоче пиріг","біллі хабар пирогом","пиріг біллі зі свинячою грудинкою"}},{q="Чому Тітонька Берніс погоджується пекти для злодія?",a="Тітонька Берніс шаленіє від того, що має винагороджувати того самого хлопчака, якого підозрює в крадіжці родинного намиста, але іншого способу його повернути не бачить. Тож вона неохоче погоджується спекти пиріг, коли їй принесуть вепрятину, ставлячи повернення свого добра вище за гордість.",al={"чому берніс пече","причина пирога берніс","стоунфілд пече для маклура"}},{q="Звідки м'ясо для пирога?",a="М'ясо — з диких вепрів, що пасуться на луках і узліссях довкола ферм Стоунфілдів і Маклюрів у Лісі Елвінн.",al={"де взяти м'ясо","джерело ніжного м'яса кабана"}},{q="Яка історія між Стоунфілдами й Маклюрами?",a="Стоунфілди й Маклюри — сусіди-фермери, що роками ведуть запеклу дріб'язкову ворожнечу й постійно підозрюють одне одного в крадіжках, шкодах і нечесних сварках через межу.",al={"ворожнеча стоунфілдів і маклюрів","суперництво ферм","маклури проти стоунфілдів"}},{q="Чи справді Біллі вкрав намисто?",a="Тітонька Берніс прямо звинувачує Біллі, і хоча він ухиляється від чесного зізнання, він явно знає, куди поділася реліквія, і міняє цю таємницю на їжу.",al={"чи біллі вкрав намисто","хто взяв намисто","біллі злодій намиста"}},{q="Що буде, коли Берніс отримає м'ясо?",a="Отримавши ніжну вепрятину, Тітонька Берніс пече пиріг зі свинячою грудинкою, який ви маєте віднести Біллі, щоб він нарешті сказав, у кого її намисто.",al={"наступний крок після пирога","що після пирога для біллі"}}},fp="13,365,13.436.0,24.422.0,41.237.0,50.262.0,42.126.0,57.222.0,38.174.0,41.161.0"}
P.entries["quest:860"] = {n="Серґра Даркторн",s="Довівши вправність у вистежуванні й скраданні на пагорбах Малгора, молоді таурени вирушають далі — у посушливу глушину Пусток. Мелор Стоунгуф посилає початківців-мисливців за межі рідного краю, до Серґри Даркторн на Перехресті. Ця подорож знаменує перехід мисливця від місцевих випробувань до суворого світу хижаків на широких рівнинах Калімдору.",h="Довівши вправність у вистежуванні й скраданні на пагорбах Малгора, молоді таурени вирушають далі — у...",kw={"серґра даркторн","мелор стоунгуф","перехрестя","пустки","мисливець","малгор","село бладгуф"},ang={["class:Hunter"]="Ця подорож — ваш випуск із полювання на місцеву дичину: далі на вас чекають агресивні хижаки й суворі умови внутрішніх саван Калімдору.",["faction:Horde"]="Перехрестя — живе серце постачання молодої Орди: тут під пильним оком ветеранів на кшталт Серґри поєднуються орківська витривалість, хитрість тролів Темного Спису й традиції тауренів.",["race:Tauren"]="Для тауренів, що виросли на зелених пасовищах Малгора, прибути до Серґри — це перший серйозний вихід за межі прабатьківських земель, на вимогливу службу всій Орді."},sec={{t="Прощання зі священними пагорбами",b="Для молодого таурена, що обрав шлях мисливця, перші обряди в Малгорі — лише початок. Пишні долини прабатьківщини захищені й знайомі, а тутешні звірі випробовують радше терпіння, ніж уміння вижити. Мелор Стоунгуф бачить, коли дух мисливця визріває для суворіших випробувань. Він велить учням зібрати спорядження, покинути безпечне Село Бладгуф і вирушити на схід крізь гірський перевал — у випалені сонцем чагарники Пусток."},{t="Дорога до Перехрестя",b="Стежка червоними кам'яними каньйонами виводить просто до широкої, випаленої сонцем савани, де молода Орда застовпує свої землі. На перетині головних торгових шляхів Калімдору лежить Перехрестя — укріплене поселення, де вирує життя орків, тролів і тауренів. Там чекає Серґра Даркторн, досвідчена шаманка з орків, відома своєю невблаганною вимогливістю. Вона стає наставницею кожному, хто наважиться полювати на лютих звірів Пусток, і обіцяє загартувати сирий запал у справжню дисципліну мисливця глушини."}},faq={{q="Хто дає це завдання і де його знайти?",a="Завдання дає Мелор Стоунгуф, таурен — наставник мисливців, що живе на Узвишші Мисливців у Тандер Блафі.",al={"хто дає серґру даркторн","місце мелора стоунхуфа","з чого почати"}},{q="Де знайти Серґру Даркторн?",a="Серґра Даркторн стоїть на Перехресті в центрі Пусток, на східному боці поселення, біля сторожових веж і загонів для худоби.",al={"місце серґри даркторн","де серґра","знайти серґру"}},{q="Як дістатися з Малгора до Перехрестя?",a="Вирушайте з Тандер Блафа на південь повз Село Бладгуф, а тоді східною дорогою з Малгора через перевал у каньйоні — до Пусток. За прикордонною брамою йдіть головною ґрунтовою дорогою на схід до роздоріжжя, а тоді на північ, аж до Перехрестя.",al={"напрям до перехрестя","з мулґору в пустки","як дістатися перехрестя з тандер блафа"}},{q="Навіщо це завдання?",a="Це завдання-дороговказ, що веде гравців, які почали свій шлях у Малгорі, до наступного великого осередку — Перехрестя в Пустках — і знайомить їх із місцевими мисливськими завданнями.",al={"навіщо це завдання","мета серґри даркторн","чи це хлібні крихти"}},{q="Чи дають це завдання оркам і тролям?",a="Орки й тролі отримують у Дуротарі схоже завдання-дороговказ «Доброволець Орди», що посилає їх до Пусток із Гострого Пагорба, хоча й вони, прибувши, можуть зустріти Серґру й брати в неї завдання.",al={"версія для орків","версія для тролів","хлібні крихти дуротару"}},{q="Чого Серґра Даркторн навчає мисливців?",a="Серґра перевіряє новоприбулих мисливців на місцевих звірах Пусток — починаючи з рівнинних довгоступів і скрадачів — і вчить, що справжня майстерність потребує витривалості, шани до землі й душевної стійкості, а не грубої сили.",al={"роль серґри","що робить серґра","полювання серґри"}}},fp="16,405,24.484.0,26.510.0,46.110.0,34.154.0,44.263.0,34.198.0,34.217.0,41.232.0"}
P.entries["quest:861"] = {n="Шлях мисливця",s="«Шлях мисливця» — обряд посвяти, який старійшина Скорн Вайтклауд пропонує майбутнім слідопитам у Малгорі. Щоб довести свою нову вправність і повагу до дикої природи, мандрівники мають здолати хитрих рівнинних скрадачів і піднести їхні пазурі Мелору Стоунгуфу на Узвишші Мисливців у Тандер Блафі.",h="«Шлях мисливця» — обряд посвяти, який старійшина Скорн Вайтклауд пропонує майбутнім слідопитам у Малгорі.",kw={"шлях мисливця","скрадачі","пазурі","скорн вайтклауд","мелор стоунгуф","узвишшя мисливців","тандер блаф"},ang={["class:Hunter"]="Випробування прямо перевіряє основи дикого краю: вистежити хижака-засідника, перш ніж він ударить першим, і читати ледь помітні знаки трав.",["faction:Horde"]="Цей обряд — міст для союзних мандрівників Орди, щоб зрозуміти тауренську шану до природи й здобути їхню довіру на висотах Тандер Блафа.",["race:Tauren"]="Для молодих тауренів піднести пазурі скрадачів на Узвишші Мисливців — основоположний обряд посвяти, що єднає їх із поколіннями предків, які полювали на цих самих розлогих рівнинах."},sec={{t="Традиція рівнин",b="Для тауренів полювання — не розвага й не простий прожиток: його мають за одну з найвищих почестей свого народу. Воно вимагає терпіння, усвідомлення рівноваги Земної Матері й шани до звірів, що блукають пагорбистими рівнинами. Старійшина Скорн Вайтклауд, що відпочиває в Малгорі після десятиліть вистежування по всьому Калімдору, упізнає цей неспокій у молодих шукачах пригод. Замість дозволити їм блукати без мети, він спрямовує їхнє честолюбство в традиційне випробування зрілості й дисципліни."},{t="Скрадачі трав'яних рівнин",b="Щоб довести, що їхнє чуття слідопита справжнє, претендентам доручають здолати рівнинних скрадачів Малгору. Ці великі коти — прудкі, потайні й хитрі хижаки-засідники, що легко зливаються з високою травою рівнин. Чотири пари пазурів доводять: молодий мандрівник уміє помітити хижака, перш ніж стати здобиччю, і обернути лють мисливця проти нього самого."},{t="Дістатися Узвишшя Мисливців",b="Здобувши трофеї, посвячений підіймається високими дерев'яними вежами й мостами, що ведуть у Тандер Блаф. Там, на Узвишші Мисливців, пазурі приймає Мелор Стоунгуф. Як майстер-слідопит, що цінує прадавню мудрість Скорна Вайтклауда, Стоунгуф приймає підношення як доказ: посвячений має належний дух, щоб його вели далі мисливськими стежками Калімдору."}},faq={{q="Хто доручає пройти Шлях мисливця?",a="Завдання дає Скорн Вайтклауд, шанований таурен-мандрівник рівнин, що спочиває в Малгорі й наставляє молодих шукачів пригод, які хочуть опанувати дику природу.",al={"видавець завдання","хто дає завдання","скорн вайтклауд"}},{q="Кому віднести кігті рівнинних скрадачів?",a="Віднесіть кігті Мелорові Стоунгуфу, що живе на Узвишші Мисливців у столиці тауренів, Тандер Блафі.",al={"де мелор стоунхуф","місце здачі","піднесення мисливців"}},{q="Чому даниною обрано кігті рівнинних скрадачів?",a="Рівнинні скрадачі — потайливі й небезпечні верховні хижаки луків Малгора. Вистеживши й здолавши їх, учень доводить, що має гостре око, терпіння й бойову дисципліну, потрібні для вищого мисливського мистецтва.",al={"чому кігті рівнинних скрадачів","кігті скрадачів","що таке скрадачі"}},{q="Чи це завдання лише для класу Мисливець?",a="Ні. Попри назву, Скорн Вайтклауд пропонує це випробування рішучості будь-якому молодому шукачеві пригод Орди, що прагне мандрувати й пізнавати традиції рівнин.",al={"чи лише мисливці","чи інші класи можуть це","чи це для мисливців"}},{q="Куди веде шлях мисливця після розмови з Мелором?",a="Щойно Мелор Стоунгуф помітить ваш хист, він почне скеровувати вас у суворіші краї Пусток, а згодом — до досвідчених слідопитів на кшталт Серґри Даркторн.",al={"що далі","наступне завдання","куди йти після мелора"}},{q="Яке значення має полювання в культурі тауренів?",a="За віруваннями тауренів, полювання — одна з найвищих почестей. Воно вимагає жити в цілковитій злагоді з творінням Земної Матері, брати лише потрібне й глибоко шанувати здобич, що годує їхні племена.",al={"переказ про полювання тауренів","честь полювання","чому полювання важливе для тауренів"}}},fp="16,291,25.509.0,30.399.0,20.391.0,45.165.0,43.105.0,53.238.0,50.170.0,61.211.1,54.224.0"}
P.entries["quest:862"] = {n="Рагу з Норової Щурятини",s="«Рагу з Норової Щурятини» — кулінарне доручення від Личинки, орка, що отаборився на схід від Перехрестя в Пустках. Щоб угамувати ситний пустельний апетит, Личинка посилає голодних шукачів пригод на південь, до дворфійських розкопок у Бель Модані, — наловити гладких норових щурів для сумнівного рагу.",h="«Рагу з Норової Щурятини» — кулінарне доручення від Личинки, орка, що отаборився на схід від Перехрестя в...",kw={"рагу з норової щурятини","личинка","норові щури","бель модан","кулінарія","перехрестя"},ang={["faction:Horde"]="Ловити норових щурів у Бель Модані — приємний спосіб покепкувати з дворфійських розкопок і заразом розжитися харчами на півдні Пусток.",["profession:Cooking"]="Приготування Рагу з Норової Щурятини вчить простого прикордонного добування їжі: набридливі кар'єрні шкідники стають ситною, хоч і смердючою, стравою біля багаття.",["race:Undead"]="Звичка Личинки давати м'ясу тижнями гнити перед варінням робить його одним із небагатьох живих кухарів, чиї смаки збігаються зі смаками Відступників."},sec={{t="Делікатеси Пусток",b="Щоб вижити на посушливих просторах Пусток, треба не перебирати в їжі. Поки бувалі мисливці валять жевр, степових довгоступів і рапторів, самотній орк Личинка розвинув дивну пристрасть до підземних гризунів. Запевняючи, що цілісінький день помирає з голоду, Личинка обіцяє поділитися власним рецептом із кожним мандрівником, готовим узятися за непоказну справу щуроловства."},{t="Дворфійські шкідники",b="Джерелом цих тварин обрано Бель Модан — величезні розкопки Альянсу глибоко на півдні Пусток. Поки дворфійські шукачі шматують червону землю в пошуках давніх реліквій, їхні глибокі кар'єри ненароком розворушили гнізда плідних норових щурів. Дворфи вважають цих дрібних гризунів напастю, а Личинка — бенкетом, який гріх проґавити, та ще й просто під носом у ворога."},{t="Справа смаку",b="Щоб приготувати Рагу з Норової Щурятини, потрібен міцний шлунок. За словами Личинки, гризуни найсмачніші, якщо дати їм кілька тижнів погнити, щоб вийшов гострий присмак. Хоч він і задовольняється свіжішими зразками, щоб нагодувати голодного шукача пригод на місці, його кухарські прийоми показують, якою грубою й невибагливою буває придорожня кухня на рубежах Калімдору."}},faq={{q="Хто такий Личинка?",a="Личинка — дивакуватий орк, що стоїть при стежці на схід від Перехрестя в Пустках. Вічно голодний, він відомий своїми незвичними кулінарними смаками й охоче вчить мандрівних шукачів пригод готувати місцевих гризунів.",al={"личинка","хто такий личинка","орк на схід від перехрестя"}},{q="Звідки беруться норові щурі?",a="Норові щурі кишать у Бель Модані — розкопках Альянсу на крайньому півдні Пусток, на південь від Табору Тауражо й на північ від Рейзорфен Краула. Загарбницькі розкопки дворфів сколихнули землю й привабили зграї цих дрібних тварин.",al={"де норові щурі","місце норових щурів","знайти норових щурів"}},{q="Чому Личинці потрібні саме норові щурі?",a="Личинка вважає їх «улюбленою стравою всіх» і запевняє, що полювання на гризунів — обряд посвяти для кожного досвідченого шукача пригод. Вони — головний складник його ситного, хоч і запашного рагу.",al={"чому щурі","чому норові щурі","мотивація личинки"}},{q="Чи Рагу з Норової Щурятини справді смачне?",a="На думку Личинки, воно чудове, але смаки в нього вкрай своєрідні. Він відверто зізнається, що любить, коли м'ясо кілька тижнів погниє, — так смак яскравіший, — тож навіть за суворими мірками Орди ця страва на любителя.",al={"чи рагу смачне","їсти норових щурів","смак рецепта личинки"}},{q="Що дворфи роблять у Бель Модані?",a="Дворфи Бель Модану належать до Ліги Дослідників Альянсу: вони риють глибокі траншеї в Пустках, шукаючи прадавні артефакти титанів і підземну історію. Їхня присутність загострила напругу з Ордою й сколихнула місцевих гризунів.",al={"дворфи в пустках","чому бель модан","альянс на півдні пусток"}},{q="Чи треба особливо вчитися кулінарії, щоб зварити рагу?",a="Для науки Личинки досить основ домашнього куховарства й уміння розбирати дичину. Кожен, хто бодай трохи куховарив, перейме його спосіб тушкувати гризунів у ситну страву.",al={"вимога кулінарії","чи потрібна кулінарія"}}},fp="12,278,18.378.0,18.428.0,18.371.0,12.222.0,28.250.0,41.201.0,37.237.0,36.255.0,55.200.0"}
P.entries["quest:863"] = {n="Втеча",s="«Втеча» — завдання із супроводом на півночі Пусток: шукачі пригод допомагають гоблінові-пілоту Візлкренку втекти з бурової ділянки Венчурної Компанії на Багнистому Болоті. Замкнений у викраденому дослідному подрібнювачі, Візлкренк потребує захисту від хвиль найманців компанії, доки не вибереться з промислового котловану. Завдання завершується доповіддю його посередникові Спаттервалву в портовому містечку Раджет.",h="«Втеча» — завдання із супроводом на півночі Пусток: шукачі пригод допомагають гоблінові-пілоту Візлкренку...",kw={"втеча","пілот візлкренк","подрібнювач","венчурна компанія","спаттервалв","супровід"},ang={["faction:Horde"]="Брудні нафтові промисли Венчурної Компанії на Багнистому Болоті — більмо на оці Пусток, тож місцеві племена радо вітають будь-яку диверсію.",["profession:Engineering"]="Дослідний подрібнювач демонструє новітню пневматику й конструкцію кабіни Венчурної Компанії, тож його рештки — справжня золота жила промислових знань.",["race:Gnome"]="Готовність Візлкренка навмання кермувати вкрай нестабільною машиною Венчурної Компанії показує, що гобліни-майстри, як і гномські, часто спершу майструють, а вже потім ставлять запитання."},sec={{t="Незграбна втеча",b="Запустивши викрадений дослідний зразок глибоко на буровій ділянці Багнистого Болота, Візлкренк швидко з'ясовує, що захопити техніку Венчурної Компанії легше сказати, ніж зробити. Ледве тямлячи у важелях і перемикачах, гоблін ривками веде важку машину грязьким дном кар'єру. Його хаотичне кермування й гуркіт механічних суглобів неминуче привертають увагу робітників і озброєних вартових поблизу, і те, що мало бути тихою втечею, обертається безладним бігом із боєм угору західним схилом котловану."},{t="Погоня Венчурної Компанії",b="Венчурна Компанія не прощає крадіжки фірмових дослідних зразків. Поки машина видирається схилом до відкритої місцевості, загони найманців компанії висуваються, щоб перехопити й знерухомити втікача. Хоч дослідний зразок і відбивається, незграбна машина не витримає злагодженої диверсії без сторонньої охорони. Вибравшись за край, машина вивалюється з головної бурової западини, хоча невдовзі по тому зазнає критичної поломки."},{t="Рештки й винагорода",b="Щойно вибравшись із безпосередньої небезпеки, дослідний подрібнювач остаточно ламається й падає на траву савани. Візлкренк вилазить живим і просить рятівників доповісти Спаттервалву в Раджеті, а сам лишається біля уламків. Спаттервалв, якому кортить розібрати новітні розробки Венчурної Компанії, поки нагода не минула, одразу посилає гоблінську бригаду, щоб доправити до порту все, що вціліло з механізмів."}},faq={{q="Хто такий Віззлкренк і чому він у шредері?",a="Віззлкренк — агент і механік, що працює зі Спаттервалвом у Раджеті. Він пробрався на північну бурову ділянку Венчурної Компанії, щоб викрасти найновіший дослідний зразок шредера, але застряг усередині, намагаючись розібратися з незнайомим керуванням у кабіні.",al={"хто такий віззлкренк","чому гоблін у шредері","віззлкренк шредер"}},{q="Де відбувається ця втеча?",a="Супровід починається глибоко в Багнистому Болоті — забрудненому промисловому буровому майданчику Венчурної Компанії на півночі Пусток, трохи на північ від сухої улоговини савани.",al={"де втеча","місце втечі","супровід болота слизу"}},{q="Чи треба супроводжувати шредер аж до Раджета?",a="Ні. Ви лише виводите Віззлкренка з котловану бурової й піднімаєтеся західним схилом. Щойно ви відійдете від краю кар'єру, машина ламається, і Віззлкренк просить вас самостійно доповісти в Раджеті.",al={"як далеко йти","шлях супроводу","чи йти до раджета"}},{q="Хто такий Спаттервалв?",a="Спаттервалв — гоблін-технік, що стоїть біля причалів у Раджеті. Він збирає промислові розвідані проти суперницької Венчурної Компанії й полює на її механічні розробки, щоб заробити на її технічних нововведеннях.",al={"хто спаттервалв","здати спаттервалву","переказ про спаттервалва"}},{q="Чому шредер наприкінці перекидається?",a="Віззлкренк ледве знає керування, а дослідна машина під час засідки працює на межі можливостей. Проламуючись крізь периметр, вона зазнала тяжкого механічного навантаження, тож зразок здає, щойно вибирається з бурової ділянки.",al={"чому шредер ламається","шредер розбитий","невдача прототипу"}},{q="Що буде, коли зразок розбився?",a="Віззлкренк лишається біля поваленої машини, а ви доповідаєте Спаттервалвові в Раджеті. Спаттервалв одразу збирає гоблінську команду, щоб зняти цінні вузли зразка, перш ніж Венчурна Компанія встигне їх забрати.",al={"команда відновлення","що далі","кінець втечі"}}},fp="10,410,16.537.0,23.516.0,18.476.1,51.270.0,34.173.0,58.215.1,20.227.0,43.261.1,41.236.1"}
P.entries["quest:8642"] = {n="Старійшина Сільвервейн",s="Старійшина Сілвервейн — шанований дух предка, що з'являється під час Місячного фестивалю на пагорбах над Телсамаром у Лох Модані. Мандрівники віддають йому шану, вшановуючи давні зв'язки між старшими народами Азероту. За визнання його присутності й спадщини він дарує своє благословення предків.",h="Старійшина Сілвервейн — шанований дух предка, що з'являється під час Місячного фестивалю на пагорбах над...",kw={"старійшина сілвервейн","місячний фестиваль","телсамар","предки","лох модан","старійшини"},ang={["faction:Alliance"]="Для мандрівників Альянсу, що проходять Лох Моданом, підйом на кряж над Телсамаром — тиха перерва в полюванні на трогів, щоб ушанувати давніх предків.",["race:Dwarf"]="Старійшина Сілвервейн спочиває просто біля дворфійського Телсамара, тож відчуває вдячну спорідненість із суворим кам'яним народом і його шаною до давньої історії."},sec={{t="Варта над Телсамаром",b="Старійшина Сілвервейн стоїть на пологих кряжах над Телсамаром — тихий охоронець і нагадування про давнину. Як постать, яку вшановують під час Місячного фестивалю, він уособлює незгасну пам'ять про минулі віки. Навіть коли навколишні землі Лох Модану борються з навалою трогів і місцевими чварами, Сілвервейн спокійно споглядає все зі своєї висоти."},{t="Шана старшим народам",b="Духи на кшталт Сілвервейна перекидають місток між нинішніми народами й давніми родоводами. Коли шукачі пригод розшукують його, він дякує, що мандрівники досі віддають шану старшим народам Азероту. Його привітання сповнене тепла вдячних предків, і тим, хто його вшановує, він дарує пам'ятний знак."}},faq={{q="Хто такий Старійшина Сілвервейн?",a="Старійшина Сілвервейн — дух предків, що з'являється під час Місячного фестивалю. Цей час він проводить на високих кручах біля Телсамара в Лох Модані.",al={"сілвервейн","хто такий сілвервейн","старійшина сілвервейн лох модан"}},{q="Де знайти Старійшину Сілвервейна?",a="Він — на трав'янистому пагорбі, з якого видно містечко Телсамар у Лох Модані.",al={"місце сілвервейна","де старійшина сілвервейн","знайти сілвервейна"}},{q="Навіщо шукати Старійшину Сілвервейна?",a="Шукачі пригод навідуються до нього під час Місячного фестивалю, щоб віддати шану предкам і прадавнім расам, і отримують натомість святковий знак і благословення.",al={"навіщо шукати сілвервейна","що робить сілвервейн","мета сілвервейна"}},{q="Що він має на увазі під «прадавніми расами»?",a="Він говорить про давні народи Азероту, що жили й творили світ задовго до того, як на перший план вийшли сучасні протистояння, і шанує незгасний дух їхньої спадщини.",al={"що значить прадавні раси","чому прадавні раси"}},{q="Чи прихильний Старійшина Сілвервейн до мандрівників Орди?",a="Так. Старійшини-предки, яких шанують під час Місячного фестивалю, вітають мандрівників будь-якого походження, що приходять із миром ушанувати предків.",al={"чи орда може говорити з сілвервейном","сілвервейн і орда"}},{q="Чи пов'язаний Старійшина Сілвервейн із навалою трогів?",a="Ні. Хоча Лох Модан потерпає від набігів трогів і клопотів із копачами, Старійшина Сілвервейн цілком осторонь місцевих військових сутичок і думає лише про шанування предків.",al={"сілвервейн і троги","чи сілвервейн б'ється з трогами"}}},fp="20,324,22.358.0,24.340.0,24.162.0,34.83.0,52.158.0,39.170.0,48.134.0,64.186.0"}
P.entries["quest:8646"] = {n="Старійшина Гаммершаут",s="Старійшина Гаммершаут — прадавній дух, якого відвідують під час Місячного фестивалю; він стоїть у Парку Стормвінда. Він винагороджує мандрівників, що зупиняються вшанувати його народ і виявити шану поважній спадщині старших рас Азерота. Його присутність нагадує про давні зв'язки навіть у серці людських земель.",h="Старійшина Гаммершаут — прадавній дух, якого відвідують під час Місячного фестивалю; він стоїть у Парку...",kw={"старійшина гаммершаут","місячний фестиваль","стормвінд","парк","предки","старійшини"},ang={["faction:Alliance"]="Герої Альянсу, що навідуються до Парку, знаходять у Гаммершауті нагадування про шану, мир і спільне минуле предків усього світу.",["faction:Horde"]="Дістатися до Гаммершаута — зухвалий виклик для прочан Орди: щоб ушанувати духів, доведеться пробратися в Стормвінд і дійти аж до Парку.",["race:Human"]="Стоячи в Парку Стормвінда, Гаммершаут нагадує людям, що варто шанувати глибшу історію Азерота, давнішу за їхнє сучасне королівство."},sec={{t="Шана давній крові",b="Під час Місячного фестивалю духи шанованих предків з'являються по всьому Азероту й дарують мудрість і благословення кожному мандрівникові, який знайде час віддати їм шану. Старійшина Гаммершаут з'являється в Парку Стормвінда. Хоч він стоїть біля серця сучасної людської цивілізації, його поява нагадує шукачам пригод про часи, коли світ формували прадавні раси, які ходили цією землею задовго до піднесення теперішніх королівств."},{t="Знаки шани до предків",b="Привітати Старійшину Гаммершаута — це не бойове випробування й не небезпечна клятва, а просте визнання минулого. Він із тихим полегшенням і вдячністю бачить, що нинішні мешканці краю досі знаходять час ушанувати стародавні раси. В обмін на цей акт пам'яті й поваги Старійшина дарує мандрівникам церемоніальний знак — символ нерозривного зв'язку між живим поколінням і духами, що були до них."}},faq={{q="Хто такий Старійшина Гаммершаут?",a="Старійшина Гаммершаут — дух предків, що з'являється під час Місячного фестивалю. Він уособлює прадавні роди Азероту й стоїть у Стормвінді, щоб дарувати благословення й знаки тим, хто його вшанує.",al={"гаммершаут","хто такий гаммершаут","особа старійшини гаммершаута"}},{q="Де знайти Старійшину Гаммершаута?",a="Під час Місячного фестивалю Старійшина Гаммершаут з'являється в Парку Стормвінда.",al={"місце гаммершаута","де гаммершаут","гаммершаут елвінн"}},{q="Чому Старійшина Гаммершаут згадує «прадавні раси»?",a="Його слова відбивають суть Місячного фестивалю — шанування давнини й предків, прадавніх народів і традицій, що творили Азерот задовго до появи нинішніх поселень.",al={"що значить прадавні раси","що має на увазі гаммершаут"}},{q="Який знак дає Старійшина Гаммершаут?",a="Він дає Монету Роду — урочистий знак, яким духи Місячного фестивалю винагороджують тих, хто шукає старійшин і віддає їм шану.",al={"нагорода гаммершаута","знак гаммершаута","що він дає"}},{q="Чи можуть шукачі пригод Орди поговорити зі Старійшиною Гаммершаутом?",a="Так. Духи предків під час Місячного фестивалю стоять понад війною фракцій, хоча мандрівникам Орди варто бути обережними, адже він перебуває в самому Стормвінді, столиці Альянсу.",al={"чи орда може говорити з гаммершаутом","гаммершаут орда"}},{q="Чи ця зустріч пов'язана зі святом?",a="Старійшина Гаммершаут з'являється лише під час щорічного Місячного фестивалю: він приходить ненадовго, щоб дарувати благословення, а тоді повертається у світ духів.",al={"чи гаммершаут завжди там","старійшина місячного фестивалю"}}},fp="21,329,22.465.0,29.457.0,25.203.0,37.86.0,53.199.0,40.146.0,51.182.0,44.151.0"}
P.entries["quest:8648"] = {n="Старійшина Даркор",s="«Старійшина Даркор» — сезонне завдання, яке можна зустріти під час Місячного фестивалю в Андерсіті. Розшукавши Старійшину Даркора, мандрівники віддають шану давнім духам, яких вшановують по всьому Азероту, і отримують за це Монету Роду.",h="«Старійшина Даркор» — сезонне завдання, яке можна зустріти під час Місячного фестивалю в Андерсіті.",kw={"старійшина даркор","місячний фестиваль","монета роду","духи предків","андерсіті","свято"},ang={["faction:Horde"]="Завдяки Старійшині Даркору члени Орди можуть долучитися до обрядів Місячного фестивалю, що проходять по всьому континенту, просто в безпеці союзної столиці.",["race:Undead"]="Для Відступників, що ходять руїнами власного колишнього королівства, Старійшина Даркор — моторошний відголос давніших часів, ще до Погибелі й падіння Лордерона."},sec={{t="Дух в Андерсіті",b="Під час Місячного фестивалю духи давніх предків — нічних ельфів і земнородних — з'являються на всіх континентах, щоб поділитися мудрістю й благословенням. Старійшина Даркор перебуває в затінених залах Андерсіті: він споглядає теперішній світ і дарує пам'ять тим, хто шукає коренів цього світу."},{t="Шана предкам",b="Прийти до Старійшини Даркора — це сповнити давній звичай шанувати достойних померлих і одвічних сторожів Азероту. На знак того, що ви здолали цей шлях, дух дарує вам Монету Роду — символ доброї волі й невмирущої пам'яті."}},faq={{q="Навіщо навідуватися до Старійшини Даркора?",a="Відвідавши Старійшину Даркора під час Місячного фестивалю, шукачі пригод можуть ушанувати прадавні народи Азероту. Розмова з ним завершує завдання й приносить Монету Роду.",al={"мета старійшини даркора","навіщо йти до даркора","мета завдання даркора"}},{q="Де знайти Старійшину Даркора?",a="Старійшина Даркор з'являється в зруйнованій тронній залі Лордерону, над столицею Відступників, Андерсіті.",al={"місце старійшини даркора","де даркор","даркор андерсіті"}},{q="Що таке Місячний фестиваль?",a="Місячний фестиваль — щорічна пора пам'яті й оновлення по всьому Азероту: тоді святкують перемогу над Палаючим Легіоном і шанують прадавніх старійшин, що вели смертні раси.",al={"переказ про місячний фестиваль","чому з'являються старійшини","хто старійшини"}},{q="Що уособлюють старійшини?",a="Старійшини — прадавні духи, здебільшого пов'язані з нічними ельфами чи давніми народами землян; під час Місячного фестивалю вони приходять, щоб благословити тих, хто пам'ятає їхні діяння й несе далі уроки давнини.",al={"хто такі старійшини","старійшини місячного фестивалю","духи предків"}},{q="Чи можуть шукачі пригод Альянсу поговорити зі Старійшиною Даркором?",a="Старійшина Даркор привітає кожного мандрівника, що зуміє до нього дістатися, але гравцям Альянсу доведеться пробратися через пильно стережену столицю Відступників.",al={"даркор альянс","чи альянс може даркора","старійшина даркор альянс"}},{q="Що таке Монета Роду?",a="Монета Роду — святковий знак, який старійшини дарують під час Місячного фестивалю: він уособлює шану до давнини, і його можна обміняти на святкове вбрання й сезонні пам'ятки.",al={"що таке монети роду","монета роду","монета місячного фестивалю"}}},fp="18,238,25.321.0,22.257.0,47.185.0,34.109.0,27.202.0,29.211.0,49.147.0,27.173.0"}
P.entries["quest:8649"] = {n="Старійшина Стормброу",s="Старійшина Стормброу — один із прадавніх духів, яких шанують під час Місячного фестивалю; він стоїть біля води неподалік Ґолдшира. Мандрівники, що розшукують цього старійшину, віддають шану давнім традиціям і стародавнім расам Азерота. У відповідь на виявлену повагу старійшина дарує невеликий пам'ятний знак.",h="Старійшина Стормброу — один із прадавніх духів, яких шанують під час Місячного фестивалю; він стоїть біля...",kw={"старійшина стормброу","місячний фестиваль","ґолдшир","дух","предки","ліс елвінн"},ang={["faction:Alliance"]="Старійшина Стормброу, що відпочиває в самому серці Лісу Елвінн, — один із найдоступніших духів предків для молодих шукачів пригод Альянсу, які проходять через Ґолдшир.",["race:Human"]="Для людей Елвінну присутність Старійшини Стормброу — нагадування про давню історію поза мурами й недавніми війнами Стормвінда."},sec={{t="Дух у Ґолдширі",b="Старійшина Стормброу з'являється біля тихого ставка, що причаївся одразу за кузнею в Ґолдширі. Зазвичай містечко вирує від вартових в обладунках, ремісників і втомлених шукачів пригод, що прямують у ліс, та поява шанованого духа приносить тиху паузу. Стоячи під мирним склепінням Лісу Елвінн, Стормброу вітає кожного, хто готовий ушанувати довгу історію краю."},{t="Шана стародавнім расам",b="Місячний фестиваль — час, коли духи великих предків повертаються ходити серед живих. Старійшина Стормброу хвалить смертних мандрівників за те, що вони знаходять час згадати тих, хто був до них. В обмін на визнання мудрості й спадщини старших народів він дарує своє благословення та пам'ятну монету на честь свята."}},faq={{q="Де знайти Старійшину Стормброу?",a="Старійшина Стормброу стоїть біля ставка просто за кузнею коваля в Ґолдширі, у Лісі Елвінн.",al={"місце стормброу","де старійшина стормброу","старійшина ґолдшира"}},{q="Хто такий Старійшина Стормброу?",a="Старійшина Стормброу — дух предків, що з'являється під час Місячного фестивалю й уособлює шанованих старійшин прадавніх рас Азероту.",al={"хто такий стормброу","переказ про стормброу","особа старійшини стормброу"}},{q="Навіщо навідуватися до Старійшини Стормброу?",a="Відвідавши Старійшину Стормброу, мандрівники можуть ушанувати прадавніх предків під час свята. За шану до цих традицій він вітає їх і дарує знак вдячності.",al={"навіщо йти до стормброу","завдання старійшини стормброу","мета старійшини стормброу"}},{q="Чи можуть гравці Орди поговорити зі Старійшиною Стормброу?",a="Старійшини Місячного фестивалю шанують кожного, хто приходить до них із миром, але Ґолдшир — пильно стережена земля Альянсу, тож будь-який візит мандрівника Орди вкрай небезпечний.",al={"стормброу орда","чи орда може до стормброу"}},{q="Який знак дає Старійшина?",a="Старійшина Стормброу дає Монету Роду — традиційний знак шани й пам'яті, яким старійшини діляться під час свята.",al={"нагорода старійшини","який знак","місячна монета стормброу"}},{q="Чому Стормброу згадує «прадавні раси»?",a="Стормброу хвалить мандрівників за те, що вони пам'ятають: нинішні народи ходять землями, які творили прадавні народи й давні звичаї задовго до появи сучасних королівств.",al={"що значить прадавні раси","чому прадавні раси","діалог стормброу"}}},fp="19,300,21.389.0,24.344.0,33.124.0,23.140.0,48.197.0,43.176.0,32.131.0,45.177.0"}
P.entries["quest:865"] = {n="Роги рапторів",s="Мебок Міззірікс, заповзятливий гоблін із Раджета, вірить, що вся хитрість місцевих рапторів зосереджена в їхніх рогах. Він наймає мандрівників полювати на сонцелуских косокігтів по всіх Пустках і збирати цілі роги для дивного комерційного задуму.",h="Мебок Міззірікс, заповзятливий гоблін із Раджета, вірить, що вся хитрість місцевих рапторів зосереджена в...",kw={"роги рапторів","мебок міззірікс","косокігті","раптори","раджет","розумні трунки"},ang={["class:Hunter"]="Мисливці, знайомі зі зграями рапторів Калімдору, добре знають їхню смертоносну хитрість, але віра Мебока в те, що їхній розум можна розлити по пляшках, — чисте гоблінське шарлатанство.",["faction:Alliance"]="Раджет дає шукачам пригод з Альянсу рідкісну нейтральну опору в Пустках, де панує Орда, — нагоду заробити монету й прихильність Стімвідлу на дивних дорученнях на кшталт Мебокового."},sec={{t="Гоблінське підприємництво",b="Раджет повний гоблінів, що шукають нового багатства, і Мебок Міззірікс — не виняток. Помітивши, що раптори Пусток виявляють незвичну хитрість і злагодженість порівняно зі звірами інших країв, Мебок дійшов дивакуватого висновку: їхній розум має бути зосереджений у рогах. Звісно, замість того щоб узятися за справжнє наукове дослідження, він одразу вирішив зробити на цьому теоретичному ресурсі гроші."},{t="Сонцелускі косокігті",b="Щоб перевірити свою теорію, Мебокові потрібні бездоганні зразки від сонцелуских косокігтів — одних із найнебезпечніших хижаків краю. Ці раптори нишпорять і південними просторами Пусток, і північними околицями біля Ашенвалю. Щоб убити їх і вийняти роги неушкодженими, потрібна неабияка бойова вправність, адже ці звірі полюють зграями й люто боронять свою територію."},{t="Рецепт багатства",b="Здобувши роги, Мебок збирається вчинити просто й, як завжди, грубо: стовкти цілі роги на дрібний порошок і зварити з нього напої. Назвавши цю суміш «розумними трунками», він уже уявляє, як продаватиме її покупцям, охочим придбати кмітливість у пляшці, — і цілком певен, що розбагатіє за одну ніч."}},faq={{q="Навіщо Мебокові Міззіріксу роги рапторів?",a="Мебок вірить, що надзвичайний розум рапторів Пусток зберігається в їхніх рогах. Він збирається змолоти їх на порошок, щоб варити «розумні напої» й вигідно їх продавати.",al={"навіщо роги рапторів","мета мебока","чого хоче мебок"}},{q="Де водяться Сонцелускі Косокігті?",a="Сонцелускі Косокігті блукають двома різними частинами Пусток: південними краями й північними рівнинами біля кордону з Лісом Ашенваль.",al={"де косокігті","місце сонцелуских косокігтів","місце рогів рапторів"}},{q="Чи справді роги рапторів магічні чи посилюють розум?",a="Раптори Пусток справді відомі хитрістю, але переконання Мебока, ніби їхній розум чи кмітливість сидять у рогах на голові, — гоблінська псевдонаука, якою рухає лише нажива, а не знання природи.",al={"чи розумні напої діють","чи раптори розумні","розум рапторів"}},{q="Хто такий Мебок Міззірікс?",a="Мебок Міззірікс — заповзятливий гоблін-купець із портового містечка Раджет, що вічно вигадує сумнівні оборудки й вариво, аби розбагатіти на мандрівниках.",al={"хто такий мебок","переказ про мебока міззікса","мебок раджет"}},{q="Що буде, коли роги зібрано?",a="Отримавши цілі роги, Мебок береться молоти їх на порошок і змішувати з вином, і це веде просто до його наступної оборудки — «Розумних напоїв».",al={"наступне завдання після рогів рапторів","завдання розумних напоїв","ланцюжок рогів рапторів"}},{q="Чи можуть гравці Альянсу допомогти Мебокові?",a="Так. Раджет — відкритий порт під орудою картелю Стімвідл, а Мебок — нейтральний гоблін, що радо веде справи і з Ордою, і з Альянсом.",al={"чи це лише для орди","роги рапторів альянс","чи альянс може роги рапторів"}}},fp="12,248,23.452.0,24.387.0,19.329.1,42.198.0,39.145.0,52.197.0,22.172.0,40.162.1,47.157.0"}
P.entries["quest:8652"] = {n="Старійшина Грейвборн",s="Старійшина Ґрейвборн — зустріч Місячного фестивалю біля містечка Брілл у Галявинах Тірісфалю. Під час святкування мандрівники шукають Старійшину Ґрейвборна серед спустошених гаїв, щоб ушанувати стародавніх пращурів Азероту. Віддана цьому духові шана приносить його благословення і святковий дарунок.",h="Старійшина Ґрейвборн — зустріч Місячного фестивалю біля містечка Брілл у Галявинах Тірісфалю.",kw={"старійшина ґрейвборн","місячний фестиваль","монета роду","брілл","пращури","старійшина"},ang={["class:Druid"]="Друїди шанують старійшин Місячного фестивалю як ланки, що єднають із давнім світом до Розколу, незважаючи на неспокійні фракційні межі, серед яких ті перебувають.",["faction:Alliance"]="Шукачам пригод з Альянсу, які хочуть знайти Старійшину Ґрейвборна, слід обережно пробиратися Галявинами Тірісфалю: Брілл — добре укріплений притулок Відступників.",["race:Undead"]="Для Відступників, що живуть у Бріллі, прихід духів давніх пращурів — яскраве нагадування про глибшу історію Азероту за межами недавніх трагедій Погибелі."},sec={{t="Примарна варта у Бріллі",b="Поки Відступники живуть серед зруйнованих маєтків і могил Галявин Тірісфалю, Місячний фестиваль приносить несподіване єднання з давніми часами. Старійшина Ґрейвборн постає примарним старцем просто за межами Брілла. Навіть у краї, розтрощеному Погибеллю й відвойованому нежиттю, він вітає прочан, які зупиняються вшанувати давні звичаї."},{t="Шана давнім народам",b="Місячний фестиваль — час, коли великі духи давно минулих епох повертаються, щоб поділитися мудрістю і вдячністю. Коли мандрівники підходять до Старійшини Ґрейвборна, він зауважує, як утішно, що мешканці Тірісфалю досі вшановують пращурів попри нинішній занепад краю, і дарує Монету Роду тим, хто його привітав."}},faq={{q="Де знайти Старійшину Ґрейвборна?",a="Старійшина Ґрейвборн — неподалік поселення Брілл на Галявинах Тірісфалю: він тихо стоїть край дороги за містечком.",al={"місце старійшини ґрейвборна","де ґрейвборн","координати ґрейвборна"}},{q="Що буде, коли поговорити зі Старійшиною Ґрейвборном?",a="Коли ви привітаєтеся, Старійшина Ґрейвборн похвалить вас за шану до прадавніх народів Азероту й у межах святкування Місячного фестивалю дасть Монету Роду.",al={"нагорода ґрейвборна","місячний фестиваль ґрейвборн","що він дає"}},{q="Чому прадавній старійшина стоїть на Галявинах Тірісфалю?",a="Під час Місячного фестивалю духи прадавніх предків з'являються по всьому Азероту — від лісів калдореїв до земель, скалічених війною й чумою. Старійшина Ґрейвборн пильнує північ Лордерону, щоб смерть не затьмарила цілком його історію.",al={"чому старійшина в тірисфалі","переказ про ґрейвборна","хто старійшина ґрейвборн"}},{q="Чи можуть гравці Альянсу відвідати Старійшину Ґрейвборна?",a="Сам Старійшина Ґрейвборн — нейтральний дух мудрості й говоритиме і з членами Альянсу, і з Ордою. Але він стоїть просто під містечком Відступників Брілл, тож шукачам пригод Альянсу варто остерігатися місцевої варти.",al={"чи альянс може до ґрейвборна","ґрейвборн альянс","ґрейвборн ворожий"}},{q="Для чого Монета Роду?",a="Монети Роду, зібрані в старійшин на кшталт Ґрейвборна, під час Місячного фестивалю можна обміняти в Місячному Гаю на святкове вбрання, рецепти феєрверків та інші святкові дрібнички.",al={"навіщо монета роду","для чого місячні монети"}},{q="Чи Старійшина Ґрейвборн — Відступник?",a="Ні. Попри своє ім'я й примарний вигляд біля Брілла, Старійшина Ґрейвборн — один із прадавніх духів, яких шанують під час Місячного фестивалю: він належить до давнього роду старійшин Азероту, а не до Відступників Сильвани.",al={"чи ґрейвборн нежить","чи старійшина відступник"}}},fp="19,307,24.352.0,24.344.0,33.126.0,47.165.0,52.270.0,43.233.0,38.176.0,39.218.0"}
P.entries["quest:8653"] = {n="Старійшина Голдвелл",s="«Старійшина Голдвелл» — завдання Місячного фестивалю, яке дає Старійшина Ґолдвелл у Хараносі, в Дун Мороґу. Вшанувати його — означає долучитися до давньої традиції шукати духів предків по засніжених дворфійських землях. В обмін на вашу шану він дарує знак благословення предків.",h="«Старійшина Голдвелл» — завдання Місячного фестивалю, яке дає Старійшина Ґолдвелл у Хараносі, в Дун Мороґу.",kw={"старійшина","ґолдвелл","місячний фестиваль","харанос","монета роду","предки"},ang={["faction:Alliance"]="Розташований у безпечних землях Альянсу, Ґолдвелл — один із найдоступніших старійшин для юних героїв Альянсу, що мандрують між Долиною Холодного Хребта та Айронфорджем.",["faction:Horde"]="Щоб дістатися Ґолдвелла, доведеться прокрастися вглиб Дун Мороґу, повз дворфійську варту й лютий холод, просто під високі брами Айронфорджа.",["race:Dwarf"]="Для дворфів, що повертаються з Айронфорджа, зустріч зі старійшиною давнього роду просто біля їхньої головної таверни в Хараносі поєднує одвічну шану з гордістю за рідне місто."},sec={{t="Гірське вітання",b="Стоячи на лютому морозі біля Ґуральні Тандербрю в Хараносі, Старійшина Ґолдвелл наглядає за жвавим торговим шляхом, що веде до брам Айронфорджа. Під час Місячного фестивалю ця поважна постать вітає втомлених мандрівників, шукачів пригод і місцевих, утілюючи довгу пам'ять давніх днів, коли перші смертні ходили під зорями Азероту."},{t="Шана предкам",b="Підійти до Ґолдвелла — означає на мить замислитися серед суворих зимових вітрів Дун Мороґу. Він висловлює полегшення й радість, що смертні досі пам'ятають давні народи та їхні діяння, і дякує всім, хто перериває подорож, щоб засвідчити повагу. Натомість він дарує священну Монету Роду як знак свого благословення."}},faq={{q="Де знайти Старійшину Ґолдвелла?",a="Старійшина Ґолдвелл стоїть просто біля корчми при Ґуральні Тандербрю в містечку Харанос, на засніженій дорозі Дун Мороґа трохи на південний захід від брами Айронфорджа.",al={"місце старійшини ґолдвелла","де ґолдвелл","місце ґолдвелла"}},{q="Навіщо шукати Старійшину Ґолдвелла?",a="До Старійшини Ґолдвелла навідуються під час Місячного фестивалю, щоб ушанувати прадавніх духів світу. Віддаючи йому шану, ви доводите, що смертні раси не забули жертв і мудрості давнини.",al={"навіщо шукати ґолдвелла","що робить ґолдвелл","завдання ґолдвелла"}},{q="Яку нагороду дає Старійшина Ґолдвелл?",a="Він дає мандрівникам Монету Роду — благословенний знак від старійшин свята, який можна віднести Колу Кенарія в Місячний Гай і обміняти на святкові товари.",al={"нагорода старійшини ґолдвелла","що я отримаю від ґолдвелла","монета роду ґолдвелл"}},{q="Чи доступне це завдання мандрівникам Орди?",a="Так. Старійшини свята на кшталт Ґолдвелла — нейтральні духи предків, що вітають шукачів пригод будь-якої фракції, хоча мандрівникам Орди варто обережно оминати пильних горян-дворфів, що патрулюють Харанос.",al={"чи орда може до ґолдвелла","ґолдвелл орда","чи ґолдвелл привітний до орди"}},{q="Чому Старійшина Ґолдвелл перебуває в Дун Мороґу?",a="Старійшини Місячного фестивалю з'являються в кожному куточку Азероту, де смертні народи збудували тривкі громади. Ґолдвелл обрав Харанос, щоб ділитися благословенням із тими, хто живе біля серця дворфійського королівства.",al={"чому ґолдвелл у харанос","чому дун мороґ","ґолдвелл дворфійська земля"}},{q="Чи можна виконати це завдання кілька разів?",a="Ні. Шану Старійшині Ґолдвеллу віддають раз за святковий сезон, і кожен шукач пригод, що прийде по його пораду, отримує одне благословення й одну монету.",al={"чи повторюване завдання","ґолдвелл щоденне","скидання ґолдвелла"}}},fp="18,282,19.365.0,22.316.0,32.177.0,50.213.0,40.183.0,43.212.0,45.227.0,43.151.0"}
P.entries["quest:867"] = {n="Гарпії-нальотчиці",s="«Гарпії-нальотчиці» — одне з перших наступальних доручень від Дарсока Свіфтдаґґера на Перехресті, щоб приборкати войовничу зграю Відьмокрилів. Шукачам пригод доручено полювати на рядових нальотчиць і розбійниць на північному заході Пусток і збирати їхні кігті, щоб підірвати грабіжницькі набіги зграї на обози.",h="«Гарпії-нальотчиці» — одне з перших наступальних доручень від Дарсока Свіфтдаґґера на Перехресті, щоб...",kw={"гарпії-нальотчиці","гарпії","відьмокрили","дарсок свіфтдаґґер","перехрестя","каравани"},ang={["class:Rogue"]="Стратегія Дарсока Свіфтдаґґера до вподоби кожному вбивці: розвідати ціль, розібрати ієрархію й усувати верхівку шматок за шматком.",["faction:Horde"]="Убезпечення внутрішніх шляхів через Пустки необхідне, щоб нові застави мали припаси й лишалися єдиними під стягами Оргріммара."},sec={{t="Загроза згори",b="Каравани, що повзуть запорошеними стежками Пусток, постійно терплять від диких звірів і шипогривів, але гарпії-Відьмокрили — особливо смертоносна повітряна напасть. Налітаючи зі скелястих круч на північному заході, ці дикі створіння раз у раз падають на купецькі валки й обози з припасами, вбивають в'ючних тварин і грабують важливі вантажі для оркських застав."},{t="Задум Дарсока",b="Замість безладного нападу на гірські гнізда оркський розбійник Дарсок Свіфтдаґґер кілька днів вивчав звички й ієрархію зграї. Він знає: непродуманий удар лише розвіє їх за вітром. Щоб остаточно зламати Відьмокрилів, Дарсок має намір планомірно винищувати зграю знизу догори — почати з нальотчиць передової, а тоді взятися за їхніх ватажків."}},faq={{q="Чому Орда виступила проти гарпій Відьмокрилих?",a="Зграя Відьмокрилих гніздиться на північно-західних кручах Пусток і раз у раз налітає на каравани Орди з припасами, що йдуть головними стежками.",al={"чому вбивати гарпій","проблема відьмокрилих","чому нападати на гарпій"}},{q="Хто такий Дарсок Свіфтдаґґер?",a="Дарсок — орк-розвідник і розбійник на Перехресті. Він стежить за місцевими загрозами й розвідав, хто кому підкоряється в місцевій зграї гарпій, щоб спланувати продумане винищення.",al={"дарсок","переказ про дарсока свіфтдаґґера","хто такий дарсок"}},{q="Навіщо Дарсокові кігті Відьмокрилих?",a="Дарсок вимагає відтяті кігті як певний доказ убивства й збирає їх як похмурі трофеї — підтвердження, що найнижчих лав рейдерок у зграї меншає.",al={"чому кігті","призначення кігтів гарпій"}},{q="Де живуть ці гарпії?",a="Вони гніздяться серед зарослих колючками круч і ярів на далекому північному заході Пусток, на північ від дороги до Кам'яного Кігтя.",al={"де знайти гарпій","місце відьмокрилих","місце гарпій-нальотчиць"}},{q="Що буде, коли нальотчиць поменшає?",a="Коли рядових нальотчиць і розбійниць стане менше, Дарсок скерує вашу увагу вище за ієрархією зграї — на їхніх офіцерів, а зрештою й на ватажицю.",al={"наступне завдання","після гарпій-нальотчиць","що далі"}},{q="Чи працюють гарпії на когось іще?",a="Гарпії Відьмокрилі — дикі падальниці, що ревно стережуть свою землю й підкоряються лише власній ватажиці гнізда, Серені Бладфезер, а не якимось стороннім силам.",al={"хто веде гарпій","вірність гарпій","ватажки відьмокрилих"}}},fp="13,279,17.396.0,13.425.0,49.155.0,26.203.0,38.167.0,32.147.0,41.172.1,40.154.0"}
P.entries["quest:8670"] = {n="Старійшина Рунтотем",s="Старійшина Рунтотем — зустріч із духом предків під час Місячного фестивалю в Дуротарі. Вона стоїть у Гострому Пагорбі під стовпом небесного світла й дарує благословення та святкові монети подорожнім, що приходять ушанувати минуле.",h="Старійшина Рунтотем — зустріч із духом предків під час Місячного фестивалю в Дуротарі.",kw={"старійшина рунтотем","місячний фестиваль","гострий пагорб","дух предків","монета","таурени"},ang={["faction:Alliance"]="Щоб ушанувати Старійшину Рунтотем, доведеться прослизнути глибоко в тил ворога, у серце Дуротару, не накликавши на себе гніву орківської варти Гострого Пагорба.",["faction:Horde"]="Старійшина Рунтотем стоїть просто в мурах Гострого Пагорба — одна з найбезпечніших і найзручніших предків, яких молоді мандрівники Орди можуть ушанувати на початку свого шляху.",["race:Tauren"]="Зустріч із духом, що носить шановане родове ім'я Рунтотемів, за межами рівнин Малгору — потужне нагадування про глибоку духовну спадщину вашого народу по всьому Калімдору."},sec={{t="Дух у Гострому Пагорбі",b="Під час Місячного фестивалю духи давніх старійшин постають по всьому Азероту, щоб спілкуватися з живими. Старійшина Рунтотем з'являється в Гострому Пагорбі одразу за південним входом. Омита чистим променем зоряного світла згори, вона пильнує орківське поселення й вітає шукачів пригод, які відволікаються від своїх мандрів, щоб ушанувати мудрість тих, хто був до них."},{t="Настанови на всі землі",b="Підійти до Старійшини Рунтотем — означає не лише вшанувати одного предка. В обмін на вашу шану вона винагороджує вас святковою монетою удачі й розповідає, де можна знайти інших духів, скеровуючи мандрівників до Старійшини Даркгорна та Старійшини Гай Маунтіна по всьому континенту."}},faq={{q="Де знайти Старійшину Рунтотем?",a="Старійшина Рунтотем — на Гострому Пагорбі в Дуротарі, одразу праворуч, щойно ввійдете через південний вхід.",al={"місце старійшини рунтотем","де старійшина рунтотем","знайти старійшину рунтотем"}},{q="Чому на неї падає промінь світла?",a="Як і всіх духів предків, що з'являються під час Місячного фестивалю, Старійшину Рунтотем осяває небесний стовп світла, що позначає її як шановану старійшину.",al={"промінь світла на старійшині","чому рунтотем сяє","промінь світла старійшина"}},{q="Що дає вшанування Старійшини Рунтотем?",a="За шану до Старійшини Рунтотем ви отримуєте святковий знак на згадку про вашу повагу до предків, а вона підказує, як знайти інших мандрівних духів — Старійшину Даркгорн і Старійшину Гай Маунтіна.",al={"нагорода рунтотем","що дає рунтотем","здати старійшині рунтотем"}},{q="Чи можуть гравці Альянсу відвідати Старійшину Рунтотем?",a="Старійшини Місячного фестивалю приймають шану від усіх смертних, хоч би кому ті були віддані, але Гострий Пагорб — пильно стережена застава Орди, тож мандрівникам Альянсу підходити до неї небезпечно.",al={"старійшина рунтотем альянс","чи альянс може до рунтотем"}},{q="Яких старійшин згадує Рунтотем?",a="Старійшина Рунтотем ділиться переказами про те, де шукати інших предків, і зокрема підказує, як знайти Старійшину Даркгорн і Старійшину Гай Маунтіна.",al={"напрям рунтотем","кого знайти за порадою рунтотем"}},{q="Старійшина Рунтотем — жива тауренка чи привид?",a="Старійшина Рунтотем — дух предків, що з'являється під час Місячного фестивалю, щоб благословити тих, у кому палає життя.",al={"чи рунтотем мертва","чи рунтотем привид"}}},fp="19,263,22.398.0,25.290.0,33.143.0,44.191.0,49.197.0,43.196.0,36.147.0,46.144.0"}
P.entries["quest:8673"] = {n="Старійшина Бладгуф",s="«Старійшина Бладгуф» — зустріч з одним із шанованих духів предків, що з'являються під час Місячного фестивалю. Цей шанований дух, що стоїть одразу за Селом Бладгуф у Малгорі, приймає пошану від мандрівників і дарує навзаєм знак предків.",h="«Старійшина Бладгуф» — зустріч з одним із шанованих духів предків, що з'являються під час Місячного фестивалю.",kw={"старійшина бладгуф","місячний фестиваль","монета роду","предки","село бладгуф","малгор","дух"},ang={["class:Druid"]="Друїди високо шанують духів Місячного фестивалю і спілкуються зі старійшинами, щоб зміцнити свій природний зв'язок із землею та зорями.",["class:Shaman"]="Для шамана розмова з проявленими предками, як-от Старійшина Бладгуф, прямо зміцнює живе єднання між смертним світом і духами предків.",["faction:Alliance"]="Щоб дістатися Старійшини Бладгуфа, треба прокрастися в саме серце Малгору, тож це зухвала подорож ворожими рівнинами Орди.",["race:Tauren"]="Привітати Старійшину Бладгуфа на рідній землі — священний обов'язок, що вшановує спадок племені, яке допомогло привести тауренів до їхнього мирного прихистку в Малгорі."},sec={{t="Гостина предків",b="Під час святкування Місячного фестивалю духи великих героїв і старійшин минулих віків повертаються в Азерот. Оповитий небесним сяйвом, Старійшина Бладгуф з'являється одразу на північ від Села Бладгуф, біля мосту. Підійти до цих шанованих предків означає вшанувати давні жертви, а навзаєм Старійшина Бладгуф дарує слова підбадьорення і священну Монету Роду."},{t="Спадок Бладгуфів",b="Стоячи на прабатьківських землях Малгору, Старійшина Бладгуф служить мостом між живими племенами тауренів і пам'яттю про їхніх пращурів. Для тауренів шанування мертвих — опора духовного життя, що зміцнює гармонію між Земною Матір'ю, предками й тими, хто нині ходить рівнинами."}},faq={{q="Де знайти Старійшину Бладгуфа?",a="Старійшина Бладгуф стоїть, осяяний небесним промінням, одразу за Селом Бладгуф у Малгорі, неподалік мосту й Ахаба Вітгуфа.",al={"місце старійшини бладгуфа","де старійшина бладгуф","місце бладгуфа"}},{q="Навіщо шукати Старійшину Бладгуфа?",a="Під час Місячного фестивалю мандрівники шукають Старійшину Бладгуфа, щоб ушанувати предків. На знак визнання дух дарує відвідувачам Монету Роду й ділиться знаннями про сусідніх духів, як-от Старійшину Вітгуфа.",al={"навіщо говорити з бладгуфом","мета старійшини бладгуфа","що дає бладгуф"}},{q="Чому на нього падає промінь світла?",a="Стовп світла позначає дух як примару предків, що з'явилася під час Місячного фестивалю, й уособлює священний зв'язок із небом і духами минулого.",al={"чому бладгуф сяє","світло на старійшині бладгуфі"}},{q="Чи можуть персонажі Альянсу вшанувати Старійшину Бладгуфа?",a="Предки Місячного фестивалю шанують усіх смертних, що виявляють повагу, незалежно від фракції. Але мандрівникам Альянсу варто бути обережними, бо Старійшина Бладгуф стоїть на самому порозі земель Орди.",al={"чи альянс може це завдання","чи старійшина бладгуф лише орда"}},{q="Хто такий Старійшина Вітгуф, якого згадує цей старійшина?",a="Старійшина Вітгуф — ще один дух предків, що шанує свято; він деінде в Малгорі. Старійшина Бладгуф може підказати, де його шукати.",al={"старійшина вітгуф","хто такий вітгуф"}},{q="Що означають Монети Роду?",a="Монети Роду — знаки прихильності шанованих духів Азероту. Вони свідчать, що мандрівник виявив повагу до минулого, а гості свята міняють їх на святкове вбрання, креслення й святкові товари.",al={"що таке монети роду","жетони місячного фестивалю"}}},fp="19,285,26.394.0,20.316.0,33.142.0,51.245.0,49.185.0,54.211.0,48.159.0,40.234.0"}
P.entries["quest:8675"] = {n="Старійшина Скайчейзер",s="Старійшина Скайчейзер — дух предків, що з'являється під час Місячного фестивалю на вершині Вежі Вартових у Вестфолі. Вшановуючи її, мандрівники, що перетинають курні рівнини, віддають шану мудрості минулих віків. Натомість старійшина визнає палку снагу живих і дарує своє благословення.",h="Старійшина Скайчейзер — дух предків, що з'являється під час Місячного фестивалю на вершині Вежі Вартових у...",kw={"старійшина скайчейзер","місячний фестиваль","вежа вартових","предки","сентінел гілл","вестфол"},ang={["class:Druid"]="Друїди шанують Місячний фестиваль як священний і бачать у явленнях предків на кшталт Скайчейзер тривкий зв'язок із прадавніми традиціями й глибоким шануванням природи.",["faction:Alliance"]="Старійшина Скайчейзер зручно розташувалася в самому серці бази Народного ополчення в Сентінел Гіллі, тож її легко вшанувати, виконуючи завдання у Вестфолі.",["faction:Horde"]="Щоб дістатися до Старійшини Скайчейзер, знадобиться скритність, швидкість або груба сила, адже Сентінел Гілл кишить ворожими вартовими Альянсу й розвідниками ополчення."},sec={{t="Маяк серед пилу",b="Серед неспокійних чагарників Вестфолу Сентінел Гілл — єдиний укріплений редут проти нападників Дефіасу й мандрівних мародерів. Під час Місячного фестивалю дух предків на ім'я Старійшина Скайчейзер займає своє місце на відкритому майданчику на вершині Вежі Вартових. Високо над пилом і вітром вона терпляче пильнує втомлених солдатів і знесилених поселенців унизу й вітає кожного, хто підніметься, щоб віддати їй шану."},{t="Шана предкам",b="Місячний фестиваль — священна пора, яку відзначають по всьому Азероту, вшановуючи мудрість, спадщину й діяння прадавніх духів, що ходили землею задовго до нинішніх негараздів. Коли мандрівник наближається, Старійшина Скайчейзер бачить у ньому життєву іскру, приймає його шану й дарує знак своєї прихильності — дарунок спорідненості між живими й шанованими мертвими."}},faq={{q="Де знайти Старійшину Скайчейзер?",a="Старійшина Скайчейзер — на самій верхівці Вежі Вартових на Сентінел Гіллі у Вестфолі. Підніміться гвинтовими сходами всередині вежі на верхні дозорні мури.",al={"місце скайчейзер","де старійшина скайчейзер","скайчейзер вестфол"}},{q="Чому Старійшина Скайчейзер стоїть на верхівці Вежі Вартових?",a="Під час Місячного фестивалю духи предків обирають помітні й символічні місця по всьому Азероту. З висоти Вежі Вартових видно всю улоговину Вестфолу, тож старійшина може бачити мандрівників, що наважуються вирушити в прикордоння.",al={"чому скайчейзер у вежі вартових","вежа скайчейзер"}},{q="Навіщо це завдання?",a="Пошуки Старійшини Скайчейзер — частина вшанування старійшин-предків під час Місячного фестивалю. За виявлену шану ви отримаєте Монету Роду й благословення на честь живого духу шукача пригод.",al={"нагорода скайчейзер","навіщо вшановувати старійшину скайчейзер"}},{q="Чи можуть гравці Орди вшанувати Старійшину Скайчейзер?",a="Сама Старійшина Скайчейзер — мирний дух, що вітає всіх прочан. Але Сентінел Гілл — пильно стережена застава Альянсу, тож шукачам пригод Орди дістатися до неї небезпечно.",al={"чи орда може до скайчейзер","чи скайчейзер ворожа до орди"}},{q="Чи бере Старійшина Скайчейзер участь в обороні Сентінел Гілла?",a="Ні. Старійшини, що приходять під час Місячного фестивалю, — духовні явища, зосереджені лише на традиціях і пам'яті про давнину. Старійшина Скайчейзер не бере участі в сутичках Народного ополчення з Братством Дефіас.",al={"чи скайчейзер воює з дефіас","чи скайчейзер у народному ополченні"}},{q="Що каже Скайчейзер у відповідь на привітання?",a="Коли ви її привітаєте, Старійшина Скайчейзер зауважить, що ваш дух яскраво палає життям, ласкаво прийме вашу шану й натомість подарує знак предків.",al={"діалог скайчейзер","що каже старійшина"}}},fp="19,307,20.435.0,22.380.0,33.168.0,57.243.0,34.197.0,40.186.0,65.231.0,43.167.0"}
P.entries["quest:8677"] = {n="Старійшина Даркгорн",s="«Старійшина Даркгорн» — сезонне завдання: під час Місячного фестивалю треба розшукати Старійшину Даркгорн в Оргріммарі. Мандрівники віддають шану поважній пращурці й отримують натомість знак мудрості та свята. Вона стоїть у самому серці столиці Орди як свідчення довголіття, витривалості й гордості за предків.",h="«Старійшина Даркгорн» — сезонне завдання: під час Місячного фестивалю треба розшукати Старійшину Даркгорн в...",kw={"місячний фестиваль","старійшина даркгорн","монета роду","предки","оргріммар","свято"},ang={["class:Shaman"]="Шамани шанують єднання між світом живих і прадавніми духами, тож відвідини старійшин-предків, як-от Даркгорн, для них — глибокий духовний обов'язок.",["faction:Alliance"]="Щоб дістатися до Старійшини Даркгорн, вам доведеться зухвало пробратися крізь добре захищену браму й вулиці Оргріммара — і вшанування предків обертається небезпечною перевіркою скритності чи сили.",["faction:Horde"]="Для чемпіонів Орди відвідини Старійшини Даркгорн — зручна нагода вшанувати традиції предків просто в безпечному й гамірному серці своєї столиці."},sec={{t="Шана пращурці",b="Під час Місячного фестивалю духи шанованих предків з'являються по всьому Азероту, щоб поділитися мудрістю з живими. Старійшина Даркгорн перебуває за укріпленими валами Оргріммара й спостерігає за гамором молодого міста воїнів. Підійшовши до неї, чемпіони Орди — і кожен шукач пригод з Альянсу, якому вистачить сміливості прослизнути крізь браму, — можуть урочисто вшанувати тих, хто ходив цією землею за багато поколінь до них."},{t="Дух свята",b="Приймаючи привітання й шану від мандрівників, Старійшина Даркгорн бачить у них яскраву іскру життя. За вшанування давніх звичаїв вона дарує Монету Роду й особисте благословення. Ці дарунки прославляють перемогу над прадавніми небезпеками й нагадують живим берегти силу, яку передають із покоління в покоління непереривні родоводи."}},faq={{q="Хто така Старійшина Даркгорн?",a="Старійшина Даркгорн — дух предків, що з'являється в Оргріммарі під час Місячного фестивалю. Вона посланниця минулого, що дарує благословення й знаки мандрівникам, які знаходять час ушанувати старійшин.",al={"старійшина даркгорн","хто така даркгорн","переказ про даркгорн"}},{q="Де знайти Старійшину Даркгорн?",a="Вона спочиває в Оргріммарі, у Долині Мудрості одразу біля Фортеці Ґроммаш, і під час свята спостерігає за повсякденним життям столиці Орди.",al={"місце даркгорн","де даркгорн","старійшина даркгорн оргріммар"}},{q="Навіщо з'являються старійшини Місячного фестивалю?",a="Старійшини з'являються під час Місячного фестивалю, щоб живі могли вшанувати мудрість, мужність і жертви предків. Шана старійшині приносить Монету Роду — символ спадщини й спільної пам'яті.",al={"навіщо шукати старійшин","старійшини місячного фестивалю","монети предків"}},{q="Чи можуть гравці Альянсу вшанувати Старійшину Даркгорн?",a="Так, старійшини-предки приймають шану від усіх живих смертних, незалежно від фракції. Але Старійшина Даркгорн перебуває в самому серці твердині Орди, Оргріммара, тож гостям з Альянсу доведеться пробиватися крізь ворожу варту й гравців.",al={"чи альянс може до даркгорн","старійшина даркгорн альянс","старійшина оргріммара альянс"}},{q="Яку нагороду дає Старійшина Даркгорн?",a="Ушанувавши Старійшину Даркгорн, ви отримаєте Монету Роду разом з її благословенням.",al={"нагорода даркгорн","що дає даркгорн","монета роду даркгорн"}},{q="Чи можна виконувати це завдання повторно?",a="Ні, кожного старійшину-предка кожен персонаж може вшанувати лише раз за щорічне святкування Місячного фестивалю.",al={"чи можна ще раз даркгорн","чи даркгорн повторюване","щоденне даркгорн"}}},fp="18,326,21.432.0,26.369.0,22.214.0,32.177.0,49.212.0,42.241.0,38.80.0,25.109.0"}
P.entries["quest:8678"] = {n="Старійшина Праудгорн",s="Старійшина Вітгуф — дух предка тауренів, якого вшановують під час Місячного фестивалю на висотах Тандер Блафа. Прийти до нього — означає віддати глибоку шану мудрості предків, які оберігають Малгор і Орду.",h="Старійшина Вітгуф — дух предка тауренів, якого вшановують під час Місячного фестивалю на висотах Тандер Блафа.",kw={"місячний фестиваль","старійшина вітгуф","старійшина праудгорн","тандер блаф","предки","монета роду","таурени"},ang={["class:Shaman"]="Для шамана розмова з духом старійшини — глибокий обряд єднання з вічним світом духів.",["faction:Horde"]="Цей старійшина, що перебуває в самому серці тауренської могутності, привітає кожного союзника Орди, який підніметься на Тандер Блаф віддати шану.",["race:Tauren"]="Вшанувати Старійшину Вітгуфа — для героїв-тауренів це священне повернення додому, що утверджує їхній вічний зв'язок із духами, які оберігають Малгор."},sec={{t="Дух Малгора",b="Високо на продуваних вітрами плато Тандер Блафа, під час Місячного фестивалю, з'являється Старійшина Вітгуф — присутність самих предків. Таурени понад усе шанують голоси пращурів і вірять, що духи давніх вождів і мудреців лишаються поруч, щоб наставляти живих і додавати їм сили."},{t="Шана й благословення предків",b="Мандрівників, які піднімаються на висоти, щоб уклонитися Старійшині Вітгуфу, він вітає не як чужинців, а як живе полум'я життя. У відповідь на шану старійшина дарує Монету Роду — символ єдності між вічним минулим і живими героями, що борються за майбутнє світу."}},faq={{q="Хто такий Старійшина Вітгуф?",a="Це шанований дух предків-тауренів, що з'являється нагорі, в Тандер Блафі, під час Місячного фестивалю, щоб приймати шану поборників з усього Азероту.",al={"вітгуф","старійшина вітгуф","хто такий вітгуф"}},{q="Де знайти Старійшину Вітгуфа?",a="Старійшина Вітгуф — у столиці тауренів, Тандер Блафі, на широких центральних столових горах, з яких видно рівнини Малгора.",al={"де старійшина вітгуф","місце вітгуфа","старійшина тандер блафа"}},{q="Навіщо до нього навідуватися?",a="Відвідавши Старійшину Вітгуфа, гравці можуть ушанувати духів минулого під час Місячного фестивалю й отримати натомість його благословення й Монету Роду.",al={"навіщо йти до вітгуфа","завдання вітгуфа","старійшина місячного фестивалю"}},{q="Чи можуть гравці Альянсу відвідати Старійшину Вітгуфа?",a="Дух благословить кожного шанобливого мандрівника, але шукачеві пригод Альянсу заходити до Тандер Блафа вкрай небезпечно через пильну міську варту й оборонців Орди.",al={"чи альянс може до вітгуфа","старійшина тандер блафа альянс"}},{q="Що таке Монета Роду?",a="Це урочистий знак, який прадавні духи дарують під час Місячного фестивалю: він уособлює шану й єднання живих із предками.",al={"монета роду","монета місячного фестивалю"}},{q="Як таурени ставляться до своїх старійшин?",a="Таурени шанують предків як охоронців і вчителів, чия духовна присутність вплетена в саму землю й постійно веде тих, хто чує Земну Матір.",al={"ставлення тауренів до предків","переказ про старійшин тауренів"}}},fp="19,240,19.318.0,29.314.0,27.157.0,37.136.0,36.156.0,43.195.0,27.154.0,36.176.0"}
P.entries["quest:86784"] = {n="Палиці й кістки",s="Палиці й кістки — місцеве завдання від Вартового Смерті Бартоломью в Галявинах Тірісфалю. Він посилає мандрівників збирати сухе гілля по спустошеному лісу й нести його Елеанор Шеклтон — досвідченій виживальниці, що отаборилася в західних пагорбах.",h="Палиці й кістки — місцеве завдання від Вартового Смерті Бартоломью в Галявинах Тірісфалю.",kw={"палиці й кістки","бартоломью","елеанор шеклтон","гілля","багаття","табір"},ang={["faction:Horde"]="Такі віддалені табори, як у Елеанор, — приязні зупинки для молодих шукачів пригод Орди, що вирушають у мандри Галявинами Тірісфалю.",["race:Undead"]="Навіть у спустошених лісах Лордерону мандрівники з Відступників на кшталт Елеанор Шеклтон мусять пристосовувати давні навички виживання до свого нового нежиття."},sec={{t="Дружній жест",b="Вартові Смерті в Галявинах Тірісфалю зазвичай цілком поглинуті патрулюванням і обороною від Погибелі чи багряних хрестоносців, та Вартовий Смерті Бартоломью знаходить хвилину подбати про знайому. Знаючи, що Елеанор Шеклтон проводить своє нежиття просто неба, серед суворої стихії, він заохочує перехожих шукачів пригод назбирати сухого гілля для її багаття."},{t="Життя в дикій глушині",b="Елеанор Шеклтон пишається тим, що виживає у спустошених нетрях Тірісфалю сама. Хоч Відступники й нежить, вони все одно відчувають вогкий, пронизливий холод, що котиться з північних боліт. Філософія Елеанор щодо хмизу проста: коли вам здається, що дров уже досить, назбирайте ще вп'ятеро більше. Вдячна за додаткове паливо, вона дозволяє гінцеві лишити собі кошик Бартоломью і ділиться теплом свого вогнища."}},faq={{q="Хто дає завдання «Палиці й кістки»?",a="Це доручення дає мандрівним шукачам пригод Вартовий Смерті Бартоломью на Галявинах Тірісфалю: він просить допомогти його знайомій, Елеанор Шеклтон.",al={"хто дає палиці й кістки","видавець палиць і кісток"}},{q="Де табір Елеанор Шеклтон?",a="Елеанор Шеклтон тримає невеликий табір у пагорбах на заході Галявин Тірісфалю, де виживає під відкритим небом, далеко від поселень.",al={"місце елеанор шеклтон","де елеанор","де здати палиці й кістки"}},{q="Навіщо Відступникам дрова, якщо вони нежить?",a="Відступники не замерзають на смерть, як живі, але все одно відчувають невідступну вогкість і пронизливий холод тірісфальської глушини. Багаття дає затишок, гріє задерев'янілі суглоби й робить табір у глушині придатним для життя.",al={"чи нежить мерзне","навіщо дрова нежиті","холод відступників"}},{q="Що Елеанор радить про збирання дров?",a="За словами Вартового Смерті Бартоломью, золоте правило виживання Елеанор таке: «Коли здається, що дров досить, — набери вп'ятеро більше».",al={"правило елеанор про дрова","порада елеанор"}},{q="Чим збирати гілки?",a="Вартовий Смерті Бартоломью дає кошик, щоб носити шість сухих гілок, знайдених на галявинах; коли доставку завершено, Елеанор дозволяє лишити кошик собі.",al={"кошик для сухих гілок","як збирати гілки"}},{q="Чи веде це завдання до дальшого навчання виживання?",a="Елеанор вітає вас у своєму таборі й ділиться порадами, як шукачеві пригод мандрувати диким краєм, тож у тірісфальській глушині у вас з'являється приязна знайома.",al={"продовження палиць і кісток","що далі робить елеанор"}}},fp="16,247,18.361.0,17.436.0,38.135.0,35.140.0,53.241.0,51.138.0,45.164.0,50.154.0"}
P.entries["quest:868"] = {n="Полювання на яйце",s="«Полювання на яйце» — доручення Орди від ученого Коррана на Перехресті. Стривожений появою розумних комахоподібних істот на півдні Пусток, Корран залучає шукачів пригод, щоб викопати цілі яйця силітидів із кучугур на Полі Велетнів і доправити їх на вивчення до Оргріммара.",h="«Полювання на яйце» — доручення Орди від ученого Коррана на Перехресті.",kw={"полювання на яйце","корран","силітиди","яйце силітида","поле велетнів","перехрестя"},ang={["faction:Horde"]="Орда покладається на розвідників на кшталт Коррана, щоб пильнувати безлюдні простори Калімдору й вивчати дивні природні загрози, перш ніж ті стануть небезпечними для Дуротару й Малгора.",["race:Troll"]="Тролі, знайомі з первісними істотами, розуміють, що силітиди — не просто жуки, і поділяють настороженість Коррана щодо звірів із неприродним, розважливим розумом."},sec={{t="Очі на Перехресті",b="Троль Корран, що стоїть на запорошеному Перехресті посеред центральної савани, — спостерігач, який звітує своїм господарям в Оргріммарі. Поки військо Орди зайняте племінними сутичками й набігами Альянсу, Корран зважає на дивні збурення в природі. Найдивніше з них — поява чужинських комах із вуликовим розумом, що вгризаються в південні околиці Пусток."},{t="Розкопуючи рій",b="Щоб дізнатися, звідки беруться ці комахи й що ними керує, Коррану потрібні біологічні зразки, поки вони не дозріли. Озброєні копальним кігтем, шукачі пригод вирушають на Поле Велетнів, щоб видобути яйця просто з земляних кучугур силітидів. Потривожені кладки викликають шалений опір навколишнього виводку — натяк на неприродний розум і спільну волю, що єднає рій."}},faq={{q="Хто дає завдання «Полювання на яйце»?",a="Завдання дає Корран на Перехресті в Пустках. Це троль-спостерігач, що вивчає рослини, тварин і нові дивовижі краю на замовлення покровителів в Оргріммарі.",al={"видавець завдання","місце корана","хто починає полювання на яйце"}},{q="Де знайти яйця силітидів?",a="Яйця лежать у земляних горбках силітидів на Полі Велетнів, у південній половині Пусток. Горбки скупчуються довкола вуликових тунелів, прокопаних у землі.",al={"місце яєць","де яйця","яйця поля велетнів"}},{q="Яке знаряддя потрібне, щоб зібрати яйця?",a="Корран дає міцний Кіготь для Копання, щоб обережно вибирати цілі яйця, не розчавлюючи тендітної шкаралупи. Знаряддя треба повернути разом із дванадцятьма неушкодженими яйцями.",al={"знаряддя для копання","кіготь для копання","як отримати яйця"}},{q="Чим ці комахи відрізняються від звичайних звірів?",a="На відміну від простих шкідників чи місцевих звірів, ці істоти виявляють моторошну злагодженість і неабияку хитрість. Корран зауважує, що їхній розум набагато перевершує звичайних тварин, а це натякає на єдину мету вулика.",al={"чому силітиди особливі","розум комах","природа силітидів"}},{q="Навіщо Оргріммару яйця силітидів?",a="Провід Оргріммара хоче заздалегідь дізнатися про невідомі загрози, що вкорінюються біля кордонів Орди. Вивчення яєць допомагає дослідникам зрозуміти цикл росту, сильні сторони й будову цих істот, перш ніж навала пошириться.",al={"навіщо оргріммару силітиди","вивчення яєць силітидів","мета корана"}},{q="Що буде, якщо потривожити горбок із яйцями?",a="Якщо торкнутися гнізд, рій довкола розлютиться. Найближчі силітиди одразу кидаються захищати виводок і нападають на кожного, кого спіймають на розоренні гнізда.",al={"засідка біля горбка","захисники силітидів"}}},fp="8,286,22.408.0,20.413.0,29.178.0,34.194.0,40.171.0,55.211.0,38.245.0,43.157.0"}
P.entries["quest:8680"] = {n="Старійшина Віндтотем",s="Старійшина Віндтотем — шанований дух предка, що з'являється на кручі над гоблінським портом Раджет під час Місячного фестивалю. Осяяна променем небесного світла, вона приймає мандрівників, які прагнуть ушанувати мудрість минулих віків. Тим, хто віддасть їй шану, вона дарує благословення предків і вказує шлях до інших старійшин, що ходять Калімдором.",h="Старійшина Віндтотем — шанований дух предка, що з'являється на кручі над гоблінським портом Раджет під час...",kw={"старійшина віндтотем","місячний фестиваль","раджет","духи предків","старійшини","таурени"},ang={["class:Druid"]="Місячний фестиваль і його видіння предків оспівують глибоке єднання з природними й небесними циклами, які оберігає Коло Кенарія.",["class:Shaman"]="Розмова з духами предків, що затримуються біля стихійних перехресть, зміцнює шаманський обов'язок шанувати померлих і дбати про духовне здоров'я землі.",["race:Tauren"]="Рід Віндтотемів — давня тауренська спадщина; шана цьому предкові над гоблінською гаванню поєднує сучасних одноплемінників із родовою пам'яттю рівнин."},sec={{t="Чування над затокою",b="Стоячи на зеленому пагорбі трохи на північний захід від господаря перельотів у Раджеті, Старійшина Віндтотем дивиться на гамірні гоблінські пристані й відкрите море. Поки гавань унизу торгує залізом, порохом і монетою, старійшина стоїть осторонь у тихому спогляданні, і торкаються її лише тихі вітри Пусток та небесне сяйво, що лине згори."},{t="Мудрість по всіх Пустках",b="Як і інші духи предків, яких прикликає Місячний фестиваль, Старійшина Віндтотем стає провідницею для мандрівних смертних. Ті, хто її розшукає, не лише здобувають її благословення й знак прихильності, а й чують шепіт про те, де шукати сусідніх старійшин на континенті, зокрема Старійшину Рунтотема й Старійшину Бладгуфа."}},faq={{q="Де знайти Старійшину Віндтотем?",a="Старійшина Віндтотем стоїть на пагорбі просто на північний захід від розпорядника польотів у Раджеті, звідки видно гавань Пусток.",al={"місце віндтотем","де віндтотем","віндтотем карта раджета"}},{q="Навіщо шукати Старійшину Віндтотем?",a="Під час Місячного фестивалю мандрівники шукають Старійшину Віндтотем, щоб ушанувати шановану пращурку. За вашу шану вона дарує Монету Роду й підказує, де шукати інших духів по всій землі.",al={"навіщо говорити з віндтотем","мета старійшини віндтотем","що робить віндтотем"}},{q="Чому на неї падає промінь світла?",a="Кожного предка, що з'являється під час Місячного фестивалю, осяває окремий стовп небесного місячного світла: він позначає його безплотну присутність і духовний зв'язок між царством предків і світом живих.",al={"промінь світла старійшина","чому віндтотем сяє","світло на старійшині"}},{q="Чи можуть і гравці Альянсу, і гравці Орди поговорити зі Старійшиною Віндтотем?",a="Так. Раджет — нейтральний порт під орудою картелю Стімвідл, а старійшини Місячного фестивалю неупереджено вітають і членів Альянсу, і Орду.",al={"чи альянс може до віндтотем","чи віндтотем нейтральна","старійшина орди й альянсу"}},{q="Про яких інших старійшин розповідає Старійшина Віндтотем?",a="Старійшина Віндтотем ділиться чутками й підказками про кількох сусідніх предків, зокрема про Старійшину Бладгуфа, Старійшину Рунтотем, Старійшину Морнінґдью, Старійшину Даркгорн, Старійшину Гай Маунтіна, Старійшину Мунвордена й Старійшину Вітгуфа.",al={"старійшини за словами віндтотем","на кого вказує віндтотем"}},{q="Що буде, коли вшанувати старійшину?",a="Коли ви підійдете й ушануєте її, вона похвалить ваш дух, що яскраво палає життям, прийме вашу шану й нагородить Монетою Роду.",al={"здати старійшину віндтотем","що каже старійшина віндтотем"}}},fp="19,360,20.353.0,25.351.0,33.123.0,51.231.0,49.214.0,61.172.0,55.221.0,51.152.0"}
P.entries["quest:8682"] = {n="Старійшина Скайсір",s="Старійшина Скайсір — шанований дух предка, що перебуває на вершині Застави Вільного Вітру під час Місячного фестивалю. Мандрівники розшукують його високо над Тисячею Голок, щоб уклонитися предкам і отримати його давнє благословення.",h="Старійшина Скайсір — шанований дух предка, що перебуває на вершині Застави Вільного Вітру під час Місячного...",kw={"старійшина скайсір","місячний фестиваль","застава вільного вітру","старійшини","духи предків","тисяча голок"},ang={["class:Druid"]="Єднання з прадавніми духами під місячним сяйвом близьке до науки Кенарія й до шани тим, хто ходив цією землею раніше.",["faction:Alliance"]="Старійшина Скайсір перебуває в ордівській твердині — на Заставі Вільного Вітру, тож прочанам з Альянсу доведеться пробиратися небезпечними висотами повз ворожу варту, щоб віддати шану.",["race:Tauren"]="Привітати шанованого старійшину на одній із найвідоміших столових гір вашого народу — утілення глибокої шани, яку шу'гало мають до роду предків."},sec={{t="Маяк серед Голок",b="На високих дерев'яних кручах Застави Вільного Вітру Старійшина Скайсір з'являється в сяйливому стовпі небесного світла. Він стоїть біля мостів, що ведуть до величезних механічних підйомників, і його примарна присутність дарує тихий прихисток серед вітряних столових гір Тисячі Голок."},{t="Шлях предків",b="Старійшина Скайсір приймає шукачів пригод, що приходять ушанувати минуле під час Місячного фестивалю. Прийнявши їхню шану, поважний старійшина може підказати мандрівникам, де шукати його родичів, розкиданих по Калімдору, — серед них Старійшину Морнінґдью й Старійшину Рунтотема."}},faq={{q="Де знайти Старійшину Скайсіра?",a="Старійшина Скайсір стоїть на верхньому плато Застави Вільного Вітру в Тисячі Голок, біля підвісних мостів неподалік підйомників на кручі.",al={"місце скайсіра","де скайсір","старійшина вільного вітру"}},{q="Навіщо шукати Старійшину Скайсіра?",a="Під час Місячного фестивалю мандрівники навідуються до духів предків на кшталт Старійшини Скайсіра, щоб ушанувати їх, отримати Монету Роду й дізнатися, де шукати інших старійшин.",al={"навіщо йти до скайсіра","мета скайсіра","місячний фестиваль скайсір"}},{q="Чому Старійшина Скайсір сяє?",a="Як і інших шанованих духів, що приходять на свято, Старійшину Скайсіра осяває з неба яскравий стовп місячного світла, що позначає його як предка, який єднається з живими.",al={"чому скайсір у світлі","промінь світла старійшина"}},{q="До яких інших старійшин Скайсір показує дорогу?",a="Старійшина Скайсір підказує, як знайти сусідніх духів предків, зокрема Старійшину Морнінґдью, Старійшину Рунтотем, Старійшину Дрімсіра й Старійшину Вайлдмейна.",al={"інші старійшини","кого згадує скайсір","напрям скайсіра"}},{q="Чи можуть мандрівники Альянсу поговорити зі Старійшиною Скайсіром?",a="Так, хоча Застава Вільного Вітру — сильно укріплене поселення Орди. Шукачам пригод Альянсу доведеться обережно оминати варту, щоб підійти до старійшини без кровопролиття.",al={"чи альянс може до скайсіра","старійшина застави вільного вітру альянс"}},{q="Що буде, коли поговорити зі Старійшиною Скайсіром?",a="Коли ви привітаєтеся й ушануєте його, Старійшина Скайсір похвалить ваш дух і подарує знак благословення предків — на цьому коротка зустріч і завершиться.",al={"нагорода скайсіра","завершення скайсіра"}}},fp="17,236,23.288.0,18.281.0,31.143.0,49.189.0,29.188.0,55.154.0,48.178.0,45.145.0"}
P.entries["quest:869"] = {n="Раптори-злодії",s="Коли зі сторожової вежі Перехрестя зникла важлива партія платні для варти, оборонці впіймали неймовірного злодія — дикого раптора. Спантеличений і розлючений крадіжкою, Ґазроґ наказує влаштувати каральне винищення, щоб хитрі звірі більше не наважилися на таке.",h="Коли зі сторожової вежі Перехрестя зникла важлива партія платні для варти, оборонці впіймали неймовірного...",kw={"раптори-злодії","ґазроґ","раптори","голова раптора","перехрестя","платня"},ang={["class:Hunter"]="Раптори Пусток славляться хитрістю, злагодженістю в зграї й швидкістю, тож вони і грізна ціль, і наочний приклад суворої природи, яку мисливці мусять опанувати.",["faction:Horde"]="Перехрестя — хребет постачання Орди в Калімдорі; неоплачений чи принижений гарнізон загрожує безпеці кожного каравану, що перетинає савану."},sec={{t="Спантеличлива крадіжка",b="The Crossroads relies heavily on mercenary and grunt guards to keep vital trade arteries open across the Barrens. Keeping those guards paid is essential for morale and discipline. When the silver payroll vanished directly from the guard tower, leadership expected Centaur raiders or Quillboar scavengers. Instead, one thief caught red-handed in the dead of night was a predatory Barrens raptor, leaving the settlement's leadership stunned and out of pocket."},{t="Розплата для зграї",b="Ґазроґ навіть не вдає, що розуміє, навіщо диким звірам ховати блискучі монети, і не має бажання вивчати поведінку тварин. Вартові дедалі більше нервуються через невиплачену платню, тож Ґазроґ вимагає крові й острашки. Посилаючи мисливців по дюжину голів рапторів по всій савані, він хоче зламати зухвалість хижаків, перш ніж узятися за повернення срібла."}},faq={{q="Навіщо рапторам красти срібні монети?",a="Навіть Ґазроґ визнає, що це звучить неймовірно. Раптори відомі гострим розумом і мисливською вправністю, але щоб дикі хижаки тягли до себе карбоване срібло — такого ще не чували. Ґазроґа менше цікавлять їхні дивні мотиви — йому важливіше покарати цих тварюк, перш ніж вони знову нападуть на заставу.",al={"навіщо рапторам срібло","раптори крадуть гроші","чому срібло"}},{q="Хто такий Ґазроґ?",a="Ґазроґ — орк-офіцер на Перехресті в Пустках. Він відповідає за оборону й порядок: відає забезпеченням варти, нагородами для гінців і місцевими загрозами для головного осередку Орди.",al={"ґазроґ","хто дає рапторів-злодіїв"}},{q="Для чого було вкрадене срібло?",a="У вкраденій скрині була платня для вартових, що боронять Перехрестя. Без неї тримати пильну варту серед небезпечних Пусток стає набагато важче.",al={"для чого було срібло","вкрадена партія"}},{q="Де сталася крадіжка?",a="Вантаж украли просто зі сторожової вежі на Перехресті під покровом темряви, і оборонці, які вважали свій головний пост безпечним, були приголомшені.",al={"де крадіжка","місце крадіжки срібла"}},{q="Де водяться ці раптори?",a="Зграї рапторів блукають саваною в центрі й на півдні Пусток. Зграї, що полюють ближче до Перехрестя, зазвичай менш досвідчені, тож мандрівним шукачам пригод легше з ними впоратися.",al={"місця рапторів","де знайти рапторів"}},{q="Чи повертає це завдання вкрадене срібло?",a="Ні. Це суто каральний захід: перебити винних звірів і проріджувати їхні зграї. Справжні пошуки вкраденої скрині з монетами Ґазроґ влаштовує лише тоді, коли загрозу від рапторів відбито.",al={"чи повернути срібло","де срібло"}}},fp="14,263,16.457.0,21.388.0,37.288.0,14.210.0,37.193.0,31.162.0,30.202.0,42.207.0"}
P.entries["quest:87"] = {n="Золотозуб",s="«Золотозуб» — завдання в Лісі Елвінн, що завершує пошуки зниклої реліквії тітоньки Берніс Стоунфілд, які мало не розпалили нову ворожнечу. Коли малий Біллі Маклур зізнається, куди поділося намисто, ви маєте вистежити злодійкуватого кобольда, що причаївся біля Копальні Фарґодіп.",h="«Золотозуб» — завдання в Лісі Елвінн, що завершує пошуки зниклої реліквії тітоньки Берніс Стоунфілд, які мало...",kw={"золотозуб","кобольд","намисто","копальня фарґодіп","біллі маклур","берніс стоунфілд"},ang={["race:Human"]="Залагоджена сварка згладжує тертя між двома найстарішими фермерськими родинами Елвінну й водночас дає раду невідчепним кобольдам, що плюндрують королівство."},sec={{t="Хлопчачі витівки",b="Пошуки загубленого родинного намиста тітоньки Берніс Стоунфілд починаються як кисла прикордонна суперечка між ворогуючими Стоунфілдами й Маклурами. Берніс, звісно, підозрювала ворожу родину, та винуватцем виявляється Біллі Маклур. Бавлячись біля Копальні Фарґодіп, малий шибеник загубив дрібничку й поспіхом прикрив провину, запевняючи, що лише натрапив на неї, перш ніж якась істота її поцупила."},{t="Лігво над шахтою",b="За словами Біллі, незвично великий кобольд із блискучими іклами підхопив блискучу пам'ятку й дременув геть. Біллі запевняє, що той побіг до лігва над шахтою, та насправді звір на ім'я Золотозуб ховається на нижньому ярусі всередині Копальні Фарґодіп. Убивши істоту, ви повертаєте намисто Берніс, кладете край сусідській суперечці й отримуєте стару похідну пам'ятку, що лишилася від покійного чоловіка Берніс."}},faq={{q="Хто вкрав намисто Тітоньки Берніс?",a="Біллі Маклур узяв його, бешкетуючи, хоча запевняє, що лише знайшов і загубив його біля Копальні Фарґодіп. Перш ніж він устиг його підібрати, блискучу здобич схопив кобольд Золотозуб.",al={"хто вкрав намисто","хто взяв намисто","чи маклури вкрали намисто"}},{q="Де знайти Золотозуба?",a="Золотозуб чатує на нижньому ярусі в Копальні Фарґодіп, хоча Біллі описує його лігво як місце над копальнею.",al={"місце золотозуба","де золотозуб","знайти золотозуба"}},{q="Що за істота Золотозуб?",a="Золотозуб — завеликий кобольд, відомий блискучим золотим іклом, за яке й отримав своє прізвисько; як і всіх його родичів, його вабить до яскравих блискучих дрібничок.",al={"що таке золотозуб","чи золотозуб кобольд"}},{q="Як це завдання пов'язане з ворожнечею Маклюрів і Стоунфілдів?",a="Стоунфілди й Маклюри — запеклі суперники, що підозрюють одне одного в кожній дрібній крадіжці чи біді. Тітонька Берніс вирішила, що Маклюри вкрали її намисто на зло, але пошуки показують, що все сталося просто через необачність Біллі.",al={"драма маклюрів і стоунфілдів","чому берніс звинувачує біллі"}},{q="Яку нагороду дає Тітонька Берніс?",a="Тітонька Берніс дарує вам стару річ, що нібито приносить щастя: вона належала її покійному чоловікові, який, на лихо, забув узяти її в свій останній військовий похід.",al={"нагорода берніс","що отримаю"}},{q="Яке завдання веде просто до «Золотозуба»?",a="Просто до «Золотозуба» веде завдання «Назад до Біллі», у якому ви підкуповуєте Біллі Маклура свининою, щоб він нарешті зізнався, що сталося з намистом.",al={"попередник золотозуба","завдання перед золотозубом"}}},fp="9,261,16.451.0,22.411.0,36.191.1,29.111.0,35.148.0,61.240.1,39.164.0,41.152.0"}
P.entries["quest:870"] = {n="Забуті ставки",s="Тонга Рунтотем на Перехресті посилає шукачів пригод з Орди оглянути Забуті ставки — оазу на північний захід від поселення. Коло Кенарія підозрює, що приховані підземні енергії спричиняють буяння зелені посеред посушливої савани.",h="Тонга Рунтотем на Перехресті посилає шукачів пригод з Орди оглянути Забуті ставки — оазу на північний захід...",kw={"забуті ставки","тонга рунтотем","коло кенарія","оази","вулканічна тріщина","перехрестя"},ang={["class:Druid"]="Для друїдів це доручення — перше знайомство з таємничими силами, що спотворюють і змінюють природне зростання в Пустках під пильним оком Кола Кенарія.",["faction:Horde"]="Оскільки Перехрестя — ключовий вузол між Дуротаром, Малгором і Ашенвалем, захист сусідніх водних ресурсів від аномальної скверни — практична необхідність для Орди.",["race:Tauren"]="Земля Пусток дорога кочовим племенам Земної Матері, тож збереження й розуміння її джерел води вкрай важливе для тауренських мандрівників."},sec={{t="Заворушення на савані",b="Колись Пустки були родючою, квітучою землею, доки віки воєн і Розкол не розтрощили континент і не обернули край на випалені сонцем чагарники. Та останнім часом у сухій улоговині дивом почали з'являтися пишні оази. Для друїдів Кола Кенарія це раптове цвітіння — неприродне. Вони відчувають не звичайні джерела, а підземні сили, що пробиваються крізь землю нагору й пробуджують рослини та звірину в дивних острівцях серед пустищ."},{t="Каламутні глибини",b="Щоб зрозуміти це відродження, Тонга Рунтотем посилає мандрівників пірнути в Забуті ставки трохи на північний захід від Перехрестя. Під поверхнею ставка на них чекає тривожне відкриття: вулканічна тріщина, що тихо випускає у воду дивні бульбашкові гази. Ця тріщина доводить, що мінливі первісні сили просочуються в ґрунтові води, — це перша відчутна підказка до розгадки неприродних змін, що охопили Пустки."}},faq={{q="Хто такий Тонга Рунтотем?",a="Тонга Рунтотем — друїд-таурен із Кола Кенарія на Перехресті. Він вивчає природні аномалії Пусток, сподіваючись з'ясувати, чому серед випалених сонцем рівнин раптом з'являються буйні оази.",al={"тонга рунтотем","хто дає завдання","видавець перехрестя"}},{q="Чому Коло Кенарія досліджує Забуті ставки?",a="Повернення зелені на суху землю звучить як добра новина, але друїди відчувають, що якась неприродна, зосереджена енергія силоміць виштовхує життя на поверхню. Вони хочуть з'ясувати, яка сила живить ці нові оази, перш ніж вона вийде з-під контролю.",al={"чому досліджувати оази","друїди й оази пусток","що не так із ставками"}},{q="Що лежить на дні Забутих ставків?",a="Під водою в оазі ховається розколина, з якої у водойму вириваються бульбашки підземних газів. Ця розколина підтверджує, що енергія з надр землі вихлюпується в поверхневі води.",al={"що у воді","розлом забутих ставків","що булькає в ставку"}},{q="Де Забуті ставки?",a="Забуті ставки лежать недалеко на північний захід від Перехрестя в центрі Пусток; їх легко впізнати за раптовим кільцем буйних пальм і водою серед сухої землі.",al={"місце забутих ставків","де забуті ставки"}},{q="Чи Пустки завжди були пустелею?",a="За переказами друїдів, колись Пустки були буйним, квітучим краєм, сповненим життя. Катаклізми й прадавні війни випалили землю, перетворивши її на нинішню посушливу савану.",al={"чи пустки завжди пустеля","прадавні пустки","історія пусток"}},{q="Що йде після дослідження Забутих ставків?",a="Тонга Рунтотем бере ваші відомості про розколину з бульбашками й посилає вас оглянути ще одну оазу Пусток — Застояну оазу на південному сході.",al={"що далі","що робити після забутих ставків"}}},fp="19,251,25.487.0,16.473.1,23.231.0,61.244.0,51.196.0,38.173.0,32.189.0,51.154.0"}
P.entries["quest:871"] = {n="Зірвати напади",s="«Зірвати напади» — одне з перших оборонних доручень від Торка на Перехресті в Пустках. Войовничі шипогриви-Гостромани перерізали шляхи постачання між Дуротаром і заставою, загрожуючи самому існуванню поселення. Шукачів пригод з Орди посилають проредити сили шипогривів, поки розвідники намагаються вистежити ватажка їхнього загону.",h="«Зірвати напади» — одне з перших оборонних доручень від Торка на Перехресті в Пустках.",kw={"зірвати напади","торк","гостромани","шипогриви","перехрестя","дуротар"},ang={["class:Hunter"]="Полювання на мисливців-Гостроманів у чагарниках перевіряє вміння читати сліди в сутичках із місцевими вояками, що знають кожен куток цієї місцевості.",["faction:Horde"]="Шлях постачання між Дуротаром і Перехрестям — головна артерія Орди в центральному Калімдорі; дати шипогривам її перекрити — означає ризикувати голодом для всієї застави.",["race:Orc"]="Для орків, що освоюють Дуротар, Пустки — життєво важливий простір для розширення, тож безупинні засідки шипогривів — перешкода, яку треба долати силою."},sec={{t="Перерізана рятівна нитка",b="Перехрестя — життєво важливий вузол для всього руху Орди центральним Калімдором. Його виживання цілком залежить від возів і караванів, що везуть на захід із Дуротару харчі, залізо й спорядження. Коли плем'я Гостроманів улаштувало запеклі засідки на північно-східних стежках, ці важливі поставки раптово припинилися. Запаси тануть, оборонні склади порожніють, і Торк не може дозволити собі чекати мирних перемовин."},{t="Обрізати терен",b="Не чекаючи, поки шипогриви вдарять просто по мурах поселення, Торк наказує завдати випереджальних ударів по їхніх колючих лігвах на північний схід від поселення. Удари по шукачах води, ткачах терну й мисливцях послаблюють їхній розвідувальний периметр і позбавляють загони нападників магічної та тилової підтримки. Ці перші сутички дають дорогоцінний час, поки слідопити Орди прочісують чагарники, щоб з'ясувати, хто стоїть за набігами."}},faq={{q="Чому Гостромани грабують каравани?",a="Плем'я Гостроманів вважає посушливі рівнини Пусток своєю прадавньою батьківщиною. Будівництво Перехрестя й регулярні каравани Орди через їхні мисливські угіддя вони сприймають як нестерпне вторгнення, тож влаштовують засідки на обози з припасами.",al={"чому вепролюди нападають","мотив гостроманів","чому нападають на дорогу дуротару"}},{q="Хто такий Торк?",a="Торк — орк-командир на Перехресті. Він відає щоденною обороною застави: організовує розвідників і доручає воїнам убезпечити торгові шляхи від ворожих кентаврів, гарпій і шипогривів.",al={"хто такий торк","переказ про торка","ватажок перехрестя"}},{q="Де ці шипогриви?",a="Табори Гостроманів, які треба розгромити, лежать на схід і північний схід від Перехрестя, біля підніжжя гір, що відділяють Пустки від Дуротару. Їх легко впізнати за високими колючими лозами довкола таборів.",al={"де гостромани","місце гостроманів","де терноплети"}},{q="Що буде після того, як напади зірвано?",a="Проріджування лав — лише тимчасовий захід. Щойно перший загін розбито, а розвідники з'ясують, хто командує рейдерами, Торк одразу доручить вам вистежити їхнього вождя в наступному завданні — «Кінець нападам».",al={"що після зірваних нападів","наступне завдання після зриву нападів"}},{q="Яку роль у племені відіграють Шукачі Води?",a="Вода — найрідкісніший і найцінніший ресурс у Пустках. Шукачі Води — важливі збирачі, що знаходять природні криниці, оази й сховані підземні джерела, щоб плем'я та його бойові загони не мучилися від спраги серед розпечених чагарників.",al={"що таке шукач води","переказ про шукача води гостроманів"}},{q="Хто такі Терноплети?",a="Терноплети — шипогриви-геоманти й заклиначі, що керують землею й вирощують величезні непрохідні терни довкола своїх лігв. У бою вони б'ють непроханих гостей магією місцевої природи.",al={"що таке терноплет","терноплет вепролюдів"}}},fp="19,357,18.459.0,20.455.0,39.258.0,13.219.0,33.244.0,42.241.1,45.241.0,22.211.0"}
P.entries["quest:8717"] = {n="Старійшина Мунворден",s="Старійшина Мунворден — шанований дух предка, якого відвідують під час Місячного фестивалю: він стоїть у промені небесного світла на Перехресті в Пустках. Розмова з ним дарує мандрівникам давню мудрість і вказує шлях до інших старійшин, розкиданих по континенту.",h="Старійшина Мунворден — шанований дух предка, якого відвідують під час Місячного фестивалю: він стоїть у...",kw={"старійшина мунворден","місячний фестиваль","перехрестя","духи предків","старійшини","калімдор"},ang={["class:Druid"]="Друїди, що налаштовуються на природу й місячні цикли, знайдуть глибокий відгук у зацікавленні Мунвордена небесними таємницями й зоряними знаменнями.",["faction:Alliance"]="Щоб відвідати Старійшину Мунвордена, доведеться вирушити просто в добре укріплений вузол Орди — на Перехрестя, тож мить тихого вшанування обертається небезпечним проникненням.",["faction:Horde"]="Для мандрівників Орди, що перетинають центральне роздоріжжя Калімдору, шана Старійшині Мунвордену — зручна й важлива частина святкування традицій предків."},sec={{t="Небесна присутність у Пустках",b="Посеред запорошеного проїзду Перехрестя Старійшина Мунворден постає, осяяний сяйливим стовпом небесного світла. Він уособлює прадавніх духів, яких шанують під час Місячного фестивалю, — у пору, коли смертні відкладають свої чвари, щоб ушанувати мудрість минулих поколінь."},{t="Дороговказ до предків",b="Старійшина Мунворден розмірковує про зоряне небо і про те, як воно відкриває земні таємниці тим, хто дивиться вгору в пошуках істини. Окрім власних благословень предків, він вказує шукачам шлях до інших старійшин по всьому Калімдору — зокрема до Старійшини Бладгуфа, Старійшини Гай Маунтіна, Старійшини Морнінґдью й Старійшини Рунтотема."}},faq={{q="Де знайти Старійшину Мунвордена?",a="Старійшина Мунворден стоїть на Перехресті в Пустках, і його добре видно завдяки яскравому стовпу зоряного світла, що падає згори.",al={"місце мунвордена","де старійшина мунворден","мунворден перехрестя"}},{q="Навіщо навідуватися до Старійшини Мунвордена?",a="Під час Місячного фестивалю мандрівники навідуються до нього, щоб ушанувати духів предків, отримати знаки роду й дізнатися, як знайти інших шанованих старійшин по всіх землях.",al={"навіщо говорити з мунворденом","завдання мунвордена","місячний фестиваль мунворден"}},{q="До яких інших старійшин може скерувати Мунворден?",a="Старійшина Мунворден розповідає, де шукати кількох сусідніх духів, зокрема Старійшину Бладгуфа, Старійшину Гай Маунтіна, Старійшину Морнінґдью й Старійшину Рунтотем.",al={"інші старійшини","напрям старійшини мунвордена","кого згадує мунворден"}},{q="Чи можуть шукачі пригод Альянсу поговорити зі Старійшиною Мунворденом?",a="Старійшини-предки шанують кожного сміливого прочанина, хоч би кому той був відданий, але Мунворден стоїть просто в поселенні Орди, на Перехресті, тож мандрівникам Альянсу треба обережно оминати місцеву варту.",al={"чи альянс може до мунвордена","старійшина перехрестя альянс"}},{q="Чому на Старійшину Мунвордена падає промінь світла?",a="Як і всіх духів, що з'являються під час Місячного фестивалю, Старійшину Мунвордена осяває небесний стовп місячного світла — знак зв'язку із зорями й царством предків.",al={"промінь світла старійшина","стовп світла мунворден"}},{q="Що Старійшина Мунворден каже про зорі?",a="Мунворден міркує, що в незліченних зорях на небі ховаються відповіді на земні таємниці, і питає, чи не знайдуть мудрі й щасливі правду, якщо підведуть погляд угору.",al={"діалог мунвордена","цитата мунвордена"}}},fp="20,276,35.288.0,25.338.0,34.133.0,49.163.0,48.156.0,53.213.0,57.181.0,47.162.0"}
P.entries["quest:8718"] = {n="Старійшина Блейдсвіфт",s="Старійшина Блейдсвіфт — дух предка, якого вшановують під час Місячного фестивалю в столиці нічних ельфів Дарнасусі. Цей давній мудрець у Ценаріонському Анклаві ділиться з мандрівниками мудрістю, почерпнутою із зоряних небес. Його благословення пов'язує шукачів пригод зі шанованими традиціями Кола Кенарія й народу нічних ельфів.",h="Старійшина Блейдсвіфт — дух предка, якого вшановують під час Місячного фестивалю в столиці нічних ельфів...",kw={"старійшина блейдсвіфт","місячний фестиваль","монета роду","ценаріонський анклав","дарнасус","предки","зорі"},ang={["class:Druid"]="Як охоронці природи, пов'язані з Колом Кенарія, друїди мають глибокий культурний і духовний обов'язок шанувати давніх духів на кшталт Блейдсвіфта.",["faction:Alliance"]="Старійшина Блейдсвіфт, що стоїть у безпечному Дарнасусі, — легка й мирна проща для героїв Альянсу під час Місячного фестивалю.",["race:NightElf"]="Постати перед Старійшиною Блейдсвіфтом у Дарнасусі — значить безпосередньо поєднатися з небесною спадщиною вашого народу та його відданістю небесам."},sec={{t="Дух серед гілля",b="Під час Місячного фестивалю духи шанованих предків з'являються по всьому Азероту, щоб поділитися мудрістю й благословити мандрівників. Старійшина Блейдсвіфт стоїть серед спокійного гілля Ценаріонського Анклаву в Дарнасусі. На відміну від сучасних мешканців, заклопотаних випробуваннями сьогодення, цей примарний пращур дивиться вгору, на космос, і розмірковує над таємницями, вплетеними в нічне небо."},{t="Зоряне світло й давні істини",b="Культура нічних ельфів здавна шанує небесні світила як відображення Елуни й глибших таємниць буття. Блейдсвіфт нагадує тим, хто до нього підходить, що незліченні зорі тримають відповіді на земні негаразди, і закликає мудрих і щасливих підводити очі до неба. Вшанувавши його, шукачі пригод отримують Монету Роду й долучаються до вічної церемонії, що єднає світ смертних із духами минулого."}},faq={{q="Хто такий Старійшина Блейдсвіфт?",a="Старійшина Блейдсвіфт — дух предків із нічних ельфів, якого шанують під час сезонного Місячного фестивалю. Він з'являється в Дарнасусі, щоб давати мандрівникам, які прагнуть ушанувати пращурів, мудрі настанови й благословення.",al={"хто такий блейдсвіфт","переказ про блейдсвіфта","особа блейдсвіфта"}},{q="Де знайти Старійшину Блейдсвіфта?",a="Він стоїть у Ценаріонському Анклаві в столиці нічних ельфів, Дарнасусі, звідки видно тихі ставки й дерев'яні переходи міста на дереві.",al={"місце блейдсвіфта","де старійшина блейдсвіфт","блейдсвіфт дарнасус"}},{q="Навіщо шукати старійшин?",a="Відвідини старійшин — головна традиція Місячного фестивалю. Ушановуючи цих прадавніх духів по всьому світу, шукачі пригод славлять мудрість минулого й здобувають Монети Роду та святкову прихильність.",al={"навіщо шукати старійшин","мета старійшин місячного фестивалю","відвідини старійшин"}},{q="Чого навчає Блейдсвіфт тих, хто з ним говорить?",a="Блейдсвіфт закликає шукачів дивитися в небо. Він вважає, що незліченні зорі зберігають глибокі істини й відповіді на земні таємниці для тих, хто має досить терпіння й мудрості, щоб їх спостерігати.",al={"послання блейдсвіфта","що каже блейдсвіфт"}},{q="Чи можуть члени Орди відвідати Старійшину Блейдсвіфта?",a="Блейдсвіфт перебуває глибоко в Дарнасусі — столиці Альянсу, яку стережуть пильні Вартові, — але сам цей сезонний дух вітає кожного шанобливого мандрівника; гостям з Орди, щоправда, доведеться пробиватися крізь ворожу варту.",al={"чи орда може до блейдсвіфта","блейдсвіфт орда","блейдсвіфт лише альянс"}},{q="Чому старійшина з'являється на Тельдрассилі, якщо це нове Світове Дерево?",a="Хоча Тельдрассил виростили зовсім недавно, після Третьої війни, духів предків-калдореїв вабить до живого серця їхнього народу, тож вони з'являються поруч із родичами, щоб побачити свято.",al={"чому блейдсвіфт у дарнасусі","переказ про старійшину тельдрассила"}}},fp="20,360,22.406.0,28.429.0,24.210.0,36.160.0,46.219.0,52.195.0,48.224.0,64.203.0"}
P.entries["quest:872"] = {n="Кінець нападам",s="Отримавши докази цілеспрямованих набігів на шляхи постачання Орди, Торк наказує стратити Крініґа Снарлснаута — ватажка загону шипогривів-Гостроманів, що влаштовує напади на каравани з Дуротару. Прорвавши їхню оборону й здобувши ікло Крініґа, Орда прагне посіяти безлад у войовничому племені.",h="Отримавши докази цілеспрямованих набігів на шляхи постачання Орди, Торк наказує стратити Крініґа Снарлснаута...",kw={"кінець нападам","крініґ снарлснаут","торк","гостромани","шипогриви","перехрестя"},ang={["faction:Horde"]="Шлях постачання між Дуротаром і Перехрестям — життєво важливий хребет раннього розширення Орди в Калімдорі; поки він відкритий, застави в глибині краю виживуть.",["race:Orc"]="Військова філософія Торка відбиває традиційну оркську бойову науку: зламати дух ворога, повалити його вождя на очах у його ж воїнів."},sec={{t="Відтяти голову",b="Важливий торговий шлях між Дуротаром і Перехрестям постійно потерпав від засідок, що загрожували постачанню харчів і підкріплень на півночі Пусток. Донесення розвідників вказали на винуватця: зухвалий загін нападників-Гостроманів, яким керував вождь на ім'я Крініґ Снарлснаут. Розуміючи, що розрізнені сутички ніколи не вбезпечать дорогу назавжди, Торк наказав завдати прямого удару по ватажкові, щоб зламати тактичну згуртованість племені."},{t="Прорив у табір",b="Крініґ укріпився зі своїм загоном на скелястих пагорбах на північний схід від Перехрестя, під захистом кремезних оборонців-Гостроманів і геомантів, що підкоряють собі суху землю. Знищення його охорони й смерть Снарлснаута в його ж твердині мали стати суворим посланням для всіх рівнин. Відтяте ікло Крініґа стало незаперечним доказом того, що Орда не стерпить хижацтва на своїх життєвих шляхах."}},faq={{q="Хто такий Крініґ Снарлснаут?",a="Крініґ Снарлснаут — знаний ватажок набігів шипогривів Гостроманів, що отаборився на північний схід від Перехрестя. Він організовував злагоджені напади на каравани Орди, що йдуть головною дорогою з Дуротару, тож Торк наказав його стратити.",al={"хто такий крініґ","переказ про крініґа снарлснаута","хто веде гостроманів"}},{q="Де знайти Крініґа Снарлснаута?",a="Він — у таборах шипогривів на північний схід від Перехрестя, що тулляться до гірських передгір'їв трохи на південь від головної дороги з Дуротару.",al={"де крініґ","місце крініґа","знайти крініґа снарлснаута"}},{q="Навіщо Торкові ікло Крініґа?",a="Трофеї важать багато і для орків, і для шипогривів. Ікло Крініґа — незаперечний доказ загибелі ватажка й водночас привселюдна наруга над переможеними, що підриває дух уцілілих бійців Гостроманів.",al={"навіщо торку ікло крініґа","чому забрати ікло","ікло трофей торка"}},{q="Як убивство Крініґа допомагає Перехрестю?",a="Задум Торка спирається на віру в те, що без сильного проводу бойові загони шипогривів поринають у хаос. Убивство Крініґа руйнує їхню тактичну злагодженість, кладе край злагодженим засідкам на каравани й робить головний шлях із Дуротару безпечнішим для мандрівників.",al={"чому вбити крініґа","стратегічне значення крініґа","захист караванів перехрестя"}},{q="Яку роль у племені відіграють геоманти Гостроманів?",a="Геоманти — шипогриви-заклиначі, що єднаються з духами землі й каменю: магією природи вони здіймають колючі тернові загорожі й змінюють порізану місцевість довкола своїх ожинових таборів, щоб відбивати загарбників.",al={"що таке геоманти","переказ про геомантів гостроманів","земна магія вепролюдів"}},{q="Яке завдання передує цьому дорученню?",a="Це доручення йде одразу після завдання «Зірвати напади», у якому розвідники вперше з'ясували, наскільки плем'я Гостроманів причетне до нападів на каравани на східному прикордонні.",al={"попереднє завдання","що перед кінцем нападам","завдання перед цим"}}},fp="19,315,16.511.0,24.410.0,26.235.0,36.170.0,35.222.0,45.256.0,52.220.0,36.179.0"}
P.entries["quest:8721"] = {n="Старійшина Старвів",s="«Старійшина Старвів» — завдання Місячного фестивалю на Темному Узбережжі. Шукачі пригод розшукують Старійшину Старвів у поселенні Обердайн, щоб ушанувати духів предків Калімдору. За вшанування давніх традицій вона ділиться небесною мудрістю й своїм благословенням.",h="«Старійшина Старвів» — завдання Місячного фестивалю на Темному Узбережжі.",kw={"старійшина старвів","місячний фестиваль","обердайн","предки","зорі","темне узбережжя"},ang={["class:Druid"]="Друїди глибоко шанують духів предків і небесну рівновагу, тож спілкування зі Старійшиною Старвів — природне відбиття їхньої віри.",["faction:Horde"]="Щоб дістатися Старійшини Старвів, мандрівникам Орди доведеться обережно пробратися на пристані Обердайна, що належать Альянсу, і вшанувати її, не розлютивши місцевих вартових.",["race:NightElf"]="Ушанування Старійшини Старвів в Обердайні безпосередньо єднає нічних ельфів із давніми духами предків і шанованими таємницями Елуни та зірок."},sec={{t="Маяк в Обердайні",b="Під час Місячного фестивалю духи шанованих предків з'являються на всіх континентах Азероту, огорнуті стовпами сяйливого небесного світла. Старійшина Старвів займає своє місце серед нічних ельфів Обердайна — важливого портового містечка на оповитих імлою берегах Темного Узбережжя. Мандрівники, що святкують фестиваль, прочанами приходять до неї, шукаючи позачасової поради минулих віків."},{t="Шепіт небес",b="Старійшина Старвів споглядає небесне плетиво над Калімдором і нагадує всім, хто підходить, що зорі тримають відповіді на сумніви смертних і загадки світу. Тих, хто знайде час попросити її поради, вона закликає шукати правду в небі — і дарує їм прихильність предків разом зі звістками про інших мандрівних духів дикого прикордоння."}},faq={{q="Де знайти Старійшину Старвів?",a="Старійшина Старвів — у прибережному містечку нічних ельфів Обердайн на Темному Узбережжі. Вона стоїть, осяяна яскравим променем місячного світла, що падає просто з неба.",al={"місце старвів","де старійшина старвів","старвів темне узбережжя"}},{q="Навіщо це завдання?",a="Завдання — частина щорічного святкування Місячного фестивалю. Відвідуючи й ушановуючи старійшин-предків, розкиданих по Азероту, ви здобуваєте визнання, святкову монету й прихильність предків.",al={"навіщо старвів","мета старвів","що робить старвів"}},{q="Хто така Старійшина Старвів?",a="Це прадавній дух нічних ельфів, що шанує Місячний фестиваль. Огорнута зоряним світлом, вона ділиться мудрими думками про сузір'я й скеровує прочан до інших шанованих старійшин, як-от Старійшини Блейдсвіфта.",al={"хто така старвів","переказ про старвів","історія старійшини старвів"}},{q="Чи можуть гравці Орди відвідати Старійшину Старвів?",a="Так. Старійшини свята лишаються нейтральними й вітають шанобливих мандрівників обох фракцій. Але Старійшина Старвів перебуває в гавані Альянсу Обердайн, тож шукачам пригод Орди варто остерігатися місцевої варти нічних ельфів.",al={"чи орда може до старвів","старійшина старвів орда","старвів ворожа до орди"}},{q="Що Старійшина Старвів каже мандрівникам?",a="Вітаючи гостей, вона нагадує, що незліченні зорі вгорі зберігають відповіді на загадки смертних, і питає, чи не відкриють мудрі й щасливі правду, якщо підведуть погляд угору.",al={"діалог старвів","що каже старвів"}},{q="На якого старійшину вказує Старвів?",a="Старійшина Старвів розповідає, де шукати Старійшину Блейдсвіфта, і веде мандрівників далі святковим шляхом північним Калімдором.",al={"кого згадує старвів","наступний старійшина після старвів","наступний старійшина темного узбережжя"}}},fp="19,290,21.400.0,23.337.0,33.177.0,34.189.0,23.222.0,40.247.0,41.170.0,36.149.0"}
P.entries["quest:8724"] = {n="Старійшина Морнінґдю",s="Старійшина Морнінґдью — шанований дух предка, якого навідують під час Місячного фестивалю в Тисячі Голок. Осяяна променем зоряного світла, вона ділиться давньою мудрістю й скеровує прочан до інших старійшин, розкиданих по Калімдору.",h="Старійшина Морнінґдью — шанований дух предка, якого навідують під час Місячного фестивалю в Тисячі Голок.",kw={"старійшина морнінґдью","місячний фестиваль","старійшини","тисяча голок","зоряне світло","духи предків"},ang={["class:Druid"]="Місячний фестиваль і його небесні старійшини втілюють глибокий зв'язок з Елуною, природою й духами предків, священний для кенарійських кіл.",["class:Shaman"]="Єднання з шанованими духами, як-от Старійшиною Морнінґдью, — ключ до розуміння рівноваги предків і стихій у всьому світі.",["race:NightElf"]="Старійшини, осяяні зоряним світлом, нагадують про давні традиції шанування небес і прадавню мудрість, вплетену в історію Калімдору.",["race:Tauren"]="Шанування мудрості старійшин-предків — один зі стовпів тауренської культури, тож прочанство до таких духів, як Морнінґдью, має глибокий сенс."},sec={{t="Небесна присутність серед каньйонів",b="Під час Місячного фестивалю духи прадавніх предків з'являються по всьому Азероту, щоб поділитися з мандрівниками своїм благословенням. Старійшина Морнінґдью постає в стовпі місячного світла, різко вирізняючись на тлі запиленого червоного каменю й гамірної метушні механізмів Тисячі Голок. Вона нагадує смертним мандрівникам, що варто дивитися далі за земні клопоти — у зоряний простір угорі."},{t="Мудрість небес",b="Коли до неї підходять, Морнінґдью закликає шукачів шукати відповіді на земні загадки серед незліченних зірок. Окрім задумливих привітань, вона — провідниця для прочан фестивалю: підказує, де шукати інших шанованих духів, що ходять цими землями, — Старійшину Гай Маунтіна, Старійшину Ґрімтотема, Старійшину Містволкера, Старійшину Мунвордена й Старійшину Віндтотема."}},faq={{q="Хто така Старійшина Морнінґдью?",a="Старійшина Морнінґдью — дух предків, що з'являється під час Місячного фестивалю. Огорнута зоряним світлом, вона ділиться мудрістю й настановами з мандрівними шукачами пригод, які прагнуть ушанувати старійшин.",al={"старійшина морнінґдью","переказ про морнінґдью","хто така морнінґдью"}},{q="Де знайти Старійшину Морнінґдью?",a="Вона в Тисячі Голок, і її добре видно завдяки сяйному стовпу світла, що падає з неба.",al={"місце морнінґдью","де морнінґдью","знайти морнінґдью"}},{q="Навіщо навідуватися до Старійшини Морнінґдью?",a="Під час Місячного фестивалю мандрівники навідуються до неї, щоб ушанувати предків, отримати благословення предків і дізнатися, де шукати інших старійшин краю.",al={"навіщо йти до морнінґдью","мета морнінґдью","старійшина місячного фестивалю"}},{q="Про яких інших старійшин знає Морнінґдью?",a="Старійшина Морнінґдью показує дорогу до п'ятьох інших шанованих духів: Старійшини Гай Маунтіна, Старійшини Ґрімтотема, Старійшини Містволкера, Старійшини Мунвордена й Старійшини Віндтотем.",al={"інші старійшини морнінґдью","список старійшин","кого згадує морнінґдью"}},{q="Чому на неї падає стовп світла?",a="Кожного духа предків під час Місячного фестивалю осяває промінь небесного зоряного світла, що підкреслює його безплотну присутність і зв'язок із небесами.",al={"промінь світла морнінґдью","стовп світла старійшина","чому старійшина сяє"}},{q="Чого Морнінґдью навчає прочан?",a="Морнінґдью навчає, що небеса з їхніми незліченними зорями зберігають відповіді на земні таємниці, і закликає мудрих і щасливих підвести погляд угору, щоб знайти правду.",al={"порада морнінґдью","діалог морнінґдью","що каже морнінґдью"}}},fp="20,244,35.371.0,21.382.0,24.184.0,36.104.0,49.179.0,46.162.0,51.171.0,36.171.0"}
P.entries["quest:8725"] = {n="Старійшина Рівсонґ",s="Старійшина Ріверсонг — дух предка з нічних ельфів, якого шанують під час Місячного фестивалю; вона спочиває під тихим святилищем в Астранаарі. Осяяна променем місячного світла, вона ділиться з мандрівниками тихою мудрістю й скеровує прочан до інших шанованих предків по всьому Калімдору.",h="Старійшина Ріверсонг — дух предка з нічних ельфів, якого шанують під час Місячного фестивалю; вона спочиває...",kw={"старійшина ріверсонг","місячний фестиваль","астранаар","предки","старійшина старвів","завдання"},ang={["class:Druid"]="Місячний фестиваль і його небесні старійшини втілюють прадавній кенарійський зв'язок із природою, духами й нічним небом.",["faction:Alliance"]="Астранаар — одна з головних твердинь Альянсу в центральному Калімдорі, тож відвідати Старійшину Ріверсонг під час Місячного фестивалю прочанам Альянсу легко й приємно.",["race:NightElf"]="Для нічних ельфів ушанувати Старійшину Ріверсонг під святилищем Астранаару — це щире єднання з довгою історією свого народу під зорями Ашенвалю."},sec={{t="Маяк в Астранаарі",b="Серед прадавнього гілля й дерев'яних переходів Астранаару Старійшина Ріверсонг постає під відкритим святилищем нічних ельфів. Її неземна присутність, позначена виразним стовпом небесного світла, що пронизує лісовий покров Ашенвалю, стає осередком для учасників Місячного фестивалю, які прагнуть поєднатися з минулими поколіннями."},{t="Погляд у небеса",b="Старійшина Ріверсонг нагадує прочанам про прадавню традицію нічних ельфів читати правду й таємниці в зоряному небі. Її слова закликають мандрівників шукати мудрості в терпінні й роздумах і ведуть тих, хто шанує це свято, далі — до інших духів, зокрема до Старійшини Старвів."}},faq={{q="Де знайти Старійшину Ріверсонг?",a="Старійшина Ріверсонг стоїть у поселенні Астранаар в Ашенвалі. Вона під невеликою святинею нічних ельфів, осяяна яскравим променем зоряного світла, що пробивається крізь крони лісу.",al={"місце ріверсонг","де ріверсонг","місце старійшини ріверсонг"}},{q="Навіщо навідуватися до Старійшини Ріверсонг?",a="Відвідини Старійшини Ріверсонг — частина вшанування предків під час Місячного фестивалю. Розмова з нею дає благословення предків і монети роду, а ще підказку, як знайти інших старійшин по всьому Калімдору.",al={"навіщо йти до ріверсонг","що робить ріверсонг"}},{q="До якого старійшини скеровує Ріверсонг?",a="Старійшина Ріверсонг скеровує шукачів до Старійшини Старвів — ще одного шанованого духу нічних ельфів, що відзначає свято.",al={"наступний старійшина після ріверсонг","кого згадує ріверсонг"}},{q="Чи можуть гравці Орди поговорити зі Старійшиною Ріверсонг?",a="Старійшина Ріверсонг перебуває просто в Астранаарі, осередку Альянсу, тож гравцям Орди доведеться пробиватися крізь міську варту й вартових, щоб до неї підійти, хоча самі старійшини свята не відмовляють у єднанні через фракцію.",al={"чи орда може до ріверсонг","чи ріверсонг лише альянс"}},{q="Чому Старійшину Ріверсонг огортає промінь світла?",a="Стовп небесного світла уособлює прихильність Елуни й небес: він осяває кожного духа предків, що з'являється під час Місячного фестивалю.",al={"чому ріверсонг сяє","світло на ріверсонг"}},{q="Що каже Старійшина Ріверсонг, коли її вшановують?",a="Старійшина Ріверсонг міркує про всесвіт: вона зауважує, що незліченні зорі на небі зберігають відповіді на земні таємниці, і питає, чи не знайдуть мудрі й щасливі правду, якщо підведуть погляд угору.",al={"цитата ріверсонг","діалог ріверсонг"}}},fp="19,284,21.317.0,21.282.0,33.194.0,48.226.0,45.111.0,43.226.0,53.152.0,43.188.0"}
P.entries["quest:873"] = {n="Іша Авак",s="«Іша Авак» — священний мисливський обряд, який доручає містикиня Магрен Скайсір на Узбережжі Крамарів. Відважних мандрівників Орди посилають пірнути у Велике море, щоб вистежити й убити грізного морського хижака, відомого як Глибинна Згуба. Здобувши серце звіра, мисливець долучається до давнього союзу духу й шани.",h="«Іша Авак» — священний мисливський обряд, який доручає містикиня Магрен Скайсір на Узбережжі Крамарів.",kw={"іша авак","глибинна згуба","магрен скайсір","купецьке узбережжя","полювання","мисливець"},ang={["class:Hunter"]="Вистежити легендарного морського звіра в глибинах Великого моря — найвище випробування терпіння, хитрості й влучності в сутичці з істотою, що безроздільно панує у своїх водах.",["faction:Horde"]="Перемога над Глибинною Згубою доводить бойову перевагу Орди на Узбережжі Крамарів: падає левіафан, що наводив жах на місцеві застави Альянсу.",["race:Tauren"]="Полювання на Іша Авак відбиває традиційні духовні звичаї тауренського полювання, де здобич шанують, а не зневажають, і відібране життя дарує єднання з духом істоти."},sec={{t="Глибинна Згуба",b="Біля узбережжя на південь від Раджета під хвилями никає Іша Авак. Відома як Глибинна Згуба, ця величезна морська істота панує в прибережних водах із грізною силою й урочистою хижою величчю. Люди-зайди, що отаборилися вздовж берега, навчилися боятися цих вод, утративши чимало розвідників і солдатів через невгамовний голод істоти."},{t="Полювання духу",b="На відміну від наляканих людей на березі, Магрен Скайсір глибоко шанує цього левіафана. Для тауренської містикині Іша Авак — не прокляття й не звичайна напасть, а дар: гідний, шляхетний супротивник, чия міць випробовує рішучість справжніх мисливців. Убити звіра — це не просто прибрати хижака; це акт духовного єднання: здобути серце, де живе суть звіра, і понести далі його неприборканий дух."}},faq={{q="Хто така Іша Авак?",a="Іша Авак, на прізвисько Глибинна Згуба, — могутня морська потвора, що чатує у водах біля східного узбережжя Пусток, на південь від Раджета. Її вважають володаркою цих прибережних вод, і вона горезвісна тим, що полює на людей — моряків і вояків, що стоять поблизу.",al={"що таке іша авак","переказ про ішу авак","глибинна приреченість"}},{q="Чому Магрен Скайсір хоче смерті Іші Авак?",a="Магрен полює на Ішу Авак не зі зла чи страху. Вона бачить у цьому великому хижакові гідного, шляхетного супротивника й духовне випробування. Для Магрен здолати таку потвору означає перейняти її силу й поєднатися з її диким духом.",al={"чому вбити ішу авак","мотив магрен скайсір"}},{q="Де знайти Ішу Авак?",a="Потвора плаває у Великому Морі біля Узбережжя Крамарів на сході Пусток, на південь від гоблінського порту Раджет, неподалік берегів, де живуть люди.",al={"місце іші авак","де знайти ішу авак","поява іші авак"}},{q="Що буде, коли принести серце?",a="Магрен Скайсір вірить, що суть і доля істоти живуть у її серці. Віддавши серце містикині, ви духовно пов'язуєте себе з полеглою потворою й несете в собі частку сили Іші Авак і зору хижака.",al={"призначення серця іші авак","навіщо серце іші авак"}},{q="Про яких людей каже Магрен?",a="Ідеться про сили Терамора й Кул Тірасу, що діють на узбережжі Пусток, особливо довкола Твердині Північної Варти й сусідніх застав. Чимало їхніх моряків і мешканців берега загинуло в щелепах морської потвори.",al={"про яких людей","люди на узбережжі","хто боїться іші авак"}},{q="Іша Авак — елементаль чи звичайна тварина?",a="Іша Авак — природна, хоч і надзвичайно велика й могутня, морська істота Великого Моря, яку місцеві таурени шанують за первісний дух і мисливську вправність.",al={"чи іша авак звір","тип істоти іші авак"}}},fp="9,333,13.371.0,16.429.0,17.266.0,45.251.0,29.158.0,43.250.0,39.242.0,57.163.0"}
P.entries["quest:874"] = {n="Магрен Скайсір",s="«Магрен Скайсір» — завдання-подорож Орди, що веде досвідчених мисливців із Табору Тауражо до східних берегів Пусток. Опанувавши полювання на хижаків рівнин, шукачі пригод вирушають за вказівкою Джорна Скайсіра вчитися прибережного слідопитства в його сестри. Щоб знайти її, доведеться ризикнути у водах і пройти повз людські табори на Узбережжі Крамарів.",h="«Магрен Скайсір» — завдання-подорож Орди, що веде досвідчених мисливців із Табору Тауражо до східних берегів...",kw={"магрен скайсір","джорн скайсір","табір тауражо","купецьке узбережжя","кул тірас","мисливець"},ang={["class:Hunter"]="Для мисливців це завдання знаменує перехід від полювання на звичну дичину савани до переслідування лютих морських звірів під проводом досвідчених тауренських слідопитів.",["faction:Horde"]="Подорож на східне узбережжя приводить розвідників Орди просто до ворожих плацдармів Альянсу, що підступають із Терамора.",["race:Tauren"]="Брат і сестра Скайсір утілюють традиційну тауренську мисливську філософію, перевіряючи, чи здатні діти Земної Матері витримати випробування в будь-якому краю."},sec={{t="Полювання за межами рівнин",b="Проходячи випробування Джорна Скайсіра в Таборі Тауражо, мисливці доводять свою завзятість у сутичках із найнебезпечнішими звірами, що никають червоними рівнинами південних Пусток. Та Джорн учить, що справжній хижак ніколи не обмежується сухою землею й хвилястими саванами. Щоб по-справжньому опанувати ремесло, слідопит мусить бути готовим переслідувати здобич болотами, стрімкими скелями й серед бурхливих хвиль Великого моря."},{t="Східний берег",b="Сестра Джорна, Магрен Скайсір, отаборилася далеко на сході, на узбережжі. Поки Джорн вивчає духів громояструбів і рівнинних скрадачів, Магрен присвячує себе невловимим створінням, що живуть серед солоних бризок. Дорога до неї небезпечна, адже морські піхотинці Кул Тірасу й загони тераморської експедиції тримають укріплені застави й сторожові вежі по всій прибережній низовині."}},faq={{q="Хто дає завдання «Магрен Скайсір»?",a="Завдання дає Джорн Скайсір у Таборі Тауражо на півдні Пусток, коли ви успішно завершите його полювання на громояструбів.",al={"хто починає магрен скайсір","видавець джорн скайсір"}},{q="Де знайти Магрен Скайсір?",a="Магрен Скайсір отаборилася на східному узбережжі Пусток, на південь від Раджета, біля берегів, куди навідуються прибережні звірі й вояки Терамора.",al={"де магрен скайсір","місце магрен скайсір","знайти магрен"}},{q="Навіщо це завдання?",a="Це завдання-місток, що пов'язує мисливські випробування Джорна Скайсіра в Таборі Тауражо з прибережними випробуваннями Магрен — полюванням на морських істот.",al={"навіщо шукати магрен","мета магрен скайсір"}},{q="Чому Джорн посилає мисливців до Магрен?",a="Джорн вірить, що справжній мисливець має опанувати будь-яке середовище, зокрема й море. Його сестра Магрен спеціалізується на вистежуванні морських звірів і сутичках із ними, тож вона — найкраща наставниця.",al={"чому джорн посилає до сестри","переказ про магрен скайсір"}},{q="Які небезпеки чатують на шляху до Магрен?",a="На східному узбережжі Пусток повно ворожих людських експедиційних сил із Терамора й Кул Тірасу, а ще агресивних прибережних рапторів і морських хижаків.",al={"небезпеки дороги до магрен","хто тримає узбережжя"}},{q="Що буде, коли знайти Магрен Скайсір?",a="Коли ви познайомитеся й здобудете її довіру, Магрен доручить вам вистежити Ішу Авак — величезну люту морську потвору, що чатує в цих водах.",al={"наступне завдання після магрен","що дає магрен"}}},fp="14,334,24.399.0,17.397.0,35.131.0,32.158.0,34.148.0,37.184.0,41.176.0,40.152.0"}
P.entries["quest:875"] = {n="Гарпії-офіцери",s="«Гарпії-офіцери» — завдання Орди від Дарсока Свіфтдаґґера на Перехресті. Продовжуючи воєнну кампанію проти Відьмокрилів на півночі Пусток, звитяжців посилають на Сухі Пагорби, щоб убити польових офіцерок зграї й зруйнувати ланцюжок командування.",h="«Гарпії-офіцери» — завдання Орди від Дарсока Свіфтдаґґера на Перехресті.",kw={"гарпії-офіцери","дарсок свіфтдаґґер","відьмокрили","сухі пагорби","серена бладфезер","розбійник"},ang={["class:Rogue"]="Дарсок Свіфтдаґґер покладається на точні вбивства цінних офіцерів, а не на дорогу відкриту війну, — саме те, у чому розбійники знаються найкраще.",["faction:Horde"]="Убезпечення північних шляхів Пусток необхідне, щоб налагодити надійний зв'язок між Дуротаром, Малгором і лісорубними таборами в Ашенвалі."},sec={{t="Ціль — офіцери",b="Після перших сутичок зі звичайними нальотчицями-Відьмокрилами Дарсок Свіфтдаґґер посилює наступ на гарпій, що гніздяться на Сухих Пагорбах. Замість того щоб і далі проріджувати рядових, Дарсок доручає розвідникам Орди полювати на вбивць-Відьмокрилів, що служать офіцерками. Ці офіцерки тримають дисципліну серед нижчих гарпій і керують набігами на шляхи постачання Орди, тож їхнє знищення вкрай важливе, щоб убезпечити північні підступи до Пусток."},{t="Знаки звання",b="Оскільки вбивці-Відьмокрили ведуть своїх родичок грубою силою й пануванням, лише найлютіші з них носять оздоблені персні — знаки влади в їхньому матріархаті. Ці персні — доказ смерті: їхнє здобуття руйнує тактичну злагодженість гніздовища й шле зграї пряме, безжальне послання: на напади на землі Орди відповідатимуть рішучою відплатою."},{t="Шлях до праматері",b="Страта цих офіцерок кидає нижчих гарпій у безлад, але має й ширшу стратегічну мету. Позбавивши гніздовище Відьмокрилів польових командирок, Орда послаблює оборону довкола висот Сухих Пагорбів і відкриває шлях до внутрішнього святилища їхньої праматері — Серени Бладфезер."}},faq={{q="Де знайти гарпій-офіцерів?",a="Гарпії-офіцери — на Сухих Пагорбах, порізаній місцевості з каньйонами на крайній півночі Пусток, на північний захід від Перехрестя. Шукайте вбивць Відьмокрилих, що патрулюють пагорби.",al={"місце лейтенантів","де відьмокрилі убивці","місце гарпій-офіцерів"}},{q="Як упізнати цих офіцерів у зграї?",a="У ковені Відьмокрилих офіцерами служать лише вбивці Відьмокрилих. Вони носять особливі персні гарпій — знак влади над нижчими розвідницями й нальотчицями.",al={"які гарпії з кільцями","впізнати відьмокрилих убивць"}},{q="Хто призначає цю нагороду?",a="Цю угоду дає Дарсок Свіфтдаґґер, орк-розвідник і координатор на Перехресті в Пустках, щоб захистити інтереси Орди й покарати гарпій за набіги.",al={"хто дає гарпій-офіцерів","роль дарсока свіфтдаґґера"}},{q="Чому Орда хоче вбити офіцерів, а не просто звичайних гарпій?",a="Офіцери керують нижчими посіпаками й організовують хижацькі напади. Знищення офіцерів розбиває провід матріархату, і решта гарпій лишається розладнаною й вразливою.",al={"чому вбивати офіцерів","командування гарпій"}},{q="Що буде, коли офіцерів знищено?",a="Коли офіцерів убито, Дарсок Свіфтдаґґер посилає поборників вистежити саму ватажицю зграї, Серену Бладфезер, на найвищих кручах Сухих Пагорбів.",al={"наступне завдання після офіцерів","що робити далі"}},{q="Чому гарпії Відьмокрилі загрожують Перехрестю?",a="Ковен Відьмокрилих заполонив північні перевали Пусток і полює на мандрівників, обози з припасами й патрулі, що намагаються пройти між Перехрестям, Дуротаром і Ашенвалем.",al={"чому битися з гарпіями","загроза відьмокрилих"}}},fp="17,291,22.478.0,14.395.0,23.287.1,38.194.0,53.172.0,23.169.0,80.191.0,45.180.1,57.185.0"}
P.entries["quest:876"] = {n="Серена Бладфезер",s="Це доручення-винагорода посилає шукачів пригод з Орди вбити Серену Бладфезер — праматір, що веде набіги гарпій на шляхи постачання Перехрестя. Її кампанія — особиста кровна помста за те, що Чемпіон Орди Рекссар убив її сестру. Покінчивши із Сереною, Орда сподівається зруйнувати злагодженість зграї гарпій на півночі Пусток.",h="Це доручення-винагорода посилає шукачів пригод з Орди вбити Серену Бладфезер — праматір, що веде набіги...",kw={"серена бладфезер","дарсок свіфтдаґґер","гарпії","відьмокрили","рекссар","помста"},ang={["class:Rogue"]="Дарсок Свіфтдаґґер захоплюється холоднокровною дієвістю й закликає швидко перерізати Серені горло, а не затягувати бійку.",["faction:Horde"]="Північні торгові шляхи через Перехрестя життєво важливі для постачання оркських застав і поєднують Дуротар із Малгором і Горами Кам'яного Кігтя; розгром організованих гарпій-нападниць тримає ці артерії відкритими.",["race:Orc"]="Це полювання завершує незакінчені справи, що тягнуться від подвигів Рекссара, і пробуджує лютий дух ранньої боротьби за рубежі Дуротару."},sec={{t="Спадщина помсти",b="Гарпії-Відьмокрили, що кишать на скелях на північний захід від Перехрестя, нападають не лише зі звірячого голоду. Їхня ватажка, Серена Бладфезер, веде відверту кровну помсту проти Орди. Багато років тому, коли засновували Дуротар, мандрівний володар звірів Рекссар убив сестру Серени — горезвісну праматір на ім'я Бладфезер. Пойнята ненавистю до молодої Орди, Серена згуртувала свою зграю в організовану напасть, що прагне вирізати обози з припасами, розвідників і купців на посушливих стежках."},{t="Відтяти голову",b="Дарсок Свіфтдаґґер на Перехресті керує планомірним винищенням гарпій — від дрібних нальотчиць до бувалих офіцерок. Убивство Серени — останній, вирішальний удар по цій загрозі. Дарсок прямо вимагає її відтяту голову — не лише як доказ, а як моторошний трофей, який прилаштують на першому ж каравані, що вирушить у дорогу. Піднявши голову праматері перед уцілілими гарпіями, Орда сподівається налякати зграю так, щоб та облишила напади на життєві шляхи Пусток."}},faq={{q="Чому Серена Бладфезер нападає на каравани Орди?",a="Серена прагне помститися Орді. Її сестру, ватажицю гарпій Бладфезер, убив поборник-мок'натал Рекссар, коли засновували Дуротар. На відплату за смерть сестри Серена посилає свою зграю на обози й мандрівників Орди.",al={"чому гарпії нападають на каравани","мотив серени","чому серена розлючена"}},{q="Ким була Бладфезер?",a="Бладфезер — горезвісна ватажиця гарпій, що багато років тому тероризувала кордони Дуротару й Пусток. Рекссар вистежив і вбив її під час своїх мандрів на службі Вождя Тралла. Серена — її сестра, що вціліла й успадкувала і її місце, і її злобу.",al={"сестра серени","перша бладфезер","рексар бладфезер"}},{q="Навіщо Дарсокові Свіфтдаґґеру її голова?",a="Окрім того, що голова підтверджує її смерть, Дарсок збирається почепити відтяту голову Серени на віз каравану, що вирушає в дорогу. Він вважає, що доля ватажиці стане суворим попередженням для всіх уцілілих гарпій, яким заманеться напасти на шляхи постачання Орди.",al={"навіщо дарсоку голова","голова серени дарсок"}},{q="Де знайти Серену Бладфезер?",a="Серена гніздиться високо серед порізаних круч і вивітрених скель на північний захід від Перехрестя, в оточенні добірних офіцерів і охоронниць ковену Відьмокрилих.",al={"місце серени бладфезер","де серена","поява серени"}},{q="Що буде після перемоги над Сереною?",a="Коли загрозу від гарпій усунуто, Дарсок посилає надійних найманців допомогти іншим союзникам, що потребують підмоги, — з листом до знахаря Джин'Зіла в Горах Кам'яного Кігтя.",al={"що після серени","ланцюжок після серени"}},{q="Хто призначив цю нагороду?",a="Дарсок Свіфтдаґґер, орк-розвідник і агент на Перехресті, керує приборканням диких загроз для торгових шляхів і призначає нагороду, коли нижчі лави її зграї вже розбито.",al={"хто дає завдання серени","роль дарсока"}}},fp="19,354,21.528.0,20.514.1,52.269.0,21.244.0,42.251.0,39.160.0,38.190.1,25.212.0"}
P.entries["quest:877"] = {n="Застояна оаза",s="«Застояна оаза» — дослідницьке завдання від друїда Тонги Рунтотема на Перехресті. Після відкриттів у Забутих ставках Тонга доручає мандрівникам дослідити каламутні води на південному сході й з'ясувати, чи немає там подібної підводної тріщини. Випробування таємничих енергій неживим насінням відкриває глибоку, незбагненну силу, що вирує під посушливою землею.",h="«Застояна оаза» — дослідницьке завдання від друїда Тонги Рунтотема на Перехресті.",kw={"застояна оаза","тонга рунтотем","тріщина","насіння","коло кенарія","друїд"},ang={["faction:Horde"]="Убезпечення й розуміння надійних прісноводних оаз біля Перехрестя вкрай важливе для захисту торгових караванів і військових застав у суворих Пустках.",["race:Tauren"]="Це завдання промовляє до тауренського обов'язку шанувати Земну Матір, розуміючи раптові глибокі порушення природної рівноваги на родових мисливських угіддях."},sec={{t="Пошуки прихованих вод",b="Виявивши дивну підземну тріщину, що вирує під Забутими ставками, Тонга Рунтотем підозрює, що раптові спалахи буйної зелені в посушливих Пустках — не простий збіг. Він посилає шукачів пригод на південний схід, до Застояної Оази, щоб перевірити, чи немає подібного отвору під її каламутною мілиною, де повно хижаків."},{t="Іскра життя",b="Щоб перевірити природу джерела, Тонга дає висушене, неплідне насіння, яке не здатне прорости саме. Варто занурити ці мертві зернята просто в бульбашкову тріщину — і вони вибухають дивовижним ростом. Присутність діяльного підземного джерела, здатного вдихнути життя в мертву матерію, підтверджує, що незвичайні, неприродні сили активно змінюють землю."}},faq={{q="Хто дає завдання «Застояна оаза»?",a="Завдання дає Тонга Рунтотем, друїд-таурен на Перехресті в центрі Пусток, одразу після дослідження Забутих ставків.",al={"видавець завдання","де взяти","завдання тонги"}},{q="Що робить висушене насіння?",a="Tonga provides dead, infertile seeds as a test. He asks you to place them in any fissure beneath the Stagnant Oasis and observe whether the waters have an effect.",al={"висушене насіння","призначення насіння","випробування насіння"}},{q="Де Застояна оаза?",a="Застояна оаза лежить на південний схід від Перехрестя в Пустках, серед скелястих круч; там живуть черепахи-клацуни, кентаври Колкари й водяні звірі.",al={"місце оази","де застояна оаза","місце на мапі"}},{q="Яке значення мають підводні розколини?",a="The fissures are mysterious cracks beneath the oasis waters. Tonga suspects they may be the source of the oases' life and asks travelers to test that possibility.",al={"підводні розколини","розколини оази","розлом, що булькає"}},{q="Яке завдання йде далі в ланцюжку?",a="Повернувшись до Тонги Рунтотема зі знахідками, ви переходите до завдання «Змінені істоти», де розслідування зосереджується на мутаціях і агресії звірів довкола водойм.",al={"наступне завдання","продовження","після застояної оази"}},{q="Чому Коло Кенарія цікавлять ці водойми?",a="Друїди Кенарія давно шукають способів зцілити суху савану Пусток. Знайти джерела, що самі породжують життя, — захопливо, але раптовість і дивна природа цього явища насторожують: що, як воно неприродне чи розхитує рівновагу?",al={"чому коло кенарія цікавлять ставки","інтерес кенарія","друїди й оази"}}},fp="18,394,26.340.0,21.380.1,40.169.0,27.162.0,36.170.0,52.162.0,35.211.0,53.259.0"}
P.entries["quest:878"] = {n="Війна племен",s="«Війна племен» — завдання Орди від полоненого шипогрива Понівечозуба в Таборі Тауражо. Замкнений тауренами за ґратами, Понівечозуб обмінює важливі відомості про вторгнення шипогривів на смерть духовних провідників ворожого племені Щетиноспинів.",h="«Війна племен» — завдання Орди від полоненого шипогрива Понівечозуба в Таборі Тауражо.",kw={"війна племен","понівечозуб","щетиноспини","гостромани","геоманти","табір тауражо"},ang={["class:Shaman"]="Геоманти шипогривів підкоряють землю й камінь завдяки первісним угодам із прадавніми духами — для шаманів це груба, але могутня перекрученість шани до стихій.",["faction:Horde"]="Табір Тауражо оточений ворожими хащами, тож кожна нагода нацькувати диких шипогривів одних на одних — тактична перемога для шляхів постачання Орди.",["race:Tauren"]="Як господарі Табору Тауражо, таурени терплять присутність Понівечозуба лише доти, доки його ворожнеча приносить безпеку південному рубежу."},sec={{t="Угода в'язня",b="Замкнений у клітці в Таборі Тауражо, шипогрив-Гостроман Понівечозуб доводить, що неволя не притуплює давньої ненависті. Пустки здавна ділять між собою дві панівні фракції шипогривів — Гостромани й Щетиноспини. Поки Орда силкується вберегти свої поселення й шляхи постачання від раптових засідок, Понівечозуб пропонує цінні відомості про те, хто насправді дошкуляє заставі Торка, — якщо звитяжець Орди спершу вб'є найшанованіших заклиначів Щетиноспинів."},{t="Ціль — ткачі землі",b="Понівечозуб посилає шукачів пригод на північ, проти містичного ядра Щетиноспинів: їхніх шукачів води, ткачів терну й геомантів. Обидва племена шанують землю й черпають сиру силу з прадавньої магії, пов'язаної з їхнім прабатьком-напівбогом Аґамаґґаном. Знищуючи їхніх заклиначів, Орда завдає нищівного удару обрядовій силі Щетиноспинів, робить їх вразливими перед суперниками-Гостроманами й послаблює тиск на сусідні стежки."},{t="Гіркі одкровення",b="Коли справу зроблено, помста не приносить Понівечозубові спокою. Замість того щоб радіти втратам Щетиноспинів, в'язень впадає в лють через те, що його покинули. Хоч він і спрямовував удари на користь свого племені з-за залізних ґрат, Гостромани не прислали до Табору Тауражо жодного рятувального загону. Зневажений і забутий, Понівечозуб звертає погляд на ще глибші таємниці шипогривів і відкриває шлях до сили крові Аґамаґґана."}},faq={{q="Чому Понівечозуб сидить у клітці в Таборі Тауражо?",a="Понівечозуб — шипогрив із Гостроманів, якого схопили сили Орди в Таборі Тауражо. Таурени тримають його в полоні, щоб запобігти набігам і витягти з нього відомості про вторгнення шипогривів на півдні Пусток.",al={"чому понівечозуб у клітці","хто схопив понівечозуба","клітка понівечозуба"}},{q="Яка ворожнеча між Гостроманами й Щетиноспинами?",a="Гостромани й Щетиноспини — суперницькі племена шипогривів, що запекло борються за землю, рідкісну воду й священні тернові угіддя Пусток. Хоча обидва ведуть духовний родовід від Великого Вепра Аґамаґґана, вони ненавидять одне одного й безупинно б'ються за владу над рівнинами.",al={"щетиноспини проти гостроманів","чому вепролюди воюють одне з одним","війна вепролюдів"}},{q="Чому Понівечозуб хоче смерті саме їхніх духовних провідників?",a="Війна шипогривів значною мірою спирається на їхній зв'язок із землею й магію крові. Геоманти, Терноплети й Шукачі Води підтримують життя племені, закликають у бою камінь і терни й ведуть воїнів. Удар по заклиначах ламає дух племені й підтинає його бойову силу.",al={"чому вбити геомантів","заклиначі щетиноспинів","шукачі води й терноплети"}},{q="Хто такий Торк і чому Понівечозуб його згадує?",a="Торк — орк-офіцер, що керує справами й безпекою Орди на Перехресті та по всіх Пустках. Його загони постійно відбивають натиск бойових ватаг шипогривів, тож відомості про пересування племен для нього надзвичайно цінні.",al={"хто такий торк","табір торка тауражо","торк орда"}},{q="Що буде після цього завдання?",a="Озлоблений тим, що плем'я не прийшло його визволити, Понівечозуб пропонує відкрити таємницю Кривавих Уламків. Це відкриває завдання «Криваві Уламки Аґамаґґана», і згодом гравці можуть міняти уламки, знайдені на шипогривах, на різні благословення духів племені.",al={"продовження війни племен","що відкриється після війни племен","наступне завдання після понівечозуба"}},{q="Де знайти духовних провідників Щетиноспинів?",a="Шукачі Води, Терноплети й Геоманти Щетиноспинів живуть у тернових хащах, таборах і ярах, які тримає плем'я Щетиноспинів на півдні Пусток, трохи на північ від Табору Тауражо.",al={"місце шукачів води щетиноспинів","де терноплети","місце геомантів щетиноспинів"}}},fp="13,264,20.484.0,26.422.0,18.443.1,52.225.0,59.302.0,68.295.0,51.234.0,41.253.1,46.186.0"}
P.entries["quest:879"] = {n="Зрада зсередини",s="«Зрада зсередини» — доручення від Понівечозуба, ув'язненого шипогрива, якого тримають у клітці в Таборі Тауражо. Зневажений і покинутий родичами напризволяще, Понівечозуб прагне кривавої помсти трійці воєначальників-Гостроманів, що вийшли з Рейзорфен Краулу, щоб організовувати напади по всіх Пустках.",h="«Зрада зсередини» — доручення від Понівечозуба, ув'язненого шипогрива, якого тримають у клітці в Таборі...",kw={"зрада зсередини","понівечозуб","лок оркбейн","гостромани","рейзорфен краул","табір тауражо"},ang={["faction:Horde"]="Зупинивши Лока Оркбейна та його спільників, ви вдаряєте просто по ватажках, винних у жорстоких нападах на каравани й застави Орди на півдні Пусток.",["race:Orc"]="Воєначальник Лок носить прізвисько «Оркбейн» — тобто погибель орків — саме за вправність і ненависть, з якими він вирізає оркських мандрівників по всьому краю.",["race:Tauren"]="Табір Тауражо стоїть просто на південному шляху, де агресія Гостроманів найзапекліша, тож знищення цих воєначальників вкрай важливе для місцевої безпеки."},sec={{t="Образа в клітці",b="Знемагаючи в неволі під сонцем Табору Тауражо, шипогрив Понівечозуб більше не відчуває жодної вірності родичам-Гостроманам. Покинутий після поразки й приречений на страту, він має одне-єдине бажання — помститися ватажкам, які його кинули. Для цього він пропонує мандрівникам Орди важливі відомості про справжніх натхненників безжальних набігів, що мучать рівнини."},{t="Воєначальники Краулу",b="Поки очільники Орди на Перехресті, як-от Торк, силкуються приборкати безупинну агресію шипогривів, Понівечозуб розкриває корінь проблеми: трьох досвідчених командирів із глибин Рейзорфен Краулу. На чолі з грізним воїном Локом Оркбейном, разом зі слідопитом Кузом і заклиначем Наком, ця трійця спрямовує нападників-Гостроманів із таборів далеко на півдні. Понівечозуб вимагає їхні відтяті черепи як доказ того, що його зрадники полягли раніше, ніж настане його власний кінець."}},faq={{q="Чому шипогрив допомагає Орді?",a="Понівечозубом рухає лише помста, а не дружба з Ордою. Родичі відвернулися від нього й лишили помирати в клітці в Таборі Тауражо. Його власна смерть неминуча, тож він охоче допомагає Орді — аби тільки його зрадники загинули першими.",al={"чому понівечозуб допомагає","мотив понівечозуба","чому вепролюд зраджує своїх"}},{q="Хто такі Нак, Куз і Лок Оркбейн?",a="Це троє знаних ватажків Гостроманів, що вийшли з Рейзорфен Краула, щоб організовувати набіги по всіх Пустках. Лок Оркбейн — лютий воїн і ватажок, а з ним містик-заклинач Нак і слідопит Куз.",al={"хто такі цілі","ватажки гостроманів","переказ про лока оркбейна"}},{q="Де знайти цих трьох?",a="Вони отаборилися далеко на півдні Пусток, окопавшись на землях Гостроманів біля межі південних чагарників.",al={"де лок оркбейн","де нак і куз","місця цілей"}},{q="Що Понівечозуб має на увазі, кажучи, що Торк помиляється?",a="Торк, що керує обороною з Перехрестя, вважає, ніби знає, хто стоїть за нападами шипогривів на шляхи постачання Орди. Понівечозуб запевняє, що Торк помиляється щодо справжніх натхненників, і стверджує, що руйнівні напади насправді влаштовують Лок Оркбейн, Нак і Куз.",al={"помилка торка","в чому помиляється торк","торк і понівечозуб"}},{q="Чи справді смерть цих ватажків принесе мир із Гостроманами?",a="Понівечозуб хвалиться, що загибель цієї трійці дасть Перехрестю й більшій частині Пусток перепочинок від набігів Гостроманів. Це розбиває їхній безпосередній провід на півдні, але глибоко вкорінена ворожість шипогривів по всіх Пустках ще далеко не згасла.",al={"чи в пустках настане мир","кінець гостроманів","гостроманів переможено"}},{q="Що буде з Понівечозубом після цього?",a="Понівечозуб змирився з тим, що в таборі Орди смерті йому не уникнути. Він не шукає ні втечі, ні милосердя — лише втіхи побачити, як падуть його зрадливі одноплемінники, перш ніж настане його кінець.",al={"чи понівечозуб вільний","доля понівечозуба","чи страчено понівечозуба"}}},fp="20,298,18.403.0,25.482.0,36.274.0,34.220.0,34.140.0,51.287.0,64.262.0,39.202.0"}
P.entries["quest:88"] = {n="Принцеса має померти!",s="«Принцеса має померти!» — місцева винагорода від Ма Стоунфілд із Ферми Стоунфілдів на півдні Лісу Елвінн. Вона хоче покласти край Принцесі — величезній призовій свині з сусідньої Гарбузової Ділянки Брекуеллів, яка раз у раз плюндрує її дорогоцінні грядки. Коли буйну свиню буде вбито, Стоунфілди зможуть спокійно зібрати врожай.",h="«Принцеса має померти!» — місцева винагорода від Ма Стоунфілд із Ферми Стоунфілдів на півдні Лісу Елвінн.",kw={"принцеса","свиня","ма стоунфілд","ферма стоунфілдів","гарбузова ділянка","нашийник","вепри"},ang={["faction:Alliance"]="Допомога місцевим фермерам на кшталт Ма Стоунфілд у боротьбі з норовливою худобою підтримує південну житницю Стормвінда, поки регулярної армії королівства тут немає.",["profession:Cooking"]="Розправа з велетенською свинею Принцесою — легендарна історія серед місцевих кухарів, адже велетенські вепри Елвінну дають удосталь ситного м'яса для смаження на відкритому вогні."},sec={{t="Загроза врожаю",b="Ферма Стоунфілдів живе з урожаю, та ненажерлива напасть поставила його під загрозу. Принцеса, уславлена призова свиня Брекуеллів, виросла до потворних розмірів, залазячи на грядки Стоунфілдів і пожираючи їхню городину. Ма Стоунфілд досить нахабної свині, що бенкетує плодами її тяжкої праці, і вона хоче, щоб тварюку вбили, перш ніж та знищить урожай цілого сезону."},{t="Свиняче Поріддя",b="Принцеса рідко блукає сама. На Гарбузовій Ділянці Брекуеллів, що лежить на схід за садибою Маклурів, її постійно оточує вірний почет вепрів-охоронців. Щоб убити цю велетенську свиню, доведеться прорубатися крізь її варту й зняти з її шиї прикметний мідний нашийник — доказ того, що ненажерлива тварюка більше не турбуватиме поля Стоунфілдів."}},faq={{q="Хто така Принцеса?",a="Принцеса — величезна свиноматка-призерка, що належить родині Брекуеллів. Вона так розгодувалася насамперед тому, що потай навідувалася на Ферму Стоунфілдів і об'їдалася добірними овочами Ма Стоунфілд.",al={"хто така принцеса","принцеса елвінн","свиня принцеса"}},{q="Чому Ма Стоунфілд хоче смерті Принцеси?",a="Ма Стоунфілд набридло, що Принцеса забрідає на її поля й пожирає овочі. Боячись, що величезна свиня з'їсть увесь урожай родини, перш ніж його зберуть, вона наймає мандрівників убити звірину й принести як доказ її латунний нашийник.",al={"чому вбити принцесу","ма стоунфілд свиня","чому принцеса має померти"}},{q="Де знайти Принцесу?",a="Принцеса живе на Гарбузовій Ділянці Брекуеллів на південному сході Лісу Елвінн, на схід за Виноградниками Маклюрів. Вона блукає серед потрощених гарбузів під охороною почту вепрів.",al={"місце принцеси","де принцеса","поява принцеси"}},{q="Кому належить Гарбузова Ділянка Брекуеллів?",a="Ділянка належить родині Брекуеллів — місцевим фермерам, чиї справи підупали через бандитів і набіги диких звірів на півдні Лісу Елвінн. Хоча вони й закинули ділянку, Принцеса лишилася там доїдати рештки.",al={"хто такі брекуелли","переказ про ферму брекуеллів","власники брекуеллів"}},{q="Як довести, що Принцеса мертва?",a="Здолавши свиноматку, треба зняти з її шиї Латунний Нашийник і віднести його Ма Стоунфілд на Ферму Стоунфілдів.",al={"доказ принцеси","який предмет принцеса","латунний нашийник"}},{q="Чи б'ється Принцеса сама?",a="Ні, з Принцесою — Свиняче Поріддя: вепри-охоронці, що кидаються на кожного, хто намагається вбити свиноматку-призерку.",al={"свита принцеси","охорона принцеси","принцеса і помічники"}}},fp="18,353,23.426.0,21.383.0,16.219.0,44.265.0,28.186.0,37.258.0,34.136.0,26.135.0"}
P.entries["quest:880"] = {n="Змінені істоти",s="«Змінені істоти» — завдання Орди від Тонги Рунтотема на Перехресті в Пустках. Після відкриття загадкових тріщин, що живлять місцеві водойми, Тонга доручає шукачам пригод зібрати панцири змінених щелепанів, щоб з'ясувати, як неприродні води впливають на місцеву звірину.",h="«Змінені істоти» — завдання Орди від Тонги Рунтотема на Перехресті в Пустках.",kw={"змінені істоти","тонга рунтотем","щелепані","оаза буйних вод","застояна оаза","друїд"},ang={["class:Druid"]="Для друїдів вивчення щелепанів показує тендітну межу між природною життєвою силою й спотвореною мутацією й дає змогу зблизька побачити збурення, що визріває під Пустками.",["faction:Horde"]="Безпека й чистота водних джерел довкола Перехрестя вкрай важливі, щоб уберегти серце земель Орди від несподіваних магічних небезпек.",["race:Tauren"]="Рівновага Земної Матері в Пустках помітно похитнулася, тож зусилля Тонги Рунтотема глибоко особисті для тауренів, що шукають злагоди на родових землях."},sec={{t="Неприродні води",b="Посушливі савани Пусток усіяні кількома родючими оазами, але їхня життєва сила не цілком природна. Дослідження друїда Тонги Рунтотема виявили дивні підземні тріщини, з яких струмують незвичні, могутні енергії. Підозрюючи, що невідоме джерело сили — чи то занесене ззовні, чи то таке, що б'є з глибин землі, — змінює довкілля, Тонга звертає увагу на істот, які п'ють із цих водойм і живуть у них."},{t="Знаки на панцирі",b="Щоб оцінити вплив тріщин на довкілля, Тонга посилає мисливців до Оази Буйних Вод і Застояної Оази. Місцеві щелепані, що живуть на мілинах, увібрали таємничу суть через їжу й воду, і на їхніх панцирах проступили помітні мутації. Оглядаючи ці змінені панцири, Тонга сподівається розгадати, яке саме магічне чи природне збурення впливає на землю, перш ніж воно пошириться далі Калімдором."}},faq={{q="Хто дає завдання «Змінені істоти»?",a="Завдання дає Тонга Рунтотем, друїд-таурен на Перехресті в центрі Пусток.",al={"видавець завдання","де взяти змінені істоти","хто починає змінені істоти"}},{q="На яких істот треба полювати в цьому дорученні?",a="Треба полювати на оазових черепах-клацунів, що живуть у водах і Оази Буйних Вод, і Застояної оази в Пустках.",al={"які істоти дають шкаралупи","цілі змінених щелепників","кого вбивати"}},{q="Чому черепахи-клацуни змінилися?",a="Загадкові розколини під оазами вимивають у воду дивну енергію. У тварин, що живуть у водоймах чи п'ють із них, з'явилися мутації, які помітно змінили їхні панцири.",al={"чому щелепники змінилися","що змінило черепах","що не так зі звірами оаз"}},{q="Де Оаза Буйних Вод і Застояна оаза?",a="Обидві оази лежать на південь від Перехрестя в Пустках. Застояна оаза — на південному сході, ближче до кордону з Багном Пилоброду, а Оаза Буйних Вод — на південному заході, біля входу до Печер Стогонів.",al={"місця оаз пусток","місце буйних вод","місце застояної оази"}},{q="Що буде після завдання «Змінені істоти»?",a="Тонга Рунтотем розуміє, що таємниця глибша за звичайних диких звірів, і скеровує шукачів пригод доповісти про знахідки вищим друїдам-старійшинам — Гамуулові Рунтотему чи Мурі Рунтотем.",al={"наступне завдання після змінених істот","куди веде ланцюжок","продовження змінених істот"}},{q="Чому Тонга Рунтотем досліджує оази?",a="Як друїд, Тонга прагне збагнути рівновагу природи в Пустках. Раптове неприродне буяння довкола оаз натякає на дію глибинних підземних сил, які, як бояться друїди, можуть порушити тендітну природу савани.",al={"мотив тонги рунтотема","чому досліджувати оазу","коло кенарія в пустках"}}},fp="14,302,16.492.0,18.449.0,35.103.0,47.131.0,29.204.0,43.217.0,45.211.1,42.227.0"}
P.entries["quest:881"] = {n="Ечеякі",s="Ечеякі — легендарний білий лев, що скрадається північними Пустками; таурени шанують його під ім'ям Білий Туман. Через Серґру Даркторн на Перехресті молодих мисливців Орди посилають викликати цього верховного хижака й помірятися з ним силою.",h="Ечеякі — легендарний білий лев, що скрадається північними Пустками; таурени шанують його під ім'ям Білий...",kw={"ечеякі","білий туман","серґра даркторн","перехрестя","білий лев","пустки"},ang={["class:Hunter"]="Завдяки рідкісному світлому хутру й легендарній славі серед звірів савани Ечеякі — бажаний супутник для молодих приборкувачів звірів, що мандрують Пустками.",["faction:Horde"]="Полювання на Ечеякі — обряд посвяти для молодих звитяжців із Перехрестя, що доводить їхнє вміння вижити серед суворої звірини Пусток.",["race:Tauren"]="Ечеякі має для тауренів священне значення як Білий Туман — втілення чистого, безболісного вбивства й взірець лютої рівноваги Земної Матері."},sec={{t="Білий Туман савани",b="Відомий мовою таур-ахе як Ечеякі, тобто «Білий Туман», цей білогривий лев панує над котами савани на центральних рівнинах. Легенда каже, що він скрадається так моторошно тихо й непомітно, що скидається на низький ранковий туман, який пливе над червоною землею. Його напади такі стрімкі, що здобич гине, не встигнувши ні злякатися, ні відчути болю, тож місцеві мисливці шанують його як втілення і милосердя, і швидкої смерті."},{t="Випробування рогом",b="Серґра Даркторн, досвідчена оркська мисливиця, що вишколює молодих воїнів на Перехресті, посилає своїх учнів кинути виклик цареві звірів, щойно ті доведуть свою вправність у сутичках із меншими нишпорками савани. З особливим рогом мисливець вирушає на північний схід, за гірські кряжі, до цвинтаря велетенських кісток кодо. Звук рогу кидає виклик просто Ечеякі й виманює примарного хижака зі схованки на двобій сили й хитрості."},{t="The Lion's Legacy",b="When Echeyakee's hide is returned, Sergra says his hunting days are over but his spirit is with the victor. She teaches that his example shows strength in subtlety and honor in mercy."}},faq={{q="Що означає ім'я Ечеякі?",a="Мовою тауренів Ечеякі означає «Білий Туман». Ім'я вшановує бліде хутро кота й безгучну, мов туман, потайність, з якою він скрадається рівнинами.",al={"переклад ечеякі","значення ечеякі","ім'я тауренів ечеякі"}},{q="Де викликають Ечеякі?",a="Ечеякі має лігво на північний схід від Перехрестя, за гірським хребтом. Він відпочиває серед розкиданих велетенських скелетів кодо й з'являється лише тоді, коли його викликати рогом, який дає Серґра Даркторн.",al={"де ечеякі","місце ечеякі","як знайти ечеякі"}},{q="Чому Ечеякі називають і милосердям, і смертю?",a="За мисливською традицією тауренів, він — і милосердя, і смерть, бо б'є миттєво. Він убиває здобич так влучно й швидко, що жертва не встигає зазнати ні довгих мук, ні страху.",al={"милосердя і смерть","переказ про ечеякі"}},{q="Хто посилає мисливців по Ечеякі?",a="Серґра Даркторн, мисливиця-орчиха на Перехресті, доручає це полювання, щоб перевірити, чи розуміє шукач пригод тонкість і рівновагу, потрібні справжньому хижакові.",al={"хто дає ечеякі","завдання серґри даркторн"}},{q="Що буде, коли Ечеякі вбито?",a="Sergra asks you to return Echeyakee's hide to her at the Crossroads as proof of the hunt.",al={"що з ечеякі","дух ечеякі"}},{q="Що йде після полювання на Ечеякі?",a="Коли мисливець покаже терпіння й смертоносну вправність, потрібні, щоб здолати Ечеякі, Серґра Даркторн переводить його до мінливішої здобичі — лютих рапторів, відомих як косокігті.",al={"завдання після ечеякі","що далі після ечеякі"}}},fp="9,240,25.434.0,21.458.0,17.183.1,34.177.0,28.206.0,51.216.0,34.176.0,38.89.0,35.186.0"}
P.entries["quest:882"] = {n="Ішамугале",s="«Ішамугале» — мисливський обряд, який доручає Джорн Скайсір у Таборі Тауражо. Щоб випробувати вашу вправність і шану до найсмертоносніших хижаків природи, вам доведеться приманити й убити найлютішого сонцелуского раптора в Пустках.",h="«Ішамугале» — мисливський обряд, який доручає Джорн Скайсір у Таборі Тауражо.",kw={"ішамугале","списозуб","джорн скайсір","раптори","табір тауражо","мисливець"},ang={["class:Hunter"]="Виманити невловимого верховного хижака свіжою принадою й знанням місцевості — це давнє мистецтво скрадання, що вшановує терпіння й хитрість майстрів-слідопитів.",["faction:Horde"]="Знищення легендарних загроз на кшталт Ішамугале доводить гідність новачка й робить шляхи між Раджетом і Тауражо хоч трохи безпечнішими для мандрівників Орди.",["race:Tauren"]="Для тауренських мисливців двобій з Ішамугале — важливий урок рівноваги: відбираючи життя могутнього хижака, ви мусите мати дисципліну, щоб приборкати лютий дух, який успадковуєте."},sec={{t="Природа Списозуба",b="Серед хижаків Пусток сонцелускі раптори наводять страх своєю хитрістю й жорстокою зграйною тактикою, але ніхто не викликає такого жаху, як Ішамугале. Відомий як Списозуб, він никає саваною не лише заради їжі чи території. Як пояснює Джорн Скайсір, Ішамугале полює з чистого інстинкту й пристрасті — він убиває просто тому, що така його природа. Сутичка з такою істотою перевіряє, чи здатен мисливець вистояти перед чистою, неприборканою звірячою злобою."},{t="Приманити звіра",b="Ішамугале — не та здобич, на яку можна просто натрапити, коли вона відпочиває в гнізді. Щоб виманити великого раптора, мисливець мусить наслідувати природний ритм рівнин. Джорн велить претендентові вполювати свіжу жевру — улюблену здобич раптора — і притягти тушу до самотнього всохлого дерева на північний захід від Раджета. Приваблений запахом свіжої крові, що лине з сухим вітром, Ішамугале швидко з'являється, щоб забрати здобич."},{t="Тягар сили",b="Принести ікло Ішамугале до Табору Тауражо — це більше, ніж похвалитися бойовою перемогою. Джорн Скайсір вважає цей трофей глибокою духовною віхою. За тауренськими віруваннями, здолати такого лютого верховного хижака — означає перейняти дещицю його сирої сили. Справжнє випробування, що настає потім, — внутрішнє: нести цю хижу міць стримано, з честю й мірою, а не піддатися сліпій жазі крові."}},faq={{q="Хто такий Ішамугале?",a="Ішамугале на прізвисько Списозуб — надзвичайно лютий сонцелуский раптор, що нишпорить Пустками. На відміну від звичайних звірів, яких жене лише голод, він полює невпинно, з самої хижацької натури й пристрасті.",al={"що таке ішамугале","хто такий списозуб","переказ про раптора ішамугале"}},{q="Як викликати Ішамугале?",a="Ішамугале треба виманити свіжою здобиччю. Роздобудьте свіжу тушу жеври й повісьте її на визначеному сухому дереві на північний захід від гоблінського порту Раджет. Запах швидко виманить його зі схованки.",al={"як викликати ішамугале","де ішамугале","приманка для ішамугале"}},{q="Де починається й закінчується це завдання?",a="Завдання дає Джорн Скайсір, мисливець-таурен із Табору Тауражо на півдні Пусток. Коли Ішамугале вбито, поверніть його ікло Джорнові в таборі.",al={"видавець ішамугале","хто дає ішамугале","де здати ішамугале"}},{q="Чому Джорн Скайсір хоче смерті Ішамугале?",a="Джорн прагне не знищення зі злості. Вистежити й здолати Ішамугале — духовне випробування, що має перевірити мисливця найсирішою люттю природи й навчити стриманості тоді, коли переймаєш таку лютість.",al={"чому вбити ішамугале","мотив джорна скайсіра"}},{q="Що буде після завдання «Ішамугале»?",a="Коли ви покажете себе в сутичці з Ішамугале, Джорн Скайсір скерує вас до більших загроз, що порушують рівновагу Пусток, — далі буде завдання «Розлючені громоящери» на півдні.",al={"завдання після ішамугале","наступне завдання після раптора"}},{q="Яке місце це завдання посідає в ланцюжку Серґри Даркторн?",a="Воно продовжує великі мисливські випробування, які почала Серґра Даркторн на Перехресті. Коли ви покажете свою вправність на північних рівнинах, Серґра посилає вас на південь, до Джорна Скайсіра в Табір Тауражо, — зійтися з найгрізнішими звірами.",al={"зв'язок із серґрою даркторн","ланцюжок полювання перехрестя"}}},fp="10,220,24.454.0,17.423.0,22.421.0,18.207.0,29.222.0,36.169.0,43.219.0,41.204.0,54.227.0"}
P.entries["quest:8827"] = {n="Дарунки Зими",s="Дарунки Зими — святкове завдання Альянсу, що веде на Свято Зимової Завіси в Айронфорджі. Веселі гуляки й оператори зимових дивовольтів PX-238 радять мандрівникам навідатися до Діда Зими біля прилавків Пасовищ Димолісся. Там, під величною святковою ялинкою, бадьорих шукачів пригод чекають подарунки.",h="Дарунки Зими — святкове завдання Альянсу, що веде на Свято Зимової Завіси в Айронфорджі.",kw={"дарунки зими","зимова завіса","дід зима","пасовища димолісся","ялинка","айронфордж"},ang={["faction:Alliance"]="Узимку Айронфордж стає великим місцем зустрічі для всіх народів Альянсу: ельфи, люди й гноми сходяться в теплі підземні зали дворфів, щоб разом радіти святу.",["race:Dwarf"]="Для дворфів запросити мандрівників святкувати Зимову Завісу біля Великої Кузні — це гучні пісні, теплі вогнища й холодний ель у їхній гірській домівці.",["race:Gnome"]="Гномські механіки захоплюються дотепними святковими механізмами, які привозять на свято, як-от зимовими дивовольтами PX-238, що працюють по всьому місту."},sec={{t="Пора радості",b="Коли на вершини Каз Модану спадає зимовий холод, Айронфордж стає серцем Свята Зимової Завіси для всього Альянсу. Гуляки й шанувальники свята по всьому місту ширять добрий настрій і радісно скеровують перехожих до величної прикрашеної ялинки поруч із торговцями Пасовищ Димолісся."},{t="Пасовища Димолісся й Дід Зима",b="За щедрою роздачею загорнутих пакунків стоїть гоблінське підприємство Пасовища Димолісся, що діє пліч-о-пліч із самим Дідом Зимою. Поки життєрадісний Дід тепло вітає гостей зі святом, гобліни-торговці ніколи не соромляться нагадати щасливим отримувачам подарунків, що їхні святкові ласощі й сезонні товари — чудовий дарунок для друзів і родини."}},faq={{q="Хто посилає мене поговорити з Дідом Зимою?",a="Запросити вас до Діда Зими біля прикрашеної ялинки може або Ентузіаст свята, або Оператор Дивоформи, що доглядає машини PX-238 «Зимовий Дивовольт» в Айронфорджі.",al={"видавець завдання","хто починає дарунки зими","хто дає завдання"}},{q="Де в Айронфорджі знайти Діда Зиму?",a="Він сидить просто біля святкової ялинки й прилавків Пасовищ Димолісся в Айронфорджі й вітає святкових гостей з усіх рас Альянсу.",al={"де дід зима","місце діда зими айронфордж","знайти діда зиму"}},{q="Що таке PX-238 «Зимовий Дивовольт», про який каже оператор?",a="PX-238 «Зимовий Дивовольт» — химерний святковий винахід, яким керують гобліни-оператори: він ненадовго перетворює сміливих гостей свята на веселих маленьких святкових помічників.",al={"пі-ікс 238","зимовий дивовольт","машина дивовольт"}},{q="Чому Пасовища Димолісся причетні до Зимової Завіси?",a="Пасовища Димолісся — заповзятлива гоблінська торгова компанія, що спонсорує сезонні ласощі, святкові дрібнички й бенкети по всьому Азероту, поєднуючи щирий святковий дух із вигідною сезонною торгівлею.",al={"роль пасовищ димолісся","чому гобліни зимовий покров","гоблінське свято"}},{q="Чи можуть гравці Орди виконати це завдання?",a="Ні, саме це запрошення — лише для Альянсу в Айронфорджі. Орда відзначає Зимову Завісу за своїми звичаями під проводом Діда Зими в Оргріммарі.",al={"чи це лише для альянсу","дарунки зими орда","чи орда може здати"}},{q="Що буде після розмови з Дідом Зимою?",a="Дід Зима вітає вас, запевняє, що не забув про вас, і радить подивитися на барвисті пакунки під святковою ялинкою поруч.",al={"що далі","відкрити подарунки","після здачі завдання"}}},fp="17,323,17.339.0,41.382.0,46.178.0,49.150.0,63.172.0,50.211.0,32.172.0,50.164.0"}
P.entries["quest:8828"] = {n="Дарунки Зими",s="«Дарунки Зими» — запрошення, яке шукачі пригод отримують в Оргріммарі під час Свята Зимової Завіси. Організатори свята й гобліни, що доглядають святкові механізми, скеровують героїв Орди до Діда Зими під прикрашеною ялинкою, щоб забрати приготовані для них подарунки.",h="«Дарунки Зими» — запрошення, яке шукачі пригод отримують в Оргріммарі під час Свята Зимової Завіси.",kw={"свято зимової завіси","дід зима","подарунки","ялинка","пасовища димолісся","оргріммар"},ang={["faction:Horde"]="Для Орди гамірний святковий табір в Оргріммарі — радісне й тепле місце зустрічі, далеке від прикордонних сутичок, що не вщухають по всьому Калімдору.",["race:Orc"]="Навіть у суворій резиденції Вождя орки відкладають справи, щоб розділити зимову учту й прийняти гостинність під гіллям ялинки Зимової Завіси."},sec={{t="Пора щедрості",b="Коли наприкінці року над Дуротаром проносяться холодні вітри, Свято Зимової Завіси приносить на суворе червоне каміння Оргріммара рідкісну мить миру й радості. Торговці з Пасовищ Димолісся разом із запальними шанувальниками свята дбають, щоб кожен воїн, мисливець і мандрівник, що відпочиває в столиці, знав: під прикрашеною ялинкою на нього чекають подарунки."},{t="Покровитель і крамарі",b="Серед святкових стрічок і запакованих коробок, біля торгових ятей Пасовищ Димолісся, сидить сам Дід Зима. Прадавня постать утілює оновлення пори року, а кмітливі гобліни-торговці не пропускають нагоди нагадати відвідувачам, що святковий дух чудово пасує до їхнього запасу сезонних товарів і ласощів."}},faq={{q="Де здати завдання «Дарунки Зими»?",a="Це завдання здають Дідові Зимі, що сидить біля святкового майданчика Пасовищ Димолісся й прикрашеної ялинки в Долині Сили в Оргріммарі.",al={"де дід зима","місце здачі","здати дарунки"}},{q="Хто посилає до Діда Зими?",a="До ялинки вас скерує або Ентузіаст свята, або гоблін — Оператор Дивоформи, що доглядає машини PX-238 «Зимовий Дивовольт» довкола святкових майданчиків.",al={"хто дає завдання","початок завдання","любитель свята"}},{q="Що таке Пасовища Димолісся?",a="Пасовища Димолісся — заповзятлива гоблінська торгова компанія, що спонсорує святкування й постачає у великі столиці на Зимову Завісу страви, ласощі й подарункові товари.",al={"переказ про пасовища димолісся","хто такі пасовища димолісся"}},{q="Що робить Дід Зима, коли з ним поговорити?",a="Дід Зима особисто вітає вас зі Святом Зимової Завіси, показує на загорнуті пакунки, що чекають під ялинкою, і тепло радить переглянути товари Пасовищ Димолісся для ваших товаришів.",al={"привітання діда зими","діалог завершення"}},{q="Чому Орда святкує Зимову Завісу в Оргріммарі?",a="Свято коріниться в давніх легендах про оновлення взимку, але нині Орда приймає його як час перепочинку, бенкетів і єднання серед боротьби за свою нову домівку в Калімдорі.",al={"свято орди зимовий покров","чому орки святкують зимовий покров"}},{q="Що таке PX-238 «Зимовий Дивовольт», про який каже оператор?",a="Це химерна гоблінська машина біля святкового майданчика, що ненадовго перетворює охочих на святково вбраних Маленьких Помічників.",al={"зимовий дивовольт","пі-ікс 238 дивовольт"}}},fp="17,287,20.355.0,27.358.0,37.155.0,41.163.0,27.184.0,57.216.0,54.200.0,63.147.0"}
